const OX = 205;
const OY = 75;
const SCALE = 1.14;
const THETA = 38;
const COS_T = Math.cos((THETA * Math.PI) / 180);
const SIN_T = Math.sin((THETA * Math.PI) / 180);

function uv(u, v) {
  return [
    OX + SCALE * (u * COS_T - v * SIN_T),
    OY + SCALE * (u * SIN_T + v * COS_T)
  ];
}

function uvAngle(angDeg) {
  return THETA + angDeg;
}

const DORSAL_PTS = [
  [-280, -24],
  [-120, -14],
  [-20, -10],
  [45, -9],
  [125, 4],
  [260, 1],
  [420, 2],
  [560, 6],
  [665, 17],
  [745, 38],
  [805, 78],
  [832, 132],
  [812, 182],
  [765, 204]
];

const VENTRAL_PTS = [
  [-280, 545],
  [-80, 510],
  [120, 448],
  [290, 368],
  [420, 305],
  [495, 288],
  [575, 298],
  [655, 332],
  [730, 326],
  [784, 280],
  [796, 228],
  [765, 206]
];

function evalPiecewise(pts, u) {
  if (u <= pts[0][0]) return pts[0][1];
  if (u >= pts[pts.length - 1][0]) return pts[pts.length - 1][1];
  for (let i = 0; i < pts.length - 1; i++) {
    let u0 = pts[i][0], v0 = pts[i][1];
    let u1 = pts[i + 1][0], v1 = pts[i + 1][1];
    if (u >= u0 && u <= u1) {
      let t = (u - u0) / (u1 - u0 || 1);
      let s = t * t * (3 - 2 * t);
      return v0 + (v1 - v0) * s;
    }
  }
  return pts[pts.length - 1][1];
}

function dorsalV(u) {
  return evalPiecewise(DORSAL_PTS, u);
}

function ventralV(u) {
  return evalPiecewise(VENTRAL_PTS, u);
}

let headPolyUV = [];

function buildHeadPolygonUV() {
  headPolyUV = [];
  for (let u = -260; u <= 745; u += 25) {
    headPolyUV.push([u, dorsalV(u)]);
  }
  headPolyUV.push([780, 56]);
  headPolyUV.push([810, 84]);
  headPolyUV.push([828, 118]);
  headPolyUV.push([832, 145]);
  headPolyUV.push([818, 176]);
  headPolyUV.push([788, 198]);
  headPolyUV.push([762, 205]);
  // Mouth cleft tuck
  headPolyUV.push([720, 212]);
  headPolyUV.push([764, 208]);
  // Lower lip and chin
  headPolyUV.push([790, 222]);
  headPolyUV.push([796, 246]);
  headPolyUV.push([784, 280]);
  headPolyUV.push([755, 312]);
  headPolyUV.push([722, 328]);
  headPolyUV.push([675, 333]);
  headPolyUV.push([625, 318]);
  headPolyUV.push([575, 298]);
  for (let u = 530; u >= -260; u -= 30) {
    headPolyUV.push([u, ventralV(u)]);
  }
}

function inPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i][0], yi = poly[i][1];
    let xj = poly[j][0], yj = poly[j][1];
    let intersect =
      yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi + 1e-9) + xi;
    if (intersect) inside = !inside;
  }
  return inside;
}

function drawShape(pts, curvature = 0.2, closed = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

function drawUVShape(uvPts, curvature = 0.25, closed = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < uvPts.length; i++) {
    let p = uv(uvPts[i][0], uvPts[i][1]);
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(closed);
}

function getCoatFlowUV(u, v) {
  // Eye whorl and orbital flow
  let dxE = u - 45;
  let dyE = v - 130;
  let dE = Math.hypot(dxE, dyE);
  if (dE < 95) {
    let orbAng = (Math.atan2(dyE, dxE) * 180) / Math.PI + 90;
    let blend = Math.pow(1 - dE / 95, 1.5);
    return orbAng * blend + 8 * (1 - blend);
  }

  // Nostril swirl
  let dxN = u - 695;
  let dyN = v - 112;
  let dN = Math.hypot(dxN, dyN);
  if (dN < 95) {
    let nAng = (Math.atan2(dyN, dxN) * 180) / Math.PI;
    let tangent = dyN < 0 ? nAng + 82 : nAng - 82;
    let blend = Math.pow(1 - dN / 95, 1.4);
    return tangent * blend + 12 * (1 - blend);
  }

  // Chin pad flow
  let dxC = u - 715;
  let dyC = v - 275;
  let dC = Math.hypot(dxC, dyC);
  if (dC < 85 && v > 208) {
    return 18 + ((v - 250) / 80) * 28;
  }

  // General nasal bridge to cheek flow
  let vTop = dorsalV(u);
  let vBot = ventralV(u);
  let normV = constrain((v - vTop) / Math.max(1, vBot - vTop), 0, 1);

  if (u > 640) {
    // Upper lip & muzzle curve down toward mouth
    return 8 + normV * 48;
  }

  // Facial crest curve
  let baseAng = 2 + Math.sin(u * 0.005) * 4;
  let jawFlare = Math.pow(normV, 1.3) * 26;
  return baseAng + jawFlare;
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  brush.scaleBrushes(3);
  randomSeed(8419);
  noiseSeed(8419);
  buildHeadPolygonUV();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#c6d8e4");

  renderAtmosphere();
  renderBackBreath();
  renderHeadBaseAndMass();
  renderCoatFur();
  renderNostril();
  renderMouthAndChin();
  renderEyeAndLashes();
  renderRimLightAndFrostCrust();
  renderFrostedWhiskers();
  renderForegroundBreath();
  renderDiamondDust();

  noLoop();
}

