// ============================================================================
// 4. HYPERREAL COAT FUR: LAYERED CHARCOAL & COLOURED PENCIL STROKES
// ============================================================================
function renderCoatFur() {
  // Pass A: Broad charcoal under-texture following anatomical hair curves
  const charcoalBatches = [
    { col: "#15131c", w: 1.15, count: 480, uRange: [-230, 580], vNorm: [0.35, 0.96] },
    { col: "#2e1914", w: 1.05, count: 460, uRange: [-230, 590], vNorm: [0.08, 0.68] },
    { col: "#1e202b", w: 1.0, count: 420, uRange: [520, 825], vNorm: [0.05, 0.96] },
    { col: "#374659", w: 0.95, count: 280, uRange: [-200, 620], vNorm: [0.72, 0.99] }
  ];

  for (let batch of charcoalBatches) {
    brush.set("charcoal", batch.col, batch.w);
    for (let i = 0; i < batch.count; i++) {
      let u = random(batch.uRange[0], batch.uRange[1]);
      let vTop = dorsalV(u);
      let vBot = ventralV(u);
      let v = lerp(vTop, vBot, random(batch.vNorm[0], batch.vNorm[1]));
      if (!inPoly(u, v, headPolyUV)) continue;
      // Skip eye orb and inner nostril cavity
      if (Math.hypot(u - 45, v - 130) < 34) continue;
      if (Math.hypot(u - 698, v - 112) < 42) continue;

      let len = u > 560 ? random(14, 26) : random(24, 44);
      let ang = getCoatFlowUV(u, v) + random(-5, 5);
      let rad = (ang * Math.PI) / 180;
      let u2 = u + Math.cos(rad) * len;
      let v2 = v + Math.sin(rad) * len;
      if (!inPoly(u2, v2, headPolyUV)) continue;

      let p1 = uv(u, v);
      let p2 = uv((u + u2) * 0.5, (v + v2) * 0.5 + random(-2, 2));
      let p3 = uv(u2, v2);
      brush.spline([p1, p2, p3], 0.3);
    }
  }

  // Pass B: Fine coloured-pencil strokes in burnt umber, chestnut, mahogany, twilight slate, and muzzle velvet
  const pencilBatches = [
    // Deep burnt umber
    { col: "#422116", w: 0.85, count: 520, uRange: [-220, 590], vNorm: [0.12, 0.72] },
    // Rich mid burnt umber
    { col: "#5e2f1e", w: 0.8, count: 550, uRange: [-220, 600], vNorm: [0.06, 0.62] },
    // Warm bay chestnut
    { col: "#7d4027", w: 0.78, count: 520, uRange: [-200, 610], vNorm: [0.03, 0.5] },
    // Luminous backlit chestnut
    { col: "#9e5533", w: 0.75, count: 440, uRange: [-180, 620], vNorm: [0.01, 0.34] },
    // Golden-copper rim transition on bridge of nose and cheek ridge
    { col: "#c47649", w: 0.7, count: 360, uRange: [-140, 630], vNorm: [0.005, 0.18] },
    // Facial crest highlight band
    { col: "#733b24", w: 0.75, count: 240, uRange: [60, 460], vNorm: [0.36, 0.54] },
    // Cool twilight cerulean reflected light on lower jaw & curb groove
    { col: "#4f6680", w: 0.75, count: 320, uRange: [-200, 660], vNorm: [0.78, 0.99] },
    { col: "#6e8ba6", w: 0.65, count: 200, uRange: [-150, 740], vNorm: [0.88, 0.995] },
    // Muzzle velvet: dark slate-umber transition
    { col: "#382c33", w: 0.7, count: 340, uRange: [500, 670], vNorm: [0.08, 0.85] },
    // Muzzle velvet: soft charcoal-grey micro hairs
    { col: "#3d4252", w: 0.65, count: 480, uRange: [560, 828], vNorm: [0.04, 0.95] },
    // Muzzle velvet: cool silver-slate sheen on upper lip, nostril dome, and chin
    { col: "#636b80", w: 0.6, count: 420, uRange: [590, 828], vNorm: [0.02, 0.92] },
    { col: "#8994ab", w: 0.55, count: 320, uRange: [610, 830], vNorm: [0.01, 0.45] }
  ];

  for (let batch of pencilBatches) {
    brush.set("cpencil", batch.col, batch.w);
    for (let i = 0; i < batch.count; i++) {
      let u = random(batch.uRange[0], batch.uRange[1]);
      let vTop = dorsalV(u);
      let vBot = ventralV(u);
      let t = random(batch.vNorm[0], batch.vNorm[1]);
      let v = lerp(vTop, vBot, t);
      if (!inPoly(u, v, headPolyUV)) continue;
      if (Math.hypot(u - 45, v - 130) < 30) continue;
      if (Math.hypot(u - 698, v - 112) < 40) continue;

      let len = u > 580 ? random(8, 18) : random(16, 32);
      let ang = getCoatFlowUV(u, v) + random(-4, 4);
      let rad = (ang * Math.PI) / 180;
      let u2 = u + Math.cos(rad) * len;
      let v2 = v + Math.sin(rad) * len;
      if (!inPoly(u2, v2, headPolyUV)) continue;

      let p1 = uv(u, v);
      let p2 = uv((u + u2) * 0.5, (v + v2) * 0.5 + random(-1.5, 1.5));
      let p3 = uv(u2, v2);
      brush.spline([p1, p2, p3], 0.25);
    }
  }

  // Subtle dark vascular veins & skin tension folds on the thin-skinned lower face
  const veinPaths = [
    [[140, 210], [220, 200], [310, 182], [390, 155]],
    [[240, 295], [310, 245], [385, 205], [465, 175]],
    [[370, 310], [435, 255], [505, 215], [565, 165]]
  ];
  for (let vp of veinPaths) {
    brush.set("charcoal", "#17141f", 0.9);
    let cPtsDark = vp.map((pt) => uv(pt[0], pt[1] + 4));
    brush.spline(cPtsDark, 0.35);

    brush.set("cpencil", "#7d452d", 0.75);
    let cPtsLight = vp.map((pt) => uv(pt[0], pt[1] - 2));
    brush.spline(cPtsLight, 0.35);
  }
}

