  brush.mass("charcoal", "#282633", { precision: 0.8, strength: 0.75, gradient: 0.3, outline: false });
  drawUVShape([
    [625, 84], [665, 76], [705, 94], [715, 122], [688, 128], [648, 112], [622, 96]
  ], 0.3, true);
  brush.noMass();

  // Sculpting strokes around nostril wing, alar fold, and wet frozen rim
  brush.set("cpencil", "#7d879c", 0.7);
  for (let i = 0; i < 65; i++) {
    let t = i / 65;
    let ang = lerp(-150, 45, t);
    let rad = (ang * Math.PI) / 180;
    let u1 = 695 + Math.cos(rad) * 52;
    let v1 = 108 + Math.sin(rad) * 44;
    let u2 = 695 + Math.cos(rad) * 68;
    let v2 = 108 + Math.sin(rad) * 56;
    let p1 = uv(u1, v1);
    let p2 = uv(u2, v2);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Wet glistening highlight & frost crust on the lower nostril rim
  brush.set("cpencil", "#d8eaf5", 0.85);
  for (let i = 0; i < 45; i++) {
    let u = random(655, 755);
    let v = evalPiecewise([[655, 135], [695, 156], [735, 154], [755, 122]], u) + random(-4, 6);
    let p1 = uv(u, v);
    let p2 = uv(u + random(4, 10), v + random(2, 7));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  brush.set("pen", "#ffffff", 0.65);
  for (let i = 0; i < 38; i++) {
    let u = random(670, 756);
    let v = evalPiecewise([[670, 145], [705, 158], [738, 152], [756, 120]], u) + random(-2, 4);
    let p = uv(u, v);
    brush.line(p[0], p[1], p[0] + random(-3, 5), p[1] + random(-2, 4));
  }
}

// ============================================================================
// 6. ANATOMICAL DETAIL: MOUTH CLEFT, VELVET LIPS & CHIN GROOVE
// ============================================================================
function renderMouthAndChin() {
  // Deep shadow along the mouth cleft
  const cleftUV = [
    [640, 210], [675, 214], [715, 213], [748, 209], [768, 205]
  ];

  brush.set("charcoal", "#111017", 1.3);
  brush.spline(cleftUV.map((pt) => uv(pt[0], pt[1])), 0.3);

  brush.set("charcoal", "#241d26", 0.95);
  brush.spline(cleftUV.map((pt) => uv(pt[0], pt[1] - 3)), 0.3);

  // Soft fleshy folds at the commissure (corner of the mouth)
  for (let offset of [-14, -7, 8, 15]) {
    brush.set("cpencil", "#1a1b24", 0.8);
    brush.spline([
      uv(625, 195 + offset),
      uv(642, 208 + offset * 0.6),
      uv(655, 222 + offset * 0.4)
    ], 0.35);
  }

  // Plush skin creases and velvet sheen on upper and lower lips
  brush.set("cpencil", "#7d889e", 0.65);
  for (let i = 0; i < 75; i++) {
    let u = random(660, 825);
    let v = random(155, 202);
    if (!inPoly(u, v, headPolyUV)) continue;
    let p1 = uv(u, v);
    let p2 = uv(u + random(5, 12), v + random(4, 10));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Lower lip and rounded chin pad highlights
  brush.set("cpencil", "#6e7b91", 0.7);
  for (let i = 0; i < 85; i++) {
    let u = random(635, 792);
    let v = random(212, 326);
    if (!inPoly(u, v, headPolyUV)) continue;
    let p1 = uv(u, v);
    let p2 = uv(u + random(6, 14), v + random(3, 9));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

// ============================================================================
// 7. ANATOMICAL DETAIL: EQUINE EYE & FROST-CRUSTED EYELASHES
// ============================================================================
function renderEyeAndLashes() {
  brush.noStroke();

  // Dark orbital socket & eyelids
  brush.wash("#121118", 245);
  drawUVShape([
    [5, 126], [24, 106], [52, 104], [78, 116],
    [86, 134], [66, 152], [36, 154], [12, 142]
  ], 0.3, true);

  // Rich dark brown iris & pupil
  brush.wash("#1f110e", 245);
  drawUVShape([
    [18, 126], [34, 112], [58, 112], [74, 124],
    [72, 140], [52, 148], [28, 146]
  ], 0.35, true);

  // Pupil (horizontal equine pupil)
  brush.wash("#09080d", 255);
  drawUVShape([
    [26, 126], [46, 121], [65, 126], [63, 136], [44, 138], [26, 134]
  ], 0.25, true);
  brush.noWash();

  // Glassy corneal reflection of the cold cerulean sky
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.2, 0.1);
  brush.fill("#8fb8d6", 155);
  drawUVShape([
    [28, 116], [52, 114], [68, 122], [58, 128], [34, 125]
  ], 0.3, true);

  brush.fill("#e6f4fc", 210);
  drawUVShape([
    [38, 116], [54, 116], [60, 121], [44, 122]
  ], 0.2, true);
  brush.noFill();

  // Eyelid folds above and below the eye
  brush.set("charcoal", "#0e0d14", 1.1);
  brush.spline([uv(-2, 122), uv(26, 100), uv(58, 99), uv(88, 115)], 0.35);
  brush.spline([uv(6, 144), uv(36, 158), uv(68, 154), uv(88, 138)], 0.35);

  brush.set("cpencil", "#69758c", 0.75);
  brush.spline([uv(4, 118), uv(30, 103), uv(58, 102), uv(84, 116)], 0.35);
  brush.spline([uv(12, 146), uv(38, 155), uv(66, 151)], 0.35);

  // Thick, straight equine upper eyelashes encrusted with white frost!
  const numLashes = 32;
  for (let i = 0; i < numLashes; i++) {
    let t = i / (numLashes - 1);
    let u0 = lerp(14, 82, t);
    let v0 = evalPiecewise([[14, 116], [45, 108], [82, 120]], u0);
    let lashLen = sin(t * 180) * 26 + random(18, 28);
    let lashAng = lerp(24, 8, t) + random(-4, 4);
    let rad = (lashAng * Math.PI) / 180;

    let uMid = u0 + Math.cos(rad) * lashLen * 0.55;
    let vMid = v0 + Math.sin(rad) * lashLen * 0.55 + 3;
    let uTip = u0 + Math.cos(rad) * lashLen;
    let vTip = v0 + Math.sin(rad) * lashLen + 5;

    let p0 = uv(u0, v0);
    let pMid = uv(uMid, vMid);
    let pTip = uv(uTip, vTip);

    // Dark lash base
    brush.set("2B", "#1c1a24", 0.7);
    brush.spline([p0, pMid, pTip], 0.25);

    // Frost rime coating the outer 75% of each eyelash
    brush.set("cpencil", "#cde4f2", 0.85);
    brush.spline([pMid, pTip], 0.2);

    brush.set("pen", "#ffffff", 0.75);
    brush.line(pMid[0], pMid[1], pTip[0], pTip[1]);

    // Tiny crystalline frost burrs clinging to the lash
    for (let k = 0; k < 3; k++) {
      let fk = random(0.35, 1.0);
      let fx = lerp(p0[0], pTip[0], fk);
      let fy = lerp(p0[1], pTip[1], fk);
      brush.set("pen", "#ffffff", 0.55);
      brush.line(fx, fy, fx + random(-4, 5), fy + random(-4, 5));
    }
  }

  // Fine frosted lower lashes
  for (let i = 0; i < 16; i++) {
    let u0 = lerp(18, 72, i / 15);
    let v0 = evalPiecewise([[18, 144], [44, 153], [72, 145]], u0);
    let p0 = uv(u0, v0);
    let p1 = uv(u0 + random(6, 14), v0 + random(10, 18));
    brush.set("cpencil", "#b8d4e6", 0.6);
    brush.line(p0[0], p0[1], p1[0], p1[1]);
    brush.set("pen", "#ffffff", 0.5);
    brush.line((p0[0] + p1[0]) * 0.5, (p0[1] + p1[1]) * 0.5, p1[0], p1[1]);
  }
}

// ============================================================================
// 8. BACKLIT RIM LIGHT & CRYSTALLINE FROST CRUST ON THE FUR
// ============================================================================
function renderRimLightAndFrostCrust() {
  // 1. Sub-rim warm amber & ice-blue backlit hairs along the entire nasal bridge and muzzle tip
  for (let u = -220; u <= 830; u += 1.6) {
    let v = dorsalV(u);
    let isMuzzle = u > 570;

    // Warm golden-amber glow filtering through coat edge
    let colWarm = isMuzzle ? "#9ab8cc" : "#e3a674";
    brush.set("cpencil", colWarm, 0.75);
    let p1 = uv(u, v + random(2, 14));
    let p2 = uv(u + random(10, 22), v - random(1, 5));
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    // Brilliant backlit rim hair projecting into the cold morning air
    brush.set("pen", "#f0f8fc", 0.6);
    let pRim1 = uv(u, v + random(-1, 4));
    let pRim2 = uv(u + random(4, 14), v - random(3, 11));
    brush.line(pRim1[0], pRim1[1], pRim2[0], pRim2[1]);

    if (random() < 0.65) {
      brush.set("pen", "#ffffff", 0.75);
      let pSpark = uv(u + random(-2, 4), v - random(0, 6));
      brush.line(pSpark[0], pSpark[1], pSpark[0] + random(2, 8), pSpark[1] - random(1, 5));
    }
  }

  // 2. Rim light wrapping around the front of the upper lip, lower lip, and chin
  for (let i = 0; i < 160; i++) {
    let t = i / 160;
    let u, v;
    if (t < 0.45) {
      // Upper lip front edge
      let s = t / 0.45;
      u = lerp(805, 768, s) + sin(s * 180) * 24;
      v = lerp(78, 204, s);
    } else {
      // Lower lip and chin pad
      let s = (t - 0.45) / 0.55;
      u = evalPiecewise([[0, 792], [0.35, 785], [0.7, 730], [1, 610]], s);
      v = evalPiecewise([[0, 224], [0.35, 278], [0.7, 326], [1, 312]], s);
    }
    let p1 = uv(u - random(2, 8), v - random(2, 6));
    let p2 = uv(u + random(4, 12), v + random(2, 9));
    brush.set("cpencil", "#d8ecf7", 0.8);
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    brush.set("pen", "#ffffff", 0.65);
    brush.line(p2[0] - 2, p2[1] - 2, p2[0] + random(2, 6), p2[1] + random(1, 5));
  }

  // 3. Heavy white hoarfrost crusting on the coat where breath moisture freezes
  // Concentrated on the muzzle, bridge above nostril, supraorbital arch, and chin
  const frostZones = [
    // Supraorbital arch & forehead above eye
    { uMin: -30, uMax: 110, vMin: -8, vMax: 95, count: 220 },
    // Lower nasal bridge crust
    { uMin: 420, uMax: 750, vMin: 4, vMax: 75, count: 380 },
    // Upper lip & around nostril
    { uMin: 620, uMax: 830, vMin: 35, vMax: 202, count: 460 },
    // Lower lip & chin pad frost crust
    { uMin: 590, uMax: 795, vMin: 210, vMax: 332, count: 420 },
    // Cheek ridge frost dusting
    { uMin: 120, uMax: 520, vMin: 140, vMax: 245, count: 180 }
  ];

  for (let z of frostZones) {
    for (let i = 0; i < z.count; i++) {
      let u = random(z.uMin, z.uMax);
      let v = random(z.vMin, z.vMax);
      if (!inPoly(u, v, headPolyUV)) continue;
      // Avoid inner eye & inner nostril
      if (Math.hypot(u - 45, v - 130) < 34) continue;
      if (Math.hypot(u - 698, v - 112) < 44) continue;

      let p = uv(u, v);
      let isBright = random() < 0.45;
      brush.set(isBright ? "pen" : "cpencil", isBright ? "#ffffff" : "#cde3f0", isBright ? 0.55 : 0.7);
      let ang = uvAngle(getCoatFlowUV(u, v)) + random(-25, 25);
      let len = random(2.5, 8);
      let x2 = p[0] + cos(ang) * len;
      let y2 = p[1] + sin(ang) * len;
      brush.line(p[0], p[1], x2, y2);
    }
  }
}

// ============================================================================
// 9. FROST-CRUSTED WHISKERS (VIBRISSAE)
// ============================================================================
function renderFrostedWhiskers() {
  const whiskers = [];

  // 1. Upper lip tactile whiskers arching outward and down
  for (let i = 0; i < 28; i++) {
    let u = random(705, 825);
    let v = random(125, 198);
    if (!inPoly(u, v, headPolyUV)) continue;
    let len = random(38, 105);
    let startAng = random(-12, 35);
    let droop = random(22, 48);
    whiskers.push({ u, v, len, startAng, droop, weight: random(0.65, 1.0) });
  }

  // 2. Lower lip and abundant chin whiskers arching downward and forward
  for (let i = 0; i < 36; i++) {
    let u = random(605, 792);
    let v = random(218, 328);
    if (!inPoly(u, v, headPolyUV)) continue;
    let len = random(45, 130);
    let startAng = random(20, 75);
    let droop = random(18, 42);
    whiskers.push({ u, v, len, startAng, droop, weight: random(0.65, 1.05) });
  }

  // 3. Supraorbital & infraorbital sensory whiskers near the eye
  for (let i = 0; i < 9; i++) {
    let isUpper = i < 5;
    let u = isUpper ? random(20, 70) : random(25, 75);
    let v = isUpper ? random(72, 92) : random(162, 182);
    let len = random(35, 75);
    let startAng = isUpper ? random(-45, -15) : random(35, 65);
    let droop = random(10, 25);
    whiskers.push({ u, v, len, startAng, droop, weight: 0.65 });
  }

  for (let w of whiskers) {
    let pts = [];
    let steps = 7;
    let curP = uv(w.u, w.v);
    pts.push([curP[0], curP[1]]);

    let baseCanvasAng = uvAngle(w.startAng);
    for (let s = 1; s <= steps; s++) {
      let t = s / steps;
      let segLen = (w.len * SCALE) / steps;
      let a = baseCanvasAng + t * t * w.droop;
      curP = [curP[0] + cos(a) * segLen, curP[1] + sin(a) * segLen];
      pts.push(curP);
    }

    // Subtle dark base shadow at root of whisker
    brush.set("2H", "#232836", w.weight * 0.75);
    brush.spline(pts.slice(0, 4), 0.3);

    // Ice-blue frosted mid-layer along full whisker
    brush.set("cpencil", "#cde4f2", w.weight * 0.95);
    brush.spline(pts, 0.35);

    // Brilliant white backlit core
    brush.set("pen", "#ffffff", w.weight * 0.7);
    brush.spline(pts, 0.35);

    // Crusty hoarfrost crystals and rime burrs clinging along the whisker shaft
    let numCrystals = Math.floor(w.len / 5.5);
    for (let c = 1; c < numCrystals; c++) {
      let f = c / numCrystals;
      if (f < 0.15) continue;
      let idx = Math.min(pts.length - 2, Math.floor(f * (pts.length - 1)));
      let frac = f * (pts.length - 1) - idx;
      let px = lerp(pts[idx][0], pts[idx + 1][0], frac);
      let py = lerp(pts[idx][1], pts[idx + 1][1], frac);

      let burrLen = random(2.5, 6.5) * (0.5 + 0.7 * Math.sin(f * Math.PI));
      let burrAng = baseCanvasAng + f * w.droop + random([-85, -60, 60, 85]) + random(-18, 18);
      brush.set(random() < 0.6 ? "pen" : "cpencil", random() < 0.7 ? "#ffffff" : "#d8edf8", random(0.45, 0.75));
      brush.line(px, py, px + cos(burrAng) * burrLen, py + sin(burrAng) * burrLen);
    }
  }
}

// ============================================================================
// 10. FOREGROUND BREATH VEIL: HANGING TRANSLUCENT PLUME
// ============================================================================
function renderForegroundBreath() {
  brush.noStroke();
  brush.fillBleed(0.48, "out");
  brush.fillTexture(0.25, 0.08);

  // Translucent layered watercolor puffs emerging directly from the nostril and curling into the frigid air
  const breathLayers = [
    {
      col: "#e3f2fa",
      op: 46,
      pts: [[735, 650], [835, 605], [985, 615], [1120, 695], [1155, 845], [1010, 925], [845, 865], [755, 755]]
    },
    {
      col: "#f0f9fd",
      op: 52,
      pts: [[745, 658], [825, 635], [945, 655], [1045, 735], [1035, 845], [910, 860], [795, 775]]
    },
    {
      col: "#ffffff",
      op: 48,
      pts: [[750, 662], [815, 652], [905, 680], [965, 745], [935, 815], [835, 795], [765, 725]]
    },
    // Upper curling eddy catching the low sunlight
    {
      col: "#ebf6fc",
      op: 38,
      pts: [[820, 615], [930, 505], [1085, 465], [1175, 555], [1110, 675], [955, 665]]
    },
    // Lower drifting veil past the chin and whiskers
    {
      col: "#e1f0f8",
      op: 36,
      pts: [[745, 785], [885, 795], [1065, 875], [1145, 1025], [985, 1115], [810, 1015], [715, 895]]
    }
  ];

  for (let bl of breathLayers) {
    brush.fill(bl.col, bl.op);
    drawShape(bl.pts, 0.38, true);
  }
  brush.noFill();

  // Delicate curling vapour filaments in charcoal & cpencil to give the breath veil organic structure
  for (let i = 0; i < 95; i++) {
    let t = random();
    let startX = lerp(742, 860, t * t);
    let startY = lerp(655, 790, random());
    let streamPts = [[startX, startY]];
    let cx = startX;
    let cy = startY;
    let baseAng = random(-28, 42);
    let curl = random(-14, 14);
    let segs = 5;
    let stepLen = random(28, 68);

    for (let s = 1; s <= segs; s++) {
      let n = noise(cx * 0.004, cy * 0.004, i * 0.1);
      let a = baseAng + (n - 0.5) * 65 + s * curl;
      cx += cos(a) * stepLen;
      cy += sin(a) * stepLen;
      streamPts.push([cx, cy]);
    }

    let isCore = i < 40;
    brush.set(isCore ? "cpencil" : "charcoal", isCore ? "#ffffff" : "#e3f2fa", random(0.45, 0.85));
    brush.spline(streamPts, 0.4);
  }

  // Fine breath mist stipple
  brush.set("spray", "#ffffff", 0.75);
  for (let i = 0; i < 55; i++) {
    let bx = random(740, 1160);
    let by = random(500, 1040);
    brush.line(bx, by, bx + random(-35, 45), by + random(-35, 35));
  }
}

// ============================================================================
// 11. GLITTERING DIAMOND-DUST FIELD: PEN SPARKS & NEEDLE-THIN CROSS GLINTS
// ============================================================================
function renderDiamondDust() {
  // 1. Tiny white & ice-blue pen sparks suspended throughout the frigid air
  const sparkColors = ["#ffffff", "#e6f6ff", "#c4e5f7"];
  for (let i = 0; i < 580; i++) {
    // Concentrate more densely in the backlit air and breath plume, with a lighter veil over the dark coat
    let x, y;
    if (random() < 0.72) {
      x = random(320, 1190);
      y = random(20, 1190);
    } else {
      x = random(20, 1190);
      y = random(20, 1190);
    }

    let col = sparkColors[i % sparkColors.length];
    let w = random(0.35, 0.75);
    brush.set("pen", col, w);
    let len = random(1.2, 3.8);
    let ang = random(360);
    brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // 2. Needle-thin cross glints (4-point & 6-point crystalline glints catching the low morning light)
  const numGlints = 105;
  for (let i = 0; i < numGlints; i++) {
    let gx, gy;
    if (i < 78) {
      // In the backlit atmosphere and breath plume (outside or near the rim of the head)
      let attempts = 0;
      do {
        gx = random(260, 1175);
        gy = random(35, 1165);
        attempts++;
      } while (attempts < 10 && gx < 680 && gy > 220 && gy < 820);
    } else {
      // Drifting in the foreground right across the horse's cheek/muzzle or rim
      gx = random(120, 1160);
      gy = random(50, 1150);
    }

    let isHero = i < 18;
    let isMed = i >= 18 && i < 52;
    let rMain = isHero ? random(18, 34) : isMed ? random(9, 17) : random(4.5, 8.5);
    let rCross = rMain * random(0.65, 0.95);
    let tilt = random(-8, 8);
    let isHex = random() < 0.35;

    // Subtle icy halo on larger glints
    if (isHero) {
      brush.set("cpencil", "#bce2f7", 0.5);
      brush.circle(gx, gy, rMain * 0.22, 0.15);
    }

    // Outer needle-thin rays in ice-blue/white
    let rayWeight = isHero ? 0.42 : isMed ? 0.34 : 0.28;
    brush.set("rotring", "#d9f1ff", rayWeight);
    brush.line(
      gx - cos(tilt) * rMain,
      gy - sin(tilt) * rMain,
      gx + cos(tilt) * rMain,
      gy + sin(tilt) * rMain
    );
    brush.line(
      gx - cos(tilt + 90) * rCross,
      gy - sin(tilt + 90) * rCross,
      gx + cos(tilt + 90) * rCross,
      gy + sin(tilt + 90) * rCross
    );

    if (isHex || isHero) {
      let rDiag = rMain * 0.48;
      brush.set("rotring", "#bfe4fa", rayWeight * 0.85);
      brush.line(
        gx - cos(tilt + 45) * rDiag,
        gy - sin(tilt + 45) * rDiag,
        gx + cos(tilt + 45) * rDiag,
        gy + sin(tilt + 45) * rDiag
      );
      brush.line(
        gx - cos(tilt - 45) * rDiag,
        gy - sin(tilt - 45) * rDiag,
        gx + cos(tilt - 45) * rDiag,
        gy + sin(tilt - 45) * rDiag
      );
    }

    // Brilliant pure white inner needle cross & pinpoint spark center
    let rCore = rMain * 0.52;
    brush.set("pen", "#ffffff", rayWeight * 1.45);
    brush.line(
      gx - cos(tilt) * rCore,
      gy - sin(tilt) * rCore,
      gx + cos(tilt) * rCore,
      gy + sin(tilt) * rCore
    );
    brush.line(
      gx - cos(tilt + 90) * rCore * 0.85,
      gy - sin(tilt + 90) * rCore * 0.85,
      gx + cos(tilt + 90) * rCore * 0.85,
      gy + sin(tilt + 90) * rCore * 0.85
    );
  }
}

