function draw() {
  translate(-width / 2, -height / 2);
  brush.clip([0, 0, width, height]);

  // 1. Deep Basalt / Slate Boulder Ground
  background(PALETTE.rockDark);
  renderLithicUndertone();

  // 2. Generate Tectonic Rock Fracture Network & Render Deep Basal Fissures
  generateRockCrackNetwork();
  renderBasalRockCracks();

  // 3. Render Interstitial Crustose Areolate Mosaic (Map Lichen & Slate Crusts along Cracks)
  renderCrustoseMosaic();

  // 4. Generate & Render the Multi-Scale Recursive Rosette Hierarchy
  const macroColonies = generateMacroColonies();
  for (let i = 0; i < macroColonies.length; i++) {
    drawLichenRosette(macroColonies[i]);
  }

  // 5. Render Secondary & Tertiary Boundary Colonies Straddling Seams and Rock Clefts
  const frontierColonies = generateFrontierColonies(macroColonies);
  for (let i = 0; i < frontierColonies.length; i++) {
    drawLichenRosette(frontierColonies[i]);
  }

  // 6. Re-inscribe Fine Graphite Pencil Cracks Threading Between & Across Colonies
  renderFinePencilCracksOverpass();

  // 7. Final Botanical Micro-Stipple & Coastline Precision Pass
  renderMasterBotanicalStipplePass(macroColonies, frontierColonies);

  brush.noClip();
  noLoop();
}

// ============================================================================
// UTILITY & GEOMETRY HELPERS
// ============================================================================

function safeSpline(pts, curvature = 0.4) {
  if (!pts || pts.length < 2) return;
  const cleaned = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    const prev = cleaned[cleaned.length - 1];
    const dx = pts[i][0] - prev[0];
    const dy = pts[i][1] - prev[1];
    if (dx * dx + dy * dy > 2.2) {
      cleaned.push(pts[i]);
    }
  }
  if (cleaned.length >= 4) {
    brush.spline(cleaned, curvature);
  } else if (cleaned.length >= 2) {
    const a = cleaned[0];
    const b = cleaned[cleaned.length - 1];
    brush.line(a[0], a[1], b[0], b[1]);
  }
}

function distToCrackNetwork(x, y) {
  let minDistSq = 1e9;
  for (let i = 0; i < crackNodes.length; i += 2) {
    const dx = x - crackNodes[i].x;
    const dy = y - crackNodes[i].y;
    const dSq = dx * dx + dy * dy;
    if (dSq < minDistSq) minDistSq = dSq;
  }
  return Math.sqrt(minDistSq);
}

// Topological rock warp so rosettes deform naturally over boulder facets
function warpPoint(x, y, scale = 0.0035, amp = 18, seedOffset = 0) {
  const nx = noise(x * scale + seedOffset, y * scale + 17.3) - 0.5;
  const ny = noise(x * scale + 53.1, y * scale + seedOffset + 91.7) - 0.5;
  return [x + nx * amp * 2.0, y + ny * amp * 2.0];
}

// ============================================================================
// STEP 1: LITHIC UNDERTONE & MINERAL GRAIN
// ============================================================================

function renderLithicUndertone() {
  brush.noStroke();
  brush.fillTexture(0.85, 0.65);
  brush.fillBleed(0.35, "out");

  // Subtle dark slate mineral patches
  const patchColors = [PALETTE.rockAbyss, PALETTE.rockSlate, "#161d24", "#222c36"];
  for (let c = 0; c < patchColors.length; c++) {
    brush.fill(patchColors[c], 75);
    for (let i = 0; i < 6; i++) {
      const px = random(-80, width + 80);
      const py = random(-80, height + 80);
      const pr = random(180, 420);
      brush.circle(px, py, pr, 0.35);
    }
  }
  brush.noFill();
  brush.noWash();

  // Carpet the entire stone substrate with fine mineral stippling
  const grainLayers = [
    { b: "stipple_heavy", col: PALETTE.rockAbyss, w: 1.1, count: 65 },
    { b: "stipple_sparse", col: PALETTE.rockPewter, w: 0.9, count: 70 },
    { b: "stipple_sparse", col: PALETTE.rockQuartz, w: 0.7, count: 45 },
    { b: "stipple_fine", col: "#0c1015", w: 0.9, count: 60 }
  ];

  for (let layer of grainLayers) {
    brush.set(layer.b, layer.col, layer.w);
    for (let i = 0; i < layer.count; i++) {
      const x1 = random(-60, width + 60);
      const y1 = random(-60, height + 60);
      const ang = random(360);
      const len = random(60, 220);
      const pts = [];
      const steps = 6;
      for (let s = 0; s <= steps; s++) {
        const t = s / steps;
        const wx = x1 + cos(ang) * len * t + (noise(x1 * 0.01, t * 3) - 0.5) * 35;
        const wy = y1 + sin(ang) * len * t + (noise(y1 * 0.01, t * 3 + 10) - 0.5) * 35;
        pts.push([wx, wy, 0.7 + 0.5 * sin(t * 180)]);
      }
      safeSpline(pts, 0.4);
    }
  }
}

// ============================================================================
// STEP 2: ROCK FRACTURE & PENCIL CRACK NETWORK
// ============================================================================

function generateRockCrackNetwork() {
  crackSegments = [];
  crackNodes = [];

  // Primary tectonic fault lines traversing the boulder face
  const primarySeeds = [
    { x: -40, y: 210, ang: 24, len: 1480, weight: 1.0 },
    { x: 310, y: -40, ang: 106, len: 1350, weight: 0.95 },
    { x: 1240, y: 420, ang: 158, len: 1420, weight: 0.9 },
    { x: -30, y: 890, ang: -19, len: 1380, weight: 0.85 },
    { x: 880, y: -40, ang: 118, len: 1360, weight: 0.85 },
    { x: 520, y: 1240, ang: -74, len: 1320, weight: 0.8 }
  ];

  for (let p of primarySeeds) {
    traceCrackBranch(p.x, p.y, p.ang, p.len, p.weight, 0);
  }
}

function traceCrackBranch(startX, startY, startAng, totalLen, baseWeight, depth) {
  if (depth > 3 || totalLen < 28) return;

  const stepLen = 14;
  const steps = Math.floor(totalLen / stepLen);
  let cx = startX;
  let cy = startY;
  let ang = startAng;
  const pts = [[cx, cy, baseWeight]];

  for (let i = 1; i <= steps; i++) {
    const nVal = noise(cx * 0.0045 + depth * 13, cy * 0.0045 + i * 0.07);
    // Angular rock cleavage deflections
    ang += (nVal - 0.49) * 26;
    if (random() < 0.14) {
      ang += random([-18, -11, 11, 18]);
    }
    cx += cos(ang) * stepLen;
    cy += sin(ang) * stepLen;

    const t = i / steps;
    const pressure = baseWeight * (0.45 + 0.65 * sin(t * 180)) * (0.8 + 0.4 * noise(i * 0.3));
    pts.push([cx, cy, pressure]);

    if (cx >= -60 && cx <= width + 60 && cy >= -60 && cy <= height + 60) {
      crackNodes.push({ x: cx, y: cy, depth: depth, ang: ang });
    }

    // Spawn secondary & tertiary splinter cracks
    const branchProb = depth === 0 ? 0.065 : depth === 1 ? 0.045 : 0.025;
    if (random() < branchProb) {
      const side = random() < 0.5 ? 1 : -1;
      const branchAng = ang + side * random(24, 52);
      const branchLen = totalLen * random(0.22, 0.48) * (1 - t * 0.4);
      traceCrackBranch(cx, cy, branchAng, branchLen, baseWeight * 0.68, depth + 1);
    }
  }

  crackSegments.push({ pts, depth, weight: baseWeight });
}

function renderBasalRockCracks() {
  // Deep crevice shadow corridors along the cracks
  for (let seg of crackSegments) {
    if (seg.depth <= 1) {
      brush.set("stipple_heavy", PALETTE.rockAbyss, 0.85 * seg.weight);
      safeSpline(seg.pts, 0.25);

      brush.set("stipple_med", "#141a21", 1.15 * seg.weight);
      safeSpline(seg.pts, 0.25);
    } else {
      brush.set("stipple_fine", PALETTE.rockAbyss, 0.65 * seg.weight);
      safeSpline(seg.pts, 0.25);
    }
  }
}

function renderFinePencilCracksOverpass() {
  // Thread sharp graphite pencil cracks ("2H", "HB") and "rotring" micro-fissures between & across colonies
  for (let seg of crackSegments) {
    const pts = seg.pts;
    if (pts.length < 3) continue;

    // Beveled quartz/mineral highlight on upper-left lip of fissure
    if (seg.depth <= 2) {
      const hiPts = pts.map(p => [p[0] - 1.6, p[1] - 1.6, p[2] * 0.65]);
      brush.set("2H", "#8c9ba8", 0.38 * seg.weight);
      safeSpline(hiPts, 0.2);
    }

    // Stippled shadow lip along fissure edge
    const shPts = pts.map(p => [p[0] + 1.8, p[1] + 1.8, p[2] * 0.85]);
    brush.set("stipple_fine", PALETTE.rockAbyss, 0.55 * seg.weight);
    safeSpline(shPts, 0.22);

    // Core graphite & ink fissure line
    brush.set("HB", "#0b0e12", 0.52 * seg.weight);
    safeSpline(pts, 0.18);

    brush.set("rotring", "#06080b", 0.36 * seg.weight);
    safeSpline(pts, 0.15);

    // Fine en-echelon pencil feather-cracks along the main fault
    brush.set("2H", "#141a20", 0.32);
    for (let i = 2; i < pts.length - 2; i += 3) {
      if (random() < 0.42) {
        const p = pts[i];
        const next = pts[i + 1];
        const baseAng = atan2(next[1] - p[1], next[0] - p[0]);
        const splAng = baseAng + random([-38, -26, 26, 38]);
        const splLen = random(8, 26) * seg.weight;
        const mx = p[0] + cos(splAng) * splLen * 0.5 + random(-2, 2);
        const my = p[1] + sin(splAng) * splLen * 0.5 + random(-2, 2);
        const ex = p[0] + cos(splAng) * splLen;
        const ey = p[1] + sin(splAng) * splLen;
        safeSpline([[p[0], p[1], 0.9], [mx, my, 0.6], [ex, ey, 0.2]], 0.25);
      }
    }
  }
}

// ============================================================================
// STEP 3: INTERSTITIAL CRUSTOSE AREOLATE MOSAIC (MAP LICHEN & SLATE CRUSTS)
// ============================================================================

function renderCrustoseMosaic() {
  // Along crack corridors and interstitial rock zones, draw hundreds of tiny crustose areoles
  // (Rhizocarpon geographicum in sulphur/chartreuse & Lecidea in slate-grey on black prothallus)
  const numPatches = 58;
  for (let p = 0; p < numPatches; p++) {
    let cx, cy;
    if (p < 38 && crackNodes.length > 0) {
      const node = random(crackNodes);
      cx = node.x + random(-48, 48);
      cy = node.y + random(-48, 48);
    } else {
      cx = random(-20, width + 20);
      cy = random(-20, height + 20);
    }

    const patchRadius = random(28, 78);
    const isSulphurMapLichen = random() < 0.42; // Yellow-green map lichen vs monochrome slate crust

    // Black prothallus base web
    brush.set("stipple_heavy", "#070a0d", 0.95);
    const webPts = [];
    const steps = 10;
    for (let s = 0; s <= steps; s++) {
      const a = (s / steps) * 360;
      const r = patchRadius * (0.75 + 0.35 * noise(cx * 0.02 + cos(a), cy * 0.02 + sin(a)));
      webPts.push([cx + cos(a) * r, cy + sin(a) * r, 0.9]);
    }
    safeSpline(webPts, 0.45);

    // Pack tiny polygonal/rounded areoles inside the prothallus patch
    const numAreoles = Math.floor( sq(patchRadius) / 65 );
    for (let a = 0; a < numAreoles; a++) {
      const ang = a * 137.508 + random(-8, 8);
      const dist = patchRadius * 0.92 * Math.sqrt((a + 0.3) / numAreoles);
      const ax = cx + cos(ang) * dist;
      const ay = cy + sin(ang) * dist;
      const ar = random(3.2, 7.8);

      // Dark hairline prothallus trench around the areole
      brush.set("rotring", "#080b0e", 0.32);
      brush.arc(ax, ay, ar + 0.9, random(0, 40), random(290, 355));

      // Stippled areole cushion
      if (isSulphurMapLichen) {
        const col = random() < 0.55 ? "#d8d138" : random() < 0.7 ? "#a8bf28" : "#ebe465";
        brush.set("stipple_rim", col, 0.55);
        brush.line(ax - ar * 0.4, ay - ar * 0.2, ax + ar * 0.4, ay + ar * 0.2);
        // Tiny black lecideine apothecium dot wedged between areoles
        if (random() < 0.35) {
          brush.set("rotring", "#090c10", 0.55);
          brush.line(ax + ar * 0.75, ay, ax + ar * 0.75 + 0.8, ay + 0.8);
        }
      } else {
        const col = random() < 0.5 ? "#5a6c7a" : random() < 0.7 ? "#8395a3" : "#b5c2cc";
        brush.set("stipple_rim", col, 0.52);
        brush.line(ax - ar * 0.4, ay - ar * 0.2, ax + ar * 0.4, ay + ar * 0.2);
      }
    }
  }
}

// ============================================================================
// STEP 4: MULTI-SCALE RECURSIVE ROSETTE HIERARCHY
// ============================================================================

function generateMacroColonies() {
  // Poisson-like relaxed all-over distribution across [-90, 1290] x [-90, 1290]
  // Ensures no horizon and no single focal point—only an endless coastline of edges
  const candidates = [];
  const targetCount = 16;
  let attempts = 0;

  while (candidates.length < targetCount && attempts < 800) {
    attempts++;
    const x = random(-70, width + 70);
    const y = random(-70, height + 70);
    const r = random(185, 295);

    let ok = true;
    for (let c of candidates) {
      const d = dist(x, y, c.x, c.y);
      if (d < (r + c.radius) * 0.54) {
        ok = false;
        break;
      }
    }
    if (ok) {
      // Assign morphs: ~72% monochrome slate/silver/zoned, ~28% sulphur-chartreuse/rust accent
      const roll = random();
      let morphName = "slateMorph";
      if (roll < 0.38) morphName = "slateMorph";
      else if (roll < 0.58) morphName = "silverMorph";
      else if (roll < 0.74) morphName = "zonedMorph";
      else if (roll < 0.90) morphName = "sulphurMorph";
      else morphName = "rustMorph";

      candidates.push({
        x,
        y,
        radius: r,
        generation: 1,
        morphName,
        morph: PALETTE[morphName],
        seed: random(100, 9999),
        eccentricity: random(0.84, 1.16),
        orientation: random(360)
      });
    }
  }
  return candidates;
}

function generateFrontierColonies(macroColonies) {
  const frontier = [];

  // Place medium & small colonies along colony collision boundaries and rock cracks
  for (let i = 0; i < 34; i++) {
    let x, y, r;
    if (i < 20 && macroColonies.length >= 2) {
      // Between two macro colonies
      const a = random(macroColonies);
      const b = random(macroColonies);
      const mix = random(0.35, 0.65);
      x = lerp(a.x, b.x, mix) + random(-45, 45);
      y = lerp(a.y, b.y, mix) + random(-45, 45);
      r = random(48, 105);
    } else if (crackNodes.length > 0) {
      // Nucleating along a rock crack edge
      const node = random(crackNodes);
      const side = random() < 0.5 ? 1 : -1;
      const offset = random(28, 70);
      x = node.x + cos(node.ang + side * 90) * offset;
      y = node.y + sin(node.ang + side * 90) * offset;
      r = random(32, 78);
    } else {
      x = random(0, width);
      y = random(0, height);
      r = random(40, 85);
    }

    const roll = random();
    let morphName = "slateMorph";
    if (roll < 0.30) morphName = "slateMorph";
    else if (roll < 0.48) morphName = "silverMorph";
    else if (roll < 0.76) morphName = "sulphurMorph";
    else if (roll < 0.92) morphName = "rustMorph";
    else morphName = "zonedMorph";

    frontier.push({
      x,
      y,
      radius: r,
      generation: 2,
      morphName,
      morph: PALETTE[morphName],
      seed: random(100, 9999),
      eccentricity: random(0.85, 1.15),
      orientation: random(360)
    });
  }

  return frontier;
}

function chooseChildMorph(parentMorphName) {
  // Self-similar contrast: slate colonies often host vibrant sulphur/chartreuse or silver daughter rosettes;
  // sulphur colonies host rust-orange or slate-blue daughter rosettes
  const r = random();
  if (parentMorphName === "slateMorph" || parentMorphName === "silverMorph") {
    if (r < 0.44) return "sulphurMorph";
    if (r < 0.68) return "rustMorph";
    if (r < 0.85) return "silverMorph";
    return "slateMorph";
  } else if (parentMorphName === "sulphurMorph") {
    if (r < 0.38) return "rustMorph";
    if (r < 0.72) return "slateMorph";
    return "sulphurMorph";
  } else {
    if (r < 0.45) return "sulphurMorph";
    if (r < 0.80) return "slateMorph";
    return "rustMorph";
  }
}

// ============================================================================
// BOTANICAL ROSETTE & BIFURCATING LOBE RENDERER
// ============================================================================

function drawLichenRosette(rosette) {
  const { x: cx, y: cy, radius: R, generation: gen, morph, morphName, seed } = rosette;
  if (R < 4.5) return;

  // 1. Outer Prothallus Fringe & Marginal Rhizines (where colony meets bare stone or older crust)
  if (R > 22) {
    drawProthallusHalo(rosette);
  }

  // 2. Concentric Imbricated Lobe Zones stepping from outer margin R inward to center
  // Each radial zone is broken into staggered, overlapping multi-lobe arc sectors (no bullseye rings!)
  let currentR = R;
  const minCoreR = Math.max(5.5, R * 0.21);
  let ringIndex = 0;

  while (currentR > minCoreR) {
    const radialFraction = currentR / R; // 1.0 at outer edge -> 0.21 at inner core
    const lobeArcWidth = Math.max(5.5, 6.5 + currentR * 0.088);
    const totalLobesInRing = Math.max(6, Math.round((TWO_PI * currentR) / lobeArcWidth));

    // Break the 360° perimeter into staggered overlapping sectors of 2 to 5 lobes each
    const numSectors = Math.max(3, Math.round(totalLobesInRing / 3.2));
    const sectorOrder = [];
    for (let s = 0; s < numSectors; s++) sectorOrder.push(s);
    // Shuffle sector draw order so adjacent sectors shingle naturally over one another
    for (let s = sectorOrder.length - 1; s > 0; s--) {
      const j = Math.floor(random(s + 1));
      const tmp = sectorOrder[s];
      sectorOrder[s] = sectorOrder[j];
      sectorOrder[j] = tmp;
    }

    const baseSectorSpan = 360 / numSectors;
    const ringAngleOffset = (ringIndex * 27.3 + seed * 13.7) % 360;

    for (let sIdx of sectorOrder) {
      const overlapDeg = Math.min(14, baseSectorSpan * 0.22);
      const thetaStart = ringAngleOffset + sIdx * baseSectorSpan - overlapDeg * 0.5;
      const thetaEnd = ringAngleOffset + (sIdx + 1) * baseSectorSpan + overlapDeg * 0.5;
      const sectorR = currentR * random(0.95, 1.05);
      const lobesInSector = Math.max(2, Math.round(((thetaEnd - thetaStart) / 360) * totalLobesInRing));

      drawLobeSector(
        rosette,
        sectorR,
        radialFraction,
        thetaStart,
        thetaEnd,
        lobesInSector,
        ringIndex * 31 + sIdx * 7
      );
    }

    // Step inward: step size shrinks proportionally as we zoom toward the center
    const stepR = Math.max(4.2, currentR * random(0.14, 0.19));
    currentR -= stepR;
    ringIndex++;
  }

  // 3. Central Apothecia (Jam-Tart Fruiting Cups) & Sorediate Core
  drawApotheciaCluster(rosette, minCoreR * 1.25);

  // 4. Recursive Self-Similarity: Spawn Daughter Rosettes Inside & Across Parent Colony
  if (gen < 4 && R > 18) {
    const numChildren = gen === 1 ? Math.floor(random(3, 6)) : gen === 2 ? Math.floor(random(2, 4)) : Math.floor(random(1, 3));
    for (let c = 0; c < numChildren; c++) {
      // First child often nucleates right in the senescent center; others on mid-inner lobe rings
      const distFactor = c === 0 ? random(0.04, 0.22) : random(0.24, 0.62);
      const childAng = c * (360 / numChildren) + random(-28, 28) + seed;
      const childDist = R * distFactor;
      const childX = cx + cos(childAng) * childDist;
      const childY = cy + sin(childAng) * childDist;
      const childR = R * (c === 0 ? random(0.24, 0.36) : random(0.16, 0.28));

      const childMorphName = chooseChildMorph(morphName);
      drawLichenRosette({
        x: childX,
        y: childY,
        radius: childR,
        generation: gen + 1,
        morphName: childMorphName,
        morph: PALETTE[childMorphName],
        seed: seed + (c + 1) * 419.3,
        eccentricity: random(0.86, 1.14),
        orientation: random(360)
      });
    }
  }
}

function drawProthallusHalo(rosette) {
  const { x: cx, y: cy, radius: R, morph, seed } = rosette;
  const numArcs = 8;
  const span = 360 / numArcs;

  for (let i = 0; i < numArcs; i++) {
    const a1 = i * span;
    const a2 = (i + 1) * span;
    const pts = [];
    const steps = 12;
    for (let s = 0; s <= steps; s++) {
      const a = lerp(a1, a2, s / steps);
      const n = noise(cx * 0.008 + cos(a) * 1.5, cy * 0.008 + sin(a) * 1.5, seed * 0.01);
      const r = R * (0.98 + 0.09 * n);
      const [wx, wy] = warpPoint(cx + cos(a) * r, cy + sin(a) * r, 0.0035, 16, seed);
      pts.push([wx, wy, 0.8 + 0.4 * sin((s / steps) * 180)]);
    }
    brush.set("stipple_heavy", morph.prothallus, R > 120 ? 1.05 : 0.75);
    safeSpline(pts, 0.35);
  }
}

function computeLobePoint(rosette, baseR, thetaCenter, dTheta, u, lobeSeed, depthScale = 1.0) {
  const { x: cx, y: cy, eccentricity, orientation, seed } = rosette;

  // Steep-sided botanical lobe arch (pinched at u = ±1 sinuses, broad across tip)
  const clampedU = constrain(u, -1, 1);
  const arch = Math.pow(Math.max(0.001, 1.0 - clampedU * clampedU), 0.52);

  // Dichotomous (forked) indentation in the middle of the lobe apex
  const forkShift = (noise(lobeSeed * 17.3) - 0.5) * 0.26;
  const forkDepth = 0.16 + 0.14 * noise(lobeSeed * 31.1);
  const fork = 1.0 - forkDepth * Math.exp(-Math.pow((clampedU - forkShift) * 3.4, 2));

  // Secondary crenate sub-lobes along the margin
  const subLobeFreq = 2.5 + Math.floor(noise(lobeSeed * 9.2) * 2);
  const crenate = 0.065 * Math.cos(clampedU * Math.PI * subLobeFreq);

  // Lobe radial protrusion length
  const lobeLength = Math.max(3.2, baseR * (0.14 + 0.07 * noise(lobeSeed * 5.7))) * depthScale;
  const rLocal = baseR * depthScale + lobeLength * (arch * fork + crenate * arch);

  // Flabellate (fan-shaped) angular flare near lobe apex so sinuses pinch into keyhole notches
  const flare = 0.22 * Math.sin(clampedU * Math.PI) * arch;
  const theta = thetaCenter + (dTheta * 0.5) * (clampedU + flare);

  // Elliptical orientation transform
  const relAng = theta - orientation;
  const ex = rLocal * cos(relAng) * eccentricity;
  const ey = (rLocal * sin(relAng)) / eccentricity;
  const rotX = cx + ex * cos(orientation) - ey * sin(orientation);
  const rotY = cy + ex * sin(orientation) + ey * cos(orientation);

  // Subtle boulder surface + crack reaction warp
  const warpAmp = Math.min(18, baseR * 0.085);
  return warpPoint(rotX, rotY, 0.0038, warpAmp, seed);
}

function drawLobeSector(rosette, sectorR, radialFraction, thetaStart, thetaEnd, numLobes, sectorSeed) {
  const { morph, morphName } = rosette;
  const dTheta = (thetaEnd - thetaStart) / numLobes;
  const isSmall = sectorR < 34;
  const samplesPerLobe = isSmall ? 7 : sectorR < 95 ? 9 : 12;

  // Build multi-band contour splines across all lobes in this sector:
  // 1. Outward drop-shadow spline (tucked just beyond the lobe tips & deep in sinuses)
  // 2. Inner recessed base spline (0.64 depth)
  // 3. Mid-thallus cushion spline (0.78 depth)
  // 4. Upper-cortex sub-marginal spline (0.91 depth)
  // 5. Bright crenulate marginal rim spline (1.00 depth)
  const shadowPts = [];
  const basePts = [];
  const midPts = [];
  const cortexPts = [];
  const rimPts = [];
  const sinusCreases = [];
  const radialNerves = [];

  const shadowOutset = Math.max(1.4, Math.min(4.2, sectorR * 0.032));

  for (let l = 0; l < numLobes; l++) {
    const thetaCenter = thetaStart + (l + 0.5) * dTheta;
    const lobeSeed = rosette.seed + sectorSeed * 19.1 + l * 7.3;

    // Record keyhole sinus crease coordinates at u = -1
    const sOuter = computeLobePoint(rosette, sectorR, thetaCenter, dTheta, -0.98, lobeSeed, 0.98);
    const sInner = computeLobePoint(rosette, sectorR, thetaCenter, dTheta, -0.92, lobeSeed, 0.72);
    sinusCreases.push([sOuter, sInner]);

    // Record radial hyphal striation nerve inside each forked lobe
    if (sectorR > 16) {
      for (let branch of [-0.36, 0.36]) {
        const n1 = computeLobePoint(rosette, sectorR, thetaCenter, dTheta, branch * 0.5, lobeSeed, 0.68);
        const n2 = computeLobePoint(rosette, sectorR, thetaCenter, dTheta, branch * 0.85, lobeSeed, 0.84);
        const n3 = computeLobePoint(rosette, sectorR, thetaCenter, dTheta, branch * 1.05, lobeSeed, 0.95);
        radialNerves.push([
          [n1[0], n1[1], 0.5],
          [n2[0], n2[1], 0.9],
          [n3[0], n3[1], 0.4]
        ]);
      }
    }

    for (let s = 0; s <= samplesPerLobe; s++) {
      // Avoid duplicate point at lobe junction
      if (l > 0 && s === 0) continue;
      const u = -1.0 + (2.0 * s) / samplesPerLobe;
      const isSinus = Math.abs(u) > 0.78;
      const isTip = Math.abs(u) < 0.65;

      const pRim = computeLobePoint(rosette, sectorR, thetaCenter, dTheta, u, lobeSeed, 1.0);
      const pCortex = computeLobePoint(rosette, sectorR, thetaCenter, dTheta, u, lobeSeed, 0.90);
      const pMid = computeLobePoint(rosette, sectorR, thetaCenter, dTheta, u, lobeSeed, 0.77);
      const pBase = computeLobePoint(rosette, sectorR, thetaCenter, dTheta, u, lobeSeed, 0.63);

      // Outward normal approximation for drop shadow
      const dx = pRim[0] - pCortex[0];
      const dy = pRim[1] - pCortex[1];
      const dLen = Math.sqrt(dx * dx + dy * dy) || 1;
      const sx = pRim[0] + (dx / dLen) * shadowOutset;
      const sy = pRim[1] + (dy / dLen) * shadowOutset;

      // Modulate pressure: heavy shadow in sinuses, heavy highlight on tips
      shadowPts.push([sx, sy, isSinus ? 1.25 : 0.82]);
      basePts.push([pBase[0], pBase[1], 0.85]);
      midPts.push([pMid[0], pMid[1], 0.95]);
      cortexPts.push([pCortex[0], pCortex[1], isTip ? 1.05 : 0.75]);
      rimPts.push([pRim[0], pRim[1], isTip ? 1.2 : 0.65]);
    }
  }

  // Select zonal colors (allowing zonedMorph or inner rings to shift toward chartreuse/sulphur/rust!)
  let cMid = morph.mid;
  let cCortex = morph.cortex;
  let cRim = morph.rim;
  let cBrightRim = morph.brightRim;

  if (morphName === "zonedMorph" && radialFraction < 0.58) {
    cMid = "#798f24";
    cCortex = "#c4cc35";
    cRim = "#e6df5c";
    cBrightRim = "#f5f09d";
  } else if (morphName === "rustMorph" && radialFraction > 0.72) {
    // Xanthoria outer lobe tips shift toward golden sulphur yellow
    cCortex = "#deb831";
    cRim = "#ede05f";
  }

  // PASS 1: Deep Sub-Marginal Drop Shadow (creates crisp 3D relief over underlying lobes/stone)
  brush.set(isSmall ? "stipple_fine" : "stipple_heavy", morph.prothallus, isSmall ? 0.65 : 0.92);
  safeSpline(shadowPts, 0.35);

  if (!isSmall) {
    brush.set("stipple_med", morph.shadow, 0.85);
    safeSpline(shadowPts, 0.35);
  }

  // PASS 2: Recessed Lobe Base & Mid-Thallus Stipple Gradation
  brush.set(isSmall ? "stipple_fine" : "stipple_med", morph.deep, isSmall ? 0.6 : 0.88);
  safeSpline(basePts, 0.38);

  brush.set(isSmall ? "stipple_fine" : "stipple_med", cMid, isSmall ? 0.62 : 0.92);
  safeSpline(midPts, 0.38);

  // PASS 3: Upper Cortex Stipple Band
  brush.set("stipple_fine", cCortex, isSmall ? 0.58 : 0.85);
  safeSpline(cortexPts, 0.38);

  // PASS 4: Radial Hyphal Striations & Dark Keyhole Sinus Creases
  if (radialNerves.length > 0) {
    brush.set("stipple_rim", morph.light, isSmall ? 0.38 : 0.52);
    for (let nerve of radialNerves) {
      safeSpline(nerve, 0.25);
    }
  }

  brush.set("rotring", morph.prothallus, isSmall ? 0.30 : 0.42);
  for (let crease of sinusCreases) {
    brush.line(crease[0][0], crease[0][1], crease[1][0], crease[1][1]);
  }

  // PASS 5: Luminous Crenulate Marginal Rim (densely stippled raised coastline edge)
  brush.set("stipple_rim", cRim, isSmall ? 0.52 : 0.78);
  safeSpline(rimPts, 0.36);

  // Crisp bright stipple highlight along the outermost lobe tips
  brush.set("stipple_rim", cBrightRim, isSmall ? 0.36 : 0.50);
  safeSpline(rimPts, 0.36);

  // Fine technical-pen stipple edge definition
  brush.set("rotring", morph.prothallus, isSmall ? 0.24 : 0.32);
  for (let i = 0; i < shadowPts.length; i += 2) {
    const p = shadowPts[i];
    brush.line(p[0], p[1], p[0] + 0.6, p[1] + 0.6);
  }

  // PASS 6: Soralia / Isidia Granular Outgrowths on mature mid-inner lobes
  if (radialFraction < 0.75 && radialFraction > 0.32 && random() < 0.45) {
    const midIdx = Math.floor(midPts.length * 0.5);
    if (midPts[midIdx]) {
      const [sx, sy] = midPts[midIdx];
      brush.set("stipple_rim", morph.soredia, isSmall ? 0.45 : 0.68);
      brush.line(sx - 2, sy - 1, sx + 2, sy + 1);
    }
  }
}

// ============================================================================
// CENTRAL APOTHECIA (JAM-TART FRUITING DISCS) RENDERER
// ============================================================================

function drawApotheciaCluster(rosette, coreRadius) {
  const { x: cx, y: cy, radius: R, morph, seed } = rosette;
  const count = constrain(Math.floor(R * 0.14), 3, 28);

  for (let i = 0; i < count; i++) {
    const a = i * 137.508 + seed;
    const dist = coreRadius * 0.95 * Math.sqrt((i + 0.25) / count);
    const [ax, ay] = warpPoint(cx + cos(a) * dist, cy + sin(a) * dist, 0.004, 10, seed);
    const apothR = constrain(R * random(0.025, 0.058) * (1.1 - 0.35 * (i / count)), 2.2, 13.5);

    drawSingleApothecium(ax, ay, apothR, morph, seed + i * 17.3);
  }
}

function drawSingleApothecium(ax, ay, rad, morph, apothSeed) {
  const steps = rad > 6 ? 12 : 8;
  const outerShadowPts = [];
  const excipleRimPts = [];
  const innerDiscPts = [];

  for (let s = 0; s <= steps; s++) {
    const ang = (s / steps) * 360;
    // Slight angular compression from crowding against neighbor apothecia
    const squeeze = 0.84 + 0.30 * noise(cos(ang) * 1.3 + apothSeed, sin(ang) * 1.3);
    const r = rad * squeeze;

    outerShadowPts.push([ax + cos(ang) * (r + 1.3), ay + sin(ang) * (r + 1.3), 0.9]);
    excipleRimPts.push([ax + cos(ang) * r, ay + sin(ang) * r, 1.0]);
    innerDiscPts.push([ax + cos(ang) * (r * 0.62), ay + sin(ang) * (r * 0.62), 0.95]);
  }

  // 1. Dark calyx shadow under the cup
  brush.set(rad > 5 ? "stipple_fine" : "rotring", morph.prothallus, rad > 5 ? 0.55 : 0.35);
  safeSpline(outerShadowPts, 0.45);

  // 2. Concave hymenium disc (Rust-Orange, Burnt Sienna, or Slate-Black)
  const discColor = morph.apotheciaDisc[Math.floor(apothSeed * 10) % morph.apotheciaDisc.length];
  brush.set("stipple_rim", discColor, rad > 6 ? 0.72 : 0.48);
  safeSpline(innerDiscPts, 0.45);
  brush.line(ax - rad * 0.3, ay - rad * 0.15, ax + rad * 0.3, ay + rad * 0.15);

  // Dark pit shadow in the very center of the concave cup
  brush.set("rotring", morph.prothallus, 0.35);
  brush.line(ax - 0.5, ay - 0.5, ax + 0.5, ay + 0.5);

  // 3. Raised crenulate thalline exciple (outer ring of the cup)
  brush.set("stipple_rim", morph.apotheciaRim, rad > 6 ? 0.58 : 0.40);
  safeSpline(excipleRimPts, 0.45);
}

// ============================================================================
// STEP 7: MASTER BOTANICAL MICRO-STIPPLE & COASTLINE PRECISION PASS
// ============================================================================

function renderMasterBotanicalStipplePass(macroColonies, frontierColonies) {
  const allColonies = macroColonies.concat(frontierColonies);

  // Add thousands of crisp individual Rapidograph ("rotring") stipple dots along colony coastlines
  // and micro-rosettes (3–7px scale) in crevices so the eye can zoom in infinitely
  for (let col of allColonies) {
    const { x: cx, y: cy, radius: R, morph, seed } = col;
    const dotClusters = Math.floor(R * 0.45);

    // 1. Crisp highlight stipple dots dusting the outer lobe crests
    brush.set("rotring", morph.brightRim, 0.30);
    for (let i = 0; i < dotClusters; i++) {
      const a = random(360);
      const r = R * random(0.28, 1.01);
      const [px, py] = warpPoint(cx + cos(a) * r, cy + sin(a) * r, 0.0038, 14, seed);
      brush.line(px, py, px + 0.55, py + 0.55);
    }

    // 2. Deep ink stipple pores & pycnidia dots in the inner thallus
    brush.set("rotring", morph.prothallus, 0.34);
    for (let i = 0; i < dotClusters; i++) {
      const a = random(360);
      const r = R * random(0.15, 0.95);
      const [px, py] = warpPoint(cx + cos(a) * r, cy + sin(a) * r, 0.0038, 14, seed);
      brush.line(px, py, px + 0.65, py + 0.65);
    }

    // 3. Vibrant accent soredia & micro-apothecia bursts
    const accentColor = random() < 0.6 ? "#e3dc46" : "#c7521a";
    brush.set("rotring", accentColor, 0.34);
    const accentCount = Math.floor(R * 0.18);
    for (let i = 0; i < accentCount; i++) {
      const a = random(360);
      const r = R * random(0.12, 0.68);
      const [px, py] = warpPoint(cx + cos(a) * r, cy + sin(a) * r, 0.0038, 14, seed);
      brush.line(px, py, px + 0.6, py + 0.6);
    }
  }
}

