function draw() {
  translate(-width / 2, -height / 2);

  // Crisp morning alabaster paper ground
  background("#f5f7fa");

  // ---------------------------------------------------------------------------
  // 1. LIGHTING & GEOMETRY DEFINITIONS
  // ---------------------------------------------------------------------------
  // Raking morning window light from upper-left
  const Lx = -0.81, Ly = -0.41, Lz = 0.42;
  const Hx = -0.45, Hy = -0.23, Hz = 0.86; // Halfway vector for specular sheen

  // Helper: Catmull-Rom / smooth cubic interpolation along control points
  function evalSplinePoint(pts, t) {
    const n = pts.length - 1;
    const st = constrain(t, 0, 1) * n;
    const i = Math.min(Math.floor(st), n - 1);
    const f = st - i;
    const p0 = pts[Math.max(0, i - 1)];
    const p1 = pts[i];
    const p2 = pts[i + 1];
    const p3 = pts[Math.min(n, i + 2)];

    const f2 = f * f;
    const f3 = f2 * f;
    const x = 0.5 * (
      (2 * p1[0]) +
      (-p0[0] + p2[0]) * f +
      (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * f2 +
      (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * f3
    );
    const y = 0.5 * (
      (2 * p1[1]) +
      (-p0[1] + p2[1]) * f +
      (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * f2 +
      (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * f3
    );
    return [x, y];
  }

  function evalSplineFrame(pts, t) {
    const eps = 0.002;
    const pA = evalSplinePoint(pts, Math.max(0, t - eps));
    const pB = evalSplinePoint(pts, Math.min(1, t + eps));
    const pC = evalSplinePoint(pts, t);
    let tx = pB[0] - pA[0];
    let ty = pB[1] - pA[1];
    const len = Math.hypot(tx, ty) || 1;
    tx /= len;
    ty /= len;
    // Normal pointing toward upper-left (for top-right to bottom-left spine)
    // Wait: if spine goes (-x, +y), then (+ty, -tx) points (+, +) down-right,
    // and (-ty, +tx) points (-, -) up-left toward the raking light!
    const nx = -ty;
    const ny = tx;
    return { x: pC[0], y: pC[1], tx, ty, nx, ny };
  }

  // ---------------------------------------------------------------------------
  // 2. RIBBON A (NARROW END / UNKNOTTED NECKBAND LOOP) & RIBBON B (WIDE BLADE)
  // ---------------------------------------------------------------------------
  // Ribbon A: Enters top-right-center, loops through upper-left, passes UNDER
  // Ribbon B near center, and drapes down-right to the narrow pointed tail tip.
  const ptsA = [
    [855, -75],
    [625, 95],
    [480, 275],
    [525, 445],
    [655, 610],
    [810, 765],
    [930, 885],
    [1015, 965]
  ];

  // Ribbon B: Hero wide blade & crushed knot-memory zone sweeping diagonally
  // from top-right to bottom-left.
  const ptsB = [
    [1175, -65],
    [965, 130],
    [775, 320],
    [595, 510],
    [425, 715],
    [270, 900],
    [155, 1035]
  ];

  // Discrete sharp creases for Ribbon B (crushed knot zone + blade folds)
  // Each crease: [s_center, slope_u, curve_u2, amp, width_s, asym]
  const creasesB = [
    [0.05,  0.035,  0.015, 11.5, 0.013,  0.4],
    [0.09, -0.045,  0.020, 14.0, 0.011, -0.5],
    [0.13,  0.055, -0.025, 16.5, 0.010,  0.6],
    [0.165,-0.030,  0.030, 18.0, 0.009, -0.7],
