    [0.235,-0.055, -0.030, 21.0, 0.0085, 0.8],
    [0.27,  0.040,  0.035, 18.5, 0.0095,-0.6],
    [0.31, -0.060,  0.018, 17.5, 0.010,  0.7],
    [0.35,  0.025, -0.028, 16.0, 0.011, -0.5],
    [0.395,-0.048,  0.022, 15.0, 0.012,  0.6],
    [0.445, 0.052,  0.015, 14.5, 0.013, -0.4],
    [0.505,-0.035, -0.025, 16.5, 0.013,  0.7], // Arch over Ribbon A
    [0.56,  0.045,  0.020, 13.5, 0.014, -0.5],
    [0.625,-0.050,  0.030, 15.5, 0.013,  0.6], // Wide blade buckle
