    [0.35,  0.055, -0.018, 14.5, 0.012,  0.6],
    [0.42, -0.040,  0.022, 13.0, 0.013, -0.5],
    [0.64,  0.045, -0.020, 13.5, 0.013,  0.6],
    [0.72, -0.038,  0.025, 14.5, 0.012, -0.6],
    [0.80,  0.032, -0.015, 12.0, 0.014,  0.5],
    [0.88, -0.028,  0.012,  9.5, 0.015, -0.4]
  ];

  function getHalfWidthB(s) {
    const tipStart = 0.855;
    if (s > tipStart) {
      const tt = (s - tipStart) / (1.0 - tipStart);
      // Crisp 45-degree pointed diamond tip with slight silk corner rounding
      return Math.max(1.5, 132 * (1.0 - Math.pow(tt, 0.98)));
    }
    // Flare from neckband (60px) through pinched knot zone (51px) up to wide blade (132px)
    const base = 58 + 74 * Math.pow(s / tipStart, 1.38);
    // Knot zone pinch around s in [0.12, 0.34]
    const knotPinch = -11.5 * Math.exp(-Math.pow((s - 0.22) / 0.11, 2));
    // Accordion edge pinching from sharp creases
    let edgeWave = 0;
    for (let i = 0; i < creasesB.length; i++) {
      const c = creasesB[i];
      const ds = (s - c[0]) / (c[4] * 1.8);
      edgeWave += (c[3] * 0.22) * Math.exp(-ds * ds) * (i % 2 === 0 ? 1 : -0.8);
    }
    return base + knotPinch + edgeWave;
  }

  function getHalfWidthA(s) {
    const tipStart = 0.895;
    if (s > tipStart) {
      const tt = (s - tipStart) / (1.0 - tipStart);
      return Math.max(1.2, 64 * (1.0 - Math.pow(tt, 0.98)));
    }
    // Narrow end with slight perspective twist narrowing around s = 0.32
    const base = 52 + 12 * (s / tipStart);
    const twistPinch = -7.5 * Math.exp(-Math.pow((s - 0.31) / 0.12, 2));
    const wave = 3.2 * Math.sin(s * 34) + 2.1 * Math.cos(s * 53);
    return base + twistPinch + wave;
  }

  // Evaluate 2D world position + 3D silk height + crease ridge metric for Ribbon B
  function evalRibbonB(s, u) {
    const fr = evalSplineFrame(ptsB, s);
    const hw = getHalfWidthB(s);

    // 3D drape & buckle waves shifting the ribbon slightly in (x, y)
    let waveShiftN = 8.0 * Math.sin(s * 19.0 + 0.5) + 5.5 * Math.cos(s * 37.0);
    let waveShiftT = 0;

    // Evaluate sharp crushed silk creases
    let hCrease = 0;
    let ridgeFactor = 0;
    let valleyFactor = 0;

    for (let i = 0; i < creasesB.length; i++) {
      const [sc, slp, crv, amp, ws, asym] = creasesB[i];
      const d = (s - sc) + slp * u + crv * (u * u - 0.35);
      const nd = d / ws;
      // Sharp cusp ridge profile: sqrt(nd^2 + 0.08) gives razor-sharp crease crest
      const cusp = Math.exp(-Math.sqrt(nd * nd + 0.06));
      // Asymmetric step across crease (origami fold)
      const step = asym * Math.atan(nd * 2.2) * Math.exp(-nd * nd * 0.22);
      // Flanking trough next to ridge
      const trough = -0.42 * nd * nd * Math.exp(-nd * nd * 0.45);

      const envU = 1.0 - 0.18 * Math.pow(Math.abs(u), 3);
      hCrease += amp * (cusp + 0.45 * step + trough) * envU;

      // Ridge crest detector (peaks sharply right on the crease line)
      const crest = Math.exp(-(nd * nd) / 0.14);
      ridgeFactor += crest * (amp / 16.0);
      if (nd > 0.25 && nd < 1.8) {
        valleyFactor += Math.exp(-Math.pow((nd - 0.85) / 0.55, 2)) * (amp / 16.0);
      }

      // Slight lateral pinch along the crease
      waveShiftN += (amp * 0.18) * step * (u > 0 ? -1 : 1);
      waveShiftT -= (amp * 0.15) * cusp;
    }

    // Secondary intersecting chevron/diamond creases in the crushed knot zone (s in [0.06, 0.46])
    const knotEnv = Math.exp(-Math.pow((s - 0.24) / 0.16, 2));
    if (knotEnv > 0.02) {
      const p1 = Math.sin((s * 68 + u * 2.6) * Math.PI);
      const p2 = Math.sin((s * 54 - u * 3.1 + 0.35) * Math.PI);
      const chev1 = Math.pow(1.0 - Math.abs(p1), 4.5);
      const chev2 = Math.pow(1.0 - Math.abs(p2), 4.5);
      hCrease += knotEnv * 11.5 * (chev1 + 0.85 * chev2);
      ridgeFactor += knotEnv * 0.95 * Math.max(chev1, chev2);

      // Classic longitudinal tie dimple (two ridges at u = +-0.38, deep central trough at u = 0)
      const dimple = -9.5 * Math.exp(-Math.pow(u / 0.28, 2)) +
                      7.5 * Math.exp(-Math.pow((Math.abs(u) - 0.42) / 0.22, 2));
      hCrease += knotEnv * dimple;
      if (Math.abs(Math.abs(u) - 0.42) < 0.14) {
        ridgeFactor += knotEnv * 0.55 * Math.exp(-Math.pow((Math.abs(u) - 0.42) / 0.1, 2));
      }
    }

    // Radiating fan micro-creases in wide blade
    const fanPhase = Math.sin((s * 42 + u * 1.7 * Math.sin(s * 14)) * Math.PI);
    const fanCrease = Math.pow(1.0 - Math.abs(fanPhase), 5.0) * (1.0 - 0.5 * knotEnv);
    hCrease += 5.5 * fanCrease;
    ridgeFactor += 0.42 * fanCrease;

    // Rolled tubular silk edge profile
    const absU = Math.abs(u);
    const edgeRoll = -14.0 * Math.pow(absU, 5.5) + 3.2 * Math.exp(-Math.pow((absU - 0.86) / 0.1, 2));

    // Macro elevation over the bedsheet and arching over Ribbon A (around s = 0.50)
    const bridgeArch = 28.0 * Math.exp(-Math.pow((s - 0.505) / 0.11, 2));
    const buckleWave = 16.0 * Math.exp(-Math.pow((s - 0.74) / 0.08, 2)) +
                       9.0 * Math.exp(-Math.pow((s - 0.97) / 0.05, 2)); // lifted pointed tip

    const x = fr.x + fr.nx * (u * hw + waveShiftN) + fr.tx * waveShiftT;
    const y = fr.y + fr.ny * (u * hw + waveShiftN) + fr.ty * waveShiftT;
    const z = 14.0 + bridgeArch + buckleWave + hCrease + edgeRoll;

    return {
      x, y, z, hw,
      tx: fr.tx, ty: fr.ty, nx: fr.nx, ny: fr.ny,
      ridge: constrain(ridgeFactor, 0, 2.2),
      valley: constrain(valleyFactor, 0, 1.8),
      knotEnv
    };
  }

  // Evaluate 2D world position + 3D silk height + crease ridge metric for Ribbon A
  function evalRibbonA(s, u) {
    const fr = evalSplineFrame(ptsA, s);
    const hw = getHalfWidthA(s);

    let waveShiftN = 5.0 * Math.sin(s * 17.0 - 0.4);
    let waveShiftT = 0;

    let hCrease = 0;
    let ridgeFactor = 0;
    let valleyFactor = 0;

    for (let i = 0; i < creasesA.length; i++) {
      const [sc, slp, crv, amp, ws, asym] = creasesA[i];
      const d = (s - sc) + slp * u + crv * (u * u - 0.3);
      const nd = d / ws;
      const cusp = Math.exp(-Math.sqrt(nd * nd + 0.07));
      const step = asym * Math.atan(nd * 2.0) * Math.exp(-nd * nd * 0.25);
      const trough = -0.38 * nd * nd * Math.exp(-nd * nd * 0.45);

      hCrease += amp * (cusp + 0.4 * step + trough);
      ridgeFactor += Math.exp(-(nd * nd) / 0.15) * (amp / 15.0);
      if (nd > 0.2 && nd < 1.7) {
        valleyFactor += Math.exp(-Math.pow((nd - 0.8) / 0.5, 2)) * (amp / 15.0);
      }
      waveShiftN += (amp * 0.14) * step;
      waveShiftT -= (amp * 0.12) * cusp;
    }

    // Secondary fine silk creases
    const fPhase = Math.sin((s * 48 - u * 2.1) * Math.PI);
    const fCrease = Math.pow(1.0 - Math.abs(fPhase), 4.5);
    hCrease += 5.0 * fCrease;
    ridgeFactor += 0.38 * fCrease;

    // Back-seam recessed channel where the narrow end shows its underside (s in [0.15, 0.44])
    const seamEnv = Math.exp(-Math.pow((s - 0.29) / 0.13, 2));
    let seamDip = 0;
    if (seamEnv > 0.05) {
      const uSeam = u - 0.06;
      seamDip = -7.5 * Math.exp(-Math.pow(uSeam / 0.09, 2)) +
                 3.8 * Math.exp(-Math.pow((uSeam + 0.11) / 0.07, 2));
      if (Math.abs(uSeam + 0.11) < 0.08) {
        ridgeFactor += seamEnv * 0.75; // Highlighted lip of the folded center seam
      }
      if (Math.abs(uSeam) < 0.06) {
        valleyFactor += seamEnv * 0.95; // Dark recessed seam channel
      }
    }

    const absU = Math.abs(u);
    const edgeRoll = -11.5 * Math.pow(absU, 5.5) + 2.5 * Math.exp(-Math.pow((absU - 0.86) / 0.1, 2));

    const x = fr.x + fr.nx * (u * hw + waveShiftN) + fr.tx * waveShiftT;
    const y = fr.y + fr.ny * (u * hw + waveShiftN) + fr.ty * waveShiftT;
    const z = 10.0 + hCrease + seamDip + edgeRoll;

    return {
      x, y, z, hw,
      tx: fr.tx, ty: fr.ty, nx: fr.nx, ny: fr.ny,
      ridge: constrain(ridgeFactor, 0, 2.0),
      valley: constrain(valleyFactor, 0, 1.8),
      seamEnv
    };
  }

  // ---------------------------------------------------------------------------
  // 3. CRUMPLED WHITE HOTEL SHEETS HEIGHTFIELD
  // ---------------------------------------------------------------------------
  // Sharp tension creases across the linen bedsheet: [x1, y1, x2, y2, amp, sharpness, curve]
  const sheetCreases = [
    [-80, 180, 740, 620, 26, 48, 35],
    [140, -60, 1080, 520, 22, 55, -40],
    [-60, 580, 920, 1180, 28, 52, 45],
    [320, 310, 1260, 880, 24, 50, -30],
    [60, 890, 780, 1260, 20, 44, 25],
    [540, -50, 1260, 410, 19, 46, 30],
    // Radiating secondary pinch creases from where the tie & body rumpled the linen
    [580, 510, 180, 420, 16, 34, -20],
    [580, 510, 440, 980, 17, 38, 25],
    [760, 320, 1180, 640, 15, 36, -18],
    [260, 880, -60, 780, 15, 32, 15],
    [820, 760, 1240, 1090, 18, 40, -22]
  ];

  function evalSheetHeight(x, y) {
    // Broad billowing pillowy mattress/linen swells
    const nx = x * 0.0022;
    const ny = y * 0.0022;
    const warpX = x + 55 * (noise(nx + 1.3, ny + 2.1) - 0.5);
    const warpY = y + 55 * (noise(nx + 4.7, ny + 0.8) - 0.5);

    // Primary diagonal drape waves
    const diag1 = (warpX * 0.58 - warpY * 0.81) * 0.011;
    const diag2 = (warpX * 0.76 + warpY * 0.65) * 0.0085;
    let h = 24.0 * Math.sin(diag1) + 18.0 * Math.cos(diag2);

    // Add sharp tension ridges and concave troughs
    for (let i = 0; i < sheetCreases.length; i++) {
      const [x1, y1, x2, y2, amp, w, crv] = sheetCreases[i];
      const dx = x2 - x1;
      const dy = y2 - y1;
      const len2 = dx * dx + dy * dy;
      const t = constrain(((x - x1) * dx + (y - y1) * dy) / len2, 0, 1);
      const px = x1 + t * dx;
      const py = y1 + t * dy;
      // Perpendicular signed distance with slight arc curvature
      const invLen = 1.0 / Math.sqrt(len2);
      const d = ((x - px) * (-dy * invLen) + (y - py) * (dx * invLen)) +
                crv * 4.0 * t * (1.0 - t);
      const env = Math.sin(t * Math.PI);
      const nd = d / w;
      // Crisp linen ridge + asymmetric fold slope
      const ridge = Math.exp(-Math.sqrt(nd * nd + 0.12)) + 0.35 * Math.atan(nd * 1.6) * Math.exp(-nd * nd * 0.2);
      h += amp * env * ridge;
    }

    // Fine crumpled cotton/linen micro-rumples
    const fine1 = noise(x * 0.009 + 10, y * 0.009 + 10);
    const fine2 = noise(x * 0.022 + 25, y * 0.022 + 25);
    h += 9.0 * (fine1 - 0.5) + 3.2 * (fine2 - 0.5);
    return h;
  }

  // ---------------------------------------------------------------------------
  // 4. PRECOMPUTE TIE FOOTPRINT & SHEET LIGHTING GRID (240 x 240)
  // ---------------------------------------------------------------------------
  const G = 240;
  const cell = width / G; // 5px per grid cell
  const sheetHGrid = new Float32Array(G * G);
  const sheetLightGrid = new Float32Array(G * G);
  const sheetRidgeGrid = new Float32Array(G * G);
  const tieHeightGrid = new Float32Array(G * G);
  const tieIdGrid = new Uint8Array(G * G); // 0 = sheet, 1 = Ribbon A, 2 = Ribbon B
  const greenBounceGrid = new Float32Array(G * G);

  // Sample sheet height
  for (let gy = 0; gy < G; gy++) {
    const y = (gy + 0.5) * cell;
    for (let gx = 0; gx < G; gx++) {
      const x = (gx + 0.5) * cell;
      sheetHGrid[gy * G + gx] = evalSheetHeight(x, y);
    }
  }

  // Rasterize Ribbon A and Ribbon B elevations onto tieHeightGrid for exact cast shadows
  function stampRibbonToGrid(evalFn, stepsS, stepsU, id) {
    for (let is = 0; is <= stepsS; is++) {
      const s = is / stepsS;
      for (let iu = 0; iu <= stepsU; iu++) {
        const u = -1 + (2 * iu) / stepsU;
        const pt = evalFn(s, u);
        const gx = Math.floor(pt.x / cell);
        const gy = Math.floor(pt.y / cell);
        if (gx >= 0 && gx < G && gy >= 0 && gy < G) {
          const idx = gy * G + gx;
          const totalZ = sheetHGrid[idx] + pt.z;
          if (totalZ > tieHeightGrid[idx]) {
            tieHeightGrid[idx] = totalZ;
            tieIdGrid[idx] = id;
          }
          // Dilate 1-cell neighborhood to avoid grid pinhole gaps
          for (let oy = -1; oy <= 1; oy++) {
            for (let ox = -1; ox <= 1; ox++) {
              const nx = gx + ox, ny = gy + oy;
              if (nx >= 0 && nx < G && ny >= 0 && ny < G) {
                const nidx = ny * G + nx;
                if (totalZ - 1 > tieHeightGrid[nidx]) {
                  tieHeightGrid[nidx] = totalZ - 1;
                  if (tieIdGrid[nidx] === 0) tieIdGrid[nidx] = id;
                }
              }
            }
          }
        }
      }
    }
  }

  stampRibbonToGrid(evalRibbonA, 320, 48, 1);
  stampRibbonToGrid(evalRibbonB, 420, 72, 2);

  // Compute sheet normals, raking light, ray-marched cast shadows & viridian bounce light
  for (let gy = 0; gy < G; gy++) {
    for (let gx = 0; gx < G; gx++) {
      const idx = gy * G + gx;
      const hC = sheetHGrid[idx];
      const hL = sheetHGrid[gy * G + Math.max(0, gx - 1)];
      const hR = sheetHGrid[gy * G + Math.min(G - 1, gx + 1)];
      const hU = sheetHGrid[Math.max(0, gy - 1) * G + gx];
      const hD = sheetHGrid[Math.min(G - 1, gy + 1) * G + gx];

      const dhdx = (hR - hL) / (2 * cell);
      const dhdy = (hD - hU) / (2 * cell);
      // Laplacian for crisp sheet crease detection
      const lap = (hL + hR + hU + hD - 4 * hC) / (cell * cell);
      sheetRidgeGrid[idx] = constrain(-lap * 18.0, -1, 1);

      // Surface normal
      let nx = -dhdx * 1.45;
      let ny = -dhdy * 1.45;
      let nz = 1.0;
      const nlen = Math.hypot(nx, ny, nz);
      nx /= nlen; ny /= nlen; nz /= nlen;

      let diff = Math.max(0, nx * Lx + ny * Ly + nz * Lz);
      diff = Math.pow(diff, 0.88);

      // Ray-march toward the upper-left light source for cast shadows
      let shadow = 0;
      let tieShadow = 0;
      const raySteps = 22;
      for (let step = 1; step <= raySteps; step++) {
        const dist = step * 1.45; // in grid cells
        const rx = Math.round(gx + Lx * dist);
        const ry = Math.round(gy + Ly * dist);
        if (rx < 0 || rx >= G || ry < 0 || ry >= G) break;
        const rIdx = ry * G + rx;
        const rayZ = hC + (Lz / Math.hypot(Lx, Ly)) * (dist * cell) * 0.72;

        // Check tie occlusion
        if (tieHeightGrid[rIdx] > rayZ) {
          const penumbra = 1.0 - (step / (raySteps + 2)) * 0.65;
          tieShadow = Math.max(tieShadow, constrain((tieHeightGrid[rIdx] - rayZ) * 0.08, 0, 1) * penumbra);
        }
        // Check sheet self-shadowing
        if (sheetHGrid[rIdx] > rayZ + 1.5) {
          const sPen = 1.0 - (step / (raySteps + 2)) * 0.5;
          shadow = Math.max(shadow, constrain((sheetHGrid[rIdx] - rayZ) * 0.045, 0, 0.75) * sPen);
        }
      }

      // Compute proximity to the silk tie for viridian reflected bounce light on the white linen
      let bounce = 0;
      const searchR = 11; // ~55px radius
      for (let oy = -searchR; oy <= searchR; oy += 2) {
        for (let ox = -searchR; ox <= searchR; ox += 2) {
          const sx = gx + ox, sy = gy + oy;
          if (sx >= 0 && sx < G && sy >= 0 && sy < G) {
            if (tieIdGrid[sy * G + sx] > 0) {
              const d2 = ox * ox + oy * oy;
              if (d2 < searchR * searchR) {
                const w = Math.exp(-d2 / 32.0);
                bounce = Math.max(bounce, w);
              }
            }
          }
        }
      }

      const combinedShadow = Math.max(shadow, tieShadow * 0.92);
      const finalLight = constrain(diff * (1.0 - combinedShadow * 0.78) - tieShadow * 0.16, 0.03, 1.0);
      sheetLightGrid[idx] = finalLight;
      // Reflected viridian light is most visible in the soft shadow & midtone troughs next to the tie
      greenBounceGrid[idx] = bounce * constrain(1.15 - finalLight * 0.9, 0.15, 1.0);
    }
  }

  // Helper to sample sheet light, gradient & bounce smoothly at any (x, y)
  function sampleSheet(x, y) {
    const gx = constrain(Math.floor(x / cell), 1, G - 2);
    const gy = constrain(Math.floor(y / cell), 1, G - 2);
    const idx = gy * G + gx;
    const gxR = sheetHGrid[idx + 1] - sheetHGrid[idx - 1];
    const gyD = sheetHGrid[idx + G] - sheetHGrid[idx - G];
    // Contour tangent angle (in degrees) along the sheet fold
    const contourAng = atan2(gxR, -gyD);
    return {
      light: sheetLightGrid[idx],
      ridge: sheetRidgeGrid[idx],
      bounce: greenBounceGrid[idx],
      tieId: tieIdGrid[idx],
      contourAng
    };
  }

  // ---------------------------------------------------------------------------
  // 5. RENDER LAYER 1: CRUMPLED WHITE HOTEL SHEETS (COOL GREY PENCIL)
  // ---------------------------------------------------------------------------
  // Cool monochrome grey palette stops from deep shadow slate to morning white
  const sheetGreyPalette = [
    "#323b48", // 0: deepest cast shadow slate
    "#414c5c", // 1: deep shadow trough
    "#525f71", // 2: dark cool slate
    "#667385", // 3: medium-dark cool grey
    "#7b889a", // 4: shadow midtone
    "#919eae", // 5: cool dove grey
    "#a8b3c2", // 6: soft silver-grey
    "#bfc8d5", // 7: light cool grey
    "#d4dce6", // 8: delicate morning shadow
    "#e6ebf2", // 9: luminous off-white slope
    "#f3f6fa", // 10: bright sunlit linen
    "#ffffff"  // 11: pure raking ridge highlight
  ];

  // Viridian-tinted cool grey palette for reflected silk bounce light in sheet shadows
  const sheetBouncePalette = [
    "#29403d",
    "#395752",
    "#4b6e68",
    "#618680",
    "#7ca19a",
    "#9bbab4"
  ];

  // 5A. Soft Tonal Under-Wash (batched by color bucket for speed & seamless graphite stump feel)
  brush.noStroke();
  brush.noHatch();
  const patchStep = 18;
  const buckets = Array.from({ length: sheetGreyPalette.length }, () => []);
  const bounceBuckets = Array.from({ length: sheetBouncePalette.length }, () => []);

  for (let y = -10; y < height + 10; y += patchStep) {
    for (let x = -10; x < width + 10; x += patchStep) {
      const s = sampleSheet(x + patchStep * 0.5, y + patchStep * 0.5);
      const bIdx = constrain(Math.floor(s.light * 11.99), 0, 11);
      if (bIdx <= 9) {
        buckets[bIdx].push([x, y, s.contourAng]);
      }
      if (s.bounce > 0.16 && s.light < 0.78) {
        const gIdx = constrain(Math.floor(s.light * 7.2), 0, sheetBouncePalette.length - 1);
        bounceBuckets[gIdx].push([x, y, s.bounce]);
      }
    }
  }

  // Draw batched soft tonal shadow foundations
  for (let b = 0; b <= 9; b++) {
    const list = buckets[b];
    if (list.length === 0) continue;
    const alpha = map(b, 0, 9, 135, 38);
    brush.wash(sheetGreyPalette[b], alpha);
    for (let i = 0; i < list.length; i++) {
      const [px, py] = list[i];
      const jx = px + random(-4, 4);
      const jy = py + random(-4, 4);
      const rw = patchStep * random(1.25, 1.65);
      const rh = patchStep * random(1.25, 1.65);
      brush.rect(jx, jy, rw, rh, "corner");
    }
  }

  // Draw subtle reflected viridian glow in the white sheet shadows adjacent to the tie
  for (let g = 0; g < sheetBouncePalette.length; g++) {
    const list = bounceBuckets[g];
    if (list.length === 0) continue;
    brush.wash(sheetBouncePalette[g], 52);
    for (let i = 0; i < list.length; i++) {
      const [px, py] = list[i];
      brush.rect(px + random(-5, 5), py + random(-5, 5), patchStep * 1.4, patchStep * 1.4, "corner");
    }
  }
  brush.noWash();

  // 5B. Tortillon / Paper-Stump Blended Graphite Pass across Sheet Folds
  for (let b = 0; b <= 8; b++) {
    const list = buckets[b];
    if (list.length === 0) continue;
    brush.set("stump_blend", sheetGreyPalette[b], map(b, 0, 8, 1.45, 0.85));
    const stride = b <= 4 ? 1 : 2;
    for (let i = 0; i < list.length; i += stride) {
      const [px, py, ang] = list[i];
      const cx = px + random(0, patchStep);
      const cy = py + random(0, patchStep);
      const len = random(24, 46);
      const rad = (ang + random(-14, 14)) * (Math.PI / 180);
      const dx = Math.cos(rad) * len * 0.5;
      const dy = Math.sin(rad) * len * 0.5;
      brush.line(cx - dx, cy - dy, cx + dx, cy + dy);
    }
  }

  // 5C. Layered Cool Grey Pencil Shading (2B in deep shadows, HB in midtones, 2H on lit slopes)
  for (let pass = 0; pass < 2; pass++) {
    const step = pass === 0 ? 11 : 14;
    for (let y = 6; y < height - 6; y += step) {
      for (let x = 6; x < width - 6; x += step) {
        const jx = x + random(-4, 4);
        const jy = y + random(-4, 4);
        const s = sampleSheet(jx, jy);

        // Leave the brightest sunlit crests mostly pure luminous paper white
        if (s.light > 0.91 && random() < 0.82) continue;
        if (s.light > 0.78 && pass === 1 && random() < 0.65) continue;

        const cIdx = constrain(Math.floor(s.light * 11.2 + random(-0.45, 0.45)), 0, 10);
        let col = sheetGreyPalette[cIdx];

        // Mix in viridian-tinted pencil strokes right inside the tie's reflected light zone
        if (s.bounce > 0.22 && s.light < 0.72 && random() < s.bounce * 0.65) {
          const gIdx = constrain(Math.floor(s.light * 7.0), 0, sheetBouncePalette.length - 1);
          col = sheetBouncePalette[gIdx];
        }

        const bName = s.light < 0.36 ? "2B" : (s.light < 0.68 ? "HB" : "2H");
        const wgt = map(s.light, 0, 1, 0.95, 0.48) * random(0.85, 1.15);
        brush.set(bName, col, wgt);

        // Pass 0 follows fold contours; Pass 1 follows diagonal linen weave cross-hatching
        const baseAng = pass === 0
          ? s.contourAng + random(-10, 10)
          : s.contourAng + 32 + random(-8, 8);
        const rad = baseAng * (Math.PI / 180);
        const len = map(s.light, 0, 1, 30, 18) * random(0.8, 1.25);
        const dx = Math.cos(rad) * len * 0.5;
        const dy = Math.sin(rad) * len * 0.5;
        brush.line(jx - dx, jy - dy, jx + dx, jy + dy);
      }
    }
  }

  // 5D. Crisp Linen Tension Crease Highlights & Subtle Shadow Edges on the Sheets
  for (let i = 0; i < sheetCreases.length; i++) {
    const [x1, y1, x2, y2, amp, w, crv] = sheetCreases[i];
    const dist = Math.hypot(x2 - x1, y2 - y1);
    const steps = Math.floor(dist / 14);
    const dx = (x2 - x1) / dist;
    const dy = (y2 - y1) / dist;
    const nx = -dy;
    const ny = dx;

    for (let k = 1; k < steps; k++) {
      const t = k / steps;
      const env = Math.sin(t * Math.PI);
      if (env < 0.15) continue;
      const cOff = crv * 4.0 * t * (1.0 - t);
      const cx = x1 + t * (x2 - x1) - nx * cOff;
      const cy = y1 + t * (y2 - y1) - ny * cOff;
      if (cx < -20 || cx > width + 20 || cy < -20 || cy > height + 20) continue;

      const s = sampleSheet(cx, cy);
      if (s.tieId > 0) continue; // Under the tie

      // Sunlit crest of the sheet crease
      if (s.light > 0.52) {
        brush.set("razor_crease", "#ffffff", 0.85 * env);
        const l = random(16, 28);
        brush.line(
          cx - dx * l * 0.5 + random(-1.5, 1.5),
          cy - dy * l * 0.5 + random(-1.5, 1.5),
          cx + dx * l * 0.5 + random(-1.5, 1.5),
          cy + dy * l * 0.5 + random(-1.5, 1.5)
        );
      }
      // Subtle cool-grey shadow edge along the leeward side of the linen crease
      const sx = cx + nx * (w * 0.28);
      const sy = cy + ny * (w * 0.28);
      const sShadow = sampleSheet(sx, sy);
      const scIdx = constrain(Math.floor(sShadow.light * 9.5), 1, 8);
      brush.set("2H", sheetGreyPalette[scIdx], 0.62 * env);
      const sl = random(18, 32);
      brush.line(sx - dx * sl * 0.5, sy - dy * sl * 0.5, sx + dx * sl * 0.5, sy + dy * sl * 0.5);
    }
  }

  // ---------------------------------------------------------------------------
  // 6. VIRIDIAN DUCHESS SILK SHADER & PALETTE
  // ---------------------------------------------------------------------------
  // 14-stop hyperrealistic Viridian Coloured-Pencil Palette:
  // Deepest bottle-black-green -> rich bottle green -> jewel viridian -> ice-mint -> pure white
  const silkPalette = [
    "#02110d", // 0: Abyssal bottle-black crevice
    "#041c16", // 1: Deepest bottle green
    "#062820", // 2: Dark bottle green shadow
    "#09362b", // 3: Rich bottle green
    "#0d4739", // 4: Deep viridian core
    "#115948", // 5: Dark viridian satin
    "#166d58", // 6: Classic viridian midtone
    "#1d846b", // 7: Luminous viridian
    "#279c80", // 8: Jewel emerald-viridian
    "#3cb597", // 9: Bright viridian sheen
    "#60cfa8", // 10: Celadon-mint glint
    "#92e6ca", // 11: Ice-mint ridge glow
    "#cdf7e8", // 12: Specular mint-white flash
    "#ffffff"  // 13: Blinding white ridge catchlight
  ];

  // Compute exact 3D surface normal and silk illumination at (s, u) on a ribbon
  function shadeSilkPoint(evalFn, s, u, isRibbonA) {
    const epsS = 0.0022;
    const epsU = 0.025;
    const pC = evalFn(s, u);
    const pS = evalFn(Math.min(1, s + epsS), u);
    const pU = evalFn(s, Math.min(1, u + epsU));

    // World-space tangent vectors along s and u
    const dxs = pS.x - pC.x, dys = pS.y - pC.y, dzs = pS.z - pC.z;
    const dxu = pU.x - pC.x, dyu = pU.y - pC.y, dzu = pU.z - pC.z;

    // Cross product for true 3D surface normal of the silk facet
    let nx = dys * dzu - dzs * dyu;
    let ny = dzs * dxu - dxs * dzu;
    let nz = dxs * dyu - dys * dxu;
    if (nz < 0) { nx = -nx; ny = -ny; nz = -nz; }
    const nlen = Math.hypot(nx, ny, nz) || 1;
    nx /= nlen; ny /= nlen; nz /= nlen;

    // Diffuse & anisotropic satin specular under raking morning light
    const ndotl = Math.max(0, nx * Lx + ny * Ly + nz * Lz);
    const ndoth = Math.max(0, nx * Hx + ny * Hy + nz * Hz);

    const diff = Math.pow(ndotl, 0.85);
    const satinSpec = Math.pow(ndoth, 14) * 0.48 + Math.pow(ndoth, 52) * 0.65;

    // Rolled edge rim lighting:
    // u -> -1 faces upper-left into the raking morning light!
    // u -> +1 faces lower-right into shadow (with faint reflected bounce from white sheet)
    let edgeRim = 0;
    if (u < -0.72) {
      edgeRim = 0.42 * Math.exp(-Math.pow((u + 0.90) / 0.09, 2)) * (0.4 + 0.6 * ndotl);
    } else if (u > 0.72) {
      edgeRim = -0.22 * Math.exp(-Math.pow((u - 0.82) / 0.12, 2)) +
                 0.12 * Math.exp(-Math.pow((u - 0.96) / 0.05, 2)); // sheet bounce on very bottom rim
    }

    // Cast shadow from Ribbon B onto Ribbon A around the center crossing (s in [0.43, 0.66])
    let crossShadow = 0;
    if (isRibbonA) {
      // Check distance to Ribbon B's crossing segment (sB around 0.50)
      const dCross = Math.abs(s - 0.535);
      if (dCross < 0.16) {
        crossShadow = 0.88 * Math.exp(-Math.pow((s - 0.538) / 0.078, 2));
      }
    }

    // Combine diffuse, specular, sharp crease ridge flash & deep crease valley traps
    const ridgeFlash = pC.ridge * (0.34 + 0.48 * ndotl) * (1.0 - crossShadow * 0.85);
    const valleyTrap = pC.valley * 0.32;

    let lum = (diff * 0.62 + satinSpec + ridgeFlash + edgeRim - valleyTrap) * (1.0 - crossShadow);
    // Boost contrast so creases flash from deep bottle green to almost white
    lum = constrain(lum, 0.0, 1.0);
    lum = Math.pow(lum, 0.92);

    const palIdx = constrain(Math.floor(lum * (silkPalette.length - 0.01)), 0, silkPalette.length - 1);
    return {
      x: pC.x,
      y: pC.y,
      z: pC.z,
      tx: pC.tx,
      ty: pC.ty,
      nx: pC.nx,
      ny: pC.ny,
      lum,
      ridge: pC.ridge,
      valley: pC.valley,
      crossShadow,
      col: silkPalette[palIdx],
      palIdx
    };
  }

  // ---------------------------------------------------------------------------
  // 7. HELPER TO RENDER A COMPLETE BURNISHED SILK RIBBON
  // ---------------------------------------------------------------------------
  function renderSilkRibbon(evalFn, creasesArr, isRibbonA) {
    const stepsS = isRibbonA ? 140 : 190;
    const stepsU = isRibbonA ? 22 : 32;

    // 7A. Crisp Contact Shadow Directly Under the Silk Edges on the Sheet
    for (let is = 0; is <= stepsS; is++) {
      const s = is / stepsS;
      const pLeft = evalFn(s, -0.98);
      const pRight = evalFn(s, 0.98);

      // Shadow side (lower-right edge u = +1) casts an immediate dark contact line
      brush.set("2B", "#1d262f", isRibbonA ? 0.85 : 1.05);
      brush.line(
        pRight.x + 1.5, pRight.y + 1.5,
        pRight.x - Lx * 8, pRight.y - Ly * 8
      );
      // Slight occlusion line under the upper-left rolled edge
      brush.set("HB", "#3b4654", 0.65);
      brush.line(
        pLeft.x + 1.2, pLeft.y + 1.2,
        pLeft.x + 3.5, pLeft.y + 2.5
      );
    }

    // 7B. Base Lacquered Undertone Wash (Batched by Silk Palette Stop)
    // Ensures 100% optical pigment saturation with zero raw paper gaps inside the silk
    const washBuckets = Array.from({ length: silkPalette.length }, () => []);
    for (let is = 0; is < stepsS; is++) {
      const s0 = is / stepsS;
      const s1 = (is + 1) / stepsS;
      const sMid = 0.5 * (s0 + s1);
      for (let iu = 0; iu < stepsU; iu++) {
        const u0 = -1 + (2 * iu) / stepsU;
        const u1 = -1 + (2 * (iu + 1)) / stepsU;
        const uMid = 0.5 * (u0 + u1);

        const sh = shadeSilkPoint(evalFn, sMid, uMid, isRibbonA);
        const p00 = evalFn(s0, u0);
        const p10 = evalFn(s1, u0);
        const p11 = evalFn(s1, u1);
        const p01 = evalFn(s0, u1);
        washBuckets[sh.palIdx].push([p00, p10, p11, p01]);
      }
    }

    brush.noStroke();
    brush.noHatch();
    for (let b = 0; b < silkPalette.length; b++) {
      const quads = washBuckets[b];
      if (quads.length === 0) continue;
      brush.wash(silkPalette[b], 235);
      for (let i = 0; i < quads.length; i++) {
        const [p00, p10, p11, p01] = quads[i];
        const cx = 0.25 * (p00.x + p10.x + p11.x + p01.x);
        const cy = 0.25 * (p00.y + p10.y + p11.y + p01.y);
        // Slightly expand each micro-quad by 1.8px so adjacent facets fuse into a continuous lacquer
        brush.beginShape(0);
        brush.vertex(p00.x + (p00.x - cx) * 0.28, p00.y + (p00.y - cy) * 0.28);
        brush.vertex(p10.x + (p10.x - cx) * 0.28, p10.y + (p10.y - cy) * 0.28);
        brush.vertex(p11.x + (p11.x - cx) * 0.28, p11.y + (p11.y - cy) * 0.28);
        brush.vertex(p01.x + (p01.x - cx) * 0.28, p01.y + (p01.y - cy) * 0.28);
        brush.endShape(true);
      }
    }
    brush.noWash();

    // 7C. Burnished Coloured Pencil Pass 1: Cross-Contour Satin Strokes (along u)
    const crossStepsS = isRibbonA ? 220 : 310;
    const crossStepsU = isRibbonA ? 14 : 22;
    for (let is = 0; is <= crossStepsS; is++) {
      const s = constrain(is / crossStepsS + random(-0.002, 0.002), 0.003, 0.997);
      for (let iu = 0; iu < crossStepsU; iu++) {
        const uA = constrain(-0.96 + (1.92 * iu) / crossStepsU + random(-0.03, 0.03), -0.98, 0.92);
        const uB = constrain(uA + 1.92 / crossStepsU * random(1.15, 1.55), -0.92, 0.98);
        const uMid = 0.5 * (uA + uB);

        const sh = shadeSilkPoint(evalFn, s, uMid, isRibbonA);
        const pA = evalFn(s, uA);
        const pB = evalFn(s, uB);

        const wgt = map(sh.lum, 0, 1, 1.15, 0.78) * random(0.85, 1.15);
        brush.set("burnish", sh.col, wgt);
        brush.line(pA.x, pA.y, pB.x, pB.y);
      }
    }

    // 7D. Burnished Coloured Pencil Pass 2: Longitudinal Bias & Weft Sheen (along s)
    // Creates the fine woven duchess silk grain and optical colour mixing
    const longStepsS = isRibbonA ? 130 : 185;
    const longStepsU = isRibbonA ? 26 : 38;
    for (let iu = 0; iu <= longStepsU; iu++) {
      const u = constrain(-0.95 + (1.90 * iu) / longStepsU + random(-0.015, 0.015), -0.97, 0.97);
      for (let is = 0; is < longStepsS; is++) {
        const sA = constrain(is / longStepsS + random(-0.003, 0.003), 0.002, 0.985);
        const sB = constrain(sA + (1.0 / longStepsS) * random(1.2, 1.65), 0.008, 0.998);
        const sMid = 0.5 * (sA + sB);

        const sh = shadeSilkPoint(evalFn, sMid, u, isRibbonA);
        const pA = evalFn(sA, u);
        const pB = evalFn(sB, u);

        // Shift palette index slightly by +-1 for authentic multi-layered coloured pencil burnishing
        const jitterIdx = constrain(sh.palIdx + (random() < 0.45 ? (random() < 0.5 ? -1 : 1) : 0), 0, silkPalette.length - 1);
        const bName = sh.lum > 0.75 || sh.lum < 0.25 ? "burnish" : "cpencil";
        const wgt = map(sh.lum, 0, 1, 0.95, 0.65) * random(0.85, 1.15);
        brush.set(bName, silkPalette[jitterIdx], wgt);
        brush.line(pA.x, pA.y, pB.x, pB.y);
      }
    }

    // 7E. Underside Back-Seam & Slip-Stitch Detail on Ribbon A (s in [0.15, 0.44])
    if (isRibbonA) {
      const seamSteps = 75;
      for (let i = 0; i < seamSteps; i++) {
        const sA = map(i, 0, seamSteps, 0.14, 0.44);
        const sB = map(i + 1.3, 0, seamSteps, 0.14, 0.44);
        const env = Math.sin(((i / seamSteps)) * Math.PI);

        // Dark recessed center seam line
        const p0 = evalFn(sA, 0.06);
        const p1 = evalFn(sB, 0.06);
        brush.set("razor_crease", "#02110d", 1.15 * env);
        brush.line(p0.x, p0.y, p1.x, p1.y);

        // Bright mint-white rolled lip of the center seam facing the light
        const pL0 = evalFn(sA, -0.04);
        const pL1 = evalFn(sB, -0.04);
        const shL = shadeSilkPoint(evalFn, sA, -0.04, true);
        const lipCol = shL.lum > 0.45 ? "#cdf7e8" : "#60cfa8";
        brush.set("razor_crease", lipCol, 0.85 * env);
        brush.line(pL0.x, pL0.y, pL1.x, pL1.y);

        // Tiny slip-stitch dimples every few steps
        if (i % 5 === 2 && env > 0.35) {
          const pStA = evalFn(sA, 0.03);
          const pStB = evalFn(sA + 0.003, 0.10);
          brush.set("razor_crease", "#02110d", 0.95);
          brush.line(pStA.x, pStA.y, pStB.x, pStB.y);
        }
      }
    }

    // 7F. Razor-Sharp Crease Flashes & Deep Bottle-Green Crease Shadows
    // "Crushed into sharp creases that flash from deep bottle green to almost white along every ridge"
    for (let ic = 0; ic < creasesArr.length; ic++) {
      const [sc, slp, crv, amp, ws] = creasesArr[ic];
      const uSamples = 28;
      for (let iu = 0; iu < uSamples; iu++) {
        const u0 = -0.94 + (1.88 * iu) / uSamples;
        const u1 = -0.94 + (1.88 * (iu + 1)) / uSamples;
        const uMid = 0.5 * (u0 + u1);

        // Exact locus of the sharp crease crest: d = (s - sc) + slp*u + crv*(u^2 - c0) = 0
        const cOffset = isRibbonA ? 0.3 : 0.35;
        const sCrest0 = sc - slp * u0 - crv * (u0 * u0 - cOffset);
        const sCrest1 = sc - slp * u1 - crv * (u1 * u1 - cOffset);
        const sCrestMid = 0.5 * (sCrest0 + sCrest1);
        if (sCrestMid <= 0.01 || sCrestMid >= 0.98) continue;

        const shCrest = shadeSilkPoint(evalFn, sCrestMid, uMid, isRibbonA);
        if (shCrest.crossShadow > 0.65) continue; // Inside deep overlap cast shadow

        const edgeFade = Math.sin(((iu + 0.5) / uSamples) * Math.PI);
        const pC0 = evalFn(sCrest0, u0);
        const pC1 = evalFn(sCrest1, u1);

        // 1. Deep bottle-green shadow immediately on the leeward (down-right) side of the crease ridge
        const sLee0 = sCrest0 + ws * 0.85;
        const sLee1 = sCrest1 + ws * 0.85;
        const pL0 = evalFn(sLee0, u0);
        const pL1 = evalFn(sLee1, u1);
        brush.set("burnish", "#02110d", 1.15 * edgeFade * (amp / 15.0));
        brush.line(pL0.x, pL0.y, pL1.x, pL1.y);

        const sLeeB0 = sCrest0 + ws * 1.45;
        const sLeeB1 = sCrest1 + ws * 1.45;
        const pLB0 = evalFn(sLeeB0, u0);
        const pLB1 = evalFn(sLeeB1, u1);
        brush.set("burnish", "#062820", 1.0 * edgeFade * (amp / 15.0));
        brush.line(pLB0.x, pLB0.y, pLB1.x, pLB1.y);

        // 2. Luminous ice-mint transition glow flanking the ridge crest
        const sGlow0 = sCrest0 - ws * 0.42;
        const sGlow1 = sCrest1 - ws * 0.42;
        const pG0 = evalFn(sGlow0, u0);
        const pG1 = evalFn(sGlow1, u1);
        brush.set("burnish", "#60cfa8", 0.95 * edgeFade * (amp / 15.0));
        brush.line(pG0.x, pG0.y, pG1.x, pG1.y);

        brush.set("razor_crease", "#92e6ca", 0.9 * edgeFade * (amp / 15.0));
        brush.line(
          0.5 * (pG0.x + pC0.x), 0.5 * (pG0.y + pC0.y),
          0.5 * (pG1.x + pC1.x), 0.5 * (pG1.y + pC1.y)
        );

        // 3. Blinding specular white / mint-white flash right along the sharp ridge crest
        const flashCol = shCrest.lum > 0.55 && edgeFade > 0.25 ? "#ffffff" : "#cdf7e8";
        brush.set("razor_crease", flashCol, 1.05 * edgeFade * (amp / 14.5));
        brush.line(pC0.x, pC0.y, pC1.x, pC1.y);
      }
    }

    // 7G. Secondary Chevron, Knot-Dimple & Fan Crease Ridge Flashes (Ribbon B)
    if (!isRibbonA) {
      // Trace the longitudinal knot dimple ridges (u = -0.42 and u = +0.42 in s in [0.06, 0.42])
      const dimpleSteps = 70;
      for (let i = 0; i < dimpleSteps; i++) {
        const s0 = map(i, 0, dimpleSteps, 0.05, 0.42);
        const s1 = map(i + 1, 0, dimpleSteps, 0.05, 0.42);
        const env = Math.sin((i / dimpleSteps) * Math.PI);

        // Deep bottle-black-green central dimple trough (u = 0)
        const pT0 = evalFn(s0, 0.0);
        const pT1 = evalFn(s1, 0.0);
        brush.set("burnish", "#02110d", 1.2 * env);
        brush.line(pT0.x, pT0.y, pT1.x, pT1.y);

        // Left & right longitudinal dimple crests
        for (const uCrest of [-0.42, 0.42]) {
          const shD = shadeSilkPoint(evalFn, s0, uCrest, false);
          const pD0 = evalFn(s0, uCrest);
          const pD1 = evalFn(s1, uCrest);
          const cD = shD.lum > 0.68 ? "#ffffff" : (shD.lum > 0.48 ? "#cdf7e8" : "#60cfa8");
          brush.set("razor_crease", cD, 0.92 * env);
          brush.line(pD0.x, pD0.y, pD1.x, pD1.y);
        }
      }

      // High-density micro-ridge scan across the entire silk surface to catch every diamond buckle
      for (let is = 6; is < 240; is++) {
        const s = is / 240;
        for (let iu = 2; iu < 30; iu++) {
          const u = -1 + (2 * iu) / 32;
          const sh = shadeSilkPoint(evalFn, s, u, false);
          if (sh.ridge > 0.78 && sh.lum > 0.62) {
            const pA = evalFn(s - 0.003, u - 0.035);
            const pB = evalFn(s + 0.003, u + 0.035);
            const c = sh.lum > 0.82 && sh.ridge > 1.05 ? "#ffffff" : "#cdf7e8";
            brush.set("razor_crease", c, map(sh.ridge, 0.78, 1.8, 0.55, 1.1));
            brush.line(pA.x, pA.y, pB.x, pB.y);
          } else if (sh.valley > 0.65 && sh.lum < 0.28) {
            const pA = evalFn(s - 0.003, u - 0.035);
            const pB = evalFn(s + 0.003, u + 0.035);
            brush.set("razor_crease", "#02110d", 0.85);
            brush.line(pA.x, pA.y, pB.x, pB.y);
          }
        }
      }
    }

    // 7H. Rolled Silk Edge Highlights & Shadow Core Contours
    const edgeSteps = isRibbonA ? 180 : 250;
    for (let i = 0; i < edgeSteps; i++) {
      const s0 = i / edgeSteps;
      const s1 = (i + 1) / edgeSteps;
      const sMid = 0.5 * (s0 + s1);

      // Sunlit upper-left rolled silk edge (u = -0.92 & -0.98)
      const shLeft = shadeSilkPoint(evalFn, sMid, -0.91, isRibbonA);
      if (shLeft.crossShadow < 0.6) {
        const pL0 = evalFn(s0, -0.92);
        const pL1 = evalFn(s1, -0.92);
        const rimCol = shLeft.lum > 0.55 || shLeft.ridge > 0.6 ? "#ffffff" : "#92e6ca";
        brush.set("razor_crease", rimCol, map(shLeft.lum, 0, 1, 0.65, 1.15));
        brush.line(pL0.x, pL0.y, pL1.x, pL1.y);

        // Outer hair-thin viridian-mint edge seal
        const pOut0 = evalFn(s0, -0.98);
        const pOut1 = evalFn(s1, -0.98);
        brush.set("razor_crease", "#279c80", 0.65);
        brush.line(pOut0.x, pOut0.y, pOut1.x, pOut1.y);
      }

      // Shadowed lower-right rolled silk edge (core shadow at u = 0.86, faint sheet bounce at u = 0.97)
      const pCore0 = evalFn(s0, 0.86);
      const pCore1 = evalFn(s1, 0.86);
      brush.set("burnish", "#02110d", 0.95);
      brush.line(pCore0.x, pCore0.y, pCore1.x, pCore1.y);

      const pRef0 = evalFn(s0, 0.97);
      const pRef1 = evalFn(s1, 0.97);
      const shRight = shadeSilkPoint(evalFn, sMid, 0.97, isRibbonA);
      const bounceEdgeCol = shRight.crossShadow > 0.5 ? "#041c16" : "#166d58";
      brush.set("razor_crease", bounceEdgeCol, 0.68);
      brush.line(pRef0.x, pRef0.y, pRef1.x, pRef1.y);
    }
  }

  // ---------------------------------------------------------------------------
  // 8. EXECUTE SILK RENDERING IN PHYSICAL DEPTH ORDER
  // ---------------------------------------------------------------------------
  // First: Ribbon A (the narrow tail and unknotted loop lying underneath)
  renderSilkRibbon(evalRibbonA, creasesA, true);

  // Soft cast shadow transition thrown by Ribbon B directly across Ribbon A at the overlap
  for (let i = 0; i < 65; i++) {
    const sB = map(i, 0, 64, 0.42, 0.59);
    const pEdge = evalRibbonB(sB, 0.98);
    brush.set("stump_blend", "#02110d", 1.15);
    brush.line(
      pEdge.x + 2, pEdge.y + 2,
      pEdge.x - Lx * 22 + random(-3, 3), pEdge.y - Ly * 22 + random(-3, 3)
    );
  }

  // Second: Ribbon B (the hero crushed knot zone & wide blade arching over Ribbon A)
  renderSilkRibbon(evalRibbonB, creasesB, false);

  // ---------------------------------------------------------------------------
  // 9. FINAL HYPERREALIST FINISHING DETAILS (MICRO-SHEEN & POINTED TIPS)
  // ---------------------------------------------------------------------------
  // Crisp highlight & folded hem detail at the wide blade's pointed diamond tip (s in [0.855, 1.0])
  for (let i = 0; i < 45; i++) {
    const s0 = map(i, 0, 45, 0.855, 0.996);
    const s1 = map(i + 1, 0, 45, 0.855, 0.996);
    const pTipL0 = evalRibbonB(s0, -0.94);
    const pTipL1 = evalRibbonB(s1, -0.94);
    brush.set("razor_crease", "#ffffff", 1.05);
    brush.line(pTipL0.x, pTipL0.y, pTipL1.x, pTipL1.y);

    // Subtle folded hem crease parallel to the diamond tip edges
    const pHem0 = evalRibbonB(s0, -0.78);
    const pHem1 = evalRibbonB(s1, -0.78);
    brush.set("razor_crease", "#09362b", 0.65);
    brush.line(pHem0.x, pHem0.y, pHem1.x, pHem1.y);
  }

  noLoop();
}

