// ===========================================================================
// GEOMETRY & CLIPPING HELPERS
// ===========================================================================

function signedLineDist(pt, line) {
  const [x1, y1, x2, y2] = line;
  return (x2 - x1) * (pt[1] - y1) - (y2 - y1) * (pt[0] - x1);
}

function clipPolyToHalfPlane(poly, line, keepSign) {
  if (!poly || poly.length < 3) return [];
  const out = [];
  const [x1, y1, x2, y2] = line;
  const dx = x2 - x1;
  const dy = y2 - y1;

  for (let i = 0; i < poly.length; i++) {
    const cur = poly[i];
    const prev = poly[(i + poly.length - 1) % poly.length];
    const dCur = (dx * (cur[1] - y1) - dy * (cur[0] - x1)) * keepSign;
    const dPrev = (dx * (prev[1] - y1) - dy * (prev[0] - x1)) * keepSign;

    if (dCur >= 0) {
      if (dPrev < 0) {
        const t = dPrev / (dPrev - dCur);
        out.push([prev[0] + t * (cur[0] - prev[0]), prev[1] + t * (cur[1] - prev[1])]);
      }
      out.push(cur);
    } else if (dPrev >= 0) {
      const t = dPrev / (dPrev - dCur);
      out.push([prev[0] + t * (cur[0] - prev[0]), prev[1] + t * (cur[1] - prev[1])]);
    }
  }
  return out;
}

function clipToCanvas(poly) {
  let p = clipPolyToHalfPlane(poly, [-20, -20, 1220, -20], 1);
  p = clipPolyToHalfPlane(p, [1220, -20, 1220, 1220], 1);
  p = clipPolyToHalfPlane(p, [1220, 1220, -20, 1220], 1);
  p = clipPolyToHalfPlane(p, [-20, 1220, -20, -20], 1);
  return p;
}

function makeCirclePoly(cx, cy, r, n = 14) {
  const pts = [];
  for (let i = 0; i < n; i++) {
    const a = (i / n) * Math.PI * 2;
    const wob = 1 + ( noise(cx * 0.05 + i, cy * 0.05) - 0.5 ) * 0.12;
    pts.push([cx + Math.cos(a) * r * wob, cy + Math.sin(a) * r * wob]);
  }
  return pts;
}

function makeLeafPoly(cx, cy, len, wid, angleDeg) {
  const rad = angleDeg * Math.PI / 180;
  const ca = Math.cos(rad), sa = Math.sin(rad);
  const local = [
    [-len * 0.5, 0],
    [-len * 0.18, -wid * 0.46],
    [len * 0.2, -wid * 0.42],
    [len * 0.5, 0],
    [len * 0.2, wid * 0.42],
    [-len * 0.18, wid * 0.46]
  ];
  return local.map(([lx, ly]) => [cx + lx * ca - ly * sa, cy + lx * sa + ly * ca]);
}

function makeTiltedRectPoly(cx, cy, w, h, angleDeg) {
  const rad = angleDeg * Math.PI / 180;
  const ca = Math.cos(rad), sa = Math.sin(rad);
  const hw = w * 0.5, hh = h * 0.5;
  const local = [[-hw, -hh], [hw, -hh], [hw, hh], [-hw, hh]];
  return local.map(([lx, ly]) => [cx + lx * ca - ly * sa, cy + lx * sa + ly * ca]);
}

function drawFlatMattePoly(poly, col, hatchAngle = 0, doMarkerPass = true) {
  if (!poly || poly.length < 3) return;
  brush.noFill();
  brush.noStroke();
  brush.noMass();
  brush.wash(col, 248);

  if (doMarkerPass) {
    brush.hatchStyle("flat_marker", col, 0.75);
    brush.hatch(14, hatchAngle, { rand: 0.02, continuous: true });
  } else {
    brush.noHatch();
  }

  brush.beginShape(0);
  for (let i = 0; i < poly.length; i++) {
    brush.vertex(poly[i][0], poly[i][1]);
  }
  brush.endShape(true);

  brush.noHatch();
  brush.noWash();
}

function drawBatchMattePolys(polys, col, hatchAngle = 0, doMarkerPass = true) {
  if (!polys || polys.length === 0) return;
  for (let i = 0; i < polys.length; i++) {
    drawFlatMattePoly(polys[i], col, hatchAngle, doMarkerPass);
  }
}

// ===========================================================================
// 1. NABIS WALLPAPER & QUILT RENDERERS
// ===========================================================================

function clipToWallpaper(poly) {
  return clipToCanvas(clipPolyToHalfPlane(poly, LINE_WP, -1));
}

function clipToMainQuilt(poly) {
  let p = clipPolyToHalfPlane(poly, LINE_WP, 1);
  p = clipPolyToHalfPlane(p, LINE_QUILT_LL, -1);
  p = clipPolyToHalfPlane(p, LINE_QUILT_LR, -1);
  return clipToCanvas(p);
}

function clipToLLQuilt(poly) {
  let p = clipPolyToHalfPlane(poly, LINE_WP, 1);
  p = clipPolyToHalfPlane(p, LINE_QUILT_LL, 1);
  return clipToCanvas(p);
}

function clipToLRQuilt(poly) {
  let p = clipPolyToHalfPlane(poly, LINE_WP, 1);
  p = clipPolyToHalfPlane(p, LINE_QUILT_LR, 1);
  p = clipPolyToHalfPlane(p, LINE_QUILT_LL, -1);
  return clipToCanvas(p);
}

function drawNabisWallpaper() {
  // Base matte ground for wallpaper
  const wpBase = clipToWallpaper([[-20, -20], [1220, -20], [1220, 600], [-20, 600]]);
  drawFlatMattePoly(wpBase, PAL.wpGround, 87, true);

  // Wallpaper presses forward with NO perspective at all (nearly vertical -3 deg stripes)
  const wpTilt = -3;
  const stripePolys1 = [];
  const stripePolys2 = [];
  const rosetteTerra = [];
  const rosetteOchre = [];
  const rosetteCream = [];
  const rosettePlum = [];

  for (let gx = -80; gx <= 1280; gx += 92) {
    // Vertical stripe pair
    const s1 = clipToWallpaper(makeTiltedRectPoly(gx, 250, 22, 650, wpTilt));
    const s2 = clipToWallpaper(makeTiltedRectPoly(gx + 26, 250, 10, 650, wpTilt));
    if (s1.length >= 3) stripePolys1.push(s1);
    if (s2.length >= 3) stripePolys2.push(s2);

    // Between stripes: flat Nabis floral medallions / lozenges
    const colIdx = Math.round((gx + 80) / 92);
    for (let gy = -40; gy <= 560; gy += 86) {
      const rowIdx = Math.round((gy + 40) / 86);
      const staggerY = gy + (colIdx % 2 === 0 ? 0 : 43);
      const rx = gx + 58 + (staggerY - 250) * Math.sin(wpTilt * Math.PI / 180);
      const ry = staggerY;

      // Diamond / lozenge backing block
      const loz = clipToWallpaper(makeTiltedRectPoly(rx, ry, 36, 36, 45 + wpTilt));
      if (loz.length >= 3) {
        if ((colIdx + rowIdx) % 2 === 0) rosetteTerra.push(loz);
        else rosettePlum.push(loz);
      }

      // 4 flat Nabis petals around center
      const pOffsets = [[0, -14], [14, 0], [0, 14], [-14, 0]];
      for (let [ox, oy] of pOffsets) {
        const pet = clipToWallpaper(makeCirclePoly(rx + ox, ry + oy, 7.5, 10));
        if (pet.length >= 3) rosetteCream.push(pet);
      }
      // Flat center disc
      const ctr = clipToWallpaper(makeCirclePoly(rx, ry, 7, 10));
      if (ctr.length >= 3) rosetteOchre.push(ctr);
    }
  }

  drawBatchMattePolys(stripePolys1, PAL.wpStripe1, 87, true);
  drawBatchMattePolys(stripePolys2, PAL.wpStripe2, 87, false);
  drawBatchMattePolys(rosetteTerra, PAL.wpTerra, 42, true);
  drawBatchMattePolys(rosettePlum, PAL.wpPlum, -45, true);
  drawBatchMattePolys(rosetteCream, PAL.wpCream, 0, false);
  drawBatchMattePolys(rosetteOchre, PAL.wpOchre, 0, false);
}

function drawNabisMainQuilt() {
  // Tilted grid of flat ochre checks (-15.5 deg)
  const qAngle = -15.5;
  const rad = qAngle * Math.PI / 180;
  const ca = Math.cos(rad), sa = Math.sin(rad);
  const cell = 76;

  const checks1 = [], checks2 = [], checks3 = [], checks4 = [];
  const plumDots1 = [], plumDots2 = [], plumDots3 = [];
  const oliveLeaves1 = [], oliveLeaves2 = [], oliveLeaves3 = [];
  const sprigStems = [];

  for (let i = -8; i <= 18; i++) {
    for (let j = -4; j <= 18; j++) {
      const lx = i * cell;
      const ly = j * cell;
      const cx = 400 + lx * ca - ly * sa;
      const cy = 500 + lx * sa + ly * ca;

      if (cx < -120 || cx > 1320 || cy < 120 || cy > 1320) continue;

      const sq = clipToMainQuilt(makeTiltedRectPoly(cx, cy, cell + 1.5, cell + 1.5, qAngle));
      if (sq.length < 3) continue;

      const parity = ((i % 2) + 2) % 2;
      const parityJ = ((j % 2) + 2) % 2;
      if (parity === 0 && parityJ === 0) checks1.push(sq);
      else if (parity === 1 && parityJ === 0) checks2.push(sq);
      else if (parity === 0 && parityJ === 1) checks3.push(sq);
      else checks4.push(sq);

      // Inside alternating checks: flat Nabis Plum Dots OR Olive Sprigs
      const motifType = (((i * 3 + j * 5) % 4) + 4) % 4;

      if (motifType === 0) {
        // Bold flat plum quincunx (5 dots)
        const dCenter = clipToMainQuilt(makeCirclePoly(cx, cy, 13.5, 12));
        if (dCenter.length >= 3) plumDots1.push(dCenter);
        const offs = [[-19, -19], [19, -19], [-19, 19], [19, 19]];
        for (let [ox, oy] of offs) {
          const dx = cx + ox * ca - oy * sa;
          const dy = cy + ox * sa + oy * ca;
          const dSmall = clipToMainQuilt(makeCirclePoly(dx, dy, 6.8, 10));
          if (dSmall.length >= 3) plumDots2.push(dSmall);
        }
      } else if (motifType === 1) {
        // Single large flat plum medallion dot with small dark core
        const dBig = clipToMainQuilt(makeCirclePoly(cx, cy, 18, 14));
        const dCore = clipToMainQuilt(makeCirclePoly(cx, cy, 7.5, 10));
        if (dBig.length >= 3) plumDots2.push(dBig);
        if (dCore.length >= 3) plumDots3.push(dCore);
      } else if (motifType === 2) {
        // Flat Nabis Olive Sprig inside the ochre check
        const sprigAng = qAngle + ((i + j) % 2 === 0 ? 32 : -38);
        addSprigToBatches(
          cx, cy, sprigAng, 1.0,
          clipToMainQuilt,
          oliveLeaves1, oliveLeaves2, oliveLeaves3, plumDots1, sprigStems
        );
      } else {
        // Clustered 3 plum dots + 2 olive leaves
        const d1 = clipToMainQuilt(makeCirclePoly(cx - 10, cy - 6, 9.5, 11));
        const d2 = clipToMainQuilt(makeCirclePoly(cx + 12, cy + 4, 8.5, 11));
        const d3 = clipToMainQuilt(makeCirclePoly(cx - 2, cy + 14, 7.5, 11));
        if (d1.length >= 3) plumDots1.push(d1);
        if (d2.length >= 3) plumDots3.push(d2);
        if (d3.length >= 3) plumDots2.push(d3);

        const lf1 = clipToMainQuilt(makeLeafPoly(cx + 8, cy - 12, 24, 11, qAngle - 25));
        const lf2 = clipToMainQuilt(makeLeafPoly(cx - 15, cy + 8, 22, 10, qAngle + 145));
        if (lf1.length >= 3) oliveLeaves1.push(lf1);
        if (lf2.length >= 3) oliveLeaves2.push(lf2);
      }
    }
  }

  // Draw batched ochre checks
  drawBatchMattePolys(checks1, PAL.ochre1, qAngle, true);
  drawBatchMattePolys(checks2, PAL.ochre2, qAngle + 90, true);
  drawBatchMattePolys(checks3, PAL.ochre3, qAngle, true);
  drawBatchMattePolys(checks4, PAL.ochre4, qAngle + 90, true);

  // Draw batched olive sprigs & plum dots
  drawBatchMattePolys(oliveLeaves1, PAL.olive1, qAngle + 30, true);
  drawBatchMattePolys(oliveLeaves2, PAL.olive2, qAngle - 30, false);
  drawBatchMattePolys(oliveLeaves3, PAL.olive3, qAngle, false);

  // Flat marker stems
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set("flat_marker", PAL.olive3, 0.36);
  for (let st of sprigStems) {
    brush.line(st[0], st[1], st[2], st[3]);
  }

  drawBatchMattePolys(plumDots1, PAL.plum1, qAngle, true);
  drawBatchMattePolys(plumDots2, PAL.plum2, qAngle + 45, false);
  drawBatchMattePolys(plumDots3, PAL.plum3, 0, false);
}

function addSprigToBatches(cx, cy, angDeg, scale, clipFn, leaves1, leaves2, leaves3, berries, stems) {
  const rad = angDeg * Math.PI / 180;
  const ca = Math.cos(rad), sa = Math.sin(rad);
  const s = scale;

  // Stem endpoints (only add if midpoint is inside clip region)
  const midCheck = clipFn(makeCirclePoly(cx, cy, 3, 6));
  if (midCheck.length >= 3) {
    stems.push([
      cx - 24 * s * ca, cy - 24 * s * sa,
      cx + 24 * s * ca, cy + 24 * s * sa
    ]);
  }

  // Terminal leaf
  const tipLeaf = clipFn(makeLeafPoly(cx + 22 * s * ca, cy + 22 * s * sa, 24 * s, 11 * s, angDeg));
  if (tipLeaf.length >= 3) leaves1.push(tipLeaf);

  // Paired side leaves
  const pairs = [
    [-10 * s, -12 * s, -48, leaves1],
    [-10 * s,  12 * s,  48, leaves2],
    [  6 * s, -11 * s, -42, leaves2],
    [  6 * s,  11 * s,  42, leaves3]
  ];
  for (let [lx, ly, dAng, targetArr] of pairs) {
    const px = cx + lx * ca - ly * sa;
    const py = cy + lx * sa + ly * ca;
    const lf = clipFn(makeLeafPoly(px, py, 23 * s, 10.5 * s, angDeg + dAng));
    if (lf.length >= 3) targetArr.push(lf);
  }

  // Little plum/ochre berry dots along sprig
  const bOffs = [[-4 * s, -18 * s], [12 * s, 16 * s]];
  for (let [bx, by] of bOffs) {
    const px = cx + bx * ca - by * sa;
    const py = cy + bx * sa + by * ca;
    const bPoly = clipFn(makeCirclePoly(px, py, 4.8 * s, 8));
    if (bPoly.length >= 3) berries.push(bPoly);
  }
}

function drawNabisQuiltBorders() {
  // Lower-left quilt fold & lower-right turnover: dense olive sprigs & plum dots on flax/ochre/plum
  const llBase = clipToLLQuilt([[-20, 500], [700, 500], [700, 1220], [-20, 1220]]);
  drawFlatMattePoly(llBase, PAL.quiltFlax, 42, true);

  const lrBase = clipToLRQuilt([[500, 500], [1220, 500], [1220, 1220], [500, 1220]]);
  drawFlatMattePoly(lrBase, PAL.plum3, -38, true);

  // Wide plum & ochre border stripes along the quilt fold lines
  const llBorder1 = clipToLLQuilt(makeTiltedRectPoly(270, 965, 950, 34, 42.5));
  const llBorder2 = clipToLLQuilt(makeTiltedRectPoly(248, 990, 950, 18, 42.5));
  drawFlatMattePoly(llBorder1, PAL.plum1, 42.5, true);
  drawFlatMattePoly(llBorder2, PAL.ochre1, 42.5, false);

  const lrBorder1 = clipToLRQuilt(makeTiltedRectPoly(920, 960, 980, 38, -41.5));
  const lrBorder2 = clipToLRQuilt(makeTiltedRectPoly(945, 985, 980, 22, -41.5));
  drawFlatMattePoly(lrBorder1, PAL.ochre1, -41.5, true);
  drawFlatMattePoly(lrBorder2, PAL.ochre4, -41.5, false);

  const leaves1 = [], leaves2 = [], leaves3 = [];
  const dots1 = [], dots2 = [], ochreDots = [];
  const stems = [];

  // Populate LL quilt with dense olive sprigs & plum dots
  const angLL = 42.5;
  const radLL = angLL * Math.PI / 180;
  const caLL = Math.cos(radLL), saLL = Math.sin(radLL);
  for (let u = -420; u <= 460; u += 78) {
    for (let v = 35; v <= 420; v += 72) {
      const su = u + (Math.round(v / 72) % 2 === 0 ? 0 : 39);
      const cx = 270 + su * caLL - v * saLL;
      const cy = 965 + su * saLL + v * caLL;
      addSprigToBatches(
        cx, cy, angLL + (su % 2 === 0 ? 18 : -24), 1.08,
        clipToLLQuilt, leaves1, leaves2, leaves3, dots1, stems
      );
      const pDot = clipToLLQuilt(makeCirclePoly(cx + 34, cy - 18, 9.5, 11));
      if (pDot.length >= 3) dots2.push(pDot);
      const oDot = clipToLLQuilt(makeCirclePoly(cx - 28, cy + 22, 7.5, 10));
      if (oDot.length >= 3) ochreDots.push(oDot);
    }
  }

  // Populate LR quilt with ochre checks & olive sprigs over deep plum
  const angLR = -41.5;
  const radLR = angLR * Math.PI / 180;
  const caLR = Math.cos(radLR), saLR = Math.sin(radLR);
  const lrChecks = [];
  for (let u = -420; u <= 440; u += 68) {
    for (let v = 38; v <= 400; v += 68) {
      const cx = 920 + u * caLR - v * saLR;
      const cy = 960 + u * saLR + v * caLR;
      const idx = Math.round((u + 420) / 68) + Math.round(v / 68);
      if (idx % 2 === 0) {
        const chk = clipToLRQuilt(makeTiltedRectPoly(cx, cy, 46, 46, angLR));
        if (chk.length >= 3) lrChecks.push(chk);
        const pd = clipToLRQuilt(makeCirclePoly(cx, cy, 11, 11));
        if (pd.length >= 3) dots2.push(pd);
      } else {
        addSprigToBatches(
          cx, cy, angLR + 25, 0.95,
          clipToLRQuilt, leaves1, leaves2, leaves3, ochreDots, stems
        );
      }
    }
  }

  drawBatchMattePolys(lrChecks, PAL.ochre2, angLR, true);
  drawBatchMattePolys(leaves1, PAL.olive1, 30, true);
  drawBatchMattePolys(leaves2, PAL.olive2, -30, false);
  drawBatchMattePolys(leaves3, PAL.olive3, 0, false);

  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set("flat_marker", PAL.olive3, 0.36);
  for (let st of stems) {
    brush.line(st[0], st[1], st[2], st[3]);
  }

  drawBatchMattePolys(dots1, PAL.plum1, 0, false);
  drawBatchMattePolys(dots2, PAL.plum2, 0, false);
  drawBatchMattePolys(ochreDots, PAL.ochre1, 0, false);
}

