// ===========================================================================
// 2. HYPERREAL SLEEPING TABBY CAT — 3D ANATOMY & COLOURED PENCIL ENGINE
// ===========================================================================

// Helper: convert head-local (u, w) coordinates to canvas (x, y)
function headPt(u, w) {
  return [
    HEAD_ORIGIN[0] + u * HEAD_U[0] + w * HEAD_W[0],
    HEAD_ORIGIN[1] + u * HEAD_U[1] + w * HEAD_W[1]
  ];
}

// Evaluate Catmull-Rom / cubic spline point and tangent at parameter u in [0, 1]
function evalSpine(ctrlPts, u) {
  const n = ctrlPts.length - 1;
  const su = constrain(u, 0, 0.99999) * n;
  const idx = Math.floor(su);
  const t = su - idx;

  const p0 = ctrlPts[Math.max(0, idx - 1)];
  const p1 = ctrlPts[idx];
  const p2 = ctrlPts[Math.min(n, idx + 1)];
  const p3 = ctrlPts[Math.min(n, idx + 2)];

  const t2 = t * t;
  const t3 = t2 * t;

  const out = [];
  const dim = p1.length;
  for (let d = 0; d < dim; d++) {
    const v0 = p0[d], v1 = p1[d], v2 = p2[d], v3 = p3[d];
    const val = 0.5 * (
      (2 * v1) +
      (-v0 + v2) * t +
      (2 * v0 - 5 * v1 + 4 * v2 - v3) * t2 +
      (-v0 + 3 * v1 - 3 * v2 + v3) * t3
    );
    out.push(val);
  }

  // Derivative along u for tangent
  const dx = 0.5 * (
    (-p0[0] + p2[0]) +
    2 * (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t +
    3 * (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t2
  );
  const dy = 0.5 * (
    (-p0[1] + p2[1]) +
    2 * (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t +
    3 * (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t2
  );
  const len = Math.hypot(dx, dy) || 1;
  const tx = dx / len, ty = dy / len;
  // Normal pointing right of tangent (inward/outward across tube)
  const nx = -ty, ny = tx;

  return { pt: out, tx, ty, nx, ny };
}

