function buildTubePolygon(spinePts, steps = 32) {
  const leftSide = [];
  const rightSide = [];
  for (let i = 0; i <= steps; i++) {
    const u = i / steps;
    const { pt, tx, ty, nx, ny } = evalSpine(spinePts, u);
    const rOut = pt[2], rIn = pt[3];
    // Cap rounding at ends
    let capScale = 1;
    if (u < 0.08) capScale = Math.sqrt(1 - Math.pow(1 - u / 0.08, 2));
    else if (u > 0.92) capScale = Math.sqrt(1 - Math.pow((u - 0.92) / 0.08, 2));

    leftSide.push([pt[0] - nx * rOut * capScale, pt[1] - ny * rOut * capScale]);
    rightSide.unshift([pt[0] + nx * rIn * capScale, pt[1] + ny * rIn * capScale]);
  }
  return leftSide.concat(rightSide);
}

// Compute 3D lighting from surface normal (nx3, ny3, nz3) and ambient occlusion
function compute3DLight(nx3, ny3, nz3, ao = 1.0) {
  // Key light from upper-left-front: (-0.48, -0.56, 0.67)
  const lx = -0.48, ly = -0.56, lz = 0.67;
  const ndotl = Math.max(0, nx3 * lx + ny3 * ly + nz3 * lz);
  // Warm bounce from ochre quilt below: (0.15, 0.55, 0.35)
  const bounce = Math.max(0, nx3 * 0.15 + ny3 * 0.55 + nz3 * 0.35) * 0.22;
  const light = (0.18 + 0.76 * ndotl + bounce) * ao;
  return constrain(light, 0.04, 1.0);
}

// Pick hyperreal coloured-pencil color from tabby stripe weight, agouti band, and 3D light
function pickTabbyPencilColor(stripeVal, lightVal, creamWeight = 0, bandPos = 0.5) {
  // stripeVal in [0, 1]: 1 = dark mackerel stripe, 0 = agouti golden-buff ground
  // creamWeight in [0, 1]: 1 = ivory/cream belly, toes, chin, spectacles
  // bandPos in [0, 1]: agouti position along individual hair (root -> mid shaft -> tip)

  if (creamWeight > 0.55) {
    if (lightVal < 0.28) return PAL.furCoolShadow;
    if (lightVal < 0.46) return PAL.furCoolMid;
    if (lightVal < 0.66) return PAL.furWarmBuff;
    if (lightVal < 0.84) return PAL.furCream;
    return bandPos > 0.6 ? PAL.furWhite : PAL.furIvory;
  }

  // Dark tabby stripe region
  if (stripeVal > 0.58) {
    if (lightVal < 0.28) return PAL.furBlack;
    if (lightVal < 0.52) return bandPos < 0.35 ? PAL.furBlack : PAL.furCharcoal;
    if (lightVal < 0.76) return bandPos > 0.7 ? PAL.furCharcoal : PAL.furDarkUmber;
    // Sunlit sheen on dark stripe guard hairs
    return bandPos > 0.55 ? PAL.furWarmUmber : PAL.furCoolShadow;
  }

  // Transition border of stripe (rich warm sienna & umber agouti roots)
  if (stripeVal > 0.32) {
    if (lightVal < 0.30) return PAL.furCharcoal;
    if (lightVal < 0.52) return PAL.furDarkUmber;
    if (lightVal < 0.74) return bandPos < 0.4 ? PAL.furWarmUmber : PAL.furSienna;
    return bandPos > 0.5 ? PAL.furOchre : PAL.furSienna;
  }

  // Agouti golden-ochre & buff ground fur (banded hairs!)
  if (lightVal < 0.24) return PAL.furDarkUmber;
  if (lightVal < 0.40) return bandPos < 0.4 ? PAL.furWarmUmber : PAL.furCoolShadow;
  if (lightVal < 0.58) {
    if (bandPos < 0.25) return PAL.furWarmUmber;
    if (bandPos < 0.78) return PAL.furOchre;
    return PAL.furDarkUmber; // dark agouti tip
  }
  if (lightVal < 0.78) {
    if (bandPos < 0.20) return PAL.furSienna;
    if (bandPos < 0.82) return PAL.furGoldBuff;
    return PAL.furWarmUmber;
  }
  // Sunlit crown agouti hair
  if (bandPos < 0.18) return PAL.furOchre;
  if (bandPos < 0.65) return PAL.furWarmBuff;
  return PAL.furCream;
}

