// Generic helper to render a tubular anatomical region with layered coloured pencil hairs
function renderTubularFurRegion(spinePts, uSteps, vSteps, opts) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  // Pass 1: Dense coloured-pencil undercoat (u from 1 down to 0 or 0 to 1 depending on shingle direction)
  // Pass 2: Crisp agouti guard hairs & stripe-edge overlap hairs
  for (let pass = 0; pass < 2; pass++) {
    const isGuard = pass === 1;
    const uCount = isGuard ? Math.floor(uSteps * 1.15) : uSteps;
    const vCount = isGuard ? Math.floor(vSteps * 1.1) : vSteps;

    for (let iu = 0; iu <= uCount; iu++) {
      // Shingle order: draw from posterior (u=1) to anterior (u=0) or vice versa as specified
      const uRaw = opts.reverseShingle ? (iu / uCount) : (1 - iu / uCount);
      const u = constrain(uRaw + random(-0.012, 0.012), 0.01, 0.99);
      const { pt, tx, ty, nx, ny } = evalSpine(spinePts, u);
      const rOut = pt[2], rIn = pt[3];

      let capScale = 1;
      if (u < 0.07) capScale = Math.sqrt(1 - Math.pow(1 - u / 0.07, 2));
      else if (u > 0.93) capScale = Math.sqrt(1 - Math.pow((u - 0.93) / 0.07, 2));

      for (let iv = 0; iv <= vCount; iv++) {
        const v = lerp(-0.98, 0.98, iv / vCount) + random(-0.04, 0.04);
        const vc = constrain(v, -0.99, 0.99);

        const distFromSpine = vc < 0 ? (vc * rOut * capScale) : (vc * rIn * capScale);
        const hx = pt[0] + nx * distFromSpine;
        const hy = pt[1] + ny * distFromSpine;

        // 3D tube normal
        const nz3 = Math.sqrt(Math.max(0.04, 1 - vc * vc));
        const nx3 = nx * vc * 0.85 + tx * (opts.uTilt || 0);
        const ny3 = ny * vc * 0.85 + ty * (opts.uTilt || 0);

        // Evaluate region-specific pattern: { stripe, cream, ao, furAngleOffset, hairLen }
        const pat = opts.evalPattern(u, vc, hx, hy);
        const light = compute3DLight(nx3, ny3, nz3, pat.ao);

        // Hair growth vector: flows along tangent (tx, ty) + outward/inward curve
        const baseAng = atan2(ty, tx) + (pat.furAngleOffset || 0) + random(-7, 7);
        const hLen = (pat.hairLen || 24) * (isGuard ? random(0.85, 1.35) : random(0.75, 1.05));

        if (!isGuard) {
          // Undercoat stroke
          const col = pickTabbyPencilColor(pat.stripe, light * 0.92, pat.cream, random(0.15, 0.55));
          brush.set("cpencil", col, random(0.55, 0.82));
          brush.line(
            hx, hy,
            hx + cos(baseAng) * hLen,
            hy + sin(baseAng) * hLen
          );
        } else {
          // Guard hair with agouti root-to-tip banding (2 segments along hair shaft)
          const midRatio = 0.52;
          const mx = hx + cos(baseAng) * hLen * midRatio;
          const my = hy + sin(baseAng) * hLen * midRatio;
          const ex = hx + cos(baseAng + random(-4, 4)) * hLen;
          const ey = hy + sin(baseAng + random(-4, 4)) * hLen;

          const colRoot = pickTabbyPencilColor(pat.stripe, light * 0.88, pat.cream, 0.25);
          const colTip = pickTabbyPencilColor(
            pat.stripe + random(-0.18, 0.15),
            constrain(light * 1.08, 0, 1),
            pat.cream,
            0.78
          );

          const bType = (light > 0.72 || pat.cream > 0.6) ? "fine_cpencil" : "cpencil";
          const w = bType === "fine_cpencil" ? random(0.55, 0.9) : random(0.32, 0.52);

          brush.set(bType, colRoot, w);
          brush.line(hx, hy, mx, my);
          brush.set(bType, colTip, w * 0.85);
          brush.line(mx, my, ex, ey);
        }
      }
    }
  }
}

function drawBellyAndChestFur() {
  // Soft, plush, warm cream & golden-buff fur inside the central curl hollow
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  const cx = 595, cy = 620;
  for (let pass = 0; pass < 2; pass++) {
    const count = pass === 0 ? 420 : 480;
    for (let i = 0; i < count; i++) {
      const r = random(15, 165);
      const a = random(0, 360);
      const hx = cx + cos(a) * r * 1.05;
      const hy = cy + sin(a) * r * 0.92;

      // Deep ambient occlusion in the center crease where paws tuck in
      const distCrease = Math.hypot(hx - 545, hy - 645);
      const ao = constrain(map(distCrease, 15, 135, 0.25, 0.92), 0.22, 0.95);
      const light = constrain(0.55 * ao + (hy < 600 ? 0.18 : -0.08), 0.12, 0.92);

      // Soft spotted belly markings
      const bellySpot = Math.sin(hx * 0.055) * Math.cos(hy * 0.055) > 0.58 ? 0.65 : 0.0;
      const creamW = bellySpot > 0.4 ? 0.1 : 0.82;
      const col = pickTabbyPencilColor(bellySpot, light, creamW, pass === 0 ? 0.35 : 0.75);

      const furAng = atan2(hy - 560, hx - 540) + 35 + random(-14, 14);
      const len = random(20, 34);
      brush.set(pass === 0 ? "cpencil" : "fine_cpencil", col, pass === 0 ? 0.68 : 0.75);
      brush.line(hx, hy, hx + cos(furAng) * len, hy + sin(furAng) * len);
    }
  }
}

function drawRightForepaw() {
