      const cream = u > 0.68 ? map(u, 0.68, 0.92, 0.3, 0.95) : 0.15;
      const wristWave = Math.sin(u * 26 + v * 1.5);
      const stripe = u < 0.68 && wristWave > 0.32 ? 0.85 : 0.12;
      // Shadow under cheek (v < 0 is upper edge under cheek, v > 0 is lower quilt edge)
      const ao = v < -0.35 ? 0.38 : (v > 0.65 ? 0.48 : 0.88);
