function drawTorsoAndScapula() {
  renderTubularFurRegion(SPINE_TORSO, 54, 28, {
    reverseShingle: false,
    evalPattern: (u, v, x, y) => {
      // v in [-1, 1]: v < 0 is outer dorsal ridge, v > 0 is inner ventral flank
      let stripe = 0.08;

      // 1. Dorsal spine triple-stripe along v in [-0.96, -0.48]
      if (v < -0.46) {
        const dWave = Math.cos((v + 0.72) * 24);
        if (dWave > 0.15) stripe = 0.92;
      } else {
        // 2. Mackerel / classic tabby vertical rib stripes radiating from spine
        // Curve the rib stripes naturally as they cross from spine (v=-0.46) to flank (v=+0.85)
        const uCurved = u + 0.065 * Math.sin((v + 0.45) * 2.6) + 0.018 * (noise(x * 0.015, y * 0.015) - 0.5);
        // Scapula butterfly whorl around u in [0.12, 0.28], v in [-0.35, 0.35]
        const dScap = Math.hypot((u - 0.20) * 3.2, (v + 0.05) * 1.3);
        let ribWave;
        if (dScap < 0.48) {
          ribWave = Math.cos(dScap * 19);
        } else {
          ribWave = Math.sin(uCurved * 64);
        }
        if (ribWave > 0.24) {
          stripe = map(ribWave, 0.24, 1.0, 0.45, 0.95);
        }
      }

      // Warm cream/buff transition along inner belly edge (v > 0.62)
      const cream = v > 0.62 ? map(v, 0.62, 0.98, 0.0, 0.78) : 0.0;

      // Ambient occlusion in inner belly tuck (v > 0.75) and lower right quilt contact
      let ao = 0.96;
      if (v > 0.68) ao *= map(v, 0.68, 0.99, 0.95, 0.35);
      if (u > 0.72 && v < -0.55) ao *= 0.68;

      // Hair flows along spine u and sweeps downward across the ribs (positive v)
      const furAngleOffset = 14 + v * 22;
      return {
        stripe,
        cream,
        ao,
        furAngleOffset,
        hairLen: 29
      };
    }
  });
}

function drawHaunchAndThigh() {
