    const t = i / 65;
    const cx = lerp(635, 815, t) + random(-4, 4);
    const cy = lerp(700, 745, t) - Math.sin(t * Math.PI) * 22 + random(-4, 4);
    brush.line(cx, cy, cx + random(-14, 14), cy + random(8, 20));
  }

  renderTubularFurRegion(SPINE_HAUNCH, 28, 22, {
    reverseShingle: false,
    evalPattern: (u, v, x, y) => {
      // Sweeping thigh tabby stripes
      const uSweep = u + 0.14 * v * v + 0.02 * (noise(x * 0.02, y * 0.02) - 0.5);
      const wave = Math.sin(uSweep * 32);
      const stripe = wave > 0.22 ? map(wave, 0.22, 1.0, 0.45, 0.92) : 0.08;
      const cream = (u > 0.75 && v > 0.3) ? map(u, 0.75, 1.0, 0.1, 0.65) : 0.0;

      // Crease AO at top edge (v > 0.65) and bottom tail crease (v < -0.65)
      let ao = 0.95;
      if (v > 0.62) ao = map(v, 0.62, 0.99, 0.92, 0.32);
      if (v < -0.62) ao = map(v, -0.62, -0.99, 0.90, 0.38);

      return {
        stripe,
        cream,
        ao,
        furAngleOffset: -12 + v * 24,
        hairLen: 27
      };
    }
  });
}

function drawRingedTail() {
  // Deep occlusion crease between tail inner edge and haunch/paws
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set("cpencil", PAL.furBlack, 0.75);
  for (let i = 0; i < 85; i++) {
    const u = i / 85;
    const { pt, nx, ny } = evalSpine(SPINE_TAIL, u);
    const cx = pt[0] + nx * (pt[3] * 0.92);
    const cy = pt[1] + ny * (pt[3] * 0.92);
    brush.line(cx, cy, cx + nx * 14 + random(-5, 5), cy + ny * 14 + random(-5, 5));
  }

  renderTubularFurRegion(SPINE_TAIL, 42, 18, {
    reverseShingle: false,
    evalPattern: (u, v, x, y) => {
      // 7 bold charcoal-black tail rings + solid dark tail tip (u > 0.83)
      const uRing = u + 0.035 * (1 - v * v);
      const ringWave = Math.sin(uRing * 46);
      let stripe = ringWave > 0.12 ? map(ringWave, 0.12, 1.0, 0.5, 0.98) : 0.1;
      if (u > 0.83) stripe = 0.98;

      const cream = (v > 0.45 && stripe < 0.3) ? 0.35 : 0.0;
      let ao = 0.94;
      if (v > 0.65) ao = map(v, 0.65, 0.99, 0.9, 0.32); // inner crease against body
      if (v < -0.65) ao = map(v, -0.65, -0.99, 0.9, 0.42); // outer contact with quilt

      return {
        stripe,
        cream,
        ao,
        furAngleOffset: v * 28,
        hairLen: 26
      };
    }
  });
}

function drawLeftForelegAndPaw() {
  // Crease shadow under the forearm and wrist against the chest
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set("cpencil", PAL.furBlack, 0.72);
  for (let i = 0; i < 55; i++) {
    const u = i / 55;
    const { pt, nx, ny } = evalSpine(SPINE_LEFT_LEG, u);
    const cx = pt[0] - nx * (pt[2] * 0.9);
    const cy = pt[1] - ny * (pt[2] * 0.9);
    brush.line(cx, cy, cx - nx * 14, cy - ny * 14);
  }

  renderTubularFurRegion(SPINE_LEFT_LEG, 26, 16, {
    reverseShingle: false,
    evalPattern: (u, v, x, y) => {
      // Bold tabby forearm bracelets (u < 0.74) & luminous cream-white curled paw (u >= 0.74)
      const cream = u > 0.72 ? map(u, 0.72, 0.92, 0.15, 0.95) : 0.08;
      const braceWave = Math.sin((u + 0.04 * v) * 32);
      const stripe = u < 0.74 && braceWave > 0.25 ? map(braceWave, 0.25, 1, 0.5, 0.95) : 0.08;

      let ao = 0.95;
      if (v < -0.58) ao = map(v, -0.58, -0.99, 0.9, 0.35);
      // Shadow directly under the cat's chin & muzzle (u > 0.68, v > 0.15)
      if (u > 0.65 && v > 0.1) ao *= 0.52;

      return {
        stripe,
        cream,
        ao,
        furAngleOffset: v * 18,
        hairLen: lerp(26, 15, u)
      };
    }
  });

  // Soft toe clefts on the curled left forepaw
  drawToeClefts([[442, 618, 170], [452, 632, 160], [468, 639, 150]]);
}

function drawToeClefts(clefts) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  for (let [tx, ty, ang] of clefts) {
    brush.set("cpencil", PAL.furDarkUmber, 0.48);
    for (let k = -2; k <= 2; k++) {
      const a = ang + k * 5;
      brush.line(tx, ty, tx + cos(a) * 16, ty + sin(a) * 16);
    }
    brush.set("fine_cpencil", PAL.furWhite, 0.65);
    for (let k = 0; k < 7; k++) {
      const a = ang + 180 + random(-25, 25);
      brush.line(tx + random(-5, 5), ty + random(-5, 5), tx + cos(a) * 13, ty + sin(a) * 13);
    }
  }
}

// ===========================================================================
// 2E. HEAD, EARS, CLOSED EYES, TERRACOTTA NOSE & FACIAL HYPERREALISM
// ===========================================================================

function drawRightEar() {
  // Lower/Left ear tilted sideways against the quilt & right forepaw
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  const b1 = headPt(-78, 28);
  const b2 = headPt(-22, 92);
  const tip = headPt(-118, 138);

  // Outer pinna fur (dark charcoal rim + pale buff ocellus "thumbprint" in center)
  for (let pass = 0; pass < 2; pass++) {
    const steps = pass === 0 ? 180 : 220;
    for (let i = 0; i < steps; i++) {
      let s = random(0.02, 0.96);
      let t = random(0.02, 0.96);
      if (s + t > 0.98) { s = 1 - s; t = 1 - t; }
      const w0 = 1 - s - t;

      const px = w0 * b1[0] + s * b2[0] + t * tip[0];
      const py = w0 * b1[1] + s * b2[1] + t * tip[1];

      // Inner concha hollow near lower edge (s > 0.35 and t < 0.55)
      const isConcha = (s > 0.38 && t < 0.52 && w0 < 0.45);
      const isOcellus = (t > 0.25 && t < 0.62 && s < 0.42);
      const isTip = t > 0.68;

      const angToTip = atan2(tip[1] - (b1[1] + b2[1]) * 0.5, tip[0] - (b1[0] + b2[0]) * 0.5) + random(-10, 10);
      const len = lerp(18, 9, t);

      let col;
      if (isConcha) {
        col = random() < 0.5 ? PAL.earInnerDeep : PAL.earInnerWarm;
      } else if (isTip) {
        col = PAL.furBlack;
      } else if (isOcellus) {
        col = random() < 0.6 ? PAL.furWarmBuff : PAL.furGoldBuff;
      } else {
        col = random() < 0.5 ? PAL.furDarkUmber : PAL.furSienna;
      }

      brush.set(pass === 0 ? "cpencil" : "fine_cpencil", col, pass === 0 ? 0.52 : 0.62);
      brush.line(px, py, px + cos(angToTip) * len, py + sin(angToTip) * len);
    }
  }

  // Long silky ivory ear furnishings streaming across the right ear opening
  for (let i = 0; i < 38; i++) {
    const f = i / 38;
    const sx = lerp(b1[0], b2[0], 0.35 + f * 0.55) + random(-4, 4);
    const sy = lerp(b1[1], b2[1], 0.35 + f * 0.55) + random(-4, 4);
    const ang = atan2(tip[1] - sy, tip[0] - sx) + random(-18, 22);
    const len = random(24, 44);
    const mx = sx + cos(ang - 8) * len * 0.5;
    const my = sy + sin(ang - 8) * len * 0.5;
    const ex = sx + cos(ang + 6) * len;
    const ey = sy + sin(ang + 6) * len;

    brush.set("fine_cpencil", i % 3 === 0 ? PAL.furWhite : PAL.furCream, random(0.55, 0.85));
    brush.spline([[sx, sy, 0.9], [mx, my, 0.7], [ex, ey, 0.15]], 0.5);
  }
}

function drawHeadAndFace() {
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  // Deep crease shadow where lower cheek & chin rest on the tucked forepaws
  brush.set("cpencil", PAL.furBlack, 0.72);
  for (let i = 0; i < 75; i++) {
    const u = random(25, 118);
    const w = random(-45, 85);
    if (u < 85 && w < 52) continue;
    const [px, py] = headPt(u, w);
    const [dx, dy] = headPt(u + 14, w + 10);
    brush.line(px, py, dx, dy);
  }

  // Cranial, Forehead, Cheek & Muzzle Fur Engine in (u, w) head coordinates
  // u in [-95, +115] (crown to chin), w in [-118, +105] (upper sunlit cheek to lower cheek)
  for (let pass = 0; pass < 2; pass++) {
    const isGuard = pass === 1;
    const uSteps = isGuard ? 58 : 46;
    const wSteps = isGuard ? 54 : 44;

    for (let iu = 0; iu <= uSteps; iu++) {
      // Shingle from muzzle/chin back to crown OR crown to cheek?
      // On a cat's face, hair grows from the nose bridge UP toward the forehead and OUT around the cheeks!
      // So drawing from outer perimeter inward (or from posterior cheek ruff toward nose bridge) shingles correctly.
      const u = lerp(112, -92, iu / uSteps) + random(-1.8, 1.8);

      for (let iw = 0; iw <= wSteps; iw++) {
        const w = lerp(-118, 102, iw / wSteps) + random(-1.8, 1.8);

        // Head & muzzle silhouette envelope in (u, w)
        let maxWLeft = 116 * Math.sqrt(Math.max(0, 1 - Math.pow((u - 5) / 108, 2)));
        let maxWRight = 100 * Math.sqrt(Math.max(0, 1 - Math.pow((u - 5) / 105, 2)));
        // Expand for muzzle whisker pads around u in [65, 112]
        if (u > 55) {
          const muzBulge = 58 * Math.exp(-Math.pow((u - 90) / 26, 2));
          maxWLeft = Math.max(maxWLeft, muzBulge + 6);
          maxWRight = Math.max(maxWRight, muzBulge - 4);
        }
        if (w < -maxWLeft || w > maxWRight) continue;

        // Skip interior of nose leather triangle (drawn separately in fine detail)
        if (u > 80 && u < 106 && w > -23 && w < 11) {
          const noseHalfW = map(u, 80, 106, 17, 1);
          if (Math.abs(w + 6) < noseHalfW) continue;
        }

        const [hx, hy] = headPt(u, w);

        // 3D Cranial normal in (u, w)
        const normU = (u - 10) / 105;
        const normW = w / 110;
        const nz3 = Math.sqrt(Math.max(0.08, 1 - 0.65 * (normU * normU + normW * normW)));
        const nx3 = normU * HEAD_U[0] + normW * HEAD_W[0];
        const ny3 = normU * HEAD_U[1] + normW * HEAD_W[1];

        // Ambient occlusion on lower cheek (w > 55) and under chin (u > 102)
        let ao = 0.96;
        if (w > 52) ao *= map(w, 52, 100, 0.95, 0.38);
        if (u > 98) ao *= map(u, 98, 114, 0.92, 0.42);
        const light = compute3DLight(nx3, ny3, nz3, ao);

        // Evaluate Facial Tabby Pattern in (u, w)
        const fPat = evalFaceTabbyPattern(u, w);

        // Facial fur flow direction in (u, w):
        // Radiates from nose bridge (u=65, w=-6) upward over forehead and outward across cheeks
        let du = -1, dw = 0;
        if (u > 18 && Math.abs(w + 6) < 22 && u < 82) {
          // Nose bridge: short velvety hairs growing straight toward nose tip (+u)
          du = 1.0;
          dw = (w + 6) * 0.03;
        } else if (u > 68) {
          // Whisker pads & chin: curving outward and downward around pads
          du = 0.35;
          dw = (w + 6) >= 0 ? 0.9 : -0.9;
        } else {
          // Forehead, eyes & cheeks: sweeping from nose bridge up forehead and out around cheeks
          du = -0.75 + 0.3 * (Math.abs(w) / 110);
          dw = (w + 6) >= 0 ? (0.25 + 0.85 * (w / 100)) : (-0.25 + 0.85 * (w / 110));
        }

        const [vx, vy] = [
          du * HEAD_U[0] + dw * HEAD_W[0],
          du * HEAD_U[1] + dw * HEAD_W[1]
        ];
        const furAng = atan2(vy, vx) + random(-6, 6);
        const hLen = fPat.hairLen * (isGuard ? random(0.85, 1.25) : random(0.75, 1.0));

        const col = pickTabbyPencilColor(
          fPat.stripe,
          light,
          fPat.cream,
          isGuard ? random(0.45, 0.85) : random(0.15, 0.5)
        );

        const bName = (isGuard || fPat.hairLen < 14) ? "fine_cpencil" : "cpencil";
        const weight = bName === "fine_cpencil" ? random(0.5, 0.82) : random(0.42, 0.65);

        brush.set(bName, col, weight);
        brush.line(hx, hy, hx + cos(furAng) * hLen, hy + sin(furAng) * hLen);
      }
    }
  }

  // Render crisp anatomical features on top of the facial fur
  drawClosedEyesAndLashes();
  drawTerracottaNoseAndMouth();
  drawWhiskerFollicleDots();
}

function evalFaceTabbyPattern(u, w) {
  let stripe = 0.1;
  let cream = 0.0;
  let hairLen = 19;

  // 1. Nose bridge (short velvety rufous-ochre & buff hair)
  if (u > 12 && u <= 82 && Math.abs(w + 6) < 20) {
    hairLen = 9.5;
    stripe = Math.abs(w + 6) > 13 ? 0.65 : 0.12;
    return { stripe, cream: 0.08, hairLen };
  }

  // 2. Whisker pads & chin (plump ivory-cream cushions)
  const dPadL = Math.hypot(u - 88, w + 38);
  const dPadR = Math.hypot(u - 88, w - 26);
  if (dPadL < 34 || dPadR < 32 || u > 95) {
    hairLen = 11.5;
    cream = 0.92;
    if (u > 103 && Math.abs(w + 4) < 18) {
      // Subtle dark lower lip / chin cleft
      stripe = 0.55;
      cream = 0.35;
    }
    return { stripe, cream, hairLen };
  }

  // 3. Eye Spectacles (luminous pale cream rings around both closed eyes)
  const dEyeL = Math.hypot((u - 28) * 1.25, (w + 52) * 0.85);
  const dEyeR = Math.hypot((u - 28) * 1.25, (w - 44) * 0.85);
  if (dEyeL < 27 || dEyeR < 25) {
    hairLen = 11;
    cream = 0.88;
    return { stripe: 0.0, cream, hairLen };
  }
  // Thin dark orbital frame just outside spectacles
  if ((dEyeL >= 27 && dEyeL < 34) || (dEyeR >= 25 && dEyeR < 32)) {
    hairLen = 14;
    return { stripe: 0.82, cream: 0.0, hairLen };
  }

  // 4. The Iconic Tabby "M" on the Forehead (u in [-55, +18], w in [-58, +52])
  if (u > -62 && u < 18 && Math.abs(w + 3) < 58) {
    hairLen = 14.5;
    // 4 dark vertical-arching brow stripes that peak into an "M"
    const mShift = Math.abs(Math.abs(w + 3) - 24) * 0.55;
    const mWave = Math.cos((w + 3) * 0.24);
    const uM = u + mShift;
    if (mWave > 0.22 && uM > -55 && uM < 14) {
      stripe = 0.94;
    } else if (Math.abs(u + 8 - mShift) < 6.5) {
      stripe = 0.92; // Arching crossbar of the M
    }
    return { stripe, cream: 0.05, hairLen };
  }

  // 5. Cheek "Pencil" Stripes sweeping from outer eyes across cheeks
  if (w < -42) {
    const cheekWave = Math.sin((u - (w + 52) * 0.42) * 0.26);
    if (cheekWave > 0.38) stripe = 0.90;
    else if (w < -82) cream = 0.45; // Pale buff cheek ruff highlights
    hairLen = 23;
  } else if (w > 34) {
    const cheekWave = Math.sin((u + (w - 44) * 0.42) * 0.26);
    if (cheekWave > 0.38) stripe = 0.90;
    hairLen = 21;
  }

  // 6. Crown stripes between ears (u <= -55)
  if (u <= -55) {
    if (Math.cos((w + 3) * 0.22) > 0.18) stripe = 0.92;
    hairLen = 18;
  }

  return { stripe, cream, hairLen };
}

function drawClosedEyesAndLashes() {
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  // Left (Upper) Closed Eye Slit: from inner tear duct (u=42, w=-28) to outer corner (u=14, w=-76)
  const lInner = headPt(43, -27);
  const lMid1  = headPt(36, -45);
  const lMid2  = headPt(26, -62);
  const lOuter = headPt(13, -77);
  const lBrow  = headPt(6, -86); // Mascara wing extension

  // Soft pale cream eyelid cushions above and below the slit
  brush.set("fine_cpencil", PAL.furIvory, 0.72);
  for (let i = 0; i < 42; i++) {
    const t = i / 42;
    const u = lerp(41, 15, t);
    const w = lerp(-28, -75, t);
    const [ux, uy] = headPt(u - 5, w + 2);
    const [dx, dy] = headPt(u - 13, w - 3);
    brush.line(ux, uy, dx, dy);

    const [lx, ly] = headPt(u + 4, w - 2);
    const [lx2, ly2] = headPt(u + 11, w - 6);
    brush.line(lx, ly, lx2, ly2);
  }

  // Crisp dark charcoal-black closed eyelid crease & tear-duct line
  brush.set("rotring", PAL.furBlack, 0.65);
  brush.spline([
    [lInner[0], lInner[1], 0.9],
    [lMid1[0], lMid1[1], 1.2],
    [lMid2[0], lMid2[1], 1.1],
    [lOuter[0], lOuter[1], 0.8],
    [lBrow[0], lBrow[1], 0.2]
  ], 0.45);

  // Delicate short eyelashes along the closed upper lid
  for (let i = 0; i < 18; i++) {
    const t = i / 18;
    const u = lerp(42, 14, t) + Math.sin(t * Math.PI) * 3.5;
    const w = lerp(-27, -76, t);
    const [sx, sy] = headPt(u, w);
    const [ex, ey] = headPt(u + 7, w - 4);
    brush.set("fine_cpencil", i % 3 === 0 ? PAL.furCharcoal : PAL.furBlack, 0.58);
    brush.line(sx, sy, ex, ey);
  }

  // Right (Lower) Closed Eye Slit: from inner tear duct (u=43, w=20) to outer corner (u=16, w=66)
  const rInner = headPt(43, 19);
  const rMid   = headPt(33, 44);
  const rOuter = headPt(16, 65);

  brush.set("fine_cpencil", PAL.furCream, 0.68);
  for (let i = 0; i < 32; i++) {
    const t = i / 32;
    const u = lerp(42, 17, t);
    const w = lerp(20, 64, t);
    const [ux, uy] = headPt(u - 4, w - 1);
    const [dx, dy] = headPt(u - 11, w + 3);
    brush.line(ux, uy, dx, dy);
  }

  brush.set("rotring", PAL.furBlack, 0.6);
  brush.spline([
    [rInner[0], rInner[1], 0.85],
    [rMid[0], rMid[1], 1.15],
    [rOuter[0], rOuter[1], 0.4]
  ], 0.45);

  for (let i = 0; i < 14; i++) {
    const t = i / 14;
    const u = lerp(42, 17, t) + Math.sin(t * Math.PI) * 3;
    const w = lerp(20, 64, t);
    const [sx, sy] = headPt(u, w);
    const [ex, ey] = headPt(u + 6, w + 4);
    brush.set("fine_cpencil", PAL.furBlack, 0.55);
    brush.line(sx, sy, ex, ey);
  }
}

function drawTerracottaNoseAndMouth() {
  // Triangular rhinarium (nose leather) in head coordinates:
  // Top-left (u=81, w=-22), Top-right (u=81, w=+10), Bottom apex (u=105, w=-6)
  const nTL = headPt(81, -22);
  const nTM = headPt(83, -6);
  const nTR = headPt(81, 10);
  const nBot = headPt(105, -6);

  // Base terracotta wash
  drawFlatMattePoly([nTL, nTM, nTR, nBot], PAL.noseTerra, 0, false);

  brush.noFill();
  brush.noWash();
  brush.noHatch();

  // Stippled / micro-hatched coloured pencil skin texture across nose leather
  for (let i = 0; i < 160; i++) {
    let s = random(0.04, 0.95);
    let t = random(0.04, 0.95);
    if (s + t > 0.98) { s = 1 - s; t = 1 - t; }
    const w0 = 1 - s - t;

    const px = w0 * nTL[0] + s * nTR[0] + t * nBot[0];
    const py = w0 * nTL[1] + s * nTR[1] + t * nBot[1];

    // Darker burnt-umber rim & nostrils, warm rose center, luminous upper highlight
    const isRim = (t > 0.72 || w0 < 0.14 || s < 0.14);
    const isHighlight = (t < 0.28 && w0 > 0.25 && s > 0.18);

    let col = PAL.noseTerra;
    if (isRim) col = PAL.noseDeep;
    else if (isHighlight) col = random() < 0.55 ? PAL.noseHighlight : PAL.noseRose;
    else if (random() < 0.45) col = PAL.noseRose;

    brush.set("fine_cpencil", col, random(0.45, 0.72));
    brush.line(px, py, px + random(-2.5, 2.5), py + random(-2.5, 2.5));
  }

  // Dark nostrils (comma slits on left and right sides of the nose leather)
  const nostL1 = headPt(86, -19), nostL2 = headPt(94, -12);
  const nostR1 = headPt(86, 7),   nostR2 = headPt(94, 0);
  brush.set("rotring", PAL.furBlack, 0.55);
  brush.line(nostL1[0], nostL1[1], nostL2[0], nostL2[1]);
  brush.line(nostR1[0], nostR1[1], nostR2[0], nostR2[1]);

  // Crisp dark nose rim & philtrum cleft dividing the two whisker pads
  const philBot = headPt(112, -5);
  const mouthL  = headPt(105, -24);
  const mouthR  = headPt(105, 14);
  brush.set("fine_cpencil", PAL.noseDeep, 0.75);
  brush.line(nTL[0], nTL[1], nBot[0], nBot[1]);
  brush.line(nTR[0], nTR[1], nBot[0], nBot[1]);
  brush.line(nBot[0], nBot[1], philBot[0], philBot[1]);
  brush.line(philBot[0], philBot[1], mouthL[0], mouthL[1]);
  brush.line(philBot[0], philBot[1], mouthR[0], mouthR[1]);
}

function drawWhiskerFollicleDots() {
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  // 3 neat arched rows of dark mystacial follicle spots on each whisker pad
  for (let row = 0; row < 3; row++) {
    const uBase = 80 + row * 7.5;
    for (let k = 0; k < 4; k++) {
      // Left (upper) pad follicles
      const [lx, ly] = headPt(uBase + k * 1.8, -28 - k * 8.5);
      brush.set("cpencil", PAL.furDarkUmber, 0.58);
      brush.line(lx - 2, ly - 1, lx + 2.5, ly + 1.5);

      // Right (lower) pad follicles
      const [rx, ry] = headPt(uBase + k * 1.8, 16 + k * 7.8);
      brush.set("cpencil", PAL.furDarkUmber, 0.55);
      brush.line(rx - 2, ry - 1, rx + 2.5, ry + 1.5);
    }
  }
}

function drawLeftEar() {
  // Upper/Foreground ear: prominent triangular cup with shell-pink/tan inner concha & long ivory tufts
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  const bInner = headPt(-78, -24);
  const bOuter = headPt(-20, -96);
  const tip    = headPt(-144, -120);

  // 1. Inner ear cartilage & skin folds (concha)
  for (let i = 0; i < 240; i++) {
    let s = random(0.05, 0.92);
    let t = random(0.03, 0.88);
    if (s + t > 0.94) { s = 1 - s; t = 1 - t; }
    const w0 = 1 - s - t;

    const px = w0 * bInner[0] + s * bOuter[0] + t * tip[0];
    const py = w0 * bInner[1] + s * bOuter[1] + t * tip[1];

    // Outer furred rim vs inner pink-tan concha hollow
    const isOuterRim = (w0 < 0.18 || s < 0.16 || t > 0.68);
    const isDeepHollow = (s > 0.35 && t < 0.38 && w0 > 0.22);

    const ang = atan2(tip[1] - (bInner[1] + bOuter[1]) * 0.5, tip[0] - (bInner[0] + bOuter[0]) * 0.5) + random(-8, 8);
    const len = isOuterRim ? lerp(18, 9, t) : 11;

    let col;
    if (isOuterRim) {
      if (t > 0.72) col = PAL.furBlack;
      else if (w0 > s) col = random() < 0.6 ? PAL.furGoldBuff : PAL.furOchre;
      else col = random() < 0.5 ? PAL.furDarkUmber : PAL.furCharcoal;
    } else if (isDeepHollow) {
      col = random() < 0.5 ? PAL.earInnerDeep : PAL.earInnerWarm;
    } else {
      col = random() < 0.55 ? PAL.earInnerPink : PAL.earInnerWarm;
    }

    brush.set(isOuterRim ? "fine_cpencil" : "cpencil", col, isOuterRim ? 0.68 : 0.52);
    brush.line(px, py, px + cos(ang) * len, py + sin(ang) * len);
  }

  // 2. Crisp dark charcoal outer edge & lynx tip hairs
  brush.set("fine_cpencil", PAL.furBlack, 0.75);
  for (let i = 0; i < 28; i++) {
    const f = i / 28;
    const ex = lerp(bOuter[0], tip[0], f);
    const ey = lerp(bOuter[1], tip[1], f);
    const ang = atan2(tip[1] - bOuter[1], tip[0] - bOuter[0]) + random(-12, 6);
    brush.line(ex, ey, ex + cos(ang) * 14, ey + sin(ang) * 14);
  }

  // 3. Luminous ivory-cream ear furnishings (feathery tufts streaming across the concha)
  for (let i = 0; i < 52; i++) {
    const f = i / 52;
    const sx = lerp(bInner[0], tip[0], f * 0.68) + random(-3, 3);
    const sy = lerp(bInner[1], tip[1], f * 0.68) + random(-3, 3);
    const dirAng = atan2(bOuter[1] - bInner[1], bOuter[0] - bInner[0]) - 28 + f * 18 + random(-12, 12);
    const len = lerp(46, 20, f) * random(0.85, 1.15);

    const mx = sx + cos(dirAng - 6) * len * 0.52;
    const my = sy + sin(dirAng - 6) * len * 0.52;
    const ex = sx + cos(dirAng + 8) * len;
    const ey = sy + sin(dirAng + 8) * len;

    const col = i % 3 === 0 ? PAL.furWhite : (i % 2 === 0 ? PAL.furIvory : PAL.furCream);
    brush.set("fine_cpencil", col, random(0.58, 0.88));
    brush.spline([[sx, sy, 0.95], [mx, my, 0.7], [ex, ey, 0.12]], 0.5);
  }
}

