function drawHaloGuardHairs() {
  // Individual sunlit guard hairs projecting from the cat's dorsal silhouette over the flat wallpaper & quilt
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  // Along torso dorsal spine (u from 0.02 to 0.96, v = -0.96)
  for (let i = 0; i < 190; i++) {
    const u = i / 190;
    const { pt, tx, ty, nx, ny } = evalSpine(SPINE_TORSO, u);
    const sx = pt[0] - nx * (pt[2] * 0.95) + random(-3, 3);
    const sy = pt[1] - ny * (pt[2] * 0.95) + random(-3, 3);

    const baseAng = atan2(ty, tx) - 18 + random(-14, 14);
    const len = random(18, 32);

    // Alternate dark dorsal tip hairs with luminous cream-gold sunlit guard hairs
    const isLightHair = (u < 0.65 && i % 2 === 0) || i % 3 === 0;
    const col = isLightHair ? (random() < 0.5 ? PAL.furIvory : PAL.furWarmBuff) : PAL.furCharcoal;
    brush.set("fine_cpencil", col, isLightHair ? 0.68 : 0.55);
    brush.line(sx, sy, sx + cos(baseAng) * len, sy + sin(baseAng) * len);
  }

  // Fluffy cheek ruff guard hairs projecting out over the quilt
  for (let i = 0; i < 55; i++) {
    const u = lerp(-15, 55, i / 55);
    const [sx, sy] = headPt(u, -110 + random(-5, 5));
    const [ex, ey] = headPt(u - 16, -134 + random(-8, 8));
    brush.set("fine_cpencil", i % 2 === 0 ? PAL.furIvory : PAL.furGoldBuff, 0.65);
    brush.line(sx, sy, ex, ey);
  }
}

