function drawSingleHyperrealWhisker(sx, sy, angDeg, len, curveDeg, thicknessScale = 1.0) {
  const a1 = angDeg;
  const a2 = angDeg + curveDeg * 0.45;
  const a3 = angDeg + curveDeg;

  const p0 = [sx, sy];
  const p1 = [sx + cos(a1) * len * 0.33, sy + sin(a1) * len * 0.33];
  const p2 = [p1[0] + cos(a2) * len * 0.34, p1[1] + sin(a2) * len * 0.34];
  const p3 = [p2[0] + cos(a3) * len * 0.33, p2[1] + sin(a3) * len * 0.33];

  // 1. Subtle dark under-shadow offset by 1.5 px so the whisker has 3D relief over light fur & flat quilt
  brush.set("fine_cpencil", PAL.furCharcoal, 0.42 * thicknessScale);
  brush.spline([
    [p0[0] + 1.2, p0[1] + 1.8, 0.9],
    [p1[0] + 1.4, p1[1] + 2.0, 0.7],
    [p2[0] + 1.4, p2[1] + 2.0, 0.4],
    [p3[0] + 1.2, p3[1] + 1.8, 0.08]
  ], 0.5);

  // 2. Warm cream-ivory coloured pencil shaft
  brush.set("vibrissa", PAL.furCream, 0.82 * thicknessScale);
  brush.spline([
    [p0[0], p0[1], 1.15],
    [p1[0], p1[1], 0.88],
    [p2[0], p2[1], 0.48],
    [p3[0], p3[1], 0.08]
  ], 0.5);

  // 3. Crisp luminous white-ivory highlight core along the whisker
  brush.set("vibrissa", PAL.furWhite, 0.52 * thicknessScale);
  brush.spline([
    [p0[0], p0[1], 0.95],
    [p1[0], p1[1], 0.75],
    [p2[0], p2[1], 0.38],
    [p3[0], p3[1], 0.05]
  ], 0.5);
}

