// =============================================================================
// 1. GEOLOGICAL & NAVAJO STEPPED-DIAMOND TOPOLOGY GENERATOR
// =============================================================================

function buildGeologyGrid() {
  for (let r = 0; r < ROWS; r++) {
    gridMat[r] = new Array(COLS).fill(MAT_CREAM);
    gridStepType[r] = new Array(COLS).fill(0);
  }

  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      gridMat[r][c] = evaluateSteppedTopology(r, c);
    }
  }

  // Compute flat-midday lighting transitions across every horizontal step boundary
  // When moving from r-1 to r at column c:
  for (let r = 1; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      let mAbove = gridMat[r - 1][c];
      let mHere = gridMat[r][c];
      if (mAbove !== mHere) {
        // Determine whether this step boundary is a recessed overhang lip or a protruding sunlit ledge tread
        let isOverhang =
          mHere === MAT_CHARCOAL ||
          (r < 52 && Math.abs(c - 47) < 38) ||
          (mAbove === MAT_CREAM && (mHere === MAT_BRICK || mHere === MAT_BRICK_DEEP));

        if (isOverhang) {
          gridStepType[r][c] = -1; // Overhang shadow cast straight down by midday sun
        } else {
          gridStepType[r][c] = 1;  // Sunlit horizontal step tread catching flat midday light
        }
      }
    }
  }
}

function evaluateSteppedTopology(r, c) {
  // Subtle geological fault shift (1-column shift along a diagonal joint plane for hyperreal naturalism)
  let faultShift = (r > 35 && r < 105 && c > 46) ? 0 : 0;
  let cc = c + faultShift;

  // --- A. THE GREAT CENTRAL STEPPED-DIAMOND ALCOVE (Centered at r = 52, c = 47) ---
  // Serrated terrace modulation: every 4 rows, steps notch outward by 2 columns
  let serrationMain = ((Math.floor(r / 2) % 3) === 0) ? 2 : 0;
  let drMain = Math.abs(r - 52);
  let dcMain = Math.floor(Math.abs(cc - 47) * 0.88);
  let dMain = drMain + dcMain;
  let dMainSerrated = drMain + Math.max(0, dcMain - serrationMain);

  if (dMainSerrated <= 39) {
    // Nested concentric stepped diamonds echoing Classic Chief's Blanket & Canyon de Chelly alcoves
    if (dMainSerrated >= 37) {
      return (r < 52) ? MAT_CHARCOAL : MAT_CREAM;
    }
    if (dMainSerrated >= 32) {
      return (r % 7 === 0) ? MAT_BRICK_DEEP : MAT_BRICK;
    }
    if (dMain >= 29) {
      return MAT_CHARCOAL;
    }
    if (dMain >= 24) {
      // Natural grey serrated erosion terrace band
      return ((r + Math.floor(cc / 2)) % 6 === 0) ? MAT_GREY_LIGHT : MAT_GREY;
    }
    if (dMain >= 22) {
      return (r < 52) ? MAT_CHARCOAL : MAT_BRICK_DEEP;
    }
    if (dMain >= 15) {
      // Wide Sunlit Undyed Cream sandstone bench (the tiny juniper clings to the lower-right ledge here!)
      if (r === 42 || r === 62) return MAT_GREY_LIGHT;
      return MAT_CREAM;
    }
    if (dMain >= 13) {
      return MAT_CHARCOAL;
    }
    if (dMain >= 8) {
      return (r < 52) ? MAT_BRICK_DEEP : MAT_BRICK;
    }
    if (dMain >= 5) {
      return MAT_GREY;
    }
    if (dMain >= 3) {
      return MAT_CHARCOAL;
    }
    // Innermost diamond sanctum eye
    return (r === 52) ? MAT_BRICK : MAT_CREAM;
  }

  // --- B. UPPER CORNER QUARTER-DIAMONDS & KEYSTONE (r = 0..30) ---
  let dUL = r + Math.floor(cc * 0.78);
  let dUR = r + Math.floor((COLS - 1 - cc) * 0.78);
  let dCorner = Math.min(dUL, dUR);

  if (dCorner <= 27) {
    if (dCorner >= 25) return MAT_CHARCOAL;
    if (dCorner >= 20) return MAT_CREAM;
    if (dCorner >= 18) return MAT_BRICK_DEEP;
    if (dCorner >= 12) return MAT_GREY;
    if (dCorner >= 9) return MAT_CHARCOAL;
    if (dCorner >= 4) return MAT_BRICK;
    return MAT_CREAM;
  }

  // Upper Central Stepped Keystone (r = 0..13, centered at c = 47)
  let dTopKey = r + Math.floor(Math.abs(cc - 47) * 0.9);
  if (dTopKey <= 12) {
    if (dTopKey >= 10) return MAT_CHARCOAL;
    if (dTopKey >= 6) return MAT_GREY_LIGHT;
    if (dTopKey >= 3) return MAT_BRICK_DEEP;
    return MAT_CREAM;
  }

  // --- C. LATERAL SERRATED HALF-DIAMONDS (Flanking Canyon Buttresses at r = 84) ---
  // Deeply serrated zig-zag erosion steps on left (c = 0) and right (c = 93)
  let sawtooth = ((Math.floor(r / 3) % 2) === 0) ? 3 : 0;
  let dLeft = Math.abs(r - 84) + Math.floor(cc * 0.85) - sawtooth;
  let dRight = Math.abs(r - 84) + Math.floor((COLS - 1 - cc) * 0.85) - sawtooth;
  let dFlank = Math.min(dLeft, dRight);

  if (dFlank <= 32) {
    if (dFlank >= 30) return (r < 84) ? MAT_CHARCOAL : MAT_CREAM;
    if (dFlank >= 25) return MAT_GREY;
    if (dFlank >= 23) return MAT_CHARCOAL;
    if (dFlank >= 17) return MAT_BRICK;
    if (dFlank >= 14) return MAT_CREAM;
    if (dFlank >= 9) return MAT_BRICK_DEEP;
    if (dFlank >= 6) return MAT_GREY_LIGHT;
    if (dFlank >= 3) return MAT_CHARCOAL;
    return MAT_CREAM;
  }

  // --- D. LOWER MONUMENTAL STEPPED-DIAMOND PEDIMENT (Centered at r = 122, c = 47) ---
  let serrationBot = ((Math.floor(r / 2) % 2) === 0) ? 1 : 0;
  let dBot = Math.abs(r - 122) + Math.floor(Math.abs(cc - 47) * 0.82) - serrationBot;

  if (dBot <= 31) {
    if (dBot >= 29) return (r < 122) ? MAT_CREAM : MAT_CHARCOAL;
    if (dBot >= 24) return MAT_BRICK_DEEP;
    if (dBot >= 21) return MAT_GREY_LIGHT;
    if (dBot >= 19) return MAT_CHARCOAL;
    if (dBot >= 13) return MAT_CREAM;
    if (dBot >= 10) return MAT_BRICK;
    if (dBot >= 6) return MAT_GREY;
    if (dBot >= 4) return MAT_CHARCOAL;
    return MAT_BRICK_DEEP;
  }

  // --- E. LOWER CORNER TALUS PYRAMIDS (r = 115..140, c near 0 and 93) ---
  let dBL = (ROWS - 1 - r) + Math.floor(cc * 0.85);
  let dBR = (ROWS - 1 - r) + Math.floor((COLS - 1 - cc) * 0.85);
  let dBotCorner = Math.min(dBL, dBR);
  if (dBotCorner <= 22) {
    if (dBotCorner >= 20) return MAT_CREAM;
    if (dBotCorner >= 15) return MAT_CHARCOAL;
    if (dBotCorner >= 10) return MAT_GREY;
    if (dBotCorner >= 5) return MAT_BRICK_DEEP;
    return MAT_CHARCOAL;
  }

  // --- F. HORIZONTAL SEDIMENTARY STRATA & CRENELLATED TERRACES (Background Matrix) ---
  // Crenellated horizontal bedding: occasional 1-row stepped notches along bedding planes
  let cren = (Math.floor(cc / 6) % 2 === 0) ? 1 : 0;
  let rEff = r + cren * ((r % 12 === 0) ? 1 : 0);

  if (rEff < 8) return MAT_CREAM;
  if (rEff < 11) return MAT_CHARCOAL;
  if (rEff < 16) return MAT_GREY_LIGHT;
  if (rEff < 22) return MAT_BRICK;
  if (rEff < 25) return MAT_CREAM;
  if (rEff < 33) return MAT_BRICK_DEEP;
  if (rEff < 38) return MAT_GREY;
  if (rEff < 44) return MAT_CREAM;
  if (rEff < 50) return MAT_BRICK;
  if (rEff < 54) return MAT_CHARCOAL;
  if (rEff < 61) return MAT_CREAM;
  if (rEff < 68) return MAT_GREY;
  if (rEff < 75) return MAT_BRICK;
  if (rEff < 79) return MAT_CREAM;
  if (rEff < 83) return MAT_CHARCOAL;
  if (rEff < 89) return MAT_GREY_LIGHT;
  if (rEff < 95) return MAT_BRICK_DEEP;
  if (rEff < 101) return MAT_CREAM;
  if (rEff < 104) return MAT_CHARCOAL;
  if (rEff < 111) return MAT_BRICK;
  if (rEff < 118) return MAT_GREY;
  if (rEff < 125) return MAT_CREAM;
  if (rEff < 132) return MAT_BRICK_DEEP;
  if (rEff < 136) return MAT_GREY;
  return MAT_CHARCOAL;
}

// =============================================================================
// 2. DESERT VARNISH STREAK SYSTEM (Manganese & Iron Oxide Weeping)
// =============================================================================

function buildDesertVarnish() {
  for (let r = 0; r < ROWS; r++) {
    varnishMap[r] = new Array(COLS).fill(0);
  }

  // Spawn vertical desert varnish streaks from step transitions & alcove drainage notches
  for (let r = 4; r < ROWS - 12; r++) {
    for (let c = 3; c < COLS - 3; c++) {
      let mAbove = gridMat[r - 1][c];
      let mHere = gridMat[r][c];

      // Varnish forms prominently on sheer Cream, Brick, and Grey faces below ledges
      if (
        mAbove !== mHere &&
        (mHere === MAT_CREAM || mHere === MAT_BRICK || mHere === MAT_GREY || mHere === MAT_GREY_LIGHT)
      ) {
        let seedVal = noise(c * 0.35, r * 0.25);
        if (seedVal > 0.46) {
          // Trace how far down this rock face continues before hitting a dark overhang break
          let maxLen = 0;
          for (let rr = r; rr < Math.min(ROWS - 1, r + 34); rr++) {
            if (gridMat[rr][c] === MAT_CHARCOAL && rr > r + 3) break;
            maxLen++;
          }

          if (maxLen >= 4) {
            let streakLen = Math.min(maxLen, Math.floor(random(5, 28)));
            let strength = map(seedVal, 0.46, 1.0, 0.35, 0.95);
            let widthCols = random() < 0.35 ? 2 : 1;

            varnishStreaks.push({
              rStart: r,
              rEnd: r + streakLen,
              cCenter: c,
              widthCols: widthCols,
              strength: strength,
              subThreads: Math.floor(random(3, 7))
            });

            for (let rr = r; rr < r + streakLen; rr++) {
              let t = (rr - r) / streakLen;
              let falloff = Math.pow(1.0 - t, 0.75);
              for (let dc = 0; dc < widthCols; dc++) {
                let cc = constrain(c + dc, 0, COLS - 1);
                varnishMap[rr][cc] = Math.max(varnishMap[rr][cc], strength * falloff);
              }
            }
          }
        }
      }
    }
  }
}

// =============================================================================
// 3. PAPER GROUND & SELVEDGE CORD PREPARATION
// =============================================================================

function renderPaperSelvedge() {
  // Subtle paper fiber grain around the perimeter margin
  brush.noFill();
  brush.set("2H", PALETTE.paperGrain, 0.5);
  for (let i = 0; i < 120; i++) {
    let y = random(8, CANVAS_H - 8);
    let x1 = random(8, MARGIN_X + 10);
    let x2 = random(CANVAS_W - MARGIN_X - 10, CANVAS_W - 8);
    brush.line(x1, y, x1 + random(10, 24), y);
    brush.line(x2 - random(10, 24), y, x2, y);
  }
}

// =============================================================================
// 4. BASE WASHES & TRUNCATED AEOLIAN CROSS-BEDDING
// =============================================================================

function renderSteppedBaseWashes() {
  // Group contiguous horizontal cells per row into crisp stepped rectangles
  // Batch by material ID for optimal p5.brush fill/wash caching
  brush.noStroke();

  let matOrder = [MAT_CREAM, MAT_GREY_LIGHT, MAT_GREY, MAT_BRICK, MAT_BRICK_DEEP, MAT_CHARCOAL];

  for (let mIdx = 0; mIdx < matOrder.length; mIdx++) {
    let targetMat = matOrder[mIdx];
    let baseCol = PALETTE[targetMat].mid;
    brush.wash(baseCol, 235);

    for (let r = 0; r < ROWS; r++) {
      let c = 0;
      while (c < COLS) {
        if (gridMat[r][c] === targetMat) {
          let cStart = c;
          while (c < COLS && gridMat[r][c] === targetMat) {
            c++;
          }
          let x = MARGIN_X + cStart * STEP_X;
          let y = MARGIN_Y + r * STEP_Y;
          let w = (c - cStart) * STEP_X;
          brush.rect(x, y, w, STEP_Y + 0.8, "corner");
        } else {
          c++;
        }
      }
    }
  }
  brush.noWash();
}

function renderCrossBedding() {
  // Inside thicker Cream and Brick sandstone strata, draw subtle diagonal aeolian dune laminae
  // truncated crisply by the horizontal bedding planes before the main weft locks over them
  for (let r = 1; r < ROWS - 1; r++) {
    let c = 0;
    while (c < COLS) {
      let mat = gridMat[r][c];
      let cStart = c;
      while (c < COLS && gridMat[r][c] === mat) c++;
      let spanCols = c - cStart;

      if ((mat === MAT_CREAM || mat === MAT_BRICK) && spanCols >= 6) {
        // Check if row above has same material (thick sandstone lens)
        if (gridMat[r - 1][Math.floor((cStart + c) / 2)] === mat && random() < 0.55) {
          let xLeft = MARGIN_X + cStart * STEP_X;
          let xRight = MARGIN_X + c * STEP_X;
          let yTop = MARGIN_Y + (r - 1) * STEP_Y;
          let yBot = MARGIN_Y + (r + 1) * STEP_Y;

          let lamCol = (mat === MAT_CREAM) ? PALETTE[MAT_CREAM].dark : PALETTE[MAT_BRICK].dark;
          brush.set("2H", lamCol, 0.45);

          let dir = (r % 20 < 10) ? 1 : -1;
          let spacing = 9;
          for (let lx = xLeft + 8; lx < xRight - 14; lx += spacing) {
            let x1 = lx;
            let x2 = constrain(lx + dir * 18, xLeft + 2, xRight - 2);
            brush.line(x1, yTop + 1.5, x2, yBot - 1.5);
          }
        }
      }
    }
  }
}

// =============================================================================
// 5. PACKED HORIZONTAL WEFT ENGINE (The Heart of the Piece)
// =============================================================================

function renderPackedHorizontalWeft() {
  // Every 8px-tall step-row is packed with tight horizontal weft courses:
  // Course A (y + 1.8) & Course C (y + 5.8): Chisel-edge marker weft ("weft_marker")
  // Course B (y + 0.8, y + 3.8, y + 6.9): Dry pencil/charcoal weft ("weft_pencil", "cpencil", "charcoal")

  for (let r = 0; r < ROWS; r++) {
    let yBase = MARGIN_Y + r * STEP_Y;

    // Extract contiguous horizontal spans [cStart, cEnd) for this row
    let spans = [];
    let c = 0;
    while (c < COLS) {
      let mat = gridMat[r][c];
      let cStart = c;
      while (c < COLS && gridMat[r][c] === mat) c++;
      spans.push({ mat: mat, cStart: cStart, cEnd: c });
    }

    // --- PASS 1: CHISEL MARKER WEFT COURSES ---
    let markerOffsets = [1.9, 5.7];
    for (let m = 0; m < markerOffsets.length; m++) {
      let y = yBase + markerOffsets[m];

      for (let s = 0; s < spans.length; s++) {
        let sp = spans[s];
        let pal = PALETTE[sp.mat];

        // Subdivide wide spans into natural shuttle-throw weft segments (4 to 10 columns wide)
        // or break wherever desert varnish intensity shifts significantly
        let curC = sp.cStart;
        while (curC < sp.cEnd) {
          let segCols = Math.min(sp.cEnd - curC, Math.floor(random(4, 11)));
          // If varnish spikes inside this segment, break tightly so varnish weaves into the weft
          for (let k = 1; k < segCols; k++) {
            if (Math.abs(varnishMap[r][curC + k] - varnishMap[r][curC]) > 0.28) {
              segCols = k;
              break;
            }
          }

          let x1 = MARGIN_X + curC * STEP_X;
          let x2 = MARGIN_X + (curC + segCols) * STEP_X;

          // Determine weft color modulated by sedimentary lamina noise & desert varnish
          let vLevel = varnishMap[r][curC + Math.floor(segCols / 2)];
          let nVal = noise(curC * 0.12, r * 0.45 + m * 3.1);

          let strokeCol = selectWeftColor(sp.mat, pal, nVal, vLevel, m === 0);
          let weightMult = map(nVal, 0, 1, 0.82, 1.15);

          brush.set("weft_marker", strokeCol, weightMult);
          brush.line(x1 + 0.4, y, x2 - 0.4, y);

          curC += segCols;
        }
      }
    }

    // --- PASS 2: TIGHT GRAPHITE, COLOURED PENCIL & CHARCOAL WEFT COURSES ---
    let pencilOffsets = [0.7, 3.8, 7.0];
    for (let p = 0; p < pencilOffsets.length; p++) {
      let y = yBase + pencilOffsets[p];

      for (let s = 0; s < spans.length; s++) {
        let sp = spans[s];
        let pal = PALETTE[sp.mat];

        let curC = sp.cStart;
        while (curC < sp.cEnd) {
          let segCols = Math.min(sp.cEnd - curC, Math.floor(random(3, 9)));
          for (let k = 1; k < segCols; k++) {
            if (Math.abs(varnishMap[r][curC + k] - varnishMap[r][curC]) > 0.25) {
              segCols = k;
              break;
            }
          }

          let x1 = MARGIN_X + curC * STEP_X;
          let x2 = MARGIN_X + (curC + segCols) * STEP_X;
          let vLevel = varnishMap[r][curC + Math.floor(segCols / 2)];
          let nVal = noise(curC * 0.18 + p * 7.3, r * 0.65);

          let strokeCol = selectPencilWeftColor(sp.mat, pal, nVal, vLevel, p);
          let brushName = "weft_pencil";
          let wMult = 0.85;

          if (sp.mat === MAT_CHARCOAL || vLevel > 0.65) {
            brushName = (p === 1) ? "charcoal" : "2B";
            wMult = (brushName === "charcoal") ? 0.48 : 0.65;
          } else if (sp.mat === MAT_CREAM) {
            brushName = (p === 0) ? "cpencil" : "weft_pencil";
            wMult = (brushName === "cpencil") ? 0.58 : 0.82;
          } else {
            brushName = (p === 2) ? "cpencil" : "weft_pencil";
            wMult = (brushName === "cpencil") ? 0.62 : 0.88;
          }

          brush.set(brushName, strokeCol, wMult);
          let yJitter = random(-0.22, 0.22);
          brush.line(x1 + 0.3, y + yJitter, x2 - 0.3, y - yJitter);

          curC += segCols;
        }
      }
    }
  }
}

function selectWeftColor(mat, pal, nVal, vLevel, isUpperCourse) {
  // Heavy desert varnish shifts the weft toward manganese charcoal-slate or dark hematite
  if (vLevel > 0.72) {
    return isUpperCourse ? PALETTE[MAT_CHARCOAL].mid : PALETTE[MAT_CHARCOAL].light;
  }
  if (vLevel > 0.42) {
    if (mat === MAT_BRICK || mat === MAT_BRICK_DEEP) return PALETTE[MAT_BRICK_DEEP].shadow;
    return PALETTE[MAT_GREY].shadow;
  }
  if (vLevel > 0.22) {
    return pal.dark;
  }

  // Natural wool abrash / sedimentary lamina variation
  if (nVal < 0.28) return pal.light;
  if (nVal < 0.58) return pal.mid;
  if (nVal < 0.80) return pal.warm;
  return pal.dark;
}

function selectPencilWeftColor(mat, pal, nVal, vLevel, courseIdx) {
  if (vLevel > 0.62) {
    return (courseIdx === 1) ? PALETTE[MAT_CHARCOAL].dark : PALETTE[MAT_CHARCOAL].mid;
  }
  if (vLevel > 0.32) {
    return pal.shadow;
  }

  if (courseIdx === 0 && nVal > 0.55) return pal.grainLight;
  if (courseIdx === 1) return (nVal > 0.5) ? pal.dark : pal.warm;
  return (nVal < 0.45) ? pal.light : pal.grainDark;
}

// =============================================================================
// 6. HYPERREAL DESERT VARNISH CURTAINS (Micro-streaking & Mineral Sheen)
// =============================================================================

function renderDesertVarnishDetail() {
  // Over the woven weft, desert varnish deposits vertical mineral seepage lines
  // and tight horizontal manganese cross-ticks where water clings to sandstone grain
  for (let i = 0; i < varnishStreaks.length; i++) {
    let vs = varnishStreaks[i];
    let xLeft = MARGIN_X + vs.cCenter * STEP_X;
    let xRight = xLeft + vs.widthCols * STEP_X;

    // 1. Tight horizontal mineral dark-weft intensifiers inside the streak
    for (let r = vs.rStart; r < vs.rEnd; r++) {
      let t = (r - vs.rStart) / (vs.rEnd - vs.rStart);
      if (random() < (1.0 - t * 0.75) * vs.strength) {
        let y = MARGIN_Y + r * STEP_Y + random(1.2, 6.8);
        let streakW = (xRight - xLeft) * map(1.0 - t, 0, 1, 0.35, 0.95);
        let xMid = (xLeft + xRight) * 0.5 + random(-1.5, 1.5);

        let vCol = (t < 0.45) ? PALETTE[MAT_CHARCOAL].dark : PALETTE[MAT_CHARCOAL].light;
        brush.set("mineral_grain", vCol, map(1.0 - t, 0, 1, 0.55, 1.05));
        brush.line(xMid - streakW * 0.5, y, xMid + streakW * 0.5, y);
      }
    }

    // 2. Delicate vertical weeping mineral threads connecting the horizontal beds
    let numThreads = vs.subThreads;
    for (let th = 0; th < numThreads; th++) {
      let tx = map(th, 0, numThreads - 1, xLeft + 1.5, xRight - 1.5) + random(-0.8, 0.8);
      let y1 = MARGIN_Y + vs.rStart * STEP_Y;
      let reach = (vs.rEnd - vs.rStart) * STEP_Y * random(0.45, 1.0);
      let y2 = y1 + reach;

      let threadCol = (th % 2 === 0) ? PALETTE[MAT_CHARCOAL].mid : PALETTE[MAT_GREY].shadow;
      brush.set("2H", threadCol, random(0.32, 0.52));
      brush.line(tx, y1, tx + random(-0.6, 0.6), y2);
    }
  }
}

// =============================================================================
// 7. CRISP STAIR-STEPPED BOUNDARIES & FLAT MIDDAY LIGHTING
// =============================================================================

function renderSteppedLedgesAndShadows() {
  // The light is flat midday (straight down):
  // - Protruding horizontal step treads catch blazing undyed cream/buff highlights on their top edge
  // - Overhanging step lips cast razor-sharp charcoal-black shadows directly below
  // - Vertical step risers (where column boundaries step) get crisp architectural definition

  for (let r = 1; r < ROWS; r++) {
    let yStep = MARGIN_Y + r * STEP_Y;

    // Scan horizontal step boundaries along row r
    let c = 0;
    while (c < COLS) {
      let sType = gridStepType[r][c];
      if (sType !== 0) {
        let cStart = c;
        let matHere = gridMat[r][c];
        while (c < COLS && gridStepType[r][c] === sType && gridMat[r][c] === matHere) {
          c++;
        }

        let x1 = MARGIN_X + cStart * STEP_X;
        let x2 = MARGIN_X + c * STEP_X;

        if (sType === 1) {
          // SUNLIT LEDGE TOP (Flat midday light hitting the horizontal sandstone step tread)
          let hiCol = PALETTE[matHere].highlight;
          if (matHere === MAT_CREAM || matHere === MAT_GREY_LIGHT) {
            hiCol = PALETTE[MAT_CREAM].highlight;
          }

          // Bright sunlit lip
          brush.set("weft_marker", hiCol, 0.68);
          brush.line(x1 + 0.3, yStep + 0.9, x2 - 0.3, yStep + 0.9);

          brush.set("cpencil", PALETTE[MAT_CREAM].grainLight, 0.52);
          brush.line(x1 + 0.3, yStep + 0.4, x2 - 0.3, yStep + 0.4);

          // Crisp micro-bedding shadow line right above the step crease
          brush.set("rotring", PALETTE[MAT_CHARCOAL].mid, 0.38);
          brush.line(x1, yStep - 0.2, x2, yStep - 0.2);

        } else if (sType === -1) {
          // OVERHANG LIP (Flat midday cast shadow plunging beneath the ledge)
          brush.set("weft_marker", PALETTE[MAT_CHARCOAL].shadow, 0.85);
          brush.line(x1 + 0.2, yStep + 1.1, x2 - 0.2, yStep + 1.1);

          brush.set("charcoal", PALETTE[MAT_CHARCOAL].dark, 0.48);
          brush.line(x1 + 0.4, yStep + 2.4, x2 - 0.4, yStep + 2.4);

          // Razor-sharp overhang crease
          brush.set("rotring", PALETTE[MAT_CHARCOAL].grainDark, 0.45);
          brush.line(x1, yStep, x2, yStep);
        }
      } else {
        c++;
      }
    }

    // Scan vertical stair-step risers within row r (where column c-1 != column c)
    for (let col = 1; col < COLS; col++) {
      let mLeft = gridMat[r][col - 1];
      let mRight = gridMat[r][col];
      if (mLeft !== mRight) {
        let xRiser = MARGIN_X + col * STEP_X;
        let y1 = yStep;
        let y2 = yStep + STEP_Y;

        // Crisp vertical step-joint line
        brush.set("rotring", PALETTE[MAT_CHARCOAL].mid, 0.42);
        brush.line(xRiser, y1, xRiser, y2);

        // Subtle sunlit vertical edge highlight on the brighter block's corner
        let leftBrighter = (mLeft === MAT_CREAM || mLeft === MAT_GREY_LIGHT);
        let hiX = leftBrighter ? xRiser - 0.8 : xRiser + 0.8;
        brush.set("2H", PALETTE[MAT_CREAM].highlight, 0.4);
        brush.line(hiX, y1 + 0.6, hiX, y2 - 0.6);
      }
    }
  }
}

// =============================================================================
// 8. MICRO-GEOLOGY: TAFONI PITTING, JOINT FRACTURES & SANDSTONE GRAIN
// =============================================================================

function renderMicroGeology() {
  // A. Aeolian Sandstone Grain Stipple (Sparse controlled spray & mineral ticks inside bands)
  for (let r = 2; r < ROWS - 2; r += 2) {
    for (let c = 2; c < COLS - 2; c += 3) {
      let mat = gridMat[r][c];
      if (random() < 0.38) {
        let x = MARGIN_X + c * STEP_X + random(1, STEP_X * 2.5);
        let y = MARGIN_Y + r * STEP_Y + random(1, STEP_Y - 1);
        let gCol = (random() < 0.5) ? PALETTE[mat].grainDark : PALETTE[mat].grainLight;

        brush.set("spray", gCol, random(0.22, 0.38));
        brush.line(x, y, x + random(6, 18), y);
      }
    }
  }

  // B. Honeycomb Weathering / Tafoni Pockets (Clustered beneath overhang roofs in Brick & Cream beds)
  for (let r = 8; r < ROWS - 10; r++) {
    for (let c = 4; c < COLS - 4; c++) {
      if (gridStepType[r][c] === -1 || (r > 1 && gridStepType[r - 1][c] === -1)) {
        let mat = gridMat[r][c];
        if ((mat === MAT_BRICK || mat === MAT_CREAM || mat === MAT_GREY) && random() < 0.28) {
          let numPockets = Math.floor(random(2, 6));
          for (let p = 0; p < numPockets; p++) {
            let px = MARGIN_X + c * STEP_X + random(1.5, STEP_X - 1.5);
            let py = MARGIN_Y + r * STEP_Y + random(2.0, STEP_Y - 1.2);
            let pw = random(1.4, 3.2);

            // Dark pit interior
            brush.set("rotring", PALETTE[MAT_CHARCOAL].dark, 0.55);
            brush.line(px - pw * 0.5, py, px + pw * 0.5, py);

            // Tiny sunlit lower lip of the pocket
            brush.set("2H", PALETTE[mat].highlight, 0.35);
            brush.line(px - pw * 0.4, py + 0.7, px + pw * 0.4, py + 0.7);
          }
        }
      }
    }
  }

  // C. Hairline Vertical Conjugate Joint Fractures (Stepping through individual strata)
  for (let f = 0; f < 28; f++) {
    let rStart = Math.floor(random(6, ROWS - 16));
    let cPos = Math.floor(random(6, COLS - 6));
    let startMat = gridMat[rStart][cPos];

    if (startMat !== MAT_CHARCOAL) {
      let x = MARGIN_X + cPos * STEP_X + random(2, STEP_X - 2);
      let rEnd = rStart;
      while (rEnd < ROWS - 2 && gridMat[rEnd][cPos] === startMat && rEnd - rStart < 8) {
        rEnd++;
      }

      if (rEnd - rStart >= 2) {
        let y1 = MARGIN_Y + rStart * STEP_Y + 0.5;
        let y2 = MARGIN_Y + rEnd * STEP_Y - 0.5;

        // Hairline shadow fissure
        brush.set("rotring", PALETTE[MAT_CHARCOAL].mid, 0.34);
        brush.line(x, y1, x + random(-0.8, 0.8), y2);

        // Micro highlight on adjacent lip
        brush.set("2H", PALETTE[startMat].highlight, 0.32);
        brush.line(x + 0.7, y1 + 1, x + 0.7, y2 - 1);
      }
    }
  }
}

// =============================================================================
// 9. THE TINY JUNIPER CLINGING TO A STEPPED LEDGE (Monumental Scale Anchor)
// =============================================================================

function renderClingingJuniper(ledgeX, ledgeY) {
  // Positioned on a prominent sunlit Cream & Brick stepped terrace on the lower-right
  // flank of the Great Central Diamond.
  // The tree is ~72px wide and ~54px tall, establishing the 300-foot scale of the cliff wall.

  let jp = PALETTE.juniper;

  // 1. Reinforce the sunlit sandstone step-tread directly beneath the juniper
  brush.set("weft_marker", PALETTE[MAT_CREAM].highlight, 0.85);
  brush.line(ledgeX - 42, ledgeY + 0.8, ledgeX + 46, ledgeY + 0.8);
  brush.set("weft_pencil", PALETTE[MAT_CREAM].light, 0.75);
  brush.line(ledgeX - 38, ledgeY + 2.4, ledgeX + 42, ledgeY + 2.4);

  // 2. Deep root-fissure crack where the juniper anchors into the horizontal bedding joint
  brush.set("rotring", PALETTE[MAT_CHARCOAL].shadow, 0.65);
  brush.line(ledgeX - 26, ledgeY, ledgeX + 22, ledgeY);
  brush.line(ledgeX - 8, ledgeY, ledgeX - 14, ledgeY + 7);
  brush.line(ledgeX + 4, ledgeY, ledgeX + 11, ledgeY + 6);

  // 3. Flat Midday Cast Shadow directly beneath the canopy on the sunlit ledge & step riser
  let shadowSpans = [
    { x1: -28, x2: 32, dy: 1.4, col: PALETTE[MAT_CHARCOAL].dark },
    { x1: -24, x2: 36, dy: 2.8, col: PALETTE[MAT_CHARCOAL].mid },
    { x1: -18, x2: 28, dy: 4.2, col: PALETTE[MAT_CHARCOAL].light },
    { x1: -10, x2: 22, dy: 5.6, col: PALETTE[MAT_GREY].shadow }
  ];
  for (let s of shadowSpans) {
    brush.set("weft_pencil", s.col, 0.75);
    brush.line(ledgeX + s.x1, ledgeY + s.dy, ledgeX + s.x2, ledgeY + s.dy);
  }

  // 4. Scattered talus pebbles & fallen bark fragments on the ledge around the roots
  for (let i = 0; i < 11; i++) {
    let px = ledgeX + random(-34, 38);
    let py = ledgeY + random(-0.5, 2.2);
    let pw = random(1.8, 4.2);
    brush.set("rotring", jp.woodDark, 0.45);
    brush.line(px, py, px + pw, py);
    brush.set("cpencil", PALETTE[MAT_CREAM].highlight, 0.4);
    brush.line(px, py - 0.6, px + pw * 0.8, py - 0.6);
  }

  // 5. Gnarled, wind-twisted trunk & exposed cliff roots (strip-bark Utah Juniper)
  // Root grip wedged into the rock joint
  drawTwistedLimb(ledgeX - 12, ledgeY + 5, ledgeX - 3, ledgeY - 2, jp.woodDark, jp.woodLight, 0.7);
  drawTwistedLimb(ledgeX + 9, ledgeY + 4, ledgeX + 1, ledgeY - 2, jp.woodDark, jp.woodBleach, 0.65);

  // Main gnarled trunk leaning out & twisting back toward the sheer cliff face
  drawTwistedLimb(ledgeX - 2, ledgeY, ledgeX - 7, ledgeY - 14, jp.woodDark, jp.woodMid, 0.95);
  drawTwistedLimb(ledgeX - 7, ledgeY - 14, ledgeX + 3, ledgeY - 26, jp.woodDark, jp.woodLight, 0.85);

  // Sun-bleached deadwood spire (krummholz lightning-struck snag) reaching upper-left
  drawTwistedLimb(ledgeX - 7, ledgeY - 14, ledgeX - 22, ledgeY - 29, jp.woodMid, jp.woodBleach, 0.6);
  drawTwistedLimb(ledgeX - 22, ledgeY - 29, ledgeX - 28, ledgeY - 39, jp.woodLight, jp.woodBleach, 0.42);
  drawTwistedLimb(ledgeX - 20, ledgeY - 26, ledgeX - 14, ledgeY - 35, jp.woodMid, jp.woodBleach, 0.38);

  // Secondary living branches supporting the horizontal foliage pads
  drawTwistedLimb(ledgeX - 4, ledgeY - 18, ledgeX - 21, ledgeY - 20, jp.woodDark, jp.woodMid, 0.65);
  drawTwistedLimb(ledgeX + 3, ledgeY - 26, ledgeX + 20, ledgeY - 23, jp.woodDark, jp.woodLight, 0.65);
  drawTwistedLimb(ledgeX + 1, ledgeY - 24, ledgeX + 8, ledgeY - 36, jp.woodDark, jp.woodMid, 0.55);

  // 6. Foliage Pads — Built entirely from tight horizontal weft-like strokes!
  // Each pad has a dark flat-midday underside, dense sage-olive core, and sunlit upper crown
  let pads = [
    { cx: ledgeX - 20, cy: ledgeY - 21, rx: 14, ry: 6.5 }, // Lower-left cascading pad
    { cx: ledgeX + 19, cy: ledgeY - 24, rx: 16, ry: 7.0 }, // Rightward cantilevered pad
    { cx: ledgeX - 4,  cy: ledgeY - 29, rx: 17, ry: 7.5 }, // Central dense crown mass
    { cx: ledgeX + 8,  cy: ledgeY - 37, rx: 13, ry: 6.0 }, // Upper-right sunlit crown
    { cx: ledgeX - 11, cy: ledgeY - 35, rx: 9,  ry: 4.5 }  // Small upper-left tuft
  ];

  for (let p = 0; p < pads.length; p++) {
    let pad = pads[p];
    // Scan vertically across the foliage pad in 1.1px increments with short horizontal strokes
    for (let dy = -pad.ry; dy <= pad.ry; dy += 1.1) {
      let normY = dy / pad.ry; // -1 (top sunlit crown) to +1 (bottom shaded underside)
      let halfW = pad.rx * Math.sqrt(Math.max(0, 1 - normY * normY));
      // Irregular serrated foliage silhouette
      halfW *= random(0.75, 1.18);

      if (halfW > 1.5) {
        let y = pad.cy + dy;
        let xStart = pad.cx - halfW + random(-1.5, 1.5);
        let xEnd = pad.cx + halfW + random(-1.5, 1.5);

        // Break each foliage scanline into 2 to 4 tight horizontal needle-tuft strokes
        let curX = xStart;
        while (curX < xEnd) {
          let segW = random(3.5, 8.5);
          let nx = Math.min(xEnd, curX + segW);

          // Select color by vertical midday light gradient (bright top, deep shadow bottom)
          let col;
          if (normY < -0.45) {
            col = (random() < 0.65) ? jp.foliageSun : jp.foliageLight;
          } else if (normY < 0.05) {
            col = (random() < 0.6) ? jp.foliageLight : jp.foliageMid;
          } else if (normY < 0.5) {
            col = (random() < 0.65) ? jp.foliageMid : jp.foliageDark;
          } else {
            col = (random() < 0.7) ? jp.foliageShadow : jp.foliageDark;
          }

          let bName = (normY > 0.35) ? "2B" : "cpencil";
          brush.set(bName, col, random(0.45, 0.68));
          brush.line(curX, y, nx, y);

          curX = nx + random(0.4, 1.6);
        }
      }
    }

    // Fine pen/graphite needle detail & warm scale/berry accents inside the pad
    for (let k = 0; k < 7; k++) {
      let kx = pad.cx + random(-pad.rx * 0.75, pad.rx * 0.75);
      let ky = pad.cy + random(-pad.ry * 0.65, pad.ry * 0.65);
      let kCol = (k % 3 === 0) ? jp.berry : (ky < pad.cy ? jp.foliageSun : jp.foliageShadow);
      brush.set("rotring", kCol, 0.36);
      brush.line(kx, ky, kx + random(2.0, 4.5), ky);
    }
  }
}

function drawTwistedLimb(x1, y1, x2, y2, shadowCol, litCol, weight) {
  let steps = 7;
  for (let i = 0; i < steps; i++) {
    let t1 = i / steps;
    let t2 = (i + 1) / steps;
    let lx1 = lerp(x1, x2, t1) + sin(t1 * 180) * 1.4;
    let ly1 = lerp(y1, y2, t1);
    let lx2 = lerp(x1, x2, t2) + sin(t2 * 180) * 1.4;
    let ly2 = lerp(y1, y2, t2);

    // Shaded bark underside
    brush.set("rotring", shadowCol, weight * 0.65);
    brush.line(lx1, ly1, lx2, ly2);

    // Sunlit bleached deadwood upper bark fiber
    brush.set("cpencil", litCol, weight * 0.55);
    brush.line(lx1 - 0.6, ly1 - 0.5, lx2 - 0.6, ly2 - 0.5);
  }
}

function renderTinyCreviceTuft(cx, cy) {
  // A tiny wind-scoured desert shrub/seedling in a lower-left stepped niche for scale balance
  let jp = PALETTE.juniper;
  brush.set("rotring", PALETTE[MAT_CHARCOAL].shadow, 0.5);
  brush.line(cx - 10, cy, cx + 10, cy);

  drawTwistedLimb(cx, cy, cx - 5, cy - 11, jp.woodDark, jp.woodBleach, 0.45);
  drawTwistedLimb(cx - 1, cy - 4, cx + 7, cy - 9, jp.woodDark, jp.woodLight, 0.4);

  for (let dy = -4; dy <= 3; dy += 1.2) {
    let y = cy - 10 + dy;
    let hw = 8.5 * (1 - Math.abs(dy) / 5.5);
    let col = (dy < -1) ? jp.foliageSun : (dy < 1 ? jp.foliageMid : jp.foliageShadow);
    brush.set("cpencil", col, 0.5);
    brush.line(cx - hw, y, cx + hw, y);
  }
}

// =============================================================================
// 10. SELVEDGE EDGE FINISH (Monumental Textile-Geological Framing)
// =============================================================================

function renderSelvedgeEdgeFinish() {
  // Crisp horizontal weft-turn loops / geological section ticks at the left & right boundaries
  let xLeft = MARGIN_X;
  let xRight = MARGIN_X + WALL_W;

  for (let r = 0; r < ROWS; r++) {
    let y = MARGIN_Y + r * STEP_Y;
    let mLeft = gridMat[r][0];
    let mRight = gridMat[r][COLS - 1];

    // Left selvedge weft turn
    brush.set("rotring", PALETTE[mLeft].dark, 0.42);
    brush.line(xLeft - 1.5, y + 1.5, xLeft + 2.5, y + 1.5);
    brush.line(xLeft - 1.5, y + 5.5, xLeft + 2.5, y + 5.5);
    brush.line(xLeft - 1.5, y + 1.5, xLeft - 1.5, y + 6.5);

    // Right selvedge weft turn
    brush.set("rotring", PALETTE[mRight].dark, 0.42);
    brush.line(xRight - 2.5, y + 1.5, xRight + 1.5, y + 1.5);
    brush.line(xRight - 2.5, y + 5.5, xRight + 1.5, y + 5.5);
    brush.line(xRight + 1.5, y + 1.5, xRight + 1.5, y + 6.5);
  }

  // Top rimrock highlight & basal ground anchor line
  brush.set("weft_marker", PALETTE[MAT_CREAM].highlight, 0.85);
  brush.line(xLeft, MARGIN_Y + 0.8, xRight, MARGIN_Y + 0.8);

  brush.set("rotring", PALETTE[MAT_CHARCOAL].shadow, 0.65);
  brush.line(xLeft - 1.5, MARGIN_Y + WALL_H, xRight + 1.5, MARGIN_Y + WALL_H);
}

// Shaker Oval Bentwood Boxes, Peg Rail & Hanging Chair
// Rendered in fine sepia pen and transparent milk-paint washes on cream laid paper

