  drawBoxTowerInk();

  // 9. Copper tacks (wash, dark sepia rim, facet & highlight)
  drawAllCopperTacks();

  noLoop();
}

// ============================================================================
// DATA DEFINITION: 9 GRADUATED SHAKER OVAL BENTWOOD BOXES
// ============================================================================
function buildBoxTowerData() {
  boxes = [];
  copperTacks = [];

  const specs = [
    // Bottom (No. 8) to Top (No. 0 miniature seed box)
    { id: 8, rx: 274, bodyH: 106, ell: 0.124, fingers: 5, lidFingers: 2, dir:  1, kind: "barnRed",     color: PALETTE.barnRed,     shade: PALETTE.barnRedDeep,     wood: "maple"  },
    { id: 7, rx: 236, bodyH:  95, ell: 0.118, fingers: 4, lidFingers: 1, dir: -1, kind: "maple",       color: PALETTE.maple,       shade: PALETTE.mapleDeep,       wood: "maple"  },
    { id: 6, rx: 202, bodyH:  85, ell: 0.112, fingers: 4, lidFingers: 1, dir:  1, kind: "chromeGreen", color: PALETTE.chromeGreen, shade: PALETTE.chromeGreenDeep, wood: "maple"  },
    { id: 5, rx: 171, bodyH:  76, ell: 0.106, fingers: 4, lidFingers: 1, dir: -1, kind: "buttermilk",  color: PALETTE.buttermilk,  shade: PALETTE.buttermilkDeep,  wood: "maple"  },
    { id: 4, rx: 143, bodyH:  68, ell: 0.100, fingers: 3, lidFingers: 1, dir:  1, kind: "cherry",      color: PALETTE.cherry,      shade: PALETTE.cherryDeep,      wood: "cherry" },
    { id: 3, rx: 117, bodyH:  60, ell: 0.095, fingers: 3, lidFingers: 1, dir: -1, kind: "barnRed",     color: PALETTE.barnRed,     shade: PALETTE.barnRedDeep,     wood: "cherry" },
    { id: 2, rx:  94, bodyH:  53, ell: 0.090, fingers: 3, lidFingers: 1, dir:  1, kind: "chromeGreen", color: PALETTE.chromeGreen, shade: PALETTE.chromeGreenDeep, wood: "maple"  },
    { id: 1, rx:  73, bodyH:  46, ell: 0.086, fingers: 2, lidFingers: 1, dir: -1, kind: "buttermilk",  color: PALETTE.buttermilk,  shade: PALETTE.buttermilkDeep,  wood: "maple"  },
    { id: 0, rx:  53, bodyH:  39, ell: 0.083, fingers: 2, lidFingers: 1, dir:  1, kind: "cherry",      color: PALETTE.cherry,      shade: PALETTE.cherryDeep,      wood: "cherry" }
  ];

  let curYBot = 1048;
  for (let i = 0; i < specs.length; i++) {
    let s = specs[i];
    let yBot = curYBot;
    let yTop = yBot - s.bodyH;
    let lidSkirtH = s.bodyH * 0.31;
    let lidRimY = yTop + lidSkirtH;

    let rx = s.rx;
    let ryBot = rx * s.ell;
    let ryTop = rx * (s.ell * 0.96);

    let rxLid = rx + map(i, 0, 8, 5.5, 3.0);
    let ryLid = rxLid * (s.ell * 0.98);

    boxes.push({
      index: i,
      id: s.id,
      cx: 600,
      yBot: yBot,
      yTop: yTop,
      bodyH: s.bodyH,
      lidRimY: lidRimY,
      lidSkirtH: lidSkirtH,
      rx: rx,
      ryBot: ryBot,
      ryTop: ryTop,
      rxLid: rxLid,
      ryLid: ryLid,
      numFingers: s.fingers,
      lidFingers: s.lidFingers,
      dir: s.dir,
      kind: s.kind,
      color: s.color,
      shade: s.shade,
      wood: s.wood
    });

    curYBot = yTop;
  }
}

// ============================================================================
// 1. CREAM LAID-PAPER GROUND
// ============================================================================
function drawLaidPaperGround() {
  brush.noField();
  brush.noHatch();
  brush.noStroke();

  // Gentle warm inner paper tone
  brush.fill(PALETTE.paperWarm, 45);
  brush.fillBleed(0.25, "in");
  brush.fillTexture(0.35, 0.15);
  brush.rect(64, 64, 1072, 1072, "corner");
  brush.noFill();

  // Horizontal laid wire lines (every 7px across the sheet)
  brush.set("2H", PALETTE.laidLine, 0.18);
  for (let y = 60; y <= 1140; y += 7) {
    let jit = sin(y * 3.7) * 0.4;
    brush.line(58, y + jit, 1142, y - jit);
  }

  // Vertical chain lines (every 88px on antique laid moulds)
  brush.set("2H", PALETTE.chainLine, 0.22);
  for (let x = 104; x <= 1096; x += 88) {
    brush.line(x, 58, x, 1142);
    brush.line(x + 1.5, 58, x + 1.5, 1142);
  }
}

// ============================================================================
// 2. TRANSPARENT WASHES (MILK-PAINT, MAPLE & CHERRY)
// ============================================================================
function drawAllTransparentWashes() {
  brush.noField();
  brush.noHatch();
  brush.noStroke();

  // --- A. Table Plinth Wash (Sugar Maple) ---
  drawPolyWash([
    [104, 1036], [1096, 1036], [1096, 1105], [104, 1105]
  ], PALETTE.maple, 72, 0.04, 0.30);

  // Front bevel strip of table
  drawPolyWash([
    [104, 1096], [1096, 1096], [1096, 1105], [104, 1105]
  ], PALETTE.mapleDeep, 65, 0.02, 0.25);

  // --- B. Peg Rail Wash (Sugar Maple) & 9 Turned Pegs ---
  drawPolyWash([
    [104, 108], [1096, 108], [1096, 136], [104, 136]
  ], PALETTE.maple, 82, 0.04, 0.32);

  const pegXs = [160, 270, 380, 490, 600, 710, 820, 930, 1040];
  for (let px of pegXs) {
    let pegPoly = makeEllipsePoly(px, 129, 9.2, 7.2, 16);
    drawPolyWash(pegPoly, PALETTE.cherry, 95, 0.03, 0.28);
  }

  // --- C. Hanging Shaker Chair Washes ---
  drawHangingChairWashes();

  // --- D. Ruled Inscription Marginal Color Bars & Compass Stars ---
  drawInscriptionAccentWashes();

  // --- E. Tower of 9 Graduated Shaker Oval Boxes ---
  for (let i = 0; i < boxes.length; i++) {
    let b = boxes[i];
    let nextB = (i < boxes.length - 1) ? boxes[i + 1] : null;

    // 1. Box Body Front Face Wash
    let bodyPoly = getBoxBodyPolygon(b);
    drawPolyWash(bodyPoly, b.color, 96, 0.05, 0.36);

    // 2. Lid Skirt Front Face Wash
    let skirtPoly = getLidSkirtPolygon(b);
    drawPolyWash(skirtPoly, b.color, 104, 0.05, 0.36);

    // 3. Visible Oval Lid Top Wash (trimmed cleanly around nextB)
    let lidTopPoly = getVisibleLidTopPolygon(b, nextB);
    let topTone = (b.wood === "cherry") ? PALETTE.cherry : PALETTE.maple;
    // Milk-painted boxes have a softer wash on the flat lid top so wood grain glows
    let lidTopColor = (b.kind === "maple" || b.kind === "cherry") ? topTone : b.color;
    drawPolyWash(lidTopPoly, lidTopColor, 82, 0.04, 0.32);

    // 4. Humble, even cylindrical edge shading on far left and right flanks
    let leftShadePoly = getBoxEdgeShadePolygon(b, -89, -62);
    let rightShadePoly = getBoxEdgeShadePolygon(b, 62, 89);
    drawPolyWash(leftShadePoly, b.shade, 36, 0.08, 0.22);
    drawPolyWash(rightShadePoly, b.shade, 42, 0.08, 0.22);

    // 5. Delicate contact glaze right underneath the overhanging lid rim
    let underLidPoly = getUnderLidShadowPolygon(b);
    drawPolyWash(underLidPoly, PALETTE.inkLight, 34, 0.02, 0.20);
  }

  brush.noFill();
}

function drawPolyWash(pts, col, opacity, bleed = 0.05, tex = 0.3) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, 0.22);
  brush.beginShape(0);
  for (let p of pts) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function makeEllipsePoly(cx, cy, rx, ry, steps = 24) {
  let pts = [];
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    pts.push([cx + rx * cos(a), cy + ry * sin(a)]);
  }
  return pts;
}

// ============================================================================
// POLYGON HELPERS FOR BOXES (NON-OVERLAPPING TESSELLATION)
// ============================================================================
function getBoxBodyPolygon(b) {
  let pts = [];
  // Top boundary: bottom rim of lid skirt (from left 180 deg to right 0 deg)
  for (let a = 180; a >= 0; a -= 6) {
    pts.push([b.cx + b.rx * cos(a), b.lidRimY + b.ryLid * sin(a)]);
  }
  // Bottom boundary: bottom arc of box body (from right 0 deg to left 180 deg)
  for (let a = 0; a <= 180; a += 6) {
    pts.push([b.cx + b.rx * cos(a), b.yBot + b.ryBot * sin(a)]);
  }
  return pts;
}

function getLidSkirtPolygon(b) {
  let pts = [];
  // Top boundary: front arc of lid top ellipse (left 180 to right 0)
  for (let a = 180; a >= 0; a -= 6) {
    pts.push([b.cx + b.rxLid * cos(a), b.yTop + b.ryLid * sin(a)]);
  }
  // Bottom boundary: bottom arc of lid skirt (right 0 to left 180)
  for (let a = 0; a <= 180; a += 6) {
    pts.push([b.cx + b.rxLid * cos(a), b.lidRimY + b.ryLid * sin(a)]);
  }
  return pts;
}

function getVisibleLidTopPolygon(b, nextB) {
  if (!nextB) {
    return makeEllipsePoly(b.cx, b.yTop, b.rxLid, b.ryLid, 40);
  }
  let pts = [];
  let ratio = constrain(nextB.rx / b.rxLid, -0.99, 0.99);
  let phi = acos(ratio); // in degrees [0, 90]

  // Sweep outer rim from back-left (180 + phi) around front (90) to back-right (-phi)
  for (let a = 180 + phi; a >= -phi; a -= 5) {
    pts.push([b.cx + b.rxLid * cos(a), b.yTop + b.ryLid * sin(a)]);
  }
  // Step down right side of nextB to its bottom-right corner
  pts.push([b.cx + nextB.rx, b.yTop]);
  // Follow bottom front arc of nextB from right (0) to left (180)
  for (let a = 6; a <= 174; a += 6) {
    pts.push([b.cx + nextB.rx * cos(a), b.yTop + nextB.ryBot * sin(a)]);
  }
  // Step to bottom-left corner of nextB
  pts.push([b.cx - nextB.rx, b.yTop]);
  return pts;
}

function getBoxEdgeShadePolygon(b, thStart, thEnd) {
  let pts = [];
  for (let th = thStart; th <= thEnd; th += 5) {
    pts.push(projectBoxPt(b, th, 0, true));
  }
  for (let th = thEnd; th >= thStart; th -= 5) {
    pts.push(projectBoxPt(b, th, 1, false));
  }
  return pts;
}

function getUnderLidShadowPolygon(b) {
  let pts = [];
  let drop = constrain(b.bodyH * 0.045, 2.0, 4.2);
  for (let a = 180; a >= 0; a -= 8) {
    pts.push([b.cx + b.rx * cos(a), b.lidRimY + b.ryLid * sin(a)]);
  }
  for (let a = 0; a <= 180; a += 8) {
    pts.push([b.cx + b.rx * cos(a), b.lidRimY + b.ryLid * sin(a) + drop]);
  }
  return pts;
}

// ============================================================================
// 3. OUTER ARCHITECTURAL BORDERS & COMPASS ROSETTES
// ============================================================================
function drawFramingBorders() {
  brush.noFill();
  brush.noHatch();

  // Outer rule
  brush.set("rotring", PALETTE.inkMed, 0.34);
  brush.line(56, 56, 1144, 56);
  brush.line(1144, 56, 1144, 1144);
  brush.line(1144, 1144, 56, 1144);
  brush.line(56, 1144, 56, 56);

  // Inner fine rule
  brush.set("rotring", PALETTE.inkLight, 0.20);
  brush.line(64, 64, 1136, 64);
  brush.line(1136, 64, 1136, 1136);
