function drawSymmetricalRuledInscriptions() {
  brush.noFill();
  brush.noHatch();

  const blocks = getInscriptionBlocks();
  for (let blk of blocks) {
    // Outer marginal vertical guide lines
    brush.set("rotring", PALETTE.inkLight, 0.20);
    brush.line(blk.x1, blk.y1 - 4, blk.x1, blk.y2 + 4);
    brush.line(blk.x2, blk.y1 - 4, blk.x2, blk.y2 + 4);

    // Outer ribbon frame
    let rx = blk.side === "left" ? blk.x1 - 10 : blk.x2 + 5;
    brush.set("rotring", PALETTE.inkLight, 0.16);
    brush.line(rx, blk.y1, rx + 5, blk.y1);
    brush.line(rx, blk.y2, rx + 5, blk.y2);
    brush.line(rx, blk.y1, rx, blk.y2);
    brush.line(rx + 5, blk.y1, rx + 5, blk.y2);

    // Top & bottom rubrication header rules
    brush.set("rotring", PALETTE.inkRubric, 0.22);
    brush.line(blk.x1 - 3, blk.y1, blk.x2 + 3, blk.y1);
    brush.line(blk.x1 - 3, blk.y2, blk.x2 + 3, blk.y2);

    // Rows of tidy parallel ruled lines + calligraphic waistlines & cadence ticks
    let spanY = blk.y2 - blk.y1;
    let stepY = spanY / (blk.rows + 1);

    for (let r = 1; r <= blk.rows; r++) {
      let yBase = blk.y1 + r * stepY;
      let yWaist = yBase - stepY * 0.36;

      // Primary baseline rule
      brush.set("rotring", PALETTE.inkLight, 0.19);
      brush.line(blk.x1, yBase, blk.x2, yBase);

      // Faint calligraphic x-height rule
      brush.set("rotring", PALETTE.inkFaint, 0.13);
      brush.line(blk.x1 + 6, yWaist, blk.x2 - 6, yWaist);

      // Rhythmic micro-inscription cadence marks standing in for gift-drawing script
      drawMicroInscriptionRow(blk.x1 + 12, blk.x2 - 12, yWaist, yBase, r + blk.y1);
    }

    // Small Shaker compass star medallion if present
    if (blk.rosetteY) {
      let mx = (blk.x1 + blk.x2) * 0.5;
      drawCompassRosette(mx, blk.rosetteY, 11);
    }
  }
}

function drawMicroInscriptionRow(xStart, xEnd, yTop, yBot, seedVal) {
  let w = xEnd - xStart;
  if (w < 30) return;

  // Leave tidy stanza indents on first/last rows
  let x = xStart + ((seedVal % 3 === 0) ? 14 : 4);
  let limit = xEnd - ((seedVal % 4 === 0) ? 22 : 4);

  brush.set("rotring", PALETTE.inkMed, 0.16);
  let wordIdx = 0;
  while (x < limit - 12) {
    let wordLen = 12 + ((seedVal * 17 + wordIdx * 31) % 26);
    if (x + wordLen > limit) wordLen = limit - x;

    // Tiny rhythmic pen strokes within the ruled track
    let pts = [];
    let steps = floor(wordLen / 3.2);
    for (let s = 0; s <= steps; s++) {
      let px = x + (s / max(1, steps)) * wordLen;
      let py = (s % 2 === 0) ? yBot - 0.4 : yTop + 0.5;
      if (s === 0 && wordIdx % 5 === 0) py = yTop - 1.8; // ascender
      pts.push([px, py]);
    }
    if (pts.length >= 3) {
      brush.spline(pts, 0.35);
    }

    // Occasional colon / divider dot between phrases
    if (wordIdx % 4 === 3 && x + wordLen + 5 < limit) {
      let dx = x + wordLen + 4;
      brush.line(dx, yTop + 0.5, dx, yTop + 1.2);
      brush.line(dx, yBot - 1.2, dx, yBot - 0.5);
    }

    x += wordLen + 7;
    wordIdx++;
  }
}

