// Project cylindrical coordinates (thetaDeg in [-90, 90], vFrac in [0, 1]) to 2D canvas
function projectBoxPt(b, thetaDeg, vFrac, isLid = false) {
  let s = sin(thetaDeg);
  let c = cos(thetaDeg);
  if (isLid) {
    let x = b.cx + b.rxLid * s;
    let yTop = b.yTop + b.ryLid * c;
    let yBot = b.lidRimY + b.ryLid * c;
    return [x, lerp(yTop, yBot, vFrac)];
  } else {
    let x = b.cx + b.rx * s;
    let yTop = b.lidRimY + b.ryLid * c;
    let yBot = b.yBot + b.ryBot * c;
    return [x, lerp(yTop, yBot, vFrac)];
  }
}

function drawBoxStructuralContours(b, nextB) {
  // --- A. Box Body Bottom Arc & Vertical Side Walls ---
  let botArc = [];
  for (let a = 0; a <= 180; a += 5) {
    botArc.push([b.cx + b.rx * cos(a), b.yBot + b.ryBot * sin(a)]);
  }
  brush.set("rotring", PALETTE.inkDark, 0.36);
  brush.spline(botArc, 0.25);

  // Subtle double-line bottom wood rim thickness
  let botInner = [];
  for (let a = 8; a <= 172; a += 6) {
    botInner.push([b.cx + b.rx * cos(a), b.yBot + b.ryBot * sin(a) - 2.0]);
  }
  brush.set("rotring", PALETTE.inkLight, 0.16);
  brush.spline(botInner, 0.25);

  // Left and right vertical body edges
  brush.set("rotring", PALETTE.inkDark, 0.36);
  brush.line(b.cx - b.rx, b.lidRimY, b.cx - b.rx, b.yBot);
  brush.line(b.cx + b.rx, b.lidRimY, b.cx + b.rx, b.yBot);

  // --- B. Lid Skirt Bottom Arc, Overhang Steps & Side Walls ---
  let skirtBotArc = [];
  for (let a = 0; a <= 180; a += 5) {
    skirtBotArc.push([b.cx + b.rxLid * cos(a), b.lidRimY + b.ryLid * sin(a)]);
  }
  brush.set("rotring", PALETTE.inkDark, 0.36);
  brush.spline(skirtBotArc, 0.25);

  // Bevel line along bottom edge of lid skirt
  let skirtBevel = [];
  for (let a = 6; a <= 174; a += 6) {
    skirtBevel.push([b.cx + b.rxLid * cos(a), b.lidRimY + b.ryLid * sin(a) - 2.2]);
  }
  brush.set("rotring", PALETTE.inkMed, 0.18);
  brush.spline(skirtBevel, 0.25);

  // Lid skirt side walls & overhang step onto body
  brush.set("rotring", PALETTE.inkDark, 0.34);
  brush.line(b.cx - b.rxLid, b.yTop, b.cx - b.rxLid, b.lidRimY);
  brush.line(b.cx + b.rxLid, b.yTop, b.cx + b.rxLid, b.lidRimY);
  brush.line(b.cx - b.rxLid, b.lidRimY, b.cx - b.rx, b.lidRimY + 1.5);
  brush.line(b.cx + b.rxLid, b.lidRimY, b.cx + b.rx, b.lidRimY + 1.5);

  // --- C. Visible Top Lid Ellipse & Inset Lid Board Seam ---
  let rxInset = b.rxLid - 4.2;
  let ryInset = max(2.0, b.ryLid - 1.8);

  if (!nextB) {
    // Full top oval for topmost Box #0
    brush.set("rotring", PALETTE.inkDark, 0.34);
    drawEllipseOutline(b.cx, b.yTop, b.rxLid, b.ryLid, 36);
    brush.set("rotring", PALETTE.inkMed, 0.22);
    drawEllipseOutline(b.cx, b.yTop, rxInset, ryInset, 36);
  } else {
    // Trimmed outer rim
    let ratio = constrain(nextB.rx / b.rxLid, -0.99, 0.99);
    let phi = acos(ratio);
    let outerPts = [];
    for (let a = 180 + phi; a >= -phi; a -= 5) {
      outerPts.push([b.cx + b.rxLid * cos(a), b.yTop + b.ryLid * sin(a)]);
    }
    brush.set("rotring", PALETTE.inkDark, 0.34);
    brush.spline(outerPts, 0.25);

    // Trimmed inset seam (where visible around nextB)
    let ratioIn = constrain(nextB.rx / rxInset, -0.99, 0.99);
    let phiIn = acos(ratioIn);
    let innerPts = [];
    for (let a = 180 + phiIn; a >= -phiIn; a -= 5) {
      let px = b.cx + rxInset * cos(a);
      let py = b.yTop + ryInset * sin(a);
      innerPts.push([px, py]);
    }
    brush.set("rotring", PALETTE.inkMed, 0.22);
    brush.spline(innerPts, 0.25);
  }
}

// ============================================================================
// SWALLOWTAIL FINGER GEOMETRY & COPPER TACKS
// ============================================================================
function getSwallowtailBoundaryTheta(b, isLid, vFrac) {
  let N = isLid ? b.lidFingers : b.numFingers;
  let dir = b.dir;

  // Vertical range of the fingers
  let vMin = isLid ? 0.08 : -0.05; // Top body finger tucks slightly under lid skirt
  let vMax = isLid ? 0.92 : 0.96;

  if (vFrac < vMin || vFrac > vMax) {
    return -dir * 20;
  }

  let fingerSpan = (vMax - vMin) / N;
  let k = constrain(floor((vFrac - vMin) / fingerSpan), 0, N - 1);
  let vStart = vMin + k * fingerSpan;
  let vEnd = vStart + fingerSpan;
  let vMid = (vStart + vEnd) * 0.5;
  let vHalf = fingerSpan * 0.5;

  // Authentic Shaker slight diagonal cant across successive fingers
  let thBase = -dir * (isLid ? 15 : (17 + k * 1.4));
  let thTip  =  dir * (isLid ? 20 : (24 - k * 1.3));

  let dv = abs(vFrac - vMid) / vHalf; // 0 at tip centerline, 1 at V-crotch
  let t = pow(max(0, 1 - dv * 1.02), 0.78);
  return lerp(thBase, thTip, t);
}

function isPointInSwallowtailOverlap(b, isLid, thetaDeg, vFrac, marginDeg = 0) {
  let thEdge = getSwallowtailBoundaryTheta(b, isLid, vFrac) + marginDeg * b.dir;
  if (b.dir === 1) {
    return thetaDeg <= thEdge;
  } else {
    return thetaDeg >= thEdge;
  }
}

function drawBoxSwallowtails(b) {
  // --- A. Body Swallowtail Fingers ---
  drawFingerSet(b, false);
  // --- B. Lid Skirt Swallowtail Finger(s) ---
  drawFingerSet(b, true);
}

function drawFingerSet(b, isLid) {
  let N = isLid ? b.lidFingers : b.numFingers;
  let dir = b.dir;
  let vMin = isLid ? 0.08 : -0.05;
  let vMax = isLid ? 0.92 : 0.96;
  let fingerSpan = (vMax - vMin) / N;

  let tackR = map(b.index, 0, 8, 2.7, 1.7);
  if (isLid) tackR *= 0.86;

  for (let k = 0; k < N; k++) {
    let vStart = vMin + k * fingerSpan;
    let vEnd = vStart + fingerSpan;
    let vMid = (vStart + vEnd) * 0.5;
    let vHalf = fingerSpan * 0.5;

    let thBase = -dir * (isLid ? 15 : (17 + k * 1.4));
    let thTip  =  dir * (isLid ? 20 : (24 - k * 1.3));

    // Build outer cut contour & inner skive bevel contour for finger k
    let outerPts = [];
    let innerPts = [];
    let shadowPts = [];

    let steps = 16;
    for (let s = -steps; s <= steps; s++) {
      let frac = s / steps; // -1 (top notch) to 0 (tip) to +1 (bottom notch)
      let v = vMid + frac * vHalf * 0.97;
      if (v < 0.01) continue; // Clipped under lid skirt!

      let dv = abs(frac);
      let t = pow(max(0, 1 - dv), 0.78);
      let th = lerp(thBase, thTip, t);

      outerPts.push(projectBoxPt(b, th, v, isLid));

      // Inner chamfer bevel line (3.2 deg inside the finger)
      let vIn = vMid + frac * vHalf * 0.78;
      if (vIn >= 0.02 && dv < 0.92) {
        let thIn = lerp(thBase - dir * 1.2, thTip - dir * 3.4, t);
        innerPts.push(projectBoxPt(b, thIn, vIn, isLid));
      }

      // Lower edge veneer thickness shadow
      if (frac >= -0.1) {
        let pSh = projectBoxPt(b, th + dir * 0.7, min(0.99, v + 0.022), isLid);
        shadowPts.push(pSh);
      }
    }

    // 1. Veneer thickness shadow line along lower edge of finger
    if (shadowPts.length >= 3) {
      brush.set("rotring", PALETTE.inkLight, 0.20);
      brush.spline(shadowPts, 0.25);
    }

    // 2. Primary outer swallowtail cut contour
    if (outerPts.length >= 3) {
      brush.set("rotring", PALETTE.inkDark, isLid ? 0.30 : 0.34);
      brush.spline(outerPts, 0.25);
    }

    // 3. Inner skive bevel contour
    if (innerPts.length >= 3) {
      brush.set("rotring", PALETTE.inkMed, 0.18);
      brush.spline(innerPts, 0.25);
      // Tiny miter line at tip connecting outer tip to inner bevel tip
      let pTipOut = projectBoxPt(b, thTip, vMid, isLid);
      let pTipIn  = projectBoxPt(b, thTip - dir * 3.4, vMid, isLid);
      brush.line(pTipOut[0], pTipOut[1], pTipIn[0], pTipIn[1]);
    }

    // 4. Register Copper Tacks along this finger
    if (vMid > 0.06) {
      // Tip tack
      let p1 = projectBoxPt(b, lerp(thBase, thTip, 0.70), vMid, isLid);
      copperTacks.push({ x: p1[0], y: p1[1], r: tackR });

      // Mid-finger tack
      let p2 = projectBoxPt(b, lerp(thBase, thTip, 0.34), vMid, isLid);
      copperTacks.push({ x: p2[0], y: p2[1], r: tackR });

      // Root tack in vertical seam column (for body fingers)
      if (!isLid) {
        let p3 = projectBoxPt(b, thBase - dir * 8.5, vMid, false);
        copperTacks.push({ x: p3[0], y: p3[1], r: tackR * 0.9 });
      }
    }
  }

  // Extra top/bottom seam tacks on the box body
  if (!isLid) {
    let thSeam = -dir * 26;
    let pBotTack = projectBoxPt(b, thSeam, 0.90, false);
    copperTacks.push({ x: pBotTack[0], y: pBotTack[1], r: tackR * 0.85 });
  }
}

// ============================================================================
// GROWTH RINGS & WOOD GRAIN (CLIPPED ACROSS SWALLOWTAIL JOINTS)
// ============================================================================
function drawBoxGrowthRings(b, nextB) {
  // 1. Body Growth Rings: Region A (Overlapping swallowtail band) & Region B (Under-band)
  drawBandGrowthRingFamily(b, false, true);  // Region A (inside overlap & fingers)
  drawBandGrowthRingFamily(b, false, false); // Region B (exposed under-band)

  // 2. Lid Skirt Growth Rings: Region A & Region B
  drawBandGrowthRingFamily(b, true, true);
  drawBandGrowthRingFamily(b, true, false);

  // 3. Visible Oval Lid Top Concentric/Longitudinal Growth Rings
  drawLidTopGrowthRings(b, nextB);
}

function drawBandGrowthRingFamily(b, isLid, isOverlapRegion) {
  let dir = b.dir;
  let seed = b.index * 37 + (isLid ? 100 : 0) + (isOverlapRegion ? 0 : 50);

  // Place the cathedral heartwood center on the appropriate side of the swallowtail joint
  let thCenter = isOverlapRegion
    ? -dir * (isLid ? 28 : (24 + (b.index % 3) * 8))
    :  dir * (isLid ? 36 : (38 + (b.index % 3) * 7));
  let vCenter = isLid ? 0.50 : (isOverlapRegion ? 0.54 : 0.46);

  let numRings = isLid ? 7 : round(map(b.index, 0, 8, 14, 8));
  let angleSteps = isLid ? 48 : 72;

  for (let m = 1; m <= numRings; m++) {
    let dTh = m * (isLid ? 9.5 : 7.2);
    let dV  = m * (isLid ? 0.22 : 0.105);

    // Alternate ink weight slightly between earlywood and latewood rings
    let isDarkRing = (m % 3 === 0);
    brush.set("rotring", isDarkRing ? PALETTE.inkMed : PALETTE.inkLight, isDarkRing ? 0.19 : 0.14);

    let currentSegment = [];
    for (let s = 0; s <= angleSteps; s++) {
      let a = (s / angleSteps) * 360;
      let wobbleTh = 2.0 * sin(a * 3 + seed + m * 19);
      let wobbleV  = 0.028 * cos(a * 2 - seed + m * 11);

      let th = thCenter + dTh * cos(a) + wobbleTh;
      let v  = vCenter  + dV  * sin(a) + wobbleV;

      // Check bounds on cylinder
      let inBounds = (th >= -86 && th <= 86 && v >= 0.05 && v <= 0.95);
      let inRegion = false;
      if (inBounds) {
        if (isOverlapRegion) {
          // Stop cleanly at the inner skive bevel of the swallowtail fingers!
          inRegion = isPointInSwallowtailOverlap(b, isLid, th, v, -3.6);
        } else {
          // Emerge cleanly from underneath the outer cut edge of the swallowtail fingers!
          inRegion = !isPointInSwallowtailOverlap(b, isLid, th, v, 1.0);
        }
      }

      if (inBounds && inRegion) {
        currentSegment.push(projectBoxPt(b, th, v, isLid));
      } else {
        if (currentSegment.length >= 3) {
          brush.spline(currentSegment, 0.25);
        }
        currentSegment = [];
      }
    }
    if (currentSegment.length >= 3) {
      brush.spline(currentSegment, 0.25);
    }
  }

  // Characteristic Sugar Maple bird's-eye figures or Aged Cherry pitch flecks
  if (!isLid && (b.wood === "maple" || b.wood === "cherry")) {
    brush.set("rotring", PALETTE.inkLight, 0.14);
    let numEyes = round(map(b.index, 0, 8, 9, 4));
    for (let e = 0; e < numEyes; e++) {
      let thE = isOverlapRegion
        ? -dir * (12 + ((e * 23 + seed) % 58))
        :  dir * (26 + ((e * 19 + seed) % 52));
      let vE = 0.16 + ((e * 29 + seed) % 68) * 0.01;
      let ok = isOverlapRegion
        ? isPointInSwallowtailOverlap(b, false, thE, vE, -5)
        : !isPointInSwallowtailOverlap(b, false, thE, vE, 3);
      if (ok) {
        let pE = projectBoxPt(b, thE, vE, false);
        if (b.wood === "maple") {
          // Tiny bird's-eye maple figure
          drawEllipseOutline(pE[0], pE[1], 2.2, 1.1, 10);
        } else {
          // Delicate cherry medullary ray streak
          let pE2 = projectBoxPt(b, thE + 4.5, vE, false);
          brush.line(pE[0], pE[1], pE2[0], pE2[1]);
        }
      }
    }
  }
}

function drawLidTopGrowthRings(b, nextB) {
  let rxIn = b.rxLid - 5.2;
  let ryIn = max(1.8, b.ryLid - 2.2);
  if (rxIn < 10) return;

  // Offset heartwood center slightly for natural plank look
  let offX = b.dir * rxIn * 0.18;
  let offY = ryIn * 0.12;

  let numRings = nextB ? 7 : 10;
  for (let m = 1; m <= numRings; m++) {
    let frac = m / (numRings + 0.5);
    let rX = rxIn * frac * 1.15;
    let rY = ryIn * frac * 1.15;

    brush.set("rotring", (m % 3 === 0) ? PALETTE.inkMed : PALETTE.inkLight, 0.14);

    let seg = [];
    for (let a = 0; a <= 360; a += 6) {
      let px = b.cx + offX + rX * cos(a);
      let py = b.yTop + offY + rY * sin(a);

      // Must lie inside inset lid board ellipse
      let dIn = sq((px - b.cx) / rxIn) + sq((py - b.yTop) / ryIn);
      // Must not be occluded by nextB
      let vis = (dIn <= 0.96) && isVisibleOnLidTop(px, py, b, nextB);

      if (vis) {
        seg.push([px, py]);
      } else {
        if (seg.length >= 3) {
          brush.spline(seg, 0.25);
        }
        seg = [];
      }
    }
    if (seg.length >= 3) {
      brush.spline(seg, 0.25);
    }
  }
}

function isVisibleOnLidTop(x, y, b, nextB) {
  if (!nextB) return true;
  let dx = abs(x - b.cx);
  if (dx > nextB.rx + 1.8) return true;
  let yFrontAtX = b.yTop + nextB.ryBot * sqrt(max(0, 1 - sq(dx / nextB.rx)));
  return y > yFrontAtX + 1.6;
}

// ============================================================================
// HUMBLE CYLINDRICAL EDGE ENGRAVING & UNDER-LID CONTACT HATCHING
// ============================================================================
function drawBoxEdgeEngraving(b) {
  brush.set("rotring", PALETTE.inkLight, 0.14);

  // Fine vertical engraving lines concentrated near left & right curvature of cylinder
  const edgeAngles = [-87.5, -85, -82, -78.5, -74, 72, 76.5, 80.5, 84, 86.8, 88.5];
  for (let th of edgeAngles) {
    // Lid skirt edge stroke
    let pL0 = projectBoxPt(b, th, 0.06, true);
    let pL1 = projectBoxPt(b, th, 0.94, true);
    brush.line(pL0[0], pL0[1], pL1[0], pL1[1]);

    // Body edge stroke
    let pB0 = projectBoxPt(b, th, 0.04, false);
    let pB1 = projectBoxPt(b, th, 0.96, false);
    brush.line(pB0[0], pB0[1], pB1[0], pB1[1]);
  }

  // Delicate short vertical ticks right underneath the overhanging lid skirt
  brush.set("rotring", PALETTE.inkMed, 0.15);
  let drop = constrain(b.bodyH * 0.042, 1.8, 3.8);
  for (let th = -84; th <= 84; th += 3.5) {
    let pTop = projectBoxPt(b, th, 0, false);
    brush.line(pTop[0], pTop[1], pTop[0], pTop[1] + drop);
  }
}

// ============================================================================
// 9. ALL COPPER TACKS (WASH, DARK SEPIA RIM, FACET & HIGHLIGHT)
// ============================================================================
function drawAllCopperTacks() {
  // 1. Batch warm rose-copper watercolor dot for every tack
  brush.noStroke();
  brush.fill(PALETTE.copperWash, 175);
  brush.fillBleed(0.02, "out");
  brush.fillTexture(0.20, 0.15);
  for (let t of copperTacks) {
    let pts = makeEllipsePoly(t.x, t.y, t.r, t.r, 10);
    brush.beginShape(0);
    for (let p of pts) brush.vertex(p[0], p[1]);
    brush.endShape(true);
  }
  brush.noFill();

  // 2. Crisp dark sepia circular rim & hand-cut square shank center dot
  for (let t of copperTacks) {
    brush.set("rotring", PALETTE.copperRim, 0.24);
    brush.circle(t.x, t.y, t.r, 0.04);

    // Tiny center hammer facet
    brush.set("rotring", PALETTE.copperRim, 0.20);
    brush.line(t.x - 0.5, t.y + 0.3, t.x + 0.6, t.y + 0.3);

    // Upper-left cream highlight speck
    brush.set("rotring", PALETTE.copperGlint, 0.22);
    brush.line(t.x - t.r * 0.42, t.y - t.r * 0.35, t.x - t.r * 0.12, t.y - t.r * 0.45);
  }
}

// Palette — Warm Sepia Graphite Scale & Vivid Aniline Dyes
const PAPER_BG    = "#f7f2e7";
const BORDER_WHT  = "#fbf8f1";
const IVORY       = "#fdfaf2";
const CREAM_HI    = "#f3eadb";

// Warm Sepia Graphite Tones (2H to 6B)
const SEP_2H      = "#c8b7a1";
const SEP_H       = "#a69076";
const SEP_HB      = "#846b52";
const SEP_2B      = "#614932";
const SEP_4B      = "#3f2c1b";
const SEP_6B      = "#22150b";
const SEP_INK     = "#160c05";

// Vivid, Saturated Aniline Tints (slightly mis-registered, watery)
const ANI_TURQ_1  = "#00cfd8";
const ANI_TURQ_2  = "#3aefff";
const ANI_PINK_1  = "#e04875";
const ANI_PINK_2  = "#d15b80";
const ANI_CHEEK   = "#ff1e62";
const ANI_CHEEK_2 = "#ff5488";
const ANI_BLUE_1  = "#0048ff";
const ANI_BLUE_2  = "#0095ff";
const ANI_BLUE_3  = "#00c8ff";
const ANI_GOLD    = "#ffaa00";

const MARGIN = 96;
const IMG_MIN = MARGIN;
const IMG_MAX = 1200 - MARGIN;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(1958);
  noiseSeed(1958);

  // Custom hyperreal graphite & hair brushes
  brush.add("fineHair", {
    type: "default",
    weight: 0.26,
    scatter: 0.04,
    sharpness: 0.88,
    grain: 0.35,
    opacity: 165,
    spacing: 0.14,
    pressure: [0.15, 1.0, 0.1],
    noise: 0.3
  });

  brush.add("curlLock", {
    type: "default",
    weight: 0.38,
    scatter: 0.06,
    sharpness: 0.82,
    grain: 0.45,
    opacity: 185,
    spacing: 0.14,
    pressure: [0.25, 1.15, 0.2],
    noise: 0.4
  });

  brush.add("sepiaTone", {
    type: "default",
    weight: 1.35,
    scatter: 0.75,
    sharpness: 0.22,
    grain: 0.8,
