  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAPER_BG);

  // Clip all interior drawing to the archival image area
  brush.clip([IMG_MIN, IMG_MIN, IMG_MAX, IMG_MAX]);

  // 1. Warm gelatin-silver / baryta paper base tone
  drawPaperBase();

  // 2. Sepia graphite architectural & fairground background
  drawFairgroundBackground();

  // 3. Thin, vivid, slightly mis-registered aniline watercolor tints
  //    (Sky, Barn Wall, Pennants, Ground hint — stopping short of edges)
  drawBackgroundAnilineTints();

  // 4. Deep sepia under-modeling for the Bull & Young Handler
  drawBullBaseModeling();
  drawHandlerBaseModeling();

  // 5. Foreground Aniline Tints (Rosy Cheek & Too-Bright Ribbon Blue, mis-registered)
  drawForegroundAnilineTints();

  // 6. Hyperreal Sepia Graphite Rendering: The Prize Bull
  drawBullLegsAndHooves();
  drawBullHideAndMusculature();
  drawBullDewlapAndNeckFolds();
  drawBullCurlyPollAndHead();
  drawBullHalterAndRosette();

  // 7. Hyperreal Sepia Graphite Rendering: The Young Handler in Pressed Whites
  drawYoungHandler();

  // 8. Foreground Fairground Ring Straw & Cast Shadows
  drawStrawAndGroundDetail();

  // 9. Soft Sepia Vignette inside the image frame
  drawSoftVignette();

  brush.noClip();

  // 10. Clean White Archival Border & Plate Line
  drawArchivalBorder();

  noLoop();
}

// ============================================================================
// 1. PAPER BASE
// ============================================================================
function drawPaperBase() {
  brush.noStroke();
  brush.fill(CREAM_HI, 48);
  brush.fillBleed(0.15, "in");
  brush.fillTexture(0.45, 0.2);
  brush.rect(IMG_MIN, IMG_MIN, IMG_MAX - IMG_MIN, IMG_MAX - IMG_MIN, "corner");
  brush.noFill();

  // Subtle paper fiber grain
  brush.set("sepiaTone", SEP_2H, 0.45);
  for (let i = 0; i < 90; i++) {
    let y = map(i, 0, 89, IMG_MIN + 8, IMG_MAX - 8);
