// ============================================================================
// 6. HYPERREAL SEPIA GRAPHITE RENDERING: THE PRIZE BULL
// ============================================================================
function drawBullLegsAndHooves() {
  // Far Foreleg (x: 412..456, y: 705..925) — in deep sepia shadow
  drawLegColumn(414, 705, 452, 922, true, false);

  // Far Hind Leg (x: 822..872, y: 695..930) — in deep sepia shadow
  drawLegColumn(825, 695, 868, 928, true, true);

  // Near Foreleg (x: 456..516, y: 690..948) — stocky, white sock below y: 825
  drawLegColumn(458, 690, 514, 946, false, false);

  // Near Hind Leg (x: 878..952, y: 675..952) — strong hock at y: 785, white sock below y: 825
  drawLegColumn(880, 675, 948, 950, false, true);

  // Tail and Combed White Switch (hanging at x: 988..1012, y: 405..865)
  brush.set("2B", SEP_4B, 0.55);
  for (let y = 408; y < 735; y += 3.5) {
    let x = 992 + sin((y - 408) * 0.4) * 5;
    brush.line(x - 5, y, x + 6, y + 14);
  }
  // Fluffy white tail switch (y: 725..865)
  for (let i = 0; i < 140; i++) {
    let t = i / 140;
    let sy = lerp(720, 825, t);
    let sx = 996 + random(-14, 14) * sin(t * 180);
    let len = random(28, 52);
    let ang = 90 + random(-18, 18);
    brush.set("fineHair", i % 3 === 0 ? SEP_HB : IVORY, random(0.45, 0.75));
    brush.line(sx, sy, sx + cos(ang) * len, sy + sin(ang) * len);
  }
}

function drawLegColumn(x1, y1, x2, y2, isFar, isHind) {
  let w = x2 - x1;
  let sockY = lerp(y1, y2, 0.56);
  let hoofY = y2 - 28;

  // Tonal cross-hatching along leg cylinder
  brush.noStroke();
  brush.hatchStyle("HB", isFar ? SEP_6B : SEP_4B, 0.45);
  brush.hatch(3.5, isHind ? 25 : -20, { rand: 0.04 });
  brush.beginShape(0.15);
  brush.vertex(x1, y1);
  brush.vertex(x2 + (isHind ? 14 : 4), y1);
  brush.vertex(x2 + (isHind ? 10 : 0), lerp(y1, y2, 0.42)); // hock or knee joint
  brush.vertex(x2 - 4, hoofY);
  brush.vertex(x1 + 4, hoofY);
  brush.vertex(x1 + (isHind ? 8 : -2), lerp(y1, y2, 0.42));
  brush.endShape(CLOSE);
  brush.noHatch();

  // White sock wash on near legs
  if (!isFar) {
    brush.noStroke();
    brush.wash(IVORY, 215);
    brush.rect(x1 + 2, sockY, w - 4, hoofY - sockY, "corner");
    brush.noWash();
  }

  // Fine directional leg hairs
  let steps = 95;
  for (let i = 0; i < steps; i++) {
    let py = random(y1, hoofY);
    let px = random(x1, x2);
    let isWhiteSock = !isFar && py > sockY;
    let col = isFar
      ? (random() < 0.6 ? SEP_6B : SEP_4B)
      : isWhiteSock
        ? (px < x1 + w * 0.45 ? SEP_H : IVORY)
        : (px < x1 + w * 0.5 ? SEP_4B : SEP_2B);
    brush.set("fineHair", col, random(0.4, 0.65));
    let ang = 85 + random(-15, 15);
    brush.line(px, py, px + cos(ang) * 14, py + sin(ang) * 14);
  }

  // Cloven Hoof
  brush.noStroke();
  brush.hatchStyle("2B", SEP_6B, 0.5);
  brush.hatch(2.8, 15, { rand: 0.03 });
  brush.beginShape(0.1);
  brush.vertex(x1 + 2, hoofY);
  brush.vertex(x2 - 2, hoofY);
  brush.vertex(x2 + 2, y2);
  brush.vertex(x1 - 6, y2);
  brush.endShape(CLOSE);
  brush.noHatch();

  // Keratin highlight ridges on hoof
  brush.set("fineHair", isFar ? SEP_HB : SEP_2H, 0.45);
  for (let hx = x1; hx <= x2 - 2; hx += 4.5) {
    brush.line(hx, hoofY + 2, hx - 3, y2 - 2);
  }
}

