  brush.vertex(875, 675);
  brush.vertex(785, 680);
  brush.endShape(CLOSE);
  brush.noHatch();

  // 2. Hyperreal Hide Texture — ~2,400 directional hair strokes following anatomical tracts
  //    plus groomed show-ring diagonal comb bands across the ribs and round!
  for (let i = 0; i < 2450; i++) {
    let bx = random(385, 995);
    // Top boundary of bull body at bx
    let topY = bx < 470
      ? map(bx, 385, 470, 385, 355)
      : bx < 540
        ? map(bx, 470, 540, 355, 394)
        : map(bx, 540, 995, 394, 405);
    // Bottom boundary of bull body at bx
    let botY = bx < 450
      ? map(bx, 385, 450, 620, 715)
      : bx < 860
        ? 738
        : map(bx, 860, 995, 715, 625);

    let by = random(topY + 3, botY - 3);
    let ny = (by - topY) / max(1, botY - topY); // 0 at backline, 1 at belly

    // Determine anatomical hair flow angle (degrees)
    // Cattle hair streams backward and downward on upper body, sweeping upward slightly where show-combed on ribs,
    // swirling at the flank cowlick (835, 595) and shoulder cowlick (485, 545).
    let dFlank = dist(bx, by, 835, 595);
    let dShldr = dist(bx, by, 485, 545);
    let baseAng = 15 + ny * 48 + noise(bx * 0.008, by * 0.008) * 28;
    if (dFlank < 75) {
      baseAng += map(dFlank, 0, 75, 115, 0);
    } else if (dShldr < 65) {
      baseAng -= map(dShldr, 0, 65, 85, 0);
    }
    // Show-ring diagonal comb pattern on mid-barrel (x: 560..820, ny: 0.2..0.72)
    let combWave = sin((bx * 0.55 + by * 0.45) * 2.2);

    // Determine value/color of hair based on 3D cylindrical lighting, muscle ridges, and white markings
    let isWhiteBelly = (bx > 535 && bx < 855 && by > 708) || (bx < 455 && by > 615);
    let isWhiteCrest = (bx > 410 && bx < 525 && by < topY + 18);

    // Muscle specular zones: top of shoulder (495, 445), loin ridge (y near topY + 35), rump round (915, 475)
    let specShoulder = exp(-sq(dist(bx, by, 500, 460) / 72));
    let specRump     = exp(-sq(dist(bx, by, 915, 478) / 78));
    let specLoin     = exp(-sq((by - (topY + 28)) / 32)) * (bx > 530 && bx < 950 ? 1 : 0);
    let lightVal     = constrain(0.55 - ny * 0.65 + (specShoulder + specRump + specLoin) * 0.45 + combWave * 0.08, 0, 1);

    let hairCol;
    let wMult = random(0.38, 0.68);
    if (isWhiteBelly || isWhiteCrest) {
      hairCol = random() < 0.72 ? IVORY : ( ny > 0.9 ? SEP_HB : SEP_2H );
      wMult *= 1.1;
    } else if (lightVal > 0.74) {
      hairCol = random() < 0.45 ? CREAM_HI : SEP_2H;
    } else if (lightVal > 0.52) {
      hairCol = random() < 0.5 ? SEP_H : SEP_HB;
    } else if (lightVal > 0.30) {
      hairCol = random() < 0.55 ? SEP_2B : SEP_4B;
    } else {
      hairCol = random() < 0.65 ? SEP_6B : SEP_4B;
    }

    let len = random(11, 22);
    brush.set("fineHair", hairCol, wMult);
    brush.line(bx, by, bx + cos(baseAng) * len, by + sin(baseAng) * len);
  }

  // 3. Crisp Backline & Rump Contour with fine backlit hairs
  brush.set("2B", SEP_4B, 0.55);
  brush.spline([[395, 384], [468, 354], [538, 392], [760, 395], [978, 402], [1002, 455]], 0.35);

  for (let x = 400; x <= 980; x += 4.5) {
    let y = x < 470
      ? map(x, 400, 470, 384, 354)
      : x < 538
        ? map(x, 470, 538, 354, 392)
        : map(x, 538, 980, 392, 402);
    let isCrest = x > 410 && x < 525;
    brush.set("fineHair", isCrest ? IVORY : SEP_2H, 0.48);
    brush.line(x, y + 2, x + random(3, 8), y - random(3, 6));
  }
}

