function drawBullCurlyPollAndHead() {
  // ==========================================================================
  // THE HYPERREAL CURLY POLL & WHITE HEREFORD HEAD (x: 255..430, y: 360..545)
  // ==========================================================================

  // 1. Shaded cranial planes on the head before layering curls
  brush.noStroke();
  brush.hatchStyle("HB", SEP_H, 0.36);
