  brush.vertex(428, 392);
  brush.vertex(438, 412);
  brush.vertex(416, 432);
  brush.vertex(382, 426);
  brush.endShape(CLOSE);
  brush.noFill();

  // Ear Fringe Hairs
  for (let i = 0; i < 65; i++) {
    let t = i / 65;
    let ex = lerp(384, 434, t);
    let ey = lerp(400, 412, t) + random(-10, 12);
    brush.set("fineHair", random() < 0.35 ? CREAM_HI : SEP_6B, 0.5);
    brush.line(ex, ey, ex + random(6, 14), ey + random(-5, 6));
  }

  // 3. Curved Ivory & Sepia Horns emerging from the curly poll
  // Near horn curving forward and down from (362, 382) to (298, 396)
  // Far horn peeking at top left (295, 378) to (264, 382)
  drawHorn(298, 376, 262, 382, 11, true);
  drawHorn(364, 382, 296, 398, 17, false);

  // 4. EVERY HAIR OF THE CURLY POLL (Forehead, Crown, Poll Crest & Nasal Bridge)
  //    We generate ~240 sculptural ringlet clusters. Each cluster has:
  //    - A dark sepia under-crescent shadow (SEP_6B / SEP_4B)
  //    - Mid-sepia spiral strands (SEP_HB / SEP_H)
  //    - Bright opaque ivory ringlet C-arcs and S-curls (IVORY / CREAM_HI)
  let curlCenters = [];
  // Dense crown & poll crest (silhouetted against the dark stall doorway!)
  for (let i = 0; i < 165; i++) {
    let cx = random(280, 398);
    let cy = random(362, 456);
    // Keep within curved poll dome
    let domeTop = 360 + sq((cx - 342) / 62) * 26;
    if (cy >= domeTop) {
      curlCenters.push({ x: cx, y: cy, r: random(5.5, 11.5) });
    }
  }
  // Forehead blaze down between the eyes to the nasal bridge
  for (let i = 0; i < 75; i++) {
    let cy = random(445, 502);
    let cx = map(cy, 445, 502, 325, 292) + random(-24, 24);
    curlCenters.push({ x: cx, y: cy, r: random(4.5, 8.5) });
  }

  // Sort top-to-bottom so overlapping ringlets shingle naturally
  curlCenters.sort((a, b) => a.y - b.y);

  for (let c of curlCenters) {
    let r = c.r;
    let a0 = random(0, 360);

    // 1) Deep sepia shadow crescent underneath each curl lock
    brush.set("curlLock", random() < 0.5 ? SEP_6B : SEP_4B, 0.58);
    brush.arc(c.x, c.y + 1.8, r * 0.92, 20 + random(-25, 25), 160 + random(-25, 25));

    // 2) Warm sepia mid-tone inner curl
    brush.set("fineHair", random() < 0.5 ? SEP_HB : SEP_H, 0.5);
    brush.arc(c.x + random(-1, 1), c.y, r * 0.78, a0, a0 + random(150, 240));

    // 3) Luminous Ivory-White individual curly hairs on top of the lock (3-4 strands per lock)
    for (let s = 0; s < 3; s++) {
      let sr = r * random(0.55, 1.05);
      let sa = a0 + s * 65 + random(-20, 20);
      let span = random(135, 235);
      brush.set("ivoryPencil", s === 2 ? CREAM_HI : IVORY, random(0.45, 0.78));
      brush.arc(c.x + random(-1.5, 1.5), c.y - 1.0, sr, sa, sa + span);
    }
  }

  // Halo of crisp backlit curly flyaway hairs along the poll crown against the dark doorway
  for (let i = 0; i < 70; i++) {
    let t = i / 69;
    let px = lerp(284, 398, t);
    let py = 360 + sq((px - 342) / 62) * 26 + random(-3, 4);
    let r = random(4, 7.5);
    let ang = map(t, 0, 1, 195, 345) + random(-25, 25);
