  // 5. Fine Short Facial Hairs on the White Cheek and Jaw
  for (let i = 0; i < 180; i++) {
    let fx = random(275, 378);
    let fy = random(445, 528);
    if (dist(fx, fy, 324, 444) < 18) continue; // skip eye socket
    let ang = 135 + noise(fx * 0.02, fy * 0.02) * 50;
    let isShadow = fx > 342 || fy > 508;
