    brush.line(fx, fy, fx + cos(ang) * 9, fy + sin(ang) * 9);
  }

  // 6. Deep, Soulful Bull's Eye at (324, 444)
  // Wrinkled heavy brow & lower eyelid folds
  brush.set("2B", SEP_6B, 0.55);
  brush.arc(324, 444, 15, 195, 345);
  brush.set("HB", SEP_4B, 0.45);
  brush.arc(324, 444, 18, 190, 350);
  brush.arc(324, 444, 14, 15, 165);

  // Dark eyeball
  brush.noStroke();
  brush.fill(SEP_INK, 230);
  brush.fillBleed(0.02, "in");
  brush.circle(324, 444, 9.5, 0.12);
  brush.noFill();

  // Crisp corneal specular catchlights + pale eyelashes
  brush.noStroke();
  brush.wash(IVORY, 245);
  brush.circle(321, 441, 2.8, 0.05);
  brush.circle(326, 445, 1.4, 0.05);
  brush.noWash();

  for (let i = 0; i < 9; i++) {
    let lx = map(i, 0, 8, 313, 334);
    brush.set("ivoryPencil", IVORY, 0.42);
    brush.line(lx, 436, lx - 3, 431);
  }

  // 7. Broad Square Muzzle, Nostrils & Brass Nose Ring (x: 254..312, y: 486..544)
  brush.noStroke();
  brush.fill(SEP_2B, 140);
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.65, 0.4);
  brush.beginShape(0.32);
  brush.vertex(258, 488);
  brush.vertex(304, 492);
  brush.vertex(312, 526);
  brush.vertex(292, 544);
  brush.vertex(256, 534);
  brush.endShape(CLOSE);
  brush.noFill();

  // Moist muzzle pebble texture & specular highlights
  for (let i = 0; i < 85; i++) {
    let mx = random(258, 306);
    let my = random(492, 538);
    brush.set("fineHair", random() < 0.35 ? CREAM_HI : SEP_4B, 0.42);
    brush.circle(mx, my, random(1.2, 2.4), 0.2);
  }

  // Dark nostril comma at (276, 506) & mouth line
  brush.noStroke();
  brush.fill(SEP_INK, 225);
  brush.fillBleed(0.02, "in");
  brush.beginShape(0.35);
  brush.vertex(268, 502);
  brush.vertex(284, 498);
  brush.vertex(286, 512);
  brush.vertex(272, 515);
  brush.endShape(CLOSE);
  brush.noFill();

  brush.set("2B", SEP_6B, 0.6);
  brush.spline([[258, 526], [278, 530], [302, 524]], 0.3);

  // Brass Nose Ring at (264, 524)
  brush.set("2B", SEP_6B, 0.65);
  brush.circle(263, 525, 11, 0.12);
  brush.set("ivoryPencil", CREAM_HI, 0.55);
  brush.arc(263, 525, 10.5, 130, 310);
}

function drawHorn(x1, y1, x2, y2, baseThick, isFar) {
  let steps = 22;
  for (let i = 0; i < steps; i++) {
    let t = i / (steps - 1);
    let hx = lerp(x1, x2, t);
    let hy = lerp(y1, y2, t) + sin(t * 180) * 8;
    let r = lerp(baseThick, 2.5, pow(t, 0.8));
    let col = t > 0.72 ? SEP_6B : (isFar ? SEP_2B : CREAM_HI);
    brush.set("curlLock", col, 0.65);
    brush.circle(hx, hy, r, 0.15);
    // Keratin growth ring
    if (i % 3 === 0) {
      brush.set("fineHair", SEP_4B, 0.45);
      brush.arc(hx, hy, r, 60, 250);
    }
  }
}

function drawBullHalterAndRosette() {
  // 1. Leather Show Halter (straps over nose, cheek, and behind poll)
  // Noseband from (274, 484) to (316, 518)
  drawLeatherStrap(274, 484, 318, 516, 7.5);
  // Cheek strap from noseband (306, 506) up through rosette (354, 462) to crown (386, 396)
  drawLeatherStrap(306, 506, 386, 396, 8.5);
  // Throatlatch from (354, 462) down to under-jaw (316, 522)
  drawLeatherStrap(354, 462, 314, 524, 7.0);

  // Brass halter ring under chin at (308, 520)
  brush.set("2B", SEP_6B, 0.65);
  brush.circle(308, 520, 7.5, 0.1);
  brush.set("ivoryPencil", IVORY, 0.5);
  brush.arc(308, 520, 7.5, 140, 320);

  // Leather Lead Strap held by the Young Handler (from chin ring 308, 520 to handler's hand 292, 508, with a loop hanging to 302, 610)
  brush.set("2B", SEP_6B, 0.85);
  brush.spline([[308, 520], [298, 514], [290, 506]], 0.3);
  brush.spline([[290, 506], [296, 565], [304, 618], [294, 622], [286, 565], [286, 508]], 0.35);

  // 2. THE PRIZE ROSETTE PINNED TO THE HALTER AT (354, 462)
  //    Note: Drawn in crisp hyperreal sepia graphite at (354, 462) so the electric blue aniline
  //    wash at (363, 456) visibly floats slightly off-register and stops short on the left!
  const rx = 354;
  const ry = 462;

  // Three Notched Satin Streamer Tails hanging from (rx, ry + 22) down to y: 594
  let streamers = [
    [[340, 482], [330, 578], [340, 568], [349, 582], [354, 486]], // Left tail
    [[348, 486], [348, 594], [357, 582], [366, 595], [364, 486]], // Center tail
    [[360, 484], [368, 582], [377, 570], [386, 580], [372, 480]]  // Right tail
  ];

  for (let st of streamers) {
    // Satin sheen shading
    brush.noStroke();
    brush.hatchStyle("fineHair", SEP_2B, 0.38);
    brush.hatch(2.8, 22, { rand: 0.03 });
    brush.beginShape(0.05);
    for (let pt of st) brush.vertex(pt[0], pt[1]);
    brush.endShape(CLOSE);
    brush.noHatch();

    // Crisp graphite outline of ribbon streamer
    brush.set("HB", SEP_6B, 0.52);
    brush.beginShape(0.05);
    for (let pt of st) brush.vertex(pt[0], pt[1]);
    brush.endShape(CLOSE);
  }

  // Outer & Inner Pleated Satin Ruffle Rings of the Rosette
  for (let ring of [{ rOut: 36, rIn: 24, n: 44 }, { rOut: 25, rIn: 14, n: 32 }]) {
    for (let i = 0; i < ring.n; i++) {
      let a1 = (i / ring.n) * 360;
      let a2 = ((i + 0.65) / ring.n) * 360;
      let xIn1 = rx + cos(a1) * ring.rIn;
      let yIn1 = ry + sin(a1) * ring.rIn;
      let xOut1 = rx + cos(a1) * ring.rOut;
      let yOut1 = ry + sin(a1) * ring.rOut;
      let xOut2 = rx + cos(a2) * ring.rOut;
      let yOut2 = ry + sin(a2) * ring.rOut;

      // Radial pleat shadow line
      brush.set("fineHair", i % 2 === 0 ? SEP_6B : SEP_2B, 0.48);
      brush.line(xIn1, yIn1, xOut1, yOut1);
      // Outer scalloped edge of pleat
      brush.set("HB", SEP_6B, 0.48);
      brush.line(xOut1, yOut1, xOut2, yOut2);

      // Satin highlight on upper-left pleats
      if (cos(a1 - 220) > 0.2) {
        brush.set("ivoryPencil", IVORY, 0.42);
        brush.line(
          rx + cos(a1 + 3) * (ring.rIn + 2),
          ry + sin(a1 + 3) * (ring.rIn + 2),
          rx + cos(a1 + 3) * (ring.rOut - 2),
          ry + sin(a1 + 3) * (ring.rOut - 2)
        );
      }
    }
  }

  // Central Rosette Medallion Button
  brush.noStroke();
  brush.wash(CREAM_HI, 175);
  brush.circle(rx, ry, 13.5, 0.1);
  brush.noWash();

  brush.set("2B", SEP_6B, 0.58);
  brush.circle(rx, ry, 13.5, 0.12);
  brush.set("fineHair", SEP_4B, 0.42);
  brush.circle(rx, ry, 10.5, 0.1);
  // Tiny emblem star/lettering inside button
  for (let a = 0; a < 360; a += 72) {
    brush.line(rx, ry, rx + cos(a - 90) * 6.5, ry + sin(a - 90) * 6.5);
  }
}

function drawLeatherStrap(x1, y1, x2, y2, thick) {
  let ang = atan2(y2 - y1, x2 - x1);
  let nx = -sin(ang) * (thick * 0.5);
  let ny = cos(ang) * (thick * 0.5);

  brush.noStroke();
  brush.fill(SEP_6B, 210);
  brush.fillBleed(0.02, "in");
  brush.beginShape(0);
  brush.vertex(x1 + nx, y1 + ny);
  brush.vertex(x2 + nx, y2 + ny);
  brush.vertex(x2 - nx, y2 - ny);
  brush.vertex(x1 - nx, y1 - ny);
  brush.endShape(CLOSE);
  brush.noFill();

  // White saddle-stitching along leather edges
  brush.set("ivoryPencil", CREAM_HI, 0.36);
  brush.line(x1 + nx * 0.65, y1 + ny * 0.65, x2 + nx * 0.65, y2 + ny * 0.65);
}

