// 9. SOFT VIGNETTE INSIDE THE IMAGE FRAME
// ============================================================================
function drawSoftVignette() {
  // Soft sepia corner darkening & perimeter fade inside [IMG_MIN, IMG_MIN, IMG_MAX, IMG_MAX]
  brush.noStroke();
  let corners = [
    [IMG_MIN, IMG_MIN, 1, 1],
    [IMG_MAX, IMG_MIN, -1, 1],
    [IMG_MIN, IMG_MAX, 1, -1],
    [IMG_MAX, IMG_MAX, -1, -1]
  ];

  for (let [cx, cy, dx, dy] of corners) {
    // Soft watercolor sepia corner vignette
    brush.fill(SEP_H, 42);
    brush.fillBleed(0.38, "in");
    brush.fillTexture(0.65, 0.25);
    brush.beginShape(0.35);
    brush.vertex(cx, cy);
    brush.vertex(cx + dx * 240, cy);
    brush.vertex(cx + dx * 135, cy + dy * 135);
    brush.vertex(cx, cy + dy * 240);
    brush.endShape(CLOSE);
    brush.noFill();

    // Fine diagonal graphite vignette hatching in the extreme corners
    brush.hatchStyle("2H", SEP_HB, 0.32);
    brush.hatch(4.8, dx * dy > 0 ? -45 : 45, { rand: 0.06, gradient: 0.6 });
    brush.beginShape(0.3);
    brush.vertex(cx, cy);
    brush.vertex(cx + dx * 175, cy);
    brush.vertex(cx + dx * 85, cy + dy * 85);
    brush.vertex(cx, cy + dy * 175);
    brush.endShape(CLOSE);
    brush.noHatch();
  }

  // Soft perimeter graphite shading along all 4 edges
  brush.set("sepiaTone", SEP_H, 0.65);
  for (let i = 0; i < 4; i++) {
    let inset = i * 4;
    brush.rect(IMG_MIN + inset, IMG_MIN + inset, (IMG_MAX - IMG_MIN) - inset * 2, (IMG_MAX - IMG_MIN) - inset * 2, "corner");
  }
}

