// Safe polygon wash/fill helper
function washPoly(pts, col, op) {
  if (!pts || pts.length < 3) return;
  let p = new brush.Polygon(pts);
  p.wash(col, op);
  brush.noWash();
  brush.noFill();
  brush.noStroke();
}

function watercolorPoly(pts, col, op, bleed = 0.08, tex = 0.25) {
  if (!pts || pts.length < 3) return;
  let p = new brush.Polygon(pts);
  p.fill(col, op, bleed, tex);
  brush.noFill();
  brush.noWash();
  brush.noStroke();
}

// Safe stroke helpers that always guarantee brush.set() is called
function drawLine(bName, col, w, x1, y1, x2, y2) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, w);
  brush.line(x1, y1, x2, y2);
}

function drawSpline(bName, col, w, pts, curv = 0.5) {
  if (!pts || pts.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, w);
  brush.spline(pts, curv);
}

function drawArc(bName, col, w, cx, cy, r, startA, endA) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, w);
  brush.arc(cx, cy, r, startA, endA);
}

function makeEllipsePts(cx, cy, rx, ry, steps = 28, jitter = 0) {
  let pts = [];
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let jx = jitter ? random(-jitter, jitter) : 0;
    let jy = jitter ? random(-jitter, jitter) * (ry / rx) : 0;
    pts.push([cx + cos(a) * rx + jx, cy + sin(a) * ry + jy]);
  }
  return pts;
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f3f7fb");
  brush.noField();

  // 1. VAST SKY: Smooth sprayed gradients of cold pastel cobalt to near white
  renderSkyAndHalo();

  // 2. DISTANT HORIZON: Whisper-thin frozen shoreline & ice fog
  renderDistantShore();

  // 3. FROZEN LAKE BASE: Dark translucent cobalt ice slabs & solar glare columns
  renderLakeBase();

  // 4. TRAPPED METHANE & AIR BUBBLES: Multi-depth frozen bubble stacks in clear ice
  renderTrappedBubbles();

  // 5. HYPERREAL PENCIL-DRAWN ICE CRACKS: Subsurface fracture ribbons & surface fissures
  renderIceCracks();

  // 6. WIND-SCOURED SNOW RIPPLES (SASTRUGI): Sculpted pastel drifts & crisp shadows
  renderSnowRipples();

  // 7. LONE RED ICE-FISHING SHANTY: Distant-midground focal counterpoint
  renderRedShanty();

  // 8. FOREGROUND AUGER HOLE: Deep black water, rotary ice wall & crystalline slush mound
  renderAugerHole();

  // 9. FINAL ATMOSPHERIC GLAZE: Diamond dust & biting mid-afternoon glare
  renderFinalGlaze();

  noLoop();
}

// ============================================================================
// 1. SKY, PALE SUN, 22° HALO & PARHELIA (SUNDOGS)
// ============================================================================
function renderSkyAndHalo() {
  // Base pastel sky washes from cold cobalt zenith to near-white horizon
  const skyPalette = [
    "#5b7eae", "#6486b5", "#6e90bd", "#7899c5", "#83a3cd",
    "#8eadD5", "#9ab7dc", "#a6c1e2", "#b2cbe8", "#bed4ed",
    "#cae0f2", "#d5e7f6", "#e0eef9", "#eaf4fb", "#f2f8fd", "#f9fbfd"
  ];

  let bands = 34;
  for (let i = 0; i < bands; i++) {
    let t0 = i / bands;
    let t1 = (i + 1.45) / bands;
    let y0 = t0 * HY;
    let y1 = min(HY + 6, t1 * HY);
    let cIdx = min(skyPalette.length - 1, floor(pow(t0, 0.82) * skyPalette.length));
    let col = skyPalette[cIdx];

    // Arch slightly around the sun so the zenith cobalt wraps the upper corners
    let pts = [];
    for (let x = 0; x <= W; x += 120) {
      let distSun = abs(x - SX) / (W * 0.5);
      let curve = (1 - distSun * distSun) * 26 * sin(t0 * 180);
      pts.push([x, max(0, y0 - curve)]);
    }
    for (let x = W; x >= 0; x -= 120) {
      let distSun = abs(x - SX) / (W * 0.5);
      let curve = (1 - distSun * distSun) * 26 * sin(t1 * 180);
      pts.push([x, min(HY + 8, y1 - curve)]);
    }
    washPoly(pts, col, 135);
  }

  // Darker cobalt interior inside the 22° halo (Alexander's optical sky darkening inside halo)
  for (let r = HR - 18; r > 95; r -= 26) {
    let pts = makeEllipsePts(SX, SY, r, r * 0.96, 36);
    washPoly(pts, "#7696c0", 16);
  }

  // Smooth sprayed horizontal and arched sky gradients (cold cobalt to near white)
  for (let pass = 0; pass < 165; pass++) {
    let t = pass / 165;
    let y = pow(t, 0.95) * (HY - 4);
    let cIdx = min(skyPalette.length - 1, floor(pow(t, 0.78) * skyPalette.length));
    let col = skyPalette[cIdx];

    let dip = (1 - abs(t - 0.55)) * 22;
    let pts = [
      [-20, y + random(-8, 8)],
      [W * 0.25, y - dip * 0.6 + random(-6, 6)],
      [W * 0.5, y - dip + random(-6, 6)],
      [W * 0.75, y - dip * 0.6 + random(-6, 6)],
      [W + 20, y + random(-8, 8)]
    ];

    drawSpline("sky_mist", col, random(1.1, 2.1), pts, 0.5);
    if (pass % 2 === 0) {
      drawSpline("fine_spray", col, random(0.9, 1.6), pts, 0.45);
    }
  }

  // Deep cold cobalt corner vignettes at the top of the dome
  for (let i = 0; i < 28; i++) {
    let y = random(0, 320);
    let span = map(y, 0, 320, 480, 140);
    drawLine("sky_mist", "#5073a3", 1.6, -10, y, span + random(-30, 30), y * 0.45);
    drawLine("sky_mist", "#5073a3", 1.6, W + 10, y, W - span + random(-30, 30), y * 0.45);
    if (i % 2 === 0) {
      drawLine("fine_spray", "#587bab", 1.2, 0, y, span, y * 0.5);
      drawLine("fine_spray", "#587bab", 1.2, W, y, W - span, y * 0.5);
    }
  }

  // Horizon freezing mist and blinding pale glare band
  for (let i = 0; i < 36; i++) {
    let y = map(i, 0, 35, HY - 130, HY + 4);
    let col = i < 18 ? "#e8f1f9" : "#fafcfe";
    drawLine("sky_mist", col, 1.5, -10, y, W + 10, y + random(-3, 3));
    if (i % 3 === 0) {
      drawLine("fine_spray", "#ffffff", 1.0, random(0, 200), y, random(W - 200, W), y);
    }
  }

  // PARHELIC CIRCLE: Faint horizontal circle of ice-crystal light passing through sun & sundogs
  for (let i = -5; i <= 5; i++) {
    let py = SY + i * 2.5;
    let pts = [
      [40, py - 14],
      [SX - HR, py],
      [SX, py + 1],
      [SX + HR, py],
      [W - 40, py - 14]
    ];
    let w = map(abs(i), 0, 5, 1.3, 0.45);
    drawSpline("halo_veil", "#f2f7fc", w, pts, 0.5);
    if (abs(i) <= 2) {
      drawSpline("fine_spray", "#ffffff", 0.75, pts, 0.5);
    }
  }

  // Vertical Solar Pillar (subtle ice-crystal column through the pale sun down to the lake)
  for (let i = -6; i <= 6; i++) {
    let px = SX + i * 4.5;
    let w = map(abs(i), 0, 6, 1.4, 0.4);
    drawLine("halo_veil", "#f5f9fd", w, px, SY - 240, px, HY);
    if (abs(i) <= 2) {
      drawLine("fine_spray", "#ffffff", 0.8, px, SY - 180, px, HY);
    }
  }

  // 22° HALO ARC: Thin luminous ring with faint warm-red inner refraction edge
  // Outer soft halo diffusion
  for (let dr = -14; dr <= 18; dr += 4) {
    let r = HR + dr;
    let col = dr < -4 ? "#edd2c8" : (dr < 4 ? "#f7fafd" : "#dce9f6");
    let w = map(abs(dr), 0, 18, 1.15, 0.35);
    drawArc("halo_veil", col, w, SX, SY, r, 162, 378);
    drawArc("halo_veil", col, w * 0.85, SX, SY, r, 378, 412);
    drawArc("halo_veil", col, w * 0.85, SX, SY, r, 128, 162);
  }

  // Faint pastel red/terracotta inner edge of the 22° halo (refracted closest to the sun)
  for (let pass = 0; pass < 3; pass++) {
    let rRed = HR - 5.5 + pass * 1.8;
    let redCol = pass === 0 ? "#df948a" : (pass === 1 ? "#eab0a3" : "#f4cfc2");
    drawArc("halo_veil", redCol, 0.65, SX, SY, rRed, 152, 388);
    drawArc("micro_spray", redCol, 0.55, SX, SY, rRed, 156, 384);
  }

  // Crisp, thin near-white halo arc spine
  for (let pass = 0; pass < 5; pass++) {
    let rWhite = HR + pass * 2.1;
    let col = pass < 3 ? "#ffffff" : "#eef5fc";
    drawArc("halo_veil", col, 0.85 - pass * 0.1, SX, SY, rWhite, 146, 394);
    drawArc("fine_spray", col, 0.7 - pass * 0.08, SX, SY, rWhite, 150, 390);
  }

  // Upper Tangent Arc brightening at the crown of the 22° halo (SX, SY - HR)
  for (let i = -3; i <= 3; i++) {
    let ty = SY - HR + i * 2.2;
    let pts = [
      [SX - 115, ty - 14],
      [SX - 50, ty - 3],
      [SX, ty],
      [SX + 50, ty - 3],
      [SX + 115, ty - 14]
    ];
    drawSpline("halo_veil", i < 0 ? "#ffffff" : "#f5ded4", 0.75, pts, 0.5);
  }

  // TWO BRIGHT PARHELIA (SUNDOGS) at (SX - HR, SY) and (SX + HR, SY)
  renderParhelion(SX - HR - 4, SY, -1); // Left parhelion (dir = -1 means outward is left, inner is right)
  renderParhelion(SX + HR + 4, SY, 1);  // Right parhelion (dir = +1 means outward is right, inner is left)

  // THE PALE SUN at (SX, SY)
  // Broad sprayed corona
  for (let r = 175; r >= 16; r -= 12) {
    let t = map(r, 175, 16, 0, 1);
    let col = t < 0.4 ? "#e6f0fa" : (t < 0.75 ? "#f6f9fd" : "#ffffff");
    let pts = makeEllipsePts(SX, SY, r, r * 0.95, 32);
    washPoly(pts, col, map(t, 0, 1, 14, 48));
    drawArc("fine_spray", col, map(t, 0, 1, 0.6, 1.3), SX, SY, r, 0, 360);
  }
  // Pale lemon-cream solar disk washed out in freezing brilliance
  washPoly(makeEllipsePts(SX, SY, 34, 34, 28), "#fffdf6", 160);
  washPoly(makeEllipsePts(SX, SY, 21, 21, 24), "#ffffff", 235);
  for (let a = 0; a < 360; a += 15) {
    let rad = random(24, 95);
    drawLine("halo_veil", "#ffffff", 0.7, SX, SY, SX + cos(a) * rad, SY + sin(a) * rad);
  }
}

function renderParhelion(px, py, outwardDir) {
  // outwardDir: -1 for left sundog (sun is to the right, so inner edge is +x),
  //             +1 for right sundog (sun is to the left, so inner edge is -x)
  let innerDir = -outwardDir;

  // 1. Outward horizontal white-blue tail along the parhelic circle
  for (let i = 0; i < 18; i++) {
    let t = i / 18;
    let len = map(t, 0, 1, 135, 24);
    let dy = (i - 8.5) * 3.2;
    let col = abs(dy) < 12 ? "#ffffff" : "#e3eef9";
    drawLine("halo_veil", col, map(abs(dy), 0, 28, 1.2, 0.35), px, py + dy * 0.35, px + outwardDir * len, py + dy);
    if (i % 2 === 0) {
      drawLine("fine_spray", col, 0.75, px, py + dy * 0.3, px + outwardDir * (len * 0.85), py + dy * 0.8);
    }
  }

  // 2. Vertical sundog light spindle (following the halo curvature)
  for (let i = -7; i <= 7; i++) {
    let dx = i * 2.4;
    let vSpan = map(abs(i), 0, 7, 78, 22);
    let curveX = innerDir * 6;
    let pts = [
      [px + dx + curveX, py - vSpan],
      [px + dx, py],
      [px + dx + curveX, py + vSpan]
    ];
    drawSpline("halo_veil", "#f5f9fe", map(abs(i), 0, 7, 1.1, 0.3), pts, 0.5);
  }

  // 3. FAINT RED INNER EDGE (closest to the sun, transitioning through pastel rose/peach to white)
  const prismColors = [
    { offset: 15.5, col: "#d16d66", w: 0.75, span: 36, op: 85 }, // Muted crimson-terracotta inner edge
    { offset: 12.5, col: "#df847a", w: 0.90, span: 44, op: 95 }, // Soft pastel Venetian red
    { offset: 9.5,  col: "#ec9f90", w: 1.00, span: 50, op: 90 }, // Rose-coral
    { offset: 6.5,  col: "#f5bfa9", w: 1.05, span: 54, op: 85 }, // Pastel peach
    { offset: 3.5,  col: "#fae1c8", w: 1.10, span: 58, op: 95 }, // Warm cream-gold
    { offset: 0.0,  col: "#ffffff", w: 1.35, span: 62, op: 140 } // Blinding white core
  ];

  for (let band of prismColors) {
    let bx = px + innerDir * band.offset;
    let bend = innerDir * 4.5;
    let pts = [
      [bx + bend, py - band.span],
      [bx + bend * 0.25, py - band.span * 0.45],
      [bx, py],
      [bx + bend * 0.25, py + band.span * 0.45],
      [bx + bend, py + band.span]
    ];
    drawSpline("halo_veil", band.col, band.w, pts, 0.5);
    drawSpline("micro_spray", band.col, band.w * 0.75, pts, 0.5);
  }

  // 4. Intense brilliant white parhelion core
  washPoly(makeEllipsePts(px - innerDir * 2, py, 16, 28, 24), "#ffffff", 185);
  washPoly(makeEllipsePts(px - innerDir * 4, py, 28, 44, 24), "#f7fbff", 95);
  for (let k = 0; k < 14; k++) {
    let a = random(0, 360);
    drawLine("micro_spray", "#ffffff", 0.65, px, py, px + cos(a) * random(10, 32), py + sin(a) * random(14, 48));
  }
}

// ============================================================================
// 2. DISTANT SHORE & HORIZON LINE
// ============================================================================
function renderDistantShore() {
  // Subtle atmospheric treeline on the far shore, nearly swallowed by bright freezing haze
  let shorePts = [[0, HY]];
  for (let x = 0; x <= W; x += 16) {
    let distCenter = abs(x - SX) / (W * 0.5);
    // Lower and fainter directly under the sun
    let h = (noise(x * 0.015, 10) * 11 + noise(x * 0.08, 20) * 4.5) * lerp(0.18, 1.0, pow(distCenter, 0.7));
    shorePts.push([x, HY - h]);
  }
  shorePts.push([W, HY]);
  washPoly(shorePts, "#9eb3cc", 150);

  // Fine vertical spruce needle texture along the far ridge
  for (let x = 8; x < W - 8; x += 5) {
    let distCenter = abs(x - SX) / (W * 0.5);
    if (distCenter < 0.16 && random() < 0.7) continue;
    let h = (noise(x * 0.015, 10) * 10 + noise(x * 0.08, 20) * 4) * lerp(0.15, 1.0, pow(distCenter, 0.7));
    if (h > 1.8) {
      let col = distCenter < 0.4 ? "#b8cae0" : (random() < 0.5 ? "#7f96b5" : "#93a9c6");
      drawLine("2H", col, 0.32, x, HY, x + random(-0.5, 0.5), HY - h);
    }
  }

  // Crisp horizon ice-mirage bright line
  drawLine("halo_veil", "#f7fbff", 0.85, 0, HY + 1, W, HY + 1);
  drawLine("2H", "#8ca3bf", 0.35, 0, HY, W, HY);
}

// ============================================================================
// 3. FROZEN LAKE BASE: Cobalt Glaze Ice Slabs & Reflected Sun/Sundog Columns
// ============================================================================
function renderLakeBase() {
  const lakeBands = [
    "#dfeaf4", "#d3e1ef", "#c4d6e8", "#b4cae0", "#a3bdd7",
    "#92b0ce", "#81a1c3", "#7092b7", "#6183aa", "#53759d",
    "#476890", "#3d5c83", "#345177", "#2c486c", "#264062", "#203959"
  ];

  let totalRows = 32;
  for (let i = 0; i < totalRows; i++) {
    let t0 = i / totalRows;
    let t1 = (i + 1.35) / totalRows;
    // Perspective spacing: tighter near horizon, wider in foreground
    let y0 = HY + pow(t0, 1.25) * (H - HY);
    let y1 = HY + pow(min(1, t1), 1.25) * (H - HY) + 4;
    let cIdx = min(lakeBands.length - 1, floor(t0 * lakeBands.length));
    let pts = [[0, y0], [W, y0], [W, y1], [0, y1]];
    washPoly(pts, lakeBands[cIdx], 175);
  }

  // Deep polished glaze-ice slabs in the foreground and midground (wind-swept bare ice)
  const darkIceSlabs = [
    { cx: 520, cy: 1065, rx: 560, ry: 125, col: "#253d59", op: 135 },
    { cx: 430, cy: 1055, rx: 390, ry: 92,  col: "#1d334c", op: 145 },
    { cx: 830, cy: 965,  rx: 340, ry: 42,  col: "#3b587a", op: 110 },
    { cx: 240, cy: 925,  rx: 270, ry: 28,  col: "#4c6a8c", op: 105 },
    { cx: 680, cy: 888,  rx: 320, ry: 18,  col: "#6482a4", op: 95 }
  ];

  for (let slab of darkIceSlabs) {
    let pts = makeEllipsePts(slab.cx, slab.cy, slab.rx, slab.ry, 32, 8);
    watercolorPoly(pts, slab.col, slab.op, 0.12, 0.35);
  }

  // Smooth horizontal ice sheen & wind-polish striations across the lake
  for (let i = 0; i < 120; i++) {
    let t = pow(random(), 1.15);
    let y = HY + 2 + t * (H - HY - 4);
    let cIdx = min(lakeBands.length - 1, floor(t * lakeBands.length));
    let col = random() < 0.45 ? lakeBands[max(0, cIdx - 2)] : lakeBands[min(lakeBands.length - 1, cIdx + 1)];
    let x1 = random(-20, W * 0.45);
    let x2 = x1 + random(240, 820);
    drawLine("sky_mist", col, map(t, 0, 1, 0.55, 1.45), x1, y, x2, y + random(-2, 2));
  }

  // Specular Sky & Sun Glare Pillar reflected on the ice surface (x = SX)
  for (let i = 0; i < 72; i++) {
    let t = i / 72;
    let y = HY + 2 + pow(t, 1.15) * (H - HY - 8);
    let halfW = lerp(55, 210, t) * random(0.45, 1.15);
    let col = t < 0.45 ? "#ffffff" : (t < 0.78 ? "#ddeaf6" : "#a9c2dc");
    let w = map(t, 0, 1, 0.45, 1.1);
    drawLine("halo_veil", col, w, SX - halfW, y, SX + halfW, y);
    if (i % 3 === 0) {
      drawLine("fine_spray", "#ffffff", 0.65, SX - halfW * 0.6, y, SX + halfW * 0.6, y);
    }
  }

  // Reflected Parhelia (Sundog) columns on the left and right lake surface
  const sundogXs = [SX - HR - 4, SX + HR + 4];
  for (let px of sundogXs) {
    for (let i = 0; i < 42; i++) {
      let t = i / 42;
      let y = HY + 2 + pow(t, 1.2) * (H - HY - 40);
      let halfW = lerp(24, 95, t) * random(0.4, 1.1);
      // Inner edge has a faint pastel rose reflection, outer is icy white
      let isInner = random() < 0.35;
      let shift = isInner ? (px < SX ? 12 : -12) : 0;
      let col = isInner ? "#e8bfb8" : (t < 0.5 ? "#f2f7fc" : "#b8cee4");
      drawLine("halo_veil", col, map(t, 0, 1, 0.38, 0.85), px + shift - halfW, y, px + shift + halfW, y);
    }
  }
}

// ============================================================================
// 4. TRAPPED METHANE & AIR BUBBLES IN CLEAR FOREGROUND ICE
// ============================================================================
function renderTrappedBubbles() {
  // Clusters of pancake bubbles frozen at varying depths in the dark foreground ice slabs
  const bubbleClusters = [
    { cx: 195, cy: 1110, spreadX: 95,  spreadY: 42, count: 22 },
    { cx: 310, cy: 1148, spreadX: 110, spreadY: 38, count: 26 },
    { cx: 565, cy: 1125, spreadX: 125, spreadY: 45, count: 28 },
    { cx: 745, cy: 1085, spreadX: 105, spreadY: 36, count: 20 },
    { cx: 255, cy: 1015, spreadX: 85,  spreadY: 26, count: 16 },
    { cx: 635, cy: 1020, spreadX: 95,  spreadY: 28, count: 18 },
    { cx: 885, cy: 1135, spreadX: 90,  spreadY: 34, count: 16 },
    { cx: 455, cy: 968,  spreadX: 80,  spreadY: 20, count: 14 },
    { cx: 820, cy: 965,  spreadX: 75,  spreadY: 18, count: 12 }
  ];

  // Draw from deep layer (0) to shallow surface layer (2) for true optical depth
  for (let layer = 0; layer < 3; layer++) {
    for (let cl of bubbleClusters) {
      let n = floor(cl.count / 3);
      for (let i = 0; i < n; i++) {
        let ang = random(0, 360);
        let rad = pow(random(), 0.7);
        let bx = cl.cx + cos(ang) * cl.spreadX * rad;
        let by = cl.cy + sin(ang) * cl.spreadY * rad;

        // Avoid placing bubbles directly inside the open auger water hole (410, 1055)
        let dxHole = (bx - 410) / 86;
        let dyHole = (by - 1055) / 36;
        if (dxHole * dxHole + dyHole * dyHole < 1.15) continue;

        let persp = map(by, HY + 80, H, 0.28, 1.0, true);
        let rx = random(3.2, 13.5) * persp * (layer === 0 ? 0.78 : (layer === 1 ? 0.92 : 1.05));
        let ry = rx * map(by, HY + 80, H, 0.24, 0.42, true);

        if (layer === 0) {
          // Deepest frozen bubbles: muted slate-cobalt, soft edges
          washPoly(makeEllipsePts(bx, by + 5 * persp, rx, ry, 14), "#4f6f94", 95);
        } else if (layer === 1) {
          // Mid-depth bubbles: cool pastel cerulean-periwinkle, stacked chimney effect
          washPoly(makeEllipsePts(bx, by + 2.5 * persp, rx, ry, 16), "#83a3c7", 130);
          drawArc("2H", "#5d7ea3", 0.28, bx, by + 2.5 * persp, rx, 10, 170);
        } else {
          // Shallow bubbles right beneath the ice surface: crisp chalk-white with dark lower rim
          washPoly(makeEllipsePts(bx, by, rx, ry, 16), "#dceaf7", 185);
          if (rx > 4.5) {
            washPoly(makeEllipsePts(bx - rx * 0.12, by - ry * 0.12, rx * 0.65, ry * 0.6, 12), "#ffffff", 210);
          }
          // Subtle dark bottom shadow rim inside the ice
          drawLine("ice_needle", "#1a2f47", 0.35, bx - rx * 0.75, by + ry * 0.85, bx + rx * 0.75, by + ry * 0.85);
          // Crisp pencil rim highlight on top edge
          drawLine("2H", "#ffffff", 0.32, bx - rx * 0.65, by - ry * 0.75, bx + rx * 0.65, by - ry * 0.75);
        }
      }
    }
  }

  // Tiny vertical bubble trails (chained micro-bubbles frozen while rising)
  for (let i = 0; i < 65; i++) {
    let bx = random(90, 1060);
    let by = random(955, 1185);
    let dxHole = (bx - 410) / 86;
    let dyHole = (by - 1055) / 36;
    if (dxHole * dxHole + dyHole * dyHole < 1.15) continue;

    let persp = map(by, 940, H, 0.4, 1.0);
    for (let s = 3; s >= 0; s--) {
      let sy = by + s * 3.2 * persp;
      let r = (2.4 - s * 0.35) * persp;
      let col = s === 0 ? "#ffffff" : (s === 1 ? "#bad2ea" : "#6989ad");
      drawLine("cpencil", col, 0.45 * persp, bx - r, sy, bx + r, sy);
    }
  }
}

// ============================================================================
// 5. HYPERREAL PENCIL-DRAWN ICE CRACKS (Subsurface Ribbons & Surface Fissures)
// ============================================================================
function renderIceCracks() {
  // Primary deep thermal fractures cutting across the lake in perspective
  const mainCracks = [
    // Crack 1: Sweeping from lower-left foreground through the auger hole toward right-midground
    [
      [45, 1182], [155, 1142], [268, 1098], [342, 1068],
      [410, 1055], [492, 1032], [615, 994], [755, 956],
      [910, 916], [1085, 882], [1195, 864]
    ],
    // Crack 2: Foreground right sweeping toward the auger hole and then toward distant left
    [
      [1130, 1192], [965, 1154], [790, 1118], [625, 1088],
      [482, 1064], [410, 1055], [318, 1018], [215, 976],
      [115, 938], [15, 908]
    ],
    // Crack 3: Deep foreground cross-fracture
    [
      [190, 1196], [335, 1162], [488, 1138], [642, 1126],
      [815, 1104], [990, 1072], [1185, 1044]
    ],
    // Crack 4: Midground pressure crack passing below the red shanty
    [
      [-10, 962], [185, 944], [390, 928], [595, 910],
      [785, 892], [975, 878], [1205, 868]
    ],
    // Crack 5: Radial stress fracture from auger hole toward lower center
    [
      [410, 1055], [435, 1098], [452, 1146], [478, 1198]
    ]
  ];

  for (let pts of mainCracks) {
    drawHyperrealCrack(pts, true);
  }

  // Secondary branching feather-cracks and internal stress splinters
  for (let c of mainCracks) {
    for (let i = 1; i < c.length - 1; i++) {
      let [px, py] = c[i];
      let persp = map(py, HY, H, 0.15, 1.0, true);
      if (random() < 0.78) {
        let dir = atan2(c[i][1] - c[i - 1][1], c[i][0] - c[i - 1][0]);
        let branchAng = dir + (random() < 0.5 ? 1 : -1) * random(22, 54);
        let bPts = [[px, py]];
        let cx = px, cy = py;
        let segs = floor(random(3, 6));
        for (let s = 0; s < segs; s++) {
          let stepLen = random(28, 72) * persp;
          branchAng += random(-16, 16);
          cx += cos(branchAng) * stepLen;
          cy += sin(branchAng) * stepLen * 0.55;
          bPts.push([cx, cy]);
        }
        drawHyperrealCrack(bPts, false);
      }
    }
  }
}

function drawHyperrealCrack(pts, isPrimary) {
  // Subdivide points with sharp crystalline kink jitter
  let dense = [];
  for (let i = 0; i < pts.length - 1; i++) {
    let [x1, y1] = pts[i];
    let [x2, y2] = pts[i + 1];
    let sub = 5;
    for (let s = 0; s < sub; s++) {
      let t = s / sub;
      let x = lerp(x1, x2, t);
      let y = lerp(y1, y2, t);
      let persp = map(y, HY, H, 0.1, 1.0, true);
      if (s > 0) {
        x += random(-4.5, 4.5) * persp;
        y += random(-2.2, 2.2) * persp;
      }
      dense.push([x, y]);
    }
  }
  dense.push(pts[pts.length - 1]);

  // 1. Subsurface vertical fracture curtain inside the thick ice (milky cyan-white ribbon below the crack)
  let ribbonPoly = [];
  for (let i = 0; i < dense.length; i++) {
    ribbonPoly.push([dense[i][0], dense[i][1]]);
  }
  for (let i = dense.length - 1; i >= 0; i--) {
    let [x, y] = dense[i];
    let persp = pow(map(y, HY, H, 0.05, 1.0, true), 1.35);
    let depth = (isPrimary ? 11.5 : 5.5) * persp * random(0.75, 1.2);
    ribbonPoly.push([x + random(-1.5, 1.5) * persp, y + depth]);
  }
  washPoly(ribbonPoly, isPrimary ? "#8fb2d6" : "#789cc2", isPrimary ? 115 : 80);

  // Internal vertical cleavage striations inside the subsurface fracture wall
  for (let i = 0; i < dense.length - 1; i++) {
    let [x1, y1] = dense[i];
    let [x2, y2] = dense[i + 1];
    let persp = pow(map(y1, HY, H, 0.08, 1.0, true), 1.25);
    let depth = (isPrimary ? 10.0 : 4.8) * persp;

    if (depth > 1.8) {
      drawLine("2H", "#c6def5", 0.32 * persp + 0.12, x1, y1 + depth * 0.45, x2, y2 + depth * 0.45);
      if (isPrimary && i % 2 === 0) {
        drawLine("2H", "#e6f2fc", 0.28 * persp + 0.1, x1, y1 + depth * 0.2, (x1 + x2) * 0.5, y1 + depth * 0.85);
      }
    }

    // 2. Dark razor-sharp surface fissure line (graphite/needle)
    let wDark = (isPrimary ? 0.58 : 0.34) * map(y1, HY, H, 0.35, 1.15, true);
    drawLine("ice_needle", "#13253b", wDark, x1, y1, x2, y2);
    drawLine("2H", "#243b57", wDark * 0.8, x1, y1 + 0.6 * persp, x2, y2 + 0.6 * persp);

    // 3. Bright white specular lip catching the mid-afternoon sun right along the crack edge
    let wLight = (isPrimary ? 0.48 : 0.28) * map(y1, HY, H, 0.3, 1.05, true);
    drawLine("cpencil", "#ffffff", wLight, x1, y1 - 0.8 * persp, x2, y2 - 0.8 * persp);

    // Occasional white conchoidal stress splinters at fracture joints
    if (isPrimary && random() < 0.28 && y1 > 920) {
      let spLen = random(6, 18) * persp;
      let spAng = random(-35, 35);
      drawLine("2H", "#f0f7fd", 0.32, x1, y1, x1 + cos(spAng) * spLen, y1 + sin(spAng) * spLen * 0.4);
    }
  }
}

// ============================================================================
// 6. WIND-SCOURED SNOW RIPPLES (SASTRUGI)
// ============================================================================
function renderSnowRipples() {
  // Sculpted wind-packed snow bands streaming across the lake ice
  // Leaving large dark glaze-ice windows open in the foreground around the auger hole
  let numRidges = 88;
  for (let i = 0; i < numRidges; i++) {
    let t = pow(i / numRidges, 1.42);
    let y = HY + 3 + t * (H - HY - 12);
    let persp = map(y, HY, H, 0.06, 1.0);

    // Determine horizontal span; leave clear dark ice around the auger hole (410, 1055)
    let spans = [];
    if (y > 975 && y < 1155) {
      // Split around the foreground clear ice window
      if (random() < 0.85) spans.push([random(-30, 80), random(180, 295)]);
      if (random() < 0.9)  spans.push([random(680, 820), random(980, W + 30)]);
      if (random() < 0.32) spans.push([random(490, 560), random(640, 740)]);
    } else {
      let xStart = random(-40, W * 0.65);
      let width = random(180, 620) * map(t, 0, 1, 0.55, 1.25);
      spans.push([xStart, min(W + 40, xStart + width)]);
    }

    for (let [x1, x2] of spans) {
      if (x2 - x1 < 40) continue;
      drawSastrugiRidge(x1, x2, y, persp);
    }
  }

  // Fine wind-scoured snow streaks (directional vector-field pencil & dry snow grain marks)
  brush.field("wind_drift");
  for (let i = 0; i < 140; i++) {
    let t = pow(random(), 1.2);
    let y = HY + 6 + t * (H - HY - 14);
    let x = random(0, W);

    // Skip the open dark-ice zone immediately around the auger hole
    let dxH = (x - 410) / 195;
    let dyH = (y - 1055) / 72;
    if (dxH * dxH + dyH * dyH < 1.0) continue;

    let persp = map(y, HY, H, 0.2, 1.0);
    let len = random(35, 130) * persp;
    let isHighlight = random() < 0.62;
    let col = isHighlight ? (random() < 0.5 ? "#ffffff" : "#f2f6fb") : "#b5c9e0";

    brush.noFill();
    brush.noWash();
    brush.noHatch();
    brush.set(isHighlight ? "snow_grain" : "2H", col, (isHighlight ? 0.55 : 0.32) * persp + 0.15);
    brush.flowLine(x, y, len, -2);
  }
  brush.noField();
}

function drawSastrugiRidge(x1, x2, yBase, persp) {
  let steps = max(6, floor((x2 - x1) / 32));
  let crestPts = [];
  let backPts = [];
  let shadowPts = [];

  let maxH = (3.5 + random(6, 18)) * persp;

  for (let s = 0; s <= steps; s++) {
    let u = s / steps;
    let x = lerp(x1, x2, u);
    // Taper smoothly at both ends like wind-carved snow tongues
    let env = sin(u * 180);
    let wave = (noise(x * 0.012, yBase * 0.05) - 0.5) * 14 * persp;
    let h = maxH * pow(env, 0.65) * (0.7 + 0.6 * noise(x * 0.025, yBase * 0.08));

    let cy = yBase + wave;
    crestPts.push([x, cy - h * 0.45]);
    backPts.push([x, cy - h]);
    shadowPts.push([x + 6 * persp, cy + h * 0.38]);
  }

  // 1. Crisp cobalt-blue undercut shadow cast by the wind-carved snow lip onto the ice
  let shPoly = [...crestPts, ...shadowPts.slice().reverse()];
  washPoly(shPoly, yBase > 980 ? "#3f5b7d" : "#6c87a8", 130);

  // 2. Shadowed snow slope (pastel periwinkle / icy lavender-blue)
  let bodyPoly = [...backPts, ...crestPts.slice().reverse()];
  washPoly(bodyPoly, yBase > 960 ? "#c3d5e9" : "#d4e2f1", 175);

  // 3. Sunlit wind-packed snow top (warm cream-white & pure snow white)
  let topPts = [];
  for (let i = 0; i < backPts.length; i++) {
    topPts.push(backPts[i]);
  }
  for (let i = crestPts.length - 1; i >= 0; i--) {
    topPts.push([crestPts[i][0], lerp(backPts[i][1], crestPts[i][1], 0.55)]);
  }
  washPoly(topPts, "#fafcfe", 215);

  // 4. Crisp pencil-drawn sastrugi lip & wind-fluted hatching
  drawSpline("2H", "#537094", 0.26 * persp + 0.12, shadowPts, 0.4);
  drawSpline("cpencil", "#ffffff", 0.45 * persp + 0.18, backPts, 0.45);
  if (persp > 0.35) {
    drawSpline("snow_grain", "#ffffff", 0.55 * persp, topPts.slice(0, steps + 1), 0.4);
  }
}

// ============================================================================
// 7. LONE RED ICE-FISHING SHANTY (Mid-Distance Right)
// ============================================================================
function renderRedShanty() {
  // Positioned just below the low horizon so its roof breaks the vast horizon line
  const sx = 835;
  const sy = 858;
  const wLeft = 24;   // Sunlit left wall facing the sun at SX=600
  const wRight = 18;  // Shadowed right wall facing away from the sun
  const hWall = 27;
  const hPeak = 34;

  // 1. Blurry pastel red & slate reflection on the slick ice directly beneath the shanty
  for (let i = 0; i < 16; i++) {
