    let spread = map(i, 0, 15, 1.0, 0.45);
    let col = i % 2 === 0 ? "#b0676c" : "#7e535c";
    drawLine("sky_mist", col, 0.48, sx - wLeft * spread + random(-3, 3), ry, sx + wRight * spread + random(-3, 3), ry);
  }

  // 2. Long, cold cobalt-violet shadow cast to the right across the ice (away from the sun at SX=600)
  let shadowPoly = [
    [sx + 2, sy + 1],
    [sx + wRight, sy - 2],
    [sx + 158, sy + 12],
    [sx + 132, sy + 19],
    [sx - 4, sy + 4]
  ];
  washPoly(shadowPoly, "#5e789c", 155);
