  }

  // 5. Shadowed Right Wall (deep muted burgundy-plum cooled by cobalt sky light)
  let rightWall = [
    [sx + 2, sy + 2],
    [sx + wRight, sy - 2],
    [sx + wRight, sy - 2 - hPeak + 6],
    [sx + 2, sy + 2 - hWall]
  ];
  washPoly(rightWall, "#7c3138", 235);
  washPoly(rightWall, "#692a34", 120);

  // Door outline on the shadowed right wall
  let doorX1 = sx + 6, doorX2 = sx + 14;
  drawLine("2H", "#3d151b", 0.3, doorX1, sy + 1, doorX1, sy - 19);
  drawLine("2H", "#3d151b", 0.3, doorX2, sy - 1, doorX2, sy - 20);
  drawLine("2H", "#3d151b", 0.3, doorX1, sy - 19, doorX2, sy - 20);

  // 6. Small frost-rimmed window on the sunlit left wall catching solar glare
  let winPts = [
    [sx - 15, sy - 13],
    [sx - 7, sy - 12],
    [sx - 7, sy - 20],
    [sx - 15, sy - 21]
  ];
  washPoly(winPts, "#384b61", 220);
  // Warm interior/sun glint & white window muntins
  washPoly([[sx - 14, sy - 14], [sx - 10, sy - 13.5], [sx - 10, sy - 19], [sx - 14, sy - 19.5]], "#fae2d2", 195);
  drawLine("cpencil", "#ffffff", 0.38, sx - 15, sy - 21, sx - 7, sy - 20);
  drawLine("cpencil", "#ffffff", 0.38, sx - 15, sy - 13, sx - 15, sy - 21);
  drawLine("2H", "#592020", 0.28, sx - 7, sy - 12, sx - 7, sy - 20);
  drawLine("2H", "#592020", 0.28, sx - 15, sy - 13, sx - 7, sy - 12);

  // 7. Snow-laden pitched roof & overhang
  let roofPts = [
    [sx - wLeft - 3, sy - hWall],
    [sx + 2, sy + 2 - hWall - 1],
    [sx + wRight + 2, sy - 2 - hPeak + 4],
    [sx - 4, sy - hPeak - 1]
  ];
  washPoly(roofPts, "#ffffff", 240);
  // Roof shadow fascia edge
  drawLine("2H", "#4f2024", 0.42, sx - wLeft - 3, sy - hWall + 1, sx + 2, sy + 2 - hWall);
  drawLine("2H", "#381519", 0.42, sx + 2, sy + 2 - hWall, sx + wRight + 2, sy - 2 - hPeak + 5);
  // Crisp sunlit snow cap on the roof ridge
  drawLine("cpencil", "#ffffff", 0.65, sx - wLeft - 3, sy - hWall, sx - 4, sy - hPeak - 1);
  drawLine("cpencil", "#e3eef8", 0.55, sx + 2, sy + 2 - hWall - 1, sx + wRight + 2, sy - 2 - hPeak + 4);

  // 8. Tiny stovepipe & delicate wisp of woodsmoke in the still air
  let pipeX = sx + 10;
