  // 9. Wind-banked snowdrift piled against the base of the shanty
  let driftLeft = [
    [sx - wLeft - 18, sy + 1],
    [sx - wLeft + 4, sy - 5],
    [sx + 3, sy + 1],
    [sx + 10, sy + 4],
    [sx - wLeft - 12, sy + 4]
  ];
  washPoly(driftLeft, "#ffffff", 225);
  drawSpline("cpencil", "#ffffff", 0.45, [[sx - wLeft - 18, sy + 1], [sx - wLeft + 2, sy - 5], [sx + 4, sy + 2]], 0.4);
  drawSpline("2H", "#7c96b8", 0.3, [[sx - wLeft - 12, sy + 4], [sx + 2, sy + 4], [sx + 16, sy + 5]], 0.4);
}

// ============================================================================
// 8. FOREGROUND AUGER HOLE (Hyperreal Ice Wall, Dark Water & Shavings Mound)
// ============================================================================
function renderAugerHole() {
  const ax = 410;
  const ay = 1055;
  const rx = 74;
  const ry = 28;
  const iceWallDepth = 13.5; // Visible thickness of the bored ice cylinder above the water line

  // 1. Dark wet refrozen splash apron around the auger hole
  let splashPts = makeEllipsePts(ax + 6, ay + 3, rx * 1.52, ry * 1.48, 36, 5);
  watercolorPoly(splashPts, "#182c44", 115, 0.14, 0.35);
  let innerSplash = makeEllipsePts(ax - 2, ay + 1, rx * 1.24, ry * 1.22, 32, 3);
  washPoly(innerSplash, "#14263b", 125);

  // 2. Interior Cylindrical Ice Wall (the bored ice thickness visible inside the top of the hole)
  let holeRimPts = makeEllipsePts(ax, ay, rx, ry, 40, 0.4);
  washPoly(holeRimPts, "#6d98b8", 235);

  // Subtle horizontal shading across the curved interior ice wall (brightest on the right/back facing the sun)
  for (let i = 0; i < 18; i++) {
    let u = i / 17;
    let a1 = lerp(182, 358, u);
    let a2 = lerp(182, 358, min(1, u + 0.12));
    let x1 = ax + cos(a1) * rx;
    let y1 = ay + sin(a1) * ry;
    let x2 = ax + cos(a2) * rx;
    let y2 = ay + sin(a2) * ry;
    let wallQuad = [
      [x1, y1],
      [x2, y2],
      [x2, y2 + iceWallDepth + 4],
      [x1, y1 + iceWallDepth + 4]
    ];
    // Left interior wall is in deeper aquamarine shadow, right interior wall catches backlit turquoise glow
    let col = u < 0.35 ? "#385b7a" : (u < 0.72 ? "#7ba6c4" : "#9ec6e0");
    washPoly(wallQuad, col, 210);
  }

  // Rotary auger blade score rings carved into the interior ice wall
  for (let d = 2.5; d < iceWallDepth; d += 2.6) {
    let ringPts = [];
    for (let a = 188; a <= 352; a += 12) {
      ringPts.push([ax + cos(a) * (rx - 0.8), ay + sin(a) * (ry - 0.5) + d]);
    }
    drawSpline("2H", d % 5 < 2.5 ? "#345675" : "#bce0f7", 0.32, ringPts, 0.5);
  }

  // 3. Deep, Cold Lake Water Recessed Inside the Hole
  // Clipped intersection of the top rim (ax, ay) and the recessed water plane (ax, ay + iceWallDepth)
  let waterPts = [];
  for (let i = 0; i < 48; i++) {
    let a = (i / 48) * 360;
    let wx = ax + cos(a) * (rx - 1.5);
    let wy = ay + iceWallDepth + sin(a) * (ry - 1.2);
    // Clamp the lower half of the water ellipse so it stays strictly inside the front lip of the hole
    let dx = (wx - ax) / (rx - 1.2);
    let maxFrontY = ay + sqrt(max(0, 1 - dx * dx)) * (ry - 1.0);
    let minBackY = ay - sqrt(max(0, 1 - dx * dx)) * (ry - 1.0);
    wy = constrain(wy, minBackY, maxFrontY);
    waterPts.push([wx, wy]);
  }
  washPoly(waterPts, "#0d1a2b", 250);

  // Subtle sky reflection gradient on the right half of the dark water meniscus
  let waterReflectPts = [];
  for (let a = -65; a <= 75; a += 12) {
    let wx = ax + 8 + cos(a) * (rx * 0.68);
    let wy = ay + iceWallDepth * 0.65 + sin(a) * (ry * 0.48);
    let dx = (wx - ax) / (rx - 2);
    let maxFrontY = ay + sqrt(max(0, 1 - dx * dx)) * (ry - 2);
    waterReflectPts.push([wx, min(wy, maxFrontY)]);
  }
  washPoly(waterReflectPts, "#233c59", 145);

  // Dark wet meniscus shadow where the water meets the vertical ice wall
  let meniscusPts = [];
  for (let a = 190; a <= 350; a += 10) {
    meniscusPts.push([ax + cos(a) * (rx - 1.5), ay + iceWallDepth + sin(a) * (ry - 1.2)]);
  }
  drawSpline("ice_needle", "#07101c", 0.65, meniscusPts, 0.5);
  drawSpline("2H", "#648eb0", 0.35, meniscusPts.map(p => [p[0], p[1] + 1.2]), 0.5);

  // 4. Floating Slush & Ice Crystals Bobbing on the Dark Water Surface
  const slushIslands = [
    { x: ax - 24, y: ay + 7,  rx: 18, ry: 5.5, col: "#7fa2c2" },
    { x: ax + 18, y: ay + 11, rx: 14, ry: 4.2, col: "#92b4d4" },
    { x: ax - 4,  y: ay + 14, rx: 11, ry: 3.5, col: "#a8c6e2" },
    { x: ax + 36, y: ay + 5,  rx: 9,  ry: 2.8, col: "#89accb" }
  ];
  for (let sl of slushIslands) {
    washPoly(makeEllipsePts(sl.x, sl.y, sl.rx, sl.ry, 14, 1.2), sl.col, 175);
    washPoly(makeEllipsePts(sl.x - 2, sl.y - 0.6, sl.rx * 0.6, sl.ry * 0.55, 10, 0.6), "#e3effa", 195);
    drawArc("2H", "#102033", 0.28, sl.x, sl.y, sl.rx, 10, 170);
  }
  // Sparkling floating ice needles on the dark water
  for (let i = 0; i < 38; i++) {
    let ang = random(0, 360);
    let r = sqrt(random()) * 0.78;
    let sx = ax + cos(ang) * rx * r;
    let sy = ay + 6 + sin(ang) * (ry - 7) * r;
    drawLine("cpencil", random() < 0.5 ? "#ffffff" : "#bad4ec", 0.38, sx - 2, sy, sx + 2, sy);
  }

  // 5. Crisp Beveled Top Rim of the Auger Hole
  // Back rim shadow lip & subsurface edge
  let backRim = [];
  for (let a = 180; a <= 360; a += 8) {
    backRim.push([ax + cos(a) * rx, ay + sin(a) * ry]);
  }
  drawSpline("ice_needle", "#1b334f", 0.52, backRim, 0.5);
  drawSpline("cpencil", "#d8eaf9", 0.45, backRim.map(p => [p[0], p[1] - 1.2]), 0.5);

  // Front rim: thick translucent beveled ice edge catching blinding afternoon sun
  let frontRim = [];
  for (let a = 0; a <= 180; a += 8) {
    frontRim.push([ax + cos(a) * rx, ay + sin(a) * ry]);
  }
  drawSpline("2H", "#3e6285", 0.65, frontRim.map(p => [p[0], p[1] + 2.2]), 0.5);
  drawSpline("cpencil", "#ffffff", 0.78, frontRim, 0.5);
  drawSpline("ice_needle", "#0a1726", 0.45, frontRim.map(p => [p[0], p[1] - 1.1]), 0.5);

  // 6. Crystalline Mound of Auger Ice Shavings & Slush Piled Around the Hole
  // Thrown out in a crescent around the right, back-right, and left edge of the hole
  const shavingMounds = [
    // Main right/back-right crescent pile
    { cx: ax + 94, cy: ay - 6,  rx: 56, ry: 22, h: 24 },
    { cx: ax + 62, cy: ay - 24, rx: 48, ry: 17, h: 21 },
    { cx: ax + 18, cy: ay - 31, rx: 42, ry: 14, h: 16 },
    { cx: ax + 112, cy: ay + 12, rx: 44, ry: 16, h: 17 },
    // Smaller left-side slush pile
    { cx: ax - 86, cy: ay - 10, rx: 38, ry: 15, h: 16 },
    { cx: ax - 54, cy: ay - 25, rx: 32, ry: 12, h: 13 }
  ];

  // Cast shadows of the slush mounds onto the dark glaze ice (stretching down-left/right away from sun)
  for (let m of shavingMounds) {
    let shPts = makeEllipsePts(m.cx + (m.cx > ax ? 14 : -10), m.cy + 8, m.rx * 1.12, m.ry * 1.05, 22, 3);
    washPoly(shPts, "#1a2f47", 155);
  }

  // Sculpted 3D volume of each slush/shaving mound
  for (let m of shavingMounds) {
    // Base wet slush (cool pastel cerulean-periwinkle)
    let basePts = makeEllipsePts(m.cx, m.cy, m.rx, m.ry, 24, 3.5);
    washPoly(basePts, "#8da9c9", 215);

    // Mid-slope shaded ice shavings
    let midPts = [];
    for (let i = 0; i <= 20; i++) {
      let a = map(i, 0, 20, 180, 360);
      midPts.push([m.cx + cos(a) * m.rx * 0.92, m.cy + sin(a) * m.ry * 0.8 - m.h * sin((i / 20) * 180) + random(-2, 2)]);
    }
    for (let i = 20; i >= 0; i--) {
      let a = map(i, 0, 20, 0, 180);
      midPts.push([m.cx + cos(a) * m.rx * 0.95, m.cy + sin(a) * m.ry * 0.85 + random(-1.5, 1.5)]);
    }
    washPoly(midPts, "#bfd4eb", 225);

    // Sunlit crystalline peak (facing the sun at SX=600)
    let sunShift = m.cx < SX ? 6 : -6;
    let topPts = [];
    for (let i = 0; i <= 18; i++) {
      let a = map(i, 0, 18, 185, 355);
      topPts.push([m.cx + sunShift * 0.5 + cos(a) * m.rx * 0.78, m.cy + sin(a) * m.ry * 0.65 - m.h * 0.92 * sin((i / 18) * 180) + random(-1.8, 1.8)]);
    }
    for (let i = 18; i >= 0; i--) {
      let a = map(i, 0, 18, 15, 165);
      topPts.push([m.cx + sunShift + cos(a) * m.rx * 0.62, m.cy + sin(a) * m.ry * 0.35 - m.h * 0.25]);
    }
    washPoly(topPts, "#fafcfe", 240);

    // Granular shaved-ice texture: pencil curls, snow_grain & micro_spray
    for (let k = 0; k < 28; k++) {
      let gx = m.cx + random(-m.rx * 0.8, m.rx * 0.8);
      let gy = m.cy + random(-m.h * 0.85, m.ry * 0.65);
      let isSun = (m.cx < SX ? gx > m.cx - 8 : gx < m.cx + 8) && gy < m.cy + 2;
      let col = isSun ? "#ffffff" : (random() < 0.5 ? "#6987ab" : "#9cb7d6");
      drawLine(isSun ? "snow_grain" : "2H", col, isSun ? 0.55 : 0.32, gx, gy, gx + random(-8, 8), gy + random(-3, 3));
    }
    drawArc("micro_spray", "#ffffff", 0.75, m.cx + sunShift * 0.5, m.cy - m.h * 0.35, m.rx * 0.55, 190, 350);
  }

  // 7. Loose Chunks of Clear & Crushed Ice Scattered Around the Auger Hole
  for (let i = 0; i < 52; i++) {
    let ang = random(-35, 225);
    let dist = random(1.08, 2.35);
    let cx = ax + cos(ang) * rx * dist;
    let cy = ay + sin(ang) * ry * dist * 1.15;
    let sz = random(2.2, 7.5);

    // Tiny reflection in the dark polished ice directly below the ice chunk
    washPoly(makeEllipsePts(cx, cy + sz * 0.9, sz * 0.9, sz * 0.45, 8), "#6889ad", 95);
    // Tiny cast shadow
    drawLine("2H", "#112236", 0.42, cx - sz * 0.5, cy + sz * 0.45, cx + sz * 1.1, cy + sz * 0.55);
    // Shaded facet of ice chunk
    washPoly(makeEllipsePts(cx, cy, sz, sz * 0.62, 7, 0.8), "#a8c4e0", 220);
    // Sunlit crystalline facet
    washPoly(makeEllipsePts(cx - sz * 0.15, cy - sz * 0.18, sz * 0.65, sz * 0.42, 6, 0.5), "#ffffff", 245);
    drawLine("cpencil", "#ffffff", 0.4, cx - sz * 0.6, cy - sz * 0.3, cx + sz * 0.4, cy - sz * 0.2);
  }
}

// ============================================================================
// 9. FINAL ATMOSPHERIC GLAZE: Diamond Dust & Specular Ice Sparkles
// ============================================================================
function renderFinalGlaze() {
  // Subtle diamond-dust ice crystals glinting in the air beneath the pale sun and parhelia
  for (let i = 0; i < 95; i++) {
    let x = random(140, W - 140);
    let y = random(220, HY + 45);
    let dSun = dist(x, y, SX, SY);
    let dLeft = dist(x, y, SX - HR, SY);
    let dRight = dist(x, y, SX + HR, SY);
    if (dSun < 240 || dLeft < 110 || dRight < 110 || y > HY - 70) {
      drawLine("cpencil", "#ffffff", random(0.28, 0.52), x - 1.2, y, x + 1.2, y);
    }
  }

  // Razor-sharp specular glints on the foreground snow ripples and ice crack edges under the sun track
  for (let i = 0; i < 85; i++) {
    let t = random();
    let y = HY + 12 + pow(t, 1.3) * (H - HY - 24);
    let spread = lerp(65, 340, t);
    let x = SX + random(-spread, spread);
    let w = map(t, 0, 1, 0.25, 0.6);
    drawLine("cpencil", "#ffffff", w, x - random(2, 7) * t, y, x + random(2, 7) * t, y);
  }
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7391);
  noiseSeed(7391);

  brush.addField("cloud_flow", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let nx = col * 0.06;
        let ny = row * 0.06;
        let cx = col - field.length * 0.5;
        let cy = row - field[0].length * 0.35;
        let bowlAngle = atan2(cy, cx) * (180 / Math.PI);
        let n = noise(nx, ny, t * 0.1) * 70 - 35;
        field[col][row] = bowlAngle * 0.25 + n;
      }
    }
    return field;
  });
}

function resetBrush() {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.noField();
}

function drawPoly(pts, curvature = 0.08) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function makeArcBand(cx, cy, rIn, rOut, aStart, aEnd, steps, jitterAmt) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let f = i / steps;
    let a = lerp(aStart, aEnd, f);
    let n = (noise(cos(a) * 1.5 + 10, sin(a) * 1.5 + 10, rOut * 0.02) - 0.5) * 2 * jitterAmt;
    let r = rOut + n;
    pts.push([cx + cos(a) * r, cy + sin(a) * r * 0.94]);
  }
  for (let i = steps; i >= 0; i--) {
    let f = i / steps;
    let a = lerp(aStart, aEnd, f);
    let n = (noise(cos(a) * 1.5 + 30, sin(a) * 1.5 + 30, rIn * 0.02) - 0.5) * 2 * jitterAmt;
    let r = max(4, rIn + n);
    pts.push([cx + cos(a) * r, cy + sin(a) * r * 0.94]);
  }
  return pts;
}

function makeCloudBillow(cx, cy, rx, ry, lobes = 14, irregularity = 0.28) {
  let pts = [];
  for (let i = 0; i < lobes; i++) {
    let a = (i / lobes) * 360;
    let n = noise(cx * 0.005 + cos(a) * 1.3, cy * 0.005 + sin(a) * 1.3);
    let radX = rx * (1 + (n - 0.45) * irregularity * 2);
    let radY = ry * (1 + (n - 0.45) * irregularity * 1.8);
    // Flatter base, puffier top for cumulus billows
    if (sin(a) > 0) radY *= 0.72;
    pts.push([cx + cos(a) * radX, cy + sin(a) * radY]);
  }
  return pts;
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#e4ecf5");

  const GX = 600;
  const GY = 415;

  // =========================================================================
  // 1. SEA OF CLOUD & ATMOSPHERIC DEPTH (WATERCOLOUR WASHES)
  // =========================================================================
  resetBrush();
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.55, 0.18);

  // Distant high-altitude glacial mist bands
  const skyBands = [
    { y: -40, h: 200, col: "#b0c3dc", op: 55 },
    { y: 80,  h: 220, col: "#c4d4e8", op: 50 },
    { y: 200, h: 260, col: "#d5e2f2", op: 50 },
    { y: 360, h: 280, col: "#cad8ea", op: 48 },
    { y: 520, h: 320, col: "#b6c8df", op: 55 },
    { y: 660, h: 280, col: "#9ab0cc", op: 60 }
  ];

  for (let b of skyBands) {
    brush.fill(b.col, b.op);
    let pts = [
      [-60, b.y],
      [600, b.y + 35],
      [1260, b.y],
      [1260, b.y + b.h],
      [600, b.y + b.h + 45],
      [-60, b.y + b.h]
    ];
    drawPoly(pts, 0.3);
  }

  // Deep cloud troughs curving into the vertiginous valley basin
  const troughColors = ["#7f95b3", "#8ea4c2", "#9fb3ce", "#aebfd6"];
  for (let cIdx = 0; cIdx < troughColors.length; cIdx++) {
    brush.fill(troughColors[cIdx], 42);
    let count = 7;
    for (let i = 0; i < count; i++) {
      let yBase = map(i, 0, count - 1, 90, 740) + cIdx * 18;
      let spread = map(yBase, 80, 760, 260, 560);
      let side = (i % 2 === 0 ? -1 : 1) * random(60, 360);
      let cx = 600 + side;
      let cy = yBase + abs(side) * 0.12;
      // Avoid muddying the immediate glory center
      if (dist(cx, cy, GX, GY) < 165) cx += (cx < GX ? -180 : 180);
      let pts = makeCloudBillow(cx, cy, random(160, 310), random(42, 85), 14, 0.35);
      drawPoly(pts, 0.45);
    }
  }

  // =========================================================================
  // 2. WET-IN-WET WATERCOLOUR GLORY RING (BROCKEN SPECTRE HALO)
  // =========================================================================
  resetBrush();
  brush.fillBleed(0.48, "out");
  brush.fillTexture(0.62, 0.15);

  // Outer Secondary Diffraction Ring (delicate & wide, bleeding into mist)
  const outerGlory = [
    { rIn: 252, rOut: 294, col: "#e63b5a", op: 28, jit: 14 }, // Soft crimson-rose
    { rIn: 224, rOut: 258, col: "#ff9e00", op: 28, jit: 12 }, // Amber-gold
    { rIn: 198, rOut: 228, col: "#12c48b", op: 26, jit: 10 }, // Viridian-green
    { rIn: 178, rOut: 202, col: "#6c35de", op: 26, jit: 9 }   // Violet
  ];

  const segCountOuter = 14;
  for (let ring of outerGlory) {
    brush.fill(ring.col, ring.op);
    for (let s = 0; s < segCountOuter; s++) {
      let a0 = (s / segCountOuter) * 360 - 6;
      let a1 = ((s + 1) / segCountOuter) * 360 + 6;
      let pts = makeArcBand(GX, GY, ring.rIn, ring.rOut, a0, a1, 5, ring.jit);
      drawPoly(pts, 0.42);
    }
  }

  // Primary Glory Ring (vivid, saturated wet-in-wet concentric spectrum)
  const primaryGlory = [
    { rIn: 138, rOut: 176, col: "#ff2a55", op: 56, jit: 10 }, // Soft to vivid crimson red
    { rIn: 126, rOut: 152, col: "#ff5436", op: 46, jit: 9 },  // Vermilion-coral transition
    { rIn: 106, rOut: 134, col: "#ffaa00", op: 60, jit: 8 },  // Vivid luminous amber
    { rIn: 94,  rOut: 116, col: "#ffd000", op: 48, jit: 7 },  // Golden yellow transition
    { rIn: 80,  rOut: 104, col: "#1ae678", op: 54, jit: 7 },  // Vivid emerald-chartreuse green
    { rIn: 68,  rOut: 86,  col: "#00b4d8", op: 42, jit: 6 },  // Cyan-turquoise inner edge
    { rIn: 54,  rOut: 74,  col: "#6929ff", op: 58, jit: 6 }   // Saturated violet-indigo
  ];

  const segCountPri = 16;
  for (let ring of primaryGlory) {
    brush.fill(ring.col, ring.op);
    for (let s = 0; s < segCountPri; s++) {
      let a0 = (s / segCountPri) * 360 - 5;
      let a1 = ((s + 1) / segCountPri) * 360 + 5;
      let pts = makeArcBand(GX, GY, ring.rIn, ring.rOut, a0, a1, 5, ring.jit);
      drawPoly(pts, 0.4);
    }
  }

  // Wet-in-wet pigment blooms where glory colours bleed into surrounding cloud billows
  const bloomCols = [
    { r: 162, col: "#ff335c", op: 36 },
    { r: 120, col: "#ffae00", op: 38 },
    { r: 92,  col: "#15d67c", op: 35 },
    { r: 64,  col: "#7030ff", op: 36 }
  ];
  for (let b of bloomCols) {
    brush.fill(b.col, b.op);
    for (let i = 0; i < 8; i++) {
      let a = i * 45 + random(-15, 15);
      let bx = GX + cos(a) * (b.r + random(-10, 12));
      let by = GY + sin(a) * (b.r + random(-10, 12)) * 0.94;
      let pts = makeCloudBillow(bx, by, random(24, 46), random(18, 36), 9, 0.32);
      drawPoly(pts, 0.45);
    }
  }

  // Radiant golden-white central aureole (around anti-solar point)
  brush.fillBleed(0.42, "out");
  brush.fill("#fff3cc", 75);
  drawPoly(makeCloudBillow(GX, GY, 56, 52, 12, 0.15), 0.45);
  brush.fill("#ffffff", 95);
  drawPoly(makeCloudBillow(GX, GY, 38, 36, 12, 0.12), 0.45);

  // =========================================================================
  // 3. MILKY FOG BILLOWS BLEEDING INTO & SURROUNDING THE GLORY
  // =========================================================================
  resetBrush();
  brush.fillBleed(0.46, "out");
  brush.fillTexture(0.45, 0.12);

  // Soft pearl-white & ice-blue cloud crests framing the glory ring
  const milkyCrests = [
    { col: "#f2f7fc", op: 58, count: 18 },
    { col: "#ffffff", op: 65, count: 16 },
    { col: "#dce7f5", op: 48, count: 14 }
  ];

  for (let layer of milkyCrests) {
    brush.fill(layer.col, layer.op);
    for (let i = 0; i < layer.count; i++) {
      let angle = random(360);
      let minR = 165;
      let maxR = 540;
      let rad = random(minR, maxR);
      let cx = GX + cos(angle) * rad * 1.15;
      let cy = GY + sin(angle) * rad * 0.85;
      if (cy > 820) cy = random(520, 790);
      let rx = map(cy, 60, 800, 90, 230) * random(0.8, 1.3);
      let ry = rx * random(0.32, 0.52);
      drawPoly(makeCloudBillow(cx, cy, rx, ry, 12, 0.3), 0.45);
    }
  }

  // Billowing cloud deck directly beneath the hiker shadow (y: 470..810)
  const lowerMistRolls = [
    { cx: 600, cy: 525, rx: 190, ry: 55, col: "#e9f1fa", op: 52 },
    { cx: 470, cy: 590, rx: 220, ry: 68, col: "#d5e2f2", op: 55 },
    { cx: 730, cy: 605, rx: 230, ry: 70, col: "#dce8f6", op: 55 },
    { cx: 595, cy: 655, rx: 260, ry: 74, col: "#f4f8fd", op: 62 },
    { cx: 420, cy: 710, rx: 250, ry: 78, col: "#c4d4e8", op: 58 },
    { cx: 780, cy: 720, rx: 260, ry: 80, col: "#cad9ec", op: 58 },
    { cx: 600, cy: 745, rx: 290, ry: 82, col: "#eef4fb", op: 68 }
  ];
  for (let m of lowerMistRolls) {
    brush.fill(m.col, m.op);
    drawPoly(makeCloudBillow(m.cx, m.cy, m.rx, m.ry, 14, 0.25), 0.45);
  }

  // Fine vapour currents across the cloud sea using vector field
  resetBrush();
  brush.field("cloud_flow");
  const mistStrokeCols = ["#ffffff", "#f0f6fc", "#bfd0e6", "#9ab0cc"];
  for (let c of mistStrokeCols) {
    brush.set("charcoal", c, 0.45);
    for (let i = 0; i < 42; i++) {
      let sx = random(40, 1160);
      let sy = random(40, 770);
      if (dist(sx, sy, GX, GY) < 130) continue;
      let dir = sx < 600 ? random(-25, 25) : random(155, 205);
      brush.flowLine(sx, sy, random(50, 140), dir);
    }
  }
  resetBrush();

  // Subtle watercolour mist spray around the glory ring
  const sprayRingCols = ["#ff4d6d", "#ffbe0b", "#1AE678", "#7030ff", "#ffffff"];
  for (let sc of sprayRingCols) {
    brush.set("spray", sc, 0.7);
    for (let i = 0; i < 16; i++) {
      let a = random(360);
      let r = sc === "#ffffff" ? random(25, 240) : random(65, 195);
      let x1 = GX + cos(a) * r;
      let y1 = GY + sin(a) * r * 0.94;
      brush.line(x1, y1, x1 + cos(a + 90) * 18, y1 + sin(a + 90) * 18);
    }
  }
  resetBrush();

  // =========================================================================
  // 4. THE EERIE ELONGATED HIKER SHADOW (CAST ONTO THE CLOUD SEA)
  // =========================================================================
  resetBrush();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.5, 0.22);

  // Optical anti-crepuscular shadow rays radiating from anti-solar point
  brush.fill("#586987", 24);
  const rayAngles = [62, 78, 92, 106, 120, 20, 160, 205, 335];
  for (let ra of rayAngles) {
    let r1 = 42;
    let r2 = ra > 50 && ra < 130 ? 370 : 250;
    let wAng = random(3.5, 6.5);
    let rayPts = [
      [GX + cos(ra - wAng * 0.4) * r1, GY + sin(ra - wAng * 0.4) * r1],
      [GX + cos(ra + wAng * 0.4) * r1, GY + sin(ra + wAng * 0.4) * r1],
      [GX + cos(ra + wAng) * r2, GY + sin(ra + wAng) * r2],
      [GX + cos(ra - wAng) * r2, GY + sin(ra - wAng) * r2]
    ];
    drawPoly(rayPts, 0.2);
  }

  // Build elongated hiker shadow geometry:
  // Head centered at (GX=600, GY=415), torso & pack, poised arms, trekking pole,
  // and long perspective legs undulating slightly over the cloud billows down to y=805
  function getHikerShadowPts(inflate = 0) {
    return [
      // Top of hooded head (at glory center)
      [600, 396 - inflate],
      [614 + inflate, 401 - inflate * 0.5],
      [618 + inflate, 416],
      // Neck & right shoulder + expedition pack top
      [614 + inflate, 429],
      [634 + inflate, 434 - inflate * 0.3],
      // Right arm extended slightly holding trekking pole
      [656 + inflate, 452],
      [672 + inflate, 468],
      [666 + inflate, 478 + inflate],
      [648 + inflate, 466 + inflate],
      // Right side of backpack & torso
      [642 + inflate, 488],
      [636 + inflate, 518],
      [626 + inflate, 536],
      // Right elongated leg undulating over cloud waves
      [636 + inflate, 585],
      [642 + inflate, 635],
      [654 + inflate, 690],
      [660 + inflate, 745],
      [672 + inflate, 805 + inflate],
      // Right boot base on ridge lip
      [638 - inflate, 808 + inflate],
      // Inner right leg ascending to stride split
      [630 - inflate, 745],
      [618 - inflate, 688],
      [612 - inflate, 632],
      [605 - inflate, 578],
      // Pelvis split
      [598, 544 + inflate],
      // Inner left leg descending
      [590 + inflate, 580],
      [582 + inflate, 635],
      [570 + inflate, 692],
      [560 + inflate, 748],
      [548 + inflate, 806 + inflate],
      // Left boot base on ridge lip
      [514 - inflate, 804 + inflate],
      // Outer left leg ascending
      [532 - inflate, 745],
      [540 - inflate, 688],
      [554 - inflate, 632],
      [562 - inflate, 582],
      [574 - inflate, 536],
      // Left side of backpack & hip
      [564 - inflate, 515],
      [558 - inflate, 482],
      // Left elbow poised for balance
      [542 - inflate, 474],
      [538 - inflate, 458],
      [556 - inflate, 442],
      // Left shoulder & neck
      [572 - inflate, 433],
      [586 - inflate, 429],
      [582 - inflate, 416],
      [586 - inflate, 401 - inflate * 0.5]
    ];
  }

  // Layer 1: Faint prismatic violet-blue diffraction fringe around the shadow
  brush.fillBleed(0.35, "out");
  brush.fill("#56489c", 32);
  drawPoly(getHikerShadowPts(9), 0.35);

  // Layer 2: Soft penumbra of the shadow on mist
  brush.fillBleed(0.26, "out");
  brush.fill("#3d4b66", 58);
  drawPoly(getHikerShadowPts(3), 0.32);

  // Layer 3: Deeper slate-indigo umbra core
  brush.fillBleed(0.16, "out");
  brush.fill("#222b3d", 78);
  drawPoly(getHikerShadowPts(-2.5), 0.28);

  // Dense core in head/torso silhouette at center of glory
  brush.fillBleed(0.12, "in");
  brush.fill("#161d2b", 82);
  drawPoly([
    [600, 400], [613, 406], [614, 426], [634, 440],
    [636, 495], [620, 535], [580, 535], [564, 492],
    [568, 440], [586, 426], [587, 406]
  ], 0.3);

  // Elongated trekking pole shadow line cast onto the clouds
  resetBrush();
  brush.set("charcoal", "#313d54", 1.1);
  brush.spline([
    [666, 442, 0.6],
    [678, 510, 0.8],
    [696, 595, 0.7],
    [710, 680, 0.6],
    [732, 775, 0.4]
  ], 0.35);

  // Delicate translucent mist wisps drifting across the lower shadow legs
  resetBrush();
  brush.fillBleed(0.45, "out");
  brush.fill("#eef5fc", 46);
  drawPoly(makeCloudBillow(600, 615, 130, 24, 10, 0.25), 0.45);
  drawPoly(makeCloudBillow(590, 715, 165, 28, 10, 0.25), 0.45);
  resetBrush();

  // =========================================================================
  // 5. HYPERREAL FOREGROUND GRANITE RIDGE (GRAPHITE, FINE PEN & WASHES)
  // =========================================================================
  // Construct a 3D-informed geological granite mesh across the foreground:
  // Left crag rises to y~535, central pulpit lip sits at y~765, right crag rises to y~575.
  const COLS = 20;
  const ROWS = 8;
  let nodes = [];

  function ridgeLipY(x) {
    let u = (x - 600) / 600; // -1 to 1
    // Deep saddle in center (pulpit), steep buttresses on left & right
    let base = 772 - 235 * pow(abs(u), 1.65);
    // Central pulpit nose juts slightly up/out around x=460..740
    let pulpit = -26 * exp(-pow((x - 595) / 145, 2));
    // Gullies flanking the central pulpit around x=340 and x=850
    let leftGully = 48 * exp(-pow((x - 335) / 75, 2));
    let rightGully = 44 * exp(-pow((x - 855) / 75, 2));
    // Sharp angular granite crag steps
    let n = (noise(x * 0.008, 1.7) - 0.5) * 38 + (noise(x * 0.025, 4.3) - 0.5) * 16;
    return base + pulpit + leftGully + rightGully + n;
  }

  for (let r = 0; r <= ROWS; r++) {
    let rowArr = [];
    let rf = r / ROWS;
    // Non-linear row spacing: tighter near the precipice lip for intricate cliff steps
    let t = pow(rf, 1.18);
    for (let c = 0; c <= COLS; c++) {
      let cf = c / COLS;
      let bx = lerp(-50, 1250, cf);
      let jx = (r > 0 && c > 0 && c < COLS) ? (noise(c * 0.7, r * 0.7, 10) - 0.5) * 42 : 0;
      let x = bx + jx;
      let yTop = ridgeLipY(x);
      let jy = (r > 0 && r < ROWS) ? (noise(c * 0.8, r * 0.8, 25) - 0.5) * 28 : 0;
      let y = lerp(yTop, 1245, t) + jy;

      // Simulated 3D elevation z for geological lighting & strata dip
      // Ledges step upwards and backwards toward the viewer; cliff drops plunge at r=0..2
      let stepTerrace = floor(rf * 4.5) * 35 + (rf * 4.5 - floor(rf * 4.5)) * 18;
      let gullyDip = -40 * exp(-pow((x - 335) / 85, 2)) - 38 * exp(-pow((x - 855) / 85, 2));
      let pulpitRise = 45 * exp(-pow((x - 595) / 180, 2));
      let rockFacetZ = (noise(c * 1.1, r * 1.1, 40) - 0.45) * 55;
      // Sharp vertical drop right at the lip (r === 0 vs r === 1)
      let cliffDrop = (r === 0) ? -85 : (r === 1 ? -22 : 0);
      let z = stepTerrace + gullyDip + pulpitRise + rockFacetZ + cliffDrop;

      rowArr.push({ x, y, z });
    }
    nodes.push(rowArr);
  }

  // First, lay a solid dark-slate under-silhouette for the entire ridge so zero sky shows through cracks
  resetBrush();
  let silhouettePts = [];
  for (let c = 0; c <= COLS; c++) {
    silhouettePts.push([nodes[0][c].x, nodes[0][c].y + 2]);
  }
  silhouettePts.push([1260, 1260]);
  silhouettePts.push([-60, 1260]);
  brush.wash("#1a202c", 255);
  drawPoly(silhouettePts, 0.02);
  resetBrush();

  // Helper to compute lighting & draw a hyperreal granite facet
  function renderGraniteFacet(p1, p2, p3, p4, isQuad = true) {
    let pts = isQuad ? [
      [p1.x, p1.y], [p2.x, p2.y], [p3.x, p3.y], [p4.x, p4.y]
    ] : [
      [p1.x, p1.y], [p2.x, p2.y], [p3.x, p3.y]
    ];

    // Compute 3D normal from (p1, p2, p3)
    let ux = p2.x - p1.x, uy = p2.y - p1.y, uz = p2.z - p1.z;
    let vx = p3.x - p1.x, vy = p3.y - p1.y, vz = p3.z - p1.z;
    let nx = uy * vz - uz * vy;
    let ny = uz * vx - ux * vz;
    let nz = ux * vy - uy * vx;
    let len = sqrt(nx * nx + ny * ny + nz * nz) || 1;
    nx /= len; ny /= len; nz /= len;
    if (nz < 0) { nx = -nx; ny = -ny; nz = -nz; }

    // Sun is behind and above viewer, shining down & forward toward anti-solar point
    let sunX = 0.08, sunY = 0.58, sunZ = 0.81;
    let dot = nx * sunX + ny * sunY + nz * sunZ;
    let light = constrain(map(dot, -0.35, 0.92, 0.05, 1.0), 0.04, 1.0);

    // Precipice front cliff faces (where y is near the lip and dropping steeply) are in deep chasm shadow
    let avgY = (p1.y + p2.y + p3.y) / 3;
    let avgX = (p1.x + p2.x + p3.x) / 3;
    let lipRef = ridgeLipY(avgX);
    if (avgY - lipRef < 48 && ny < 0.15) {
      light *= 0.38;
    }

    // Select cold granite palette (pearl grey, blue-white, slate, charcoal)
    let washCol, toneCol, hatchCol1, hatchCol2;
    if (light > 0.78) {
      washCol = "#dfe6f0";
      toneCol = "#eef4fa";
      hatchCol1 = "#7e8ea3";
      hatchCol2 = "#5a687c";
    } else if (light > 0.58) {
      washCol = "#bcc8d8";
      toneCol = "#cfd9e6";
      hatchCol1 = "#526073";
      hatchCol2 = "#374252";
    } else if (light > 0.36) {
      washCol = "#7d8c9f";
      toneCol = "#647387";
      hatchCol1 = "#2d3645";
      hatchCol2 = "#1b222e";
    } else if (light > 0.20) {
      washCol = "#465366";
      toneCol = "#333e4f";
      hatchCol1 = "#19202b";
      hatchCol2 = "#0f141c";
    } else {
      washCol = "#27303f";
      toneCol = "#1b222e";
      hatchCol1 = "#10151e";
      hatchCol2 = "#090c12";
    }

    // 1. Opaque mineral base wash
    resetBrush();
    brush.wash(washCol, 250);
    drawPoly(pts, 0.02);
    brush.noWash();

    // 2. Subtle granulated stone undertone
    brush.fillBleed(0.03, "in");
    brush.fillTexture(0.75, 0.35);
    brush.fill(toneCol, light > 0.65 ? 75 : 95);
    drawPoly(pts, 0.02);
    brush.noFill();

    // 3. Crisp directional graphite & fine pen hatching aligned with rock cleavage
    let dipAngle = atan2(ny, nx) * (180 / Math.PI);
    let strikeAngle = dipAngle + 90;

    if (light > 0.72) {
      // Sunlit slab: delicate 2H graphite grain + bright cpencil glint
      brush.hatchStyle("2H", hatchCol1, 0.45);
      brush.hatch(7.5, strikeAngle * 0.35 + 12, { rand: 0.03, gradient: 0.45 });
      drawPoly(pts, 0.02);
      brush.noHatch();
    } else if (light > 0.42) {
      // Mid-tone cleavage plane: crisp HB hatching + secondary 2H cleavage lines
      brush.hatchStyle("HB", hatchCol1, 0.58);
      brush.hatch(5.2, dipAngle * 0.5 + 25, { rand: 0.04, gradient: 0.3 });
      drawPoly(pts, 0.02);
      brush.hatchStyle("2H", hatchCol2, 0.42);
      brush.hatch(8.0, strikeAngle * 0.4 - 18, { rand: 0.03 });
      drawPoly(pts, 0.02);
      brush.noHatch();
    } else {
      // Steep shadow chasm wall: dense 2B graphite + sharp rotring cross-hatching
      let sp1 = map(light, 0.04, 0.42, 3.2, 4.8);
      brush.hatchStyle("2B", hatchCol1, 0.75);
      brush.hatch(sp1, 78 + nx * 25, { rand: 0.04, gradient: 0.2 });
      drawPoly(pts, 0.02);

      brush.hatchStyle("rotring", hatchCol2, 0.48);
      brush.hatch(sp1 + 1.2, -16 + ny * 20, { rand: 0.03 });
      drawPoly(pts, 0.02);
      brush.noHatch();
    }

    // 4. Crisp joint-plane outline & sunlit bevel highlight
    resetBrush();
    brush.set("rotring", hatchCol2, light < 0.35 ? 0.65 : 0.42);
    drawPoly(pts, 0.02);

    if (light > 0.55) {
      brush.set("cpencil", "#f5f9ff", 0.55);
      brush.line(p1.x, p1.y + 1, p2.x, p2.y + 1);
    }

    // 5. Internal diaclase fracture cracks & crystalline mineral ticks
    let areaApprox = abs((p2.x - p1.x) * (p3.y - p1.y) - (p3.x - p1.x) * (p2.y - p1.y)) * 0.5;
    if (areaApprox > 1800) {
      let numCracks = floor(map(areaApprox, 1800, 14000, 1, 4));
      for (let k = 0; k < numCracks; k++) {
        let f1 = random(0.18, 0.82);
        let f2 = random(0.18, 0.82);
        let sx = lerp(p1.x, p2.x, f1);
        let sy = lerp(p1.y, p2.y, f1);
        let ex = lerp(p3.x, isQuad ? p4.x : p1.x, f2);
        let ey = lerp(p3.y, isQuad ? p4.y : p1.y, f2);
        let mx = (sx + ex) * 0.5 + random(-14, 14);
        let my = (sy + ey) * 0.5 + random(-10, 10);

        brush.set("rotring", "#121721", random(0.35, 0.65));
        brush.spline([[sx, sy, 0.3], [mx, my, 0.9], [ex, ey, 0.2]], 0.2);

        if (light > 0.45) {
          brush.set("cpencil", "#ffffff", 0.4);
          brush.line(sx + 1.2, sy + 1.2, mx + 1.2, my + 1.2);
        }
      }
    }
    resetBrush();
  }

  // Render the entire granite mesh row by row (back to front)
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      let n00 = nodes[r][c];
      let n10 = nodes[r][c + 1];
      let n11 = nodes[r + 1][c + 1];
      let n01 = nodes[r + 1][c];

      // Split some quads diagonally into sharp triangular cleavage facets for geological realism
      if ((r + c) % 3 === 0 || r === 0) {
        renderGraniteFacet(n00, n10, n11, null, false);
        renderGraniteFacet(n00, n11, n01, null, false);
      } else {
        renderGraniteFacet(n00, n10, n11, n01, true);
      }
    }
  }

  // =========================================================================
  // 6. MONUMENTAL FOREGROUND GRANITE SLABS & STEPPED LEDGES (CENTRAL PULPIT)
  // =========================================================================
  // Add prominent, hyper-detailed 3D granite block slabs on the foreground ridge
  // where the hiker stands, each with a sunlit top table, steep dark front riser, and side face.
  const heroSlabs = [
    // Left foreground crag block
    { cx: 175, cy: 865, w: 230, d: 88, h: 48, tilt: -14 },
    { cx: 245, cy: 1020, w: 290, d: 115, h: 56, tilt: -8 },
    // Right foreground crag block
    { cx: 1025, cy: 890, w: 240, d: 92, h: 52, tilt: 15 },
    { cx: 955, cy: 1045, w: 300, d: 120, h: 60, tilt: 10 },
    // Central precipice pulpit slabs (boot-scuffed zone)
    { cx: 525, cy: 825, w: 210, d: 72, h: 36, tilt: -3 },
    { cx: 685, cy: 838, w: 200, d: 68, h: 34, tilt: 5 },
    { cx: 590, cy: 935, w: 340, d: 110, h: 44, tilt: -1 },
    { cx: 455, cy: 1070, w: 280, d: 118, h: 48, tilt: -4 },
    { cx: 735, cy: 1085, w: 295, d: 124, h: 50, tilt: 4 },
    { cx: 600, cy: 1155, w: 420, d: 125, h: 45, tilt: 0 }
  ];

  let sunlitSlabTops = [];

  for (let s of heroSlabs) {
    let hw = s.w * 0.5;
    let hd = s.d * 0.5;
    let ang = s.tilt;
    let ca = cos(ang), sa = sin(ang);

    function rotPt(lx, ly) {
      return [s.cx + lx * ca - ly * sa, s.cy + lx * sa + ly * ca];
    }

    // 6-vertex irregular cleaved top polygon
    let topPts = [
      rotPt(-hw * 0.85 + random(-8, 8), -hd + random(-5, 5)),
      rotPt(hw * 0.2 + random(-10, 10), -hd * 1.06 + random(-5, 5)),
      rotPt(hw + random(-8, 8), -hd * 0.35 + random(-6, 6)),
      rotPt(hw * 0.82 + random(-8, 8), hd * 0.88 + random(-6, 6)),
      rotPt(-hw * 0.25 + random(-10, 10), hd + random(-6, 6)),
      rotPt(-hw + random(-8, 8), hd * 0.25 + random(-6, 6))
    ];

    sunlitSlabTops.push({ pts: topPts, cx: s.cx, cy: s.cy, w: s.w, d: s.d });

    // Front-top riser face (facing the abyss in deep crisp shadow)
    let riser1 = [
      topPts[5], topPts[0], topPts[1],
      [topPts[1][0], topPts[1][1] - s.h],
      [topPts[0][0] - 6, topPts[0][1] - s.h * 1.05],
      [topPts[5][0] - 8, topPts[5][1] - s.h * 0.85]
    ];
    let riser2 = [
      topPts[1], topPts[2],
      [topPts[2][0] + 6, topPts[2][1] - s.h * 0.8],
      [topPts[1][0], topPts[1][1] - s.h]
    ];

    // Cast shadow under the riser onto the rock below
    resetBrush();
    brush.wash("#141923", 230);
    drawPoly([
      [topPts[5][0] - 12, topPts[5][1] - s.h * 0.85],
      [topPts[0][0] - 6, topPts[0][1] - s.h * 1.25],
      [topPts[2][0] + 10, topPts[2][1] - s.h * 0.95],
      topPts[2], topPts[0], topPts[5]
    ], 0.02);

    // Draw dark front riser 1
    brush.wash("#222b3a", 252);
    drawPoly(riser1, 0.02);
    brush.noWash();
    brush.hatchStyle("2B", "#11161f", 0.72);
    brush.hatch(3.2, 82 + s.tilt, { rand: 0.03, gradient: 0.25 });
    drawPoly(riser1, 0.02);
    brush.hatchStyle("rotring", "#090c12", 0.48);
    brush.hatch(4.5, -12 + s.tilt, { rand: 0.02 });
    drawPoly(riser1, 0.02);
    brush.noHatch();
    brush.set("rotring", "#0c1017", 0.65);
    drawPoly(riser1, 0.02);

    // Draw mid-dark side riser 2
    resetBrush();
    brush.wash("#3c485c", 252);
    drawPoly(riser2, 0.02);
    brush.noWash();
    brush.hatchStyle("HB", "#1e2530", 0.6);
    brush.hatch(4.0, 68 + s.tilt, { rand: 0.03 });
    drawPoly(riser2, 0.02);
    brush.noHatch();
    brush.set("rotring", "#121721", 0.55);
    drawPoly(riser2, 0.02);

    // Draw sunlit top slab table (pearl grey / blue-white hyperreal granite)
    resetBrush();
    brush.wash("#d8e1ed", 252);
    drawPoly(topPts, 0.02);
    brush.noWash();

    brush.fillBleed(0.03, "in");
    brush.fillTexture(0.7, 0.35);
    brush.fill("#ebf1f8", 85);
    drawPoly(topPts, 0.02);
    brush.noFill();

    brush.hatchStyle("2H", "#7c8b9e", 0.45);
    brush.hatch(6.5, s.tilt + 8, { rand: 0.03, gradient: 0.4 });
    drawPoly(topPts, 0.02);
    brush.hatchStyle("2H", "#95a4b8", 0.35);
    brush.hatch(9.0, s.tilt - 28, { rand: 0.03 });
    drawPoly(topPts, 0.02);
    brush.noHatch();

    // Razor-sharp pen contour + quartz edge highlight along the front lip
    brush.set("rotring", "#1b222e", 0.55);
    drawPoly(topPts, 0.02);

    brush.set("cpencil", "#ffffff", 0.75);
    brush.line(topPts[5][0], topPts[5][1], topPts[0][0], topPts[0][1]);
    brush.line(topPts[0][0], topPts[0][1], topPts[1][0], topPts[1][1]);
    brush.line(topPts[1][0], topPts[1][1], topPts[2][0], topPts[2][1]);

    // Fine internal cleavage striation lines on the slab
    for (let m = 0; m < 5; m++) {
      let f = random(0.15, 0.85);
      let xA = lerp(topPts[5][0], topPts[4][0], f) + random(-10, 10);
      let yA = lerp(topPts[5][1], topPts[4][1], f) + random(-6, 6);
      let xB = lerp(topPts[1][0], topPts[3][0], f) + random(-10, 10);
      let yB = lerp(topPts[1][1], topPts[3][1], f) + random(-6, 6);
      let xM = (xA + xB) * 0.5 + random(-12, 12);
      let yM = (yA + yB) * 0.5 + random(-8, 8);

      brush.set("rotring", "#2b3545", random(0.3, 0.5));
      brush.spline([[xA, yA, 0.2], [xM, yM, 0.8], [xB, yB, 0.2]], 0.25);
      brush.set("cpencil", "#ffffff", 0.38);
      brush.line(xA, yA + 1.2, xM, yM + 1.2);
    }
    resetBrush();
  }

  // =========================================================================
  // 7. CRYSTALLINE GRANITE GRAIN (BIOTITE MICA, QUARTZ & FELDSPAR SPECKLE)
  // =========================================================================
  resetBrush();
  // Fine spray grain across foreground rock
  const graniteSprayCols = [
    { col: "#141923", w: 0.55, n: 55 }, // Black biotite mica
    { col: "#ffffff", w: 0.60, n: 50 }, // White quartz glints
    { col: "#5a697d", w: 0.50, n: 45 }  // Grey feldspar
  ];
  for (let gs of graniteSprayCols) {
    brush.set("spray", gs.col, gs.w);
    for (let i = 0; i < gs.n; i++) {
      let gx = random(30, 1170);
      let minY = ridgeLipY(gx) + 12;
      let gy = random(minY, 1190);
      brush.line(gx, gy, gx + random(-22, 22), gy + random(-12, 12));
    }
  }

  // Crisp micro-ticks in rotring & 2B for hyperreal mineral crystal facets
  const crystalTicks = [
    { brush: "rotring", col: "#121720", w: 0.42, count: 280 },
    { brush: "2H",      col: "#485669", w: 0.48, count: 220 },
    { brush: "cpencil", col: "#ffffff", w: 0.52, count: 180 }
  ];
  for (let ct of crystalTicks) {
    brush.set(ct.brush, ct.col, ct.w);
    for (let i = 0; i < ct.count; i++) {
      let tx = random(20, 1180);
      let minY = ridgeLipY(tx) + 8;
      if (minY > 1190) continue;
      let ty = random(minY, 1195);
      let len = random(2, 5.5);
      let a = random(-35, 35);
      brush.line(tx, ty, tx + cos(a) * len, ty + sin(a) * len);
    }
  }
  resetBrush();

  // =========================================================================
  // 8. VIVID BOOT-SCUFFED LICHEN & ANGULAR SCREE STONES
  // =========================================================================
  // Lichen colonies grow across the sunlit granite slabs:
  // 1) Xanthoria elegans (vivid sunburst orange, vermilion-amber, cadmium gold)
  // 2) Rhizocarpon geographicum (electric map-lichen chartreuse, acid lime, emerald)
  // 3) Parmelia / Lecanora (pale pearl-sage crustose rosettes)
  const lichenPalette = [
    // Vivid chartreuse / emerald map-lichen
    { main: "#a8e600", hi: "#d9ff38", rim: "#151a21", dot: "#10141a", weight: 0.42 },
    { main: "#72cc00", hi: "#b8f500", rim: "#18201c", dot: "#121715", weight: 0.38 },
    { main: "#2ec462", hi: "#80ed99", rim: "#14211b", dot: "#0e1713", weight: 0.25 },
    // Vivid sunburst orange / amber lichen
    { main: "#ff5500", hi: "#ff9900", rim: "#2b160c", dot: "#bf2a00", weight: 0.45 },
    { main: "#ff8000", hi: "#ffc400", rim: "#2e1c0d", dot: "#d93800", weight: 0.40 },
    // Pale grey-green alpine crustose lichen
    { main: "#9eb39d", hi: "#dce8da", rim: "#2a332c", dot: "#3b473e", weight: 0.25 }
  ];

  function drawLichenColony(cx, cy, radius, pal) {
    resetBrush();
    // Dark prothallus base rim (characteristic of alpine map-lichen)
    let rimPts = makeCloudBillow(cx, cy, radius * 1.08, radius * 0.68, 12, 0.28);
    brush.wash(pal.rim, 235);
    drawPoly(rimPts, 0.2);

    // Clustered crustose thallus areoles (mosaic of vivid scales)
    let numAreoles = floor(map(radius, 12, 48, 7, 24));
    brush.wash(pal.main, 248);
    for (let i = 0; i < numAreoles; i++) {
      let a = random(360);
      let d = random(0, radius * 0.78);
      let ax = cx + cos(a) * d;
      let ay = cy + sin(a) * d * 0.64;
      let arx = random(3.5, 9.5);
      let ary = arx * random(0.6, 0.85);
      let aPts = makeCloudBillow(ax, ay, arx, ary, 7, 0.22);
      drawPoly(aPts, 0.15);
    }

    // Luminous saturated center highlights
    brush.wash(pal.hi, 240);
    for (let i = 0; i < floor(numAreoles * 0.55); i++) {
      let a = random(360);
      let d = random(0, radius * 0.58);
      let ax = cx + cos(a) * d;
      let ay = cy + sin(a) * d * 0.62;
      let arx = random(2.2, 5.5);
      let aPts = makeCloudBillow(ax, ay, arx, arx * 0.72, 6, 0.2);
      drawPoly(aPts, 0.15);
    }
    brush.noWash();

    // Crisp fine-pen cellular boundaries & apothecia spore dots
    brush.set("rotring", pal.rim, 0.35);
    drawPoly(rimPts, 0.2);
    for (let i = 0; i < numAreoles; i++) {
      let a = random(360);
      let d = random(0, radius * 0.75);
      let ax = cx + cos(a) * d;
      let ay = cy + sin(a) * d * 0.64;
      brush.line(ax - 2, ay, ax + 2, ay + 1);
    }
    resetBrush();
  }

  // Place lichen colonies across the foreground granite slabs (concentrated on the central pulpit)
  for (let slab of sunlitSlabTops) {
    let colonyCount = slab.cx > 350 && slab.cx < 850 ? 6 : 3;
    for (let c = 0; c < colonyCount; c++) {
      let lx = slab.cx + random(-slab.w * 0.36, slab.w * 0.36);
      let ly = slab.cy + random(-slab.d * 0.32, slab.d * 0.32);
      let rad = random(14, 38);
      let pal = lichenPalette[floor(random(lichenPalette.length))];
      drawLichenColony(lx, ly, rad, pal);
    }
  }

  // Additional smaller lichen patches along the rock ledges
  for (let i = 0; i < 28; i++) {
    let lx = random(80, 1120);
    let minY = ridgeLipY(lx) + 25;
    if (minY > 1160) continue;
    let ly = random(minY, 1175);
    let rad = random(10, 26);
    let pal = lichenPalette[floor(random(lichenPalette.length))];
    drawLichenColony(lx, ly, rad, pal);
  }

  // =========================================================================
  // 9. BOOT SCUFFS, VIBRAM TREAD MARKS & SCRAPED LICHEN CRUMBS
  // =========================================================================
  // Where the hiker stepped to the precipice edge: heavy boot scrapes gouge through
  // the lichen mats, exposing raw white scratched quartz, dark rubber lugs, and torn lichen crumbs.
  const bootScuffs = [
    // Left boot scuff approaching the left stance at (525, 825)
    { x1: 485, y1: 945, x2: 530, y2: 818, w: 46 },
    // Right boot scuff approaching the right stance at (670, 835)
    { x1: 715, y1: 965, x2: 665, y2: 828, w: 48 },
    // Lower foreground pivot step on the central altar slab (590, 935..1090)
    { x1: 565, y1: 1125, x2: 605, y2: 965, w: 54 },
    // Secondary heel skid on the lower-left slab
    { x1: 435, y1: 1095, x2: 475, y2: 1020, w: 38 }
  ];

  for (let bs of bootScuffs) {
    let dx = bs.x2 - bs.x1;
    let dy = bs.y2 - bs.y1;
    let len = sqrt(dx * dx + dy * dy);
    let ang = atan2(dy, dx) * (180 / Math.PI);
    let nx = -dy / len;
    let ny = dx / len;

    // 1. Raw abraded granite patch where lichen was scraped off
    resetBrush();
    let scuffPoly = [
      [bs.x1 + nx * bs.w * 0.45, bs.y1 + ny * bs.w * 0.45],
      [bs.x2 + nx * bs.w * 0.38, bs.y2 + ny * bs.w * 0.38],
      [bs.x2 - nx * bs.w * 0.38, bs.y2 - ny * bs.w * 0.38],
      [bs.x1 - nx * bs.w * 0.45, bs.y1 - ny * bs.w * 0.45]
    ];
    brush.wash("#dce5f0", 220);
    drawPoly(scuffPoly, 0.15);
    brush.noWash();

    // 2. Dark rubber boot-sole lug tread smudges (transverse bars along the boot path)
    let numLugs = floor(len / 13);
    for (let i = 0; i < numLugs; i++) {
      let f = (i + 0.5) / numLugs;
      let cx = lerp(bs.x1, bs.x2, f);
      let cy = lerp(bs.y1, bs.y2, f);
      let lugW = bs.w * random(0.28, 0.42);

      // Left & right Vibram cleat marks
      for (let side of [-1, 1]) {
        let lx1 = cx + nx * side * (lugW * 0.25);
        let ly1 = cy + ny * side * (lugW * 0.25);
        let lx2 = cx + nx * side * lugW;
        let ly2 = cy + ny * side * lugW;
        brush.set("2B", "#232a36", random(0.85, 1.35));
        brush.line(lx1, ly1, lx2, ly2);
      }
    }

    // 3. Sharp white quartz scratch grooves from grit/crampon points under the boot
    for (let s = 0; s < 14; s++) {
      let offset = random(-bs.w * 0.42, bs.w * 0.42);
      let fStart = random(0, 0.35);
      let fEnd = random(0.65, 1.05);
      let sx1 = lerp(bs.x1, bs.x2, fStart) + nx * offset;
      let sy1 = lerp(bs.y1, bs.y2, fStart) + ny * offset;
      let sx2 = lerp(bs.x1, bs.x2, fEnd) + nx * (offset + random(-6, 6));
      let sy2 = lerp(bs.y1, bs.y2, fEnd) + ny * (offset + random(-6, 6));

      brush.set("cpencil", "#ffffff", random(0.55, 0.95));
      brush.line(sx1, sy1, sx2, sy2);

      // Crisp dark micro-groove right beside the white quartz scratch
      brush.set("rotring", "#2b3442", 0.35);
      brush.line(sx1 + 1.2, sy1 + 1.2, sx2 + 1.2, sy2 + 1.2);
    }

    // 4. Dislodged, crumbled vivid orange & chartreuse lichen flakes scattered beside the scuff
    for (let f = 0; f < 26; f++) {
      let t = random(-0.05, 1.08);
      let side = (random() < 0.5 ? -1 : 1) * random(bs.w * 0.25, bs.w * 0.85);
      let fx = lerp(bs.x1, bs.x2, t) + nx * side + random(-8, 8);
      let fy = lerp(bs.y1, bs.y2, t) + ny * side + random(-8, 8);
      let flakeR = random(1.8, 4.5);
      let flakeCol = random() < 0.52
        ? (random() < 0.5 ? "#ff5500" : "#ff9e00")
        : (random() < 0.5 ? "#a8e600" : "#d9ff38");

      resetBrush();
      // Tiny dark shadow under the dislodged lichen crumb
      brush.wash("#121720", 230);
      drawPoly(makeCloudBillow(fx + 1.5, fy + 1.8, flakeR, flakeR * 0.75, 5, 0.2), 0.1);
      // Vivid lichen crumb
      brush.wash(flakeCol, 250);
      drawPoly(makeCloudBillow(fx, fy, flakeR, flakeR * 0.75, 5, 0.2), 0.1);
      brush.noWash();
      brush.set("rotring", "#161c26", 0.3);
      brush.line(fx - flakeR, fy, fx + flakeR, fy);
    }
    resetBrush();
  }

  // =========================================================================
  // 10. LOOSE ANGULAR GRANITE SCREE CHIPS & PRECIPICE EDGE DETAILS
  // =========================================================================
  // Scatter razor-sharp angular granite gravel & fractured stone chips on the ledges
  for (let i = 0; i < 65; i++) {
    let sx = random(70, 1130);
    let minY = ridgeLipY(sx) + 16;
    if (minY > 1185) continue;
    let sy = random(minY, 1190);
    let rw = random(5, 18);
    let rh = rw * random(0.55, 0.85);

    let topFace = [
      [sx - rw * 0.6, sy - rh * 0.3],
      [sx + rw * 0.2, sy - rh * 0.6],
      [sx + rw * 0.7, sy - rh * 0.1],
      [sx + rw * 0.1, sy + rh * 0.3]
    ];
    let sideFace = [
      [sx - rw * 0.6, sy - rh * 0.3],
      [sx + rw * 0.1, sy + rh * 0.3],
      [sx + rw * 0.7, sy - rh * 0.1],
      [sx + rw * 0.6, sy + rh * 0.55],
      [sx - rw * 0.1, sy + rh * 0.75],
      [sx - rw * 0.65, sy + rh * 0.2]
    ];
    let castShadow = [
      [sx - rw * 0.65, sy + rh * 0.2],
      [sx - rw * 0.1, sy + rh * 0.75],
      [sx + rw * 0.6, sy + rh * 0.55],
      [sx + rw * 0.85, sy + rh * 0.85],
      [sx - rw * 0.3, sy + rh * 1.1]
    ];

    resetBrush();
    brush.wash("#121721", 220);
    drawPoly(castShadow, 0.02);

    brush.wash("#384457", 250);
    drawPoly(sideFace, 0.02);

    brush.wash("#e3ebf5", 250);
    drawPoly(topFace, 0.02);
    brush.noWash();

    brush.set("rotring", "#121721", 0.42);
    drawPoly(sideFace, 0.02);
    drawPoly(topFace, 0.02);

    brush.set("cpencil", "#ffffff", 0.5);
    brush.line(topFace[0][0], topFace[0][1], topFace[1][0], topFace[1][1]);
  }
  resetBrush();

  // =========================================================================
  // 11. FINAL TENDRILS OF MIST CURLING UP OVER THE CHASM GULLIES
  // =========================================================================
  // Delicate wisps of valley fog licking over the low gullies at x~335 and x~855
  resetBrush();
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.4, 0.1);
  brush.fill("#edf4fc", 48);
  drawPoly(makeCloudBillow(335, 795, 95, 32, 10, 0.3), 0.45);
  drawPoly(makeCloudBillow(855, 805, 100, 34, 10, 0.3), 0.45);
  resetBrush();

  // Re-sharpen the central precipice lip right in front of the hiker's boots so it stays hyperreal and crisp
  for (let c = 5; c < 15; c++) {
    let pA = nodes[0][c];
    let pB = nodes[0][c + 1];
    brush.set("rotring", "#0d1118", 0.75);
    brush.line(pA.x, pA.y, pB.x, pB.y);
    brush.set("cpencil", "#ffffff", 0.65);
    brush.line(pA.x, pA.y + 1.5, pB.x, pB.y + 1.5);
  }
  resetBrush();

  noLoop();
}

