/* ============================================================================
 * SPATIAL DENSITY & UTILITY HELPERS
 * ============================================================================ */

// Returns 0..1 indicating proximity to the tight, nervous knot core vs margins
function knotFocus(x, y) {
  let dx = (x - 555) / 470;
  let dy = (y - 515) / 460;
  let d = sqrt(dx * dx + dy * dy);
  let n = noise(x * 0.005, y * 0.005) * 0.16 - 0.08;
  return constrain(1.18 - pow(max(0, d + n), 1.45), 0.04, 1.0);
}

// Evaluates point and tangent along a Catmull-Rom / piecewise cubic spline
function evalPath(pts, t) {
  let n = pts.length - 1;
  let ft = constrain(t, 0, 0.999999) * n;
  let idx = floor(ft);
  let lt = ft - idx;

  let p0 = pts[max(0, idx - 1)];
  let p1 = pts[idx];
  let p2 = pts[min(n, idx + 1)];
  let p3 = pts[min(n, idx + 2)];

  let t2 = lt * lt;
  let t3 = t2 * lt;

  let x =
    0.5 *
    (2 * p1[0] +
      (-p0[0] + p2[0]) * lt +
      (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 +
      (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
  let y =
    0.5 *
    (2 * p1[1] +
      (-p0[1] + p2[1]) * lt +
      (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 +
      (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);

  let dx =
    0.5 *
    (-p0[0] +
      p2[0] +
      (4 * p0[0] - 10 * p1[0] + 8 * p2[0] - 2 * p3[0]) * lt +
      (-3 * p0[0] + 9 * p1[0] - 9 * p2[0] + 3 * p3[0]) * t2);
  let dy =
    0.5 *
    (-p0[1] +
      p2[1] +
      (4 * p0[1] - 10 * p1[1] + 8 * p2[1] - 2 * p3[1]) * lt +
      (-3 * p0[1] + 9 * p1[1] - 9 * p2[1] + 3 * p3[1]) * t2);

  let len = sqrt(dx * dx + dy * dy) || 1;
  let tx = dx / len;
  let ty = dy / len;
  let nx = -ty;
  let ny = tx;

  let r1 = p1[2] !== undefined ? p1[2] : 48;
  let r2 = p2[2] !== undefined ? p2[2] : 48;
  let r = lerp(r1, r2, lt);

  return { x, y, tx, ty, nx, ny, r };
}

function approxPathLength(pts) {
  let total = 0;
  let prev = evalPath(pts, 0);
  for (let i = 1; i <= 40; i++) {
    let cur = evalPath(pts, i / 40);
    total += dist(prev.x, prev.y, cur.x, cur.y);
    prev = cur;
  }
  return total;
}

/* ============================================================================
 * 1. PLATE-TONE SMEAR & INTAGLIO PAPER SURFACE
 * ============================================================================ */

function renderPlateToneAndPaper() {
  brush.noStroke();

  // Uneven hand-wiped plate tone washes (faint grey-charcoal and Prussian/umber tint)
  const tonePatches = [
    { x: 580, y: 520, rx: 390, ry: 410, col: PAL.plateToneCool, op: 16, bleed: 0.45 },
    { x: 530, y: 490, rx: 280, ry: 290, col: PAL.plateToneWarm, op: 18, bleed: 0.4 },
    { x: 650, y: 620, rx: 260, ry: 310, col: PAL.plateToneDeep, op: 14, bleed: 0.5 },
    { x: 420, y: 690, rx: 240, ry: 200, col: PAL.plateToneCool, op: 12, bleed: 0.45 },
    { x: 620, y: 310, rx: 230, ry: 170, col: PAL.plateToneWarm, op: 13, bleed: 0.4 }
  ];

  for (let p of tonePatches) {
    brush.fill(p.col, p.op);
    brush.fillBleed(p.bleed, "out");
    brush.fillTexture(0.65, 0.35);
    brush.beginShape(0.5);
    let steps = 14;
    for (let i = 0; i < steps; i++) {
      let a = (i / steps) * 360;
      let radVar = 0.75 + 0.45 * noise(p.x * 0.01 + cos(a), p.y * 0.01 + sin(a));
      let vx = p.x + cos(a) * p.rx * radVar;
      let vy = p.y + sin(a) * p.ry * radVar;
      brush.vertex(vx, vy);
    }
    brush.endShape(true);
  }
  brush.noFill();

  // Tarlatan cloth wiping smears across the copperplate
  for (let i = 0; i < 190; i++) {
    let cx = random(95, 1105);
    let cy = random(95, 1105);
    let f = knotFocus(cx, cy);
    if (random() > f * 0.85 + 0.12) continue;

    let ang = -28 + random(-18, 18) + (noise(cx * 0.003, cy * 0.003) - 0.5) * 35;
    let len = random(60, 240);
    let col = random() < 0.55 ? PAL.plateToneCool : PAL.plateToneWarm;
    brush.set("plate_wipe", col, random(0.6, 1.5));
    let x1 = cx - cos(ang) * len * 0.5;
    let y1 = cy - sin(ang) * len * 0.5;
    let x2 = cx + cos(ang) * len * 0.5;
    let y2 = cy + sin(ang) * len * 0.5;
    brush.line(x1, y1, x2, y2);
  }

  // Faint charcoal grain & foul-biting specks in the plate
  for (let i = 0; i < 160; i++) {
    let x = random(75, 1125);
    let y = random(75, 1125);
    let f = knotFocus(x, y);
    let col = random() < 0.7 ? PAL.inkFaint : PAL.plateToneDeep;
    brush.set("2B", col, random(0.35, 0.85) * (0.4 + 0.6 * f));
    let a = -32 + random(-25, 25);
    let l = random(8, 45);
    brush.line(x, y, x + cos(a) * l, y + sin(a) * l);
  }

  // Subtle copperplate bevel mark near the outer margin (72 px inset)
  const m = 68;
  brush.set("drypoint_fine", PAL.plateToneCool, 0.55);
  for (let s = 0; s < 4; s++) {
    let segs = 22;
    for (let i = 0; i < segs; i++) {
      if (random() < 0.35) continue;
      let t1 = i / segs;
      let t2 = (i + random(0.4, 0.95)) / segs;
      let x1, y1, x2, y2;
      if (s === 0) {
        x1 = lerp(m, width - m, t1); y1 = m + random(-1.5, 1.5);
        x2 = lerp(m, width - m, t2); y2 = m + random(-1.5, 1.5);
      } else if (s === 1) {
        x1 = lerp(m, width - m, t1); y1 = height - m + random(-1.5, 1.5);
        x2 = lerp(m, width - m, t2); y2 = height - m + random(-1.5, 1.5);
      } else if (s === 2) {
        x1 = m + random(-1.5, 1.5); y1 = lerp(m, height - m, t1);
        x2 = m + random(-1.5, 1.5); y2 = lerp(m, height - m, t2);
      } else {
        x1 = width - m + random(-1.5, 1.5); y1 = lerp(m, height - m, t1);
        x2 = width - m + random(-1.5, 1.5); y2 = lerp(m, height - m, t2);
      }
      brush.line(x1, y1, x2, y2);
    }
  }
}

/* ============================================================================
 * 2. DOCK GROUND SCRATCHES
 * ============================================================================ */

function renderDockGroundScratches() {
  // Sparse horizontal and perspective drypoint scratches suggesting weathered dock timber/iron plate
  for (let i = 0; i < 220; i++) {
    let y = random(880, 1085);
    let spread = map(y, 880, 1085, 320, 490);
    let x = 590 + random(-spread, spread);
    let f = knotFocus(x, y);
    if (random() > f * 1.35) continue;

    let len = random(18, 95) * (0.4 + 0.6 * f);
    let ang = random(-6, 6) + (x - 590) * 0.008;
    let isDark = abs(x - 590) < 250 && y < 1015;
    let col = isDark
      ? (random() < 0.7 ? PAL.inkCharcoal : PAL.prussianDark)
      : PAL.inkFaint;

    brush.set(isDark ? "drypoint_needle" : "drypoint_fine", col, random(0.45, 0.95));
    brush.line(x - cos(ang) * len * 0.5, y - sin(ang) * len * 0.5, x + cos(ang) * len * 0.5, y + sin(ang) * len * 0.5);
  }
}

/* ============================================================================
 * 3. BOLLARD ANALYTICAL GEOMETRY & RENDERING
 * ============================================================================ */

// Returns the horizontal center and left/right radii of the cast-iron bollard at height y
function getBollardSlice(y) {
  let cx = 592;
  let rLeft = 142;
  let rRight = 142;
  let tiltRatio = 0.21; // elliptical perspective ratio

  if (y < 215) {
    // Top domed crown
    let t = constrain((y - 178) / (215 - 178), 0, 1);
    let r = 186 * sqrt(max(0.01, t));
    rLeft = r;
    rRight = r;
  } else if (y < 272) {
    // Heavy overhanging cap rim
    let bulge = sin(((y - 215) / (272 - 215)) * 180) * 10;
    rLeft = 186 + bulge;
    rRight = 186 + bulge;
  } else if (y < 298) {
    // Undercut neck beneath cap lip
    let t = (y - 272) / (298 - 272);
    let r = lerp(186, 136, sin(t * 90));
    rLeft = r;
    rRight = r;
  } else if (y < 815) {
    // Main waist + projecting mooring horns around y = 320..430
    let waistT = (y - 298) / (815 - 298);
    let baseR = 136 + sin(waistT * 180) * 12 + waistT * 10;
    rLeft = baseR;
    rRight = baseR;

    // Left horn (juts out and slightly upward around y = 370)
    if (y >= 305 && y <= 445) {
      let ht = (y - 305) / (445 - 305);
      let hornProfile = pow(sin(ht * 180), 1.6);
      rLeft += hornProfile * 98;
    }
    // Right horn (juts out around y = 375)
    if (y >= 310 && y <= 448) {
      let ht = (y - 310) / (448 - 310);
      let hornProfile = pow(sin(ht * 180), 1.6);
      rRight += hornProfile * 88;
    }
  } else {
    // Flared base bell (y = 815..965)
    let bt = constrain((y - 815) / (965 - 815), 0, 1);
    let flare = pow(bt, 1.75) * 96;
    rLeft = 146 + flare;
    rRight = 146 + flare;
  }

  return { cx, rLeft, rRight, tiltRatio };
}

function renderIronBollard() {
  // A. Cap Top Crown (elliptical concentric & radial drypoint scratches)
  let capCx = 592;
  let capCy = 220;
  let capRx = 186;
  let capRy = 39;

  for (let ring = 0; ring < 36; ring++) {
    let frac = ring / 36;
    let rx = capRx * frac;
    let ry = capRy * frac;
    let segs = floor(12 + frac * 42);

    for (let s = 0; s < segs; s++) {
      // Top-left of cap is brightly lit; right and rear edges carry more needle tone
      let a1 = (s / segs) * 360 + random(-4, 4);
      let a2 = ((s + random(0.45, 0.92)) / segs) * 360;
      let shade = map(cos(a1 - 35), -1, 1, 0.15, 0.92);
      if (random() > shade + 0.12) continue;

      let x1 = capCx + cos(a1) * rx;
      let y1 = capCy + sin(a1) * ry - (1 - frac) * 14;
      let x2 = capCx + cos(a2) * rx;
      let y2 = capCy + sin(a2) * ry - (1 - frac) * 14;

      let col = shade > 0.65 ? PAL.inkBlack : (random() < 0.25 ? PAL.rustDark : PAL.inkCharcoal);
      brush.set(shade > 0.7 ? "drypoint_needle" : "drypoint_fine", col, random(0.4, 0.95));
      brush.line(x1, y1, x2, y2);
    }
  }

  // B. Main Bollard Cylinder, Horns, Cap Rim & Flared Base
  // Cross-contour circumferential needle incisions from y = 216 down to y = 965
  for (let y = 216; y <= 965; y += 2.3) {
    let slice = getBollardSlice(y);
    let fCenter = knotFocus(slice.cx, y);

    // Determine vertical shadow modifiers (under cap lip, under horns, base flange)
    let underCapShadow = y >= 268 && y <= 315 ? map(y, 268, 315, 1.0, 0.0) : 0;
    let underHornShadow = y >= 395 && y <= 445 ? map(y, 395, 445, 0.75, 0.0) : 0;
    let rimDark = y >= 252 && y <= 274 ? 0.65 : 0;

    // Number of angular sub-segments across the front cylinder arc (angle 0..180 deg)
    let numArcSteps = 34;
    for (let i = 0; i < numArcSteps; i++) {
      let deg1 = map(i, 0, numArcSteps, 180, 0) + random(-2.5, 2.5);
      let deg2 = deg1 - random(4, 11);
      deg1 = constrain(deg1, 0, 180);
      deg2 = constrain(deg2, 0, 180);

      let c1 = cos(deg1);
      let s1 = sin(deg1);
      let c2 = cos(deg2);
      let s2 = sin(deg2);

      let rad1 = c1 < 0 ? slice.rLeft : slice.rRight;
      let rad2 = c2 < 0 ? slice.rLeft : slice.rRight;

      let x1 = slice.cx + c1 * rad1;
      let y1 = y + s1 * (rad1 * slice.tiltRatio);
      let x2 = slice.cx + c2 * rad2;
      let y2 = y + s2 * (rad2 * slice.tiltRatio);

      // Cylindrical normal nx = c1, nz = s1
      // Core shadow sits around c1 = 0.35..0.82 (right-hand side), reflected light near c1 > 0.86
      let lightDot = c1 * LIGHT.x + s1 * LIGHT.z;
      let coreShadow = exp(-pow((c1 - 0.58) / 0.28, 2)) * 0.55;
      let edgeDark = pow(abs(c1), 3.2) * 0.45;
      let darkness = constrain(
        map(lightDot, -0.7, 0.85, 0.88, 0.04) +
          coreShadow +
          edgeDark +
          underCapShadow * 0.75 +
          underHornShadow * (abs(c1) > 0.55 ? 0.65 : 0.1) +
          rimDark,
        0.02,
        1.0
      );

      let localFocus = knotFocus(x1, y1);
      // Dissolve strokes toward top/bottom margins while preserving crisp contour hints
      let drawProb = darkness * (0.35 + 0.65 * localFocus);
      if (abs(c1) > 0.92) drawProb += 0.32 * localFocus; // silhouette crispness

      if (random() < drawProb) {
        let col = PAL.inkCharcoal;
        if (darkness > 0.75) {
          col = random() < 0.72 ? PAL.inkBlack : (random() < 0.5 ? PAL.prussianDark : PAL.rustDark);
        } else if (darkness < 0.3) {
          col = PAL.inkSoft;
        }

        let br = darkness > 0.78 ? "drypoint_heavy" : (darkness > 0.35 ? "drypoint_needle" : "drypoint_fine");
        let w = map(darkness, 0, 1, 0.38, 1.08) * random(0.8, 1.2);
        brush.set(br, col, w);
        brush.line(x1, y1, x2, y2);

        // Add velvety drypoint burr where darks cluster (core shadow, under cap lip, under horns)
        if (darkness > 0.82 && random() < 0.38 * localFocus) {
          let burrCol = random() < 0.6 ? PAL.inkBlack : (random() < 0.6 ? PAL.prussianDark : PAL.rustDark);
          brush.set("drypoint_burr", burrCol, random(0.65, 1.35));
          brush.line(x1, y1 + random(-1.5, 1.5), x2, y2 + random(-1.5, 1.5));
        }
      }
    }
  }

  // C. Vertical & Steep Diagonal Cast-Iron Grain & Foundry Striations
  for (let i = 0; i < 950; i++) {
    let yStart = random(220, 955);
    let len = random(14, 58);
    let yEnd = min(968, yStart + len);
    let angDeg = random(0, 180);
    let c = cos(angDeg);
    let s = sin(angDeg);

    let sl1 = getBollardSlice(yStart);
    let sl2 = getBollardSlice(yEnd);
    let r1 = c < 0 ? sl1.rLeft : sl1.rRight;
    let r2 = c < 0 ? sl2.rLeft : sl2.rRight;

    let x1 = sl1.cx + c * r1;
    let y1 = yStart + s * r1 * sl1.tiltRatio;
    let x2 = sl2.cx + c * r2 + random(-2, 2);
    let y2 = yEnd + s * r2 * sl2.tiltRatio;

    let f = knotFocus(x1, y1);
    let shade = map(c, -0.8, 0.8, 0.18, 0.92) + (yStart < 310 ? 0.35 : 0);
    if (random() > shade * (0.3 + 0.7 * f)) continue;

    let col = shade > 0.7 ? PAL.inkBlack : (random() < 0.25 ? PAL.rustDark : PAL.inkCharcoal);
    brush.set(shade > 0.65 ? "drypoint_needle" : "drypoint_fine", col, random(0.35, 0.88));
    brush.line(x1, y1, x2, y2);
  }

  // D. Rust Pitting & Corrosion Craters (incised one stroke at a time with saturated oxide accents)
  const rustClusters = [];
  for (let k = 0; k < 58; k++) {
    let ry = random(235, 950);
    let rAng = random(12, 168);
    let sl = getBollardSlice(ry);
    let c = cos(rAng);
    let s = sin(rAng);
    let rad = c < 0 ? sl.rLeft : sl.rRight;
    let rx = sl.cx + c * rad;
    let realY = ry + s * rad * sl.tiltRatio;
    rustClusters.push({
      x: rx,
      y: realY,
      size: random(8, 32),
      intensity: random(0.5, 1.0),
      cVal: c
    });
  }

  for (let rc of rustClusters) {
    let f = knotFocus(rc.x, rc.y);
    let pitStrokes = floor(rc.size * 2.6 * (0.4 + 0.6 * f));

    // Tiny velvety oxide burr inside deep rust pit
    if (rc.intensity > 0.65 && f > 0.35) {
      let bCol = random() < 0.65 ? PAL.rustVivid : PAL.rustDark;
      brush.set("drypoint_burr", bCol, random(0.5, 1.1));
      brush.line(rc.x - rc.size * 0.3, rc.y, rc.x + rc.size * 0.3, rc.y + random(-3, 3));
    }

    for (let p = 0; p < pitStrokes; p++) {
      let a = random(360);
      let rDist = pow(random(), 0.7) * rc.size * 0.65;
      let px = rc.x + cos(a) * rDist;
      let py = rc.y + sin(a) * rDist * 0.75;

      // Short, jagged incised pit mark
      let strokeAng = random(-75, 75) + (p % 2 === 0 ? 90 : 0);
      let strokeLen = random(2.5, 9.5);
      let pCol;
      let rnd = random();
      if (rnd < 0.36) pCol = PAL.inkBlack;
      else if (rnd < 0.68) pCol = PAL.rustVivid;
      else if (rnd < 0.86) pCol = PAL.rustDark;
      else pCol = PAL.rustBright;

      brush.set("drypoint_needle", pCol, random(0.42, 0.95));
      brush.line(
        px - cos(strokeAng) * strokeLen * 0.5,
        py - sin(strokeAng) * strokeLen * 0.5,
        px + cos(strokeAng) * strokeLen * 0.5,
        py + sin(strokeAng) * strokeLen * 0.5
      );
    }

    // Vertical weeping rust streaks below the crater
    let drips = floor(random(2, 7) * f);
    for (let d = 0; d < drips; d++) {
      let dx = rc.x + random(-rc.size * 0.45, rc.size * 0.45);
      let dy1 = rc.y + random(0, rc.size * 0.3);
      let dy2 = dy1 + random(12, 48);
      let dCol = random() < 0.6 ? PAL.rustSienna : PAL.rustVivid;
      brush.set("drypoint_fine", dCol, random(0.35, 0.75));
      brush.line(dx, dy1, dx + random(-2, 2), dy2);
    }
  }

  // E. Heavy Base Anchor Bolts on the Flared Bollard Flange
  const boltAngles = [28, 68, 115, 152];
  let baseSl = getBollardSlice(955);
  for (let ba of boltAngles) {
    let bx = baseSl.cx + cos(ba) * (baseSl.rLeft * 0.92);
    let by = 955 + sin(ba) * (baseSl.rLeft * baseSl.tiltRatio * 0.92);
    let bf = knotFocus(bx, by);
    if (bf < 0.12) continue;

    // Incised hexagonal/square bolt head & rust collar
    for (let k = 0; k < 22; k++) {
      let a = random(360);
      let rad = random(4, 15);
      let x1 = bx + cos(a) * rad;
      let y1 = by + sin(a) * rad * 0.6 - random(0, 10);
      let l = random(5, 14);
      let ang = a + 90 + random(-20, 20);
      let col = random() < 0.65 ? PAL.inkBlack : PAL.rustDark;
      brush.set("drypoint_needle", col, random(0.45, 0.9));
      brush.line(x1, y1, x1 + cos(ang) * l, y1 + sin(ang) * l);
    }
  }
}

/* ============================================================================
 * 4. ROPE STRAND & FIBRE DRYPOINT ENGINE
 * ============================================================================ */

/**
 * Renders a 3-strand twisted hawser rope segment in hyperrealistic drypoint:
 * - Bulbous diagonal twisted lays (strands)
 * - Deep velvety burred valleys between strands
 * - Hundreds of individual helical incised fibres curving over each strand
 * - Salt-stiffened crust highlights & bristling broken whiskers
 */
function drawDrypointRopeSegment(pts, opts = {}) {
  let totalLen = approxPathLength(pts);
  let twistSign = opts.twistSign || 1;
  let shadeBias = opts.shadeBias || 0;
  let dissolveStart = opts.dissolveStart !== undefined ? opts.dissolveStart : 1.0;
  let dissolveEnd = opts.dissolveEnd !== undefined ? opts.dissolveEnd : 1.0;
  let frayFactor = opts.frayFactor !== undefined ? opts.frayFactor : 1.0;

  // Step size along the rope for each discrete twisted strand lobe
  let avgR = pts[0][2] || 48;
  let layStepDist = avgR * 0.68;
  let numLays = max(4, floor(totalLen / layStepDist));

  // 1. Underlying Rope Core Shadow & Edge Burr (only where knotFocus is strong)
  for (let i = 0; i <= numLays * 3; i++) {
    let t = i / (numLays * 3);
    let p = evalPath(pts, t);
    let f = knotFocus(p.x, p.y);
    if (random() > f * 0.9) continue;

    // Shadow side of the rope tube (facing away from top-left light)
    let nLight = p.nx * LIGHT.x + p.ny * LIGHT.y;
    let shadowSide = nLight < 0 ? 1 : -1;
    let sx = p.x + p.nx * p.r * 0.72 * shadowSide;
    let sy = p.y + p.ny * p.r * 0.72 * shadowSide;

    if (f > 0.45 && random() < 0.65) {
      let bCol = random() < 0.68 ? PAL.inkBlack : PAL.prussianDark;
      brush.set("drypoint_burr", bCol, random(0.65, 1.35) * f);
      brush.line(
        sx - p.tx * 8 + random(-2, 2),
        sy - p.ty * 8 + random(-2, 2),
        sx + p.tx * 8 + random(-2, 2),
        sy + p.ty * 8 + random(-2, 2)
      );
    }
  }

  // 2. Render each twisted strand lobe (lay) sequentially along the rope
  for (let k = 0; k < numLays; k++) {
    let tCenter = (k + 0.5) / numLays;
    let tSpan = 0.72 / numLays;
    let pCenter = evalPath(pts, tCenter);
    let focus = knotFocus(pCenter.x, pCenter.y);

    // Optional margin fade along ends of incoming/outgoing tails
    let endFade = 1.0;
    if (dissolveStart < 1.0 && tCenter < 0.25) {
      endFade = map(tCenter, 0, 0.25, dissolveStart, 1.0);
    }
    if (dissolveEnd < 1.0 && tCenter > 0.75) {
      endFade = map(tCenter, 0.75, 1.0, 1.0, dissolveEnd);
    }
    let density = constrain(focus * endFade, 0.05, 1.0);

    // Compute the S-curve spine of this diagonal twisted strand across the rope width
    // It goes from (tCenter - tSpan, -nx*R) through (tCenter, 0) to (tCenter + tSpan, +nx*R)
    let lobeHalfWidth = pCenter.r * 0.36; // radius of individual strand cylinder

    // A. Incise the deep inter-strand valley (crevice between strand k and k-1)
    let valleyLines = floor(map(density, 0.05, 1.0, 2, 14));
    for (let v = 0; v < valleyLines; v++) {
      let sFrac = random(-0.92, 0.92); // position across the rope width (-1 to +1)
      let tValley = constrain(tCenter - tSpan * 0.65 + sFrac * tSpan * 0.65 * twistSign, 0.001, 0.999);
      let pv = evalPath(pts, tValley);

      // Bulge profile across cylinder
      let across = sFrac * pv.r * 0.95;
      let jitter = random(-3.5, 3.5);
      let vx = pv.x + pv.nx * across + pv.tx * jitter;
      let vy = pv.y + pv.ny * across + pv.ty * jitter;

      // Valley tangent direction (diagonal across the rope)
      let vAngX = pv.tx * 0.58 * twistSign + pv.nx * 0.81;
      let vAngY = pv.ty * 0.58 * twistSign + pv.ny * 0.81;
      let segLen = random(7, 19) * (0.5 + 0.5 * density);

      let vCol = random() < 0.65 ? PAL.inkBlack : (random() < 0.55 ? PAL.prussianDark : PAL.rustDark);
      brush.set(density > 0.55 ? "drypoint_heavy" : "drypoint_needle", vCol, random(0.55, 1.15));
      brush.line(
        vx - vAngX * segLen * 0.5,
        vy - vAngY * segLen * 0.5,
        vx + vAngX * segLen * 0.5,
        vy + vAngY * segLen * 0.5
      );

      // Velvety drypoint burr trapped inside the strand crevice
      if (density > 0.48 && random() < 0.45 * density) {
        let burrCol = random() < 0.65 ? PAL.inkBlack : PAL.prussianVivid;
        brush.set("drypoint_burr", burrCol, random(0.6, 1.25) * density);
        brush.line(
          vx - vAngX * segLen * 0.4,
          vy - vAngY * segLen * 0.4,
          vx + vAngX * segLen * 0.4,
          vy + vAngY * segLen * 0.4
        );
      }
    }

    // B. Incise individual helical hemp/manila fibres across the rounded belly of strand k
    let numFibres = floor(map(density, 0.05, 1.0, 7, 56));
    for (let fIdx = 0; fIdx < numFibres; fIdx++) {
      // Position across rope width u in [-0.96, 0.96] and position across strand belly w in [-0.9, 0.9]
      let u = random(-0.96, 0.96);
      let w = random(-0.9, 0.9);

      let tSample = constrain(
        tCenter + u * tSpan * 0.62 * twistSign + w * (tSpan * 0.42),
        0.002,
        0.998
      );
      let ps = evalPath(pts, tSample);

      // 3D surface normal of this point on the twisted strand lobe
      // Combination of overall rope cylinder normal and local strand cylinder normal
      let ropeN_x = ps.nx * u;
      let ropeN_y = ps.ny * u;
      let ropeN_z = sqrt(max(0.05, 1 - u * u));

      let strandN_x = ps.tx * w * 0.7 - ps.nx * w * 0.4 * twistSign;
      let strandN_y = ps.ty * w * 0.7 - ps.ny * w * 0.4 * twistSign;
      let strandN_z = sqrt(max(0.05, 1 - w * w));

      let nx3 = ropeN_x * 0.65 + strandN_x * 0.35;
      let ny3 = ropeN_y * 0.65 + strandN_y * 0.35;
      let nz3 = ropeN_z * 0.65 + strandN_z * 0.35;

      let lDot = nx3 * LIGHT.x + ny3 * LIGHT.y + nz3 * LIGHT.z;
      let fibreDarkness = constrain(
        map(lDot, -0.65, 0.85, 0.96, 0.05) + shadeBias + abs(w) * 0.25 + (1 - ropeN_z) * 0.22,
        0.02,
        1.0
      );

      // Skip some strokes on brightly lit salt-encrusted strand crowns to let warm paper breathe
      if (fibreDarkness < 0.24 && random() < 0.72) continue;

      // Fibre center position (incorporating outer scallop bulge of the twisted lobe)
      let scallopBulge = (1 - w * w) * 5.5 * (abs(u) > 0.6 ? sign(u) : 0);
      let fx = ps.x + ps.nx * (u * ps.r * 0.94 + scallopBulge);
      let fy = ps.y + ps.ny * (u * ps.r * 0.94 + scallopBulge);

      // Fibre direction: counter-twisted relative to the strand lay so fibres lock together
      let fibDirX = ps.tx * 0.88 - ps.nx * 0.46 * twistSign + (noise(fx * 0.03, fy * 0.03) - 0.5) * 0.3;
      let fibDirY = ps.ty * 0.88 - ps.ny * 0.46 * twistSign + (noise(fy * 0.03, fx * 0.03) - 0.5) * 0.3;
      let fLen = random(9, 24) * (0.55 + 0.45 * (1 - abs(w)));

      // Slight 3-point curve following the convex roundness of the strand
      let arch = (1 - w * w) * 3.2;
      let pStart = [
        fx - fibDirX * fLen * 0.5,
        fy - fibDirY * fLen * 0.5,
        random(0.2, 0.6)
      ];
      let pMid = [
        fx + ps.nx * u * arch + random(-1.2, 1.2),
        fy + ps.ny * u * arch + random(-1.2, 1.2),
        random(0.7, 1.1)
      ];
      let pEnd = [
        fx + fibDirX * fLen * 0.5,
        fy + fibDirY * fLen * 0.5,
        random(0.15, 0.5)
      ];

      // Choose drypoint ink color
      let fCol = PAL.inkCharcoal;
      if (fibreDarkness > 0.72) {
        let r = random();
        if (r < 0.64) fCol = PAL.inkBlack;
        else if (r < 0.86) fCol = PAL.prussianDark;
        else fCol = PAL.rustDark; // iron-stained contact fibres
      } else if (fibreDarkness < 0.35) {
        fCol = random() < 0.7 ? PAL.inkSoft : PAL.plateToneWarm;
      } else if (random() < 0.12) {
        fCol = PAL.rustSienna;
      }

      let fBrush =
        fibreDarkness > 0.78 && density > 0.5
          ? "drypoint_heavy"
          : fibreDarkness > 0.35
          ? "drypoint_needle"
          : "drypoint_fine";
      let fWeight = map(fibreDarkness, 0, 1, 0.36, 1.02) * random(0.82, 1.18);

      brush.set(fBrush, fCol, fWeight);
      brush.spline([pStart, pMid, pEnd], 0.45);
    }

    // C. Salt-stiffened dry scraped highlights on the upper-left lit crest of each strand lobe
    if (density > 0.35 && shadeBias < 0.3) {
      let saltStrokes = floor(random(2, 6) * density);
      for (let s = 0; s < saltStrokes; s++) {
        let uLit = random(-0.65, 0.15);
        let ps = evalPath(pts, constrain(tCenter + uLit * tSpan * 0.4, 0.01, 0.99));
        let sx = ps.x + ps.nx * uLit * ps.r * 0.82;
        let sy = ps.y + ps.ny * uLit * ps.r * 0.82;
        let sLen = random(6, 15);
        brush.set("salt_scrape", PAL.saltLight, random(0.5, 0.95));
        brush.line(
          sx - ps.tx * sLen * 0.5,
          sy - ps.ty * sLen * 0.5,
          sx + ps.tx * sLen * 0.5,
          sy + ps.ty * sLen * 0.5
        );
      }
    }

    // D. Scalloped Outer Contour & Bristling Salt-Stiffened Whiskers along both edges
    for (let side of [-1, 1]) {
      let edgeSamples = floor(map(density, 0.05, 1.0, 2, 7));
      for (let e = 0; e < edgeSamples; e++) {
        let wEdge = map(e, 0, edgeSamples, -0.75, 0.75);
        let tEdge = constrain(tCenter + side * tSpan * 0.52 * twistSign + wEdge * tSpan * 0.38, 0.005, 0.995);
        let pe = evalPath(pts, tEdge);

        // Outer scallop lobe bulge
        let lobeOut = (1 - wEdge * wEdge) * 6.5;
        let ex = pe.x + pe.nx * side * (pe.r * 0.95 + lobeOut);
        let ey = pe.y + pe.ny * side * (pe.r * 0.95 + lobeOut);

        let eLen = random(8, 18);
        let eCol = side > 0 ? PAL.inkBlack : PAL.inkCharcoal;
        brush.set(density > 0.4 ? "drypoint_needle" : "drypoint_fine", eCol, random(0.45, 0.95));
        brush.line(
          ex - pe.tx * eLen * 0.5,
          ey - pe.ty * eLen * 0.5,
          ex + pe.tx * eLen * 0.5,
          ey + pe.ty * eLen * 0.5
        );

        // Stiff, salt-crusted frayed fibre springing out from the rope edge
        if (random() < 0.48 * frayFactor * (0.4 + 0.6 * density)) {
          let whiskerLen = random(12, 44) * frayFactor;
          let outAng = atan2(pe.ny * side + pe.ty * random(-0.9, 0.9), pe.nx * side + pe.tx * random(-0.9, 0.9));
          let kinkAng = outAng + random(-28, 28);
          let wx1 = ex + cos(outAng) * whiskerLen * 0.55;
          let wy1 = ey + sin(outAng) * whiskerLen * 0.55;
          let wx2 = wx1 + cos(kinkAng) * whiskerLen * 0.45;
          let wy2 = wy1 + sin(kinkAng) * whiskerLen * 0.45;

          let wCol = random() < 0.75 ? PAL.inkBlack : PAL.inkSoft;
          brush.set(random() < 0.6 ? "drypoint_needle" : "drypoint_fine", wCol, random(0.32, 0.72));
          brush.spline(
            [
              [ex, ey, 0.95],
              [wx1, wy1, 0.55],
              [wx2, wy2, 0.08]
            ],
            0.35
          );
        }
      }
    }
  }
}

