// Pre-incises dense drypoint cast shadows and velvety burr on the iron bollard beneath the front rope wraps
function renderRopeOnBollardShadows() {
  const shadowPaths = [
    // Shadow beneath incoming standing part
    [
      [755, 765, 50],
      [620, 695, 50],
      [485, 628, 48],
      [425, 575, 46]
    ],
    // Shadow beneath Pass B (upward-left diagonal wrap)
    [
      [755, 535, 50],
      [625, 498, 52],
      [485, 452, 50],
      [375, 405, 46]
    ],
    // Shadow beneath Pass C (crossing bight from upper-right to lower-left)
    [
      [748, 405, 48],
      [645, 458, 52],
      [535, 530, 52],
      [455, 588, 50]
    ]
  ];

  for (let sp of shadowPaths) {
    let steps = 85;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let p = evalPath(sp, t);
      let f = knotFocus(p.x, p.y);
      if (random() > f * 0.95) continue;

      // Cast shadow falls downward and slightly right (opposite top-left light)
      let sx = p.x + 12 + random(-14, 18);
      let sy = p.y + p.r * 0.78 + random(2, 26);

      // Only draw shadow if it lands on the bollard body or underlying rope
      let sl = getBollardSlice(sy);
      if (sx > sl.cx - sl.rLeft - 25 && sx < sl.cx + sl.rRight + 25) {
        let len = random(14, 34);
        let ang = 52 + random(-18, 18);
        let col = random() < 0.72 ? PAL.inkBlack : (random() < 0.5 ? PAL.prussianDark : PAL.rustDark);

        brush.set("drypoint_heavy", col, random(0.65, 1.2));
        brush.line(
          sx - cos(ang) * len * 0.5,
          sy - sin(ang) * len * 0.5,
          sx + cos(ang) * len * 0.5,
          sy + sin(ang) * len * 0.5
        );

        if (random() < 0.55 * f) {
          brush.set("drypoint_burr", col, random(0.8, 1.55) * f);
          brush.line(sx - 8, sy, sx + 8, sy + random(-4, 4));
        }
      }
    }
  }
}

// Helper to lay down a dark contact shadow / occlusion crease right before an overlapping rope pass
function drawRopeOverlapShadow(pts, tMin, tMax) {
  let steps = 42;
  for (let i = 0; i <= steps; i++) {
    let t = lerp(tMin, tMax, i / steps);
    let p = evalPath(pts, t);
    let f = knotFocus(p.x, p.y);

    for (let side of [-1, 1]) {
      let ox = p.x + p.nx * side * (p.r * 0.92) + 5;
      let oy = p.y + p.ny * side * (p.r * 0.92) + 8;
      let col = random() < 0.75 ? PAL.inkBlack : PAL.prussianDark;

      brush.set("drypoint_burr", col, random(0.9, 1.65) * f);
      brush.line(ox - p.tx * 10, oy - p.ty * 10, ox + p.tx * 10, oy + p.ty * 10);

      for (let h = 0; h < 3; h++) {
        let hx = ox + random(-8, 8);
        let hy = oy + random(-8, 8);
        let hAng = random(25, 75);
        brush.set("drypoint_heavy", PAL.inkBlack, random(0.6, 1.1));
        brush.line(hx - cos(hAng) * 9, hy - sin(hAng) * 9, hx + cos(hAng) * 9, hy + sin(hAng) * 9);
      }
    }
  }
}

