function renderWhippedFrayedCrown(wx, wy, dirDeg) {
  let tx = cos(dirDeg);
  let ty = sin(dirDeg);
  let nx = -ty;
  let ny = tx;

  // 1. Tight marline cord whipping binding (14 closely packed incised wraps choking the rope end)
  let whipRadius = 38;
  for (let w = 0; w < 15; w++) {
    let axial = w * 3.1;
    let cx = wx + tx * axial;
    let cy = wy + ty * axial;

    // Draw each whipping cord turn with cross-contour curve and heavy burr
    for (let s = 0; s < 14; s++) {
      let u1 = map(s, 0, 14, -1, 1);
      let u2 = map(s + 1, 0, 14, -1, 1);
      let arch1 = sqrt(max(0, 1 - u1 * u1)) * 7;
      let arch2 = sqrt(max(0, 1 - u2 * u2)) * 7;

      let x1 = cx + nx * u1 * whipRadius + tx * arch1;
      let y1 = cy + ny * u1 * whipRadius + ty * arch1;
      let x2 = cx + nx * u2 * whipRadius + tx * arch2;
      let y2 = cy + ny * u2 * whipRadius + ty * arch2;

      let shade = map(u1, -1, 1, 0.25, 0.95);
      let col = shade > 0.6 ? PAL.inkBlack : (random() < 0.35 ? PAL.rustDark : PAL.inkCharcoal);
      brush.set(shade > 0.65 ? "drypoint_heavy" : "drypoint_needle", col, random(0.55, 1.1));
      brush.line(x1, y1, x2, y2);

      if (shade > 0.72 && random() < 0.45) {
        brush.set("drypoint_burr", PAL.inkBlack, random(0.65, 1.2));
        brush.line(x1, y1, x2, y2);
      }
    }
  }

  // 2. Three untwisted sub-strands splaying out from the whipped collar and dissolving into stiff fibres
  let crownStartX = wx + tx * 46;
  let crownStartY = wy + ty * 46;
  let splayAngles = [dirDeg - 26, dirDeg + 2, dirDeg + 28];

  // Deep burr shadow right inside the mouth of the frayed crown
  for (let i = 0; i < 24; i++) {
    let bx = crownStartX + random(-28, 28);
    let by = crownStartY + random(-22, 22);
    let bCol = random() < 0.7 ? PAL.inkBlack : PAL.prussianDark;
    brush.set("drypoint_burr", bCol, random(0.8, 1.5));
    brush.line(bx, by, bx + tx * random(12, 28), by + ty * random(12, 28));
  }

  for (let sIdx = 0; sIdx < 3; sIdx++) {
    let baseAng = splayAngles[sIdx];
    let offsetSpread = (sIdx - 1) * 24;
    let sx0 = crownStartX + nx * offsetSpread;
    let sy0 = crownStartY + ny * offsetSpread;

    // Hundreds of stiff, salt-encrusted sisal/manila fibres fanning and kinking outward
    let fibreCount = 135;
    for (let f = 0; f < fibreCount; f++) {
      let progress = f / fibreCount;
      let startJitter = random(-16, 16);
      let fx0 = sx0 + nx * startJitter + tx * random(-6, 18);
      let fy0 = sy0 + ny * startJitter + ty * random(-6, 18);

      let ang1 = baseAng + random(-24, 24);
      let ang2 = ang1 + random(-32, 32);
      let ang3 = ang2 + random(-38, 38);

      let totalL = random(35, 195);
      let l1 = totalL * 0.35;
      let l2 = totalL * 0.35;
      let l3 = totalL * 0.3;

      let fx1 = fx0 + cos(ang1) * l1;
      let fy1 = fy0 + sin(ang1) * l1;
      let fx2 = fx1 + cos(ang2) * l2;
      let fy2 = fy1 + sin(ang2) * l2;
      let fx3 = fx2 + cos(ang3) * l3;
      let fy3 = fy2 + sin(ang3) * l3;

      let fFocus = knotFocus(fx1, fy1);
      if (random() > fFocus * 1.35 && f > 45) continue;

      let isCore = abs(startJitter) < 9 && totalL < 115;
      let col = PAL.inkCharcoal;
      if (isCore) {
        col = random() < 0.7 ? PAL.inkBlack : (random() < 0.5 ? PAL.prussianDark : PAL.rustDark);
      } else if (totalL > 140) {
        col = random() < 0.6 ? PAL.inkSoft : PAL.inkFaint;
      } else if (random() < 0.14) {
        col = PAL.rustVivid;
      }

      let br = isCore ? "drypoint_heavy" : (totalL < 130 ? "drypoint_needle" : "drypoint_fine");
      let w = isCore ? random(0.55, 1.05) : random(0.28, 0.68);

      brush.set(br, col, w);
      brush.spline(
        [
          [fx0, fy0, 0.95],
          [fx1, fy1, 0.75],
          [fx2, fy2, 0.4],
          [fx3, fy3, 0.05]
        ],
        0.35
      );
    }
  }
}

/* ============================================================================
 * 6. FINAL VELVETY BURR BLOOMS & NERVOUS MARGIN SCRATCHES
 * ============================================================================ */

function renderFinalBurrAndMarginScratches() {
  // 1. Deep, velvety drypoint burr blooms in the tightest high-tension crevices of the knot
  const velvetZones = [
    { x: 545, y: 465, r: 38 }, // Central knot throat tuck
    { x: 488, y: 528, r: 36 }, // Lower hitch lock
    { x: 605, y: 482, r: 34 }, // Main X-crossing shadow
    { x: 412, y: 405, r: 30 }, // Left horn hook crease
    { x: 685, y: 438, r: 30 }, // Right upper wrap shadow
    { x: 595, y: 282, r: 32 }, // Deep undercut beneath bollard cap lip
    { x: 645, y: 695, r: 28 }  // Lower standing part shadow pocket
  ];

  for (let vz of velvetZones) {
    // Soft spray burr bloom + dense crisscrossing drypoint burr & needle marks
    for (let i = 0; i < 16; i++) {
      let a = random(360);
      let d = random(0, vz.r * 0.75);
      let bx = vz.x + cos(a) * d;
      let by = vz.y + sin(a) * d;
      let sAng = random(360);
      let sLen = random(10, 26);

      let bCol = random() < 0.62 ? PAL.inkBlack : (random() < 0.65 ? PAL.prussianDark : PAL.rustDark);
      brush.set("burr_velvet", bCol, random(0.7, 1.35));
      brush.line(
        bx - cos(sAng) * sLen * 0.5,
        by - sin(sAng) * sLen * 0.5,
        bx + cos(sAng) * sLen * 0.5,
        by + sin(sAng) * sLen * 0.5
      );

      brush.set("drypoint_burr", PAL.inkBlack, random(0.75, 1.4));
      brush.line(
        bx - cos(sAng + 25) * sLen * 0.45,
        by - sin(sAng + 25) * sLen * 0.45,
        bx + cos(sAng + 25) * sLen * 0.45,
        by + sin(sAng + 25) * sLen * 0.45
      );
    }

    // Nervous, tight needle hatching inside the knot crevice
    for (let j = 0; j < 28; j++) {
      let a = random(360);
      let d = random(0, vz.r);
      let nx = vz.x + cos(a) * d;
      let ny = vz.y + sin(a) * d;
      let lAng = random(-70, 70) + (j % 2 === 0 ? 45 : -35);
      let lLen = random(8, 22);

      let nCol = random() < 0.75 ? PAL.inkBlack : (random() < 0.5 ? PAL.prussianVivid : PAL.rustVivid);
      brush.set("drypoint_heavy", nCol, random(0.55, 1.05));
      brush.line(
        nx - cos(lAng) * lLen * 0.5,
        ny - sin(lAng) * lLen * 0.5,
        nx + cos(lAng) * lLen * 0.5,
        ny + sin(lAng) * lLen * 0.5
      );
    }
  }

  // 2. Stray Broken Hemp Fibres, Salt Crystals & Nervous Drypoint Scratches Dissolving to the Margins
  for (let i = 0; i < 420; i++) {
    let ang = random(360);
    // Distribute from the knot perimeter out toward the plate margins
    let rad = random(180, 540);
    let sx = 560 + cos(ang) * rad;
    let sy = 525 + sin(ang) * rad;

    if (sx < 75 || sx > 1125 || sy < 75 || sy > 1125) continue;

    let f = knotFocus(sx, sy);
    // Sparse peripheral scratches at the margins, tighter nervous ticks near the rope & bollard
    if (random() > f * 0.75 + 0.14) continue;

    let scratchLen = random(10, 52) * (0.45 + 0.55 * (1 - f));
    let scratchAng = ang + 90 + random(-55, 55);
    let kink = scratchAng + random(-22, 22);

    let x1 = sx + cos(scratchAng) * scratchLen * 0.5;
    let y1 = sy + sin(scratchAng) * scratchLen * 0.5;
    let x2 = x1 + cos(kink) * scratchLen * 0.5;
    let y2 = y1 + sin(kink) * scratchLen * 0.5;

    let col = f > 0.45
      ? (random() < 0.7 ? PAL.inkCharcoal : (random() < 0.5 ? PAL.rustSienna : PAL.prussianDark))
      : (random() < 0.65 ? PAL.inkFaint : PAL.plateToneCool);

    brush.set(f > 0.5 ? "drypoint_needle" : "drypoint_fine", col, random(0.25, 0.72));
    brush.spline(
      [
        [sx, sy, random(0.2, 0.8)],
        [x1, y1, random(0.5, 0.9)],
        [x2, y2, 0.05]
      ],
      0.3
    );
  }
}

