// ============================================================================
// GEOMETRY & SHAPE HELPERS
// ============================================================================

function fillPoly(pts, col, alphaVal = 255, bleedVal = 0.04, texVal = 0.25, borderVal = 0.15) {
  brush.noStroke();
  brush. noWash();
  brush.fill(col, alphaVal);
  brush.fillBleed(bleedVal, "out");
  brush.fillTexture(texVal, borderVal);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function washPoly(pts, col, alphaVal = 255) {
  brush.noStroke();
  brush.noFill();
  brush.wash(col, alphaVal);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function strokePoly(pts, closeShape = true, curvature = 0) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closeShape);
}

// Generates scalloped oval boundary points
function getScallopOvalPoint(angleDeg, rx, ry, numLobes, lobeAmp) {
  let rad = angleDeg;
  let lobePhase = abs(sin(angleDeg * (numLobes / 2)));
  let rOffset = pow(lobePhase, 0.75) * lobeAmp;
  let x = (rx + rOffset) * cos(rad);
  let y = (ry + rOffset) * sin(rad);
  return [x, y];
}

// ============================================================================
// 1. ROSE-MADDER GROUND
// ============================================================================

function drawRoseMadderGround() {
  brush.noField();

  // Layered watercolor & opaque washes for deep rose-madder board
  washPoly([[0, 0], [1200, 0], [1200, 1200], [0, 1200]], PAL.groundBase, 255);

  // Subtle directional vignette (brighter top-left, deeper bottom-right)
  let steps = 7;
  for (let i = 0; i < steps; i++) {
    let r = map(i, 0, steps - 1, 950, 260);
    let pts = [];
    for (let a = 0; a < 360; a += 15) {
      pts.push([420 + cos(a) * r, 380 + sin(a) * r]);
    }
    fillPoly(pts, PAL.groundWarm, 18, 0.25, 0.4, 0.1);
  }

  // Deep umber-madder corners
  const corners = [
    [[0, 0], [450, 0], [0, 450]],
    [[1200, 0], [1200, 520], [680, 0]],
    [[0, 1200], [520, 1200], [0, 680]],
    [[1200, 1200], [550, 1200], [1200, 550]]
  ];
  for (let c of corners) {
    fillPoly(c, PAL.groundDeep, 65, 0.35, 0.5, 0.2);
  }

  // Fine woven linen/wood grain across the rose-madder mounting board
  brush.set("2H", PAL.groundDeep, 0.4);
  for (let y = 8; y < 1200; y += 9) {
    let yJit = y + random(-2, 2);
    brush.set("2H", random() < 0.5 ? PAL.groundDeep : PAL.groundUmber, random(0.25, 0.5));
    brush.line(0, yJit, 1200, yJit + random(-4, 4));
  }

  // Subtle vertical cross-grain & aged patina speckles
  for (let x = 12; x < 1200; x += 16) {
    if (random() < 0.65) {
      brush.set("cpencil", PAL.groundMid, random(0.2, 0.4));
      brush.line(x + random(-3, 3), 0, x + random(-3, 3), 1200);
    }
  }

  // Atmospheric spray mottling
  for (let i = 0; i < 90; i++) {
    let sx = random(60, 1140);
    let sy = random(60, 1140);
    brush.set("spray", i % 2 === 0 ? PAL.groundDeep : PAL.groundWarm, random(0.6, 1.4));
    brush.circle(sx, sy, random(18, 55), 0.3);
  }
}

// ============================================================================
// 2 & 4. FADED SILK RIBBON
// ============================================================================

function drawSilkRibbonStrip(centerPts, halfWidth, shadowOffset, isUnderLace) {
  let leftEdge = [];
  let rightEdge = [];
  let shadowPoly = [];

  for (let i = 0; i < centerPts.length; i++) {
    let p = centerPts[i];
    let pNext = centerPts[min(i + 1, centerPts.length - 1)];
    let pPrev = centerPts[max(i - 1, 0)];
    let dx = pNext[0] - pPrev[0];
    let dy = pNext[1] - pPrev[1];
    let len = sqrt(dx * dx + dy * dy) || 1;
    let nx = -dy / len;
    let ny = dx / len;

    // Slight undulating silk width
    let w = halfWidth * (0.9 + 0.18 * sin(i * 28));
    leftEdge.push([p[0] + nx * w, p[1] + ny * w]);
    rightEdge.push([p[0] - nx * w, p[1] - ny * w]);
  }

  // Notch the tail end (classic V-cut ribbon tail at the last point)
  let lastIdx = centerPts.length - 1;
  let prevIdx = max(0, lastIdx - 1);
  let tdx = centerPts[lastIdx][0] - centerPts[prevIdx][0];
  let tdy = centerPts[lastIdx][1] - centerPts[prevIdx][1];
  let tlen = sqrt(tdx * tdx + tdy * tdy) || 1;
  let notchPt = [
    centerPts[lastIdx][0] - (tdx / tlen) * (halfWidth * 1.15),
    centerPts[lastIdx][1] - (tdy / tlen) * (halfWidth * 1.15)
  ];

  let polyPts = [...leftEdge, notchPt, ...rightEdge.slice().reverse()];

  // Cast shadow on ground/lace
  for (let pt of polyPts) {
    shadowPoly.push([pt[0] + shadowOffset[0], pt[1] + shadowOffset[1]]);
  }
  fillPoly(shadowPoly, isUnderLace ? PAL.groundShadow : PAL.laceShadow, 130, 0.18, 0.3, 0.1);

  // Soft penumbra shadow
  brush.set("velvetShadow", isUnderLace ? PAL.groundShadow : PAL.laceShadow, 1.1);
  strokePoly(shadowPoly, true, 0.2);

  // Base silk wash
  washPoly(polyPts, PAL.ribBase, 245);
  fillPoly(polyPts, PAL.ribWarm, 55, 0.06, 0.25, 0.15);

  // Silk warp striations along length
  let steps = 11;
  for (let s = 0; s <= steps; s++) {
    let t = s / steps;
    let strand = [];
    for (let i = 0; i < leftEdge.length; i++) {
      let lx = lerp(leftEdge[i][0], rightEdge[i][0], t);
      let ly = lerp(leftEdge[i][1], rightEdge[i][1], t);
      strand.push([lx, ly]);
    }
    let col = (s === 0 || s === steps) ? PAL.ribHighlight : (s % 3 === 0 ? PAL.ribLight : PAL.ribMid);
    brush.set("filigree", col, (s === 0 || s === steps) ? 0.55 : 0.32);
    brush.spline(strand, 0.35);
  }

  // Transverse silk sheen & fold highlights (watered taffeta/moire shimmer)
  for (let i = 1; i < leftEdge.length - 1; i++) {
    let wave = sin(i * 42);
    let col = wave > 0.2 ? PAL.ribHighlight : (wave < -0.2 ? PAL.ribDark : PAL.ribWarm);
    let subSteps = 6;
    for (let k = 0; k < subSteps; k++) {
      let frac = k / subSteps;
      let iNext = i + 1;
      let x1 = lerp(leftEdge[i][0], leftEdge[iNext][0], frac);
      let y1 = lerp(leftEdge[i][1], leftEdge[iNext][1], frac);
      let x2 = lerp(rightEdge[i][0], rightEdge[iNext][0], frac);
      let y2 = lerp(rightEdge[i][1], rightEdge[iNext][1], frac);
      brush.set("2H", col, 0.35);
      brush.line(x1, y1, x2, y2);
    }
  }

  // Picot / selvedge edge stitch & thickness highlight
  brush.set("rotring", PAL.ribHighlight, 0.45);
  brush.spline(leftEdge, 0.3);
  brush.set("rotring", PAL.ribDark, 0.45);
  brush.spline(rightEdge, 0.3);

  // Tiny picot loops along ribbon edge
  brush.set("filigree", PAL.ribHighlight, 0.35);
  for (let i = 0; i < leftEdge.length - 1; i++) {
    for (let f = 0; f < 1; f += 0.25) {
      let lx = lerp(leftEdge[i][0], leftEdge[i + 1][0], f);
      let ly = lerp(leftEdge[i][1], leftEdge[i + 1][1], f);
      brush.circle(lx, ly, 1.8, 0.1);
    }
  }
}

