// ============================================================================
// 3. VICTORIAN PIERCED PAPER LACE DOILY
// ============================================================================

function drawPunchedHole(x, y, r, groundCol, thicknessHighlightCol, shadowCol, hasGiltRim = false) {
  // 1. Rose-madder ground visible through the punched hole
  let pts = [];
  let segs = r > 5 ? 14 : 8;
  for (let i = 0; i < segs; i++) {
    let a = (i / segs) * 360;
    pts.push([x + cos(a) * r, y + sin(a) * r]);
  }
  washPoly(pts, groundCol, 250);

  // 2. Inner cast shadow on top-left of the hole (cast by the paper thickness onto the ground)
  brush.set("rotring", shadowCol, r > 4 ? 0.65 : 0.45);
  brush.arc(x, y, r * 0.88, 185, 345);

  // 3. Bright paper-thickness wall on the bottom-right inside of the hole (catching top-left light)
  brush.set("filigree", thicknessHighlightCol, r > 4 ? 0.6 : 0.42);
  brush.arc(x, y, r, 5, 165);

  // 4. Optional embossed collar or gilt glint around hole
  if (hasGiltRim) {
    brush.set("rotring", PAL.giltBright, 0.35);
    brush.arc(x, y, r + 1.3, 195, 335);
  } else {
    brush.set("filigree", PAL.lacePure, 0.32);
    brush.arc(x, y, r + 1.0, 190, 340);
  }
}

function drawPiercedPetalHole(cx, cy, angleDeg, len, wid, groundCol) {
  let c = cos(angleDeg);
  let s = sin(angleDeg);
  let nx = -s;
  let ny = c;

  // Teardrop / pointed oval polygon in local coords
  let localPts = [
    [-len * 0.5, 0],
    [-len * 0.15, -wid * 0.48],
    [len * 0.25, -wid * 0.42],
    [len * 0.5, 0],
    [len * 0.25, wid * 0.42],
    [-len * 0.15, wid * 0.48]
  ];

  let worldPts = [];
  let innerHighlightPts = [];
  let innerShadowPts = [];

  for (let i = 0; i < localPts.length; i++) {
    let lx = localPts[i][0];
    let ly = localPts[i][1];
    let wx = cx + lx * c + ly * nx;
    let wy = cy + lx * s + ly * ny;
    worldPts.push([wx, wy]);
  }

  // Fill with ground color
  washPoly(worldPts, groundCol, 250);

  // Paper thickness highlight on bottom-right edge, shadow on top-left
  for (let i = 0; i < worldPts.length; i++) {
    let p1 = worldPts[i];
    let p2 = worldPts[(i + 1) % worldPts.length];
    let mx = (p1[0] + p2[0]) * 0.5 - cx;
    let my = (p1[1] + p2[1]) * 0.5 - cy;
    let dotLight = mx * LIGHT_DX + my * LIGHT_DY;

    if (dotLight > 0) {
      // Bottom-right wall faces the light -> bright white paper thickness
      brush.set("filigree", PAL.lacePure, 0.52);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    } else {
      // Top-left edge casts a crisp dark shadow into the hole
      brush.set("rotring", PAL.groundShadow, 0.55);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }
}

function drawEmbossedRosette(cx, cy, r, numPetals, withGilt = false) {
  // Subtle recessed ring shadow around the rosette
  brush.set("2H", PAL.laceGreyMid, 0.4);
  brush.circle(cx + 1.2, cy + 1.5, r * 1.05, 0.15);

  for (let i = 0; i < numPetals; i++) {
    let a = (i / numPetals) * 360;
    let px = cx + cos(a) * (r * 0.56);
    let py = cy + sin(a) * (r * 0.56);
    let pr = r * 0.36;

    // Shadow side of embossed petal dome (bottom-right)
    brush.set("2H", PAL.laceGreyMid, 0.45);
    brush.arc(px + 1.0, py + 1.2, pr, 15, 165);
    brush.set("cpencil", PAL.laceGreyLight, 0.5);
    brush.arc(px + 0.6, py + 0.8, pr * 0.78, 10, 170);

    // Highlight dome of embossed petal (top-left)
    brush.set("filigree", PAL.lacePure, 0.68);
    brush.arc(px - 0.6, py - 0.8, pr * 0.9, 195, 345);
    brush.set("filigree", PAL.lacePure, 0.55);
    brush.arc(px - 0.8, py - 1.0, pr * 0.6, 205, 335);

    if (withGilt && i % 2 === 0) {
      brush.set("rotring", PAL.giltBright, 0.32);
      brush.arc(px - 0.5, py - 0.5, pr * 0.75, 210, 320);
    }

    // Tiny pierced pin-hole between petals
    let ha = a + 180 / numPetals;
    let hx = cx + cos(ha) * (r * 0.88);
    let hy = cy + sin(ha) * (r * 0.88);
    drawPunchedHole(hx, hy, r * 0.11, PAL.groundBase, PAL.lacePure, PAL.groundShadow, false);
  }

  // Central embossed boss with pierced eyelet center
  brush.set("2H", PAL.laceGreyDark, 0.42);
  brush.arc(cx + 0.8, cy + 1.0, r * 0.32, 10, 175);
  brush.set("filigree", PAL.lacePure, 0.65);
  brush.arc(cx - 0.6, cy - 0.8, r * 0.32, 190, 350);

  drawPunchedHole(cx, cy, r * 0.16, PAL.groundDeep, PAL.lacePure, PAL.groundShadow, withGilt);
}

function drawVictorianPaperLace(rx, ry) {
  const numLobes = 36;
  const lobeAmp = 24;

  // -------------------------------------------------------------------------
  // A. TROMPE-L'OEIL DROP SHADOW OF THE SCALLOPED LACE ON ROSE-MADDER GROUND
  // -------------------------------------------------------------------------
  let outerPts = [];
  let shadowPtsFar = [];
  let shadowPtsNear = [];

  for (let a = 0; a < 360; a += 1.5) {
    let pt = getScallopOvalPoint(a, rx, ry, numLobes, lobeAmp);
    outerPts.push(pt);

    // Variable paper lift! Some lobes curl slightly upward off the board,
    // casting a wider shadow to fool the eye into lifting the paper.
    let curlFactor = 1.0 + 0.85 * pow(max(0, sin(a * 3 - 40)), 2) + 0.6 * pow(max(0, cos(a * 2 + 25)), 3);
    let sdx = 6.5 * curlFactor;
    let sdy = 9.0 * curlFactor;

    shadowPtsFar.push([pt[0] + sdx, pt[1] + sdy]);
    shadowPtsNear.push([pt[0] + sdx * 0.45, pt[1] + sdy * 0.45]);
  }

  // Soft outer shadow wash
  fillPoly(shadowPtsFar, PAL.groundShadow, 145, 0.22, 0.45, 0.15);
  // Crisp contact shadow under the paper rim
  washPoly(shadowPtsNear, PAL.groundShadow, 185);

  // Velvet charcoal shadow softening along lifted edges
  brush.set("velvetShadow", PAL.groundShadow, 1.3);
  strokePoly(shadowPtsFar, true, 0.15);

  // -------------------------------------------------------------------------
  // B. BASE IVORY PAPER BODY OF THE LACE DOILY
  // -------------------------------------------------------------------------
  washPoly(outerPts, PAL.laceBase, 255);

  // Subtle warm antique paper toning & light-to-shadow gradient across the lace
  fillPoly(outerPts, PAL.laceCream, 70, 0.12, 0.35, 0.15);

  // Paper thickness highlight along top-left scalloped perimeter & shadow on bottom-right
  for (let i = 0; i < outerPts.length; i++) {
    let p1 = outerPts[i];
    let p2 = outerPts[(i + 1) % outerPts.length];
    let nx = p2[1] - p1[1];
    let ny = -(p2[0] - p1[0]);
    let dot = nx * LIGHT_DX + ny * LIGHT_DY;

    if (dot < 0) {
      // Top-left facing edge catches bright white + soft gilt highlight
      brush.set("filigree", PAL.lacePure, 0.72);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    } else {
      // Bottom-right edge shows paper-thickness bevel
      brush.set("rotring", PAL.laceGreyDark, 0.48);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // -------------------------------------------------------------------------
  // C. ZONE 1 (OUTER): SCALLOPED LACE LOBES, PIERCED EYELETS & SOFT GILT EDGES
  // -------------------------------------------------------------------------
  for (let l = 0; l < numLobes; l++) {
    let aCenter = (l + 0.5) * (360 / numLobes);
    let aStart = l * (360 / numLobes);
    let aEnd = (l + 1) * (360 / numLobes);

    // Gilt highlight catching the scalloped crest
    let giltArc = [];
    for (let a = aStart + 1.2; a <= aEnd - 1.2; a += 1.5) {
      let gp = getScallopOvalPoint(a, rx - 2.5, ry - 2.5, numLobes, lobeAmp * 0.92);
      giltArc.push(gp);
    }
    brush.set("rotring", PAL.giltMid, 0.5);
    brush.spline(giltArc, 0.35);
    brush.set("filigree", PAL.giltBright, 0.42);
    brush.spline(giltArc, 0.35);

    // Occasional soft gilt leaf fleck on the scallop rim
    if (l % 2 === 0) {
      let tipPt = getScallopOvalPoint(aCenter, rx - 1, ry - 1, numLobes, lobeAmp);
      brush.set("giltPen", PAL.giltPale, 0.65);
      brush.circle(tipPt[0], tipPt[1], 4.5, 0.2);
    }

    // Arc of 5 tiny punched pin-holes inside each scallop lobe
    for (let k = -2; k <= 2; k++) {
      let ak = aCenter + k * 1.65;
      let hp = getScallopOvalPoint(ak, rx - 14, ry - 14, numLobes, lobeAmp * 0.65);
      drawPunchedHole(hp[0], hp[1], 2.4, PAL.groundBase, PAL.lacePure, PAL.groundShadow, k === 0);
    }

    // Central pierced teardrop in each scallop lobe
    let cx = (rx - 9) * cos(aCenter);
    let cy = (ry - 9) * sin(aCenter);
    drawPiercedPetalHole(cx, cy, aCenter, 15, 7.5, PAL.groundDeep);

    // Embossed white C-scrolls framing each scallop lobe
    let s1 = [(rx - 22) * cos(aStart + 1.5), (ry - 22) * sin(aStart + 1.5)];
    let s2 = [(rx - 4) * cos(aCenter), (ry - 4) * sin(aCenter)];
    let s3 = [(rx - 22) * cos(aEnd - 1.5), (ry - 22) * sin(aEnd - 1.5)];

    brush.set("2H", PAL.laceGreyMid, 0.42);
    brush.spline([[s1[0] + 1, s1[1] + 1], [s2[0] + 1, s2[1] + 1], [s3[0] + 1, s3[1] + 1]], 0.45);
    brush.set("filigree", PAL.lacePure, 0.68);
    brush.spline([s1, s2, s3], 0.45);

    // Inner cusp pierced quatrefoil between lobes
    let cuspX = (rx - 24) * cos(aStart);
    let cuspY = (ry - 24) * sin(aStart);
    drawPunchedHole(cuspX, cuspY, 3.8, PAL.groundDeep, PAL.lacePure, PAL.groundShadow, true);
  }

  // -------------------------------------------------------------------------
  // D. ZONE 2: WIDE PIERCED COBWEB TRELLIS / HONEYCOMB MESH RING
  //    (Where the rose-madder ground shows through hundreds of diamond cutouts
  //     and fine white-and-pale-grey pen threads form the lattice)
  // -------------------------------------------------------------------------
  const meshOuterRx = rx - 34;
  const meshOuterRy = ry - 34;
  const meshInnerRx = rx - 108;
  const meshInnerRy = ry - 108;

  // Fill the mesh band with the rose-madder ground first (since it's 75% pierced open!)
  let meshOuterPoly = [];
  let meshInnerPoly = [];
  for (let a = 0; a < 360; a += 4) {
    meshOuterPoly.push([meshOuterRx * cos(a), meshOuterRy * sin(a)]);
    meshInnerPoly.push([meshInnerRx * cos(a), meshInnerRy * sin(a)]);
  }
  washPoly(meshOuterPoly, PAL.groundBase, 245);

  // Draw the cast shadows of the criss-crossing paper lace threads onto the rose-madder ground
  const numSpokes = 72;
  const numRings = 5;

  for (let s = 0; s < numSpokes; s++) {
    let a1 = s * (360 / numSpokes);
    let a2 = (s + 3) * (360 / numSpokes);
    let a3 = (s - 3) * (360 / numSpokes);

    let pOut = [meshOuterRx * cos(a1), meshOuterRy * sin(a1)];
    let pInCW = [meshInnerRx * cos(a2), meshInnerRy * sin(a2)];
    let pInCCW = [meshInnerRx * cos(a3), meshInnerRy * sin(a3)];

    // Cast shadow on ground (offset +3.5, +4.8)
    brush.set("rotring", PAL.groundShadow, 0.55);
    brush.line(pOut[0] + 3.5, pOut[1] + 4.8, pInCW[0] + 3.5, pInCW[1] + 4.8);
    brush.line(pOut[0] + 3.5, pOut[1] + 4.8, pInCCW[0] + 3.5, pInCCW[1] + 4.8);
  }

  // Now draw the pale grey edge + crisp white filigree paper threads of the mesh
  for (let s = 0; s < numSpokes; s++) {
    let a1 = s * (360 / numSpokes);
    let a2 = (s + 3) * (360 / numSpokes);
    let a3 = (s - 3) * (360 / numSpokes);

    let pOut = [meshOuterRx * cos(a1), meshOuterRy * sin(a1)];
    let pInCW = [meshInnerRx * cos(a2), meshInnerRy * sin(a2)];
    let pInCCW = [meshInnerRx * cos(a3), meshInnerRy * sin(a3)];

    // Pale grey paper thickness side
    brush.set("rotring", PAL.laceGreyMid, 0.65);
    brush.line(pOut[0] + 0.8, pOut[1] + 1.0, pInCW[0] + 0.8, pInCW[1] + 1.0);
    brush.line(pOut[0] + 0.8, pOut[1] + 1.0, pInCCW[0] + 0.8, pInCCW[1] + 1.0);

    // Crisp white filigree top face
    brush.set("filigree", PAL.lacePure, 0.82);
    brush.line(pOut[0], pOut[1], pInCW[0], pInCW[1]);
    brush.line(pOut[0], pOut[1], pInCCW[0], pInCCW[1]);
  }

  // Concentric filigree rings & tiny embossed knots at mesh intersections
  for (let rIdx = 0; rIdx <= numRings; rIdx++) {
    let frac = rIdx / numRings;
    let crx = lerp(meshInnerRx, meshOuterRx, frac);
    let cry = lerp(meshInnerRy, meshOuterRy, frac);

    // Shadow ring on ground
    brush.set("rotring", PAL.groundShadow, 0.45);
    let ringShadowPts = [];
    let ringPts = [];
    for (let a = 0; a <= 360; a += 5) {
      ringShadowPts.push([crx * cos(a) + 3.2, cry * sin(a) + 4.4]);
      ringPts.push([crx * cos(a), cry * sin(a)]);
    }
    brush.spline(ringShadowPts, 0.25);

    // Pale grey under-rim + bright white thread
    brush.set("rotring", PAL.laceGreyMid, 0.55);
    brush.spline(ringPts.map(p => [p[0] + 0.7, p[1] + 0.9]), 0.25);
    brush.set("filigree", PAL.lacePure, 0.75);
    brush.spline(ringPts, 0.25);

    // Tiny pearl picot dots at intersections on alternating rings
    if (rIdx === 1 || rIdx === 3 || rIdx === 4) {
      for (let s = 0; s < numSpokes; s += 2) {
        let a = (s + (rIdx % 2) * 0.5) * (360 / numSpokes);
        let kx = crx * cos(a);
        let ky = cry * sin(a);
        brush.set("filigree", PAL.lacePure, 0.65);
        brush.circle(kx, ky, 1.8, 0.1);
      }
    }
  }

  // Restore solid ivory paper inside the mesh band, with its inner rim shadow
  washPoly(meshInnerPoly, PAL.laceBase, 255);
  fillPoly(meshInnerPoly, PAL.laceCream, 55, 0.1, 0.3, 0.1);

  // Embossed pearl & gilt border framing the cobweb mesh band (outer & inner)
  const borderRadii = [
    [meshOuterRx + 3, meshOuterRy + 3],
    [meshInnerRx - 2, meshInnerRy - 2]
  ];
  for (let br of borderRadii) {
    let brx = br[0];
    let bry = br[1];
    for (let a = 0; a < 360; a += 3) {
      let bx = brx * cos(a);
      let by = bry * sin(a);
      // Embossed pearl bead
      brush.set("2H", PAL.laceGreyDark, 0.45);
      brush.arc(bx + 0.8, by + 1.0, 3.2, 10, 175);
      brush.set("filigree", PAL.lacePure, 0.75);
      brush.arc(bx - 0.5, by - 0.6, 3.2, 190, 350);
      if (a % 9 === 0) {
        brush.set("rotring", PAL.giltBright, 0.38);
        brush.arc(bx - 0.4, by - 0.4, 2.5, 200, 330);
      }
    }
  }

  // -------------------------------------------------------------------------
  // E. ZONE 3: EMBOSSED VICTORIAN ROSETTE & FLORAL GARLAND BAND
  // -------------------------------------------------------------------------
  const garlandRx = rx - 152;
  const garlandRy = ry - 152;
  const numRosettes = 16;

  for (let i = 0; i < numRosettes; i++) {
    let a = i * (360 / numRosettes);
    let rcx = garlandRx * cos(a);
    let rcy = garlandRy * sin(a);

    // Alternating large 8-petal embossed rosettes and pierced floral medallions
    if (i % 2 === 0) {
      // Pierced dark background halo around the rosette for high relief
      for (let p = 0; p < 8; p++) {
        let pa = a + p * 45 + 22.5;
        let hx = rcx + cos(pa) * 29;
        let hy = rcy + sin(pa) * 29;
        drawPiercedPetalHole(hx, hy, pa, 11, 5.5, PAL.groundBase);
      }
      drawEmbossedRosette(rcx, rcy, 25, 8, true);
    } else {
      // Ornate pierced diamond-quatrefoil medallion with embossed scroll foliage
      for (let q = 0; q < 4; q++) {
        let qa = a + q * 90;
        let qx = rcx + cos(qa) * 14;
        let qy = rcy + sin(qa) * 14;
        drawPiercedPetalHole(qx, qy, qa, 16, 7.5, PAL.groundDeep);
      }
      drawPunchedHole(rcx, rcy, 5.5, PAL.groundDeep, PAL.lacePure, PAL.groundShadow, true);

      // Embossed white leaf sprays curving left and right
      for (let side of [-1, 1]) {
        for (let lf = 1; lf <= 3; lf++) {
          let la = a + side * (lf * 3.2);
          let lr = garlandRx + (lf - 2) * 10;
          let lx = lr * cos(la);
          let ly = (garlandRy + (lf - 2) * 10) * sin(la);
          // Shadow under embossed leaf
          brush.set("2H", PAL.laceGreyMid, 0.48);
          brush.arc(lx + 1, ly + 1.2, 7, 15, 165);
          // Raised white leaf highlight
          brush.set("filigree", PAL.lacePure, 0.72);
          brush.arc(lx - 0.6, ly - 0.8, 7, 195, 345);
        }
      }
    }

    // Connecting embossed vine & punched pin-hole trail between medallions
    let aMid = a + 180 / numRosettes;
    for (let t = -2; t <= 2; t++) {
      let ta = aMid + t * 1.4;
      let waveR = 12 * sin(t * 60);
      let tx = (garlandRx + waveR) * cos(ta);
      let ty = (garlandRy + waveR) * sin(ta);
      drawPunchedHole(tx, ty, 2.6, PAL.groundBase, PAL.lacePure, PAL.groundShadow, false);
    }
  }

  // -------------------------------------------------------------------------
  // F. ZONE 4: INNER SCALLOPED MEDALLION RING & FINE PIN-PRICK FILIGREE
  // -------------------------------------------------------------------------
  const innerMedRx = rx - 205;
  const innerMedRy = ry - 205;
  const innerLobes = 28;

  for (let l = 0; l < innerLobes; l++) {
    let a1 = l * (360 / innerLobes);
    let aMid = (l + 0.5) * (360 / innerLobes);
    let a2 = (l + 1) * (360 / innerLobes);

    let p1 = [innerMedRx * cos(a1), innerMedRy * sin(a1)];
    let pMid = [(innerMedRx - 14) * cos(aMid), (innerMedRy - 14) * sin(aMid)];
    let p2 = [innerMedRx * cos(a2), innerMedRy * sin(a2)];

    // Embossed inner scallop arch
    brush.set("2H", PAL.laceGreyMid, 0.48);
    brush.spline([[p1[0] + 1, p1[1] + 1], [pMid[0] + 1, pMid[1] + 1], [p2[0] + 1, p2[1] + 1]], 0.45);
    brush.set("filigree", PAL.lacePure, 0.75);
    brush.spline([p1, pMid, p2], 0.45);

    // Gilt accent on inner scallop arch
    brush.set("rotring", PAL.giltMid, 0.35);
    brush.spline([[p1[0], p1[1]], [pMid[0], pMid[1]], [p2[0], p2[1]]], 0.45);

    // Pierced eyelet at each arch peak and cusp
    drawPunchedHole(pMid[0], pMid[1], 3.2, PAL.groundDeep, PAL.lacePure, PAL.groundShadow, true);
    drawPunchedHole(p1[0], p1[1], 2.2, PAL.groundBase, PAL.lacePure, PAL.groundShadow, false);
  }

  // Delicate radial pen-and-ink filigree scrollwork inside the central reserve
  // (Mostly visible around the edges of the folded love letter)
  for (let a = 0; a < 360; a += 15) {
    let sx1 = (innerMedRx - 24) * cos(a);
    let sy1 = (innerMedRy - 24) * sin(a);
    let sx2 = (innerMedRx - 52) * cos(a + 5);
    let sy2 = (innerMedRy - 52) * sin(a + 5);
    let sx3 = (innerMedRx - 38) * cos(a + 11);
    let sy3 = (innerMedRy - 38) * sin(a + 11);

    brush.set("2H", PAL.laceGreyLight, 0.38);
    brush.spline([[sx1 + 0.8, sy1 + 0.8], [sx2 + 0.8, sy2 + 0.8], [sx3 + 0.8, sy3 + 0.8]], 0.5);
    brush.set("filigree", PAL.lacePure, 0.62);
    brush.spline([[sx1, sy1], [sx2, sy2], [sx3, sy3]], 0.5);
    drawPunchedHole(sx3, sy3, 2.0, PAL.groundBase, PAL.lacePure, PAL.groundShadow, false);
  }
}

// ============================================================================
// 5. FOLDED LOVE LETTER & IRON-GALL BROWN HANDWRITING
// ============================================================================

function drawIronGallScriptLine(x1, y1, x2, y2, scaleH, inkCol, density = 1.0, slantDeg = -18) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let totalLen = sqrt(dx * dx + dy * dy);
  if (totalLen < 8) return;

  let ux = dx / totalLen;
  let uy = dy / totalLen;
  let nx = -uy;
  let ny = ux;

  // Faint ruled baseline / ink halo
  let curDist = 0;
  let slantX = sin(slantDeg) * scaleH;
  let slantY = -cos(slantDeg) * scaleH;

  while (curDist < totalLen - 6) {
    // Word length
    let wordLen = min(random(18, 62), totalLen - curDist - 4);
    let numLetters = max(2, floor((wordLen / (scaleH * 0.65)) * density));
    let wordPts = [];

    for (let l = 0; l <= numLetters; l++) {
      let t = curDist + (l / numLetters) * wordLen;
      let bx = x1 + ux * t;
      let by = y1 + uy * t;

      // Copperplate / Spencerian upstroke & downstroke rhythm
      let isAscender = random() < 0.16;
      let isDescender = !isAscender && random() < 0.14;
      let amp = scaleH * (isAscender ? random(1.5, 2.3) : (isDescender ? random(-1.8, -1.1) : random(0.45, 0.95)));

      // Upstroke peak
      let px = bx + slantX * (amp / scaleH) + ux * (scaleH * 0.22);
      let py = by + slantY * (amp / scaleH) + uy * (scaleH * 0.22);
      wordPts.push([px, py]);

      // Downstroke return to baseline
      let rx = bx + ux * (scaleH * 0.52) + nx * random(-1.2, 1.2);
      let ry = by + uy * (scaleH * 0.52) + ny * random(-1.2, 1.2);
      wordPts.push([rx, ry]);

      // Occasional shaded downstroke (thicker iron-gall nib pressure)
      if (random() < 0.45) {
        brush.set("rotring", inkCol, random(0.38, 0.62));
        brush.line(px, py, rx, ry);
      }

      // Occasional loop on ascender/descender
      if (isAscender || isDescender) {
        let loopPts = [
          [bx, by],
          [px - ux * (scaleH * 0.28), py - uy * (scaleH * 0.28)],
          [px + ux * (scaleH * 0.15), py + uy * (scaleH * 0.15)],
          [rx, ry]
        ];
        brush.set("filigree", inkCol, 0.32);
        brush.spline(loopPts, 0.55);
      }
    }

    if (wordPts.length >= 2) {
      brush.set("rotring", inkCol, random(0.28, 0.42));
      brush.spline(wordPts, 0.45);
    }

    // Dot for 'i' or cross for 't'
    if (random() < 0.55) {
      let dotT = curDist + wordLen * random(0.25, 0.75);
      let dotX = x1 + ux * dotT + slantX * 1.15;
      let dotY = y1 + uy * dotT + slantY * 1.15;
      brush.set("rotring", inkCol, 0.42);
      if (random() < 0.6) {
        brush.circle(dotX, dotY, 0.8, 0.1);
      } else {
        brush.line(dotX - ux * 4, dotY - uy * 4, dotX + ux * 5, dotY + uy * 5);
      }
    }

    curDist += wordLen + random(8, 18); // Space between words
  }
}

function drawLaidPaperTexture(polyPts, minX, maxX, minY, maxY) {
  // Subtle laid rag paper wire lines (horizontal closely spaced, vertical chain lines every 38px)
  for (let y = minY; y <= maxY; y += 5) {
    brush.set("2H", y % 10 === 0 ? PAL.paperWarm : PAL.paperLight, 0.25);
    brush.line(minX + 6, y, maxX - 6, y);
  }
  for (let x = minX + 24; x <= maxX - 16; x += 38) {
    brush.set("2H", PAL.paperShade, 0.22);
    brush.line(x, minY + 6, x, maxY - 6);
  }
}

function drawFoldedLoveLetter() {
  // Envelope dimensions in local letter space (centered around 0,0)
  const W = 470;
  const H = 330;
  const hw = W / 2; // 235
  const hh = H / 2; // 165

  // Slightly organic hand-folded corners of the antique rag letter packet
  const TL = [-hw + 4, -hh + 2];
  const TR = [hw - 3, -hh - 3];
  const BR = [hw + 2, hh - 2];
  const BL = [-hw - 2, hh + 4];

  // Seal convergence point (slightly right and below center for authentic folds)
  const SC = [18, 12];

  // -------------------------------------------------------------------------
  // A. PEEKING CORNER OF AN INNER UNFOLDED NOTE SHEET (Top-Left / Left)
  //    Tucked slightly askew inside the packet, showing dense iron-gall script
  // -------------------------------------------------------------------------
  const innerSheet = [
    [-hw - 28, -hh + 38],
    [45, -hh - 42],
    [110, 40],
    [-hw + 12, 118]
  ];

  // Cast shadow of inner sheet onto the white paper lace
  fillPoly(
    innerSheet.map(p => [p[0] + 10, p[1] + 14]),
    PAL.laceShadow,
    135,
    0.2,
    0.35,
    0.15
  );
  brush.set("velvetShadow", PAL.laceShadow, 1.2);
  strokePoly(innerSheet.map(p => [p[0] + 8, p[1] + 11]), true, 0.1);

  // Inner sheet base paper
  washPoly(innerSheet, PAL.paperInterior, 255);
  fillPoly(innerSheet, PAL.paperWarm, 65, 0.08, 0.3, 0.15);

  // Gilt edge on inner note sheet!
  brush.set("rotring", PAL.giltBright, 0.55);
  brush.line(innerSheet[0][0], innerSheet[0][1], innerSheet[1][0], innerSheet[1][1]);
  brush.line(innerSheet[0][0], innerSheet[0][1], innerSheet[3][0], innerSheet[3][1]);

  // Iron-gall brown handwriting across the peeking inner sheet
  for (let row = 0; row < 8; row++) {
    let frac = (row + 1.2) / 9.5;
    let sx = lerp(innerSheet[0][0] + 14, innerSheet[3][0] + 14, frac);
    let sy = lerp(innerSheet[0][1] + 8, innerSheet[3][1] - 6, frac);
    let ex = lerp(innerSheet[1][0] - 16, innerSheet[2][0] - 16, frac);
    let ey = lerp(innerSheet[1][1] + 12, innerSheet[2][1] - 8, frac);
    drawIronGallScriptLine(sx, sy, ex, ey, 8.5, row % 2 === 0 ? PAL.inkDark : PAL.inkMid, 1.05, -14);
  }

  // -------------------------------------------------------------------------
  // B. MAIN ENVELOPE DROP SHADOW ONTO THE PAPER LACE
  //    Notice how the right and bottom corners lift slightly off the lace!
  // -------------------------------------------------------------------------
  const envShadowPts = [
    [TL[0] + 7, TL[1] + 9],
    [TR[0] + 15, TR[1] + 19],
    [BR[0] + 18, BR[1] + 24],
    [BL[0] + 10, BL[1] + 14]
  ];
  fillPoly(envShadowPts, PAL.laceShadow, 155, 0.22, 0.4, 0.15);
  washPoly(
    [
      [TL[0] + 4, TL[1] + 5],
      [TR[0] + 8, TR[1] + 10],
      [BR[0] + 9, BR[1] + 12],
      [BL[0] + 5, BL[1] + 7]
    ],
    PAL.laceShadow,
    170
  );
  brush.set("velvetShadow", PAL.laceShadow, 1.4);
  strokePoly(envShadowPts, true, 0.12);

  // -------------------------------------------------------------------------
  // C. ENVELOPE BODY & EXPOSED INTERIOR WELL (Revealed because top flap is lifted!)
  // -------------------------------------------------------------------------
  const envRect = [TL, TR, BR, BL];
  washPoly(envRect, PAL.paperInterior, 255);
  drawLaidPaperTexture(envRect, -hw, hw, -hh, hh);

  // Deep recessed shadow inside the envelope well under the lifted top flap
  fillPoly([TL, TR, [SC[0] + 35, SC[1] - 10], [SC[0] - 45, SC[1] - 15]], PAL.paperDeepShade, 90, 0.18, 0.35, 0.1);

  // Dense, passionate iron-gall brown love letter handwriting visible on the interior sheet!
  // (Written horizontally across the inside of the letter sheet before it was folded)
  const wellTopY = -hh + 18;
  const wellBotY = SC[1] + 15;
  for (let y = wellTopY; y <= wellBotY; y += 15) {
    let xLeft = map(y, wellTopY, wellBotY, TL[0] + 24, -110);
    let xRight = map(y, wellTopY, wellBotY, TR[0] - 24, 125);
    let inkC = (y % 30 === 0) ? PAL.inkDark : PAL.inkMid;
    drawIronGallScriptLine(xLeft, y, xRight, y - 3, 9.2, inkC, 1.1, -16);
  }

  // Expressive calligraphic flourish ("Mon coeur..." / love signature curl inside the well)
  brush.set("rotring", PAL.inkDark, 0.48);
  brush.spline([[-55, -75], [-15, -88], [32, -72], [65, -82], [20, -64], [-30, -68]], 0.65);

  // -------------------------------------------------------------------------
  // D. LEFT AND RIGHT FOLDED ENVELOPE FLAPS
  // -------------------------------------------------------------------------
  const leftFlap = [
    TL,
    [SC[0] - 12, SC[1] - 18],
    [SC[0] - 10, SC[1] + 22],
    BL
  ];
  const rightFlap = [
    TR,
    [SC[0] + 22, SC[1] - 16],
    [SC[0] + 18, SC[1] + 24],
    BR
  ];

  // Shadows cast by left and right flaps onto the interior well
  fillPoly(leftFlap.map(p => [p[0] + 4, p[1] + 3]), PAL.paperDeepShade, 110, 0.1, 0.25, 0.1);
  fillPoly(rightFlap.map(p => [p[0] - 3, p[1] + 4]), PAL.paperDeepShade, 95, 0.1, 0.25, 0.1);

  // Wash & texture for Left Flap
  washPoly(leftFlap, PAL.paperBase, 255);
  fillPoly(leftFlap, PAL.paperLight, 95, 0.12, 0.3, 0.1);

  // Wash & texture for Right Flap (slightly more in shadow on right slope)
  washPoly(rightFlap, PAL.paperBase, 255);
  fillPoly(rightFlap, PAL.paperWarm, 110, 0.12, 0.3, 0.1);

  // Faint, ghostly iron-gall ink bleed-through visible through the translucent rag paper of the side flaps!
  for (let by = -hh + 35; by < hh - 35; by += 18) {
    let maxLeftX = map( abs(by), 0, hh, SC[0] - 25, -hw + 30);
    if (maxLeftX > -hw + 25) {
      drawIronGallScriptLine(-hw + 20, by, maxLeftX, by + 2, 7.5, PAL.inkBleed, 0.75, 15);
    }
    let minRightX = map(abs(by), 0, hh, SC[0] + 32, hw - 30);
    if (minRightX < hw - 25) {
      drawIronGallScriptLine(minRightX, by - 2, hw - 20, by, 7.5, PAL.inkBleed, 0.75, 15);
    }
  }

  // Crisp paper-thickness edges on Left & Right flaps
  brush.set("filigree", PAL.lacePure, 0.72);
  brush.line(leftFlap[0][0], leftFlap[0][1], leftFlap[1][0], leftFlap[1][1]);
  brush.line(leftFlap[1][0], leftFlap[1][1], leftFlap[2][0], leftFlap[2][1]);
  brush.set("rotring", PAL.paperDeepShade, 0.52);
  brush.line(leftFlap[2][0], leftFlap[2][1], leftFlap[3][0], leftFlap[3][1]);

  brush.set("rotring", PAL.paperDeepShade, 0.5);
  brush.line(rightFlap[0][0], rightFlap[0][1], rightFlap[1][0], rightFlap[1][1]);
  brush.set("filigree", PAL.lacePure, 0.65);
  brush.line(rightFlap[2][0], rightFlap[2][1], rightFlap[3][0], rightFlap[3][1]);

  // -------------------------------------------------------------------------
  // E. LOWER ENVELOPE FLAP (Overlapping the side flaps, bearing postscript/address
  //    in iron-gall brown scribble)
  // -------------------------------------------------------------------------
  const botFlap = [
    BL,
    [SC[0] - 26, SC[1] - 6],
    [SC[0] + 28, SC[1] - 4],
    BR
  ];

  // Cast shadow of lower flap edge onto side flaps
  fillPoly(
    [
      [BL[0], BL[1]],
      [SC[0] - 28, SC[1] - 11],
      [SC[0] + 32, SC[1] - 9],
      [BR[0], BR[1]]
    ],
    PAL.paperDeepShade,
    125,
    0.08,
    0.25,
    0.1
  );

  washPoly(botFlap, PAL.paperBase, 255);
  fillPoly(botFlap, PAL.paperWarm, 85, 0.1, 0.3, 0.12);

  // Soft crease modeling along the bottom fold
  for (let i = 0; i < 6; i++) {
    let y = hh - i * 2.5;
    brush.set("2H", PAL.paperShade, 0.35);
    brush.line(BL[0] + 8, y, BR[0] - 8, y - 2);
  }

  // Bright paper-thickness highlight along the top diagonal edges of the bottom flap
  brush.set("filigree", PAL.lacePure, 0.8);
  brush.line(BL[0], BL[1], SC[0] - 26, SC[1] - 6);
  brush.line(SC[0] - 26, SC[1] - 6, SC[0] + 28, SC[1] - 4);
  brush.set("2H", PAL.paperShade, 0.45);
  brush.line(SC[0] + 28, SC[1] - 4, BR[0], BR[1]);

  // Soft gilt highlight catching the deckled edge of the lower flap
  brush.set("rotring", PAL.giltBright, 0.42);
  brush.line(BL[0] + 35, lerp(BL[1], SC[1] - 6, 0.18), SC[0] - 26, SC[1] - 6);

  // Iron-gall brown handwriting across the lower flap (a coy inscription / verse on the fold)
  drawIronGallScriptLine(-135, 62, 115, 56, 10.5, PAL.inkDark, 0.95, -18);
  drawIronGallScriptLine(-155, 86, 145, 79, 9.5, PAL.inkMid, 1.0, -18);
  drawIronGallScriptLine(-175, 109, 165, 102, 9.2, PAL.inkMid, 1.0, -18);
  drawIronGallScriptLine(-95, 132, 135, 126, 8.8, PAL.inkLight, 0.88, -18);

  // Elegant Spencerian flourish beneath the inscription
  brush.set("rotring", PAL.inkDark, 0.45);
  brush.spline([
    [-65, 146],
    [15, 139],
    [88, 148],
    [45, 155],
    [-25, 149],
    [65, 143]
  ], 0.6);

  // Tiny ink splatters / nib flecks near the flourish
  brush.set("rotring", PAL.inkDark, 0.5);
  brush.circle(94, 146, 1.1, 0.2);
  brush.circle(101, 149, 0.7, 0.2);
  brush.circle(-72, 148, 0.9, 0.2);

  // -------------------------------------------------------------------------
  // F. PRIZED-OPEN / LIFTED TOP FLAP (Cracked free from the crimson wax seal!)
  //    It arches upward, casting a dramatic curved shadow into the letter well.
  // -------------------------------------------------------------------------
  // Because it is lifted toward the light (top-left), its tip is shifted up-left
  // from the seal center SC, and its shadow drops down-right onto the well & flaps!
  const liftedTip = [SC[0] - 8, SC[1] - 24];
  const topFlapShadow = [
    TL,
    TR,
    [liftedTip[0] + 44, liftedTip[1] + 58],
    [liftedTip[0] + 14, liftedTip[1] + 62]
  ];

  // Dramatic trompe-l'oeil drop shadow of the lifted flap!
  fillPoly(topFlapShadow, PAL.paperDeepShade, 145, 0.24, 0.4, 0.15);
  fillPoly(
    [
      TL,
      TR,
      [liftedTip[0] + 24, liftedTip[1] + 34],
      [liftedTip[0] + 6, liftedTip[1] + 36]
    ],
    PAL.inkLight,
    75,
    0.18,
    0.3,
    0.1
  );
  brush.set("velvetShadow", PAL.paperDeepShade, 1.35);
  brush.spline([TL, [liftedTip[0] + 18, liftedTip[1] + 48], [liftedTip[0] + 38, liftedTip[1] + 45], TR], 0.3);

  // The lifted top flap itself (with a gentle 3D curve)
  const topFlap = [
    TL,
    TR,
    [liftedTip[0] + 16, liftedTip[1] - 2],
    [liftedTip[0] - 14, liftedTip[1]]
  ];
  washPoly(topFlap, PAL.paperLight, 255);

  // Warm curvature shading across the arching flap
  fillPoly(
    [
      [lerp(TL[0], TR[0], 0.45), lerp(TL[1], TR[1], 0.45)],
      TR,
      [liftedTip[0] + 16, liftedTip[1] - 2],
      [liftedTip[0], liftedTip[1] - 1]
    ],
    PAL.paperWarm,
    95,
    0.15,
    0.3,
    0.1
  );

  // Iron-gall script bleeding faintly through the lifted top flap + written inside edge
  for (let row = 0; row < 5; row++) {
    let t = (row + 1) / 6.2;
    let lx = lerp(TL[0] + 28, liftedTip[0] - 10, t);
    let ly = lerp(TL[1] + 14, liftedTip[1] - 8, t);
    let rx = lerp(TR[0] - 28, liftedTip[0] + 12, t);
    let ry = lerp(TR[1] + 14, liftedTip[1] - 8, t);
    drawIronGallScriptLine(lx, ly, rx, ry, 8.0, PAL.inkBleed, 0.85, -15);
  }

  // Crisp lit paper thickness along the lifted flap's free edges
  brush.set("filigree", PAL.lacePure, 0.85);
  brush.line(TL[0], TL[1], liftedTip[0] - 14, liftedTip[1]);
  brush.line(liftedTip[0] - 14, liftedTip[1], liftedTip[0] + 16, liftedTip[1] - 2);
  brush.set("rotring", PAL.paperShade, 0.55);
  brush.line(liftedTip[0] + 16, liftedTip[1] - 2, TR[0], TR[1]);

  // Soft gilt edge along the top fold & flap rim
  brush.set("rotring", PAL.giltBright, 0.45);
  brush.line(TL[0], TL[1], TR[0], TR[1]);
  brush.line(TL[0], TL[1], lerp(TL[0], liftedTip[0] - 14, 0.65), lerp(TL[1], liftedTip[1], 0.65));

  // Outer perimeter creases & trompe-l'oeil paper thickness of the whole letter packet
  brush.set("filigree", PAL.lacePure, 0.85);
  brush.line(TL[0], TL[1], BL[0], BL[1]);
  brush.line(TL[0], TL[1], TR[0], TR[1]);

  brush.set("rotring", PAL.paperDeepShade, 0.6);
  brush.line(TR[0], TR[1], BR[0], BR[1]);
  brush.line(BL[0], BL[1], BR[0], BR[1]);

  // Subtle crease lines radiating from the corners
  brush.set("2H", PAL.paperShade, 0.4);
  brush.line(TL[0], TL[1], TL[0] + 45, TL[1] + 32);
  brush.line(BL[0], BL[1], BL[0] + 52, BL[1] - 35);
  brush.line(BR[0], BR[1], BR[0] - 48, BR[1] - 34);
}

// ============================================================================
// 6. CRACKED CRIMSON WAX SEAL & SCATTERED WAX CRUMBS
// ============================================================================

function drawCrackedWaxSeal(cx, cy) {
  const rx = 38;
  const ry = 35;

  // We split the wax seal into two main fractured halves:
  // 1) Lower-Right main half (still firmly adhered to the lower/side flaps & ribbon)
  // 2) Upper-Left cracked half (prized slightly upward with the lifted top flap, leaving a dark jagged fissure!)

  // Generate organic molten wax perimeter for Upper-Left half (angles 145 to 325)
  // and Lower-Right half (angles -35 to 145)
  const crackAngle = -35; // -35 deg to 145 deg diagonal fracture line

  // Jagged fracture path across the center of the seal
  const crackPts = [
    [cx + cos(145) * (rx + 3), cy + sin(145) * (ry + 3)],
    [cx - 18, cy + 12],
    [cx - 8, cy + 2],
    [cx - 2, cy + 7],
    [cx + 6, cy - 5],
    [cx + 15, cy - 3],
    [cx + 22, cy - 14],
    [cx + cos(325) * (rx + 3), cy + sin(325) * (ry + 3)]
  ];

  // Upper-left half shifted slightly (-2.5, -3.5) from being prized open!
  const ulShift = [-2.5, -3.5];
  let ulPoly = [];
  for (let a = 145; a <= 325; a += 8) {
    let wobble = 3.2 * sin(a * 5) + 1.8 * cos(a * 8);
    ulPoly.push([
      cx + ulShift[0] + cos(a) * (rx + wobble),
      cy + ulShift[1] + sin(a) * (ry + wobble)
    ]);
  }
  for (let i = crackPts.length - 1; i >= 0; i--) {
    ulPoly.push([crackPts[i][0] + ulShift[0], crackPts[i][1] + ulShift[1]]);
  }

  // Lower-right half anchored in place
  let lrPoly = [...crackPts];
  for (let a = -35; a <= 145; a += 8) {
    let wobble = 3.2 * sin(a * 5 + 20) + 2.0 * cos(a * 7);
    lrPoly.push([
      cx + cos(a) * (rx + wobble),
      cy + sin(a) * (ry + wobble)
    ]);
  }

  // -------------------------------------------------------------------------
  // A. CAST SHADOW OF THE THICK WAX SEAL ONTO THE PAPER FLAPS
  // -------------------------------------------------------------------------
  fillPoly(ulPoly.map(p => [p[0] + 4.5, p[1] + 6.0]), PAL.waxDeep, 130, 0.14, 0.3, 0.1);
  fillPoly(lrPoly.map(p => [p[0] + 4.0, p[1] + 5.5]), PAL.waxDeep, 165, 0.14, 0.3, 0.1);

  // Torn paper fibers & dark crevice visible inside the crack between the two wax halves
  washPoly(
    [
      ...crackPts.map(p => [p[0] + ulShift[0], p[1] + ulShift[1]]),
      ...crackPts.slice().reverse()
    ],
    PAL.waxDeep,
    240
  );
  // Tiny white torn paper fibers spanning the fissure
  brush.set("filigree", PAL.paperLight, 0.45);
  for (let i = 1; i < crackPts.length - 1; i++) {
    let p = crackPts[i];
    brush.line(p[0], p[1], p[0] + ulShift[0] * 0.7, p[1] + ulShift[1] * 0.7);
  }

  // -------------------------------------------------------------------------
  // B. BASE CRIMSON SHELLAC WAX MASS
  // -------------------------------------------------------------------------
  washPoly(ulPoly, PAL.waxBase, 255);
  fillPoly(ulPoly, PAL.waxDark, 95, 0.08, 0.35, 0.2);

  washPoly(lrPoly, PAL.waxBase, 255);
  fillPoly(lrPoly, PAL.waxDark, 115, 0.08, 0.35, 0.2);

  // Bulbous rolled outer lip (characteristic of molten sealing wax pressed by a signet)
  for (let a = 152; a <= 318; a += 6) {
    let wobble = 3.2 * sin(a * 5) + 1.8 * cos(a * 8);
    let r = rx + wobble - 4.5;
    let px = cx + ulShift[0] + cos(a) * r;
    let py = cy + ulShift[1] + sin(a) * r;
    brush.set("rotring", PAL.waxBright, 0.9);
    brush.circle(px, py, 3.2, 0.2);
  }
  for (let a = -28; a <= 138; a += 6) {
    let wobble = 3.2 * sin(a * 5 + 20) + 2.0 * cos(a * 7);
    let r = rx + wobble - 4.5;
    let px = cx + cos(a) * r;
    let py = cy + sin(a) * r;
    brush.set("rotring", a < 55 ? PAL.waxMid : PAL.waxDark, 0.9);
    brush.circle(px, py, 3.4, 0.2);
  }

  // -------------------------------------------------------------------------
  // C. RECESSED INTAGLIO STAMP IMPRESSION (Central Oval & Pierced Heart Crest)
  // -------------------------------------------------------------------------
  const inRx = rx * 0.64;
  const inRy = ry * 0.64;

  // Recessed dark carmine well of the signet impression (split across the crack)
  brush.set("rotring", PAL.waxDeep, 0.85);
  brush.arc(cx + ulShift[0], cy + ulShift[1], inRx, 150, 320);
  brush.arc(cx, cy, inRx, 330, 500);

  // Beaded inner garter ring of the signet matrix
  for (let a = 0; a < 360; a += 12) {
    let isUpper = (a >= 145 && a <= 325);
    let sx = isUpper ? ulShift[0] : 0;
    let sy = isUpper ? ulShift[1] : 0;
    let bx = cx + sx + cos(a) * (inRx - 2.5);
    let by = cy + sy + sin(a) * (inRy - 2.5);
    brush.set("filigree", PAL.waxBright, 0.55);
    brush.circle(bx, by, 1.4, 0.1);
  }

  // Embossed central emblem inside the wax: A Victorian Heart & Foliage Crest, split by the crack!
  // Upper-left lobe of the heart (on the shifted upper-left wax piece)
  const heartUL = [
    [cx + ulShift[0] - 2, cy + ulShift[1] - 5],
    [cx + ulShift[0] - 9, cy + ulShift[1] - 12],
    [cx + ulShift[0] - 14, cy + ulShift[1] - 4],
    [cx + ulShift[0] - 8, cy + ulShift[1] + 4]
  ];
  fillPoly(heartUL, PAL.waxMid, 220, 0.04, 0.2, 0.1);
  brush.set("filigree", PAL.waxSpec, 0.65);
  brush.spline(heartUL.slice(0, 3), 0.4);

  // Lower-right lobe & point of the heart (on the anchored lower-right wax piece)
  const heartLR = [
    [cx + 1, cy - 4],
    [cx + 9, cy - 11],
    [cx + 14, cy - 2],
    [cx + 1, cy + 13],
    [cx - 7, cy + 5]
  ];
  fillPoly(heartLR, PAL.waxMid, 220, 0.04, 0.2, 0.1);
  brush.set("filigree", PAL.waxBright, 0.65);
  brush.spline(heartLR.slice(0, 3), 0.4);
  brush.set("rotring", PAL.waxDeep, 0.55);
  brush.spline(heartLR.slice(2), 0.3);

  // -------------------------------------------------------------------------
  // D. JAGGED FRACTURE EDGES, SECONDARY HAIRLINE CRACKS & RESINOUS SPECULARS
  // -------------------------------------------------------------------------
  // Brittle shellac wax turns a pale, chalky vermilion-pink along fresh fracture facets!
  let ulCrackEdge = crackPts.map(p => [p[0] + ulShift[0], p[1] + ulShift[1]]);
  brush.set("rotring", PAL.waxDeep, 0.75);
  brush.spline(ulCrackEdge, 0.1);

  // Lit lower-right fracture cliff (facing the top-left light directly!)
  brush.set("rotring", PAL.waxFracture, 0.85);
  brush.spline(crackPts, 0.1);
  brush.set("filigree", PAL.waxSpec, 0.75);
  brush.spline(crackPts.slice(1, 6), 0.1);

  // Secondary branching hairline cracks in the wax
  const branchCracks = [
    [[cx - 8, cy + 2], [cx - 16, cy - 8], [cx - 24, cy - 12]],
    [[cx + 6, cy - 5], [cx + 14, cy + 9], [cx + 22, cy + 15], [cx + 29, cy + 17]],
    [[cx - 2, cy + 7], [cx + 2, cy + 19], [cx - 3, cy + 28]]
  ];
  for (let bc of branchCracks) {
    brush.set("rotring", PAL.waxDeep, 0.55);
    brush.spline(bc, 0.15);
    brush.set("filigree", PAL.waxFracture, 0.42);
    brush.spline(bc.map(p => [p[0] + 0.7, p[1] + 0.7]), 0.15);
  }

  // High-gloss shellac specular highlights on the rounded outer wax rim
  let specArc1 = [];
  for (let a = 195; a <= 265; a += 8) {
    let r = rx - 4.2 + 2.5 * sin(a * 5);
    specArc1.push([cx + ulShift[0] + cos(a) * r, cy + ulShift[1] + sin(a) * r]);
  }
  brush.set("filigree", PAL.waxSpec, 0.9);
  brush.spline(specArc1, 0.4);

  let specArc2 = [];
  for (let a = -15; a <= 42; a += 8) {
    let r = rx - 5.5 + 2.5 * sin(a * 5 + 20);
    specArc2.push([cx + cos(a) * r, cy + sin(a) * r]);
  }
  brush.set("filigree", PAL.waxFracture, 0.75);
  brush.spline(specArc2, 0.4);

  // -------------------------------------------------------------------------
  // E. SCATTERED CRIMSON WAX CRUMBS & FLAKES (Broken off when the seal cracked!)
  // -------------------------------------------------------------------------
  const crumbs = [
    { x: cx - 54, y: cy + 26, r: 5.2 },
    { x: cx - 44, y: cy + 38, r: 3.4 },
    { x: cx + 48, y: cy - 28, r: 4.6 },
    { x: cx + 58, y: cy - 16, r: 2.8 },
    { x: cx + 38, y: cy + 44, r: 3.8 },
    { x: cx - 28, y: cy - 42, r: 2.6 },
    { x: cx + 74, y: cy + 28, r: 2.1 },
    { x: cx - 68, y: cy + 46, r: 1.9 }
  ];

  for (let c of crumbs) {
    let cPts = [
      [c.x - c.r, c.y - c.r * 0.4],
      [c.x + c.r * 0.3, c.y - c.r],
      [c.x + c.r, c.y + c.r * 0.2],
      [c.x - c.r * 0.2, c.y + c.r * 0.9]
    ];
    // Tiny crisp cast shadow under each wax crumb
    washPoly(cPts.map(p => [p[0] + 1.8, p[1] + 2.4]), PAL.waxDeep, 190);
    // Crimson wax body
    washPoly(cPts, PAL.waxBase, 255);
    // Bright chalky fracture facet on top-left of crumb
    brush.set("filigree", PAL.waxSpec, 0.65);
    brush.line(cPts[0][0], cPts[0][1], cPts[1][0], cPts[1][1]);
  }
}

// ============================================================================
// 7. FINAL TROMPE-L'OEIL GLAZES & GILT HIGHLIGHTS
// ============================================================================

function drawFinalTrompeLoeilTouches() {
  // Subtle gilt shimmer catching the most prominent scalloped edges on the upper-left of the lace
  push();
  translate(600, 605);
  rotate(-4.5);

  const numLobes = 36;
  const rx = 435;
  const ry = 478;
  const lobeAmp = 24;

  // Focus gilt highlights where the directional light grazes the scalloped curves
  for (let l = 14; l <= 31; l++) {
    let aCenter = (l + 0.5) * (360 / numLobes);
    let aStart = l * (360 / numLobes) + 1.5;
    let aMid = aCenter;

    let p1 = getScallopOvalPoint(aStart, rx - 1.5, ry - 1.5, numLobes, lobeAmp);
    let p2 = getScallopOvalPoint(aMid, rx - 1.5, ry - 1.5, numLobes, lobeAmp);

    brush.set("filigree", PAL.giltPale, 0.72);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
  pop();

  // Tiny collector's pin-prick or Trompe-l'oeil highlight on the lifted corner of the letter
  // to heighten the illusion of 3D projection from the picture plane
  push();
  translate(605, 590);
  rotate(6.2);
  brush.set("filigree", PAL.lacePure, 0.92);
  brush.line(-231, -163, 2, -14);
  brush.line(2, -14, 34, -16);
  pop();
}

