// ============================================================================
// GEOMETRY INITIALIZATION
// ============================================================================

function initTrayDents() {
  dents = [
    { x: 340, y: 58, dx: 0, dy: 16, radius: 75 },
    { x: 820, y: 58, dx: 0, dy: -11, radius: 60 },
    { x: 1142, y: 290, dx: -17, dy: 4, radius: 80 },
    { x: 1142, y: 870, dx: 12, dy: 0, radius: 65 },
    { x: 760, y: 1142, dx: 0, dy: -15, radius: 85 },
    { x: 250, y: 1142, dx: 0, dy: 12, radius: 70 },
    { x: 58, y: 680, dx: 15, dy: -3, radius: 78 },
    { x: 58, y: 210, dx: -10, dy: 6, radius: 55 }
  ];
}

function warpTrayPoint(x, y) {
  let ox = 0;
  let oy = 0;
  for (let i = 0; i < dents.length; i++) {
    let d = dents[i];
    let distSq = (x - d.x) * (x - d.x) + (y - d.y) * (y - d.y);
    let rSq = d.radius * d.radius;
    if (distSq < rSq * 2.5) {
      let w = exp(-distSq / (rSq * 0.65));
      ox += d.dx * w;
      oy += d.dy * w;
    }
  }
  // Subtle hand-forged waviness
  ox += (noise(x * 0.008, y * 0.008, 10) - 0.5) * 4.5;
  oy += (noise(x * 0.008, y * 0.008, 20) - 0.5) * 4.5;
  return [x + ox, y + oy];
}

function initRollsGeometry() {
  rolls = [];
  let gridN = 4;
  let margin = 136;
  let span = 1200 - margin * 2;
  let step = span / gridN;

  // Create 4x4 centers with organic baking squish offsets
  for (let row = 0; row < gridN; row++) {
    for (let col = 0; col < gridN; col++) {
      let idx = row * gridN + col;
      let cx = margin + (col + 0.5) * step + random(-11, 11);
      let cy = margin + (row + 0.5) * step + random(-11, 11);
      let dir = (row + col) % 2 === 0 ? 1 : -1;
      if (random() < 0.25) dir *= -1;

      // Distance from tray center controls degree of oven browning
      let distFromCenter = dist(cx, cy, 600, 600) / 500;

      rolls.push({
        idx,
        row,
        col,
        cx,
        cy,
        dir,
        startAngle: random(0, 360),
        turns: random(4.35, 4.95),
        coreRadius: random(11, 15.5),
        eccentricity: random(0.05, 0.14),
        eccAngle: random(0, 180),
        bakeToast: constrain(distFromCenter * 0.85 + random(-0.1, 0.15), 0, 1),
        rBound: [],
        rAvg: 112
      });
    }
  }

  // Compute exact Voronoi + tray wall boundary for each roll across 72 angles
  let trayMin = 128;
  let trayMax = 1072;
  let cornerRad = 72;

  for (let i = 0; i < rolls.length; i++) {
    let rA = rolls[i];
    let rawBound = [];

    for (let a = 0; a < 72; a++) {
      let ang = a * 5;
      let ux = cos(ang);
      let uy = sin(ang);
      let maxD = 220;

      // Distance to inner baking tray walls
      if (ux > 0.001) maxD = min(maxD, (trayMax - rA.cx) / ux);
      if (ux < -0.001) maxD = min(maxD, (trayMin - rA.cx) / ux);
      if (uy > 0.001) maxD = min(maxD, (trayMax - rA.cy) / uy);
      if (uy < -0.001) maxD = min(maxD, (trayMin - rA.cy) / uy);

      // Rounded tray corners constraint
      let testX = rA.cx + ux * maxD;
      let testY = rA.cy + uy * maxD;
      let corners = [
        [trayMin + cornerRad, trayMin + cornerRad, -1, -1],
        [trayMax - cornerRad, trayMin + cornerRad, 1, -1],
        [trayMax - cornerRad, trayMax - cornerRad, 1, 1],
        [trayMin + cornerRad, trayMax - cornerRad, -1, 1]
      ];
      for (let c = 0; c < corners.length; c++) {
        let [ccx, ccy, sx, sy] = corners[c];
        if ((testX - ccx) * sx > 0 && (testY - ccy) * sy > 0) {
          maxD *= 0.9;
        }
      }

      // Half-plane distance to every neighboring roll
      for (let j = 0; j < rolls.length; j++) {
        if (i === j) continue;
        let rB = rolls[j];
        let vx = rB.cx - rA.cx;
        let vy = rB.cy - rA.cy;
        let vLenSq = vx * vx + vy * vy;
        let dot = vx * ux + vy * uy;
        if (dot > 0) {
          let dPlane = (0.5 * vLenSq) / dot;
          if (dPlane < maxD) maxD = dPlane;
        }
      }

      // Slight inset for caramelized cinnamon crevice between rolls
      rawBound.push(maxD * 0.975);
    }

    // Smooth boundary over angular neighborhood for pillowy baked squish
    let sumR = 0;
    for (let a = 0; a < 72; a++) {
      let s = 0;
      let wSum = 0;
      for (let k = -4; k <= 4; k++) {
        let idx = (a + k + 72) % 72;
        let w = 5 - abs(k);
        s += rawBound[idx] * w;
        wSum += w;
      }
      let val = s / wSum;
      rA.rBound.push(val);
      sumR += val;
    }
    rA.rAvg = sumR / 72;
  }
}

// Interpolate boundary radius for roll at any angle in degrees
function getRollBoundary(roll, angleDeg) {
  let a = ((angleDeg % 360) + 360) % 360;
  let fIdx = a / 5;
  let i0 = floor(fIdx) % 72;
  let i1 = (i0 + 1) % 72;
  let frac = fIdx - floor(fIdx);
  return lerp(roll.rBound[i0], roll.rBound[i1], frac);
}

// Compute exact spiral outer radius at turn parameter t in [0, roll.turns]
function getSpiralRadius(roll, t) {
  let clampedT = constrain(t, 0, roll.turns);
  let f = clampedT / roll.turns;
  let ang = roll.startAngle + roll.dir * clampedT * 360;
  let rBound = getRollBoundary(roll, ang);

  // Inner turns are circular/elliptical quilled coils; outer turns squish into Voronoi polygon
  let ovalMod = 1 + roll.eccentricity * (1 - f * 0.7) * cos(2 * (ang - roll.eccAngle));
  let rCircle = (roll.coreRadius + f * (roll.rAvg * 0.92 - roll.coreRadius)) * ovalMod;
  let rPoly = roll.coreRadius + f * (rBound - roll.coreRadius);

  let squishFactor = pow(f, 1.65);
  let r = lerp(rCircle, rPoly, squishFactor);

  // Subtle organic hand-quilled wobble
  let wob = (noise(roll.idx * 17 + cos(ang) * 1.4, sin(ang) * 1.4, clampedT * 0.35) - 0.5) * 4.2 * f;
  return r + wob;
}

// Get [x, y] on a roll at turn parameter t and fractional offset within the turn
// fracInTurn: 0 = inner coil boundary (t-1), 1 = outer coil boundary (t)
function getRollPoint(roll, t, fracInTurn = 1.0) {
  let ang = roll.startAngle + roll.dir * t * 360;
  let rOut = getSpiralRadius(roll, t);
  let rIn = t >= 1.0 ? getSpiralRadius(roll, t - 1.0) : roll.coreRadius * (t * 0.35);
  let r = lerp(rIn, rOut, fracInTurn);
  return [roll.cx + cos(ang) * r, roll.cy + sin(ang) * r, rOut - rIn, ang];
}

// ============================================================================
// DRAWING HELPERS
// ============================================================================

function filterDistinctPts(pts, minDist = 1.2) {
  if (!pts || pts.length === 0) return [];
  let out = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = out[out.length - 1];
    let dx = pts[i][0] - prev[0];
    let dy = pts[i][1] - prev[1];
    if (dx * dx + dy * dy >= minDist * minDist) {
      out.push(pts[i]);
    }
  }
  if (out.length > 2) {
    let first = out[0];
    let last = out[out.length - 1];
    if (dist(first[0], first[1], last[0], last[1]) < minDist) {
      out.pop();
    }
  }
  return out;
}

function drawFilledPoly(pts, curvature = 0.12) {
  let clean = filterDistinctPts(pts, 1.5);
  if (clean.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < clean.length; i++) {
    brush.vertex(clean[i][0], clean[i][1]);
  }
  brush.endShape(true);
}

function safeSpline(pts, curvature = 0.45) {
  let clean = filterDistinctPts(pts, 1.0);
  if (clean.length < 2) return;
  if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  } else {
    brush.spline(clean, curvature);
  }
}

// ============================================================================
// 1. COUNTERTOP & DENTED BAKING TRAY
// ============================================================================

function sampleRoundedRect(x1, y1, x2, y2, cornerR, stepsPerSide = 20, applyWarp = true) {
  let pts = [];
  let cx1 = x1 + cornerR;
  let cy1 = y1 + cornerR;
  let cx2 = x2 - cornerR;
  let cy2 = y2 - cornerR;

  // Top edge
  for (let i = 0; i <= stepsPerSide; i++) {
    pts.push([lerp(cx1, cx2, i / stepsPerSide), y1]);
  }
  // Top-right corner
  for (let i = 1; i < 8; i++) {
    let a = -90 + (i / 8) * 90;
    pts.push([cx2 + cos(a) * cornerR, cy1 + sin(a) * cornerR]);
  }
  // Right edge
  for (let i = 0; i <= stepsPerSide; i++) {
    pts.push([x2, lerp(cy1, cy2, i / stepsPerSide)]);
  }
  // Bottom-right corner
  for (let i = 1; i < 8; i++) {
    let a = 0 + (i / 8) * 90;
    pts.push([cx2 + cos(a) * cornerR, cy2 + sin(a) * cornerR]);
  }
  // Bottom edge
  for (let i = 0; i <= stepsPerSide; i++) {
    pts.push([lerp(cx2, cx1, i / stepsPerSide), y2]);
  }
  // Bottom-left corner
  for (let i = 1; i < 8; i++) {
    let a = 90 + (i / 8) * 90;
    pts.push([cx1 + cos(a) * cornerR, cy2 + sin(a) * cornerR]);
  }
  // Left edge
  for (let i = 0; i <= stepsPerSide; i++) {
    pts.push([x1, lerp(cy2, cy1, i / stepsPerSide)]);
  }
  // Top-left corner
  for (let i = 1; i < 8; i++) {
    let a = 180 + (i / 8) * 90;
    pts.push([cx1 + cos(a) * cornerR, cy1 + sin(a) * cornerR]);
  }

  if (applyWarp) {
    return pts.map((p) => warpTrayPoint(p[0], p[1]));
  }
  return pts;
}

function drawCounterAndTray() {
  // Subtle dark wood/stone grain around outer margin
  brush.noFill();
  brush.noWash();
  brush.set("charcoal", "#171412", 1.2);
  for (let i = 0; i < 45; i++) {
    let y = random(8, 1192);
    if (y > 70 && y < 1130) {
      brush.line(8, y, 65, y + random(-4, 4));
      brush.line(1135, y, 1192, y + random(-4, 4));
    } else {
      brush.line(8, y, 1192, y + random(-8, 8));
    }
  }

  // Drop shadow of tray on countertop
  let shadowPts = sampleRoundedRect(54, 56, 1154, 1156, 52, 18, true);
  brush.noStroke();
  brush.wash("#120f0d", 180);
  drawFilledPoly(shadowPts, 0.15);

  // Outer metallic tray base
  let outerTray = sampleRoundedRect(52, 52, 1148, 1148, 48, 22, true);
  brush.wash(PALETTE.trayMid, 240);
  brush.fill(PALETTE.trayDark, 110);
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.65, 0.5);
  drawFilledPoly(outerTray, 0.15);
  brush.noFill();
  brush.noWash();

  // Raised rim bevel rings
  let rimMid = sampleRoundedRect(68, 68, 1132, 1132, 42, 22, true);
  let rimInner = sampleRoundedRect(102, 102, 1098, 1098, 34, 22, true);

  // Baked-on oil patina patches along the tray rim
  brush.noStroke();
  brush.fill(PALETTE.trayPatina, 115);
  brush.fillBleed(0.25, "out");
  brush.fillTexture(0.75, 0.6);
  for (let i = 0; i < 18; i++) {
    let idx = floor(random(outerTray.length));
    let p1 = outerTray[idx];
    let p2 = rimInner[idx];
    let cx = lerp(p1[0], p2[0], 0.5) + random(-8, 8);
    let cy = lerp(p1[1], p2[1], 0.5) + random(-8, 8);
    let rad = random(16, 38);
    let patch = [];
    for (let a = 0; a < 8; a++) {
      let ang = a * 45;
      let r = rad * random(0.6, 1.25);
      patch.push([cx + cos(ang) * r, cy + sin(ang) * r]);
    }
    drawFilledPoly(patch, 0.3);
  }
  brush.noFill();

  // Metallic rim contour strokes & dent bevel highlights
  brush.set("2B", PALETTE.trayDark, 1.3);
  safeSpline([...outerTray, outerTray[0]], 0.3);
  brush.set("HB", "#332f2b", 1.1);
  safeSpline([...rimInner, rimInner[0]], 0.3);

  brush.set("cpencil", PALETTE.trayLight, 0.9);
  safeSpline(rimMid.slice(0, floor(rimMid.length * 0.55)), 0.3);

  // Highlight and shadow creases around the physical dents
  for (let i = 0; i < dents.length; i++) {
    let d = dents[i];
    brush.set("cpencil", PALETTE.trayHighlight, 0.85);
    for (let s = -3; s <= 3; s++) {
      let ang = atan2(d.dy, d.dx) + 90;
      let bx = d.x + cos(ang) * s * 11;
      let by = d.y + sin(ang) * s * 11;
      let pA = warpTrayPoint(bx - d.dx * 0.6, by - d.dy * 0.6);
      let pB = warpTrayPoint(bx + d.dx * 1.1, by + d.dy * 1.1);
      brush.line(pA[0], pA[1], pB[0], pB[1]);
    }
    // Scratches on dented metal lip
    brush.set("fineHair", "#cfc8be", 0.75);
    for (let k = 0; k < 5; k++) {
      let sx = d.x + random(-30, 30);
      let sy = d.y + random(-30, 30);
      let pS = warpTrayPoint(sx, sy);
      let a = random(0, 180);
      brush.line(pS[0] - cos(a) * 10, pS[1] - sin(a) * 10, pS[0] + cos(a) * 10, pS[1] + sin(a) * 10);
    }
  }
}

// ============================================================================
// 2. BUCKLED PARCHMENT PAPER AT EDGES & CORNERS
// ============================================================================

let parchmentTips = [];

function drawBuckledParchment() {
  let innerLoop = sampleRoundedRect(138, 138, 1062, 1062, 28, 14, false);
  let midLoop = [];
  let outerLoop = [];
  let n = innerLoop.length;

  for (let i = 0; i < n; i++) {
    let pIn = innerLoop[i];
    let vx = pIn[0] - 600;
    let vy = pIn[1] - 600;
    let len = sqrt(vx * vx + vy * vy) || 1;
    let ux = vx / len;
    let uy = vy / len;

    // Corner flare: parchment juts out dramatically at the 4 corners
    let cornerFactor = pow(abs(ux * uy) * 2.0, 1.4);
    let pleat = (i % 2 === 0 ? 1 : -1) * random(9, 19);

    let midDist = 32 + cornerFactor * 26 + pleat * 0.65;
    let outDist = 56 + cornerFactor * 52 + pleat;

    // Tangential buckle shift
    let tx = -uy * pleat * 0.45;
    let ty = ux * pleat * 0.45;

    midLoop.push([pIn[0] + ux * midDist + tx * 0.5, pIn[1] + uy * midDist + ty * 0.5]);
    outerLoop.push([pIn[0] + ux * outDist + tx, pIn[1] + uy * outDist + ty]);
  }

  // Group parchment facets by tone according to facet normal relative to top-left light
  let buckets = {
    light: [],
    mid: [],
    toast: [],
    scorch: []
  };
  let creaseLines = [];
  let ridgeHighlights = [];

  for (let i = 0; i < n; i++) {
    let ni = (i + 1) % n;
    let q1 = [innerLoop[i], midLoop[i], midLoop[ni], innerLoop[ni]];
    let q2 = [midLoop[i], outerLoop[i], outerLoop[ni], midLoop[ni]];

    // Determine tilt orientation from perimeter index & accordion parity
    let edgeAng = atan2(outerLoop[ni][1] - outerLoop[i][1], outerLoop[ni][0] - outerLoop[i][0]);
    let shade = sin(edgeAng + (i % 2 === 0 ? 38 : -38));

    // Corner facets get extra oven toasting
    let cx = (outerLoop[i][0] + outerLoop[ni][0]) * 0.5;
    let cy = (outerLoop[i][1] + outerLoop[ni][1]) * 0.5;
    let isCorner = dist(cx, cy, 600, 600) > 560;

    if (isCorner && i % 2 === 1) {
      buckets.scorch.push(q2);
      buckets.toast.push(q1);
    } else if (shade > 0.25) {
      buckets.light.push(q1, q2);
    } else if (shade > -0.2) {
      buckets.mid.push(q1);
      buckets.light.push(q2);
    } else {
      buckets.toast.push(q1, q2);
    }

    creaseLines.push([innerLoop[i], midLoop[i], outerLoop[i]]);
    if (i % 2 === 0) {
      ridgeHighlights.push([innerLoop[i], midLoop[i], outerLoop[i]]);
    }

    // Save extreme corner tips to redraw over outer rolls for realism
    if (dist(outerLoop[i][0], outerLoop[i][1], 600, 600) > 590 && i % 2 === 0) {
      parchmentTips.push([midLoop[(i - 1 + n) % n], outerLoop[i], midLoop[ni]]);
    }
  }

  // Batch render parchment watercolor facets
  const renderBucket = (polys, col, washAlpha, fillAlpha, bleed) => {
    brush.noStroke();
    brush.wash(col, washAlpha);
    brush.fill(col, fillAlpha);
    brush.fillBleed(bleed, "out");
    brush.fillTexture(0.55, 0.45);
    for (let i = 0; i < polys.length; i++) {
      drawFilledPoly(polys[i], 0.04);
    }
    brush.noFill();
    brush.noWash();
  };

  renderBucket(buckets.light, PALETTE.parchmentLight, 195, 110, 0.08);
  renderBucket(buckets.mid, PALETTE.parchmentMid, 195, 115, 0.1);
  renderBucket(buckets.toast, PALETTE.parchmentToast, 190, 125, 0.12);
  renderBucket(buckets.scorch, PALETTE.parchmentScorch, 185, 135, 0.15);

  // Crisp paper buckle creases & outer edge line
  brush.set("fineHair", "#6e5032", 0.9);
  for (let i = 0; i < creaseLines.length; i++) {
    safeSpline(creaseLines[i], 0.15);
  }
  brush.set("quillPen", "#593e23", 0.85);
  safeSpline([...outerLoop, outerLoop[0]], 0.12);

  brush.set("cpencil", "#f7efe0", 0.95);
  for (let i = 0; i < ridgeHighlights.length; i++) {
    safeSpline(ridgeHighlights[i], 0.15);
  }
}

