  burntCrustZones = [
    { x: 142, y: 142, r: 58, isCorner: true },
    { x: 1058, y: 142, r: 62, isCorner: true },
    { x: 1058, y: 1058, r: 60, isCorner: true },
    { x: 142, y: 1058, r: 56, isCorner: true },
    { x: 375, y: 132, r: 34, isCorner: false },
    { x: 830, y: 132, r: 30, isCorner: false },
    { x: 1068, y: 600, r: 36, isCorner: false },
    { x: 600, y: 1068, r: 35, isCorner: false },
    { x: 132, y: 375, r: 32, isCorner: false },
    { x: 132, y: 830, r: 30, isCorner: false }
  ];

  let amberPuddles = [];
