// ============================================================================
// 5. GRADED WATERCOLOR WASHES ON ROLL SPIRAL STRIPS (COLOR-BATCHED)
// ============================================================================

// Helper to build a curved spiral ribbon polygon from t0 to t1 between fIn and fOut
function buildRibbonPolygon(roll, t0, t1, fIn, fOut, steps = 9) {
  let outerPts = [];
  let innerPts = [];
  for (let i = 0; i <= steps; i++) {
    let t = lerp(t0, t1, i / steps);
    let pOut = getRollPoint(roll, t, fOut);
    let pIn = getRollPoint(roll, t, fIn);
    outerPts.push([pOut[0], pOut[1]]);
    innerPts.push([pIn[0], pIn[1]]);
  }
  innerPts.reverse();
  return [...outerPts, ...innerPts];
}

function drawAllRollsWatercolorWashes() {
  let washBatches = {
    butterPale: [],
    butterWarm: [],
    butterToast: [],
    caramelGold: [],
    caramelWarm: [],
    caramelDeep: [],
    nutmegCrevice: []
  };

  // Segment each roll's spiral into half-turn curved ribbons
  let segLen = 0.52;

  for (let i = 0; i < rolls.length; i++) {
    let roll = rolls[i];

    // Central core dough bud
    let corePoly = [];
    for (let a = 0; a < 10; a++) {
      let ang = a * 36;
      let r = roll.coreRadius * 0.92;
      corePoly.push([roll.cx + cos(ang) * r, roll.cy + sin(ang) * r]);
    }
    washBatches.butterPale.push(corePoly);

    for (let t = 0.25; t < roll.turns; t += segLen) {
      let tNext = min(roll.turns, t + segLen + 0.03);
      let fNorm = t / roll.turns;
      let steps = 8;

      // 1. Main dough ribbon base (pale butter in center, toasted butter near outer rim)
      let doughPoly = buildRibbonPolygon(roll, t, tNext, 0.18, 0.98, steps);
      let toastScore = fNorm * 0.65 + roll.bakeToast * 0.45 + random(-0.08, 0.08);
      if (toastScore < 0.42) {
        washBatches.butterPale.push(doughPoly);
      } else if (toastScore < 0.72) {
        washBatches.butterWarm.push(doughPoly);
      } else {
        washBatches.butterToast.push(doughPoly);
      }

      // 2. Graded watercolor wash on inner edge of strip (caramel & nutmeg bleed)
      let innerEdgeWash = buildRibbonPolygon(roll, t, tNext, 0.16, 0.55, steps);
      if (fNorm < 0.45) {
        washBatches.caramelGold.push(innerEdgeWash);
      } else {
        washBatches.caramelWarm.push(innerEdgeWash);
      }

      // 3. Graded watercolor wash on outer edge of strip
      let outerEdgeWash = buildRibbonPolygon(roll, t, tNext, 0.74, 1.0, steps);
      if (toastScore > 0.6) {
        washBatches.caramelDeep.push(outerEdgeWash);
      } else {
        washBatches.caramelGold.push(outerEdgeWash);
      }

      // 4. Recessed cinnamon-nutmeg channel between dough turns
      let crevicePoly = buildRibbonPolygon(roll, t, tNext, 0.0, 0.24, steps);
      washBatches.nutmegCrevice.push(crevicePoly);
    }
  }

  // Execute batched watercolor fills from base dough tones to dark spiced edge washes
  const flushBatch = (polys, col, washOp, fillOp, bleed, dir, tex, border) => {
    brush.noStroke();
    if (washOp > 0) brush.wash(col, washOp);
    brush.fill(col, fillOp);
    brush.fillBleed(bleed, dir);
    brush.fillTexture(tex, border);
    for (let i = 0; i < polys.length; i++) {
      drawFilledPoly(polys[i], 0.18);
    }
    brush.noFill();
    brush.noWash();
  };

  // Base dough layers
  flushBatch(washBatches.butterPale, PALETTE.butterPale, 175, 95, 0.08, "in", 0.42, 0.35);
  flushBatch(washBatches.butterWarm, PALETTE.butterWarm, 175, 100, 0.08, "in", 0.45, 0.38);
  flushBatch(washBatches.butterToast, PALETTE.butterToast, 170, 105, 0.1, "in", 0.48, 0.42);

  // Graded edge watercolor washes (translucent, bleeding softly into the pale butter)
  flushBatch(washBatches.caramelGold, PALETTE.caramelGold, 0, 82, 0.18, "out", 0.58, 0.48);
  flushBatch(washBatches.caramelWarm, PALETTE.caramelWarm, 0, 88, 0.2, "out", 0.62, 0.52);
  flushBatch(washBatches.caramelDeep, PALETTE.caramelDeep, 0, 92, 0.18, "out", 0.65, 0.55);

  // Deep cinnamon-nutmeg spiral channel wash
  flushBatch(washBatches.nutmegCrevice, PALETTE.nutmegDark, 140, 115, 0.14, "out", 0.72, 0.65);
}

// ============================================================================
// 6. PAPER-QUILLING COILED RIBBONS, FINE BROWN PEN EDGING & SPICE DUST
// ============================================================================

function drawAllRollsQuillingAndPen() {
  for (let i = 0; i < rolls.length; i++) {
    drawSingleRollQuilling(rolls[i]);
  }
}

function drawSingleRollQuilling(roll) {
  let dt = 1 / 28; // ~13 degrees per sample step

  // Collect continuous spiral paths for graded edge shading, quilled sub-strips, and pen edges
  let creviceCenter = [];
  let doughInnerEdge = [];
  let quillSub1 = [];
  let quillSub2 = [];
  let doughCrown = [];
  let doughOuterEdge = [];

  for (let t = 0.15; t <= roll.turns; t += dt) {
    // Organic paper-quilling pinch modulation along the strip
    let pinch1 = 0.44 + 0.06 * sin(t * 360 * 2.0 + roll.idx * 45);
    let pinch2 = 0.72 + 0.055 * cos(t * 360 * 2.0 + roll.idx * 30);

    let pCrev = getRollPoint(roll, t, 0.1);
    let pIn = getRollPoint(roll, t, 0.2);
    let pS1 = getRollPoint(roll, t, pinch1);
    let pS2 = getRollPoint(roll, t, pinch2);
    let pCrown = getRollPoint(roll, t, 0.58);
    let pOut = getRollPoint(roll, t, 0.97);

    creviceCenter.push([pCrev[0], pCrev[1]]);
    doughInnerEdge.push([pIn[0], pIn[1]]);
    quillSub1.push([pS1[0], pS1[1]]);
    quillSub2.push([pS2[0], pS2[1]]);
    doughCrown.push([pCrown[0], pCrown[1]]);
    doughOuterEdge.push([pOut[0], pOut[1]]);
  }

  // A. Continuous graded edge shading strokes (deepening the watercolor edge effect)
  brush.set("stripShade", PALETTE.caramelDeep, 1.35);
  safeSpline(doughInnerEdge, 0.45);
  brush.set("stripShade", PALETTE.caramelWarm, 1.0);
  safeSpline(quillSub1, 0.45);
  safeSpline(doughOuterEdge, 0.45);

  // Lit pale-butter crown along the middle of each coiled ribbon
  brush.set("stripShade", PALETTE.butterHighlight, 1.15);
  safeSpline(doughCrown, 0.45);

  // B. Paper-quilling crescent loops & fluted cells in the wide corner swells
  // Where the spiral crosses the 4 diagonal corners of its Voronoi cell, the strip widens
  brush.set("fineHair", PALETTE.penLight, 0.9);
  for (let t = 1.15; t < roll.turns - 0.1; t += 0.09) {
    let pTest = getRollPoint(roll, t, 0.5);
    let stripW = pTest[2];
    if (stripW > 22) {
      // Draw a tight quilled paper crescent / crimped loop inside the sub-strip
      let loopPts = [];
      for (let a = 0; a <= 8; a++) {
        let ang = (a / 8) * 360;
        let tLoc = t + cos(ang) * 0.036;
        let fLoc = 0.58 + sin(ang) * 0.18;
        let pL = getRollPoint(roll, tLoc, fLoc);
        loopPts.push([pL[0], pL[1]]);
      }
      safeSpline(loopPts, 0.55);
    }
  }

  // C. Fine cross-contour paper-edge striations across the cinnamon crevice
  brush.set("fineHair", PALETTE.penDark, 0.85);
  for (let t = 0.3; t < roll.turns; t += 0.055) {
    let p1 = getRollPoint(roll, t, 0.02);
    let p2 = getRollPoint(roll, t + 0.015, 0.23);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // D. Deep dark espresso pen along the recessed cinnamon-nutmeg channel
  brush.set("2B", PALETTE.creviceDeep, 1.15);
  safeSpline(creviceCenter, 0.45);

  // E. Crisp fine brown pen edging on every coiled ribbon and internal quilling strip
  // Internal laminated paper-quilling strip dividers
  brush.set("fineHair", PALETTE.penMid, 0.95);
  safeSpline(quillSub1, 0.45);
  brush.set("fineHair", PALETTE.penLight, 0.85);
  safeSpline(quillSub2, 0.45);

  // Primary inner & outer dough ribbon edges in fine brown pen
  brush.set("quillPen", PALETTE.penDark, 1.05);
  safeSpline(doughInnerEdge, 0.45);
  brush.set("quillPen", PALETTE.penMid, 0.95);
  safeSpline(doughOuterEdge, 0.45);

  // Crisp pale-butter paper edge rim highlight right beside the brown pen line
  brush.set("fineHair", PALETTE.butterHighlight, 0.85);
  let rimHighlight = [];
  for (let t = 0.25; t <= roll.turns; t += dt * 1.5) {
    let pH = getRollPoint(roll, t, 0.26);
    rimHighlight.push([pH[0], pH[1]]);
  }
  safeSpline(rimHighlight, 0.45);

  // F. Tight paper-quilled center eye scroll at the heart of the roll
  brush.set("quillPen", PALETTE.penDark, 0.95);
  for (let c = 0; c < 3; c++) {
    let eyePts = [];
    let rScale = map(c, 0, 2, 0.85, 0.28);
    for (let a = 0; a <= 12; a++) {
      let ang = roll.startAngle + roll.dir * a * 38;
      let r = roll.coreRadius * rScale * (1 - a * 0.055);
      eyePts.push([roll.cx + cos(ang) * r, roll.cy + sin(ang) * r]);
    }
    safeSpline(eyePts, 0.5);
  }

  // Tucked outer dough tail where the cinnamon roll ribbon ends
  let tailPts = [];
  for (let s = 0; s <= 8; s++) {
    let u = s / 8;
    let tTail = roll.turns - 0.18 + u * 0.18;
    let fTail = lerp(0.97, 0.15, pow(u, 1.5));
    let pT = getRollPoint(roll, tTail, fTail);
    tailPts.push([pT[0], pT[1]]);
  }
  brush.set("quillPen", PALETTE.penDark, 1.1);
  safeSpline(tailPts, 0.4);

  // G. Ground nutmeg & toasted cinnamon sugar granules dusted along the spiral seams
  brush.set("spiceSpray", PALETTE.nutmegDark, 0.95);
  for (let t = 0.4; t < roll.turns; t += 0.22) {
    let pS = getRollPoint(roll, t, 0.22);
    brush.line(pS[0] - 2, pS[1] - 2, pS[0] + 2, pS[1] + 2);
  }
  brush.set("spiceSpray", PALETTE.caramelDeep, 0.8);
  for (let t = 0.6; t < roll.turns; t += 0.28) {
    let pS = getRollPoint(roll, t, 0.82);
    brush.line(pS[0] - 2, pS[1] - 2, pS[0] + 2, pS[1] + 2);
  }
}

// ============================================================================
// 7. TRANSLUCENT GLOSSY SUGAR GLAZE DRIPS & SHARP SPECULAR HIGHLIGHTS
// ============================================================================

function drawSugarGlazeAndHighlights() {
  let veilPolys = [];
  let corePolys = [];
  let shadowArcs = [];
  let meniscusArcs = [];
  let specularArcs = [];
  let specularBeads = [];

  // Part A: Central glaze pools with viscous radial drip lobes on each roll
  for (let i = 0; i < rolls.length; i++) {
    let roll = rolls[i];
    let numLobes = floor(random(5, 8));
    let baseAng = random(0, 360);
    let lobes = [];

    for (let l = 0; l < numLobes; l++) {
      let lAng = baseAng + (l / numLobes) * 360 + random(-16, 16);
      let lLen = random(42, 96);
      let lWidth = random(11, 20);
      lobes.push({ ang: lAng, len: lLen, width: lWidth });
    }

    // Build smooth polar contour around the central pool and its radial drip fingers
    let poolOuter = [];
    let poolInner = [];
    let steps = 64;
    let poolBaseR = random(18, 28);

    for (let s = 0; s < steps; s++) {
      let ang = (s / steps) * 360;
      let r = poolBaseR + (noise(roll.idx * 10 + cos(ang), sin(ang)) - 0.5) * 8;

      for (let l = 0; l < lobes.length; l++) {
        let lb = lobes[l];
        let dAng = abs(((ang - lb.ang + 540) % 360) - 180);
        let halfSpan = lb.width * 1.15;
        if (dAng < halfSpan) {
          let profile = pow(cos((dAng / halfSpan) * 90), 1.4);
          // Slight bulbous drip tip swell
          r = max(r, poolBaseR * 0.7 + lb.len * profile);
        }
      }

      let px = roll.cx + cos(ang) * r;
      let py = roll.cy + sin(ang) * r;
      poolOuter.push([px, py]);
      poolInner.push([roll.cx + cos(ang) * (r * 0.66), roll.cy + sin(ang) * (r * 0.66)]);
    }

    veilPolys.push(poolOuter);
    corePolys.push(poolInner);

    // Lower-right wet contact shadow & meniscus arcs
    let shadPts = [];
    for (let s = 2; s <= 30; s++) {
      let p = poolOuter[s % steps];
      shadPts.push([p[0] + 2.2, p[1] + 2.6]);
    }
    shadowArcs.push(shadPts);
    meniscusArcs.push(poolOuter);

    // Compute sharp specular highlights crowning over each underlying dough coil along every lobe
    for (let l = 0; l < lobes.length; l++) {
      let lb = lobes[l];
      let ux = cos(lb.ang);
      let uy = sin(lb.ang);
      let nx = -uy;
      let ny = ux;

      // Specular ridges where the glaze lobe steps across spiral rings
      for (let d = 18; d < lb.len - 8; d += 21) {
        let hx = roll.cx + ux * d - 1.5;
        let hy = roll.cy + uy * d - 1.5;
        let w = lb.width * 0.34 * (1 - (d / lb.len) * 0.35);
        specularArcs.push([
          [hx - nx * w, hy - ny * w],
          [hx + ux * 3.5, hy + uy * 3.5],
          [hx + nx * w, hy + ny * w]
        ]);
      }

      // Bright crescent specular catchlight on the bulbous tip of each drip lobe
      let tipD = lb.len - 6;
      let tx = roll.cx + ux * tipD - 1.5;
      let ty = roll.cy + uy * tipD - 1.5;
      let tw = lb.width * 0.28;
      specularArcs.push([
        [tx - nx * tw - ux * 2, ty - ny * tw - uy * 2],
        [tx + ux * 2.5, ty + uy * 2.5],
        [tx + nx * tw - ux * 2, ty + ny * tw - uy * 2]
      ]);
      specularBeads.push([tx - ux * 3, ty - uy * 3]);
    }
  }

  // Part B: Sweeping diagonal glaze drizzle ribbons bridging across the tray
  let drizzlePaths = [
    [[165, 230], [360, 290], [560, 240], [790, 310], [1010, 255]],
    [[185, 460], [410, 395], [650, 490], [880, 420], [1035, 510]],
    [[160, 690], [380, 745], [610, 665], [840, 755], [1030, 695]],
    [[195, 920], [430, 875], [685, 960], [925, 895], [1040, 955]],
    [[250, 175], [490, 480], [720, 740], [960, 1015]],
    [[960, 185], [710, 465], [470, 735], [230, 1005]],
    [[510, 170], [460, 520], [535, 860], [485, 1030]],
    [[740, 175], [790, 540], [715, 850], [765, 1025]]
  ];

  for (let d = 0; d < drizzlePaths.length; d++) {
    let anchors = drizzlePaths[d];
    let leftOuter = [];
    let rightOuter = [];
    let leftCore = [];
    let rightCore = [];
    let spineHighlight = [];
    let shadowLine = [];

    let totalSteps = 52;
    for (let s = 0; s <= totalSteps; s++) {
      let u = s / totalSteps;
      // Catmull-Rom / piecewise smooth interpolation along anchors
      let segF = u * (anchors.length - 1);
      let idx = min(anchors.length - 2, floor(segF));
      let f = segF - idx;
      let p0 = anchors[max(0, idx - 1)];
      let p1 = anchors[idx];
      let p2 = anchors[idx + 1];
      let p3 = anchors[min(anchors.length - 1, idx + 2)];

      let x =
        0.5 *
        (2 * p1[0] +
          (-p0[0] + p2[0]) * f +
          (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * f * f +
          (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * f * f * f);
      let y =
        0.5 *
        (2 * p1[1] +
          (-p0[1] + p2[1]) * f +
          (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * f * f +
          (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * f * f * f);

      // Organic viscous drip swell & pinch along the drizzle stream
      let dx = p2[0] - p1[0];
      let dy = p2[1] - p1[1];
      let len = sqrt(dx * dx + dy * dy) || 1;
      let nx = -dy / len;
      let ny = dx / len;

      let swell = sin(u * 180) * (7.5 + 5.5 * sin(u * 360 * 3.5 + d * 50));
      swell = max(2.8, swell);

      leftOuter.push([x + nx * swell, y + ny * swell]);
      rightOuter.push([x - nx * swell, y - ny * swell]);
      leftCore.push([x + nx * swell * 0.55, y + ny * swell * 0.55]);
      rightCore.push([x - nx * swell * 0.55, y - ny * swell * 0.55]);
      shadowLine.push([x - nx * swell + 2.0, y - ny * swell + 2.4]);

      if (s > 3 && s < totalSteps - 3) {
        spineHighlight.push([x + nx * swell * 0.28 - 1.2, y + ny * swell * 0.28 - 1.2]);
      }
    }

    rightOuter.reverse();
    rightCore.reverse();
    let ribbonOuter = [...leftOuter, ...rightOuter];
    let ribbonCore = [...leftCore, ...rightCore];

    veilPolys.push(ribbonOuter);
    corePolys.push(ribbonCore);
    shadowArcs.push(shadowLine);
    meniscusArcs.push(ribbonOuter);

    // Break spine specular into intermittent glossy segments stepping over dough ridges
    for (let k = 0; k < spineHighlight.length - 4; k += 6) {
      specularArcs.push(spineHighlight.slice(k, k + 4));
    }
  }

  // Part C: Render Glaze Layers in Order
  // 1. Subtle warm caramel contact shadows under glaze edges
  brush.set("stripShade", PALETTE.glazeShadow, 0.95);
  for (let i = 0; i < shadowArcs.length; i++) {
    safeSpline(shadowArcs[i], 0.4);
  }

  // 2. Translucent outer milky glaze veil (lets brown pen & caramel wash show through!)
  brush.noStroke();
  brush.wash(PALETTE.glazeVeil, 78);
  brush.fill(PALETTE.glazeVeil, 95);
  brush.fillBleed(0.05, "in");
  brush.fillTexture(0.22, 0.28);
  for (let i = 0; i < veilPolys.length; i++) {
    drawFilledPoly(veilPolys[i], 0.25);
  }
  brush.noFill();
  brush.noWash();

  // 3. Thicker milky-white inner glaze core
  brush.noStroke();
  brush.wash(PALETTE.glazeMilk, 92);
  brush.fill(PALETTE.glazeCore, 85);
  brush.fillBleed(0.04, "in");
  brush.fillTexture(0.15, 0.2);
  for (let i = 0; i < corePolys.length; i++) {
    drawFilledPoly(corePolys[i], 0.25);
  }
  brush.noFill();
  brush.noWash();

  // 4. Delicate meniscus rim contour on every glaze pool and ribbon
  brush.set("fineHair", "#dfd5c3", 0.85);
  for (let i = 0; i < meniscusArcs.length; i++) {
    safeSpline(meniscusArcs[i], 0.35);
  }

  // 5. Small satellite glaze pearls & droplets
  brush.noStroke();
  brush.wash(PALETTE.glazeMilk, 155);
  let pearlCoords = [];
  for (let i = 0; i < 42; i++) {
    let rIdx = floor(random(rolls.length));
    let rl = rolls[rIdx];
    let ang = random(0, 360);
    let distR = random(35, 95);
    let px = rl.cx + cos(ang) * distR;
    let py = rl.cy + sin(ang) * distR;
    let pr = random(3.5, 7.5);
    brush.circle(px, py, pr, 0.2);
    pearlCoords.push([px, py, pr]);
  }
  brush.noWash();

  // 6. Razor-sharp pure white specular highlights on glaze crests & drip bulbs
  brush.set("glazeBody", PALETTE.glazeCore, 1.0);
  for (let i = 0; i < specularArcs.length; i++) {
    safeSpline(specularArcs[i], 0.45);
  }

  brush.set("specularPen", PALETTE.specular, 1.15);
  for (let i = 0; i < specularArcs.length; i++) {
    safeSpline(specularArcs[i], 0.45);
  }

  // Pinpoint specular beads on drip tips and glaze pearls
  brush.set("rotring", PALETTE.specular, 1.35);
  for (let i = 0; i < specularBeads.length; i++) {
    let b = specularBeads[i];
    brush.line(b[0] - 1.2, b[1] - 0.8, b[0] + 1.2, b[1] + 0.8);
  }
  for (let i = 0; i < pearlCoords.length; i++) {
    let [px, py, pr] = pearlCoords[i];
    brush.line(px - pr * 0.35, py - pr * 0.35, px - pr * 0.1, py - pr * 0.45);
  }
}

// ============================================================================
// 8. FINAL BURNT SUGAR BUBBLES & OVERHANGING PARCHMENT TIPS
// ============================================================================

function drawFinalSurfaceAccents() {
  // Crystalline caramelized sugar blisters & glassy bubbles in the burnt corner crusts
  for (let i = 0; i < burntCrustZones.length; i++) {
    let z = burntCrustZones[i];
    let count = z.isCorner ? 18 : 9;

    for (let b = 0; b < count; b++) {
      let ang = random(0, 360);
      let d = random(4, z.r * 0.72);
      let bx = z.x + cos(ang) * d;
      let by = z.y + sin(ang) * d;
      let br = random(2.5, 7.5);

      brush.set("quillPen", PALETTE.burntBlack, 1.0);
      brush.arc(bx, by, br, 0, 360);

      // Tiny amber-glass specular rim on the blistered burnt sugar bubble
      brush.set("fineHair", "#d9a273", 0.9);
      brush.arc(bx, by, br * 0.78, 200, 315);
    }

    // Crusted burnt sugar granules
    brush.set("spiceSpray", PALETTE.burntBlack, 1.1);
    brush.line(z.x - 12, z.y - 12, z.x + 12, z.y + 12);
  }

  // Crisp overhanging corner tips of buckled parchment curling slightly inward
  for (let i = 0; i < parchmentTips.length; i++) {
    let tri = parchmentTips[i];
    brush.noStroke();
    brush.wash(PALETTE.parchmentToast, 190);
    brush.fill(PALETTE.parchmentScorch, 110);
    brush.fillBleed(0.1, "in");
    drawFilledPoly(tri, 0.04);
    brush.noFill();
    brush.noWash();

    brush.set("quillPen", "#593d22", 0.85);
    safeSpline([tri[0], tri[1], tri[2]], 0.08);
    brush.set("fineHair", PALETTE.butterHighlight, 0.8);
    brush.line(tri[0][0], tri[0][1], tri[1][0], tri[1][1]);
  }
}

