function draw() {
  translate(-width / 2, -height / 2);

  // 1. Render the cool grey toned paper ground
  drawCoolGreyGround();

  // 2. Define the 4x4 grid of sugar cubes and their individual deviations
  const cubes = buildCubeGridSpecs();

  // 3. Pass 1: Ground tea stains & short, soft cast shadows for all cubes
  for (let spec of cubes) {
    drawGroundStainAndShadow(spec);
  }

  // 4. Pass 2: Render each sugar cube (faces, tea stains, hatching, crystals, crumbs)
  for (let spec of cubes) {
    drawSugarCube(spec);
  }

  // 5. Pass 3: Render the lone ant on cube (row 2, col 1)
  const antCube = cubes[2 * 4 + 1];
  drawLoneAnt(antCube);

  // 6. Final subtle clinical framing & stray dust motes
  drawFinalSurfaceTouches();

  noLoop();
}

