      }

      specs.push({
        row: r,
        col: c,
        gx,
        gy,
        rot,
        R,
        H,
        chips,
        tea,
        crack,
        edgeNotch,
        extraCrumbs,
        seed: SEED + r * 137 + c * 31
      });
    }
  }

  return specs;
}

// Project local 3D point (x, y, z) on a cube to 2D canvas coordinates
// x in [-R, R] (back-left to front-right)
// y in [-R, R] (back-right to front-left)
// z in [0, H]  (ground to top face)
function projectPt(spec, x, y, z) {
  const aRight = spec.rot;        // ~23 deg down-right
  const aLeft = 45 - spec.rot;    // ~22 deg down-left
  const pitch = 0.88;
  const zScale = 0.74;

  const sx = spec.gx + x * cos(aRight) - y * cos(aLeft);
  const sy = spec.gy + (x * sin(aRight) + y * sin(aLeft)) * pitch - z * zScale;
  return [sx, sy];
}

// Compute the shadow projection on ground (z = 0) for a 3D point (x, y, z)
// Lit from upper-left: shadow falls short and soft toward lower-right (+X, +Y)
function projectShadowPt(spec, x, y, z) {
  const base = projectPt(spec, x, y, 0);
  return [
    base[0] + z * 0.45,
    base[1] + z * 0.29
  ];
}

// Perturb a polygon's vertices slightly to emulate granular sugar edges
function roughenPoly(pts, amp, seedOffset) {
  const out = [];
  for (let i = 0; i < pts.length; i++) {
    const p1 = pts[i];
    const p2 = pts[(i + 1) % pts.length];
    const d = dist(p1[0], p1[1], p2[0], p2[1]);
    const steps = max(2, floor(d / 9));
    for (let s = 0; s < steps; s++) {
      const t = s / steps;
      const bx = lerp(p1[0], p2[0], t);
      const by = lerp(p1[1], p2[1], t);
      const n1 = noise(bx * 0.08 + seedOffset, by * 0.08 + seedOffset) - 0.5;
      const n2 = noise(bx * 0.08 + 99 + seedOffset, by * 0.08 + 99 + seedOffset) - 0.5;
      out.push([bx + n1 * amp * 2.2, by + n2 * amp * 2.2]);
    }
  }
  return out;
}

// Build exact 2D polygons for the cube faces and chipped fracture planes
function getCubeGeometry(spec) {
  const R = spec.R;
  const H = spec.H;
  const ch = spec.chips;

  // Chipped corner offsets (clamped for safety)
  const ft = min(R * 0.7, ch.frontTop);
  const rt = min(R * 0.75, ch.rightTop);
  const lt = min(R * 0.75, ch.leftTop);
  const bt = min(R * 0.65, ch.backTop);
  const fb = min(R * 0.65, ch.frontBot);

  // Top face 3D vertices (counter-clockwise from back)
  const top3D = [
    [-R + bt, -R, H],
    [R - rt, -R, H],
    [R, -R + rt * 0.9, H - rt * 0.18],
    [R, R - ft, H],
    [R - ft, R, H],
    [-R + lt * 0.9, R, H - lt * 0.18],
    [-R, R - lt, H],
    [-R, -R + bt, H]
  ];

  // Front-Left face 3D vertices (y = +R plane)
  const left3D = [
    [-R, R - lt * 0.35, H - lt * 0.85],
    [-R + lt * 0.9, R, H - lt * 0.18],
    [R - ft, R, H],
    [R, R, H - ft * 0.95],
    [R, R, fb * 0.95],
    [R - fb * 0.9, R, 0],
    [-R, R, 0]
  ];

  // Front-Right face 3D vertices (x = +R plane)
  const right3D = [
    [R, R, H - ft * 0.95],
    [R, R - ft, H],
    [R, -R + rt * 0.9, H - rt * 0.18],
    [R, -R, H - rt * 0.88],
    [R, -R, 0],
    [R, R - fb * 0.9, 0],
    [R, R, fb * 0.95]
  ];

  // Fracture planes for prominent corner chips
  const fractures = [];
  if (rt > 7) {
    fractures.push({
      type: "rightTop",
      pts: [
        projectPt(spec, R - rt, -R, H),
        projectPt(spec, R, -R, H - rt * 0.88),
        projectPt(spec, R, -R + rt * 0.9, H - rt * 0.18)
      ]
    });
  }
  if (lt > 7) {
    fractures.push({
      type: "leftTop",
      pts: [
        projectPt(spec, -R, R - lt, H),
        projectPt(spec, -R + lt * 0.9, R, H - lt * 0.18),
        projectPt(spec, -R, R - lt * 0.35, H - lt * 0.85)
      ]
    });
  }
  if (ft > 6.5) {
    fractures.push({
      type: "frontTop",
      pts: [
        projectPt(spec, R - ft, R, H),
        projectPt(spec, R, R - ft, H),
        projectPt(spec, R, R, H - ft * 0.95)
      ]
    });
  }
  if (fb > 6.5) {
    fractures.push({
      type: "frontBot",
      pts: [
        projectPt(spec, R - fb * 0.9, R, 0),
        projectPt(spec, R, R, fb * 0.95),
        projectPt(spec, R, R - fb * 0.9, 0)
      ]
    });
  }

  return {
    top2D: roughenPoly(top3D.map(p => projectPt(spec, p[0], p[1], p[2])), 1.15, spec.seed),
    left2D: roughenPoly(left3D.map(p => projectPt(spec, p[0], p[1], p[2])), 1.1, spec.seed + 17),
    right2D: roughenPoly(right3D.map(p => projectPt(spec, p[0], p[1], p[2])), 1.1, spec.seed + 33),
    fractures
  };
}

// ============================================================================
// 3. CAST SHADOWS & GROUND TEA STAINS
// ============================================================================
function drawGroundStainAndShadow(spec) {
  randomSeed(spec.seed);
  const R = spec.R;
  const H = spec.H;

  // Optional migrating tea stain ring on the cool grey ground
  if (spec.tea && spec.tea.groundPool) {
    const px = spec.gx + spec.tea.poolOffset[0];
    const py = spec.gy + spec.tea.poolOffset[1];
    const rad = spec.tea.poolRadius;

    const stainPts = [];
    for (let a = 0; a < 360; a += 20) {
      const n = noise(cos(a) * 1.3 + spec.row, sin(a) * 1.3 + spec.col);
      const r = rad * (0.75 + 0.4 * n);
      stainPts.push([px + cos(a) * r * 1.15, py + sin(a) * r * 0.82]);
    }
    const sPoly = new brush.Polygon(stainPts);
    sPoly.fill(PAL.teaGround, 48, 0.25, 0.35);

    // Subtle darker capillary edge of ground stain
    brush.set("2H", PAL.teaEdge, 0.45);
    for (let i = 0; i < stainPts.length; i += 2) {
      const p1 = stainPts[i];
      const p2 = stainPts[(i + 1) % stainPts.length];
      if (random() < 0.65) {
        brush.line(p1[0], p1[1], p2[0], p2[1]);
      }
    }
  }

  // Short, soft shadow cast toward lower-right
  // Construct outer penumbra, mid shadow, and inner umbra polygons
  const pBackRight = projectPt(spec, -R, -R, 0);
  const pFrontRight = projectPt(spec, R, -R, 0);
  const pFrontMid = projectPt(spec, R, R, 0);
  const pFrontLeft = projectPt(spec, -R, R, 0);

  const sBackRight = projectShadowPt(spec, -R, -R, H * 0.92);
  const sFrontRight = projectShadowPt(spec, R, -R, H * 0.95);
  const sFrontMid = projectShadowPt(spec, R, R, H * 0.92);
  const sFrontLeft = projectShadowPt(spec, -R, R, H * 0.78);

  // 1. Soft outer penumbra
  const penumbraPts = [
    [pBackRight[0], pBackRight[1]],
    [sBackRight[0] + 6, sBackRight[1] - 3],
    [sFrontRight[0] + 9, sFrontRight[1] + 4],
    [sFrontMid[0] + 5, sFrontMid[1] + 8],
    [sFrontLeft[0] - 2, sFrontLeft[1] + 5],
    [pFrontLeft[0], pFrontLeft[1]],
    [pFrontMid[0], pFrontMid[1]]
  ];
  const penPoly = new brush.Polygon(penumbraPts);
  penPoly.wash(PAL.shadowSoft, 75);
  penPoly.fill(PAL.paperLavender, 28, 0.18, 0.2);

  // 2. Mid umbra
  const umbraPts = [
    [pFrontRight[0] - 4, pFrontRight[1] - 4],
    [sBackRight[0] - 2, sBackRight[1] + 2],
    [sFrontRight[0] + 1, sFrontRight[1] + 1],
    [sFrontMid[0] - 1, sFrontMid[1] + 2],
    [pFrontMid[0] - 2, pFrontMid[1] + 1],
    [pFrontLeft[0] + 6, pFrontLeft[1] + 2]
  ];
  const umbPoly = new brush.Polygon(umbraPts);
  umbPoly.wash(PAL.shadowMid, 95);

  // 3. Core shadow near the shadow-side base
  const corePts = [
    [pFrontRight[0], pFrontRight[1]],
    [lerp(pFrontRight[0], sFrontRight[0], 0.58), lerp(pFrontRight[1], sFrontRight[1], 0.58)],
    [lerp(pFrontMid[0], sFrontMid[0], 0.58), lerp(pFrontMid[1], sFrontMid[1], 0.58)],
    [pFrontMid[0], pFrontMid[1]]
  ];
  const corePoly = new brush.Polygon(corePts);
  corePoly.wash(PAL.shadowCore, 110);

  // 4. Fine graphite directional hatching across the cast shadow for clinical realism
  brush.hatchStyle("2H", PAL.graphiteMid, 0.42);
  umbPoly.hatch(4.2, 33, { rand: 0.06 });
  brush.hatchStyle("HB", PAL.graphiteDark, 0.38);
  corePoly.hatch(3.2, -25, { rand: 0.05 });
  brush.noHatch();

  // Soft chalk blending along the shadow edge
  brush.set("chalk", PAL.shadowMid, 0.65);
  brush.line(sBackRight[0], sBackRight[1], sFrontRight[0], sFrontRight[1]);
  brush.line(sFrontRight[0], sFrontRight[1], sFrontMid[0], sFrontMid[1]);
}

// ============================================================================
// 4. HYPERREAL SUGAR CUBE RENDERING
// ============================================================================
function drawSugarCube(spec) {
  randomSeed(spec.seed + 500);
  const geom = getCubeGeometry(spec);
  const R = spec.R;
  const H = spec.H;

  const topPoly = new brush.Polygon(geom.top2D);
  const leftPoly = new brush.Polygon(geom.left2D);
  const rightPoly = new brush.Polygon(geom.right2D);

  // --------------------------------------------------------------------------
  // STEP A: Opaque Base Washes & Pastel Subsurface Tints
  // --------------------------------------------------------------------------
  // 1. Front-Right Face (Core Shadow + Pastel Bounce Light)
  rightPoly.wash(PAL.rightBase, 235);
  rightPoly.fill(PAL.rightBounce, 55, 0.06, 0.3);

  // Upper/front core shadow zone on the right face
  const rightCorePts = [
    projectPt(spec, R, R, H * 0.92),
    projectPt(spec, R, -R * 0.6, H * 0.92),
    projectPt(spec, R, -R * 0.4, H * 0.28),
    projectPt(spec, R, R, H * 0.22)
  ];
  new brush.Polygon(rightCorePts).wash(PAL.rightCore, 125);

  // 2. Front-Left Face (Grazing Upper-Left Light, Cool Alabaster & Lilac Pastel)
  leftPoly.wash(PAL.leftBase, 240);
  leftPoly.fill(PAL.leftLilac, 42, 0.05, 0.25);

  const leftUpperPts = [
    projectPt(spec, -R, R, H),
    projectPt(spec, R * 0.5, R, H),
    projectPt(spec, R * 0.2, R, H * 0.35),
    projectPt(spec, -R, R, H * 0.45)
  ];
  new brush.Polygon(leftUpperPts).wash(PAL.leftSky, 75);

  // 3. Top Face (Direct Clinical Light, Warm Chalk White & Pastel Ice/Blush)
  topPoly.wash(PAL.topBase, 248);
  topPoly.fill(PAL.topWarm, 75, 0.04, 0.2);

  // Pastel ice-blue cool reflection near back-left of top face
  const topIcePts = [
    projectPt(spec, -R * 0.9, -R * 0.9, H),
    projectPt(spec, R * 0.2, -R * 0.9, H),
    projectPt(spec, -R * 0.1, R * 0.3, H),
    projectPt(spec, -R * 0.9, R * 0.4, H)
  ];
  new brush.Polygon(topIcePts).wash(PAL.topIce, 80);

  // Subtle pastel blush warmth near center-front of top face
  const topBlushPts = [
    projectPt(spec, -R * 0.3, -R * 0.2, H),
    projectPt(spec, R * 0.85, -R * 0.2, H),
    projectPt(spec, R * 0.85, R * 0.85, H),
    projectPt(spec, -R * 0.2, R * 0.85, H)
  ];
  new brush.Polygon(topBlushPts).wash(PAL.topBlush, 60);

  // 4. Chipped Corner Fracture Planes
  for (let frac of geom.fractures) {
    const fPoly = new brush.Polygon(frac.pts);
    const fCol = (frac.type === "rightTop" || frac.type === "frontBot")
      ? PAL.rightCrystal
      : PAL.leftHighlight;
    fPoly.wash(fCol, 220);
  }

  // --------------------------------------------------------------------------
  // STEP B: Migrating Tea Stain Across the Series
  // --------------------------------------------------------------------------
  if (spec.tea) {
    drawCubeTeaStain(spec);
  }

  // --------------------------------------------------------------------------
  // STEP C: Fine Graphite Planar Hatching
  // --------------------------------------------------------------------------
  // Shadow face cross-hatching
  brush.hatchStyle("2H", PAL.graphiteMid, 0.38);
  rightPoly.hatch(4.8, 28, { rand: 0.08 });
  brush.hatchStyle("2H", PAL.graphiteLight, 0.32);
  rightPoly.hatch(6.5, -52, { rand: 0.08 });

  // Grazing-light face delicate single hatching
  brush.hatchStyle("2H", PAL.graphiteLight, 0.28);
  leftPoly.hatch(6.8, -22, { rand: 0.09 });
  brush.noHatch();

  // --------------------------------------------------------------------------
  // STEP D: Granular Crystalline Surface Texture (Graphite + White Pencil)
  // --------------------------------------------------------------------------
  drawFaceCrystals(spec);

  // --------------------------------------------------------------------------
  // STEP E: Ridge Highlights, Edge Serrations & Contact Crevice Shadows
  // --------------------------------------------------------------------------
  drawRidgesAndContactShadows(spec, geom);

  // --------------------------------------------------------------------------
  // STEP F: Optional Cleavage Crack & Loose Spilled Sugar Crystals
  // --------------------------------------------------------------------------
  if (spec.crack) {
    drawCleavageCrack(spec);
  }
  drawLooseCrystals(spec);
}

// Render capillary tea stain soaking into specific cubes
function drawCubeTeaStain(spec) {
  const R = spec.R;
  const H = spec.H;
  const t = spec.tea;

  if (t.type === "origin") {
    // Small splash on upper-right edge of top face and trickling down right face
    const pTop = [];
    for (let a = 0; a < 360; a += 30) {
      let rx = R * (0.45 + 0.32 * cos(a) + random(-0.05, 0.05));
      let ry = R * (-0.1 + 0.32 * sin(a) + random(-0.05, 0.05));
      rx = constrain(rx, -R * 0.9, R * 0.95);
      ry = constrain(ry, -R * 0.9, R * 0.95);
      pTop.push(projectPt(spec, rx, ry, H));
    }
    const poly1 = new brush.Polygon(pTop);
    poly1.fill(PAL.teaHalo, 110, 0.15, 0.3);
    poly1.wash(PAL.teaSoft, 95);

    // Trickle onto right face
    const pRight = [
      projectPt(spec, R, -R * 0.35, H),
      projectPt(spec, R, R * 0.25, H),
      projectPt(spec, R, R * 0.15, H * 0.48),
      projectPt(spec, R, -R * 0.2, H * 0.55)
    ];
    new brush.Polygon(pRight).fill(PAL.teaMid, 85, 0.12, 0.35);

    // Capillary ring
    brush.set("cpencil", PAL.teaEdge, 0.45);
    for (let i = 0; i < pTop.length; i++) {
      const a = pTop[i];
      const b = pTop[(i + 1) % pTop.length];
      if (random() < 0.75) brush.line(a[0], a[1], b[0], b[1]);
    }
  } else if (t.type === "soakUp") {
    // Wicking up from the bottom across both front-left and front-right faces
    const leftSoak = [];
    const steps = 8;
    for (let i = 0; i <= steps; i++) {
      let u = map(i, 0, steps, -R * 0.35, R);
      let hWave = H * (0.52 + 0.14 * sin(i * 35) + random(-0.04, 0.04));
      leftSoak.push(projectPt(spec, u, R, hWave));
    }
    leftSoak.push(projectPt(spec, R, R, 0));
    leftSoak.push(projectPt(spec, -R * 0.45, R, 0));

    const lPoly = new brush.Polygon(leftSoak);
    lPoly.wash(PAL.teaSoft, 145);
    lPoly.fill(PAL.teaMid, 95, 0.18, 0.4);

    const rightSoak = [];
    for (let i = 0; i <= steps; i++) {
      let v = map(i, 0, steps, R, -R * 0.65);
      let hWave = H * (0.56 - 0.22 * (i / steps) + 0.08 * cos(i * 40));
      rightSoak.push(projectPt(spec, R, v, hWave));
    }
    rightSoak.push(projectPt(spec, R, -R * 0.75, 0));
    rightSoak.push(projectPt(spec, R, R, 0));

    const rPoly = new brush.Polygon(rightSoak);
    rPoly.wash(PAL.teaMid, 140);
    rPoly.fill(PAL.teaEdge, 75, 0.15, 0.35);

    // Tide line in warm toasted pastel sienna
    brush.set("cpencil", PAL.teaEdge, 0.55);
    for (let i = 0; i < steps; i++) {
      brush.line(leftSoak[i][0], leftSoak[i][1], leftSoak[i + 1][0], leftSoak[i + 1][1]);
      brush.line(rightSoak[i][0], rightSoak[i][1], rightSoak[i + 1][0], rightSoak[i + 1][1]);
    }
  } else if (t.type === "leftSpread") {
    // Stain climbing the front-left face onto the left side of the top face
    const lStain = [
      projectPt(spec, -R, R, H),
      projectPt(spec, R * 0.25, R, H),
      projectPt(spec, R * 0.35, R, H * 0.4),
      projectPt(spec, R * 0.15, R, 0),
      projectPt(spec, -R, R, 0)
    ];
    const lp = new brush.Polygon(lStain);
    lp.wash(PAL.teaSoft, 130);
    lp.fill(PAL.teaMid, 80, 0.16, 0.35);

    const tStain = [
      projectPt(spec, -R, R, H),
      projectPt(spec, -R, -R * 0.15, H),
      projectPt(spec, -R * 0.2, R * 0.1, H),
      projectPt(spec, R * 0.25, R, H)
    ];
    const tp = new brush.Polygon(tStain);
    tp.wash(PAL.teaHalo, 145);
    tp.fill(PAL.teaSoft, 95, 0.18, 0.3);

    brush.set("cpencil", PAL.teaEdge, 0.45);
    brush.line(tStain[1][0], tStain[1][1], tStain[2][0], tStain[2][1]);
    brush.line(tStain[2][0], tStain[2][1], tStain[3][0], tStain[3][1]);
  } else if (t.type === "ghost" || t.type === "droplet") {
    // Subtle pale remnant near the bottom corner
    const cx = (t.type === "ghost") ? -R * 0.55 : R * 0.65;
    const gPts = [
      projectPt(spec, cx - R * 0.3, R, 0),
      projectPt(spec, cx - R * 0.2, R, H * 0.32),
      projectPt(spec, cx + R * 0.25, R, H * 0.28),
      projectPt(spec, cx + R * 0.3, R, 0)
    ];
    const gp = new brush.Polygon(gPts);
    gp.wash(PAL.teaHalo, 120);
    gp.fill(PAL.teaSoft, 75, 0.15, 0.25);
  }
}

// Check if a local 3D coordinate lies inside a cube's tea stain zone
function isPointStained(spec, x, y, z) {
  if (!spec.tea) return false;
  const R = spec.R;
  const H = spec.H;
  const t = spec.tea.type;
  if (t === "origin") {
    return (x > 0 && y > -R * 0.45 && y < R * 0.35 && z > H * 0.5);
  }
  if (t === "soakUp") {
    return (z < H * 0.54 && (x > -R * 0.35 || y > -R * 0.5));
  }
  if (t === "leftSpread") {
    return (x < R * 0.25 && y > -R * 0.15);
  }
  if (t === "ghost") {
    return (x < -R * 0.2 && y > R * 0.5 && z < H * 0.32);
  }
  if (t === "droplet") {
    return (x > R * 0.35 && y > R * 0.5 && z < H * 0.3);
  }
  return false;
}

// Render hundreds of individual compressed sugar granules across all 3 visible faces
function drawFaceCrystals(spec) {
  const R = spec.R;
  const H = spec.H;

  // 1. TOP FACE CRYSTALS (Brightest white pencil & delicate 2H interstices)
  const topGrid = 9;
  for (let ix = 0; ix < topGrid; ix++) {
    for (let iy = 0; iy < topGrid; iy++) {
      let lx = map(ix + 0.5, 0, topGrid, -R * 0.88, R * 0.88) + random(-3.2, 3.2);
      let ly = map(iy + 0.5, 0, topGrid, -R * 0.88, R * 0.88) + random(-3.2, 3.2);

      // Skip if sliced off by a major corner chip
      if (lx > R - spec.chips.rightTop * 0.85 && ly < -R + spec.chips.rightTop * 0.85) continue;
      if (lx < -R + spec.chips.leftTop * 0.85 && ly > R - spec.chips.leftTop * 0.85) continue;
      if (lx > R - spec.chips.frontTop * 0.85 && ly > R - spec.chips.frontTop * 0.85) continue;

      const pt = projectPt(spec, lx, ly, H);
      const stained = isPointStained(spec, lx, ly, H);

      // Tiny graphite crevice on lower-right of crystal
      const crevCol = stained ? PAL.teaEdge : PAL.graphiteLight;
      brush.set("needle", crevCol, random(0.45, 0.85));
      const cLen = random(1.8, 3.6);
      brush.line(pt[0] + 0.6, pt[1] + 0.6, pt[0] + 0.6 + cLen, pt[1] + 0.9);
      if (random() < 0.55) {
        brush.line(pt[0] + 0.6, pt[1] + 0.6, pt[0] + 0.2, pt[1] + 0.6 + cLen * 0.75);
      }

      // Crisp white pencil / crystal highlight on upper-left of crystal
      const hiCol = stained ? PAL.teaHalo : (random() < 0.78 ? PAL.pureWhite : PAL.topIce);
      if (random() < 0.65) {
        brush.set("crystal", hiCol, random(0.55, 1.15));
        brush.line(pt[0] - 1.2, pt[1] - 0.8, pt[0] + 0.8, pt[1] - 0.3);
      } else {
        brush.set("cpencil", hiCol, random(0.7, 1.3));
        brush.line(pt[0] - 1.5, pt[1] - 0.6, pt[0] + 1.0, pt[1] + 0.2);
      }
    }
  }

  // 2. FRONT-LEFT FACE CRYSTALS (Mid-tone graphite crevices & crisp alabaster facets)
  const sideCols = 8;
  const sideRows = 8;
  for (let ix = 0; ix < sideCols; ix++) {
    for (let iz = 0; iz < sideRows; iz++) {
      let lx = map(ix + 0.5, 0, sideCols, -R * 0.88, R * 0.88) + random(-2.8, 2.8);
      let lz = map(iz + 0.5, 0, sideRows, H * 0.08, H * 0.92) + random(-2.8, 2.8);

      if (lx < -R + spec.chips.leftTop * 0.8 && lz > H - spec.chips.leftTop * 0.8) continue;
      if (lx > R - spec.chips.frontTop * 0.8 && lz > H - spec.chips.frontTop * 0.8) continue;
      if (lx > R - spec.chips.frontBot * 0.8 && lz < spec.chips.frontBot * 0.8) continue;

      const pt = projectPt(spec, lx, R, lz);
      const stained = isPointStained(spec, lx, R, lz);

      // Graphite interstice
      brush.set("needle", stained ? PAL.teaEdge : PAL.graphiteMid, random(0.55, 0.95));
      const cLen = random(1.8, 3.4);
      brush.line(pt[0], pt[1] + 0.8, pt[0] + cLen, pt[1] + 1.4);

      // White/pastel crystal facet
      const hiCol = stained ? PAL.teaHalo : (random() < 0.5 ? PAL.pureWhite : PAL.leftHighlight);
      brush.set("cpencil", hiCol, random(0.6, 1.05));
      brush.line(pt[0] - 1.2, pt[1] - 0.6, pt[0] + 0.7, pt[1] + 0.1);
    }
  }

  // 3. FRONT-RIGHT FACE CRYSTALS (Deeper graphite crevices & muted reflected sparkles)
  for (let iy = 0; iy < sideCols; iy++) {
    for (let iz = 0; iz < sideRows; iz++) {
      let ly = map(iy + 0.5, 0, sideCols, -R * 0.88, R * 0.88) + random(-2.8, 2.8);
      let lz = map(iz + 0.5, 0, sideRows, H * 0.08, H * 0.92) + random(-2.8, 2.8);

      if (ly < -R + spec.chips.rightTop * 0.8 && lz > H - spec.chips.rightTop * 0.8) continue;
      if (ly > R - spec.chips.frontTop * 0.8 && lz > H - spec.chips.frontTop * 0.8) continue;
      if (ly > R - spec.chips.frontBot * 0.8 && lz < spec.chips.frontBot * 0.8) continue;

      const pt = projectPt(spec, R, ly, lz);
      const stained = isPointStained(spec, R, ly, lz);

      // Darker graphite crevice in shadow
      brush.set("needle", stained ? PAL.teaEdge : PAL.graphiteDark, random(0.6, 1.0));
      const cLen = random(1.8, 3.5);
      brush.line(pt[0], pt[1] + 0.6, pt[0] + cLen * 0.85, pt[1] - 0.4);

      // Subtle cool crystal highlight catching ambient bounce light
      if (random() < 0.75) {
        const hiCol = stained ? PAL.teaSoft : PAL.rightCrystal;
        brush.set("cpencil", hiCol, random(0.5, 0.85));
        brush.line(pt[0] - 1.0, pt[1] - 0.3, pt[0] + 0.6, pt[1] - 0.9);
      }
    }
  }
}

// Render the glittering crystal ridges between faces and tight ambient occlusion at the base
function drawRidgesAndContactShadows(spec, geom) {
  const R = spec.R;
  const H = spec.H;
  const ch = spec.chips;

  // 1. Central Y-Ridges (where top meets front-left, top meets front-right, and front vertical ridge)
  // Top-Left Ridge: (-R, +R, H) to (+R, +R, H) — catches brightest edge light!
  const steps = 18;
  for (let i = 0; i <= steps; i++) {
    let lx = map(i, 0, steps, -R + ch.leftTop * 0.85, R - ch.frontTop * 0.85);
    let jitterZ = H + random(-1.2, 1.4);
    if (spec.edgeNotch && spec.edgeNotch.edge === "topLeft") {
      let d = abs((i / steps) - spec.edgeNotch.pos);
      if (d < 0.14) jitterZ -= (1 - d / 0.14) * spec.edgeNotch.depth;
    }
    const p = projectPt(spec, lx, R, jitterZ);
    const stained = isPointStained(spec, lx, R, H);

    // Bright white pencil crystal cluster along the ridge
    brush.set("crystal", stained ? PAL.teaHalo : PAL.pureWhite, random(0.8, 1.35));
    brush.line(p[0] - 1.4, p[1] - 0.6, p[0] + 1.4, p[1] + 0.5);

    // Tiny micro-shadow just below the ridge on the front-left face
    brush.set("needle", PAL.graphiteLight, 0.6);
    brush.line(p[0] - 0.5, p[1] + 1.8, p[0] + 1.5, p[1] + 2.6);
  }

  // Top-Right Ridge: (+R, +R, H) to (+R, -R, H) — dramatic contrast between bright top and shadow side!
  for (let i = 0; i <= steps; i++) {
    let ly = map(i, 0, steps, -R + ch.rightTop * 0.85, R - ch.frontTop * 0.85);
    const p = projectPt(spec, R, ly, H + random(-1.2, 1.2));
    const stained = isPointStained(spec, R, ly, H);

    // Crisp white crystal edge on the top side of the ridge
    brush.set("cpencil", stained ? PAL.teaHalo : PAL.pureWhite, random(0.85, 1.3));
    brush.line(p[0] - 1.8, p[1] - 0.4, p[0] + 0.4, p[1] - 1.2);

    // Serrated dark crystal shadow immediately below the ridge on the front-right shadow face
    brush.set("needle", PAL.graphiteDark, random(0.65, 1.05));
    brush.line(p[0] + 0.4, p[1] + 1.2, p[0] + 2.2, p[1] + 0.3);
  }

  // Front Vertical Ridge: (+R, +R, 0) to (+R, +R, H)
  const vSteps = 14;
  for (let i = 0; i <= vSteps; i++) {
    let lz = map(i, 0, vSteps, ch.frontBot * 0.9, H - ch.frontTop * 0.9);
    const p = projectPt(spec, R + random(-0.8, 0.8), R + random(-0.8, 0.8), lz);
    const stained = isPointStained(spec, R, R, lz);

    brush.set("cpencil", stained ? PAL.teaHalo : PAL.leftHighlight, random(0.65, 1.1));
    brush.line(p[0] - 1.6, p[1] - 0.4, p[0] - 0.2, p[1] + 1.4);

    brush.set("needle", PAL.graphiteDark, random(0.6, 0.95));
    brush.line(p[0] + 0.8, p[1] - 0.6, p[0] + 1.2, p[1] + 1.6);
  }

  // 2. Outer Silhouette Granular Edge Definition
  // Back-left and back-right illuminated edges get crisp white pencil & ultra-fine 2H contour
  const backSteps = 14;
  for (let i = 0; i < backSteps; i++) {
    let u1 = map(i, 0, backSteps, -R + ch.backTop * 0.8, R - ch.rightTop * 0.8);
    let u2 = map(i + 1, 0, backSteps, -R + ch.backTop * 0.8, R - ch.rightTop * 0.8);
    let p1 = projectPt(spec, u1, -R, H + random(-0.9, 0.9));
    let p2 = projectPt(spec, u2, -R, H + random(-0.9, 0.9));
    brush.set("needle", PAL.graphiteLight, 0.48);
    brush.line(p1[0], p1[1] - 0.8, p2[0], p2[1] - 0.8);
    brush.set("cpencil", PAL.pureWhite, 0.95);
    brush.line(p1[0], p1[1] + 0.5, p2[0], p2[1] + 0.5);

    let v1 = map(i, 0, backSteps, -R + ch.backTop * 0.8, R - ch.leftTop * 0.8);
    let v2 = map(i + 1, 0, backSteps, -R + ch.backTop * 0.8, R - ch.leftTop * 0.8);
    let q1 = projectPt(spec, -R, v1, H + random(-0.9, 0.9));
    let q2 = projectPt(spec, -R, v2, H + random(-0.9, 0.9));
    brush.set("needle", PAL.graphiteLight, 0.48);
    brush.line(q1[0] - 0.8, q1[1], q2[0] - 0.8, q2[1]);
    brush.set("cpencil", PAL.pureWhite, 1.05);
    brush.line(q1[0] + 0.6, q1[1], q2[0] + 0.6, q2[1]);
  }

  // Left and Right vertical silhouette edges
  for (let i = 0; i < 12; i++) {
    let z1 = map(i, 0, 12, 0, H - ch.leftTop * 0.85);
    let z2 = map(i + 1, 0, 12, 0, H - ch.leftTop * 0.85);
    let l1 = projectPt(spec, -R + random(-0.7, 0.7), R, z1);
    let l2 = projectPt(spec, -R + random(-0.7, 0.7), R, z2);
    brush.set("needle", PAL.graphiteMid, 0.55);
    brush.line(l1[0] - 0.6, l1[1], l2[0] - 0.6, l2[1]);
    brush.set("cpencil", PAL.leftHighlight, 0.8);
    brush.line(l1[0] + 0.7, l1[1], l2[0] + 0.7, l2[1]);

    let rz1 = map(i, 0, 12, 0, H - ch.rightTop * 0.85);
    let rz2 = map(i + 1, 0, 12, 0, H - ch.rightTop * 0.85);
    let r1 = projectPt(spec, R, -R + random(-0.7, 0.7), rz1);
    let r2 = projectPt(spec, R, -R + random(-0.7, 0.7), rz2);
    brush.set("needle", PAL.graphiteDark, 0.72);
    brush.line(r1[0], r1[1], r2[0], r2[1]);
  }

  // 3. Fracture Plane Crystalline Texture (for chipped corners)
  for (let frac of geom.fractures) {
    const c0 = frac.pts[0];
    const c1 = frac.pts[1];
    const c2 = frac.pts[2];
    for (let k = 0; k < 14; k++) {
      let a = random();
      let b = random() * (1 - a);
      let c = 1 - a - b;
      let px = a * c0[0] + b * c1[0] + c * c2[0];
      let py = a * c0[1] + b * c1[1] + c * c2[1];
      brush.set("needle", PAL.graphiteDark, 0.65);
      brush.line(px, py, px + random(1.5, 3.0), py + random(0.5, 2.0));
      brush.set("crystal", PAL.pureWhite, 0.85);
      brush.line(px - 1.0, py - 0.6, px + 0.6, py - 0.2);
    }
  }

  // 4. Tight Ambient Occlusion Contact Shadow where rough cube base meets the ground
  const baseSteps = 14;
  for (let i = 0; i < baseSteps; i++) {
    // Front-left base line
    let lx1 = map(i, 0, baseSteps, -R, R - ch.frontBot * 0.8);
    let lx2 = map(i + 1, 0, baseSteps, -R, R - ch.frontBot * 0.8);
    let bp1 = projectPt(spec, lx1, R, 0);
    let bp2 = projectPt(spec, lx2, R, 0);
    brush.set("needle", PAL.aoDark, random(0.85, 1.35));
    brush.line(bp1[0], bp1[1] + random(-0.6, 0.8), bp2[0], bp2[1] + random(-0.6, 0.8));

    // Front-right base line (deeper occlusion on shadow side)
    let ly1 = map(i, 0, baseSteps, R - ch.frontBot * 0.8, -R);
    let ly2 = map(i + 1, 0, baseSteps, R - ch.frontBot * 0.8, -R);
    let rp1 = projectPt(spec, R, ly1, 0);
    let rp2 = projectPt(spec, R, ly2, 0);
    brush.set("2B", PAL.aoDark, random(0.55, 0.85));
    brush.line(rp1[0], rp1[1] + random(-0.5, 0.9), rp2[0], rp2[1] + random(-0.5, 0.9));
  }
}

// Render a sharp geological fracture crack on cube (3, 3)
function drawCleavageCrack(spec) {
  const R = spec.R;
  const H = spec.H;
  const crackTop = [];
  const steps = 10;

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let lx = lerp(-R * 0.35, -R * 0.15, t) + random(-2.2, 2.2);
    let ly = lerp(-R * 0.75, R, t);
    crackTop.push(projectPt(spec, lx, ly, H));
  }

  const crackSide = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let lx = lerp(-R * 0.15, -R * 0.42, t) + random(-2.0, 2.0);
    let lz = lerp(H, 0, t);
    crackSide.push(projectPt(spec, lx, R, lz));
  }

  const allPts = crackTop.concat(crackSide);
  for (let i = 0; i < allPts.length - 1; i++) {
    const p1 = allPts[i];
    const p2 = allPts[i + 1];
    // Dark crevice
    brush.set("needle", PAL.aoDark, 0.95);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    // Illuminated right/lower lip of the crack catching upper-left light
    brush.set("cpencil", PAL.pureWhite, 0.8);
    brush.line(p1[0] + 1.5, p1[1] + 0.5, p2[0] + 1.5, p2[1] + 0.5);
  }
}

// Render loose spilled sugar crystals on the cool grey ground
function drawLooseCrystals(spec) {
  for (let c of spec.extraCrumbs) {
    const cx = spec.gx + c.dx;
    const cy = spec.gy + c.dy;
    const s = c.sz;

    // 1. Tiny short cast shadow to lower-right
    brush.set("needle", PAL.shadowCore, 0.85);
    brush.line(cx + s * 0.3, cy + s * 0.3, cx + s * 1.45, cy + s * 0.95);
    brush.set("needle", PAL.aoDark, 0.7);
    brush.line(cx - s * 0.2, cy + s * 0.45, cx + s * 0.7, cy + s * 0.55);

    // 2. Mid-tone lower-right crystal facet
    brush.set("cpencil", c.stained ? PAL.teaMid : PAL.leftBase, 0.85);
    brush.line(cx, cy + s * 0.2, cx + s * 0.75, cy - s * 0.1);

    // 3. Brilliant white upper-left crystal facet
    brush.set("crystal", c.stained ? PAL.teaHalo : PAL.pureWhite, map(s, 1.5, 4.6, 0.55, 1.15));
    brush.line(cx - s * 0.65, cy - s * 0.25, cx + s * 0.35, cy - s * 0.45);
  }
}

// ============================================================================
// 5. THE LONE ANT (Hyperreal miniature entomology on Cube row 2, col 1)
// ============================================================================
function drawLoneAnt(spec) {
  // Position the ant on the illuminated top face of cube (2, 1),
  // walking toward the front-right edge (toward the tea-stained cube at 2, 2!)
  const pCenter = projectPt(spec, spec.R * 0.18, spec.R * 0.22, spec.H);
  const ax = pCenter[0];
  const ay = pCenter[1];
  const dir = 18; // Facing angle in degrees (toward lower-right / right neighbor)

  const ca = cos(dir);
  const sa = sin(dir);

  // Local helper to transform ant-space coordinates (u along body, v perpendicular)
  const antPt = (u, v) => [
    ax + u * ca - v * sa,
    ay + u * sa + v * ca
  ];

  // 1. Miniature cast shadow of the ant on the sugar crystals (shifted lower-right)
  const shOff = [2.4, 1.8];
  brush.set("needle", PAL.graphiteMid, 0.75);
  // Shadow of body segments
  const gasterC = antPt(-7.5, 0);
  const thoraxC = antPt(0, 0);
  const headC = antPt(5.8, 0);
  brush.line(gasterC[0] + shOff[0] - 2, gasterC[1] + shOff[1], headC[0] + shOff[0] + 1, headC[1] + shOff[1]);

  // 2. Six Jointed Legs (3 per side: femur, tibia, tarsus with tiny shadow on sugar)
  const legSpecs = [
    // Front pair (reaching forward)
    { base: [2.2, -1.1], knee: [4.8, -5.8], foot: [8.5, -7.2], tarsus: [10.2, -6.8] },
    { base: [2.2,  1.1], knee: [4.5,  5.6], foot: [8.2,  7.4], tarsus: [9.8,  7.9] },
    // Middle pair (bracing laterally)
    { base: [-0.2, -1.2], knee: [-1.2, -6.5], foot: [-2.8, -9.5], tarsus: [-3.8, -10.2] },
    { base: [-0.2,  1.2], knee: [-0.8,  6.2], foot: [-1.8,  9.6], tarsus: [-2.5,  10.8] },
    // Hind pair (pushing backward)
    { base: [-2.4, -1.1], knee: [-5.8, -5.8], foot: [-10.5, -8.2], tarsus: [-12.2, -8.0] },
    { base: [-2.4,  1.1], knee: [-5.5,  5.6], foot: [-9.8,  8.8], tarsus: [-11.6,  9.2] }
  ];

  for (let leg of legSpecs) {
    const pBase = antPt(leg.base[0], leg.base[1]);
    const pKnee = antPt(leg.knee[0], leg.knee[1]);
    const pFoot = antPt(leg.foot[0], leg.foot[1]);
    const pTars = antPt(leg.tarsus[0], leg.tarsus[1]);

    // Leg cast shadow on the sugar surface (knee is raised, foot touches surface!)
    brush.set("needle", PAL.graphiteLight, 0.48);
    brush.line(pBase[0] + 1.8, pBase[1] + 1.3, pKnee[0] + 2.4, pKnee[1] + 1.8);
    brush.line(pKnee[0] + 2.4, pKnee[1] + 1.8, pFoot[0], pFoot[1]);

    // Femur & Tibia
    brush.set("needle", PAL.antLeg, 0.72);
    brush.line(pBase[0], pBase[1], pKnee[0], pKnee[1]);
    brush.set("needle", PAL.antDark, 0.62);
    brush.line(pKnee[0], pKnee[1], pFoot[0], pFoot[1]);
    // Delicate tarsus tip gripping a sugar crystal
    brush.set("needle", PAL.antLeg, 0.45);
    brush.line(pFoot[0], pFoot[1], pTars[0], pTars[1]);
  }

  // 3. Elbowed Antennae (Scape + Funiculus) inspecting a protruding crystal
  const antLeft1 = antPt(7.2, -0.9);
  const antLeft2 = antPt(10.5, -3.6);
  const antLeft3 = antPt(13.8, -2.2);

  const antRight1 = antPt(7.2, 0.9);
  const antRight2 = antPt(10.2, 3.8);
  const antRight3 = antPt(13.6, 2.8);

  brush.set("needle", PAL.antLeg, 0.52);
  brush.line(antLeft1[0], antLeft1[1], antLeft2[0], antLeft2[1]);
  brush.line(antLeft2[0], antLeft2[1], antLeft3[0], antLeft3[1]);
  brush.line(antRight1[0], antRight1[1], antRight2[0], antRight2[1]);
  brush.line(antRight2[0], antRight2[1], antRight3[0], antRight3[1]);

  // 4. Gaster (Abdomen), Petiole Node, Thorax (Mesosoma), and Head
  // Build small polygons for the chitinous body segments
  const makeOval = (u0, v0, ru, rv) => {
    const pts = [];
    for (let a = 0; a < 360; a += 30) {
      pts.push(antPt(u0 + cos(a) * ru, v0 + sin(a) * rv));
    }
    return new brush.Polygon(pts);
  };

  const gasterPoly = makeOval(-7.6, 0, 4.2, 2.8);
  const thoraxPoly = makeOval(-0.3, 0, 3.1, 1.5);
  const headPoly = makeOval(5.6, 0, 2.2, 1.85);

  gasterPoly.wash(PAL.antDark, 245);
  thoraxPoly.wash(PAL.antMid, 240);
  headPoly.wash(PAL.antDark, 245);

  // Crisp graphite & dark ink contour of segments and petiole waist
  const pPetiole1 = antPt(-4.0, 0);
  const pPetiole2 = antPt(-2.8, 0);
  brush.set("needle", PAL.antDark, 0.95);
  brush.line(pPetiole1[0], pPetiole1[1], pPetiole2[0], pPetiole2[1]);

  // Dense shading on the lower-right side of gaster, thorax, and head
  for (let a = 15; a <= 165; a += 25) {
    let pG = antPt(-7.6 + cos(a) * 3.8, sin(a) * 2.4);
    brush.set("needle", PAL.antDark, 0.85);
    brush.line(pG[0] - 0.8, pG[1] - 0.4, pG[0] + 0.5, pG[1] + 0.4);
  }

  // 5. Chitinous Specular Highlights (Upper-left glints from the clinical light)
  const glintGaster1 = antPt(-8.8, -1.2);
  const glintGaster2 = antPt(-6.2, -1.3);
  const glintThorax1 = antPt(-1.4, -0.7);
  const glintThorax2 = antPt(0.8, -0.6);
  const glintHead1 = antPt(5.0, -0.8);
  const glintHead2 = antPt(6.3, -0.7);

  brush.set("cpencil", PAL.antGlint, 0.72);
  brush.line(glintGaster1[0], glintGaster1[1], glintGaster2[0], glintGaster2[1]);
  brush.set("cpencil", PAL.antGlint, 0.58);
  brush.line(glintThorax1[0], glintThorax1[1], glintThorax2[0], glintThorax2[1]);
  brush.line(glintHead1[0], glintHead1[1], glintHead2[0], glintHead2[1]);

  // A slightly larger sugar crystal right in front of the ant's antennae
  const foodPt = antPt(15.2, 0.3);
  brush.set("needle", PAL.aoDark, 0.75);
  brush.line(foodPt[0] + 0.8, foodPt[1] + 1.2, foodPt[0] + 3.2, foodPt[1] + 2.0);
  brush.set("crystal", PAL.pureWhite, 1.05);
  brush.line(foodPt[0] - 1.5, foodPt[1] - 0.8, foodPt[0] + 1.2, foodPt[1] - 0.2);
}

// ============================================================================
// 6. FINAL CLINICAL SURFACE TOUCHES
// ============================================================================
function drawFinalSurfaceTouches() {
  // Sparse microscopic sugar dust specks and paper tooth highlights across the table
  for (let i = 0; i < 65; i++) {
    const x = random(140, 1060);
    const y = random(140, 1060);
    brush.set("needle", PAL.graphiteLight, random(0.3, 0.55));
    brush.line(x, y, x + 1.2, y + 0.6);
    if (random() < 0.45) {
      brush.set("cpencil", PAL.pureWhite, random(0.35, 0.6));
      brush.line(x - 0.8, y - 0.4, x + 0.4, y - 0.2);
    }
  }
}

