// Diagonal dividing line runs from (76, 842) through (600, 600) to (1124, 358)
const M_DIAG = (358 - 842) / (1124 - 76); // -0.461832
const BAND_HALF = 6.5;

function diagLimitY(x, pad = BAND_HALF) {
  return 600 + (x - 600) * M_DIAG - pad;
}

function clipVal(x, y, pad = BAND_HALF) {
  return y - diagLimitY(x, pad); // <= 0 is inside upper-left half
}

// Clip a polygon against the diagonal line
function clipPolyToDiag(pts, pad = BAND_HALF) {
  let out = [];
  const n = pts.length;
  if (n < 3) return out;
  for (let i = 0; i < n; i++) {
    const cur = pts[i];
    const prev = pts[(i + n - 1) % n];
    const cVal = clipVal(cur[0], cur[1], pad);
    const pVal = clipVal(prev[0], prev[1], pad);
    const cIn = cVal <= 0;
    const pIn = pVal <= 0;
    if (cIn !== pIn) {
      const t = pVal / (pVal - cVal);
      out.push([
        prev[0] + t * (cur[0] - prev[0]),
        prev[1] + t * (cur[1] - prev[1])
      ]);
    }
    if (cIn) out.push([cur[0], cur[1]]);
  }
  return out;
}

// Clip a line segment against the diagonal line
function clipSegToDiag(x1, y1, x2, y2, pad = BAND_HALF) {
  const v1 = clipVal(x1, y1, pad);
  const v2 = clipVal(x2, y2, pad);
  if (v1 > 0 && v2 > 0) return null;
  if (v1 <= 0 && v2 <= 0) return [x1, y1, x2, y2];
  const t = v1 / (v1 - v2);
  const ix = x1 + t * (x2 - x1);
  const iy = y1 + t * (y2 - y1);
  if (v1 <= 0) return [x1, y1, ix, iy];
  return [ix, iy, x2, y2];
}

// Draw a line clipped to the diagonal AND mirrored 180 deg across (600, 600)
function mLine(x1, y1, x2, y2, pad = BAND_HALF) {
  const seg = clipSegToDiag(x1, y1, x2, y2, pad);
  if (!seg) return;
  const [ax, ay, bx, by] = seg;
  if ( Math.hypot(bx - ax, by - ay) < 0.9 ) return;
  brush.line(ax, ay, bx, by);
  brush.line(1200 - ax, 1200 - ay, 1200 - bx, 1200 - by);
}

// Draw a spline clipped to the diagonal AND mirrored 180 deg across (600, 600)
function mSpline(pts, curv = 0.5, pad = BAND_HALF) {
  if (!pts || pts.length < 2) return;
  // Subdivide into dense points if needed, clip segments into subpaths
  let current = [];
  let subpaths = [];
  for (let i = 0; i < pts.length - 1; i++) {
    const p1 = pts[i];
    const p2 = pts[i + 1];
    const seg = clipSegToDiag(p1[0], p1[1], p2[0], p2[1], pad);
    const pr1 = p1[2] !== undefined ? p1[2] : 1;
    const pr2 = p2[2] !== undefined ? p2[2] : 1;
    if (seg) {
      if (current.length === 0) {
        current.push([seg[0], seg[1], pr1]);
      }
      current.push([seg[2], seg[3], pr2]);
      // If p2 was outside, close current subpath
      if (clipVal(p2[0], p2[1], pad) > 0) {
        subpaths.push(current);
        current = [];
      }
    } else if (current.length > 0) {
      subpaths.push(current);
      current = [];
    }
  }
  if (current.length > 0) subpaths.push(current);

  for (let sp of subpaths) {
    // Filter out points too close together
    let clean = [sp[0]];
    for (let k = 1; k < sp.length; k++) {
      const prev = clean[clean.length - 1];
      if (Math.hypot(sp[k][0] - prev[0], sp[k][1] - prev[1]) > 1.2) {
        clean.push(sp[k]);
      }
    }
    if (clean.length === 2) {
      brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
      brush.line(1200 - clean[0][0], 1200 - clean[0][1], 1200 - clean[1][0], 1200 - clean[1][1]);
    } else if (clean.length >= 3) {
      brush.spline(clean, curv);
      let mir = clean.map(p => [1200 - p[0], 1200 - p[1], p[2]]);
      brush.spline(mir, curv);
    }
  }
}

// Draw a filled/washed polygon in both halves (clipped to diagonal)
function mPolyFill(pts, col, alpha = 180, useWash = true, pad = BAND_HALF) {
  const cPts = clipPolyToDiag(pts, pad);
  if (cPts.length < 3) return;
  brush.noStroke();
  if (useWash) {
    brush. noFill();
    brush.wash(col, alpha);
  } else {
    brush.noWash();
    brush.fill(col, alpha);
    brush.fillBleed(0.04, "in");
    brush.fillTexture(0.35, 0.2);
  }
  // Upper half
  brush.beginShape(0);
  for (let p of cPts) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  // Lower mirrored half
  brush.beginShape(0);
  for (let p of cPts) brush.vertex(1200 - p[0], 1200 - p[1]);
  brush.endShape(true);
  brush.noFill();
  brush.noWash();
}

// Helper: Fill a quadrilateral band with directional coloured-pencil hatching
function mHatchQuad(p00, p10, p11, p01, steps, jitter = 1.5, pad = BAND_HALF) {
  for (let i = 0; i <= steps; i++) {
    const t = i / Math.max(1, steps);
    const x1 = p00[0] + (p01[0] - p00[0]) * t + random(-jitter, jitter);
    const y1 = p00[1] + (p01[1] - p00[1]) * t + random(-jitter, jitter);
    const x2 = p10[0] + (p11[0] - p10[0]) * t + random(-jitter, jitter);
    const y2 = p10[1] + (p11[1] - p10[1]) * t + random(-jitter, jitter);
    mLine(x1, y1, x2, y2, pad);
  }
}

// Helper: Contoured 3D surface shading between two rails (each rail is an array of [x,y])
function mContourShade(railA, railB, strokes, curv = 0.45, jitter = 1.2, pad = BAND_HALF) {
  const n = Math.min(railA.length, railB.length);
  for (let s = 0; s <= strokes; s++) {
    const t = s / Math.max(1, strokes);
    let pts = [];
    for (let i = 0; i < n; i++) {
      const x = railA[i][0] + (railB[i][0] - railA[i][0]) * t + random(-jitter, jitter);
      const y = railA[i][1] + (railB[i][1] - railA[i][1]) * t + random(-jitter, jitter);
      const pr = 0.65 + 0.6 * Math.sin((i / (n - 1)) * Math.PI);
      pts.push([x, y, pr]);
    }
    mSpline(pts, curv, pad);
  }
}

// Point-in-polygon check for constrained hatching
function ptInPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const xi = poly[i][0], yi = poly[i][1];
    const xj = poly[j][0], yj = poly[j][1];
    const intersect = ((yi > y) !== (yj > y)) &&
      (x < (xj - xi) * (y - yi) / (yj - yi + 0.00001) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

