// ============================================================================
// 5. BRAIDED GOLD EPAULETTES, BULLION FRINGE & AIGUILLETTE CORDS
// ============================================================================
function drawEpaulettesAndCords() {
  // Helper to draw a braided shoulder epaulette (dir = -1 for left shoulder, +1 for right)
  function renderShoulderEpaulette(dir) {
    const cx = 555;
    const xCollar = cx + dir * 98;
    const yCollar = 488;
    const xShoulder = cx + dir * 328;
    const yShoulder = 542;

    // 1. Dark cobalt/black strap core with vermilion edge
    brush.set("burnish", PAL.cobaltDeep, 1.1);
    for (let t = 0.15; t <= 0.85; t += 0.12) {
      mLine(
        xCollar, yCollar - 8 + t * 24,
        xShoulder - dir * 24, yShoulder - 14 + t * 30
      );
    }

    // 2. Intertwined braided gold rope loops along the shoulder board
    const numKnots = 11;
    for (let i = 0; i < numKnots; i++) {
      const t0 = i / numKnots;
      const t1 = (i + 1) / numKnots;
      const mx = lerp(xCollar, xShoulder, (t0 + t1) * 0.5);
      const my = lerp(yCollar, yShoulder, (t0 + t1) * 0.5);
      const w = lerp(14, 24, (t0 + t1) * 0.5);

      // Warm vermilion-ochre underside shadow of each braid twist
      brush.set("cpencil", PAL.vermDark, 0.95);
      mSpline([
        [lerp(xCollar, xShoulder, t0), lerp(yCollar, yShoulder, t0) - w * 0.7],
        [mx, my + w * 0.85],
        [lerp(xCollar, xShoulder, t1), lerp(yCollar, yShoulder, t1) - w * 0.7]
      ], 0.55);

      // Rich egg-yolk yellow main rope strand
      brush.set("burnish", PAL.yolk, 1.15);
      mSpline([
        [lerp(xCollar, xShoulder, t0), lerp(yCollar, yShoulder, t0) + w * 0.7],
        [mx, my - w * 0.85],
        [lerp(xCollar, xShoulder, t1), lerp(yCollar, yShoulder, t1) + w * 0.7]
      ], 0.55);

      // Specular lemon-cream highlight on top of each cord twist
      brush.set("finepencil", PAL.yolkPale, 0.85);
      mLine(mx - dir * 5, my - w * 0.45, mx + dir * 5, my - w * 0.15);

      // Crisp black pen outline separating each twisted strand
      brush.set("rotring", PAL.black, 0.52);
      mSpline([
        [lerp(xCollar, xShoulder, t0), lerp(yCollar, yShoulder, t0) + w * 0.75],
        [mx, my - w * 0.9],
        [lerp(xCollar, xShoulder, t1), lerp(yCollar, yShoulder, t1) + w * 0.75]
      ], 0.55);
    }

    // 3. Heavy Bullion Fringe hanging from the outer crescent of the epaulette
    const fringeCount = 20;
    for (let f = 0; f < fringeCount; f++) {
      const u = f / (fringeCount - 1);
      // Curve along outer crescent from mid-shoulder out to shoulder tip
      const fx0 = lerp(xCollar + dir * 82, xShoulder + dir * 12, u);
      const fy0 = lerp(yCollar + 22, yShoulder + 12, u) + Math.sin(u * Math.PI) * 14;
      const len = lerp(34, 58, Math.sin(u * Math.PI * 0.85 + 0.15));
      const sway = dir * (6 + u * 12);
      const fx1 = fx0 + sway * 0.5;
      const fy1 = fy0 + len * 0.55;
      const fx2 = fx0 + sway;
      const fy2 = fy0 + len;

      // Cobalt & black cast shadow behind each bullion tassel
      brush.set("cpencil", PAL.cobaltDeep, 0.95);
      mSpline([[fx0 + 2, fy0 + 2], [fx1 + 2, fy1 + 2], [fx2 + 2, fy2 + 2]], 0.35);

      // Deep ochre-vermilion core
      brush.set("cpencil", PAL.yolkDeep, 1.0);
      mSpline([[fx0, fy0], [fx1, fy1], [fx2, fy2]], 0.35);

      // Bright egg-yolk bullion body
      brush.set("cpencil", PAL.yolkBright, 0.85);
      mSpline([[fx0 - 1.5, fy0], [fx1 - 1.5, fy1], [fx2 - 1, fy2]], 0.35);

      // Cream-white metallic glint along the bullion coil
      brush.set("finepencil", PAL.creamLight, 0.65);
      mLine(fx0 - 1.5, fy0 + 6, fx1 - 1.5, fy1 - 2);

      // Crisp black pen wire-coil rings & contour on every tassel
      brush.set("rotring", PAL.black, 0.45);
      mSpline([[fx0 - 3, fy0], [fx1 - 3, fy1], [fx2, fy2 + 2]], 0.35);
      for (let r = 0.2; r <= 0.85; r += 0.22) {
        const rx = lerp(fx0, fx2, r);
        const ry = lerp(fy0, fy2, r);
        mLine(rx - 3, ry, rx + 2.5, ry + 1.5);
      }
    }
  }

  renderShoulderEpaulette(-1);
  renderShoulderEpaulette(1);

  // 4. Braided Aiguillette (Swagging Gold Shoulder Cords across the Left Chest)
  const swags = [
    { x0: 245, y0: 558, xm: 305, ym: 688, x1: 445, y1: 508, braids: 24 },
    { x0: 225, y0: 572, xm: 288, ym: 748, x1: 432, y1: 595, braids: 28 },
    { x0: 268, y0: 552, xm: 335, ym: 635, x1: 445, y1: 508, braids: 20 }
  ];

  for (let sw of swags) {
    // Cast shadow on the cobalt wool coat beneath the hanging cord
    let shadowPts = [];
    for (let i = 0; i <= 16; i++) {
      const t = i / 16;
      const x = (1 - t) * (1 - t) * sw.x0 + 2 * (1 - t) * t * sw.xm + t * t * sw.x1;
      const y = (1 - t) * (1 - t) * sw.y0 + 2 * (1 - t) * t * sw.ym + t * t * sw.y1;
      shadowPts.push([x + 5, y + 8]);
    }
    brush.set("burnish", PAL.blackCool, 1.15);
    mSpline(shadowPts, 0.45);

    // Individual plaited gold links along the catenary curve
    for (let i = 0; i < sw.braids; i++) {
      const t0 = i / sw.braids;
      const t1 = (i + 1) / sw.braids;
      const tm = (t0 + t1) * 0.5;
      const x0 = (1 - t0) * (1 - t0) * sw.x0 + 2 * (1 - t0) * t0 * sw.xm + t0 * t0 * sw.x1;
      const y0 = (1 - t0) * (1 - t0) * sw.y0 + 2 * (1 - t0) * t0 * sw.ym + t0 * t0 * sw.y1;
      const x1 = (1 - t1) * (1 - t1) * sw.x0 + 2 * (1 - t1) * t1 * sw.xm + t1 * t1 * sw.x1;
      const y1 = (1 - t1) * (1 - t1) * sw.y0 + 2 * (1 - t1) * t1 * sw.ym + t1 * t1 * sw.y1;
      const xm = (1 - tm) * (1 - tm) * sw.x0 + 2 * (1 - tm) * tm * sw.xm + tm * tm * sw.x1;
      const ym = (1 - tm) * (1 - tm) * sw.y0 + 2 * (1 - tm) * tm * sw.ym + tm * tm * sw.y1;

      const dx = x1 - x0, dy = y1 - y0;
      const len = Math.hypot(dx, dy) || 1;
      const nx = -dy / len, ny = dx / len;
      const w = 5.5;

      // Vermilion-ochre shadow strand
      brush.set("cpencil", PAL.vermDark, 0.85);
      mLine(x0 + nx * w, y0 + ny * w, x1 - nx * w, y1 - ny * w);

      // Egg-yolk gold main plait
      brush.set("cpencil", PAL.yolk, 1.05);
      mLine(x0 - nx * w, y0 - ny * w, x1 + nx * w, y1 + ny * w);

      // Bright yellow-cream crown highlight
      brush.set("finepencil", PAL.yolkPale, 0.75);
      mLine(xm - nx * (w * 0.6), ym - ny * (w * 0.6), xm + dx * 0.25, ym + dy * 0.25);

      // Crisp black pen plait notch
      brush.set("rotring", PAL.black, 0.45);
      mLine(x0 - nx * w, y0 - ny * w, xm + nx * w, ym + ny * w);
      mLine(xm - nx * w, ym - ny * w, x1 + nx * w, y1 + ny * w);
    }
  }
}

