  // --- B. HYPERREAL EYES (LEFT AT 508,312; RIGHT AT 600,312) ---
  function renderEye(ex, ey, isLeft) {
    const dir = isLeft ? -1 : 1;
    // Eye socket shadow & tear trough bags
    brush.set("cpencil", PAL.cobaltMid, 0.68);
    mContourShade(
      [[ex - 24, ey - 14], [ex, ey - 18], [ex + 24, ey - 12]],
      [[ex - 22, ey - 5], [ex, ey - 8], [ex + 22, ey - 4]],
      9, 0.45, 0.3
    );
    // Tear trough & under-eye bags in vermilion + cobalt
    brush.set("finepencil", PAL.verm, 0.65);
    mContourShade(
      [[ex - 22, ey + 7], [ex, ey + 11], [ex + 22, ey + 7]],
      [[ex - 20, ey + 19], [ex, ey + 24], [ex + 20, ey + 17]],
      10, 0.45, 0.3
    );
    brush.set("finepencil", PAL.cobalt, 0.65);
    mSpline([[ex - 21, ey + 15], [ex, ey + 21], [ex + 20, ey + 14]], 0.45);
    mSpline([[ex - 18, ey + 22], [ex + 2, ey + 27], [ex + 18, ey + 20]], 0.45);

    // Sclera (eyeball white shaded in cool icy cobalt)
    const sclera = [
      [ex - 19, ey + 1], [ex - 8, ey - 7], [ex + 8, ey - 7],
      [ex + 19, ey + 1], [ex + 8, ey + 7], [ex - 8, ey + 7]
    ];
    mPolyFill(sclera, PAL.creamLight, 235, true);
    brush.set("finepencil", PAL.cobaltIce, 0.55);
    mLine(ex - 16, ey - 2, ex + 16, ey - 2);
    mLine(ex - 15, ey - 4, ex + 15, ey - 4);

    // Pinkish vermilion tear duct (caruncle)
    brush.set("finepencil", PAL.verm, 0.8);
    const tearX = isLeft ? ex + 16 : ex - 16;
    mLine(tearX - 2, ey + 1, tearX + 2, ey + 1);

    // Iris: radial cobalt blue fibres & dark limbal ring
    const ir = 7.2;
    for (let a = 0; a < 360; a += 15) {
      const col = (a % 30 === 0) ? PAL.cobaltDark : PAL.cobaltMid;
      brush.set("finepencil", col, 0.62);
      mLine(
        ex + cos(a) * 2.2, ey + sin(a) * 2.0,
        ex + cos(a) * ir, ey + sin(a) * (ir * 0.92)
      );
    }
    // Lower iris icy cobalt crescent catchlight
    brush.set("finepencil", PAL.cobaltIce, 0.72);
    for (let a = 25; a <= 155; a += 18) {
      mLine(
        ex + cos(a) * 3.0, ey + sin(a) * 2.8,
        ex + cos(a) * (ir - 1), ey + sin(a) * (ir * 0.82)
      );
    }
    // Pupil & limbal ring in jet black
    brush.set("rotring", PAL.black, 0.95);
    for (let r = 0.8; r <= 2.8; r += 0.7) {
      let pPts = [];
      for (let a = 0; a <= 360; a += 45) {
        pPts.push([ex + cos(a) * r, ey + sin(a) * r]);
      }
      mSpline(pPts, 0.5);
    }
    // Limbal ring
    brush.set("rotring", PAL.cobaltDeep, 0.58);
    let limbPts = [];
    for (let a = 0; a <= 360; a += 30) {
      limbPts.push([ex + cos(a) * ir, ey + sin(a) * (ir * 0.9)]);
    }
    mSpline(limbPts, 0.5);

    // Crisp upper & lower eyelid folds in black pen
    brush.set("rotring", PAL.black, 0.78);
    mSpline([[ex - 21, ey + 2], [ex - 8, ey - 7], [ex + 8, ey - 7], [ex + 20, ey + 2]], 0.45);
    brush.set("rotring", PAL.black, 0.48);
    mSpline([[ex - 19, ey + 2], [ex - 7, ey + 7.5], [ex + 8, ey + 7.5], [ex + 19, ey + 2]], 0.45);
    // Epicanthic / upper lid crease
    mSpline([[ex - 22, ey - 3], [ex - 6, ey - 11.5], [ex + 9, ey - 11], [ex + 21, ey - 2]], 0.45);

    // Crow's feet radiating from outer corner
    const outerX = isLeft ? ex - 21 : ex + 21;
    brush.set("finepencil", PAL.cobaltDark, 0.58);
    mLine(outerX, ey - 2, outerX + dir * 14, ey - 7);
    mLine(outerX, ey + 1, outerX + dir * 16, ey + 2);
    mLine(outerX, ey + 4, outerX + dir * 13, ey + 9);

    // Wet corneal specular window highlight + lower lid tear-film glint
    brush.set("cpencil", PAL.creamLight, 1.05);
    mLine(ex - 3.5, ey - 3.5, ex - 1.2, ey - 2.2);
    mLine(ex + 2.2, ey + 2.5, ex + 3.5, ey + 3.2);
    mLine(ex - 6, ey + 6.5, ex + 5, ey + 6.5);

    // Bushy salt-and-pepper eyebrows (individual hairs in black, cobalt & cream)
    for (let i = 0; i < 34; i++) {
      const u = i / 33;
      const bx = lerp(ex - 24, ex + 24, u);
      const by = ey - 16 - Math.sin(u * Math.PI) * 5 + random(-1.5, 1.5);
      const ang = isLeft ? lerp(-155, -110, u) : lerp(-70, -25, u);
      const len = random(6, 11);
      const col = (i % 5 === 0) ? PAL.creamLight : (i % 2 === 0 ? PAL.black : PAL.cobaltDeep);
      brush.set("finepencil", col, 0.68);
      mLine(bx, by, bx + cos(ang) * len, by + sin(ang) * len);
    }
  }

  renderEye(508, 312, true);
  renderEye(600, 312, false);

  // Glabella (frown lines between eyebrows)
  brush.set("finepencil", PAL.cobaltDark, 0.68);
  mLine(546, 282, 548, 304);
  mLine(562, 282, 560, 304);

  // --- C. LIPS & STERN MOUTH ---
  // Upper lip in dark vermilion & cool cobalt shadow
  const upperLip = [
    [514, 405], [538, 396], [554, 399], [570, 396],
    [594, 405], [554, 407]
  ];
  const lowerLip = [
    [518, 405], [554, 407], [590, 405],
    [576, 419], [554, 422], [532, 419]
  ];
  mPolyFill(upperLip, PAL.vermDark, 210, true);
  mPolyFill(lowerLip, PAL.vermMid, 185, true);

  // Vertical lip crease hatching
  brush.set("finepencil", PAL.cobaltDark, 0.58);
  for (let x = 522; x <= 586; x += 4) {
    mLine(x, 398, x, 405);
  }
  brush.set("finepencil", PAL.vermDark, 0.58);
  for (let x = 526; x <= 582; x += 4.5) {
    mLine(x, 407, x, 419);
  }
  // Lower lip specular highlight
  brush.set("finepencil", PAL.creamLight, 0.78);
  mSpline([[534, 412], [554, 414], [572, 412]], 0.4);
  // Deep shadow under lower lip (mentolabial sulcus)
  brush.set("cpencil", PAL.cobaltDark, 0.78);
  mHatchQuad([530, 421], [578, 421], [570, 432], [538, 432], 10, 0.4);

  // --- D. HYPERREAL STUBBLE (SALT-AND-PEPPER 5-O'CLOCK SHADOW & WHISKERS) ---
  // Underlying cool slate-cobalt follicular shadow across jaw, chin & upper lip
  brush.set("burnish", PAL.cobaltLight, 0.65);
  mContourShade(
    [[462, 382], [505, 428], [554, 436], [603, 428], [646, 382]],
    [[478, 436], [516, 458], [554, 468], [592, 458], [630, 436]],
    18, 0.45, 0.8
  );

  // 680 individual directional stubble hairs (jet black, deep cobalt, vermilion pore, cream-white grey hairs)
  const jawZone = [
    [454, 362], [488, 385], [514, 384], [554, 382], [594, 384],
    [620, 385], [654, 362], [646, 414], [612, 454], [554, 470],
    [496, 454], [462, 414]
  ];
  const mouthExclude = [
    [512, 395], [596, 395], [592, 423], [516, 423]
  ];

  for (let pass = 0; pass < 4; pass++) {
    let col, w, count;
    if (pass === 0) {
      col = PAL.vermDark; w = 0.48; count = 130; // warm follicle shadow
    } else if (pass === 1) {
      col = PAL.cobaltDeep; w = 0.55; count = 220; // cool dark bristle shadow
    } else if (pass === 2) {
      col = PAL.black; w = 0.58; count = 210; // jet black stubble
    } else {
      col = PAL.creamLight; w = 0.62; count = 125; // glistening silver/white catchlight bristles
    }
    brush.set("finepencil", col, w);

    for (let i = 0; i < count; i++) {
      const sx = random(456, 652);
      const sy = random(365, 468);
      if (!ptInPoly(sx, sy, jawZone)) continue;
      if (ptInPoly(sx, sy, mouthExclude)) continue;

      // Hair growth direction radiates downward and slightly outward from nose/chin center
      const dx = sx - 554;
      const baseAng = 90 - dx * 0.32 + random(-12, 12);
      // Shorter, denser bristles on upper lip; slightly longer on chin & jawline
      const isMoustache = (sy < 397 && sx > 512 && sx < 596);
      const hLen = isMoustache ? random(2.8, 5.2) : random(2.2, 4.6);
      mLine(sx, sy, sx + cos(baseAng) * hLen, sy + sin(baseAng) * hLen);
    }
  }
}

