// ============================================================================
// 8. BRASS BUTTONS REFLECTING THE STREET (HERO FISHEYE CONVEX MIRRORS)
// ============================================================================
function drawStreetButton(cx, cy, R, isHero = true) {
  // 1. Cast shadow under button on wool coat
  let shadowPoly = [];
  for (let a = 0; a < 360; a += 20) {
    shadowPoly.push([cx + 4 + cos(a) * (R + 3), cy + 6 + sin(a) * (R + 3)]);
  }
  mPolyFill(shadowPoly, PAL.black, 225, true);

  // 2. Outer metallic brass bezel
  let bezelPoly = [];
  for (let a = 0; a < 360; a += 18) {
    bezelPoly.push([cx + cos(a) * R, cy + sin(a) * R]);
  }
  mPolyFill(bezelPoly, PAL.yolk, 235, true);

  if (isHero) {
    // 3. Convex Dome Interior: Fisheye Street Reflection
    const rIn = R * 0.84;

    // A. Upper dome: Cool cobalt & cream sky canyon between curved tall buildings
    let skyPoly = [];
    for (let a = 200; a <= 340; a += 15) {
      skyPoly.push([cx + cos(a) * rIn, cy + sin(a) * rIn]);
    }
    skyPoly.push([cx + rIn * 0.45, cy + rIn * 0.05]);
    skyPoly.push([cx, cy - rIn * 0.12]);
    skyPoly.push([cx - rIn * 0.45, cy + rIn * 0.05]);
    mPolyFill(skyPoly, PAL.cobaltIce, 220, true);

    // B. Left & Right warped building facades in deep cobalt & black
    let leftBldg = [
      [cx - rIn * 0.96, cy - rIn * 0.25],
      [cx - rIn * 0.42, cy - rIn * 0.85],
      [cx - rIn * 0.22, cy + rIn * 0.18],
      [cx - rIn * 0.88, cy + rIn * 0.45]
    ];
    let rightBldg = [
      [cx + rIn * 0.42, cy - rIn * 0.85],
      [cx + rIn * 0.96, cy - rIn * 0.25],
      [cx + rIn * 0.88, cy + rIn * 0.45],
      [cx + rIn * 0.22, cy + rIn * 0.18]
    ];
    mPolyFill(leftBldg, PAL.cobaltDeep, 235, true);
    mPolyFill(rightBldg, PAL.cobaltDeep, 235, true);

    // C. Lower dome: Wet dark asphalt street surface reflecting taxi & hotel canopy
    let streetPoly = [];
    for (let a = 20; a <= 160; a += 15) {
      streetPoly.push([cx + cos(a) * rIn, cy + sin(a) * rIn]);
    }
    streetPoly.push([cx - rIn * 0.85, cy + rIn * 0.18]);
    streetPoly.push([cx, cy + rIn * 0.08]);
    streetPoly.push([cx + rIn * 0.85, cy + rIn * 0.18]);
    mPolyFill(streetPoly, PAL.blackCool, 235, true);

    // D. Fisheye perspective lines of building windows & cornice arches
    brush.set("finepencil", PAL.yolkBright, 0.65);
    for (let h = -0.55; h <= 0.1; h += 0.22) {
      // Left building curved window rows
      mSpline([
        [cx - rIn * 0.88, cy + rIn * (h + 0.18)],
        [cx - rIn * 0.55, cy + rIn * h],
        [cx - rIn * 0.24, cy + rIn * (h + 0.12)]
      ], 0.5);
      // Right building curved window rows
      mSpline([
        [cx + rIn * 0.24, cy + rIn * (h + 0.12)],
        [cx + rIn * 0.55, cy + rIn * h],
        [cx + rIn * 0.88, cy + rIn * (h + 0.18)]
      ], 0.5);
    }

    // E. Vermilion hotel awning & taillight streak reflected in the brass
    brush.set("cpencil", PAL.verm, 0.95);
    mSpline([
      [cx - rIn * 0.72, cy + rIn * 0.22],
      [cx - rIn * 0.35, cy + rIn * 0.12],
      [cx - rIn * 0.12, cy + rIn * 0.18]
    ], 0.45);
    mLine(cx + rIn * 0.25, cy + rIn * 0.35, cx + rIn * 0.58, cy + rIn * 0.28);

    // F. Yellow Taxi Cab & streetlamp reflection on the wet street curve
    brush.set("cpencil", PAL.yolkBright, 1.1);
    mSpline([
      [cx - rIn * 0.28, cy + rIn * 0.42],
      [cx + rIn * 0.05, cy + rIn * 0.36],
      [cx + rIn * 0.35, cy + rIn * 0.46]
    ], 0.45);
    // Warm golden brass reflection rim along the lower-right curve
    brush.set("cpencil", PAL.yolk, 0.95);
    let lowerArc = [];
    for (let a = 15; a <= 145; a += 18) {
      lowerArc.push([cx + cos(a) * (rIn * 0.92), cy + sin(a) * (rIn * 0.92)]);
    }
    mSpline(lowerArc, 0.5);

    // G. Blinding cream-white curved specular sky/sun highlight on upper-left dome
    brush.set("cpencil", PAL.creamLight, 1.15);
    let glintArc = [];
    for (let a = 205; a <= 265; a += 15) {
      glintArc.push([cx + cos(a) * (rIn * 0.72), cy + sin(a) * (rIn * 0.72)]);
    }
    mSpline(glintArc, 0.5);
    // Headlight pinpricks on street
    mLine(cx - 4, cy + rIn * 0.38, cx - 1, cy + rIn * 0.38);
    mLine(cx + 5, cy + rIn * 0.40, cx + 8, cy + rIn * 0.40);
    // Streetlamp glow dot
    mLine(cx - rIn * 0.22, cy - rIn * 0.15, cx - rIn * 0.18, cy - rIn * 0.15);
  } else {
    // Smaller secondary brass button with horizon & sky glint
    brush.set("cpencil", PAL.cobaltDeep, 0.95);
    mLine(cx - R * 0.7, cy, cx + R * 0.7, cy);
    mLine(cx - R * 0.6, cy + 3, cx + R * 0.6, cy + 3);
    brush.set("cpencil", PAL.verm, 0.8);
    mLine(cx - R * 0.5, cy + 5, cx + R * 0.4, cy + 5);
    brush.set("cpencil", PAL.creamLight, 0.95);
    mLine(cx - R * 0.45, cy - R * 0.45, cx + R * 0.1, cy - R * 0.55);
  }

  // 4. Crisp black pen concentric bezel rings & embossed rim ticks
  brush.set("rotring", PAL.black, 0.72);
  let outerRing = [];
  let innerRing = [];
  for (let a = 0; a <= 360; a += 20) {
    outerRing.push([cx + cos(a) * R, cy + sin(a) * R]);
    innerRing.push([cx + cos(a) * (R * 0.84), cy + sin(a) * (R * 0.84)]);
  }
  mSpline(outerRing, 0.5);
  brush.set("rotring", PAL.black, 0.5);
  mSpline(innerRing, 0.5);
}

