// ============================================================================
// 10. DIAGONAL DIVIDING SASH, ROUNDED-CORNER BORDER & PLAYING CARD INDICES
// ============================================================================
function drawCardFrameAndIndices() {
  // --- A. DIAGONAL DIVIDING BAND FROM (76, 842) TO (1124, 358) ---
  const xA = 76, yA = 842, xB = 1124, yB = 358;
  const dx = xB - xA, dy = yB - yA;
  const len = Math.hypot(dx, dy);
  const nx = -dy / len, ny = dx / len; // normal vector
  const w = BAND_HALF;

  // Fill diagonal sash with cream & gold base so the cut is razor-clean
  const sashPoly = [
    [xA + nx * w, yA + ny * w],
    [xB + nx * w, yB + ny * w],
    [xB - nx * w, yB - ny * w],
    [xA - nx * w, yA - ny * w]
  ];
  brush.noStroke();
  brush.wash(PAL.cream, 255);
  brush.beginShape(0);
  for (let p of sashPoly) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noWash();

  // Geometric gold & vermilion guilloche zig-zag inside the diagonal sash
  const steps = 68;
  for (let i = 0; i < steps; i++) {
    const t0 = i / steps;
    const t1 = (i + 1) / steps;
    const px0 = lerp(xA, xB, t0), py0 = lerp(yA, yB, t0);
    const px1 = lerp(xA, xB, t1), py1 = lerp(yA, yB, t1);
    const s = (i % 2 === 0) ? 1 : -1;
    brush.set("cpencil", (i % 2 === 0) ? PAL.yolk : PAL.verm, 0.85);
    brush.line(px0 + nx * (w * 0.72 * s), py0 + ny * (w * 0.72 * s), px1 - nx * (w * 0.72 * s), py1 - ny * (w * 0.72 * s));
  }

  // Crisp double black pen rules along the diagonal sash
  brush.set("rotring", PAL.black, 0.95);
  brush.line(xA + nx * w, yA + ny * w, xB + nx * w, yB + ny * w);
  brush.line(xA - nx * w, yA - ny * w, xB - nx * w, yB - ny * w);
  brush.set("rotring", PAL.cobaltDark, 0.52);
  brush.line(xA + nx * (w + 3.5), yA + ny * (w + 3.5), xB + nx * (w + 3.5), yB + ny * (w + 3.5));
  brush.line(xA - nx * (w + 3.5), yA - ny * (w + 3.5), xB - nx * (w + 3.5), yB - ny * (w + 3.5));

  // Central heraldic diamond rosette at (600, 600)
  const dR = 16;
  const rosette = [[600 - dR * 1.4, 600], [600, 600 - dR], [600 + dR * 1.4, 600], [600, 600 + dR]];
  brush.noStroke();
  brush.wash(PAL.verm, 245);
  brush.beginShape(0);
  for (let p of rosette) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noWash();

  brush.set("cpencil", PAL.yolkBright, 1.0);
  brush.line(600 - 10, 600, 600 + 10, 600);
  brush.line(600, 600 - 7, 600, 600 + 7);
  brush.set("rotring", PAL.black, 0.85);
  brush.spline([...rosette, rosette[0]], 0.15);

  // --- B. THIN ROUNDED-CORNER BORDER ENCLOSING EVERYTHING ---
  function drawRoundedRect(x1, y1, x2, y2, r) {
    // Top, Bottom, Left, Right straight lines
    brush.line(x1 + r, y1, x2 - r, y1);
    brush.line(x1 + r, y2, x2 - r, y2);
    brush.line(x1, y1 + r, x1, y2 - r);
    brush.line(x2, y1 + r, x2, y2 - r);
    // Four rounded corners
    const corners = [
      { cx: x1 + r, cy: y1 + r, a0: 180, a1: 270 },
      { cx: x2 - r, cy: y1 + r, a0: 270, a1: 360 },
      { cx: x2 - r, cy: y2 - r, a0: 0, a1: 90 },
      { cx: x1 + r, cy: y2 - r, a0: 90, a1: 180 }
    ];
    for (let c of corners) {
      let pts = [];
      for (let a = c.a0; a <= c.a1; a += 15) {
        pts.push([c.cx + cos(a) * r, c.cy + sin(a) * r]);
      }
      brush.spline(pts, 0.45);
    }
  }

  // Colored pencil hairline between the double rounded borders
  brush.set("cpencil", PAL.cobalt, 0.85);
  drawRoundedRect(70, 70, 1130, 1130, 32);
  brush.set("cpencil", PAL.verm, 0.65);
  drawRoundedRect(73, 73, 1127, 1127, 30);

  // Outer and inner crisp black pen rounded-corner borders
  brush.set("rotring", PAL.black, 1.05);
  drawRoundedRect(64, 64, 1136, 1136, 36);
  brush.set("rotring", PAL.black, 0.68);
  drawRoundedRect(76, 76, 1124, 1124, 26);

  // --- C. PLAYING CARD CORNER INDICES ("K" + HOTEL SPADE-KEY EMBLEM) ---
  // Drawn at upper-left (142, 148) and automatically mirrored upside-down at (1058, 1052)
  const kx = 142, ky = 145;

  // Classic Serif "K" in Vermilion, Gold & Jet Black Pen
  const kStem = [[kx - 22, ky - 36], [kx - 11, ky - 36], [kx - 11, ky + 36], [kx - 22, ky + 36]];
  const kArmUp = [[kx - 11, ky + 2], [kx + 12, ky - 36], [kx + 23, ky - 36], [kx - 2, ky + 4]];
  const kArmDn = [[kx - 4, ky - 4], [kx + 24, ky + 36], [kx + 11, ky + 36], [kx - 11, ky + 4]];
  mPolyFill(kStem, PAL.verm, 240, true);
  mPolyFill(kArmUp, PAL.verm, 240, true);
  mPolyFill(kArmDn, PAL.verm, 240, true);

  // Gold shadow trim on "K"
  brush.set("cpencil", PAL.yolk, 0.95);
  mLine(kx - 8, ky - 34, kx - 8, ky + 34);
  mLine(kx + 25, ky - 34, kx + 3, ky + 1);
  mLine(kx + 2, ky - 2, kx + 27, ky + 34);

  // Crisp black pen serifs & outline of "K"
  brush.set("rotring", PAL.black, 0.72);
  mLine(kx - 27, ky - 36, kx - 5, ky - 36);
  mLine(kx - 27, ky + 36, kx - 5, ky + 36);
  mLine(kx + 6, ky - 36, kx + 28, ky - 36);
  mLine(kx + 6, ky + 36, kx + 28, ky + 36);
  mLine(kx - 22, ky - 36, kx - 22, ky + 36);
  mLine(kx - 11, ky - 36, kx - 11, ky + 36);
  mLine(kx - 11, ky + 2, kx + 12, ky - 36);
  mLine(kx + 23, ky - 36, kx - 2, ky + 2);
  mLine(kx - 2, ky - 2, kx + 24, ky + 36);
  mLine(kx + 11, ky + 36, kx - 11, ky + 4);

  // Suit Pip below "K": Heraldic Spade-Key at (142, 238)
  const sx = 142, sy = 236;
  const spadePoly = [
    [sx, sy - 30],
    [sx + 24, sy - 4],
    [sx + 22, sy + 12],
    [sx + 8, sy + 16],
    [sx, sy + 6],
    [sx - 8, sy + 16],
    [sx - 22, sy + 12],
    [sx - 24, sy - 4]
  ];
  mPolyFill(spadePoly, PAL.cobaltDeep, 245, true);

  // Gold hotel key stem & bit below the spade
  brush.set("cpencil", PAL.yolkBright, 1.15);
  mLine(sx, sy + 8, sx, sy + 36);
  mLine(sx, sy + 26, sx + 10, sy + 26);
  mLine(sx, sy + 32, sx + 10, sy + 32);
  mLine(sx - 9, sy + 36, sx + 9, sy + 36);

  // Crisp black pen outline on Spade-Key pip
  brush.set("rotring", PAL.black, 0.72);
  mSpline([
    [sx, sy - 30], [sx + 24, sy - 4], [sx + 22, sy + 12],
    [sx + 8, sy + 16], [sx, sy + 6], [sx - 8, sy + 16],
    [sx - 22, sy + 12], [sx - 24, sy - 4], [sx, sy - 30]
  ], 0.35);
  mLine(sx, sy + 8, sx, sy + 36);
  mLine(sx - 9, sy + 36, sx + 9, sy + 36);
}

