// ============================================================================
// ANATOMICAL 3D FACE TOPOGRAPHY & EYE GEOMETRY
// ============================================================================

const FACE = {
  cx: 600,
  cy: 560,
  leftEye: { x: 352, y: 492, hw: 118, ir: 49, ix: 357, iy: 486 },
  rightEye: { x: 848, y: 482, hw: 118, ir: 49, ix: 843, iy: 476 },
  noseTip: { x: 602, y: 832 },
  lipCenter: { x: 602, y: 1118 }
};

function gauss2D(x, y, cx, cy, rx, ry) {
  let dx = (x - cx) / rx;
  let dy = (y - cy) / ry;
  return Math.exp(-(dx * dx + dy * dy));
}

// Exact upper/lower eyelid and crease geometry for either eye
function getEyeGeometry(x, y, eye, isRight) {
  let dx = x - eye.x;
  // Normalize t from -1 (inner medial canthus) to +1 (outer lateral canthus)
  let t = isRight ? dx / eye.hw : -dx / eye.hw;
  let tilt = isRight ? -0.04 * dx : 0.04 * dx; // subtle natural canthal tilt

  let inSpan = Math.abs(t) <= 1.04;
  let tc = constrain(t, -1, 1);
  let env = Math.pow(Math.max(0, 1 - tc * tc), 0.78);

  // Almond contour: upper lid peaks slightly medial (t ~ -0.16), lower lid dips slightly lateral (t ~ +0.18)
  let yUpper = eye.y + tilt - 49 * env * (1 - 0.15 * tc);
  let yLower = eye.y + tilt + 41 * env * (1 + 0.18 * tc);

  // Medial lacrimal caruncle bay (inner corner tear duct extension)
  if (t < -0.78 && t >= -1.16) {
    let ct = map(t, -1.16, -0.78, 0, 1);
    let carEnv = Math.sin(constrain(ct, 0, 1) * 180);
    yUpper = lerp(eye.y + tilt + 6, yUpper, constrain(ct, 0, 1)) - 5 * carEnv;
    yLower = lerp(eye.y + tilt + 10, yLower, constrain(ct, 0, 1)) + 6 * carEnv;
    inSpan = true;
  }

  // Tarsal eyelid crease above upper lid
  let creaseEnv = Math.pow(Math.max(0, 1 - Math.pow(constrain(t * 0.92, -1, 1), 2)), 0.72);
  let yCrease = eye.y + tilt - (82 + 8 * tc) * creaseEnv;

  // Lower tear trough / orbital rim groove
  let yTearTrough = eye.y + tilt + (74 + 14 * tc) * creaseEnv;

  return {
    inSpan,
    t,
    yUpper,
    yLower,
    yCrease,
    yTearTrough,
    isInsideOpening: inSpan && y >= yUpper && y <= yLower
  };
}

// 3D heightfield z(x, y) in canvas units (0..180) for lighting, Langer lines & tulle warping
function getFaceHeight(x, y) {
  // Base cranial/facial cylinder
  let nx = (x - 600) / 680;
  let ny = (y - 580) / 820;
  let z = 95 * Math.sqrt(Math.max(0.05, 1 - 0.72 * nx * nx - 0.28 * ny * ny));

  // Forehead dome & brow ridge
  z += 22 * gauss2D(x, y, 600, 190, 420, 220);
  z += 18 * gauss2D(x, y, 330, 355, 165, 52); // left superciliary arch
  z += 18 * gauss2D(x, y, 870, 345, 165, 52); // right superciliary arch
  z += 9 * gauss2D(x, y, 600, 365, 85, 55);   // glabella

  // Orbital sockets (concave depressions)
  z -= 32 * gauss2D(x, y, 365, 485, 145, 105);
  z -= 32 * gauss2D(x, y, 835, 475, 145, 105);

  // Eyeball & eyelid spheres nested inside sockets
  z += 28 * gauss2D(x, y, 355, 492, 82, 58);
  z += 28 * gauss2D(x, y, 845, 482, 82, 58);

  // Sharp tarsal crease indent
  let gL = getEyeGeometry(x, y, FACE.leftEye, false);
  if (Math.abs(gL.t) < 1.1) {
    z -= 7 * Math.exp(-Math.pow((y - gL.yCrease) / 7.5, 2));
    z += 5 * Math.exp(-Math.pow((y - (gL.yUpper - 14)) / 11, 2)); // mobile lid roll
    z -= 4 * Math.exp(-Math.pow((y - gL.yTearTrough) / 14, 2));   // tear trough
  }
  let gR = getEyeGeometry(x, y, FACE.rightEye, true);
  if (Math.abs(gR.t) < 1.1) {
    z -= 7 * Math.exp(-Math.pow((y - gR.yCrease) / 7.5, 2));
    z += 5 * Math.exp(-Math.pow((y - (gR.yUpper - 14)) / 11, 2));
    z -= 4 * Math.exp(-Math.pow((y - gR.yTearTrough) / 14, 2));
  }

  // Nose bridge, dorsum, tip (pronasale) and alae (wings)
  if (y > 380 && y < 930) {
    let bridgeT = constrain((y - 420) / 412, 0, 1);
    let bridgeWidth = lerp(42, 34, Math.sin(bridgeT * 140)) + 22 * Math.pow(bridgeT, 3);
    let bridgeHeight = lerp(18, 62, Math.pow(bridgeT, 0.88));
    let noseEnv = Math.exp(-Math.pow((x - 601) / bridgeWidth, 2));
    let vertCutoff = y < 835 ? 1.0 : Math.exp(-Math.pow((y - 835) / 48, 2));
    z += bridgeHeight * noseEnv * vertCutoff;
  }
  // Bulbous nasal tip & alae
  z += 24 * gauss2D(x, y, 602, 830, 52, 46);
  z += 19 * gauss2D(x, y, 504, 858, 46, 36); // left ala
  z += 19 * gauss2D(x, y, 698, 854, 46, 36); // right ala
  // Nostril cavities
  z -= 22 * gauss2D(x, y, 544, 882, 26, 16);
  z -= 22 * gauss2D(x, y, 658, 878, 26, 16);

  // Zygomatic arches & malar cheek pads
  z += 26 * gauss2D(x, y, 225, 705, 175, 145);
  z += 26 * gauss2D(x, y, 975, 695, 175, 145);
  z += 14 * gauss2D(x, y, 395, 735, 120, 110);
  z += 14 * gauss2D(x, y, 805, 725, 120, 110);

  // Philtrum columns & groove
  z += 10 * gauss2D(x, y, 566, 980, 22, 65);
  z += 10 * gauss2D(x, y, 636, 978, 22, 65);
  z -= 9 * gauss2D(x, y, 601, 982, 24, 60);

  // Upper & lower lips
  let lipDx = (x - 602) / 195;
  if (Math.abs(lipDx) < 1.2 && y > 1015) {
    let bowDip = 12 * Math.exp(-Math.pow((x - 602) / 28, 2));
    let upperPeakY = 1044 + bowDip + 38 * lipDx * lipDx;
    let partY = 1122 + 8 * lipDx * lipDx - 4 * Math.exp(-Math.pow((x - 602) / 45, 2));
    // Upper lip volume
    if (y >= upperPeakY - 20 && y <= partY + 10) {
      let ut = (y - upperPeakY) / Math.max(10, partY - upperPeakY);
      if (ut >= 0 && ut <= 1) {
        z += 24 * Math.sin(ut * 180) * Math.exp(-0.8 * lipDx * lipDx);
      }
      // Crisp vermilion ridge highlight
      z += 5 * Math.exp(-Math.pow((y - upperPeakY) / 5, 2)) * Math.exp(-lipDx * lipDx);
    }
    // Lower lip fullness
    if (y > partY - 5) {
      let lt = constrain((y - partY) / 92, 0, 1);
      z += 31 * Math.sin(lt * 165) * Math.exp(-0.9 * lipDx * lipDx);
    }
    // Oral parting groove
    z -= 14 * Math.exp(-Math.pow((y - partY) / 6, 2)) * Math.exp(-1.1 * lipDx * lipDx);
  }

  return z;
}

// Compute 3D surface normal, lighting, subsurface scattering & skin tension flow angle
function getFaceShading(x, y) {
  let eps = 3.0;
  let zc = getFaceHeight(x, y);
  let zx = (getFaceHeight(x + eps, y) - getFaceHeight(x - eps, y)) / (2 * eps);
  let zy = (getFaceHeight(x, y + eps) - getFaceHeight(x, y - eps)) / (2 * eps);

  // Surface normal N = normalize(-zx, -zy, 1)
  let invLen = 1.0 / Math.sqrt(zx * zx + zy * zy + 1.0);
  let nx = -zx * invLen;
  let ny = -zy * invLen;
  let nz = 1.0 * invLen;

  // Primary directional key light (upper-left-front)
  let lx = -0.32, ly = -0.38, lz = 0.868;
  let ndotl = constrain(nx * lx + ny * ly + nz * lz, 0, 1);

  // Secondary warm bounce light (lower-right)
  let bx = 0.38, by = 0.32, bz = 0.868;
  let ndotb = constrain(nx * bx + ny * by + nz * bz, 0, 1);

  // Ambient occlusion in deep anatomical crevices (sockets, nostrils, lip parting)
  let ao = 1.0;
  ao -= 0.35 * gauss2D(x, y, 475, 470, 58, 48); // left medial eye hollow
  ao -= 0.35 * gauss2D(x, y, 725, 462, 58, 48); // right medial eye hollow
  ao -= 0.55 * gauss2D(x, y, 544, 882, 28, 16); // left nostril
  ao -= 0.55 * gauss2D(x, y, 658, 878, 28, 16); // right nostril
  ao -= 0.25 * gauss2D(x, y, 602, 895, 55, 22); // subnasale shadow

  let light = constrain((0.78 * ndotl + 0.24 * ndotb + 0.12) * ao, 0.04, 1.0);

  // Subsurface scattering peaks along the shadow terminator (light ~ 0.32..0.58)
  // and in thin/vascular tissues (eyelids, nose tip, cheeks, alae, ears/lips)
  let sssBand = Math.exp(-Math.pow((light - 0.46) / 0.19, 2));
  let vascularity =
    0.55 * gauss2D(x, y, 602, 840, 88, 55) +
    0.45 * gauss2D(x, y, 270, 710, 165, 125) +
    0.45 * gauss2D(x, y, 930, 700, 165, 125) +
    0.50 * gauss2D(x, y, 352, 485, 115, 65) +
    0.50 * gauss2D(x, y, 848, 475, 115, 65);
  let sss = constrain(0.65 * sssBand + 0.55 * vascularity, 0, 1);

  // Specular highlight (half-vector close to +Z)
  let hx = -0.16, hy = -0.20, hz = 0.966;
  let spec = Math.pow(constrain(nx * hx + ny * hy + nz * hz, 0, 1), 24);

  // Anatomical Langer's skin-tension flow angle
  let contourAngle = atan2(zy, zx) + 90;
  // Blend with radial muscle flow around orbicularis oculi when near eyes
  let dLE = dist(x, y, FACE.leftEye.x, FACE.leftEye.y);
  let dRE = dist(x, y, FACE.rightEye.x, FACE.rightEye.y);
  let flowAngle = contourAngle;
  if (dLE < 175) {
    let eyeTangent = atan2(y - FACE.leftEye.y, (x - FACE.leftEye.x) * 0.65) + 90;
    flowAngle = eyeTangent;
  } else if (dRE < 175) {
    let eyeTangent = atan2(y - FACE.rightEye.y, (x - FACE.rightEye.x) * 0.65) + 90;
    flowAngle = eyeTangent;
  }

  return { z: zc, light, sss, spec, flowAngle, nx, ny };
}

// Vivid, saturated colored-pencil skin palette selector
function pickVividSkinColor(x, y, sh) {
  // Lip vermilion zone
  let lipDx = (x - 602) / 188;
  let bowDip = 12 * Math.exp(-Math.pow((x - 602) / 28, 2));
  let upperPeakY = 1044 + bowDip + 38 * lipDx * lipDx;
  if (Math.abs(lipDx) < 1.02 && y > upperPeakY) {
    if (sh.light < 0.25) return "#4A1024";
    if (sh.light < 0.48) return "#8E1E3E";
    if (sh.light < 0.68) return "#CC3358";
    if (sh.light < 0.84) return "#EB5E78";
    return "#FFCCD8";
  }

  // Cool violet/periwinkle undertone zones (temples, tear troughs, outer sockets)
  let coolWeight =
    0.65 * gauss2D(x, y, 425, 560, 75, 36) +
    0.65 * gauss2D(x, y, 775, 550, 75, 36) +
    0.55 * gauss2D(x, y, 105, 420, 130, 220) +
    0.55 * gauss2D(x, y, 1095, 410, 130, 220);

  if (coolWeight > 0.36 && random() < coolWeight) {
    if (sh.light < 0.36) return random(["#543A5E", "#6B4668", "#483858"]);
    if (sh.light < 0.62) return random(["#8E6E96", "#A47B9E", "#7E7EAB"]);
    return random(["#C8A4BE", "#D6B8CC", "#B8B4D4"]);
  }

  // Deep shadow palette (rich plum, burgundy, burnt sienna)
  if (sh.light < 0.26) {
    return random(["#4A1526", "#5E1C2E", "#6E2424", "#3E1222"]);
  }
  // Dark terminator / rich subsurface scattering (vivid crimson, coral, magenta-rose)
  if (sh.light < 0.44) {
    return sh.sss > 0.48
      ? random(["#B82D42", "#C93B52", "#A83238", "#D44848"])
      : random(["#8E3542", "#9E4448", "#7E3244"]);
  }
  // Luminous mid-terminator (saturated coral, vermilion-peach, rose-salmon)
  if (sh.light < 0.62) {
    return sh.sss > 0.45
      ? random(["#E65550", "#EC6A5C", "#DF5268", "#F0785A"])
      : random(["#D86E5E", "#E08268", "#C96A6E"]);
  }
  // Bright warm midtones (golden apricot, vivid peach, warm salmon)
  if (sh.light < 0.78) {
    return random(["#F49268", "#F7A474", "#F28A78", "#EFA07E", "#F8B282"]);
  }
  // High-key lit skin (champagne-peach, luminous rose-gold, warm ivory)
  if (sh.light < 0.90) {
    return random(["#FCC49C", "#FAD0B4", "#FDE0C4", "#FBC8C4"]);
  }
  // Specular skin highlights
  return random(["#FFF2E2", "#FFE8EC", "#FFF9F0"]);
}

// ============================================================================
// BRIDAL TULLE FOLD & PLEAT WAVE FUNCTIONS (3 SHEETS AT DIFFERENT DISTANCES)
// ============================================================================

// Evaluates fold ridges, pleat compression, and 2D fabric displacement for Sheet k (1, 2, or 3)
function getTulleSheetState(x, y, layerId) {
  let zFace = getFaceHeight(x, y);
  let dx = 0, dy = 0;
  let foldDensity = 0; // 0 = single sheer ply, 1..2.5 = multi-ply folded veil ridge

  if (layerId === 1) {
    // Sheet 1 (Deepest): Drapes from upper-left across nose bridge to lower-right, plus cheek gathers
    let u1 = (x * 0.62 + y * 0.78) - 720;
    let wave1 = 42 * Math.sin(x * 0.0045 - y * 0.003);
    let d1 = u1 + wave1;
    let ridge1 = Math.exp(-Math.pow(d1 / 68, 2)) + 0.75 * Math.exp(-Math.pow((d1 - 110) / 42, 2));

    let u2 = (x * -0.55 + y * 0.83) - 380 + 35 * Math.cos(x * 0.005);
    let ridge2 = 0.85 * Math.exp(-Math.pow(u2 / 55, 2));

    let u3 = (y - 195) + 28 * Math.sin(x * 0.006);
    let ridge3 = 0.9 * Math.exp(-Math.pow(u3 / 62, 2));

    foldDensity = ridge1 + ridge2 + ridge3;
    // Deep layer conforms closely to 3D facial heightfield + fold gathering
    dx = (x - 600) * (zFace * 0.00055) + 14 * Math.sin(d1 * 0.025) * ridge1;
    dy = (y - 560) * (zFace * 0.00055) - 11 * Math.cos(d1 * 0.025) * ridge1 - zFace * 0.16;
  } else if (layerId === 2) {
    // Sheet 2 (Mid-distance): Sweeping Z-pleat from upper-right between eyes to lower-left cheek,
    // plus a dramatic lower veil across nose tip & philtrum
    let v1 = (x * -0.64 + y * 0.76) - 15 + 48 * Math.sin(y * 0.005 + 1.2);
    let pleat1 = 1.15 * Math.exp(-Math.pow(v1 / 52, 2)) + 0.8 * Math.exp(-Math.pow((v1 + 85) / 36, 2));

    let v2 = (y - 845 + (x - 600) * -0.14) + 34 * Math.sin(x * 0.0055);
    let pleat2 = 1.25 * Math.exp(-Math.pow(v2 / 58, 2));

    let v3 = (y - 265 + (x - 600) * 0.12) + 25 * Math.cos(x * 0.0045);
    let pleat3 = 0.95 * Math.exp(-Math.pow(v3 / 50, 2));

    foldDensity = pleat1 + pleat2 + pleat3;
    dx = (x - 600) * (zFace * 0.00032) + 18 * Math.sin(v1 * 0.032) * pleat1;
    dy = -zFace * 0.09 + 16 * Math.sin(v2 * 0.035) * pleat2;
  } else {
    // Sheet 3 (Nearest foreground): Sharpest gossamer veil with diagonal fold ribbons framing the eyes
    let w1 = (x * 0.52 + y * 0.85) - 960 + 38 * Math.sin(x * 0.004 - 0.6);
    let fold1 = 1.2 * Math.exp(-Math.pow(w1 / 48, 2)) + 0.85 * Math.exp(-Math.pow((w1 - 74) / 30, 2));

    let w2 = (x * 0.48 - y * 0.87) + 220 + 32 * Math.cos(y * 0.0045);
    let fold2 = 0.95 * Math.exp(-Math.pow(w2 / 46, 2));

    let w3 = (y - 115) + 30 * Math.sin(x * 0.005 + 2.1);
    let fold3 = 1.1 * Math.exp(-Math.pow(w3 / 55, 2));

    foldDensity = fold1 + fold2 + fold3;
    // Slight dome over the nose tip where the foreground sheet grazes the highest point of the face
    let nosePush = gauss2D(x, y, 602, 830, 120, 110);
    dx = 15 * Math.sin(w1 * 0.038) * fold1 + (x - 602) * 0.08 * nosePush;
    dy = 15 * Math.cos(w1 * 0.038) * fold1 + (y - 830) * 0.08 * nosePush - zFace * 0.045;
  }

  // Keep the direct aperture over both irises slightly tauter so pore/iris clarity shines through
  let eyeClearL = gauss2D(x, y, FACE.leftEye.ix, FACE.leftEye.iy, 95, 62);
  let eyeClearR = gauss2D(x, y, FACE.rightEye.ix, FACE.rightEye.iy, 95, 62);
  let eyeWindow = constrain(1.0 - 0.65 * (eyeClearL + eyeClearR), 0.25, 1.0);

  return {
    wx: x + dx,
    wy: y + dy,
    foldDensity: foldDensity * eyeWindow,
    rawFold: foldDensity
  };
}

// Helper to draw a smooth ribbon/veil polygon for watercolor glazes
function drawVeilRibbon(ptsCenter, halfWidthFn, bleedInside) {
  brush.beginShape(0.35);
  for (let i = 0; i < ptsCenter.length; i++) {
    let p = ptsCenter[i];
    let hw = halfWidthFn(i / (ptsCenter.length - 1));
    brush.vertex(p[0] + p[2] * hw, p[1] + p[3] * hw);
  }
  for (let i = ptsCenter.length - 1; i >= 0; i--) {
    let p = ptsCenter[i];
    let hw = halfWidthFn(i / (ptsCenter.length - 1)) * bleedInside;
    brush.vertex(p[0] - p[2] * hw, p[1] - p[3] * hw);
  }
  brush.endShape(CLOSE);
}

// ============================================================================
// PHASE 1: SUBSURFACE WATERCOLOR UNDERPAINTING
// ============================================================================

function renderSubsurfaceUnderpainting() {
  brush.noStroke();
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.48, 0.22);

  // Batch 1: Warm Golden-Apricot & Peach Midtone Glow
  brush.fill("#F7A86C", 46);
  drawEllipsePoly(600, 220, 440, 175, 18); // Forehead glow
  drawEllipsePoly(255, 700, 185, 155, 16); // Left malar pad
  drawEllipsePoly(945, 690, 185, 155, 16); // Right malar pad
  drawEllipsePoly(601, 660, 68, 195, 16);  // Nasal dorsum

  // Batch 2: Vivid Subsurface Coral, Vermilion & Rose-Magenta Blush
  brush.fill("#E85258", 52);
  drawEllipsePoly(285, 735, 165, 120, 16); // Left cheek blush
  drawEllipsePoly(915, 725, 165, 120, 16); // Right cheek blush
  drawEllipsePoly(602, 842, 92, 58, 16);   // Nasal tip & alae vascular glow
  drawEllipsePoly(352, 465, 130, 56, 16);  // Left eyelid warmth
  drawEllipsePoly(848, 455, 130, 56, 16);  // Right eyelid warmth
  drawEllipsePoly(602, 1110, 175, 75, 16); // Lips subsurface crimson base

  // Batch 3: Deep Violet-Plum & Burgundy Anatomical Hollows
  brush.fill("#6E223E", 54);
  drawEllipsePoly(468, 468, 68, 52, 14);   // Left medial eye socket
  drawEllipsePoly(732, 460, 68, 52, 14);   // Right medial eye socket
  drawEllipsePoly(602, 895, 95, 36, 14);   // Subnasale shadow under nose
  drawEllipsePoly(602, 1085, 155, 38, 14); // Upper lip shadow

  // Batch 4: Cool Periwinkle-Lavender Undertones (Temples & Tear Troughs)
  brush.fill("#888EB8", 42);
  drawEllipsePoly(95, 420, 115, 240, 14);  // Left temple
  drawEllipsePoly(1105, 410, 115, 240, 14);// Right temple
  drawEllipsePoly(390, 558, 92, 34, 14);   // Left tear trough cool undertone
  drawEllipsePoly(810, 548, 92, 34, 14);   // Right tear trough cool undertone

  brush.noFill();
}

function drawEllipsePoly(cx, cy, rx, ry, steps) {
  brush.beginShape(0.4);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    let jit = 0.92 + 0.16 * noise(cx * 0.01 + cos(a), cy * 0.01 + sin(a));
    brush.vertex(cx + cos(a) * rx * jit, cy + sin(a) * ry * jit);
  }
  brush.endShape(CLOSE);
}

// ============================================================================
// PHASE 2: COLOURED PENCIL SKIN MODELING & CROSS-CONTOUR SHADING
// ============================================================================

function renderColoredPencilSkin() {
  // Pass 1: Broad anatomical form building following Langer's skin tension lines
  let step = 15;
  for (let y = -10; y <= 1210; y += step) {
    for (let x = -10; x <= 1210; x += step) {
      let jx = x + random(-6, 6);
      let jy = y + random(-6, 6);

      // Skip inside open eye apertures (drawn in Phase 3 with clinical precision)
      let gL = getEyeGeometry(jx, jy, FACE.leftEye, false);
      let gR = getEyeGeometry(jx, jy, FACE.rightEye, true);
      if (gL.isInsideOpening || gR.isInsideOpening) continue;

      let sh = getFaceShading(jx, jy);
      let col = pickVividSkinColor(jx, jy, sh);

      // Primary contour stroke
      let len = random(22, 38);
      let ang = sh.flowAngle + random(-14, 14);
      let dx = cos(ang) * len * 0.5;
      let dy = sin(ang) * len * 0.5;

      brush.set("cpencil", col, random(0.45, 0.85));
      brush.line(jx - dx, jy - dy, jx + dx, jy + dy);

      // Cross-hatch pass for velvety colored-pencil tooth
      if (random() < 0.65) {
        let sh2 = getFaceShading(jx + 3, jy - 3);
        let col2 = pickVividSkinColor(jx + 3, jy - 3, sh2);
        let ang2 = sh.flowAngle + (random() < 0.5 ? 24 : -24);
        let dx2 = cos(ang2) * len * 0.42;
        let dy2 = sin(ang2) * len * 0.42;
        brush.set("cpencil", col2, random(0.35, 0.65));
        brush.line(jx - dx2, jy - dy2, jx + dx2, jy + dy2);
      }
    }
  }

  // Pass 2: High-density colored pencil refinement on nose, periocular skin, cheeks & lips
  for (let i = 0; i < 2400; i++) {
    // Concentrate around high-focus central features
    let rx = 600 + randomGaussian(0, 310);
    let ry = 610 + randomGaussian(0, 260);
    if (rx < 0 || rx > 1200 || ry < 0 || ry > 1200) continue;

    let gL = getEyeGeometry(rx, ry, FACE.leftEye, false);
    let gR = getEyeGeometry(rx, ry, FACE.rightEye, true);
    if (gL.isInsideOpening || gR.isInsideOpening) continue;

    let sh = getFaceShading(rx, ry);
    let col = pickVividSkinColor(rx, ry, sh);
    let len = random(10, 22);
    let ang = sh.flowAngle + random(-10, 10);
    let dx = cos(ang) * len * 0.5;
    let dy = sin(ang) * len * 0.5;

    brush.set("cpencil", col, random(0.28, 0.52));
    brush.line(rx - dx, ry - dy, rx + dx, ry + dy);
  }
}

// ============================================================================
// PHASE 3: RUTHLESS PORE-LEVEL PRECISION (EYES, PORES, LASHES, BROWS, LIPS)
// ============================================================================

function renderPoreLevelSkinTexture() {
  // Clinical pore-level micro-relief across nose bridge, tear troughs, eyelids, glabella & malar cheeks
  let spacing = 9.5;
  for (let y = 260; y <= 1040; y += spacing) {
    for (let x = 110; x <= 1090; x += spacing) {
      let px = x + random(-3.6, 3.6);
      let py = y + random(-3.6, 3.6);

      // Focus intensity map (strongest around eyes, nose bridge/tip, glabella, inner cheeks)
      let focus =
        0.95 * gauss2D(px, py, 355, 520, 195, 145) +
        0.95 * gauss2D(px, py, 845, 510, 195, 145) +
        1.00 * gauss2D(px, py, 601, 680, 125, 230) +
        0.85 * gauss2D(px, py, 275, 720, 160, 130) +
        0.85 * gauss2D(px, py, 925, 710, 160, 130);

      if (random() > focus) continue;

      let gL = getEyeGeometry(px, py, FACE.leftEye, false);
      let gR = getEyeGeometry(px, py, FACE.rightEye, true);
      if (gL.isInsideOpening || gR.isInsideOpening) continue;

      let sh = getFaceShading(px, py);
      let ang = sh.flowAngle;
      let ca = cos(ang), sa = sin(ang);

      // 1. Microscopic recessed pore dimple (warm crimson-umber / plum-sienna)
      let poreCol = sh.light < 0.45
        ? random(["#521626", "#681E2C", "#4A1822"])
        : random(["#8E2E36", "#A43A3E", "#7A2834", "#98423C"]);
      let pLen = random(1.8, 3.4);
      brush.set("cpencil", poreCol, random(0.22, 0.36));
      brush.line(px - ca * pLen * 0.5, py - sa * pLen * 0.5, px + ca * pLen * 0.5, py + sa * pLen * 0.5);

      // 2. Micro-sulci diamond skin-cell crease connecting adjacent pores
      if (random() < 0.42) {
        let sulciAng = ang + (random() < 0.5 ? 38 : -38);
        let sLen = random(4.0, 7.5);
        brush.set("2H", poreCol, 0.16);
        brush.line(px, py, px + cos(sulciAng) * sLen, py + sin(sulciAng) * sLen);
      }

      // 3. Adjacent specular skin-cell pillow highlight (catches key light on lower-right rim of pore)
      if (sh.light > 0.52 && (sh.spec > 0.08 || random() < 0.55)) {
        let hiCol = sh.spec > 0.35 ? "#FFF9F0" : random(["#FFE6DC", "#FFF0E4", "#FFD8DE"]);
        let hx = px + 1.6, hy = py + 1.8;
        brush.set("cpencil", hiCol, random(0.20, 0.34));
        brush.line(hx - ca * 1.4, hy - sa * 1.4, hx + ca * 1.4, hy + sa * 1.4);
      }
    }
  }

  // Fine vellus hair (peach fuzz) catching grazing light on cheeks and temples
  for (let i = 0; i < 260; i++) {
    let side = i % 2 === 0 ? -1 : 1;
    let vx = 600 + side * random(240, 540);
    let vy = random(540, 960);
    let sh = getFaceShading(vx, vy);
    if (sh.light < 0.48) continue;
    let vAng = side < 0 ? random(105, 145) : random(35, 75);
    let vLen = random(7, 15);
    brush.set("2H", "#FFF3E8", 0.16);
    brush.line(vx, vy, vx + cos(vAng) * vLen, vy + sin(vAng) * vLen);
  }
}

function renderDetailedNoseAndLips() {
  // Crisp nostril cavities, alar crease, and nasal tip specular pores
  let nostrils = [
    { cx: 544, cy: 882, rx: 25, ry: 14, rot: -16 },
    { cx: 658, cy: 878, rx: 25, ry: 14, rot: 16 }
  ];
  for (let n of nostrils) {
    for (let r = 1.0; r >= 0.15; r -= 0.14) {
      let col = r > 0.65 ? "#6E1C2C" : r > 0.38 ? "#3A0B16" : "#18040A";
      brush.set("cpencil", col, 0.42);
      brush.beginShape(0.4);
      for (let a = 0; a <= 360; a += 30) {
        let lx = cos(a) * n.rx * r;
        let ly = sin(a) * n.ry * r;
        let rx = n.cx + lx * cos(n.rot) - ly * sin(n.rot);
        let ry = n.cy + lx * sin(n.rot) + ly * cos(n.rot);
        brush.vertex(rx, ry);
      }
      brush.endShape();
    }
    // Warm subsurface crimson-coral rim glow around nostril edge
    brush.set("cpencil", "#E6454F", 0.38);
    for (let a = 20; a <= 160; a += 14) {
      let x1 = n.cx + cos(a) * n.rx * 1.08;
      let y1 = n.cy + sin(a) * n.ry * 1.15;
      brush.line(x1, y1, x1 + random(-3, 3), y1 + random(4, 9));
    }
  }

  // Nasal tip & bridge specular micro-beads
  for (let i = 0; i < 190; i++) {
    let ny = random(460, 855);
    let spread = ny > 780 ? 34 : 18;
    let nx = 594 + randomGaussian(0, spread);
    let hiCol = random(["#FFF8EE", "#FFEAE6", "#FFF2DC"]);
    brush.set("cpencil", hiCol, random(0.24, 0.42));
    brush.line(nx, ny, nx + random(-2, 2), ny + random(2, 5));
  }

  // Upper & Lower Lip Vertical Sulci (realistic lip creases & glossy specular highlights)
  for (let x = 415; x <= 790; x += 3.2) {
    let lipDx = (x - 602) / 188;
    let bowDip = 12 * Math.exp(-Math.pow((x - 602) / 28, 2));
    let upperPeakY = 1044 + bowDip + 38 * lipDx * lipDx;
    let partY = 1122 + 8 * lipDx * lipDx - 4 * Math.exp(-Math.pow((x - 602) / 45, 2));

    // Crisp Cupid's bow white-gold dermal roll highlight
    if (Math.abs(lipDx) < 0.85) {
      brush.set("cpencil", "#FFF2E6", 0.30);
      brush.line(x, upperPeakY - 2, x + 2.5, upperPeakY - 1);
    }

    // Upper lip radial sulci
    for (let s = 0; s < 3; s++) {
      let t0 = random(0.05, 0.65);
      let t1 = constrain(t0 + random(0.22, 0.42), 0, 1);
      let y0 = lerp(upperPeakY, partY, t0);
      let y1 = lerp(upperPeakY, partY, t1);
      let curveX = (x - 602) * 0.06;
      let col = t1 > 0.78 ? "#4E1024" : random(["#8A1C3A", "#B82B4E", "#D94864", "#6E1630"]);
      brush.set("cpencil", col, random(0.22, 0.38));
      brush.line(x + curveX * t0, y0, x + curveX * t1, y1);
    }

    // Oral parting line shadow
    brush.set("cpencil", "#220610", 0.45);
    brush.line(x - 1.5, partY, x + 1.5, partY + random(-1, 1));

    // Lower lip plush vertical sulci & wet gloss highlights
    for (let s = 0; s < 3; s++) {
      let y0 = partY + random(4, 38);
      let y1 = y0 + random(18, 36);
      if (y1 > 1200) continue;
      let col = y0 < partY + 14 ? "#7A1834" : random(["#C83558", "#E65270", "#F07288", "#9E2242"]);
      brush.set("cpencil", col, random(0.25, 0.42));
      brush.line(x, y0, x + (x - 602) * 0.04, y1);
    }
    if (Math.abs(lipDx) < 0.62 && random() < 0.55) {
      let gy = partY + random(18, 46);
      brush.set("cpencil", "#FFEBF0", random(0.24, 0.38));
      brush.line(x, gy, x + random(-1, 1), gy + random(5, 12));
    }
  }
}

// Master hyperrealist eye renderer (called for Left and Right eyes)
function renderHyperrealEye(eye, isRight) {
  let sign = isRight ? 1 : -1;

  // 1. EYELID CREASE (TARSAL FOLD) & ORBICULARIS OCULI MICRO-WRINKLES
  for (let x = eye.x - eye.hw * 1.15; x <= eye.x + eye.hw * 1.15; x += 2.2) {
    let g = getEyeGeometry(x, eye.y, eye, isRight);
    // Deep tarsal crease shadow in plum-burgundy & burnt umber
    for (let k = -3; k <= 3; k++) {
      let cy = g.yCrease + k * 1.6 + random(-0.8, 0.8);
      let col = Math.abs(k) <= 1 ? "#3E101E" : k < 0 ? "#7E2B38" : "#9E4246";
      brush.set("cpencil", col, 0.32);
      brush.line(x - 3, cy, x + 3, cy + (isRight ? -0.3 : 0.3));
    }

    // Mobile upper eyelid vertical/curved micro-shimmer & pores
    if (g.inSpan && random() < 0.75) {
      let lidY = lerp(g.yCrease + 6, g.yUpper - 3, random(0.15, 0.88));
      let distFromCenter = Math.abs(x - eye.x) / eye.hw;
      let lidCol = distFromCenter < 0.38
        ? random(["#FFE4DC", "#F9C4B8", "#F49E92"])
        : random(["#C85E64", "#9E3E4C", "#7A2838"]);
      brush.set("cpencil", lidCol, 0.26);
      brush.line(x - 2.5, lidY, x + 2.5, lidY + random(-1.5, 1.5));
    }

    // Lower eyelid bag / tear trough micro-creases
    if (Math.abs(g.t) < 0.95 && random() < 0.6) {
      let bagY = g.yLower + random(8, 26);
      let bagCol = random(["#8E3E4E", "#B25864", "#78384C", "#F2A89E"]);
      brush.set("cpencil", bagCol, 0.22);
      brush.line(x - 3, bagY, x + 3, bagY + sign * 0.8);
    }
  }

  // 2. SCLERA (3D SPHERICAL SHADING + EPISCLERAL BLOOD VESSELS)
  for (let x = eye.x - eye.hw * 1.12; x <= eye.x + eye.hw * 1.12; x += 2.2) {
    let g = getEyeGeometry(x, eye.y, eye, isRight);
    if (!g.inSpan) continue;
    for (let y = g.yUpper; y <= g.yLower; y += 2.2) {
      let dIris = dist(x, y, eye.ix, eye.iy);
      if (dIris < eye.ir - 2 && g.t > -0.78) continue; // Inside iris

      // Lacrimal caruncle & plica semilunaris at medial corner (t < -0.74)
      if (g.t < -0.72) {
        let carCol = g.t < -0.92
          ? random(["#9E1E32", "#C83248", "#7A1424"])
          : random(["#E65868", "#F2828E", "#D44658", "#FAD2D6"]);
        brush.set("cpencil", carCol, 0.34);
        brush.line(x, y, x + random(-2, 2), y + random(-2, 2));
        continue;
      }

      // Spherical sclera shading + upper lid cast shadow
      let dUpper = y - g.yUpper;
      let edgeDark = Math.pow(Math.abs(g.t), 1.6);
      let scleraCol;
      if (dUpper < 9) {
        scleraCol = random(["#4A4E6E", "#625C7E", "#7A6E8E"]); // Cast shadow from upper lid
      } else if (dUpper < 17 || edgeDark > 0.62) {
        scleraCol = random(["#8E94B2", "#A89EB8", "#B8A6BA"]);
      } else if (edgeDark > 0.38) {
        scleraCol = random(["#D4C8D4", "#E2D4DC", "#C8CCD8"]);
      } else {
        scleraCol = random(["#F5EEF0", "#FAF5F5", "#EBE4EA", "#FFFDFB"]);
      }
      brush.set("cpencil", scleraCol, 0.36);
      brush.line(x - 1.8, y, x + 1.8, y + random(-1, 1));
    }
  }

  // Wet specular droplets on lacrimal caruncle (inner tear duct)
  let carX = isRight ? eye.x - eye.hw * 0.92 : eye.x + eye.hw * 0.92;
  let carY = eye.y + 5;
  for (let i = 0; i < 14; i++) {
    let wx = carX + random(-9, 9);
    let wy = carY + random(-6, 6);
    brush.set("rotring", "#FFFFFF", 0.25);
    brush.line(wx, wy, wx + 1.8, wy + 0.8);
  }

  // Fine branched episcleral capillaries on lateral & medial sclera
  for (let side of [-1, 1]) {
    for (let v = 0; v < 9; v++) {
      let vx = eye.x + side * random(eye.hw * 0.58, eye.hw * 0.92);
      let g0 = getEyeGeometry(vx, eye.y, eye, isRight);
      if (!g0.inSpan) continue;
      let vy = lerp(g0.yUpper + 8, g0.yLower - 6, random(0.2, 0.85));
      let ang = side > 0 ? random(155, 205) : random(-25, 25);
      for (let seg = 0; seg < 6; seg++) {
        let nx = vx + cos(ang) * random(3.5, 6.5);
        let ny = vy + sin(ang) * random(3.5, 6.5);
        let gn = getEyeGeometry(nx, ny, eye, isRight);
        if (!gn.isInsideOpening || dist(nx, ny, eye.ix, eye.iy) < eye.ir + 2) break;
        brush.set("rotring", seg < 3 ? "#C8283C" : "#E87280", 0.14);
        brush.line(vx, vy, nx, ny);
        vx = nx;
        vy = ny;
        ang += random(-28, 28);
      }
    }
  }

  // 3. HYPER-DETAILED IRIS (EMERALD-TEAL STROMA, CRYPTS, AMBER COLLARETTE, LIMBAL RING)
  let ir = eye.ir;
  let pr = 16.5; // Pupil radius

  // 3a. Dark velvety iris substrate & rich limbal ring
  for (let a = 0; a < 360; a += 1.5) {
    let ca = cos(a), sa = sin(a);
    for (let r = pr; r <= ir; r += 2.2) {
      let px = eye.ix + ca * r;
      let py = eye.iy + sa * r;
      let g = getEyeGeometry(px, py, eye, isRight);
      if (!g.isInsideOpening) continue;

      let col;
      if (r > ir - 6.5) {
        col = random(["#071820", "#0E222E", "#161428", "#0A2B2E"]); // Deep limbal ring
      } else if (py - g.yUpper < 12) {
        col = random(["#09222C", "#12303C", "#1A2438"]); // Upper lid shadow on iris
      } else if (r < pr + 11) {
        col = random(["#3E2214", "#5E3418", "#183E38", "#0E2C28"]); // Peripupillary base
      } else {
        col = random(["#0D4A42", "#146256", "#1A7564", "#12525C", "#0B3B38"]); // Vivid emerald-teal base
      }
      brush.set("cpencil", col, 0.34);
      brush.line(px, py, px + ca * 2.4, py + sa * 2.4);
    }
  }

  // 3b. 360 Wavy Radial Stroma Fibers & Recessed Crypts of Fuchs
  for (let i = 0; i < 360; i++) {
    let baseAng = i * 1.0 + random(-0.4, 0.4);
    let isCrypt = noise(i * 0.18, isRight ? 10 : 20) > 0.56;
    let rStart = pr + random(0, 3);
    let rEnd = ir - random(2, 6);

    let pts = [];
    for (let r = rStart; r <= rEnd; r += 4.5) {
      let wave = isCrypt ? sin((r - pr) * 9) * 3.2 : sin((r - pr) * 6) * 1.2;
      let a = baseAng + wave;
      let px = eye.ix + cos(a) * r;
      let py = eye.iy + sin(a) * r;
      let g = getEyeGeometry(px, py, eye, isRight);
      if (g.isInsideOpening) {
        pts.push([px, py]);
      }
    }
    if (pts.length < 2) continue;

    // Upper portion of iris is shadowed by upper eyelid; lower portion glows vividly
    let midY = pts[Math.floor(pts.length / 2)][1];
    let gMid = getEyeGeometry(eye.ix, midY, eye, isRight);
    let inShadow = (midY - gMid.yUpper) < 13;

    let fiberCol;
    if (isCrypt && random() < 0.65) {
      fiberCol = random(["#06181C", "#0B2428", "#1C1218"]); // Dark iris crypt cavity
    } else if (inShadow) {
      fiberCol = random(["#123E48", "#1B525C", "#24485E", "#0E323A"]);
    } else {
      fiberCol = random([
        "#1E8C78", "#2BB094", "#3AD4B2", "#1FA098",
        "#68D89B", "#24869E", "#88E2B8"
      ]);
    }
    brush.set(i % 3 === 0 ? "rotring" : "cpencil", fiberCol, random(0.15, 0.26));
    brush.spline(pts, 0.35);
  }

  // 3c. Vivid Fiery Amber, Cadmium Orange & Gold Collarette Ring around Pupil
  for (let i = 0; i < 210; i++) {
    let a = random(0, 360);
    let r0 = pr + random(1.5, 7.5);
    let r1 = r0 + random(5.5, 14.5);
    let x0 = eye.ix + cos(a) * r0;
    let y0 = eye.iy + sin(a) * r0;
    let x1 = eye.ix + cos(a + random(-5, 5)) * r1;
    let y1 = eye.iy + sin(a + random(-5, 5)) * r1;

    let g0 = getEyeGeometry(x0, y0, eye, isRight);
    let g1 = getEyeGeometry(x1, y1, eye, isRight);
    if (!g0.isInsideOpening || !g1.isInsideOpening) continue;

    let inShadow = (y0 - g0.yUpper) < 11;
    let col = inShadow
      ? random(["#7A3E18", "#9E521C", "#68321A"])
      : random(["#E87818", "#F7A428", "#FFD04C", "#D95B16", "#FFDF78"]);
    brush.set("cpencil", col, random(0.18, 0.30));
    brush.line(x0, y0, x1, y1);
  }

  // 3d. Jet-Black Velvet Pupil
  for (let r = pr; r >= 0.8; r -= 1.3) {
    for (let a = 0; a < 360; a += 10) {
      let px = eye.ix + cos(a) * r;
      let py = eye.iy + sin(a) * r;
      let g = getEyeGeometry(px, py, eye, isRight);
      if (!g.isInsideOpening) continue;
      let nx = eye.ix + cos(a + 14) * r;
      let ny = eye.iy + sin(a + 14) * r;
      brush.set("cpencil", r > pr - 2.2 ? "#1E0E14" : "#050408", 0.38);
      brush.line(px, py, nx, ny);
    }
  }

  // 4. WET WATERLINE (LOWER & UPPER LID MARGINS) & TEAR MENISCUS
  for (let x = eye.x - eye.hw * 0.98; x <= eye.x + eye.hw * 0.98; x += 2.0) {
    let g = getEyeGeometry(x, eye.y, eye, isRight);
    if (!g.inSpan) continue;

    // Lower pink wet waterline shelf (3.5px thick)
    let wlCol = Math.abs(g.t) > 0.7 ? "#C84B5A" : random(["#F07E88", "#F79EA6", "#E26674"]);
    brush.set("cpencil", wlCol, 0.34);
    brush.line(x - 1.5, g.yLower + 1.8, x + 1.5, g.yLower + 3.6);

    // Glistening white tear meniscus highlight along bottom edge of eyeball
    if (Math.abs(g.t) < 0.78 && random() < 0.82) {
      brush.set("rotring", "#FFFFFF", random(0.16, 0.26));
      brush.line(x - 1.5, g.yLower - 0.5, x + 1.5, g.yLower - 0.5);
    }

    // Upper lid tightline shadow (dark root line under upper lashes)
    brush.set("cpencil", "#1A0A10", 0.45);
    brush.line(x - 1.8, g.yUpper, x + 1.8, g.yUpper + 1.2);
  }

  // 5. CORNEAL WINDOW CATCHLIGHTS (WITH SUBTLE TULLE HEXAGONAL SHADOW IMPRINT)
  let catchX = eye.ix - 14;
  let catchY = eye.iy - 15;
  for (let wy = -11; wy <= 11; wy += 1.1) {
    for (let wx = -13; wx <= 13; wx += 1.1) {
      // Curved window pane geometry on spherical cornea
      let rx = catchX + wx - wy * 0.22;
      let ry = catchY + wy + wx * 0.08 + (wx * wx) * 0.015;
      let g = getEyeGeometry(rx, ry, eye, isRight);
      if (!g.isInsideOpening || ry < g.yUpper + 2.5) continue;

      // Window mullion crossbars + faint hexagonal tulle mesh shadow across catchlight
      if (Math.abs(wx - 1.5) < 1.1 || Math.abs(wy + 1.0) < 0.9) continue;
      let hexMod = Math.sin(rx * 0.42) * Math.sin((rx * 0.21 + ry * 0.36));
      let cCol = hexMod > 0.45 ? "#CBE8F8" : "#FFFFFF";
      brush.set("rotring", cCol, 0.26);
      brush.line(rx, ry, rx + 1.4, ry + 0.4);
    }
  }
  // Secondary lower-right warm crescent corneal reflection
  for (let a = 25; a <= 72; a += 3) {
    let r = ir * 0.68;
    let rx = eye.ix + cos(a) * r;
    let ry = eye.iy + sin(a) * r;
    let g = getEyeGeometry(rx, ry, eye, isRight);
    if (g.isInsideOpening) {
      brush.set("cpencil", "#FFF6E8", 0.24);
      brush.line(rx, ry, rx - sin(a) * 2.5, ry + cos(a) * 2.5);
    }
  }

  // 6. INDIVIDUAL EYELASHES (UPPER & LOWER, CURVED IN 3D PERSPECTIVE WITH CLUMPING)
  // Upper eyelashes (~88 lashes)
  let numUpper = 88;
  for (let i = 0; i < numUpper; i++) {
    let t = map(i, 0, numUpper - 1, -0.76, 0.98);
    let x0 = eye.x + (isRight ? t : -t) * eye.hw;
    let g = getEyeGeometry(x0, eye.y, eye, isRight);

    // Clumping attractor: every 4-5 lashes converge slightly at their tips
    let clumpCenterT = Math.round(t * 14) / 14;
    let clumpPull = (clumpCenterT - t) * (isRight ? 1 : -1) * 32;

    // Length & 3D foreshortening
    let env = Math.sin(map(t, -0.8, 1.0, 15, 168));
    let lashLen = (24 + 34 * env) * (0.88 + 0.24 * noise(i * 0.7));
    let fanAngle = -90 + (isRight ? 1 : -1) * (t * 54 + 6);

    // 4-point 3D spline: dips slightly down out of the follicle, then sweeps up & out
    let p0 = [x0, g.yUpper - 0.5, 1.0];
    let p1 = [
      x0 + cos(fanAngle) * lashLen * 0.26,
      g.yUpper + 2.5 + sin(fanAngle) * lashLen * 0.14,
      0.85
    ];
    let p2 = [
      x0 + cos(fanAngle) * lashLen * 0.65 + clumpPull * 0.5,
      g.yUpper + sin(fanAngle) * lashLen * 0.58,
      0.55
    ];
    let p3 = [
      x0 + cos(fanAngle) * lashLen + clumpPull,
      g.yUpper + sin(fanAngle) * lashLen * 0.96,
      0.18
    ];

    // Subtle lash cast shadow on sclera/eyelid
    if (i % 2 === 0) {
      brush.set("2H", "#4A2E38", 0.16);
      brush.line(p0[0], p0[1] + 2, p1[0] + 2, p1[1] + 5);
    }

    let lashCol = i % 5 === 0 ? "#381E24" : i % 3 === 0 ? "#1E0E14" : "#0C0609";
    brush.set(i % 2 === 0 ? "rotring" : "cpencil", lashCol, random(0.20, 0.34));
    brush.spline([p0, p1, p2, p3], 0.45);
  }

  // Lower eyelashes (~56 finer lashes growing from outer edge of lower waterline)
  let numLower = 56;
  for (let i = 0; i < numLower; i++) {
    let t = map(i, 0, numLower - 1, -0.68, 0.94);
    let x0 = eye.x + (isRight ? t : -t) * eye.hw + random(-1.2, 1.2);
    let g = getEyeGeometry(x0, eye.y, eye, isRight);
    let y0 = g.yLower + 4.2; // Outer rim below wet waterline

    let clumpT = Math.round(t * 12) / 12;
    let clumpPull = (clumpT - t) * (isRight ? 1 : -1) * 22;

    let env = Math.sin(map(t, -0.75, 1.0, 12, 165));
    let lashLen = (11 + 19 * env) * random(0.82, 1.15);
    let fanAngle = 90 - (isRight ? 1 : -1) * (t * 42 + 4);

    let p0 = [x0, y0, 0.85];
    let p1 = [
      x0 + cos(fanAngle) * lashLen * 0.48 + clumpPull * 0.4,
      y0 + sin(fanAngle) * lashLen * 0.48,
      0.55
    ];
    let p2 = [
      x0 + cos(fanAngle) * lashLen + clumpPull,
      y0 + sin(fanAngle) * lashLen * 0.92,
      0.15
    ];

    // Tiny follicle dot & soft shadow on lower lid
    brush.set("cpencil", "#7A3B44", 0.18);
    brush.line(x0, y0, p1[0] + 1.5, p1[1] + 1.5);

    let lCol = i % 3 === 0 ? "#422428" : "#1D1014";
    brush.set("rotring", lCol, random(0.14, 0.22));
    brush.spline([p0, p1, p2], 0.4);
  }
}

// Anatomical Eyebrows (~360 individual layered hair strokes per brow)
function renderEyebrow(isRight) {
  let sign = isRight ? 1 : -1;
  let numHairs = 360;

  for (let i = 0; i < numHairs; i++) {
    let u = random(0, 1); // 0 = medial head near glabella, 1 = lateral tail
    let bx = 600 + sign * lerp(108, 438, u) + random(-5, 5);

    // Arch trajectory peaking at u ~ 0.62
    let arch = Math.sin(Math.pow(u, 0.82) * 168);
    let baseBy = (isRight ? 382 : 390) - 54 * arch + 18 * u * u;
    let thickness = lerp(34, 11, Math.pow(u, 1.4)) * (0.4 + 0.6 * Math.sin(u * 170 + 10));
    let v = random(-0.5, 0.5);
    let by = baseBy + v * thickness;

    // Anatomical hair growth angle: nearly vertical at medial head, sweeping outward & downward at tail
    let localAngle;
    if (u < 0.18) {
      localAngle = -90 + sign * map(u, 0, 0.18, 12, 48) + random(-10, 10);
    } else {
      let baseDir = map(u, 0.18, 1.0, 52, 112);
      // Upper hairs angle slightly down toward brow spine; lower hairs angle slightly up
      let spinePull = v < 0 ? 14 : -12;
      localAngle = -90 + sign * (baseDir + spinePull) + random(-7, 7);
    }

    let hLen = lerp(26, 36, Math.sin(u * 160)) * random(0.78, 1.18);
    let p0 = [bx, by, 0.8];
    let p1 = [
      bx + cos(localAngle) * hLen * 0.5,
      by + sin(localAngle) * hLen * 0.5,
      0.65
    ];
    let p2 = [
      bx + cos(localAngle + sign * 8) * hLen,
      by + sin(localAngle + sign * 8) * hLen,
      0.15
    ];

    // Layering from warm skin-shadow roots to dark espresso hairs to bronze/champagne lit hairs
    let hCol;
    if (i < 90) {
      hCol = random(["#7A4644", "#623638", "#8E524E"]); // Soft dermal root shadow
    } else if (i < 300) {
      hCol = random(["#241416", "#382022", "#180C0E", "#4A2C2A"]); // Core brow hairs
    } else {
      hCol = random(["#8C6258", "#B88E82", "#D8B4A6"]); // Specular lit brow hairs
    }

    brush.set(i > 220 ? "rotring" : "cpencil", hCol, i < 90 ? 0.34 : random(0.16, 0.25));
    brush.spline([p0, p1, p2], 0.35);
  }
}

// ============================================================================
// PHASE 4: BRIDAL TULLE WATERCOLOR GLAZES & MULTI-LAYER HEXAGONAL PEN MESHES
// ============================================================================

// Renders the transparent watercolor glazes for a specific tulle sheet (batched by color)
function renderTulleWatercolorGlaze(layerId) {
  brush.noStroke();
  brush.fillBleed(0.24, "out");
  brush.fillTexture(0.45, 0.28);

  if (layerId === 1) {
    // Sheet 1 Glazes: Faint Champagne (#F9E9C8) and Shell Pink (#F8C9D4)
    let ribbon1 = buildFoldSpine(-60, 180, 1260, 1020, 26, (t) => 38 * Math.sin(t * 280));
    let ribbon2 = buildFoldSpine(-40, 420, 780, 1240, 20, (t) => 28 * Math.cos(t * 220));
    let ribbon3 = buildFoldSpine(0, 165, 1200, 215, 22, (t) => -25 * Math.sin(t * 200));

    // Batch A: Faint Champagne
    brush.fill("#F9E9C8", 24);
    drawVeilRibbon(ribbon1, (t) => 115 + 35 * Math.sin(t * 180), 0.85);
    drawVeilRibbon(ribbon3, (t) => 95 + 25 * Math.cos(t * 180), 0.90);
    // Denser inner fold core
    drawVeilRibbon(ribbon1, (t) => 42 + 18 * Math.sin(t * 360), 0.65);

    // Batch B: Shell Pink
    brush.fill("#F8C9D4", 26);
    drawVeilRibbon(ribbon2, (t) => 105 + 30 * Math.sin(t * 180), 0.85);
    drawVeilRibbon(ribbon1, (t) => 65 + 20 * Math.cos(t * 240), 0.55);
  } else if (layerId === 2) {
    // Sheet 2 Glazes: Oyster Grey (#CFD6E0, #BAC2CE) and Shell Pink (#F7C2D0)
    let pleatA = buildFoldSpine(1180, 20, 40, 1120, 26, (t) => -44 * Math.sin(t * 300));
    let pleatB = buildFoldSpine(-40, 885, 1240, 795, 24, (t) => 34 * Math.sin(t * 240));
    let pleatC = buildFoldSpine(-40, 250, 1240, 310, 22, (t) => 22 * Math.cos(t * 260));

    // Batch A: Luminous Oyster Grey
    brush.fill("#CFD6E0", 28);
    drawVeilRibbon(pleatA, (t) => {
      // Narrow slightly between the eyes so eye precision remains razor-sharp
      let eyePinch = 1.0 - 0.52 * Math.exp(-Math.pow((t - 0.44) / 0.14, 2));
      return (110 + 30 * Math.sin(t * 180)) * eyePinch;
    }, 0.82);
    drawVeilRibbon(pleatB, (t) => 98 + 28 * Math.sin(t * 220), 0.88);
    drawVeilRibbon(pleatC, (t) => 78 + 20 * Math.cos(t * 180), 0.75);

    // Overlapping denser Z-pleat cores in Oyster-Lavender
    brush.fill("#B8C0D0", 24);
    drawVeilRibbon(pleatA, (t) => 36 + 14 * Math.cos(t * 320), 0.50);
    drawVeilRibbon(pleatB, (t) => 38 + 15 * Math.sin(t * 280), 0.55);

    // Batch B: Shell Pink fold underside blush
    brush.fill("#F7C2D0", 24);
    drawVeilRibbon(pleatB, (t) => 64 + 22 * Math.cos(t * 200), 0.65);
  } else {
    // Sheet 3 (Nearest Foreground): Gossamer Shell Pink (#FAD4DE), Champagne (#FDF2D8) & Oyster (#DCE2EA)
    let foreA = buildFoldSpine(-40, 620, 1240, 990, 24, (t) => 36 * Math.sin(t * 240));
    let foreB = buildFoldSpine(0, 95, 1200, 135, 22, (t) => 28 * Math.sin(t * 190));
    let foreC = buildFoldSpine(620, -40, 1240, 640, 20, (t) => -30 * Math.sin(t * 210));

    brush.fill("#FAD4DE", 22);
    drawVeilRibbon(foreA, (t) => 92 + 26 * Math.sin(t * 180), 0.80);
    drawVeilRibbon(foreC, (t) => 76 + 20 * Math.cos(t * 180), 0.75);

    brush.fill("#FDF2D8", 22);
    drawVeilRibbon(foreB, (t) => 88 + 24 * Math.sin(t * 180), 0.85);
    drawVeilRibbon(foreA, (t) => 34 + 12 * Math.cos(t * 300), 0.48);

    brush.fill("#DCE2EA", 20);
    drawVeilRibbon(foreC, (t) => 32 + 12 * Math.sin(t * 260), 0.52);
  }

  brush.noFill();

  // Silky dry-media grazing highlights along the fold ridges of each tulle sheet
  renderTulleFoldRidgeSheen(layerId);
}

function buildFoldSpine(x0, y0, x1, y1, steps, waveFn) {
  let dx = x1 - x0, dy = y1 - y0;
  let len = Math.sqrt(dx * dx + dy * dy);
  let nx = -dy / len, ny = dx / len;
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let w = waveFn(t);
    let px = lerp(x0, x1, t) + nx * w;
    let py = lerp(y0, y1, t) + ny * w;
    pts.push([px, py, nx, ny]);
  }
  return pts;
}

// Adds luminous shell-pink, oyster-grey, and champagne dry-brush sheen along fabric fold creases
function renderTulleFoldRidgeSheen(layerId) {
  let count = layerId === 3 ? 650 : 480;
  for (let i = 0; i < count; i++) {
    let x = random(0, 1200);
    let y = random(0, 1200);
    let st = getTulleSheetState(x, y, layerId);
    if (st.foldDensity < 0.45) continue;

    // Compute fold ridge tangent via finite difference
    let stX = getTulleSheetState(x + 6, y, layerId).rawFold - st.rawFold;
    let stY = getTulleSheetState(x, y + 6, layerId).rawFold - st.rawFold;
    let ridgeAng = atan2(stY, stX) + 90 + random(-8, 8);
    let len = random(18, 42);
    let dx = cos(ridgeAng) * len * 0.5;
    let dy = sin(ridgeAng) * len * 0.5;

    let sheenCol;
    if (layerId === 1) {
      sheenCol = random(["#FFF2D8", "#FCE0E8", "#F5D2DC"]);
    } else if (layerId === 2) {
      sheenCol = random(["#E6ECF2", "#D8E0EA", "#FCE2EA"]);
    } else {
      sheenCol = random(["#FFF8EC", "#FFEBF0", "#EDF2F7", "#FFFFFF"]);
    }

    brush.set("cpencil", sheenCol, random(0.22, 0.42));
    brush.line(x - dx, y - dy, x + dx, y + dy);
  }
}

// Renders the hexagonal bobbinet mesh for a given tulle sheet:
// - Layer 1 (Deepest): Blurred & doubled (`veilBlur` + offset `2H`), warped strongly by 3D face height
// - Layer 2 (Mid): Slightly doubled & soft (`2H` + `HB`), rotated for moiré interference
// - Layer 3 (Nearest): Razor-sharp hairline pen mesh (`rotring` & `microPen`) + folded-under pleat moiré + vertex twists
function renderHexagonalTulleMesh(layerId) {
  let hexR = layerId === 1 ? 13.8 : layerId === 2 ? 15.0 : 16.2;
  let rotAngle = layerId === 1 ? 8.5 : layerId === 2 ? -11.0 : 2.2;
  let cosA = cos(rotAngle), sinA = sin(rotAngle);

  let dxCol = Math.sqrt(3) * hexR;
  let dyRow = 1.5 * hexR;

  // Transform grid coordinates (gx, gy) -> rotated canvas space -> 3D warped tulle space
  function projectNode(gx, gy) {
    let cx = 600 + (gx - 600) * cosA - (gy - 600) * sinA;
    let cy = 600 + (gx - 600) * sinA + (gy - 600) * cosA;
    let st = getTulleSheetState(cx, cy, layerId);
    return { x: st.wx, y: st.wy, rawX: cx, rawY: cy, fold: st.foldDensity };
  }

  let rowIndex = 0;
  for (let gy = -120; gy <= 1320; gy += dyRow) {
    let xOffset = (rowIndex % 2 !== 0) ? dxCol * 0.5 : 0;
    for (let gx = -120 + xOffset; gx <= 1320; gx += dxCol) {
      // Quick bounds check on center
      let c0 = projectNode(gx, gy);
      if (c0.x < -30 || c0.x > 1230 || c0.y < -30 || c0.y > 1230) continue;

      // Visibility & density modulation
      if (layerId === 1 && c0.fold < 0.22 && random() < 0.35) continue;
      if (layerId === 2 && c0.fold < 0.18 && random() < 0.25) continue;

      // In pointy-top hex grid, each cell owns 3 unique edges (upper-right, upper-left, and top-vertical)
      // so every shared edge in the entire lattice is drawn once per pass without redundant overlap:
      // v0 = top vertex (0, -R), v1 = upper-right (+dx/2, -R/2), v2 = lower-right (+dx/2, +R/2), v5 = upper-left (-dx/2, -R/2)
      let v5 = projectNode(gx - dxCol * 0.5, gy - hexR * 0.5);
      let v0 = projectNode(gx, gy - hexR);
      let v1 = projectNode(gx + dxCol * 0.5, gy - hexR * 0.5);
      let v2 = projectNode(gx + dxCol * 0.5, gy + hexR * 0.5);

      let sh = getFaceShading(c0.rawX, c0.rawY);

      if (layerId === 1) {
        // LAYER 1 (DEEPEST): Blurred and doubled hexagonal mesh over the skin
        let blurCol = sh.light < 0.42
          ? random(["#8A6E7C", "#786270", "#9E828E"])
          : random(["#B896A4", "#C8B0B8", "#D8C2B8"]);
        let ghostCol = random(["#EED8E0", "#F5E8D6", "#D6C8D2"]);

        // Pass A: Soft blurred primary mesh
        brush.set("veilBlur", blurCol, 0.38);
        brush.line(v5.x, v5.y, v0.x, v0.y);
        brush.line(v0.x, v0.y, v1.x, v1.y);
        brush.line(v1.x, v1.y, v2.x, v2.y);

        // Pass B: Doubled out-of-focus offset mesh (+2.6px, +1.7px)
        let ox = 2.6, oy = 1.7;
        brush.set("2H", ghostCol, 0.22);
        brush.line(v5.x + ox, v5.y + oy, v0.x + ox, v0.y + oy);
        brush.line(v0.x + ox, v0.y + oy, v1.x + ox, v1.y + oy);
        brush.line(v1.x + ox, v1.y + oy, v2.x + ox, v2.y + oy);

      } else if (layerId === 2) {
        // LAYER 2 (MID-DISTANCE): Softly doubled oyster-grey & champagne mesh
        let midCol = c0.fold > 0.65
          ? random(["#686272", "#7E7888", "#EAEFF5"])
          : sh.light < 0.45
            ? random(["#7C7484", "#988E9C"])
            : random(["#8E7E8A", "#A89BA6", "#E8D8E0"]);

        brush.set("2H", midCol, 0.24);
        brush.line(v5.x, v5.y, v0.x, v0.y);
        brush.line(v0.x, v0.y, v1.x, v1.y);
        brush.line(v1.x, v1.y, v2.x, v2.y);

        // Doubled echo where the mid-layer billows away from the skin or folds
        if (c0.fold > 0.32 || random() < 0.55) {
          let ox = -1.6, oy = 1.3;
          let echoCol = c0.fold > 0.6 ? "#F4E8EE" : "#B8B2C0";
          brush.set("2H", echoCol, 0.18);
          brush.line(v5.x + ox, v5.y + oy, v0.x + ox, v0.y + oy);
          brush.line(v0.x + ox, v0.y + oy, v1.x + ox, v1.y + oy);
          brush.line(v1.x + ox, v1.y + oy, v2.x + ox, v2.y + oy);
        }

      } else {
        // LAYER 3 (NEAREST FOREGROUND): Razor-sharp hairline pen mesh of tiny hexagons
        let gL = getEyeGeometry(c0.rawX, c0.rawY, FACE.leftEye, false);
        let gR = getEyeGeometry(c0.rawX, c0.rawY, FACE.rightEye, true);
        let overDarkEye =
          (gL.isInsideOpening && dist(c0.rawX, c0.rawY, FACE.leftEye.ix, FACE.leftEye.iy) < FACE.leftEye.ir) ||
          (gR.isInsideOpening && dist(c0.rawX, c0.rawY, FACE.rightEye.ix, FACE.rightEye.iy) < FACE.rightEye.ir);

        // Optical behavior of fine bridal tulle thread:
        // Dark crisp hairline against luminous skin; glowing shell-pink/champagne thread over dark iris/shadows or fold ridges!
        let penCol, penW;
        if (overDarkEye) {
          penCol = random(["#F5E6EC", "#E2D4DC", "#584854"]);
          penW = 0.16;
        } else if (c0.fold > 0.72) {
          penCol = random() < 0.55
            ? random(["#FFF6FA", "#FFF9EB", "#F0F4F8"])
            : random(["#382834", "#4E3C48"]);
          penW = 0.21;
        } else if (sh.light < 0.36) {
          penCol = random(["#E8D2DC", "#F2E4D8", "#5A4652"]);
          penW = 0.17;
        } else {
          penCol = random(["#362632", "#4A3844", "#5E4A56", "#6E5864"]);
          penW = 0.18;
        }

        brush.set("rotring", penCol, penW);
        brush.line(v5.x, v5.y, v0.x, v0.y);
        brush.line(v0.x, v0.y, v1.x, v1.y);
        brush.line(v1.x, v1.y, v2.x, v2.y);

        // Micro-bobbinet thread twist at the 3-way hexagonal vertices!
        if (random() < 0.65) {
          let twistCol = c0.fold > 0.55 ? "#FFF8FA" : "#2A1C26";
          brush.set("microPen", twistCol, 0.22);
          brush.line(v0.x - 0.9, v0.y - 0.4, v0.x + 0.9, v0.y + 0.4);
          brush.line(v1.x - 0.4, v1.y - 0.9, v1.x + 0.4, v1.y + 0.9);
        }

        // Where the fabric folds over itself in a pleat (fold > 0.58), draw the compressed
        // folded-under ply of the hexagonal mesh to create a vivid geometric fold moiré!
        if (c0.fold > 0.58) {
          let fx = 4.2 * Math.sin(gx * 0.04), fy = 3.6 * Math.cos(gy * 0.04);
          let foldCol = random(["#685462", "#FFF0F5", "#D8CED8"]);
          brush.set("rotring", foldCol, 0.15);
          brush.line(v5.x + fx, v5.y + fy, v0.x + fx * 0.6, v0.y + fy * 0.6);
          brush.line(v0.x + fx * 0.6, v0.y + fy * 0.6, v1.x + fx, v1.y + fy);
        }
      }
    }
    rowIndex++;
  }
}

// ============================================================================
// MAIN DRAW LOOP
// ============================================================================

function draw() {
  translate(-width / 2, -height / 2);
  background("#FBF3EE");

  // 1. Vivid subsurface watercolor underpainting (batched by color)
  renderSubsurfaceUnderpainting();

  // 2. Hyperrealist colored pencil 3D skin modeling
  renderColoredPencilSkin();

  // 3. Ruthless pore-level precision: skin pores, sulci, eyes, irises, lashes, brows & lips
