function evalCatmullRom(p0, p1, p2, p3, t) {
  let t2 = t * t;
  let t3 = t2 * t;
  let out = [];
  for (let k = 0; k < p0.length; k++) {
    let v0 = p0[k], v1 = p1[k], v2 = p2[k], v3 = p3[k];
    let a = -0.5 * v0 + 1.5 * v1 - 1.5 * v2 + 0.5 * v3;
    let b = v0 - 2.5 * v1 + 2.0 * v2 - 0.5 * v3;
    let c = -0.5 * v0 + 0.5 * v2;
    let d = v1;
    out.push(a * t3 + b * t2 + c * t + d);
  }
  return out;
}

function sampleSpline(ctrlPts, numSamples) {
  let samples = [];
  let n = ctrlPts.length;
  for (let i = 0; i < numSamples; i++) {
    let u = i / (numSamples - 1);
    let segFloat = u * (n - 1);
    let idx = Math.min(n - 2, Math.floor(segFloat));
    let t = segFloat - idx;
    let p0 = ctrlPts[Math.max(0, idx - 1)];
    let p1 = ctrlPts[idx];
    let p2 = ctrlPts[idx + 1];
    let p3 = ctrlPts[Math.min(n - 1, idx + 2)];
    let val = evalCatmullRom(p0, p1, p2, p3, t);
    samples.push({ u, val, tx: 0, ty: 0, nx: 0, ny: 0 });
  }
  for (let i = 0; i < numSamples; i++) {
    let i0 = Math.max(0, i - 1);
    let i1 = Math.min(numSamples - 1, i + 1);
    let dx = samples[i1].val[0] - samples[i0].val[0];
    let dy = samples[i1].val[1] - samples[i0].val[1];
    let len = Math.hypot(dx, dy) || 1;
    samples[i].tx = dx / len;
    samples[i].ty = dy / len;
    // Outward normal (pointing away from center of clockwise curl)
    samples[i].nx = samples[i].ty;
    samples[i].ny = -samples[i].tx;
  }
  return samples;
}

