function evalQuadBezierDist(x, y, p0, p1, p2) {
  let minD2 = 1e12;
  let bestT = 0;
  let bestX = p0[0], bestY = p0[1];
  let bestTX = 1, bestTY = 0;
  const steps = 14;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let mt = 1 - t;
    let bx = mt * mt * p0[0] + 2 * mt * t * p1[0] + t * t * p2[0];
    let by = mt * mt * p0[1] + 2 * mt * t * p1[1] + t * t * p2[1];
    let d2 = (x - bx) * (x - bx) + (y - by) * (y - by);
    if (d2 < minD2) {
      minD2 = d2;
      bestT = t;
      bestX = bx;
      bestY = by;
    }
  }
  // Refine with 1 step around bestT
  let dt = 1 / steps;
  for (let sub = -2; sub <= 2; sub++) {
    let t = Math.max(0, Math.min(1, bestT + sub * 0.25 * dt));
    let mt = 1 - t;
    let bx = mt * mt * p0[0] + 2 * mt * t * p1[0] + t * t * p2[0];
    let by = mt * mt * p0[1] + 2 * mt * t * p1[1] + t * t * p2[1];
    let d2 = (x - bx) * (x - bx) + (y - by) * (y - by);
    if (d2 < minD2) {
      minD2 = d2;
      bestT = t;
      bestX = bx;
      bestY = by;
    }
  }
  let mt = 1 - bestT;
  let tx = 2 * mt * (p1[0] - p0[0]) + 2 * bestT * (p2[0] - p1[0]);
  let ty = 2 * mt * (p1[1] - p0[1]) + 2 * bestT * (p2[1] - p1[1]);
  let tLen = Math.hypot(tx, ty) || 1;
  bestTX = tx / tLen;
  bestTY = ty / tLen;
  let nx = -bestTY;
  let ny = bestTX;
  let signedD = (x - bestX) * nx + (y - bestY) * ny;
  return { signedD, t: bestT, tx: bestTX, ty: bestTY };
}

function buildSceneGrid() {
  for (let gy = 0; gy < GRID_N; gy++) {
    let y = gy * STEP;
    for (let gx = 0; gx < GRID_N; gx++) {
      let x = gx * STEP;
      let idx = gy * GRID_N + gx;

      // --- 1. RUMPLED WHITE LINEN BED HEIGHTFIELD ---
      // Base mattress pillow & diagonal loft
      let dDiag = (x + y) * 0.7071;
      let dPerp = (x - y) * 0.7071;
      let zMattress = 18 * Math.exp(-Math.pow(dPerp / 620, 2));

      // Upper-left pillow volume
      let pillowFactor = Math.max(0, 1 - Math.hypot(x - 160, y - 150) / 360);
      zMattress += 34 * Math.pow(pillowFactor, 1.6);

      // Depression basin where the sleeping greyhound's weight sinks into the mattress
      let distToCenter = Math.hypot(x - 605, y - 595);
      let basinSink = -28 * Math.exp(-Math.pow(distToCenter / 270, 2));
      // Soft displaced linen bolster ring just outside the curled dog
      let bolsterRing = 14 * Math.exp(-Math.pow((distToCenter - 255) / 85, 2));
      zMattress += basinSink + bolsterRing;

      // Sum explicit sculptural linen folds
      let zFolds = 0;
      let domWeight = 0.01;
      let lvx = 0.7071, lvy = 0.7071;

      for (let f = 0; f < linenFolds.length; f++) {
        let fold = linenFolds[f];
        // Quick bounding box check
        let minX = Math.min(fold.p0[0], fold.p1[0], fold.p2[0]) - fold.w * 2.2;
        let maxX = Math.max(fold.p0[0], fold.p1[0], fold.p2[0]) + fold.w * 2.2;
        let minY = Math.min(fold.p0[1], fold.p1[1], fold.p2[1]) - fold.w * 2.2;
        let maxY = Math.max(fold.p0[1], fold.p1[1], fold.p2[1]) + fold.w * 2.2;
        if (x < minX || x > maxX || y < minY || y > maxY) continue;

        let res = evalQuadBezierDist(x, y, fold.p0, fold.p1, fold.p2);
        let dNorm = res.signedD / fold.w;
        if (Math.abs(dNorm) < 2.1) {
          let endTaper = Math.sin(Math.PI * Math.max(0.02, Math.min(0.98, res.t)));
          endTaper = Math.pow(endTaper, 0.55);
          let da = dNorm + fold.asym * dNorm * dNorm;
          let prof = Math.exp(-2.6 * da * da)
            - 0.26 * Math.exp(-1.4 * Math.pow(da - 0.88, 2))
            - 0.22 * Math.exp(-1.4 * Math.pow(da + 0.88, 2));
          let contrib = fold.amp * endTaper * prof;
          zFolds += contrib;
          let wInfluence = Math.abs(contrib);
          if (wInfluence > domWeight) {
            domWeight = wInfluence;
            lvx = res.tx;
            lvy = res.ty;
          }
        }
      }

      // Secondary washed-linen crinkle & micro-creases
      let n1 = noise(x * 0.0065, y * 0.0065);
      let n2 = noise(x * 0.018 + n1 * 2.2, y * 0.018 - n1 * 2.2);
      let crinkle = (1.0 - Math.abs(2.0 * n2 - 1.0));
      zFolds += 7.5 * Math.pow(crinkle, 2.2) - 3.2;

      let zLinenTotal = zMattress + zFolds;

      // --- 2. SLEEPING GREYHOUND 3D ANATOMICAL SCULPT ---
      let zDog = -999;
      let dogMask = 0;
      let bestU = 0;
      let bestW = 0;
      let partID = 0;
      let albedo = 0.92; // Linen albedo
      let fx = lvx, fy = lvy;

      // A. Evaluate Torso / Neck / Ribcage / Flank / Haunch
      if (x > 410 && x < 860 && y > 350 && y < 840) {
        let minDist2 = 1e12;
        let bestS = null;
        for (let i = 0; i < spineSamples.length; i++) {
          let s = spineSamples[i];
          let dx = x - s.val[0];
          let dy = y - s.val[1];
          let d2 = dx * dx + dy * dy;
          if (d2 < minDist2) {
            minDist2 = d2;
            bestS = s;
          }
        }
        if (bestS) {
          let u = bestS.u;
          let dx = x - bestS.val[0];
          let dy = y - bestS.val[1];
          let dLat = dx * bestS.nx + dy * bestS.ny;
          let rOut = bestS.val[2];
          let rIn = bestS.val[3];
          let zH = bestS.val[4];
          let dMid = 0.5 * (rOut - rIn);
          let wHalf = 0.5 * (rOut + rIn);
          let w = (dLat - dMid) / wHalf; // [-1 = inner belly/chest, +1 = outer spine edge]

          if (Math.abs(w) < 1.08) {
            let wClamped = Math.max(-0.999, Math.min(0.999, w));
            let maskEdge = Math.max(0, Math.min(1, (1.04 - Math.abs(w)) / 0.08));
            let baseCyl = Math.sqrt(Math.max(0, 1 - wClamped * wClamped));
            // Dorsal vertebral spine prominence at w ≈ +0.38
            let spineRidge = 0.14 * Math.exp(-Math.pow((wClamped - 0.38) / 0.20, 2));
            let zT = zH * baseCyl * (1 + spineRidge);

            // Individual Vertebral Bumps along spine (u ∈ [0.20, 0.85], w ≈ +0.38)
            if (u > 0.18 && u < 0.86) {
              let vEnv = Math.sin(Math.PI * (u - 0.18) / 0.68) * Math.exp(-Math.pow((wClamped - 0.38) / 0.12, 2));
              let vWave = Math.pow(0.5 + 0.5 * Math.cos((u - 0.18) * 195), 1.6);
              zT += 2.6 * vEnv * vWave;
            }

            // THE 9 ANATOMICAL RIBS (u ∈ [0.24, 0.61])
            let ribDelta = 0;
            if (u > 0.22 && u < 0.63) {
              // Ribs arch caudally near the spine and sweep ventrally across the barrel chest
              let uRib = u - 0.034 * (0.38 - wClamped) - 0.018 * Math.pow(0.38 - wClamped, 2);
              if (uRib > 0.24 && uRib < 0.59) {
                let envU = Math.pow(Math.sin(Math.PI * (uRib - 0.24) / 0.35), 0.85);
                let envW = Math.exp(-Math.pow((wClamped + 0.08) / 0.54, 2)) * (1 - wClamped * wClamped);
                let phase = (uRib - 0.24) / 0.35 * 8.5 * Math.PI * 2;
                let ribWave = Math.pow(0.5 + 0.5 * Math.cos(phase), 1.35) - 0.44;
                ribDelta = 10.5 * envU * envW * ribWave;
                zT += ribDelta;
              }
            }

            // Scapula (Shoulder Blade) ridge (u ∈ [0.15, 0.29])
            if (u > 0.14 && u < 0.30) {
              let uScap = u - 0.22 + 0.045 * (0.35 - wClamped);
              let scapRidge = 6.0 * Math.exp(-Math.pow(uScap / 0.028, 2)) * Math.exp(-Math.pow((wClamped + 0.05) / 0.42, 2));
              zT += scapRidge;
            }

            // Deep Sighthound Flank Hollow (Tuck-up) between last rib and hip (u ∈ [0.58, 0.77])
            if (u > 0.58 && u < 0.77) {
              let flankDip = -9.5 * Math.sin(Math.PI * (u - 0.58) / 0.19) * Math.exp(-Math.pow((wClamped + 0.18) / 0.45, 2));
              zT += flankDip;
            }

            // Iliac Crest (Hip bone point) & Muscular Thigh / Haunch (u ∈ [0.75, 0.95])
            if (u > 0.74 && u < 0.96) {
              let ilium = 6.5 * Math.exp(-Math.pow((u - 0.80) / 0.035, 2)) * Math.exp(-Math.pow((wClamped - 0.30) / 0.16, 2));
              let thighSwirl = 8.0 * Math.exp(-Math.pow((u - 0.85) / 0.065, 2)) * Math.exp(-Math.pow((wClamped + 0.18) / 0.42, 2));
              zT += ilium + thighSwirl;
            }

            zDog = zMattress + 8 + zT;
            dogMask = maskEdge;
            bestU = u;
            bestW = wClamped;
            partID = 1;

            // Coat pattern: cool pewter/silver-graphite coat with white brisket/chest & subtle dorsal shading
            let chestWhite = (u < 0.35 && wClamped < -0.45) ? 0.32 * Math.exp(-Math.pow((u - 0.20) / 0.14, 2)) : 0;
            let dorsalDark = -0.14 * Math.exp(-Math.pow((wClamped - 0.35) / 0.35, 2));
            albedo = Math.max(0.28, Math.min(0.88, 0.56 + chestWhite + dorsalDark));

            // Fur growth vector: flows caudally along spine tangent, curving slightly ventrally across ribs/flank
            let ventTwist = -0.26 * (1 - Math.abs(wClamped));
            fx = bestS.tx * Math.cos(ventTwist) - bestS.ty * Math.sin(ventTwist);
            fy = bestS.tx * Math.sin(ventTwist) + bestS.ty * Math.cos(ventTwist);
          }
        }
      }

      // B. Evaluate Head & Sighthound Muzzle
      if (x > 340 && x < 520 && y > 390 && y < 620) {
        let minDist2 = 1e12;
        let bestH = null;
        for (let i = 0; i < headSamples.length; i++) {
          let s = headSamples[i];
          let dx = x - s.val[0];
          let dy = y - s.val[1];
          let d2 = dx * dx + dy * dy;
          if (d2 < minDist2) {
            minDist2 = d2;
            bestH = s;
          }
        }
        if (bestH) {
          let uH = bestH.u;
          let dx = x - bestH.val[0];
          let dy = y - bestH.val[1];
          let dLat = dx * bestH.nx + dy * bestH.ny;
          let wHalf = 0.5 * (bestH.val[2] + bestH.val[3]);
          let wH = dLat / wHalf;
          if (Math.abs(wH) < 1.06 && uH >= 0 && uH <= 1) {
            let wClamped = Math.max(-0.999, Math.min(0.999, wH));
            let maskH = Math.max(0, Math.min(1, (1.03 - Math.abs(wH)) / 0.08));
            // Taper nose tip smoothly
            if (uH > 0.92) maskH *= Math.max(0, (1.0 - uH) / 0.08);
            let zHeadVal = zMattress + 10 + bestH.val[4] * Math.sqrt(Math.max(0, 1 - wClamped * wClamped));

            // Supraorbital brow ridge around uH ≈ 0.42, wH ≈ -0.45
            let brow = 4.2 * Math.exp(-Math.pow((uH - 0.40) / 0.08, 2)) * Math.exp(-Math.pow((wClamped + 0.42) / 0.25, 2));
            zHeadVal += brow;

            if (zHeadVal > zDog) {
              zDog = zHeadVal;
              dogMask = Math.max(dogMask, maskH);
              partID = 2;
              fx = bestH.tx;
              fy = bestH.ty;
              // White sighthound muzzle blaze & dark rhinarium (nose tip)
              let blaze = (Math.abs(wClamped) < 0.32 && uH > 0.35 && uH < 0.88) ? 0.28 : 0;
              albedo = 0.58 + blaze;
              if (uH > 0.88) {
                partID = 7; // Dark nose leather
                albedo = 0.16;
              }
            }
          }
        }
      }

      // C. Evaluate Ears, Tucked Slender Legs, Paws & Whip Tail
      for (let L = 0; L < limbCurves.length; L++) {
        let limb = limbCurves[L];
        let pts = limb.pts;
        let minDist2 = 1e12;
        let bestP = null;
        for (let i = 0; i < pts.length; i++) {
          let s = pts[i];
          let dx = x - s.val[0];
          let dy = y - s.val[1];
          let d2 = dx * dx + dy * dy;
          if (d2 < minDist2) {
            minDist2 = d2;
            bestP = s;
          }
        }
        if (bestP) {
          let rad = bestP.val[2];
          let dist = Math.sqrt(minDist2);
          if (dist < rad * 1.06) {
            let wL = ((x - bestP.val[0]) * bestP.nx + (y - bestP.val[1]) * bestP.ny) / rad;
            let wClamped = Math.max(-0.999, Math.min(0.999, wL));
            let maskL = Math.max(0, Math.min(1, (1.03 - Math.abs(wL)) / 0.10));
            if (bestP.u > 0.92) maskL *= Math.max(0, (1.0 - bestP.u) / 0.08);
            let zLimb = zMattress + 8 + bestP.val[3] * Math.sqrt(Math.max(0, 1 - wClamped * wClamped));

            // Add individual knuckled toe ridges at the paw tips of forelegs and hindlegs
            if ((limb.id === 4 || limb.id === 5) && bestP.u > 0.78) {
              let toeWave = 2.8 * Math.cos(wClamped * Math.PI * 3.5) * (1 - wClamped * wClamped);
              zLimb += toeWave;
            }

            if (zLimb > zDog) {
              zDog = zLimb;
              dogMask = Math.max(dogMask, maskL);
              partID = limb.id;
              fx = bestP.tx;
              fy = bestP.ty;
              // White stockings on paws and tail tip
              let pawWhite = (bestP.u > 0.72) ? 0.25 : 0;
              albedo = Math.min(0.90, limb.albedo + pawWhite);
            }
          }
        }
      }

      // Blend Dog & Linen Heightfields seamlessly
      let finalZ = zLinenTotal;
      let finalDetail = zFolds;
      let finalMacro = zMattress;

      if (dogMask > 0.001) {
        finalZ = zLinenTotal * (1 - dogMask) + zDog * dogMask;
        finalMacro = zMattress * (1 - dogMask) + (zMattress + 42) * dogMask;
        finalDetail = finalZ - finalMacro;
      } else {
        partID = 0;
        albedo = 0.92;
        fx = lvx;
        fy = lvy;
      }

      gridZ[idx] = finalZ;
      gridZDetail[idx] = finalDetail;
      gridZMacro[idx] = finalMacro;
      gridDogMask[idx] = dogMask;
      gridDogU[idx] = bestU;
      gridDogW[idx] = bestW;
      gridAlbedo[idx] = albedo;
      gridFurX[idx] = fx;
      gridFurY[idx] = fy;
      gridLinenX[idx] = lvx;
      gridLinenY[idx] = lvy;
      gridPartID[idx] = partID;
    }
  }

  // Compute Surface Normals, Ridge Curvature & Ambient Occlusion
  for (let gy = 1; gy < GRID_N - 1; gy++) {
    for (let gx = 1; gx < GRID_N - 1; gx++) {
      let idx = gy * GRID_N + gx;
      let dzdx = (gridZ[idx + 1] - gridZ[idx - 1]) / (2 * STEP);
      let dzdy = (gridZ[idx + GRID_N] - gridZ[idx - GRID_N]) / (2 * STEP);
      let nx = -dzdx * 2.4;
      let ny = -dzdy * 2.4;
      let nz = 1.0;
      let nLen = Math.hypot(nx, ny, nz) || 1;
      gridNX[idx] = nx / nLen;
      gridNY[idx] = ny / nLen;
      gridNZ[idx] = nz / nLen;

      // Second derivative Laplacian for ridge crest (+)/valley trough (-) detection
      let zC = gridZ[idx];
      let lap = (gridZ[idx + 1] + gridZ[idx - 1] + gridZ[idx + GRID_N] + gridZ[idx - GRID_N] - 4 * zC) / (STEP * STEP);
      gridRidge[idx] = Math.max(-1, Math.min(1, -lap * 14.0));

      // Ambient occlusion in deep linen troughs and around the curled dog's contact perimeter
      let dogM = gridDogMask[idx];
      let contactCrevice = 4.0 * dogM * (1.0 - dogM); // peaks at silhouette contact boundary
      let valleyDark = Math.max(0, -gridZDetail[idx] / 28.0);
      gridAO[idx] = Math.max(0.18, Math.min(1.0, 1.0 - 0.55 * contactCrevice - 0.35 * valleyDark + 0.15 * gridRidge[idx]));
    }
  }
}

function sampleScene(x, y) {
  let gx = Math.max(1, Math.min(GRID_N - 2.001, x / STEP));
  let gy = Math.max(1, Math.min(GRID_N - 2.001, y / STEP));
  let ix = Math.floor(gx);
  let iy = Math.floor(gy);
  let fx = gx - ix;
  let fy = gy - iy;

  let i00 = iy * GRID_N + ix;
  let i10 = i00 + 1;
  let i01 = i00 + GRID_N;
  let i11 = i01 + 1;

  let w00 = (1 - fx) * (1 - fy);
  let w10 = fx * (1 - fy);
  let w01 = (1 - fx) * fy;
  let w11 = fx * fy;

  let z = gridZ[i00] * w00 + gridZ[i10] * w10 + gridZ[i01] * w01 + gridZ[i11] * w11;
  let zDetail = gridZDetail[i00] * w00 + gridZDetail[i10] * w10 + gridZDetail[i01] * w01 + gridZDetail[i11] * w11;
  let zMacro = gridZMacro[i00] * w00 + gridZMacro[i10] * w10 + gridZMacro[i01] * w01 + gridZMacro[i11] * w11;
  let nx = gridNX[i00] * w00 + gridNX[i10] * w10 + gridNX[i01] * w01 + gridNX[i11] * w11;
  let ny = gridNY[i00] * w00 + gridNY[i10] * w10 + gridNY[i01] * w01 + gridNY[i11] * w11;
  let nz = gridNZ[i00] * w00 + gridNZ[i10] * w10 + gridNZ[i01] * w01 + gridNZ[i11] * w11;
  let ridge = gridRidge[i00] * w00 + gridRidge[i10] * w10 + gridRidge[i01] * w01 + gridRidge[i11] * w11;
  let ao = gridAO[i00] * w00 + gridAO[i10] * w10 + gridAO[i01] * w01 + gridAO[i11] * w11;
  let dogMask = gridDogMask[i00] * w00 + gridDogMask[i10] * w10 + gridDogMask[i01] * w01 + gridDogMask[i11] * w11;
  let albedo = gridAlbedo[i00] * w00 + gridAlbedo[i10] * w10 + gridAlbedo[i01] * w01 + gridAlbedo[i11] * w11;

  // Lighting from quiet morning window (upper-right-top)
  const lx = 0.56, ly = -0.48, lz = 0.67;
  let ndotl = Math.max(0, nx * lx + ny * ly + nz * lz);
  let light = (0.32 + 0.68 * ndotl) * ao;

  return {
    z, zDetail, zMacro, nx, ny, nz, ridge, ao, dogMask, albedo, light,
    dogU: gridDogU[i00],
    dogW: gridDogW[i00],
    furX: gridFurX[i00],
    furY: gridFurY[i00],
    linenX: gridLinenX[i00],
    linenY: gridLinenY[i00],
    partID: gridPartID[i00]
  };
}

// ============================================================================
// PRISM RAINBOW 3D PROJECTION & BENDING ENGINE
// ============================================================================

// The narrow prism beam enters from an unseen window in the upper-right and sweeps
// across the diagonal folds and the greyhound's ribcage/flank toward the lower-left.
const PRISM_X0 = 695;
const PRISM_Y0 = 562;
// Tangent along stripe (upper-right to lower-left: ~136 degrees)
const PRISM_TX = -0.695;
const PRISM_TY = 0.719;
// Normal across stripe (pointing down-right: ~46 degrees)
const PRISM_NX = 0.719;
const PRISM_NY = 0.695;

function evalPrismCoord(x, y) {
  let sc = sampleScene(x, y);
  let s = (x - PRISM_X0) * PRISM_TX + (y - PRISM_Y0) * PRISM_TY;
  let wFlat = (x - PRISM_X0) * PRISM_NX + (y - PRISM_Y0) * PRISM_NY;

  // Grazing window light bends the spectrum over every fabric fold and every rib!
  let bendOffset = 0.58 * (sc.zMacro - 15.0) + 1.95 * sc.zDetail;
  let wBent = wFlat - bendOffset;

  // Optical dispersion widens the prism beam slightly as it travels across the bed
  let halfWidth = 50.0 - 0.011 * s;
  let p = wBent / halfWidth; // Normalized spectral coordinate [-1 = Cadmium Red, +1 = Violet]

  // Grazing illumination factor for the prism beam
  let prismLight = Math.max(0.08, 0.58 * sc.nx - 0.52 * sc.ny + 0.62 * sc.nz);

  return { s, wFlat, wBent, p, halfWidth, prismLight, sc };
}

// Solve for exact (x, y) on the 3D surface corresponding to stripe position `s` and spectral phase `pTarget`
function solvePrismPoint(s, pTarget) {
  let halfWidth = 50.0 - 0.011 * s;
  let wTarget = pTarget * halfWidth;
  let wFlatGuess = wTarget;
  for (let iter = 0; iter < 4; iter++) {
    let x = PRISM_X0 + s * PRISM_TX + wFlatGuess * PRISM_NX;
    let y = PRISM_Y0 + s * PRISM_TY + wFlatGuess * PRISM_NY;
    let sc = sampleScene(x, y);
    let bendOffset = 0.58 * (sc.zMacro - 15.0) + 1.95 * sc.zDetail;
    wFlatGuess = wTarget + bendOffset;
  }
  let x = PRISM_X0 + s * PRISM_TX + wFlatGuess * PRISM_NX;
  let y = PRISM_Y0 + s * PRISM_TY + wFlatGuess * PRISM_NY;
  return { x, y, sc: sampleScene(x, y) };
}

// ============================================================================
// SAFE DRAWING HELPERS
// ============================================================================

function drawSafeSpline(pts, curvature = 0.5) {
  if (!pts || pts.length < 3) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = clean[clean.length - 1];
    if (Math.hypot(pts[i][0] - prev[0], pts[i][1] - prev[1]) > 1.8) {
      clean.push(pts[i]);
    }
  }
  if (clean.length >= 3) {
    brush.spline(clean, curvature);
  } else if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  }
}

function drawSafeShape(pts, curvature = 0.35, closed = true) {
  if (!pts || pts.length < 3) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = clean[clean.length - 1];
    if (Math.hypot(pts[i][0] - prev[0], pts[i][1] - prev[1]) > 2.0) {
      clean.push(pts[i]);
    }
  }
  if (clean.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < clean.length; i++) {
    brush.vertex(clean[i][0], clean[i][1]);
  }
  brush.endShape(closed);
}

// ============================================================================
// LAYER 0: DUSKY TWILIGHT PAPER GROUND & ATMOSPHERIC UNDERTONE
// ============================================================================

function renderTwilightPaperGround() {
  brush.noStroke();
  brush.noHatch();

  // Cool dusky twilight atmospheric washes in corners and deep mattress basins
  const washes = [
    { col: "#abb3c2", op: 42, x: 600, y: 600, w: 1180, h: 1180 },
    { col: "#c9cfd8", op: 55, x: 560, y: 550, w: 920, h: 860 },
    { col: "#9ea7b8", op: 38, x: 180, y: 980, w: 520, h: 420 },
    { col: "#9ea7b8", op: 35, x: 1020, y: 980, w: 460, h: 420 },
    { col: "#a4adbe", op: 36, x: 605, y: 605, w: 520, h: 500 }
  ];

  for (let w of washes) {
    brush.wash(w.col, w.op);
    brush.rect(w.x, w.y, w.w, w.h, "center");
  }
  brush.noWash();

  // Subtle watercolor paper tooth & twilight shadow pools in deep fold valleys
  brush.fill("#9099ab", 28);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.55, 0.2);

  for (let f = 0; f < linenFolds.length; f += 2) {
    let fold = linenFolds[f];
    let poly = [];
    for (let t = 0.1; t <= 0.9; t += 0.2) {
      let mt = 1 - t;
      let bx = mt * mt * fold.p0[0] + 2 * mt * t * fold.p1[0] + t * t * fold.p2[0];
      let by = mt * mt * fold.p0[1] + 2 * mt * t * fold.p1[1] + t * t * fold.p2[1];
      poly.push([bx + fold.w * 0.65, by + fold.w * 0.55]);
    }
    for (let t = 0.9; t >= 0.1; t -= 0.2) {
      let mt = 1 - t;
      let bx = mt * mt * fold.p0[0] + 2 * mt * t * fold.p1[0] + t * t * fold.p2[0];
      let by = mt * mt * fold.p0[1] + 2 * mt * t * fold.p1[1] + t * t * fold.p2[1];
      poly.push([bx + fold.w * 1.35, by + fold.w * 1.15]);
    }
    drawSafeShape(poly, 0.45, true);
  }
  brush.noFill();
}

// ============================================================================
// LAYER 1: RUMPLED WHITE LINEN — SOFT GRAPHITE & WHITE PENCIL UNDERDRAWING
// ============================================================================

function renderLinenUnderdrawing() {
  brush.noFill();
  brush.noHatch();

  // 1. Trace long sculptural graphite shading & white pencil highlights along every explicit fold
  for (let f = 0; f < linenFolds.length; f++) {
    let fold = linenFolds[f];
    let tx = fold.p2[0] - fold.p0[0];
    let ty = fold.p2[1] - fold.p0[1];
    let len = Math.hypot(tx, ty) || 1;
    let nx = -ty / len;
    let ny = tx / len;

    // Cross-sectional offsets across each fold: trough -> shadow flank -> crest -> sunlit flank -> trough
    for (let band = -14; band <= 14; band++) {
      let dNorm = band / 9.0;
      let offset = dNorm * fold.w;
      let pts = [];
      let avgLight = 0;
      let avgRidge = 0;
      let validCount = 0;

      for (let s = 0; s <= 14; s++) {
        let t = s / 14;
        let mt = 1 - t;
        let bx = mt * mt * fold.p0[0] + 2 * mt * t * fold.p1[0] + t * t * fold.p2[0] + nx * offset;
        let by = mt * mt * fold.p0[1] + 2 * mt * t * fold.p1[1] + t * t * fold.p2[1] + ny * offset;
        if (bx < 15 || bx > 1185 || by < 15 || by > 1185) continue;
        let sc = sampleScene(bx, by);
        if (sc.dogMask > 0.25) {
          if (pts.length >= 3) drawFoldStroke(pts, avgLight / validCount, avgRidge / validCount);
          pts = [];
          avgLight = 0;
          avgRidge = 0;
          validCount = 0;
          continue;
        }
        pts.push([bx + random(-1.5, 1.5), by + random(-1.5, 1.5), 0.4 + 0.6 * Math.sin(Math.PI * t)]);
        avgLight += sc.light;
        avgRidge += sc.ridge;
        validCount++;
      }
      if (pts.length >= 3 && validCount > 0) {
        drawFoldStroke(pts, avgLight / validCount, avgRidge / validCount);
      }
    }
  }

  // 2. Grid-guided flow strokes & cross-contour modeling over the rumpled linen bed
  const step = 22;
  for (let y = 24; y < 1176; y += step) {
    for (let x = 24; x < 1176; x += step) {
      let jx = x + random(-7, 7);
      let jy = y + random(-7, 7);
      let sc = sampleScene(jx, jy);
      if (sc.dogMask > 0.15) continue;

      // Determine stroke direction: mix of fold tangent and cross-contour gradient
      let isCross = random() < 0.38;
      let dirX = isCross ? sc.nx : sc.linenX;
      let dirY = isCross ? sc.ny : sc.linenY;
      let dLen = Math.hypot(dirX, dirY) || 1;
      dirX /= dLen;
      dirY /= dLen;

      // Trace 5-point streamline on linen
      let pts = [];
      let cx = jx, cy = jy;
      let strokeLen = isCross ? random(24, 46) : random(38, 72);
      let ds = strokeLen / 4;

      for (let k = -2; k <= 2; k++) {
        let px = cx + k * ds * dirX + random(-1.0, 1.0);
        let py = cy + k * ds * dirY + random(-1.0, 1.0);
        if (px < 12 || px > 1188 || py < 12 || py > 1188) continue;
        if (sampleScene(px, py).dogMask > 0.2) continue;
        pts.push([px, py, k === 0 ? 1.0 : 0.45]);
      }

      if (pts.length < 3) continue;

      // Select soft graphite vs white pencil based on surface lighting & ridge curvature
      let lum = sc.light + 0.16 * sc.ridge;
      if (lum < 0.44) {
        // Deep fold trough: soft dark graphite
        let col = lum < 0.34 ? "#3e4554" : "#565e70";
        brush.set("graphite_soft", col, random(0.85, 1.35));
        drawSafeSpline(pts, 0.45);
        if (lum < 0.36) {
          brush.set("2B", "#353b48", random(0.65, 0.95));
          drawSafeSpline(pts, 0.5);
        }
      } else if (lum < 0.58) {
        // Cool silvery graphite half-tone
        let col = lum < 0.51 ? "#6f7788" : "#8991a1";
        brush.set("HB", col, random(0.65, 1.05));
        drawSafeSpline(pts, 0.4);
      } else if (lum > 0.64) {
        // Sunlit linen fold flank & ridge: white pencil buildup!
        let col = lum > 0.78 ? "#f5f7fb" : (lum > 0.71 ? "#e6e9f0" : "#d6dbe4");
        brush.set("white_chalk_pencil", col, random(0.8, 1.35));
        drawSafeSpline(pts, 0.45);
        if (lum > 0.75) {
          brush.set("cpencil", "#ffffff", random(0.7, 1.1));
          drawSafeSpline(pts, 0.4);
        }
      }
    }
  }
}

function drawFoldStroke(pts, light, ridge) {
  let lum = light + 0.18 * ridge;
  if (lum < 0.46) {
    let col = lum < 0.36 ? "#3b4250" : "#555d6e";
    brush.set("graphite_soft", col, random(0.9, 1.4));
    drawSafeSpline(pts, 0.5);
  } else if (lum > 0.63) {
    let col = lum > 0.76 ? "#f4f6fa" : "#dfe3ec";
    brush.set("white_chalk_pencil", col, random(0.85, 1.3));
    drawSafeSpline(pts, 0.5);
  } else {
    brush.set("2H", "#7c8494", random(0.6, 0.95));
    drawSafeSpline(pts, 0.45);
  }
}

// ============================================================================
// LAYER 2: SLEEPING GREYHOUND — ANATOMICAL GRAPHITE & WHITE PENCIL MODELING
// ============================================================================

function renderGreyhoundUnderdrawing() {
  brush.noFill();
  brush.noHatch();

  // 1. Deep contact crevice shadow nesting the curled greyhound into the linen creases
  for (let gy = 65; gy < 310; gy += 2) {
    for (let gx = 95; gx < 315; gx += 2) {
      let idx = gy * GRID_N + gx;
      let dm = gridDogMask[idx];
      if (dm > 0.04 && dm < 0.78) {
        let x = gx * STEP + random(-2, 2);
        let y = gy * STEP + random(-2, 2);
        let fx = gridFurX[idx], fy = gridFurY[idx];
        brush.set("graphite_soft", dm < 0.38 ? "#282d38" : "#3a404f", random(0.9, 1.4));
        brush.line(x - fx * 11, y - fy * 11, x + fx * 11, y + fy * 11);
      }
    }
  }

  // 2. Smooth anatomical shading across torso, neck, ribcage, tucked flank, pelvis, head & limbs
  const dogStep = 9;
  for (let y = 370; y < 835; y += dogStep) {
    for (let x = 335; x < 845; x += dogStep) {
      let jx = x + random(-3, 3);
      let jy = y + random(-3, 3);
      let sc = sampleScene(jx, jy);
      if (sc.dogMask < 0.35) continue;

      let fx = sc.furX, fy = sc.furY;
      let fLen = Math.hypot(fx, fy) || 1;
      fx /= fLen;
      fy /= fLen;

      let halfL = random(7, 14);
      let pts = [
        [jx - fx * halfL, jy - fy * halfL, 0.35],
        [jx + fy * random(-1.2, 1.2), jy - fx * random(-1.2, 1.2), 1.0],
        [jx + fx * halfL, jy + fy * halfL, 0.35]
      ];

      // Combine lighting, coat albedo, and rib/spine curvature
      let val = sc.light * (0.55 + 0.45 * sc.albedo) + 0.14 * sc.ridge;

      if (val < 0.32) {
        brush.set("2B", "#232730", random(0.75, 1.15));
        drawSafeSpline(pts, 0.4);
      } else if (val < 0.44) {
        brush.set("graphite_soft", "#393f4d", random(0.7, 1.1));
        drawSafeSpline(pts, 0.4);
      } else if (val < 0.56) {
        brush.set("HB", "#586070", random(0.65, 1.0));
        drawSafeSpline(pts, 0.35);
      } else if (val < 0.67) {
        brush.set("2H", "#7c8494", random(0.65, 0.95));
        drawSafeSpline(pts, 0.35);
      } else {
        // Illuminated fur on spine, rib crests, shoulder, brow, white paws & chest
        let wCol = val > 0.78 ? "#f2f5fa" : "#d8dde6";
        brush.set("white_chalk_pencil", wCol, random(0.65, 1.05));
        drawSafeSpline(pts, 0.35);
      }
    }
  }
}

// ============================================================================
// LAYER 3: WET-IN-WET WATERCOLOUR PRISM RAINBOW (BENDING OVER EVERY FOLD & RIB)
// ============================================================================

function renderPrismWatercolourStripe() {
  brush.noStroke();
  brush.noHatch();

  // Spectral palette: Cadmium Red bleeding into Lemon, Viridian, Ultramarine & Violet
  const spectralBands = [
    { name: "Cadmium Red", p0: -1.04, p1: -0.58, col: "#d92b24", coreCol: "#e6392e", glowCol: "#ff5447", op: 72 },
    { name: "Cadmium Orange Bleed", p0: -0.66, p1: -0.26, col: "#ee6e22", coreCol: "#f58426", glowCol: "#ffa03b", op: 66 },
    { name: "Lemon Yellow", p0: -0.34, p1: 0.06, col: "#f7de32", coreCol: "#ffea47", glowCol: "#fff478", op: 76 },
    { name: "Viridian", p0: -0.02, p1: 0.40, col: "#12996c", coreCol: "#17b07d", glowCol: "#3bd49e", op: 68 },
    { name: "Ultramarine", p0: 0.32, p1: 0.74, col: "#1d4ec7", coreCol: "#285ee0", glowCol: "#5789ff", op: 70 },
    { name: "Violet", p0: 0.64, p1: 1.05, col: "#5e26ad", coreCol: "#7233c7", glowCol: "#9e63f0", op: 65 }
  ];

  const sMin = -720;
  const sMax = 720;
  const segLen = 58; // Overlapping wet watercolour segments along the beam

  // PASS A: Soft Wet-in-Wet Base Bleed Pass (grouped by spectral color for p5.brush caching)
  for (let b = 0; b < spectralBands.length; b++) {
    let band = spectralBands[b];
    brush.fill(band.col, band.op);
    brush.fillBleed(0.32, "out");
    brush.fillTexture(0.58, 0.32);

    for (let sStart = sMin; sStart < sMax; sStart += segLen * 0.82) {
      let sEnd = Math.min(sMax, sStart + segLen);
      let poly = [];
      let avgLight = 0;
      let count = 0;

      // Left edge of spectral ribbon (bending over 3D heightfield!)
      for (let s = sStart; s <= sEnd; s += 8) {
        let jitterP = band.p0 + 0.08 * (noise(s * 0.025, b * 10) - 0.5);
        let pt = solvePrismPoint(s, jitterP);
        if (pt.x > 10 && pt.x < 1190 && pt.y > 10 && pt.y < 1190) {
          poly.push([pt.x, pt.y]);
          avgLight += pt.sc.light;
          count++;
        }
      }
      // Right edge of spectral ribbon
      for (let s = sEnd; s >= sStart; s -= 8) {
        let jitterP = band.p1 + 0.08 * (noise(s * 0.025 + 50, b * 10) - 0.5);
        let pt = solvePrismPoint(s, jitterP);
        if (pt.x > 10 && pt.x < 1190 && pt.y > 10 && pt.y < 1190) {
          poly.push([pt.x, pt.y]);
        }
      }

      if (poly.length >= 6 && (avgLight / Math.max(1, count)) > 0.25) {
        drawSafeShape(poly, 0.45, true);
      }
    }

    // Wet-in-wet cauliflower blooms & pooled pigment drops along ridge crests & rib furrows
    for (let s = sMin + 30; s < sMax - 30; s += 34) {
      let pMid = 0.5 * (band.p0 + band.p1) + random(-0.14, 0.14);
      let pt = solvePrismPoint(s, pMid);
      if (pt.x < 25 || pt.x > 1175 || pt.y < 25 || pt.y > 1175) continue;
      if (pt.sc.light > 0.42) {
        let r = random(10, 22) * (0.7 + 0.5 * pt.sc.light);
        brush.circle(pt.x + random(-3, 3), pt.y + random(-3, 3), r, 0.35);
      }
    }
  }

  // PASS B: Intense Luminous Pigment Core on Sunlit Ridges & Ribs
  for (let b = 0; b < spectralBands.length; b++) {
    let band = spectralBands[b];
    brush.fill(band.coreCol, Math.round(band.op * 0.88));
    brush.fillBleed(0.18, "in");
    brush.fillTexture(0.68, 0.44);

    let pInner0 = band.p0 + 0.18 * (band.p1 - band.p0);
    let pInner1 = band.p1 - 0.18 * (band.p1 - band.p0);

    for (let sStart = sMin + 15; sStart < sMax - 15; sStart += 42) {
      let sEnd = sStart + 38;
      let ptMid = solvePrismPoint(0.5 * (sStart + sEnd), 0.5 * (pInner0 + pInner1));
      if (ptMid.x < 20 || ptMid.x > 1180 || ptMid.y < 20 || ptMid.y > 1180) continue;

      // Emphasize luminous pigment saturation on sunlit fold crests and rib tops
      if (ptMid.sc.light + 0.2 * ptMid.sc.ridge < 0.48) continue;

      let poly = [];
      for (let s = sStart; s <= sEnd; s += 6) {
        let pt = solvePrismPoint(s, pInner0);
        poly.push([pt.x, pt.y]);
      }
      for (let s = sEnd; s >= sStart; s -= 6) {
        let pt = solvePrismPoint(s, pInner1);
        poly.push([pt.x, pt.y]);
      }
      drawSafeShape(poly, 0.4, true);
    }
  }
  brush.noFill();

  // PASS C: Soft Wet-in-Wet Diffusion Filaments Wicking Along Linen Threads & Fur
  for (let b = 0; b < spectralBands.length; b++) {
    let band = spectralBands[b];
    let pCenter = 0.5 * (band.p0 + band.p1);
    for (let s = sMin + 10; s < sMax - 10; s += 9) {
      let pSample = pCenter + random(-0.24, 0.24);
      let pt = solvePrismPoint(s, pSample);
      if (pt.x < 20 || pt.x > 1180 || pt.y < 20 || pt.y > 1180) continue;

      let sc = pt.sc;
      let dirX = sc.dogMask > 0.3 ? sc.furX : sc.linenX;
      let dirY = sc.dogMask > 0.3 ? sc.furY : sc.linenY;
      let bleedLen = random(12, 26);

      brush.set("prism_glow", band.col, random(0.75, 1.35));
      brush.line(
        pt.x - dirX * bleedLen * 0.5,
        pt.y - dirY * bleedLen * 0.5,
        pt.x + dirX * bleedLen * 0.5,
        pt.y + dirY * bleedLen * 0.5
      );
    }
  }
}

// ============================================================================
// LAYER 4: HYPERREALIST OVER-DETAILING (LINEN WEAVE, RIBS, FUR, HEAD & PAWS)
// ============================================================================

function renderLinenFineDetailing() {
  brush.noFill();
  brush.noHatch();

  // 1. Crisp white pencil ridge highlights & deep graphite fold crevices across the linen bed
  for (let f = 0; f < linenFolds.length; f++) {
    let fold = linenFolds[f];
    let tx = fold.p2[0] - fold.p0[0];
    let ty = fold.p2[1] - fold.p0[1];
    let len = Math.hypot(tx, ty) || 1;
    let nx = -ty / len;
    let ny = tx / len;

    // Crest highlight pass (3 tight parallel white pencil threads along the top of the ridge)
    for (let sub = -2; sub <= 2; sub++) {
      let off = sub * 2.5 - fold.asym * fold.w * 0.18;
      let crestPts = [];
      for (let s = 0; s <= 16; s++) {
        let t = s / 16;
        let mt = 1 - t;
        let bx = mt * mt * fold.p0[0] + 2 * mt * t * fold.p1[0] + t * t * fold.p2[0] + nx * off;
        let by = mt * mt * fold.p0[1] + 2 * mt * t * fold.p1[1] + t * t * fold.p2[1] + ny * off;
        if (bx < 15 || bx > 1185 || by < 15 || by > 1185) continue;
        let pr = evalPrismCoord(bx, by);
        if (pr.sc.dogMask > 0.15) {
          if (crestPts.length >= 3) {
            brush.set("white_chalk_pencil", "#f8f9fc", random(0.75, 1.15));
            drawSafeSpline(crestPts, 0.45);
          }
          crestPts = [];
          continue;
        }
        // Outside prism rainbow: pure white pencil; inside rainbow: handled by spectral highlights
        if (Math.abs(pr.p) > 1.08) {
          crestPts.push([bx + random(-0.8, 0.8), by + random(-0.8, 0.8), 0.5 + 0.5 * Math.sin(Math.PI * t)]);
        } else {
          if (crestPts.length >= 3) {
            brush.set("white_chalk_pencil", "#f8f9fc", random(0.75, 1.15));
            drawSafeSpline(crestPts, 0.45);
          }
          crestPts = [];
        }
      }
      if (crestPts.length >= 3) {
        brush.set("white_chalk_pencil", "#ffffff", random(0.75, 1.15));
        drawSafeSpline(crestPts, 0.45);
      }
    }

    // Shadow trough accent line along the dark base of the fold
    for (let side of [-0.82, 0.85]) {
      let off = side * fold.w;
      let troughPts = [];
      for (let s = 0; s <= 14; s++) {
        let t = s / 14;
        let mt = 1 - t;
        let bx = mt * mt * fold.p0[0] + 2 * mt * t * fold.p1[0] + t * t * fold.p2[0] + nx * off;
        let by = mt * mt * fold.p0[1] + 2 * mt * t * fold.p1[1] + t * t * fold.p2[1] + ny * off;
        if (bx < 15 || bx > 1185 || by < 15 || by > 1185) continue;
        let sc = sampleScene(bx, by);
        if (sc.dogMask > 0.15 || sc.light > 0.48) {
          if (troughPts.length >= 3) {
            brush.set("2B", "#3c4352", random(0.65, 0.95));
            drawSafeSpline(troughPts, 0.45);
          }
          troughPts = [];
          continue;
        }
        troughPts.push([bx, by, 0.6]);
      }
      if (troughPts.length >= 3) {
        brush.set("2B", "#3c4352", random(0.65, 0.95));
        drawSafeSpline(troughPts, 0.45);
      }
    }
  }

  // 2. Fine woven flax-linen micro-thread texture across the bed
  for (let i = 0; i < 650; i++) {
    let x = random(20, 1180);
    let y = random(20, 1180);
    let pr = evalPrismCoord(x, y);
    if (pr.sc.dogMask > 0.1) continue;

    // Warp and weft directions of the diagonal linen sheet
    let isWarp = random() < 0.5;
    let tx = isWarp ? pr.sc.linenX : -pr.sc.linenY;
    let ty = isWarp ? pr.sc.linenY : pr.sc.linenX;
    let len = random(10, 24);

    if (pr.sc.light > 0.66 && Math.abs(pr.p) > 1.05) {
      brush.set("cpencil", "#f2f5fa", random(0.45, 0.75));
      brush.line(x - tx * len * 0.5, y - ty * len * 0.5, x + tx * len * 0.5, y + ty * len * 0.5);
    } else if (pr.sc.light < 0.44) {
      brush.set("2H", "#586070", random(0.45, 0.75));
      brush.line(x - tx * len * 0.5, y - ty * len * 0.5, x + tx * len * 0.5, y + ty * len * 0.5);
    }
  }
}

function renderGreyhoundFineDetailing() {
  brush.noFill();
  brush.noHatch();

  // 1. Explicit Sculptural Rib Contours & Intercostal Furrows (9 ribs across the barrel chest)
  for (let ribIdx = 0; ribIdx < 9; ribIdx++) {
    let uBase = 0.25 + (ribIdx / 8.5) * 0.34;
    let ribCrestPts = [];
    let ribShadowPts = [];

    for (let wStep = -0.72; wStep <= 0.36; wStep += 0.08) {
      let uActual = uBase + 0.034 * (0.38 - wStep) + 0.018 * Math.pow(0.38 - wStep, 2);
      let sIdx = Math.min(spineSamples.length - 1, Math.max(0, Math.round(uActual * (spineSamples.length - 1))));
      let s = spineSamples[sIdx];
      let rOut = s.val[2], rIn = s.val[3];
      let dMid = 0.5 * (rOut - rIn);
      let wHalf = 0.5 * (rOut + rIn);
      let dLat = dMid + wStep * wHalf;

      let cx = s.val[0] + s.nx * dLat;
      let cy = s.val[1] + s.ny * dLat;
      ribCrestPts.push([cx - s.tx * 2.5, cy - s.ty * 2.5, 0.85]);
      ribShadowPts.push([cx + s.tx * 7.5, cy + s.ty * 7.5, 0.8]);
    }

    // Intercostal shadow furrow behind each rib
    brush.set("graphite_soft", "#2f3542", 0.85);
    drawSafeSpline(ribShadowPts, 0.5);
    brush.set("2B", "#262b36", 0.65);
    drawSafeSpline(ribShadowPts, 0.5);

    // Fine directional fur strokes crossing each rib crest
    for (let k = 0; k < ribCrestPts.length; k++) {
      let p = ribCrestPts[k];
      let pr = evalPrismCoord(p[0], p[1]);
      let fx = pr.sc.furX, fy = pr.sc.furY;
      if (Math.abs(pr.p) > 1.02) {
        // Outside rainbow: luminous silver-white pencil on rib crest
        brush.set("white_chalk_pencil", "#eef1f7", random(0.65, 0.95));
        brush.line(p[0] - fx * 6, p[1] - fy * 6, p[0] + fx * 6, p[1] + fy * 6);
      } else {
        // Inside rainbow: crisp graphite shadow on the intercostal side to keep the rib sharp under watercolor!
        let sx = ribShadowPts[k][0], sy = ribShadowPts[k][1];
        brush.set("graphite_detail", "#2e3442", 0.7);
        brush.line(sx - fx * 5, sy - fy * 5, sx + fx * 5, sy + fy * 5);
      }
    }
  }

  // 2. Dorsal Spine Vertebrae & Deep Flank Tuck-Up Definition
  for (let i = 18; i < spineSamples.length - 12; i += 3) {
    let s = spineSamples[i];
    let rOut = s.val[2], rIn = s.val[3];
    let dMid = 0.5 * (rOut - rIn);
    let wHalf = 0.5 * (rOut + rIn);
    let dSpine = dMid + 0.38 * wHalf;
    let sx = s.val[0] + s.nx * dSpine;
    let sy = s.val[1] + s.ny * dSpine;
    let pr = evalPrismCoord(sx, sy);

    if (Math.abs(pr.p) > 1.0) {
      brush.set("white_chalk_pencil", "#f0f3f8", random(0.6, 0.95));
      brush.line(sx - s.tx * 7, sy - s.ty * 7, sx + s.tx * 7, sy + s.ty * 7);
    }
    // Outer dorsal silhouette contour hair strokes
    let ox = s.val[0] + s.nx * (rOut - 2);
    let oy = s.val[1] + s.ny * (rOut - 2);
    brush.set("graphite_detail", "#252a34", 0.85);
    brush.line(ox - s.tx * 8, oy - s.ty * 8, ox + s.tx * 8, oy + s.ty * 8);
  }

  // 3. Dense Short Velvety Sighthound Fur Tracts Across Body, Neck, Thigh & Head
  for (let i = 0; i < 1450; i++) {
    let x = random(345, 835);
    let y = random(375, 825);
    let pr = evalPrismCoord(x, y);
    let sc = pr.sc;
    if (sc.dogMask < 0.45) continue;

    let fx = sc.furX, fy = sc.furY;
    let fLen = Math.hypot(fx, fy) || 1;
    fx /= fLen;
    fy /= fLen;

    let hLen = sc.partID === 2 ? random(4, 8) : random(6, 13);
    let val = sc.light * (0.55 + 0.45 * sc.albedo) + 0.16 * sc.ridge;

    if (val < 0.38) {
      brush.set("graphite_detail", "#242832", random(0.55, 0.9));
      brush.line(x - fx * hLen * 0.5, y - fy * hLen * 0.5, x + fx * hLen * 0.5, y + fy * hLen * 0.5);
    } else if (val < 0.54) {
      brush.set("HB", "#484f60", random(0.5, 0.8));
      brush.line(x - fx * hLen * 0.5, y - fy * hLen * 0.5, x + fx * hLen * 0.5, y + fy * hLen * 0.5);
    } else if (val > 0.65 && Math.abs(pr.p) > 0.98) {
      let col = val > 0.76 ? "#ffffff" : "#e2e6ef";
      brush.set("white_chalk_pencil", col, random(0.55, 0.9));
      brush.line(x - fx * hLen * 0.5, y - fy * hLen * 0.5, x + fx * hLen * 0.5, y + fy * hLen * 0.5);
    }
  }

  // 4. Anatomical Micro-Details: Sighthound Head, Closed Sleeping Eye, Rose Ears, Nose & Paws
  // A. Closed Sleeping Eye & Brow Arch at (424, 496)
  const eyePts = [[434, 486, 0.4], [426, 495, 1.0], [417, 503, 0.5]];
  brush.set("graphite_detail", "#181b22", 1.15);
  drawSafeSpline(eyePts, 0.4);
  // Delicate lower lid crease & sleeping eyelashes
  brush.set("graphite_detail", "#2b303c", 0.75);
  drawSafeSpline([[432, 489], [424, 498], [415, 505]], 0.4);
  // Highlighted supraorbital brow bone above the closed eye
  brush.set("white_chalk_pencil", "#f4f6fb", 0.95);
  drawSafeSpline([[440, 482], [430, 491], [420, 498]], 0.45);

  // B. Dark Rhinarium (Nose Tip) at (388, 580) with Nostril Slits & Wet Specular Catchlight
  brush.fill("#1d2028", 190);
  brush.fillBleed(0.05, "in");
  brush.fillTexture(0.4, 0.5);
  drawSafeShape([[398, 572], [395, 586], [382, 588], [378, 575], [388, 569]], 0.35, true);
  brush.noFill();

  // Nostril comma slits
  brush.set("graphite_detail", "#0f1117", 1.2);
  brush.line(393, 578, 389, 584);
  brush.line(384, 577, 381, 583);
  // Crisp white pencil wet catchlight on upper nasal pad & white muzzle bridge
  brush.set("white_chalk_pencil", "#ffffff", 1.05);
  drawSafeSpline([[406, 524], [397, 550], [390, 572]], 0.4);
  brush.line(391, 573, 385, 575);

  // Delicate fine white whiskers (vibrissae) curving from muzzle over the linen crease
  brush.set("cpencil", "#f0f3f8", 0.55);
  drawSafeSpline([[398, 562], [418, 572], [438, 580]], 0.5);
  drawSafeSpline([[395, 568], [414, 580], [432, 592]], 0.5);
  drawSafeSpline([[383, 564], [364, 572], [346, 582]], 0.5);

  // C. Rose Ears Cartilage Folds & Velvety Rim Shading
  brush.set("graphite_detail", "#20242e", 0.95);
  drawSafeSpline([[458, 444], [484, 426], [512, 412]], 0.45);
  drawSafeSpline([[464, 448], [488, 432], [518, 414]], 0.45);
  brush.set("white_chalk_pencil", "#e8ecf4", 0.8);
  drawSafeSpline([[456, 440], [480, 420], [506, 408]], 0.45);

  // D. Tucked Hare-Paws: Individual Knuckled Toes, Inter-digital Crevices & Curved Claws
  const pawCenters = [
    { x: 416, y: 608, ang: 162 }, // Right forepaw
    { x: 366, y: 598, ang: 152 }, // Left forepaw
    { x: 448, y: 632, ang: 120 }, // Right hindpaw
    { x: 454, y: 642, ang: 128 }  // Left hindpaw
  ];

  for (let p of pawCenters) {
    let rad = p.ang * Math.PI / 180;
    let tx = Math.cos(rad), ty = Math.sin(rad);
    let nx = -ty, ny = tx;
    for (let toe = -1.5; toe <= 1.5; toe += 1.0) {
      let bx = p.x + nx * toe * 5.2;
      let by = p.y + ny * toe * 5.2;
      // Dark inter-digital shadow furrow
      brush.set("graphite_detail", "#222630", 0.9);
      brush.line(bx - tx * 8, by - ty * 8, bx + tx * 7, by + ty * 7);
      // White pencil highlight on top of each knuckled toe
      let hx = bx + nx * 2.2;
      let hy = by + ny * 2.2;
      brush.set("white_chalk_pencil", "#f5f7fb", 0.85);
      brush.line(hx - tx * 6, hy - ty * 6, hx + tx * 5, hy + ty * 5);
      // Curved claw tip + tiny glint
      let cx = hx + tx * 6.5;
      let cy = hy + ty * 6.5;
      brush.set("graphite_detail", "#1c2029", 0.95);
      brush.line(cx, cy, cx + tx * 4.5, cy + ty * 4.5 + 1.5);
      brush.set("cpencil", "#ffffff", 0.55);
      brush.line(cx + 0.5, cy - 0.5, cx + tx * 3.0, cy + ty * 3.0);
    }
  }
}

// ============================================================================
// LAYER 5: CHROMATIC FUR & LINEN THREAD HIGHLIGHTS INSIDE THE PRISM RAINBOW
// ============================================================================

function renderPrismSpectralHighlights() {
  brush.noFill();
  brush.noHatch();

  // Where the narrow prism rainbow crosses linen ridges and the greyhound's ribs,
  // individual hairs and linen threads catch luminous chromatic highlights!
  const sMin = -700;
  const sMax = 700;

  for (let s = sMin; s <= sMax; s += 4.5) {
    for (let p = -0.96; p <= 0.96; p += 0.14) {
      let pt = solvePrismPoint(s + random(-2, 2), p + random(-0.04, 0.04));
      if (pt.x < 18 || pt.x > 1182 || pt.y < 18 || pt.y > 1182) continue;

      let sc = pt.sc;
      let lum = sc.light + 0.22 * sc.ridge;
      let dirX = sc.dogMask > 0.25 ? sc.furX : sc.linenX;
      let dirY = sc.dogMask > 0.25 ? sc.furY : sc.linenY;
      let len = sc.dogMask > 0.25 ? random(6, 12) : random(10, 20);

      // Determine luminous highlight color matching the local spectral band
      let hiCol = "#fff6a8";
      let midCol = "#f7de32";
      if (p < -0.58) {
        hiCol = "#ff9685"; midCol = "#e6392e"; // Cadmium Red
      } else if (p < -0.28) {
        hiCol = "#ffc278"; midCol = "#f58426"; // Cadmium Orange bleed
      } else if (p < 0.05) {
        hiCol = "#fff9b8"; midCol = "#ffea47"; // Lemon Yellow
      } else if (p < 0.38) {
        hiCol = "#9ef7d4"; midCol = "#17b07d"; // Viridian Green
      } else if (p < 0.70) {
        hiCol = "#a8c8ff"; midCol = "#285ee0"; // Ultramarine Blue
      } else {
        hiCol = "#dfb8ff"; midCol = "#7b3bd4"; // Violet
      }

      if (lum > 0.60) {
        // Sunlit ridge crest or rib top inside the rainbow: glowing chromatic pencil highlight
        brush.set("white_chalk_pencil", hiCol, random(0.65, 1.05));
        brush.line(
          pt.x - dirX * len * 0.5,
          pt.y - dirY * len * 0.5,
          pt.x + dirX * len * 0.5,
          pt.y + dirY * len * 0.5
        );
        if (lum > 0.74 && random() < 0.45) {
          brush.set("cpencil", "#ffffff", random(0.45, 0.75));
          brush.line(
            pt.x - dirX * len * 0.35,
            pt.y - dirY * len * 0.35,
            pt.x + dirX * len * 0.35,
            pt.y + dirY * len * 0.35
          );
        }
      } else if (lum < 0.40) {
        // Deep fold crevice or intercostal rib shadow inside the rainbow: subtle dark graphite & deep pigment
        brush.set("graphite_detail", "#323846", random(0.5, 0.8));
        brush.line(
          pt.x - dirX * len * 0.45,
          pt.y - dirY * len * 0.45,
          pt.x + dirX * len * 0.45,
          pt.y + dirY * len * 0.45
        );
      } else if (random() < 0.45) {
        // Midtone chromatic fiber/fur texture
        brush.set("cpencil", midCol, random(0.55, 0.85));
        brush.line(
          pt.x - dirX * len * 0.45,
          pt.y - dirY * len * 0.45,
          pt.x + dirX * len * 0.45,
          pt.y + dirY * len * 0.45
        );
      }
    }
  }
}

