// ============================================================================
// PALETTE & LIGHTING CONSTANTS
// High-contrast tonal charcoal, hard graphite, white chalk on warm mid-grey ground
// ============================================================================
const PAL = {
  ground: "#877f73",      // Warm mid-grey sandstone paper ground
  tones: [
    "#0a0908", // 0: Abyssal compressed charcoal black (deepest niche apexes)
    "#13110f", // 1: Core cast shadow black
    "#1d1a17", // 2: Deep blended charcoal mass
    "#292521", // 3: Dark shadow facet
    "#37322d", // 4: Charcoal shadow wall
    "#47413a", // 5: Reflected warm sandstone bounce in shadow
    "#585047", // 6: Dark half-tone plaster
    "#6a6157", // 7: Shaded paper value
    "#7c7367", // 8: Mid-grey paper shadow
    "#8d8477", // 9: Base warm mid-grey ground
    "#9f9586", // 10: Grazing afternoon light on sandstone plaster
    "#b3a898", // 11: Lit plaster plane
    "#c7bcab", // 12: Strong raking afternoon light
    "#dbd0bf", // 13: Chalk-warmed sunlit facet
    "#eee6d8", // 14: Bright white chalk-pencil bevel
    "#ffffff"  // 15: Pure crisp white chalk catchlight on chipped edges
  ],
  graphiteDark: "#1c1917",
  graphiteMid: "#3b3630",
  graphiteLight: "#595249",
  chalkCream: "#efe8da",
  chalkPure: "#ffffff"
};

// Center of geometry & slightly offset worm's-eye camera vanishing point
const CX = 600;
const CY = 600;
const VX = 588;
const VY = 612;

// Raking afternoon sunlight vector (pointing TOWARD the light source in upper-left)
// Low raking angle (~17 deg elevation) sweeping across the vault from WNW
const LIGHT = (() => {
  let lx = -0.85, ly = -0.43, lz = -0.29;
  let m = Math.hypot(lx, ly, lz);
  return { x: lx / m, y: ly / m, z: lz / m };
})();

// ============================================================================
// 3D GEOMETRY & PROJECTION HELPERS
// ============================================================================

// Convert polar (angle in deg, screen radius r, local vertical height dz)
// into both 3D world space (for exact surface normals) and 2D projected canvas coords.
// In a worm's-eye view, dropping DOWN in 3D (dz < 0, closer to viewer) pushes the
// projected point radially OUTWARD from the vanishing point (VX, VY).
function makeVertex(angDeg, r, dz = 0) {
  let rad = angDeg * Math.PI / 180;
  let wx = CX + r * Math.cos(rad);
  let wy = CY + r * Math.sin(rad);

  // Global dome curvature Z + local stalactite/niche relief dz
  let normR = Math.min(1.25, r / 820);
  let domeZ = 560 * Math.pow(Math.max(0, 1 - normR * normR * 0.72), 0.85);
  let wz = domeZ + dz;

  // Perspective foreshortening ray from vanishing point (VX, VY)
  let dx = wx - VX;
  let dy = wy - VY;
  let distV = Math.hypot(dx, dy);
  let perspShift = -dz * (0.14 + 0.74 * (distV / 820));
  let scale = distV > 0.001 ? (distV + perspShift) / distV : 1;

  return {
    x: VX + dx * scale,
    y: VY + dy * scale,
    wx: wx,
    wy: wy,
    wz: wz,
    r: r,
    ang: angDeg,
    dz: dz
  };
}

// Compute unit 3D surface normal of triangle (p1, p2, p3) oriented generally downward (-Z)
function calcNormal(p1, p2, p3) {
  let ux = p2.wx - p1.wx, uy = p2.wy - p1.wy, uz = p2.wz - p1.wz;
  let vx = p3.wx - p1.wx, vy = p3.wy - p1.wy, vz = p3.wz - p1.wz;
  let nx = uy * vz - uz * vy;
  let ny = uz * vx - ux * vz;
  let nz = ux * vy - uy * vx;
  let m = Math.hypot(nx, ny, nz);
  if (m < 1e-6) return { x: 0, y: 0, z: -1 };
  nx /= m; ny /= m; nz /= m;
  // Ensure normal points generally toward the viewer on the floor (-Z hemisphere)
  if (nz > 0.25) {
    nx = -nx; ny = -ny; nz = -nz;
  }
  return { x: nx, y: ny, z: nz };
}

// Map 3D normal + cavity depth (0 = exposed tip, 1 = deep niche apex) + cast shadow
// to a continuous tone index in [0, 15]
function computeToneIndex(norm, cavityDepth, inCastShadow, macroPos) {
  // Direct raking light dot product
  let ndotl = norm.x * LIGHT.x + norm.y * LIGHT.y + norm.z * LIGHT.z;

  // Macro dome position modulation (raking light sweeps from upper-left to lower-right)
  let rx = (macroPos.x - CX) / 700;
  let ry = (macroPos.y - CY) / 700;
  // Upper-left recesses are shielded by the outer vault rim; lower-right faces the raking sun
  let macroGrazing = (rx * (-LIGHT.x) + ry * (-LIGHT.y)) * 0.22;

  // Reflected warm sandstone bounce light from opposite cell walls
  let bounce = Math.max(0, -ndotl * 0.35) * (1 - cavityDepth * 0.75);

  let direct = Math.max(0, ndotl + macroGrazing);
  if (inCastShadow) {
    direct *= 0.08;
  }

  // Combine base mid-grey value with direct raking light, cavity occlusion, and shadow
  let val = 6.2
    + direct * 9.6
    + bounce * 2.2
    - Math.pow(cavityDepth, 0.85) * 6.8
    - (inCastShadow ? 2.6 : 0);

  return Math.max(0, Math.min(15, val));
}

function getToneHex(toneIdx) {
  let idx = Math.max(0, Math.min(15, Math.round(toneIdx)));
  return PAL.tones[idx];
}

// Check if a set of 2D points intersects the visible 1200x1200 canvas (with margin)
function isVisibleOnCanvas(pts, margin = 55) {
  let minX = 1e9, maxX = -1e9, minY = 1e9, maxY = -1e9;
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    if (p.x < minX) minX = p.x;
    if (p.x > maxX) maxX = p.x;
    if (p.y < minY) minY = p.y;
    if (p.y > maxY) maxY = p.y;
  }
  return !(maxX < -margin || minX > 1200 + margin || maxY < -margin || minY > 1200 + margin);
}

// Safe polygon area check & fast wash
function washFacet(pts, col, opacity = 215) {
  if (!pts || pts.length < 3 || !isVisibleOnCanvas(pts)) return null;
  let area = 0;
  let clean = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    if (isNaN(p.x) || isNaN(p.y)) return null;
    clean.push([p.x, p.y]);
    let q = pts[(i + 1) % pts.length];
    area += p.x * q.y - q.x * p.y;
  }
  if (Math.abs(area) * 0.5 < 0.8) return null;
  let poly = new brush.Polygon(clean);
  poly.wash(col, opacity);
  return poly;
}

function lerpPt(a, b, t) {
  return {
    x: a.x + (b.x - a.x) * t,
    y: a.y + (b.y - a.y) * t,
    wx: a.wx !== undefined ? a.wx + (b.wx - a.wx) * t : a.x + (b.x - a.x) * t,
    wy: a.wy !== undefined ? a.wy + (b.wy - a.wy) * t : a.y + (b.y - a.y) * t,
    wz: a.wz !== undefined ? a.wz + (b.wz - a.wz) * t : 0
  };
}

// ============================================================================
// HYPERREALISTIC DRAWING PRIMITIVES (CHALK CHIPS, STUMP MASS, LATTICE, CRACKS)
// ============================================================================

// Render a soft blended charcoal or chalk tonal mass across a quad/triangle facet
function blendFacetMass(p1, p2, p3, p4, toneIdx, isApexShadow = false) {
  if (!isVisibleOnCanvas([p1, p2, p3, p4 || p3])) return;

  let c1 = lerpPt(p1, p2, 0.5);
  let c2 = p4 ? lerpPt(p3, p4, 0.5) : p3;
  let span = Math.hypot(c2.x - c1.x, c2.y - c1.y);
  if (span < 3) return;

  // Soft tortillon stump pass for blended charcoal mass
  if (toneIdx < 7.2 || isApexShadow) {
    let darkCol = getToneHex(Math.max(0, toneIdx - 1.2));
    brush.set("stump", darkCol, map(constrain(span, 6, 90), 6, 90, 0.35, 1.15));
    let steps = isApexShadow ? 3 : 2;
    for (let s = 0; s < steps; s++) {
      let t = (s + 0.5) / steps;
      let a = lerpPt(p1, p4 || p3, t * 0.75);
      let b = lerpPt(p2, p3, t * 0.75);
      if (Math.hypot(b.x - a.x, b.y - a.y) > 2.5) {
        brush.line(a.x, a.y, b.x, b.y);
      }
    }
  } else if (toneIdx > 10.8) {
    // Soft chalk-pencil mass on sunlit plaster faces
    let lightCol = getToneHex(Math.min(14, toneIdx + 0.6));
    brush.set("chalk_soft", lightCol, map(constrain(span, 6, 90), 6, 90, 0.3, 0.9));
    let a = lerpPt(p1, p4 || p3, 0.45);
    let b = lerpPt(p2, p3, 0.45);
    if (Math.hypot(b.x - a.x, b.y - a.y) > 2.5) {
      brush.line(a.x, a.y, b.x, b.y);
    }
  }

  // Directional charcoal hatching on mid-dark shadow facets
  if (toneIdx <= 6.0 && span > 11) {
    let hatchCol = getToneHex(Math.max(0, toneIdx - 1.8));
    brush.set("charcoal_velvet", hatchCol, map(constrain(span, 10, 80), 10, 80, 0.28, 0.65));
    let nLines = Math.min(5, Math.max(2, Math.floor(span / 9)));
    for (let i = 1; i <= nLines; i++) {
      let u = i / (nLines + 1);
      let sA = lerpPt(p1, p2, u);
      let sB = p4 ? lerpPt(p4, p3, u) : lerpPt(p1, p3, u);
      if (Math.hypot(sB.x - sA.x, sB.y - sA.y) > 3) {
        brush.line(sA.x, sA.y, sB.x, sB.y);
      }
    }
  }
}

// Render an architectural plaster edge with raking white chalk-pencil highlights
// and realistic chipped plaster nicks (dark graphite pit + bright white chip bevel)
function drawChippedEdge(p1, p2, edgeLight, weightScale = 1.0, forceChalk = false) {
  if (!isVisibleOnCanvas([p1, p2])) return;
  let len = Math.hypot(p2.x - p1.x, p2.y - p1.y);
  if (len < 1.8) return;

  // Determine how strongly the edge catches the raking afternoon light
  let dx = (p2.x - p1.x) / len;
  let dy = (p2.y - p1.y) / len;
  // Edge normal in screen plane pointing toward upper-left light
  let nx = -dy, ny = dx;
  let align = Math.abs(nx * LIGHT.x + ny * LIGHT.y);
  let litScore = edgeLight + align * 0.35;

  if (litScore > 0.38 || forceChalk) {
    // 1. Soft warm chalk halo slightly beneath the sharp arris
    if (len > 8 && litScore > 0.55) {
      brush.set("chalk_soft", PAL.chalkCream, 0.48 * weightScale);
      brush.line(p1.x, p1.y, p2.x, p2.y);
    }

    // 2. Crisp segmented white chalk line interrupted by tiny weathered plaster chips
    let numChips = len > 28 ? 2 : (len > 13 ? 1 : 0);
    if (numChips === 0) {
      let col = litScore > 0.72 ? PAL.chalkPure : PAL.chalkCream;
      brush.set("chalk_crisp", col, (litScore > 0.72 ? 0.85 : 0.6) * weightScale);
      brush.line(p1.x, p1.y, p2.x, p2.y);
    } else {
      let chipPositions = [];
      for (let c = 0; c < numChips; c++) {
        chipPositions.push(constrain(0.22 + c * 0.45 + random(-0.1, 0.1), 0.15, 0.85));
      }
      chipPositions.sort((a, b) => a - b);

      let prevT = 0;
      let col = litScore > 0.68 ? PAL.chalkPure : PAL.chalkCream;
      for (let c = 0; c <= chipPositions.length; c++) {
        let nextT = c < chipPositions.length ? chipPositions[c] - 0.04 : 1.0;
        if (nextT > prevT + 0.03) {
          let a = lerpPt(p1, p2, prevT);
          let b = lerpPt(p1, p2, nextT);
          brush.set("chalk_crisp", col, (0.68 + 0.28 * random()) * weightScale);
          brush.line(a.x, a.y, b.x, b.y);
        }
        if (c < chipPositions.length) {
          let ct = chipPositions[c];
          let cp = lerpPt(p1, p2, ct);
          let chipSize = Math.min(3.8, len * 0.08) * weightScale;
          // Tiny dark graphite shadow pit inside the chipped plaster notch
          brush.set("graphite_2H", PAL.tones[1], 0.95 * weightScale);
          brush.line(
            cp.x - dx * chipSize * 0.6,
            cp.y - dy * chipSize * 0.6,
            cp.x + nx * chipSize * 0.75,
            cp.y + ny * chipSize * 0.75
          );
          // Blazing pure white chalk catchlight on the sun-facing lip of the chip
          brush.set("chalk_crisp", PAL.chalkPure, 1.05 * weightScale);
          brush.line(
            cp.x + nx * chipSize * 0.75,
            cp.y + ny * chipSize * 0.75,
            cp.x + dx * chipSize * 0.9,
            cp.y + dy * chipSize * 0.9
          );
          prevT = ct + 0.045;
        }
      }
    }
  } else {
    // Shaded architectural crease picked out in hard/medium graphite
    let gCol = litScore < 0.15 ? PAL. tones[1] : PAL.graphiteMid;
    brush.set("graphite_HB", gCol, 0.65 * weightScale);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }
}

// Carve intricate Moorish Sebka diamond lattice & blind pointed arches into vertical shaft quad
// Quad vertices: topL, topR (inner/upper edge), botR, botL (outer/lower edge)
function drawCarvedLatticeOnShaft(topL, topR, botR, botL, isSunlit, tierIdx) {
  if (!isVisibleOnCanvas([topL, topR, botR, botL])) return;
  let w = Math.hypot(topR.x - topL.x, topR.y - topL.y);
  let h = Math.hypot(botL.x - topL.x, botL.y - topL.y);
  if (w < 7 || h < 6) return;

  let bilerp = (u, v) => {
    let tPt = lerpPt(topL, topR, u);
    let bPt = lerpPt(botL, botR, u);
    return lerpPt(tPt, bPt, v);
  };

  let incCol = isSunlit ? PAL.graphiteMid : PAL.tones[1];
  let wScale = map(constrain(w, 7, 55), 7, 55, 0.55, 1.05);

  // Outer recessed panel frame incision
  let f00 = bilerp(0.12, 0.14);
  let f10 = bilerp(0.88, 0.14);
  let f11 = bilerp(0.88, 0.86);
  let f01 = bilerp(0.12, 0.86);

  brush.set("graphite_2H", incCol, 0.72 * wScale);
  brush.line(f00.x, f00.y, f10.x, f10.y);
  brush.line(f10.x, f10.y, f11.x, f11.y);
  brush.line(f01.x, f01.y, f00.x, f00.y);

  // Sun-struck lower bevel of recessed frame
  if (isSunlit) {
    brush.set("chalk_crisp", PAL.chalkCream, 0.52 * wScale);
    brush.line(f01.x, f01.y, f11.x, f11.y);
  }

  // Sebka diamond interlacing lattice inside the recessed panel
  let cols = w > 24 ? 3 : 2;
  let rows = h > 20 ? 3 : 2;
  brush.set("graphite_2H", incCol, 0.65 * wScale);

  for (let r = 0; r < rows; r++) {
    let v0 = 0.16 + (r / rows) * 0.68;
    let vMid = 0.16 + ((r + 0.5) / rows) * 0.68;
    let v1 = 0.16 + ((r + 1) / rows) * 0.68;

    for (let c = 0; c < cols; c++) {
      let u0 = 0.14 + (c / cols) * 0.72;
      let uMid = 0.14 + ((c + 0.5) / cols) * 0.72;
      let u1 = 0.14 + ((c + 1) / cols) * 0.72;

      let pTop = bilerp(uMid, v0);
      let pRight = bilerp(u1, vMid);
      let pBot = bilerp(uMid, v1);
      let pLeft = bilerp(u0, vMid);

      brush.set("graphite_2H", incCol, 0.65 * wScale);
      brush.line(pTop.x, pTop.y, pRight.x, pRight.y);
      brush.line(pRight.x, pRight.y, pBot.x, pBot.y);
      brush.line(pBot.x, pBot.y, pLeft.x, pLeft.y);
      brush.line(pLeft.x, pLeft.y, pTop.x, pTop.y);

      // Tiny white chalk catchlight on the sun-facing lower-right facet of each incised diamond
      if (isSunlit && w > 13) {
        brush.set("chalk_crisp", PAL.chalkCream, 0.45 * wScale);
        brush.line(pLeft.x, pLeft.y, pBot.x, pBot.y);
      }
    }
  }

  // Occasional hairline crack wandering across larger plaster panels
  if (w > 18 && random() < 0.38) {
    drawHairlineCrack(bilerp(random(0.2, 0.5), 0.1), bilerp(random(0.5, 0.85), 0.9), isSunlit);
  }
}

// Pick out delicate, jagged hairline structural cracks in hard 2H graphite
function drawHairlineCrack(pStart, pEnd, isSunlit = false) {
  if (!isVisibleOnCanvas([pStart, pEnd])) return;
  let len = Math.hypot(pEnd.x - pStart.x, pEnd.y - pStart.y);
  if (len < 5) return;

  let steps = Math.min(9, Math.max(3, Math.floor(len / 6)));
  let dx = (pEnd.x - pStart.x) / len;
  let dy = (pEnd.y - pStart.y) / len;
  let nx = -dy, ny = dx;

  let pts = [pStart];
  for (let i = 1; i < steps; i++) {
    let t = i / steps;
    let jitter = (noise(pStart.x * 0.05 + i * 1.7, pStart.y * 0.05) - 0.5) * Math.min(7, len * 0.16);
    pts.push({
      x: lerp(pStart.x, pEnd.x, t) + nx * jitter,
      y: lerp(pStart.y, pEnd.y, t) + ny * jitter
    });
  }
  pts.push(pEnd);

  for (let i = 0; i < pts.length - 1; i++) {
    let w = map(i, 0, pts.length - 1, 0.85, 0.42);
    brush.set("graphite_2H", PAL.tones[1], w);
    brush.line(pts[i].x, pts[i].y, pts[i + 1].x, pts[i + 1].y);

    if (isSunlit && i % 2 === 0) {
      brush.set("chalk_crisp", PAL.chalkCream, 0.38);
      brush.line(pts[i].x + 0.9, pts[i].y + 0.9, pts[i + 1].x + 0.9, pts[i + 1].y + 0.9);
    }
  }

  // Tiny secondary fork crack
  if (len > 18 && pts.length >= 4 && random() < 0.65) {
    let branchIdx = Math.floor(pts.length * 0.5);
    let bp = pts[branchIdx];
    let side = random() < 0.5 ? 1 : -1;
    let bEnd = {
      x: bp.x + (dx * 0.7 + nx * 0.55 * side) * len * 0.32,
      y: bp.y + (dy * 0.7 + ny * 0.55 * side) * len * 0.32
    };
    brush.set("graphite_2H", PAL.graphiteDark, 0.48);
    brush.line(bp.x, bp.y, bEnd.x, bEnd.y);
  }
}

// ============================================================================
// 3D STALACTITE PENDANT (MOCÁRABE / PIÑA) RENDERER
// Renders the vertical hanging prism shaft + octagonal star soffit cap facing viewer
// ============================================================================
function renderStalactitePendant(angDeg, rBase, dzTop, dzDrop, capRadius, tierScale) {
  let centerTop = makeVertex(angDeg, rBase, dzTop);
  let centerTip = makeVertex(angDeg, rBase, dzTop - dzDrop);
  if (!isVisibleOnCanvas([centerTop, centerTip], 60)) return;

  // 1. Vertical prismatic column facets hanging from dzTop down to dzTop - dzDrop
  // The side of the prism facing the viewer (inward toward VX, VY) and side cheeks are visible
  let numSides = 8;
  let topRing = [];
  let botRing = [];
  for (let k = 0; k < numSides; k++) {
    let a = angDeg + k * 45;
    let rad = a * Math.PI / 180;
    let ox = Math.cos(rad) * capRadius;
    let oy = Math.sin(rad) * capRadius;

    let pT = {
      x: centerTop.x + ox * 0.92,
      y: centerTop.y + oy * 0.92,
      wx: centerTop.wx + ox,
      wy: centerTop.wy + oy,
      wz: centerTop.wz
    };
    let pB = {
      x: centerTip.x + ox * 1.05,
      y: centerTip.y + oy * 1.05,
      wx: centerTip.wx + ox,
      wy: centerTip.wy + oy,
      wz: centerTip.wz
    };
    topRing.push(pT);
    botRing.push(pB);
  }

  // Draw the visible vertical prism faces (those facing generally toward the camera ray)
  for (let k = 0; k < numSides; k++) {
    let kNext = (k + 1) % numSides;
    let pT1 = topRing[k], pT2 = topRing[kNext];
    let pB2 = botRing[kNext], pB1 = botRing[k];

    // Check screen-space winding (visible face of extruded prism)
    let cross = (pT2.x - pT1.x) * (pB1.y - pT1.y) - (pT2.y - pT1.y) * (pB1.x - pT1.x);
    if (cross > 0.5) {
      let midAng = (angDeg + k * 45 + 22.5) * Math.PI / 180;
      let norm = { x: Math.cos(midAng), y: Math.sin(midAng), z: -0.15 };
      let tIdx = computeToneIndex(norm, 0.15, false, centerTip);
      washFacet([pT1, pT2, pB2, pB1], getToneHex(tIdx), 230);
      blendFacetMass(pT1, pT2, pB2, pB1, tIdx, false);

      // Vertical arris between prism facets
      let edgeLit = Math.max(0, norm.x * LIGHT.x + norm.y * LIGHT.y);
      drawChippedEdge(pT1, pB1, edgeLit, 0.65 * tierScale, edgeLit > 0.55);
    }
  }

  // 2. Downward-facing 8-pointed Star Soffit Cap at the bottom tip of the stalactite
  let starOuter = [];
  let starInner = [];
  for (let k = 0; k < 16; k++) {
    let a = (angDeg + k * 22.5) * Math.PI / 180;
    let isPoint = k % 2 === 0;
    let radOuter = isPoint ? capRadius * 1.12 : capRadius * 0.72;
    let radInner = isPoint ? capRadius * 0.52 : capRadius * 0.34;
    starOuter.push({
      x: centerTip.x + Math.cos(a) * radOuter,
      y: centerTip.y + Math.sin(a) * radOuter,
      wx: centerTip.wx + Math.cos(a) * radOuter,
      wy: centerTip.wy + Math.sin(a) * radOuter,
      wz: centerTip.wz
    });
    starInner.push({
      x: centerTip.x + Math.cos(a) * radInner,
      y: centerTip.y + Math.sin(a) * radInner,
      wx: centerTip.wx + Math.cos(a) * radInner,
      wy: centerTip.wy + Math.sin(a) * radInner,
      wz: centerTip.wz + capRadius * 0.65
    });
  }

  // Flat plaster star rim facing straight down toward viewer (normal ~ (0, 0, -1))
  let rimTone = computeToneIndex({ x: LIGHT.x * 0.35, y: LIGHT.y * 0.35, z: -0.94 }, 0.05, false, centerTip);
  washFacet(starOuter, getToneHex(Math.min(14, rimTone + 1.5)), 240);

  // Recessed miniature hollow cup inside the star soffit
  for (let k = 0; k < 16; k++) {
    let kNext = (k + 1) % 16;
    let s1 = starInner[k], s2 = starInner[kNext];
    let a = (angDeg + (k + 0.5) * 22.5) * Math.PI / 180;
    // Inner cup wall faces inward toward centerTip
    let cupNorm = { x: -Math.cos(a) * 0.8, y: -Math.sin(a) * 0.8, z: -0.6 };
    let cupTone = computeToneIndex(cupNorm, 0.55, cupNorm.x * LIGHT.x + cupNorm.y * LIGHT.y < 0, centerTip);
    washFacet([s1, s2, centerTip], getToneHex(cupTone), 235);
  }

  // Outline the 8-pointed star soffit rim with chipped white chalk on sun side, graphite on shadow side
  for (let k = 0; k < 16; k++) {
    let kNext = (k + 1) % 16;
    let p1 = starOuter[k], p2 = starOuter[kNext];
    let a = (angDeg + (k + 0.5) * 22.5) * Math.PI / 180;
    let rimNormalLit = Math.cos(a) * LIGHT.x + Math.sin(a) * LIGHT.y;
    drawChippedEdge(p1, p2, 0.45 + rimNormalLit * 0.55, 0.72 * tierScale, rimNormalLit > 0.1);
  }

  // Central carved pendant boss (botón) catching a pinpoint white chalk highlight
  if (capRadius > 4.5) {
    brush.set("graphite_2H", PAL.tones[1], 0.75 * tierScale);
    brush.circle(centerTip.x, centerTip.y, Math.max(1.5, capRadius * 0.18), 0.15);
    brush.set("chalk_crisp", PAL.chalkPure, 0.95 * tierScale);
    brush.line(
      centerTip.x + LIGHT.x * capRadius * 0.16,
      centerTip.y + LIGHT.y * capRadius * 0.16,
      centerTip.x - LIGHT.x * capRadius * 0.08,
      centerTip.y - LIGHT.y * capRadius * 0.08
    );
  }
}

// ============================================================================
// SINGLE 3D MUQARNAS HONEYCOMB CELL RENDERER
// Builds:
//   1. V-angled vertical stalactite shafts with diagonal cast shadows & incised Sebka lattice
//   2. Downward-facing plaster arch soffit rim with chipped white chalk edges
//   3. Deeply recessed multi-fluted concave hood (bovedilla) with blended charcoal apex mass
//   4. Corbelled outer scalloped arch rim
// ============================================================================
function renderMuqarnasCell(cfg) {
  let {
    angL, angM, angR,
    rInPeak, rInShoulder,
    rOutPendant, rOutPeak,
    dzTop, dzShaftDrop, dzApexLift,
    soffitWidth, numFlutes,
    tierIdx, tierScale
  } = cfg;

  // Quick visibility bounding test
  let testPts = [
    makeVertex(angM, rInPeak, dzTop),
    makeVertex(angL, rOutPendant, dzTop - dzShaftDrop),
    makeVertex(angR, rOutPendant, dzTop - dzShaftDrop),
    makeVertex(angM, rOutPeak, dzTop)
  ];
  if (!isVisibleOnCanvas(testPts, 75)) return;

  // --------------------------------------------------------------------------
  // ZONE 1: V-ANGLED VERTICAL STALACTITE SHAFTS (Dropping from dzTop to dzBot)
  // --------------------------------------------------------------------------
  let dzBot = dzTop - dzShaftDrop;

  let vTopL = makeVertex(angL, rInShoulder, dzTop);
  let vTopM = makeVertex(angM, rInPeak, dzTop);
  let vTopR = makeVertex(angR, rInShoulder, dzTop);

  let vBotL = makeVertex(angL, rInShoulder, dzBot);
  let vBotM = makeVertex(angM, rInPeak, dzBot);
  let vBotR = makeVertex(angR, rInShoulder, dzBot);

  // Left vertical shaft wall (from angL to angM) & Right vertical shaft wall (from angM to angR)
  // Remember: looking up from inside the dome, these walls face INWARD toward the center
  let normShaftL = calcNormal(vTopL, vTopM, vBotM);
  let normShaftR = calcNormal(vTopM, vTopR, vBotR);

  let dotL = normShaftL.x * LIGHT.x + normShaftL.y * LIGHT.y + normShaftL.z * LIGHT.z;
  let dotR = normShaftR.x * LIGHT.x + normShaftR.y * LIGHT.y + normShaftR.z * LIGHT.z;

  // Left Shaft Wall
  let toneShaftL = computeToneIndex(normShaftL, 0.25, dotL < -0.05, vBotL);
  washFacet([vTopL, vTopM, vBotM, vBotL], getToneHex(toneShaftL), 232);

  // If Left Shaft faces the raking light, slice the diagonal cast shadow of the upper arch across it!
  if (dotL > 0.05) {
    let shadowFrac = constrain(0.32 + (1 - dotL) * 0.35, 0.22, 0.68);
    let sL = lerpPt(vTopL, vBotL, shadowFrac);
    let sM = lerpPt(vTopM, vBotM, shadowFrac * 0.65);
    let shadowTone = computeToneIndex(normShaftL, 0.48, true, vTopL);
    washFacet([vTopL, vTopM, sM, sL], getToneHex(shadowTone), 220);
    blendFacetMass(vTopL, vTopM, sM, sL, shadowTone, true);
    blendFacetMass(sL, sM, vBotM, vBotL, toneShaftL, false);
    // Soft charcoal edge along cast shadow terminator
    brush.set("charcoal_velvet", getToneHex(Math.max(0, shadowTone - 1)), 0.45 * tierScale);
    brush.line(sL.x, sL.y, sM.x, sM.y);
  } else {
    blendFacetMass(vTopL, vTopM, vBotM, vBotL, toneShaftL, false);
  }
  drawCarvedLatticeOnShaft(vTopL, vTopM, vBotM, vBotL, dotL > 0.08, tierIdx);

  // Right Shaft Wall
  let toneShaftR = computeToneIndex(normShaftR, 0.25, dotR < -0.05, vBotR);
  washFacet([vTopM, vTopR, vBotR, vBotM], getToneHex(toneShaftR), 232);

  if (dotR > 0.05) {
    let shadowFrac = constrain(0.32 + (1 - dotR) * 0.35, 0.22, 0.68);
    let sM = lerpPt(vTopM, vBotM, shadowFrac * 0.65);
    let sR = lerpPt(vTopR, vBotR, shadowFrac);
    let shadowTone = computeToneIndex(normShaftR, 0.48, true, vTopR);
    washFacet([vTopM, vTopR, sR, sM], getToneHex(shadowTone), 220);
    blendFacetMass(vTopM, vTopR, sR, sM, shadowTone, true);
    blendFacetMass(sM, sR, vBotR, vBotM, toneShaftR, false);
    brush.set("charcoal_velvet", getToneHex(Math.max(0, shadowTone - 1)), 0.45 * tierScale);
    brush.line(sM.x, sM.y, sR.x, sR.y);
  } else {
    blendFacetMass(vTopM, vTopR, vBotR, vBotM, toneShaftR, false);
  }
  drawCarvedLatticeOnShaft(vTopM, vTopR, vBotR, vBotM, dotR > 0.08, tierIdx);

  // Central vertical spine crease of V-shaft
  drawChippedEdge(vTopM, vBotM, Math.max(dotL, dotR) + 0.2, 0.85 * tierScale, Math.max(dotL, dotR) > 0.28);

  // --------------------------------------------------------------------------
  // ZONE 2: DOWNWARD-FACING PLASTER ARCH SOFFIT RIM (Thickness of the arch)
  // --------------------------------------------------------------------------
  let vLipL = makeVertex(angL, rInShoulder + soffitWidth, dzBot);
  let vLipM = makeVertex(angM, rInPeak + soffitWidth, dzBot);
  let vLipR = makeVertex(angR, rInShoulder + soffitWidth, dzBot);

  let soffitNormL = { x: normShaftL.x * 0.35, y: normShaftL.y * 0.35, z: -0.93 };
  let soffitNormR = { x: normShaftR.x * 0.35, y: normShaftR.y * 0.35, z: -0.93 };

  let soffitToneL = computeToneIndex(soffitNormL, 0.08, false, vLipL);
  let soffitToneR = computeToneIndex(soffitNormR, 0.08, false, vLipR);

  washFacet([vBotL, vBotM, vLipM, vLipL], getToneHex(Math.min(14, soffitToneL + 1.2)), 240);
  washFacet([vBotM, vBotR, vLipR, vLipM], getToneHex(Math.min(14, soffitToneR + 1.2)), 240);

  // Crisp white chalk-pencil highlights on the sun-catching soffit arrises
  drawChippedEdge(vBotL, vBotM, dotL + 0.42, 0.92 * tierScale, dotL > -0.1);
  drawChippedEdge(vBotM, vBotR, dotR + 0.42, 0.92 * tierScale, dotR > -0.1);
  drawChippedEdge(vLipL, vLipM, dotL + 0.3, 0.72 * tierScale, dotL > 0.15);
  drawChippedEdge(vLipM, vLipR, dotR + 0.3, 0.72 * tierScale, dotR > 0.15);

  // --------------------------------------------------------------------------
  // ZONE 3: DEEPLY RECESSED CONCAVE FLUTED HOOD (BOVEDILLA / STALACTITE VAULT)
  // --------------------------------------------------------------------------
  // The apex of the cell hood sits tucked up inside the honeycomb cavity (high dz)
  let rApex = lerp(rInPeak + soffitWidth, rOutPeak, 0.42);
  let dzApex = dzTop + dzApexLift;
  let vApex = makeVertex(angM, rApex, dzApex);

  // Build the scalloped outer arch perimeter fanning from Left Pendant -> Outer Peak -> Right Pendant
  let halfFlutes = Math.max(2, Math.floor(numFlutes / 2));
  let perimeterPts = [];
  let perimeterRimPts = [];

  for (let i = 0; i <= halfFlutes * 2; i++) {
    let u = i / (halfFlutes * 2); // 0 = angL, 0.5 = angM, 1 = angR
    let a = lerp(angL, angR, u);
    // Arch profile in radius and height (low at side pendants, arched peak at center angM)
    let archFactor = 1 - Math.pow(Math.abs(u - 0.5) * 2, 1.35);
    // Scalloped flute modulation along the arch
    let scallop = Math.sin(u * halfFlutes * 2 * Math.PI) * soffitWidth * 0.25;
    let rPt = lerp(rOutPendant, rOutPeak, archFactor) + scallop;
    let dzPt = lerp(dzBot - dzShaftDrop * 0.25, dzTop + dzApexLift * 0.18, archFactor);

    perimeterPts.push(makeVertex(a, rPt, dzPt));
    perimeterRimPts.push(makeVertex(a, rPt + soffitWidth * 0.78, dzPt - soffitWidth * 0.22));
  }

  // Render each concave fluted triangle/strip inside the hood in 3 depth rings
  // (Ring 0 = deepest charcoal apex cavity, Ring 1 = middle vault transition, Ring 2 = outer arch mouth)
  for (let i = 0; i < perimeterPts.length - 1; i++) {
    let pOut1 = perimeterPts[i];
    let pOut2 = perimeterPts[i + 1];

    // Intermediate ring vertices along the concave curve from vApex to outer arch
    let m1A = lerpPt(vApex, pOut1, 0.38);
    let m2A = lerpPt(vApex, pOut2, 0.38);
    let m1B = lerpPt(vApex, pOut1, 0.72);
    let m2B = lerpPt(vApex, pOut2, 0.72);

    // Adjust 3D Z of intermediate points to reflect concave dome curvature inside the hood
    m1A.wz = lerp(vApex.wz, pOut1.wz, 0.22);
    m2A.wz = lerp(vApex.wz, pOut2.wz, 0.22);
    m1B.wz = lerp(vApex.wz, pOut1.wz, 0.58);
    m2B.wz = lerp(vApex.wz, pOut2.wz, 0.58);

    let normFlute = calcNormal(vApex, pOut2, pOut1);
    let fluteDot = normFlute.x * LIGHT.x + normFlute.y * LIGHT.y + normFlute.z * LIGHT.z;
    // Is this flute occluded by the overhanging lip on the sun side?
    let uMid = (i + 0.5) / (perimeterPts.length - 1);
    let fluteCastShadow = fluteDot < 0.02;

    // 1. Deep Apex Triangle (tucked high in the cavity -> soft blended dark charcoal mass)
    let toneApex = computeToneIndex(normFlute, 0.92, true, vApex);
    washFacet([vApex, m1A, m2A], getToneHex(toneApex), 242);
    blendFacetMass(vApex, m1A, m2A, null, toneApex, true);

    // 2. Mid-Cavity Quad (blended charcoal transition from deep cavity to outer wall)
    let toneMid = computeToneIndex(normFlute, 0.58, fluteCastShadow, m1A);
    washFacet([m1A, m2A, m2B, m1B], getToneHex(toneMid), 235);
    blendFacetMass(m1A, m2A, m2B, m1B, toneMid, toneMid < 4.5);

    // 3. Outer Hood Mouth Quad (catches raking light or warm reflected bounce)
    let toneOuter = computeToneIndex(normFlute, 0.22, fluteCastShadow && fluteDot < -0.15, m1B);
    washFacet([m1B, m2B, pOut2, pOut1], getToneHex(toneOuter), 230);
    blendFacetMass(m1B, m2B, pOut2, pOut1, toneOuter, false);

    // Delicate graphite flute rib separating adjacent concave scallops
    if (i > 0) {
      let ribLit = fluteDot * 0.6 + 0.25;
      brush.set("graphite_2H", ribLit > 0.35 ? PAL.graphiteMid : PAL.tones[1], 0.58 * tierScale);
      brush.line(vApex.x, vApex.y, m1B.x, m1B.y);
      drawChippedEdge(m1B, pOut1, ribLit, 0.58 * tierScale, ribLit > 0.52);
    }

    // Outer scalloped arch soffit thickness
    let rOut1 = perimeterRimPts[i];
    let rOut2 = perimeterRimPts[i + 1];
    let rimNorm = { x: normFlute.x * 0.4, y: normFlute.y * 0.4, z: -0.91 };
    let rimTone = computeToneIndex(rimNorm, 0.1, false, pOut1);
    washFacet([pOut1, pOut2, rOut2, rOut1], getToneHex(Math.min(14, rimTone + 1.0)), 238);
    drawChippedEdge(pOut1, pOut2, fluteDot + 0.38, 0.78 * tierScale, fluteDot > -0.05);
  }

  // Side cheek facets connecting inner soffit lip (vLipL, vLipR) to outer pendants
  let pLeftPend = perimeterPts[0];
  let pRightPend = perimeterPts[perimeterPts.length - 1];

  let normCheekL = calcNormal(vLipL, vApex, pLeftPend);
  let toneCheekL = computeToneIndex(normCheekL, 0.45, normCheekL.x * LIGHT.x + normCheekL.y * LIGHT.y < 0, vLipL);
  washFacet([vLipL, vLipM, vApex, pLeftPend], getToneHex(toneCheekL), 232);
  blendFacetMass(vLipL, vLipM, vApex, pLeftPend, toneCheekL, toneCheekL < 4);
  drawChippedEdge(vLipL, pLeftPend, (normCheekL.x * LIGHT.x + normCheekL.y * LIGHT.y) + 0.35, 0.75 * tierScale, false);

  let normCheekR = calcNormal(vApex, vLipR, pRightPend);
  let toneCheekR = computeToneIndex(normCheekR, 0.45, normCheekR.x * LIGHT.x + normCheekR.y * LIGHT.y < 0, vLipR);
  washFacet([vLipM, vLipR, pRightPend, vApex], getToneHex(toneCheekR), 232);
  blendFacetMass(vLipM, vLipR, pRightPend, vApex, toneCheekR, toneCheekR < 4);
  drawChippedEdge(vLipR, pRightPend, (normCheekR.x * LIGHT.x + normCheekR.y * LIGHT.y) + 0.35, 0.75 * tierScale, false);

  // Central groin ridge from inner arch peak vLipM up into the dark apex vApex
  drawChippedEdge(vLipM, vApex, Math.max(dotL, dotR) + 0.25, 0.75 * tierScale, Math.max(dotL, dotR) > 0.35);

  // Use dry-media brush.mass() on larger deep cavity apexes for authentic hand-built charcoal density
  if (tierScale > 0.78 && isVisibleOnCanvas([vApex, perimeterPts[0], perimeterPts[perimeterPts.length - 1]], 10)) {
    let mA = lerpPt(vApex, perimeterPts[0], 0.35);
    let mB = lerpPt(vApex, perimeterPts[ Math.floor(perimeterPts.length / 2) ], 0.38);
    let mC = lerpPt(vApex, perimeterPts[perimeterPts.length - 1], 0.35);
    let areaCheck = Math.abs((mA.x - vApex.x) * (mB.y - vApex.y) - (mB.x - vApex.x) * (mA.y - vApex.y));
    if (areaCheck > 18) {
      brush.noStroke();
      brush.noFill();
      brush.noWash();
      brush.mass("charcoal_velvet", PAL.tones[0], {
        precision: 0.65,
        strength: 0.7,
        gradient: 0.45,
        outline: false
      });
      let pMass = new brush.Polygon([
        [vApex.x, vApex.y],
        [mA.x, mA.y],
        [mB.x, mB.y],
        [mC.x, mC.y]
      ]);
      pMass.mass();
      brush.noMass();
    }
  }

  // Occasional structural hairline crack radiating from the arch apex
  if (tierScale > 0.65 && random() < 0.28) {
    let midPerim = perimeterPts[Math.floor(perimeterPts.length / 2)];
    drawHairlineCrack(lerpPt(vApex, midPerim, 0.25), lerpPt(vApex, midPerim, 0.92), Math.max(dotL, dotR) > 0.2);
  }
}

// ============================================================================
// CENTRAL 16-POINTED STAR CUPOLA (SHAMSA) & INTERLOCKING LACERÍA STRAPWORK
// ============================================================================
function renderCentralStarCupola(rMax) {
  let center = makeVertex(0, 0, 75);

  // 1. Deep recessed octagonal/16-fold coffer background at zenith
  let outerPts = [];
  for (let i = 0; i < 32; i++) {
    let a = i * 11.25;
    let r = (i % 2 === 0) ? rMax : rMax * 0.74;
    outerPts.push(makeVertex(a, r, 45));
  }
  washFacet(outerPts, PAL.tones[2], 245);

  // 2. 16 radiating scalloped shell flutes (Gallones) around the central rosette
  for (let i = 0; i < 16; i++) {
    let aL = i * 22.5 - 11.25;
    let aM = i * 22.5;
    let aR = i * 22.5 + 11.25;

    let pInL = makeVertex(aL, rMax * 0.28, 68);
    let pInM = makeVertex(aM, rMax * 0.22, 74);
    let pInR = makeVertex(aR, rMax * 0.28, 68);

    let pOutL = makeVertex(aL, rMax * 0.74, 38);
    let pOutM = makeVertex(aM, rMax * 0.98, 52);
    let pOutR = makeVertex(aR, rMax * 0.74, 38);

    // Left and right halves of each concave shell flute
    let normL = calcNormal(pInM, pOutM, pOutL);
    let normR = calcNormal(pInM, pOutR, pOutM);

    let tL = computeToneIndex(normL, 0.35, normL.x * LIGHT.x + normL.y * LIGHT.y < -0.05, pOutL);
    let tR = computeToneIndex(normR, 0.35, normR.x * LIGHT.x + normR.y * LIGHT.y < -0.05, pOutR);

    washFacet([pInL, pInM, pOutM, pOutL], getToneHex(tL), 238);
    blendFacetMass(pInL, pInM, pOutM, pOutL, tL, tL < 5);

    washFacet([pInM, pInR, pOutR, pOutM], getToneHex(tR), 238);
    blendFacetMass(pInM, pInR, pOutR, pOutM, tR, tR < 5);

    // Raised plaster strapwork rib (Lacería) with double parallel edges and white chalk highlight
    let ribW = 3.2;
    let pOutL_in = makeVertex(aL + 2.2, rMax * 0.74, 32);
    let pOutM_in = makeVertex(aM, rMax * 0.98 - ribW * 1.4, 36);
    let pOutR_in = makeVertex(aR - 2.2, rMax * 0.74, 32);

    let dotRibL = normL.x * LIGHT.x + normL.y * LIGHT.y;
    let dotRibR = normR.x * LIGHT.x + normR.y * LIGHT.y;

    washFacet([pOutL, pOutM, pOutM_in, pOutL_in], getToneHex(dotRibL > 0 ? 13 : 8), 245);
    washFacet([pOutM, pOutR, pOutR_in, pOutM_in], getToneHex(dotRibR > 0 ? 13 : 8), 245);

    drawChippedEdge(pOutL, pOutM, dotRibL + 0.5, 0.85, dotRibL > -0.1);
    drawChippedEdge(pOutM, pOutR, dotRibR + 0.5, 0.85, dotRibR > -0.1);
    drawChippedEdge(pOutL_in, pOutM_in, dotRibL + 0.35, 0.65, dotRibL > 0.15);
    drawChippedEdge(pOutM_in, pOutR_in, dotRibR + 0.35, 0.65, dotRibR > 0.15);
    drawChippedEdge(pInM, pOutM_in, Math.max(dotRibL, dotRibR) + 0.3, 0.7, false);
  }

  // 3. Innermost 16-pointed Star Knot (Sino) at the exact zenith
  for (let i = 0; i < 16; i++) {
    let a1 = i * 22.5;
    let aMid = i * 22.5 + 11.25;
    let a2 = (i + 1) * 22.5;

    let vTip1 = makeVertex(a1, rMax * 0.34, 58);
    let vVal = makeVertex(aMid, rMax * 0.18, 66);
    let vTip2 = makeVertex(a2, rMax * 0.34, 58);
    let vIn1 = makeVertex(a1, rMax * 0.11, 72);
    let vIn2 = makeVertex(a2, rMax * 0.11, 72);

    let normPetal = calcNormal(center, vTip1, vVal);
    let tPetal = computeToneIndex(normPetal, 0.25, false, vTip1);
    washFacet([vIn1, vTip1, vVal, vIn2], getToneHex(tPetal), 242);

    let petalLit = normPetal.x * LIGHT.x + normPetal.y * LIGHT.y;
    drawChippedEdge(vTip1, vVal, petalLit + 0.55, 0.75, petalLit > -0.1);
    drawChippedEdge(vVal, vTip2, petalLit + 0.45, 0.75, petalLit > 0);
  }

  // Central carved lotus boss at (0,0)
  brush.set("charcoal_velvet", PAL.tones[0], 0.7);
  brush.circle(center.x, center.y, rMax * 0.1, 0.18);
  brush.set("chalk_crisp", PAL.chalkPure, 0.95);
  brush.arc(center.x, center.y, rMax * 0.085, 165, 315);
}

