  brush.noStroke();
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.55, 0.28);

  // Dark charcoal macro-shadow washes in the upper-left vault recess & deep corners
  let darkZones = [
    [160, 160, 420, 380],
    [1020, 170, 380, 360],
    [170, 1020, 380, 380],
    [1030, 1030, 400, 400],
