    brush.set("graphite_2H", col, 0.32);
    brush.line(0, y, 1200, y + random(-3, 3));
  }

  for (let i = 0; i < 28; i++) {
    let col = i < 16 ? PAL.tones[3] : PAL.tones[13];
    brush.set("plaster_dust", col, random(0.6, 1.3));
    let x1 = random(60, 1140), y1 = random(60, 1140);
    brush.line(x1, y1, x1 + random(-140, 140), y1 + random(-140, 140));
  }

  // Faint geometric architect's construction compass lines & radial axes (2H graphite)
  brush.set("graphite_2H", PAL.tones[7], 0.42);
  for (let i = 0; i < 16; i++) {
    let a = i * 22.5 * Math.PI / 180;
    brush.line(
      CX + Math.cos(a) * 45,
      CY + Math.sin(a) * 45,
      CX + Math.cos(a) * 880,
      CY + Math.sin(a) * 880
    );
  }
}

