// MAIN VAULT ASSEMBLY & DRAW LOOP
// ============================================================================
function draw() {
  translate(-width / 2, -height / 2);

  // 1. Render warm mid-grey ground, atmospheric under-washes, and construction grid
  renderPaperGround();

  // 2. Define the 13 Cascading Muqarnas Tiers (from r = 72 out to r = 980 to fill corners at 849)
  // Each tier specifies its angular division count N, radial span, 8-fold star modulation,
  // 4-fold corner squinch expansion, vertical shaft drop, cavity apex lift, and stalactite pendants.
  const tiers = [
    { n: 16, rIn: 70,  rOut: 118, star8: 0.06, corner4: 0.00, drop: 26, lift: 22, soffit: 5.5, flutes: 4, pendR: 6.5,  scale: 0.72 },
    { n: 16, rIn: 110, rOut: 168, star8: 0.09, corner4: 0.00, drop: 32, lift: 28, soffit: 6.5, flutes: 4, pendR: 8.0,  scale: 0.78 },
    { n: 32, rIn: 156, rOut: 222, star8: 0.11, corner4: 0.01, drop: 36, lift: 32, soffit: 6.8, flutes: 4, pendR: 7.5,  scale: 0.82 },
    { n: 32, rIn: 208, rOut: 284, star8: 0.13, corner4: 0.02, drop: 42, lift: 36, soffit: 7.5, flutes: 6, pendR: 9.0,  scale: 0.88 },
    { n: 32, rIn: 266, rOut: 354, star8: 0.14, corner4: 0.04, drop: 48, lift: 42, soffit: 8.5, flutes: 6, pendR: 10.5, scale: 0.94 },
    { n: 32, rIn: 332, rOut: 432, star8: 0.13, corner4: 0.06, drop: 54, lift: 48, soffit: 9.5, flutes: 6, pendR: 11.8, scale: 1.00 },
    { n: 48, rIn: 406, rOut: 516, star8: 0.11, corner4: 0.09, drop: 58, lift: 52, soffit: 9.2, flutes: 6, pendR: 11.2, scale: 1.04 },
    { n: 48, rIn: 486, rOut: 608, star8: 0.09, corner4: 0.12, drop: 64, lift: 56, soffit: 10.2, flutes: 6, pendR: 12.5, scale: 1.08 },
    { n: 48, rIn: 572, rOut: 706, star8: 0.08, corner4: 0.15, drop: 70, lift: 62, soffit: 11.2, flutes: 6, pendR: 13.8, scale: 1.12 },
    { n: 64, rIn: 666, rOut: 812, star8: 0.06, corner4: 0.18, drop: 76, lift: 66, soffit: 11.5, flutes: 6, pendR: 14.2, scale: 1.15 },
    { n: 64, rIn: 768, rOut: 925, star8: 0.05, corner4: 0.21, drop: 82, lift: 72, soffit: 12.2, flutes: 6, pendR: 15.0, scale: 1.18 },
    { n: 64, rIn: 878, rOut: 1050, star8: 0.04, corner4: 0.24, drop: 88, lift: 76, soffit: 13.0, flutes: 6, pendR: 16.0, scale: 1.20 }
  ];

  // Radial modulation helper: combines 8-pointed star geometry with 4-corner squinch expansion
  let modRadius = (baseR, angDeg, star8, corner4) => {
    let rad = angDeg * Math.PI / 180;
    // 8-pointed star peaks at 0, 45, 90...; 4-corner squinches expand along diagonals (45, 135, 225, 315)
    let m8 = Math.cos(8 * rad) * star8;
    let m4 = -Math.cos(4 * rad) * corner4;
    return baseR * (1 + m8 + m4);
  };

  // 3. Render Central 16-Pointed Star Cupola at the zenith (highest Z)
  renderCentralStarCupola(74);

  // 4. Render each cascading tier from innermost (highest elevation) to outermost (lowest elevation)
  // Within each tier, we first draw all recessed cells/hoods and vertical shafts,
  // and then draw the hanging stalactite pendants (mocárabes) which hang down below the cell junctions.
  for (let tIdx = 0; tIdx < tiers.length; tIdx++) {
    let T = tiers[tIdx];
    let stepDeg = 360 / T.n;
    // Alternate half-step phase shift between tiers so cells interlock in true honeycomb topology
    let phaseShift = (tIdx % 2 === 1) ? stepDeg * 0.5 : 0;

    // Step 4A: Render all Muqarnas Honeycomb Cells in this tier
    for (let i = 0; i < T.n; i++) {
      let angL = i * stepDeg + phaseShift;
      let angM = (i + 0.5) * stepDeg + phaseShift;
      let angR = (i + 1) * stepDeg + phaseShift;

      let rInShoulderL = modRadius(T.rIn * 1.06, angL, T.star8, T.corner4);
      let rInPeakM     = modRadius(T.rIn * 0.94, angM, T.star8, T.corner4);
      let rOutPend     = modRadius(T.rOut * 0.95, angL, T.star8, T.corner4);
      let rOutPeakM    = modRadius(T.rOut * 1.06, angM, T.star8, T.corner4);

      // Modulate vertical relief based on 8-fold star ribs so primary star axes hang deeper
      let starRelief = 1 + 0.22 * Math.cos(8 * angM * Math.PI / 180);

      renderMuqarnasCell({
        angL: angL,
        angM: angM,
        angR: angR,
        rInPeak: rInPeakM,
        rInShoulder: rInShoulderL,
        rOutPendant: rOutPend,
        rOutPeak: rOutPeakM,
        dzTop: 18 * starRelief,
        dzShaftDrop: T.drop * starRelief,
        dzApexLift: T.lift,
        soffitWidth: T.soffit,
        numFlutes: T.flutes,
        tierIdx: tIdx,
        tierScale: T.scale
      });
    }

    // Step 4B: Render the hanging Stalactite Pendants (Mocárabes / Piñas) at the junctions of this tier
    for (let i = 0; i < T.n; i++) {
      let angP = i * stepDeg + phaseShift;
      let rPend = modRadius(T.rOut * 0.95, angP, T.star8, T.corner4);
      let starRelief = 1 + 0.25 * Math.cos(8 * angP * Math.PI / 180);

      // Major stalactite pendants at even junctions, smaller corbel pendants at odd junctions
      let isMajor = i % 2 === 0;
      let pRadius = isMajor ? T.pendR * 1.12 : T.pendR * 0.82;
      let pDrop   = isMajor ? T.drop * 0.95 * starRelief : T.drop * 0.68 * starRelief;

      renderStalactitePendant(
        angP,
        rPend,
        -T.drop * 0.35,
        pDrop,
        pRadius,
        T.scale
      );
    }
  }

  // 5. Final Atmospheric & Surface Realism Pass:
  // Fine plaster dust in raking light beams + crisp catchlights on the most prominent star ribs
  for (let i = 0; i < 22; i++) {
    let a = random(360) * Math.PI / 180;
    let r = random(85, 780);
    let px = CX + Math.cos(a) * r;
    let py = CY + Math.sin(a) * r;
    if (px > 20 && px < 1180 && py > 20 && py < 1180) {
      let isSunSide = (px - CX) * (-LIGHT.x) + (py - CY) * (-LIGHT.y) > 0;
      brush.set("plaster_dust", isSunSide ? PAL.chalkCream : PAL.tones[1], random(0.45, 0.95));
      brush.line(px, py, px + LIGHT.x * 45, py + LIGHT.y * 45);
    }
  }

  noLoop();
}

