// ============================================================================
// GEOMETRY & BRUSH HELPERS
// ============================================================================

function safeLine(x1, y1, x2, y2) {
  if (dist(x1, y1, x2, y2) < 0.4) {
    x2 = x1 + 0.5;
    y2 = y1 + 0.2;
  }
  brush.line(x1, y1, x2, y2);
}

function tracePoly(pts, curvature = 0, closed = true) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

function fillPoly(pts, col, opacity, bleed = 0.06, tex = 0.45, border = 0.25, curvature = 0) {
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  tracePoly(pts, curvature, true);
  brush.noFill();
}

function washPoly(pts, col, opacity, curvature = 0) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, opacity);
  tracePoly(pts, curvature, true);
  brush.noWash();
}

function strokePoly(pts, bName, col, weight, curvature = 0, closed = true) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, weight);
  tracePoly(pts, curvature, closed);
  brush.noStroke();
}

function hatchPoly(pts, bName, col, weight, distVal, angleVal, opts, curvature = 0) {
  brush.noStroke();
  brush.noFill();
  brush.noWash();
  brush.hatchStyle(bName, col, weight);
  brush.hatch(distVal, angleVal, opts);
  tracePoly(pts, curvature, true);
  brush.noHatch();
}

// ============================================================================
// 1. HYPERREALISTIC CORKBOARD TEXTURE (1200 x 1200, NO MARGINS)
// ============================================================================

function drawCorkboard() {
  // Base warm honey-brown wash covering edge-to-edge
  washPoly([[0, 0], [1200, 0], [1200, 1200], [0, 1200]], "#b9824b", 255);

  // Subtle macro tonal variations in raw sienna, golden ochre, and warm umber
  const patches = [
    { x: 220, y: 240, r: 390, col: "#cf9960", op: 55 },
    { x: 920, y: 260, r: 420, col: "#9d622e", op: 50 },
    { x: 600, y: 600, r: 480, col: "#c78e54", op: 45 },
    { x: 260, y: 920, r: 430, col: "#965b28", op: 55 },
    { x: 960, y: 940, r: 440, col: "#854c1d", op: 60 },
    { x: 80, y: 600, r: 310, col: "#8c5222", op: 50 },
    { x: 1120, y: 580, r: 320, col: "#7d4518", op: 55 },
    { x: 580, y: 110, r: 330, col: "#a46934", op: 45 },
    { x: 620, y: 1120, r: 350, col: "#7a4317", op: 60 }
  ];

  for (let p of patches) {
    let pts = [];
    for (let a = 0; a < 360; a += 30) {
      let rad = p.r * (0.75 + 0.4 * noise(p.x * 0.01 + cos(a), p.y * 0.01 + sin(a)));
      pts.push([p.x + cos(a) * rad, p.y + sin(a) * rad]);
    }
    fillPoly(pts, p.col, p.op, 0.35, 0.8, 0.3, 0.3);
  }

  // Diagonal coloured-pencil base grain across the entire board
  hatchPoly(
    [[0, 0], [1200, 0], [1200, 1200], [0, 1200]],
    "cpencil", "#9c622e", 0.75, 7.5, 32, { rand: 0.18 }
  );
  hatchPoly(
    [[0, 0], [1200, 0], [1200, 1200], [0, 1200]],
    "cpencil", "#cfa06a", 0.65, 9.0, -52, { rand: 0.22 }
  );

  // Layer 1: Thousands of honey-gold, raw sienna, and buff cork granules via custom brush
  const granuleCols = [
    { col: "#8d5222", w: 1.15, count: 145 },
    { col: "#a76b37", w: 1.1, count: 155 },
    { col: "#cb945b", w: 1.05, count: 165 },
    { col: "#dca972", w: 0.95, count: 150 },
    { col: "#ebc08d", w: 0.82, count: 120 },
    { col: "#6e3b14", w: 0.9, count: 130 }
  ];

  for (let g of granuleCols) {
    brush.set("cork_granule", g.col, g.w);
    for (let i = 0; i < g.count; i++) {
      let x1 = random(-20, 1220);
      let y1 = random(-20, 1220);
      let len = random(35, 110);
      let ang = random(360);
      safeLine(x1, y1, x1 + cos(ang) * len, y1 + sin(ang) * len);
    }
  }

  // Layer 2: Thousands of recessed umber pores and inter-granular crevices
  const poreCols = [
    { col: "#542a0e", w: 0.95, count: 150 },
    { col: "#381a07", w: 0.82, count: 145 },
    { col: "#210e03", w: 0.68, count: 115 }
  ];

  for (let p of poreCols) {
    brush.set("cork_pore", p.col, p.w);
    for (let i = 0; i < p.count; i++) {
      let x1 = random(-10, 1210);
      let y1 = random(-10, 1210);
      let len = random(24, 75);
      let ang = random(360);
      safeLine(x1, y1, x1 + cos(ang) * len, y1 + sin(ang) * len);
    }
  }

  // Layer 3: Individual Trompe-l'œil cork cells, lenticels, and coloured-pencil stipple
  // Light comes from upper-left: indented pores have a dark core and a bright lower-right rim;
  // raised cork granules have a bright upper-left edge and warm sienna shadow on lower-right.
  let cellData = [];
  for (let i = 0; i < 950; i++) {
    cellData.push({
      x: random(4, 1196),
      y: random(4, 1196),
      len: random(2.2, 7.5),
      ang: random(-40, 50),
      type: i % 3
    });
  }

  // Batch 3A: Dark umber pore cores
  brush.set("cpencil", "#2b1305", 0.72);
  for (let c of cellData) {
    let dx = cos(c.ang) * c.len;
    let dy = sin(c.ang) * c.len;
    safeLine(c.x, c.y, c.x + dx, c.y + dy);
    if (c.type === 0) {
      safeLine(c.x + 0.8, c.y + 0.9, c.x + dx * 0.75 + 0.8, c.y + dy * 0.75 + 0.9);
    }
  }

  // Batch 3B: Rich burnt umber secondary crevices
  brush.set("cpencil", "#5c3012", 0.85);
  for (let i = 0; i < cellData.length; i += 2) {
    let c = cellData[i];
    let ang2 = c.ang + 65;
    safeLine(c.x - 1.5, c.y - 1.0, c.x + cos(ang2) * c.len * 1.1, c.y + sin(ang2) * c.len * 1.1);
  }

  // Batch 3C: Honey-buff rim highlights catching upper-left raking light on the far lip of each pore
  brush.set("cpencil", "#f0c999", 0.65);
  for (let c of cellData) {
    let dx = cos(c.ang) * c.len * 0.85;
    let dy = sin(c.ang) * c.len * 0.85;
    safeLine(c.x + 1.4, c.y + 1.6, c.x + dx + 1.4, c.y + dy + 1.6);
  }

  // Batch 3D: Fine spray of raw sienna & charcoal micro-grain for velvety depth
  brush.set("spray", "#4a240b", 0.55);
  for (let i = 0; i < 36; i++) {
    let sx = random(40, 1160);
    let sy = random(40, 1160);
    safeLine(sx, sy, sx + random(-90, 90), sy + random(-90, 90));
  }
  brush.set("spray", "#e6b883", 0.45);
  for (let i = 0; i < 28; i++) {
    let sx = random(40, 1160);
    let sy = random(40, 1160);
    safeLine(sx, sy, sx + random(-80, 80), sy + random(-80, 80));
  }
  brush.noStroke();
}

function drawOldPinholes() {
  // Lived-in corkboard detail: old empty pinholes where past notes were pinned
  const holes = [
    [118, 140], [568, 224], [612, 515], [134, 622],
    [555, 810], [1082, 745], [520, 1085], [1055, 1110]
  ];
  for (let [hx, hy] of holes) {
    // Bruised sienna crater around the old pinhole
    brush.set("cpencil", "#693814", 0.9);
    brush.circle(hx, hy, 4.2, 0.35);
    // Raised pale cork crumb on lower-right rim
    brush.set("cpencil", "#f2cca0", 0.8);
    safeLine(hx + 1.8, hy + 1.8, hx + 4.5, hy + 3.2);
    safeLine(hx + 0.8, hy + 2.8, hx + 2.6, hy + 4.0);
    // Deep pitch-umber needle hole center
    brush.set("rotring", "#120702", 1.35);
    brush.circle(hx, hy, 1.4, 0.2);
    safeLine(hx - 0.8, hy - 0.8, hx + 0.8, hy + 0.8);
  }

  // One tiny forgotten torn paper corner still wedged into a staple scar at (576, 502)
  push();
  translate(576, 502);
