function drawTextString(str, x, y, charW, charH, spacing, bName, col, weight, jitter = 0) {
  brush.set(bName, col, weight);
  let cx = x;
  let up = str.toUpperCase();
  for (let i = 0; i < up.length; i++) {
    let ch = up[i];
    if (ch === ' ') {
      cx += (charW + spacing) * 0.75;
      continue;
    }
    let paths = GLYPHS[ch];
    if (paths) {
      let ox = jitter > 0 ? random(-jitter, jitter) : 0;
      let oy = jitter > 0 ? random(-jitter, jitter) : 0;
      for (let p of paths) {
        for (let k = 0; k < p.length - 1; k++) {
          let x1 = cx + ox + p[k][0] * charW;
          let y1 = y + oy + p[k][1] * charH;
          let x2 = cx + ox + p[k + 1][0] * charW;
          let y2 = y + oy + p[k + 1][1] * charH;
          safeLine(x1, y1, x2, y2);
        }
      }
    }
    cx += charW + spacing;
  }
  brush.noStroke();
}

