function drawTakeawayMenu(cx, cy, ang) {
  push();
  translate(cx, cy);
  rotate(ang);

  // Menu dimensions: width 356 (-178..178), top -242, bottom jaggedly torn from y=185 to y=242
  const tearBottom = [
    [178, 196], [152, 206], [128, 194], [104, 215], [76, 208],
    [48, 229], [18, 218], [-12, 238], [-44, 224], [-75, 242],
    [-108, 226], [-136, 235], [-162, 216], [-178, 224]
  ];

  const menuPts = [
    [-178, -242], [0, -240], [178, -242],
    [180, -78], [176, 82],
    ...tearBottom,
    [-176, 82], [-180, -78]
  ];

  // White fibrous inner-pulp deckle layer extending 4-7px below the tear line
  const decklePts = [
    [-178, 180], [178, 180],
    [178, 201], [152, 212], [128, 200], [104, 222], [76, 214],
    [48, 236], [18, 224], [-12, 245], [-44, 230], [-75, 248],
    [-108, 232], [-136, 241], [-162, 222], [-178, 230]
