  // Cast shadow (tight at top pin, deeper under tri-fold ridges and lifted bottom tear)
  let shadowPts = [[-172, -236], [186, -235], [192, -72], [190, 92]];
  for (let i = 0; i < tearBottom.length; i++) {
    shadowPts.push([tearBottom[i][0] + 18, tearBottom[i][1] + 22]);
  }
  shadowPts.push([-166, 94], [-172, -72]);

  washPoly(shadowPts, "#301606", 70, 0.08);
  let shadowCore = shadowPts.map(p => [p[0] - 5, p[1] - 5]);
  fillPoly(shadowCore, "#1b0b02", 125, 0.14, 0.55, 0.25, 0.06);
  hatchPoly(shadowCore, "cpencil", "#140802", 0.65, 5.0, 42, { rand: 0.12 }, 0.05);

  // Exposed white inner paper pulp along the torn bottom edge
  washPoly(decklePts, "#faf5eb", 240, 0.04);
  // Hundreds of microscopic torn paper fibers protruding from the deckle edge
  brush.set("paper_fiber", "#fffdf9", 0.85);
  for (let i = 0; i < tearBottom.length - 1; i++) {
    let p1 = tearBottom[i];
