    for (let t = 0; t <= 1; t += 0.12) {
      let tx = lerp(p1[0], p2[0], t);
      let ty = lerp(p1[1], p2[1], t);
      safeLine(tx, ty - 2, tx + random(-3, 3), ty + random(4, 9));
