  // Aged newsprint takeaway paper stock (#ebdcc3 warming to #dcc7a4 at edges)
  washPoly(menuPts, "#ecdec6", 250, 0.03);
  fillPoly(menuPts, "#e2d0b3", 165, 0.05, 0.48, 0.3, 0.03);
  // Subtle yellowed oxidation along the right and top edges
  fillPoly([[130, -242], [178, -242], [178, 196], [140, 200]], "#cfb792", 75, 0.25, 0.5, 0.2, 0.05);

  // --- TRI-FOLD CREASES & CENTER VERTICAL FOLD ---
