function drawBusTicket(cx, cy, ang) {
  push();
  translate(cx, cy);
  rotate(ang);

  // Ticket dimensions: 196 x 336 (-98..98, -168..168)
  // Build authentic serrated roll-teeth along top and bottom, plus two conductor punch notches on right edge
  let ticketPts = [];
  // Top serrated edge (-98 to 98 at y = -168)
  for (let x = -98; x <= 90; x += 14) {
    ticketPts.push([x, -168]);
    ticketPts.push([x + 7, -163]);
  }
  ticketPts.push([98, -168]);

  // Right edge with two semicircular conductor punch bites at y = -42 and y = 28
  ticketPts.push([98, -52]);
  for (let a = -75; a <= 75; a += 30) {
    ticketPts.push([98 - cos(a) * 11, -42 + sin(a) * 10]);
  }
  ticketPts.push([98, -32]);
  ticketPts.push([98, 18]);
  for (let a = -75; a <= 75; a += 30) {
    ticketPts.push([98 - cos(a) * 11, 28 + sin(a) * 10]);
  }
  ticketPts.push([98, 38]);
  ticketPts.push([98, 168]);

  // Bottom serrated edge (98 down to -98 at y = 168)
  for (let x = 98; x >= -90; x -= 14) {
    ticketPts.push([x, 168]);
    ticketPts.push([x - 7, 163]);
  }
  ticketPts.push([-98, 168]);
  ticketPts.push([-98, 42]); // Slight kink where diagonal pocket crease crosses left edge
  ticketPts.push([-96, 36]);
  ticketPts.push([-98, -168]);

  // Cast shadow (tight near top pin, deeper toward dog-eared bottom-left and bottom-right)
  let shadowPts = ticketPts.map(p => {
    let lift = map(p[1], -168, 168, 4, 17);
    if (p[0] < -20 && p[1] > 40) lift += 6; // Extra lift under dog-eared corner
    return [p[0] + lift * 0.85, p[1] + lift];
  });
  washPoly(shadowPts, "#2e1506", 75, 0.04);
  let shadowInner = ticketPts.map(p => {
    let lift = map(p[1], -168, 168, 2.5, 11);
    return [p[0] + lift * 0.85, p[1] + lift];
  });
  fillPoly(shadowInner, "#1a0b02", 130, 0.12, 0.5, 0.25, 0.04);

  // Oatmeal / buff recycled pulp card stock (#e3d3b7)
  washPoly(ticketPts, "#e5d6bc", 252, 0.02);
  fillPoly(ticketPts, "#d9c6a7", 170, 0.05, 0.52, 0.32, 0.02);

  // Diagonal pocket crease from (-98, 38) to (38, 168): lower-left dog-eared triangle is slightly darker
  fillPoly([[-98, 38], [38, 168], [-98, 168]], "#c6b190", 115, 0.08, 0.5, 0.2, 0.02);
  washPoly([[-98, 32], [44, 168], [36, 168], [-98, 40]], "#fffcf5", 175, 0);

  // Recycled wood-pulp flecks & fibers embedded in the ticket stock
  brush.set("paper_fiber", "#9c8362", 0.75);
  for (let i = 0; i < 160; i++) {
    let fx = random(-90, 90);
    let fy = random(-156, 156);
    let fang = random(360);
    safeLine(fx, fy, fx + cos(fang) * random(2, 6), fy + sin(fang) * random(2, 6));
  }
  brush.set("paper_fiber", "#fbf4e6", 0.7);
  for (let i = 0; i < 95; i++) {
    let fx = random(-90, 90);
    let fy = random(-156, 156);
    let fang = random(360);
    safeLine(fx, fy, fx + cos(fang) * random(2, 5), fy + sin(fang) * random(2, 5));
  }

  // Faded vermilion/crimson header band at top (-92..92, -152..-116)
  fillPoly([[-92, -152], [92, -152], [92, -116], [-92, -116]], "#bd3828", 110, 0.06, 0.55, 0.3, 0);
  drawTextString("MUNICIPAL TRANSIT", -74, -144, 5.8, 8.5, 2.8, "rotring", "#f4e6d0", 0.68, 0.12);
  drawTextString("ONE WAY TRANSFER", -66, -129, 4.8, 6.8, 2.5, "rotring", "#f4e6d0", 0.52, 0.12);

  // Bold stamped serial number in crimson ink (#a62116)
  drawTextString("# 48291-B", -62, -102, 9.5, 14.0, 4.2, "rotring", "#a62116", 0.95, 0.28);

  // Left and Right Fare-Stage Grid Columns
  brush.set("rotring", "#5e4f3e", 0.48);
  safeLine(-92, -76, 92, -76);
  safeLine(-92, 144, 92, 144);
  safeLine(-60, -76, -60, 144);
  safeLine(60, -76, 60, 144);
  safeLine(-92, -76, -92, 144);
  safeLine(92, -76, 92, 144);

  for (let s = 0; s < 8; s++) {
    let sy = -76 + s * 27.5;
    brush.set("rotring", "#6e5d4a", 0.42);
    safeLine(-92, sy, -60, sy);
    safeLine(60, sy, 92, sy);
    let numL = "0" + (s + 1);
    let numR = (s + 11).toString();
    drawTextString(numL, -84, sy + 8, 5.2, 7.5, 2.2, "rotring", "#4f4133", 0.48, 0.1);
    if (s !== 1 && s !== 3) {
      drawTextString(numR, 68, sy + 8, 5.2, 7.5, 2.2, "rotring", "#4f4133", 0.48, 0.1);
    }
  }

  // Center column fare rules & faded violet-charcoal rotary validation stamp
  drawTextString("TARIF NORMAL", -46, -64, 4.8, 7.0, 2.2, "rotring", "#4f4133", 0.5, 0.1);
  drawTextString("NON-TRANSF.", -42, -48, 4.5, 6.5, 2.0, "rotring", "#665544", 0.45, 0.1);

  // Fine horizontal rules in center column
  brush.set("rotring", "#8c7963", 0.38);
  for (let ry = -28; ry <= 108; ry += 22) {
    safeLine(-54, ry, 54, ry);
  }

  // Skewed rotary machine stamp across the middle of the ticket
  push();
  translate(-4, 18);
  rotate(-6.5);
  strokePoly([[-52, -26], [52, -26], [52, 26], [-52, 26]], "2B", "#3d333b", 0.65, 0, true);
  drawTextString("ZONE 03", -36, -18, 6.8, 9.5, 3.0, "2B", "#382e36", 0.75, 0.35);
  drawTextString("17:42  19.X", -42, 4, 5.8, 8.5, 2.5, "2B", "#453942", 0.68, 0.35);
  pop();

  drawTextString("KEEP FOR INSP.", -48, 124, 4.2, 6.2, 1.8, "rotring", "#5e4f3e", 0.45, 0.12);

  // --- FULL CONDUCTOR PUNCH HOLE AT (52, -12) REVEALING CORKBOARD UNDERNEATH ---
  let holePts = [];
  for (let a = 0; a < 360; a += 24) {
    holePts.push([52 + cos(a) * 8.5, -12 + sin(a) * 8.5]);
  }
  // Corkboard visible inside punch hole + cast shadow of card edge inside the hole
  washPoly(holePts, "#915826", 250, 0.25);
  fillPoly(holePts, "#241004", 165, 0.05, 0.5, 0.3, 0.25);
  // Bright lower-right card thickness rim catching light inside the punch hole
  brush.set("rotring", "#fffdf8", 0.85);
  brush.arc(52, -12, 8.5, -25, 115);
  brush.set("rotring", "#1a0b03", 0.9);
  brush.arc(52, -12, 8.5, 125, 330);

  // Scuffed white paper fibers along the diagonal pocket fold (-98, 38) -> (38, 168)
  brush.set("paper_fiber", "#fffefb", 0.95);
  for (let t = 0; t <= 1; t += 0.025) {
    let fx = lerp(-98, 38, t);
    let fy = lerp(38, 168, t);
    safeLine(fx - 2, fy - 1, fx + 3, fy + 1);
  }
  brush.set("2H", "#857055", 0.65);
  safeLine(-97, 40, 36, 168);

  // Outer card thickness bevel
  strokePoly(ticketPts, "2H", "#8c775c", 0.65, 0.02, true);
  brush.set("rotring", "#fffefb", 0.8);
  safeLine(-98, -166, -98, 36);

  pop();
  brush.noStroke();
}

