// 6. ARTIFACT 4: PRESSED RECEIPT (Lower Right)
// ============================================================================

function drawPressedReceipt(cx, cy, ang) {
  push();
  translate(cx, cy);
  rotate(ang);

  // Receipt dimensions: 248 x 368 (-124..124, -184..184)
  // Wavy side edges from pressed crumples, serrated cutter teeth at top and bottom
  let recPts = [];
  for (let x = -124; x <= 116; x += 8) {
    recPts.push([x, -184]);
    recPts.push([x + 4, -180]);
  }
  recPts.push([124, -184]);
  // Right edge with crinkle indentations
  const rightWave = [
    [122, -125], [126, -68], [120, -12], [125, 44], [119, 98], [124, 148], [122, 184]
  ];
  recPts.push(...rightWave);
  // Bottom serrated cutter edge
  for (let x = 122; x >= -116; x -= 8) {
    recPts.push([x, 184]);
    recPts.push([x - 4, 180]);
  }
  recPts.push([-124, 184]);
  // Left edge with crinkle indentations
  const leftWave = [
    [-121, 135], [-126, 78], [-119, 22], [-125, -36], [-120, -95], [-125, -142], [-124, -184]
  ];
  recPts.push(...leftWave);

  // Cast shadow (varies along the wavy crumpled perimeter)
  let shadowPts = recPts.map(p => {
    let lift = map(p[1], -184, 184, 4, 18) + 3.5 * sin(p[1] * 2.2);
    return [p[0] + lift * 0.82, p[1] + lift];
  });
  washPoly(shadowPts, "#2e1506", 68, 0.04);
  let shadowCore = recPts.map(p => {
    let lift = map(p[1], -184, 184, 2.5, 11) + 2.0 * sin(p[1] * 2.2);
    return [p[0] + lift * 0.82, p[1] + lift];
  });
  fillPoly(shadowCore, "#1b0b03", 120, 0.14, 0.5, 0.25, 0.04);

  // Base thin thermal paper (#f4ede0)
  washPoly(recPts, "#f3ebdc", 248, 0.02);
  fillPoly(recPts, "#e9decb", 155, 0.05, 0.42, 0.25, 0.02);

  // --- TROMPE-L'ŒIL CRUMPLED-AND-PRESSED VORONOÏ / TRIANGULATED FACETS ---
  // Define a 4x6 grid of interior & edge vertices to shade every pressed paper facet
  const colsX = [-123, -46, 38, 123];
  const rowsY = [-182, -118, -48, 18, 84, 142, 182];
  let mesh = [];
  for (let r = 0; r < rowsY.length; r++) {
    let row = [];
    for (let c = 0; c < colsX.length; c++) {
      let jx = (c > 0 && c < 3 && r > 0 && r < 6) ? (noise(c * 3, r * 3) - 0.5) * 34 : 0;
      let jy = (r > 0 && r < 6) ? (noise(c * 5 + 10, r * 5) - 0.5) * 26 : 0;
      row.push([colsX[c] + jx, rowsY[r] + jy]);
    }
    mesh.push(row);
  }

  // Render subtle light/shadow washes on each triangular facet according to slope
  const facetTones = ["#d1c2aa", "#dfd2bc", "#f7f1e4", "#fffdf9", "#c8b79c"];
  for (let r = 0; r < mesh.length - 1; r++) {
    for (let c = 0; c < mesh[0].length - 1; c++) {
      let p00 = mesh[r][c];
      let p10 = mesh[r][c + 1];
      let p11 = mesh[r + 1][c + 1];
      let p01 = mesh[r + 1][c];
      let idx1 = (r * 3 + c * 2) % facetTones.length;
      let idx2 = (r * 2 + c * 3 + 2) % facetTones.length;
      washPoly([p00, p10, p11], facetTones[idx1], 85, 0);
      washPoly([p00, p11, p01], facetTones[idx2], 85, 0);
    }
  }

  // --- THERMAL RECEIPT TYPOGRAPHY & ITEMIZED LIST ---
  drawTextString("M. VANCE & SONS", -78, -162, 6.8, 9.8, 3.0, "rotring", "#332b24", 0.68, 0.15);
  drawTextString("ARCHIVAL HARDWARE", -76, -146, 5.2, 7.2, 2.4, "rotring", "#4a3f35", 0.52, 0.15);
  drawTextString("22/11/24   18:14", -68, -130, 4.8, 6.8, 2.2, "rotring", "#594c40", 0.48, 0.15);

  // Dashed thermal separator rules
  function drawDashedRule(ry) {
    brush.set("rotring", "#594c40", 0.5);
    for (let dx = -106; dx <= 100; dx += 9) {
      safeLine(dx, ry, dx + 5, ry);
    }
  }
  drawDashedRule(-114);

  const receiptItems = [
    ["1X RAW SIENNA 04", "06.40"],
    ["2X BURNT UMBER", "12.80"],
    ["1X BRASS PINS", "03.50"],
    ["1X LINEN TAPE", "08.20"],
    ["3X PULP CARD A5", "04.50"],
    ["1X INDIA INK", "07.90"],
    ["1X BONE FOLDER", "11.20"]
  ];

  let ry = -100;
  for (let i = 0; i < receiptItems.length; i++) {
    let [item, val] = receiptItems[i];
    // Slight thermal fade in the middle where crease rubbed the coating
    let col = (i === 2 || i === 3) ? "#66584b" : "#382f27";
    let w = (i === 2 || i === 3) ? 0.44 : 0.54;
    drawTextString(item, -104, ry, 4.5, 6.8, 1.8, "rotring", col, w, 0.15);
    drawTextString(val, 68, ry, 4.6, 6.8, 1.8, "rotring", col, w, 0.15);
    ry += 19.5;
  }

  drawDashedRule(42);
  drawTextString("SUBTOTAL", -104, 52, 4.8, 7.0, 2.0, "rotring", "#382f27", 0.52, 0.12);
  drawTextString("54.50", 66, 52, 4.8, 7.0, 1.8, "rotring", "#382f27", 0.52, 0.12);
  drawTextString("TOTAL", -104, 72, 6.8, 9.8, 2.8, "rotring", "#241d17", 0.85, 0.12);
  drawTextString("54.50", 56, 72, 6.8, 9.8, 2.4, "rotring", "#241d17", 0.85, 0.12);
  drawDashedRule(92);

  // Crimson "PAID" rubber stamp box rotated at (-28, 66)
  push();
  translate(-22, 68);
  rotate(-9);
  strokePoly([[-36, -13], [36, -13], [36, 13], [-36, 13]], "rotring", "#b5261b", 0.78, 0, true);
  drawTextString("PAID", -24, -8, 8.2, 11.0, 3.8, "rotring", "#b5261b", 0.85, 0.3);
  pop();

  // --- HIGH-DENSITY VERTICAL BARCODE AT BOTTOM (-94..94, 104..148) ---
  let bx = -92;
  let barIdx = 0;
  while (bx < 92) {
    let bw = (barIdx % 5 === 0) ? 0.95 : (barIdx % 3 === 0 ? 0.65 : 0.35);
    let step = (barIdx % 4 === 0) ? 4.2 : (barIdx % 2 === 0 ? 2.6 : 3.2);
    brush.set("rotring", "#2c251f", bw);
    // Slight deflection across the lower crease at y ~ 126
    safeLine(bx, 104, bx + 0.4, 126);
    safeLine(bx + 0.4, 126, bx, 146);
    bx += step;
    barIdx++;
  }
  drawTextString("4 018294 772109", -68, 153, 4.4, 6.5, 2.2, "rotring", "#382f27", 0.48, 0.12);

  // --- RAZOR-SHARP PRESSED CREASE RIDGES & VALLEYS OVER THE RECEIPT ---
  for (let r = 0; r < mesh.length - 1; r++) {
    for (let c = 0; c < mesh[0].length - 1; c++) {
      let p00 = mesh[r][c];
      let p10 = mesh[r][c + 1];
      let p11 = mesh[r + 1][c + 1];
      let p01 = mesh[r + 1][c];
      // Highlight along pressed ridges
      brush.set("paper_fiber", "#fffefb", 0.9);
      if (r > 0) safeLine(p00[0], p00[1] - 0.8, p10[0], p10[1] - 0.8);
      safeLine(p00[0] - 0.7, p00[1], p11[0] - 0.7, p11[1]);
      // Paired hairline shadow along each ridge
      brush.set("2H", "#99876e", 0.52);
      if (r > 0) safeLine(p00[0], p00[1] + 0.8, p10[0], p10[1] + 0.8);
      safeLine(p00[0] + 0.7, p00[1], p11[0] + 0.7, p11[1]);
    }
  }

  // Two tiny staple holes at upper-left corner (-96, -162)
  brush.set("2H", "#8c7a62", 0.55);
  safeLine(-102, -160, -90, -165);
  brush.set("rotring", "#1a0c04", 1.05);
  safeLine(-103, -159, -101, -161);
  safeLine(-91, -164, -89, -166);
  brush.set("paper_fiber", "#fffefb", 0.85);
