// Smooth minimum for hyperbolic Chladni webbing at nodal intersections
function smin(a, b, k) {
  let h = Math.max(k - Math.abs(a - b), 0.0) / k;
  return Math.min(a, b) - h * h * k * 0.25;
}

// Exact Euclidean pixel distance to M closed acoustic petals centered at rc with radial half-span hr
function petalDist(rw, tw, rc, hr, M, phase, widthFactor) {
  let u = (rw - rc) / hr;
  if (Math.abs(u) > 1.65) return Math.abs(rw - rc) - hr * 0.45;
  let ang = M * (tw + phase);
  let v = (0.5 * (1.0 - Math.cos(ang))) / widthFactor;
  let F = u * u + v - 1.0;
  let dFdr = (2.0 * u) / hr;
  let dFdth = (M * Math.sin(ang)) / (2.0 * rw * widthFactor);
  let grad = Math.hypot(dFdr, dFdth, 0.015);
  return Math.abs(F) / grad;
}

// Maps ideal polar nodal coordinates (r, theta) to organically warped physical coordinates (x, y)
function warpPoint(r, theta) {
  let x0 = r * Math.cos(theta);
  let y0 = r * Math.sin(theta);
  let n1 = noise(x0 * 0.0035 + 100, y0 * 0.0035 + 100) - 0.5;
  let n2 = noise(x0 * 0.0035 + 300, y0 * 0.0035 + 300) - 0.5;
  let rw = r - n1 * 4.5;
  let tw = theta - n2 * 0.025;
  return [rw * Math.cos(tw), rw * Math.sin(tw)];
}

// Exact composite distance field to the acoustic nodal network (rings, petals, crossing lines)
function getNodalDist(x, y) {
  let r = Math.hypot(x, y);
  if (r > 442) return 999;

  let n1 = noise(x * 0.0035 + 100, y * 0.0035 + 100) - 0.5;
  let n2 = noise(x * 0.0035 + 300, y * 0.0035 + 300) - 0.5;
  let rw = Math.max(0.5, r + n1 * 4.5);
  let tw = Math.atan2(y, x) + n2 * 0.025;

  // 1. Concentric Nodal Rings
  let dRing0 = Math.abs(rw - (34.0 + 1.5 * Math.cos(6.0 * tw)));
  let dRing1 = Math.abs(rw - (130.0 + 0.5 * Math.cos(12.0 * tw))) * 0.76; // Dust cap seam
  let dRing2 = Math.abs(rw - (166.0 - 3.0 * Math.cos(12.0 * tw)));
  let dRing3 = Math.abs(rw - (238.0 + 3.5 * Math.cos(12.0 * tw)));
  let dRing4 = Math.abs(rw - (326.0 - 4.0 * Math.cos(12.0 * tw)));
  let dRing5 = Math.abs(rw - (398.0 + 3.0 * Math.cos(24.0 * tw)));
  let dRing6 = Math.abs(rw - (427.5 + 0.6 * Math.cos(16.0 * tw))) * 0.72; // Surround trough

  let dRings = Math.min(dRing0, dRing1, dRing2, dRing3, dRing4, dRing5, dRing6);

  // 2. Closed Geometric Petals & Inner Eye-Loops
  let dPetalCap = petalDist(rw, tw, 80.0, 36.0, 6, 0.0, 0.52);
  let dPetalInner = petalDist(rw, tw, 202.0, 32.0, 12, 0.0, 0.58);
  let dPetalInnerEye = petalDist(rw, tw, 202.0, 11.5, 12, 0.0, 0.22);
  let dPetalOuter = petalDist(rw, tw, 362.0, 32.0, 12, Math.PI / 12.0, 0.62);
  let dPetalOuterEye = petalDist(rw, tw, 362.0, 13.0, 12, Math.PI / 12.0, 0.25);
  let dPetalRim = petalDist(rw, tw, 413.0, 14.0, 24, 0.0, 0.55);

  let dPetals = Math.min(
    dPetalCap,
    dPetalInner,
    dPetalInnerEye,
    dPetalOuter,
    dPetalOuterEye,
    dPetalRim
  );

  // 3. Radial & Spiral Crossing Nodal Lines
  let dRadA = 999;
  if (rw >= 14.0 && rw <= 428.5) {
    dRadA = (rw * Math.abs(Math.sin(6.0 * tw + 0.06 * Math.sin(rw * 0.03)))) / 6.0;
  }
  let dRadB = 999;
  if (rw >= 166.0 && rw <= 428.5) {
    dRadB = (rw * Math.abs(Math.cos(6.0 * tw - 0.05 * Math.cos(rw * 0.03)))) / 6.0;
  }

  // Counter-rotating spiral crossing lattice in mid-cone (238 <= r <= 326)
  let dCrossMid = 999;
  if (rw >= 236.0 && rw <= 328.0) {
    let s = (rw - 238.0) / 88.0;
    let gCross = Math.hypot(Math.PI / 88.0, 6.0 / rw);
    let cA = Math.abs(Math.sin(6.0 * tw + Math.PI * s)) / gCross;
    let cB = Math.abs(Math.sin(6.0 * tw - Math.PI * s)) / gCross;
    dCrossMid = smin(cA, cB, 6.0);
  }

  // Inner cone V-lattice struts (130 <= r <= 166)
  let dCrossInner = 999;
  if (rw >= 129.0 && rw <= 167.0) {
    let s1 = (rw - 130.0) / 36.0;
    let gCross1 = Math.hypot(Math.PI / 36.0, 12.0 / rw);
    let c1 = Math.abs(Math.sin(12.0 * tw + Math.PI * s1)) / gCross1;
    let c2 = Math.abs(Math.sin(12.0 * tw - Math.PI * s1)) / gCross1;
    dCrossInner = smin(c1, c2, 5.0);
  }

  let dCross = Math.min(dRadA, dRadB, dCrossMid, dCrossInner);

  // Combine rings, petals, and crossing lines with hyperbolic smooth-min fillets
  let d = smin(dRings, dPetals, 6.5);
  d = smin(d, dCross, 6.5);
  return d;
}

// Helper to convert RGB array to hex string
function rgbToHex(r, g, b) {
  let cr = Math.max(0, Math.min(255, Math.round(r)));
  let cg = Math.max(0, Math.min(255, Math.round(g)));
  let cb = Math.max(0, Math.min(255, Math.round(b)));
  return (
    "#" +
    ((1 << 24) + (cr << 16) + (cg << 8) + cb).toString(16).slice(1)
  );
}

// Builds parametric polyline segments for all nodal curves (used for stipple-base & curve-guided grains)
function buildNodalPolylines() {
  let polylines = [];

  // 1. Concentric rings
  const ringDefs = [
    { r: 34.0, amp: 1.5, m: 6, steps: 90, weight: 0.9 },
    { r: 130.0, amp: 0.5, m: 12, steps: 220, weight: 1.35 },
    { r: 166.0, amp: -3.0, m: 12, steps: 240, weight: 1.0 },
    { r: 238.0, amp: 3.5, m: 12, steps: 300, weight: 1.1 },
    { r: 326.0, amp: -4.0, m: 12, steps: 360, weight: 1.1 },
    { r: 398.0, amp: 3.0, m: 24, steps: 420, weight: 1.0 },
    { r: 427.5, amp: 0.6, m: 16, steps: 460, weight: 1.35 }
  ];

  for (let rd of ringDefs) {
    let segs = 12;
    let ptsPerSeg = Math.floor(rd.steps / segs);
    for (let s = 0; s < segs; s++) {
      let pts = [];
      for (let i = 0; i <= ptsPerSeg; i++) {
        let idx = s * ptsPerSeg + i;
        let th = (idx / rd.steps) * TWO_PI;
        let rr = rd.r + rd.amp * Math.cos(rd.m * th);
        pts.push(warpPoint(rr, th));
      }
      polylines.push({ pts, weight: rd.weight });
    }
  }

  // 2. Closed Petals using exact analytical parameterization
  const petalDefs = [
    { rc: 80.0, hr: 36.0, M: 6, phase: 0.0, wf: 0.52, steps: 44, weight: 1.0 },
    { rc: 202.0, hr: 32.0, M: 12, phase: 0.0, wf: 0.58, steps: 44, weight: 1.05 },
    { rc: 202.0, hr: 11.5, M: 12, phase: 0.0, wf: 0.22, steps: 24, weight: 0.75 },
    { rc: 362.0, hr: 32.0, M: 12, phase: Math.PI / 12.0, wf: 0.62, steps: 50, weight: 1.1 },
    { rc: 362.0, hr: 13.0, M: 12, phase: Math.PI / 12.0, wf: 0.25, steps: 26, weight: 0.8 },
    { rc: 413.0, hr: 14.0, M: 24, phase: 0.0, wf: 0.55, steps: 26, weight: 0.85 }
  ];

  for (let pd of petalDefs) {
    let sqrtWf = Math.sqrt(pd.wf);
    for (let k = 0; k < pd.M; k++) {
      let thCenter = (TWO_PI * k) / pd.M - pd.phase;
      let pts = [];
      for (let i = 0; i <= pd.steps; i++) {
        let phi = (i / pd.steps) * TWO_PI;
        let rr = pd.rc + pd.hr * Math.cos(phi);
        let dth = (2.0 / pd.M) * Math.asin(Math.max(-0.999, Math.min(0.999, sqrtWf * Math.sin(phi))));
        pts.push(warpPoint(rr, thCenter + dth));
      }
      polylines.push({ pts, weight: pd.weight });
    }
  }

  // 3. Radial Crossing Lines (12 primary rays + 12 outer secondary rays)
  for (let k = 0; k < 12; k++) {
    let baseTh = (k * Math.PI) / 6.0;
    let ptsA = [];
    for (let r = 15; r <= 427; r += 8) {
      let th = baseTh - (0.06 * Math.sin(r * 0.03)) / 6.0;
      ptsA.push(warpPoint(r, th));
    }
    polylines.push({ pts: ptsA, weight: 0.95 });

    let baseThB = ((k + 0.5) * Math.PI) / 6.0;
    let ptsB = [];
    for (let r = 166; r <= 427; r += 8) {
      let th = baseThB + (0.05 * Math.cos(r * 0.03)) / 6.0;
      ptsB.push(warpPoint(r, th));
    }
    polylines.push({ pts: ptsB, weight: 0.85 });
  }

  // 4. Mid-Cone Spiral Crossing Lattice (238 <= r <= 326) & Inner Cone V-Struts (130 <= r <= 166)
  for (let k = 0; k < 12; k++) {
    let baseTh = (k * Math.PI) / 6.0;
    for (let dir of [-1, 1]) {
      let ptsMid = [];
      for (let r = 238; r <= 326; r += 6) {
        let s = (r - 238.0) / 88.0;
        let th = baseTh + (dir * Math.PI * s) / 6.0;
        ptsMid.push(warpPoint(r, th));
      }
      polylines.push({ pts: ptsMid, weight: 1.0 });
    }
  }

  for (let k = 0; k < 24; k++) {
    let baseTh = (k * Math.PI) / 12.0;
    for (let dir of [-1, 1]) {
      let ptsIn = [];
      for (let r = 130; r <= 166; r += 5) {
        let s = (r - 130.0) / 36.0;
        let th = baseTh + (dir * Math.PI * s) / 12.0;
        ptsIn.push(warpPoint(r, th));
      }
      polylines.push({ pts: ptsIn, weight: 0.8 });
    }
  }

  return polylines;
}

function draw() {
  translate(-width / 2, -height / 2);

  // =========================================================================
  // 1. DEEP MATTE BLACK GROUND & BASE SPEAKER SILHOUETTE
  // =========================================================================
  background("#050608");

  brush.noStroke();
  // Outer cast metal basket flange base wash
  brush.wash("#121418", 230);
  brush.circle(CX, CY, 566, 0.02);

  // Foam surround dark base
  brush.wash("#15181d", 240);
  brush.circle(CX, CY, 502, 0.02);

  // Deep matte charcoal cone basin
  brush.wash("#08090c", 250);
  brush.circle(CX, CY, 430, 0.015);

  // Central dust cap base
  brush.wash("#090b0e", 250);
  brush.circle(CX, CY, 130, 0.015);
  brush.noWash();

  // =========================================================================
  // 2. DENSE CHARCOAL MASS & SOFT RUBBERY SHEEN ON THE CONE (130 < r <= 428)
  // =========================================================================
  // A concave conical funnel lit from top-left (-135 deg) catches broad diffuse light on its
  // bottom-right inner slope (+45 deg) and an anisotropic bowtie specular sheen along both axes.
  const coneRings = 34;
  const coneSegs = 24;

  for (let i = 0; i < coneRings; i++) {
    let t = i / (coneRings - 1);
    let r = 133 + t * 293;
    let radialFade = Math.sin(t * Math.PI); // Softens near inner seam and outer rim

    for (let s = 0; s < coneSegs; s++) {
      let a0 = (s / coneSegs) * TWO_PI;
      let a1 = ((s + 1.05) / coneSegs) * TWO_PI;
      let aMid = 0.5 * (a0 + a1);

      // Inward-sloping cone normal dot light: brightest around LIGHT_ANGLE + PI (+45 deg)
      let alignOpposite = Math.cos(aMid - (LIGHT_ANGLE + Math.PI));
      let alignAxis = Math.cos(2.0 * (aMid - LIGHT_ANGLE)); // Anisotropic bowtie sheen

      let diffuse = Math.max(0, alignOpposite) * 0.55;
      let anisoMain = Math.pow(Math.max(0, alignOpposite), 3.0) * 0.65;
      let anisoSecond = Math.pow(Math.max(0, -alignOpposite), 4.0) * 0.32;
      let bowtie = Math.pow(Math.max(0, alignAxis), 3.0) * 0.25;

      // Rim shadow cast by the raised foam surround into the top-left edge of the cone
      let rimShadow = 0;
      if (r > 392 && alignOpposite < 0) {
        rimShadow = ((r - 392) / 36.0) * (-alignOpposite) * 0.55;
      }

      let sheen = Math.max(
        0,
        (diffuse + anisoMain + anisoSecond + bowtie) * (0.45 + 0.55 * radialFade) - rimShadow
      );

      let baseVal = 9 + sheen * 36;
      let col = rgbToHex(baseVal * 0.92, baseVal * 0.96, baseVal * 1.1);

      brush.set("rubbery_charcoal", col, 1.15);
      brush.arc(CX, CY, r, a0, a1);
    }
  }

  // Fine concentric pressed-cone ribs & radial charcoal blending strokes
  for (let r = 136; r <= 424; r += 6.5) {
    let t = (r - 130) / 298.0;
    for (let s = 0; s < 16; s++) {
      let a0 = (s / 16) * TWO_PI + random(-0.03, 0.03);
      let a1 = a0 + TWO_PI / 16 - 0.02;
      let aMid = 0.5 * (a0 + a1);
      let alignOpp = Math.cos(aMid - (LIGHT_ANGLE + Math.PI));
      let spec =
        Math.pow(Math.max(0, alignOpp), 2.5) * 0.7 +
        Math.pow(Math.max(0, -alignOpp), 3.5) * 0.35;

      if (spec > 0.14) {
        let v = 16 + spec * 38 * Math.sin(t * Math.PI);
        brush.set("2B", rgbToHex(v * 0.9, v * 0.96, v * 1.12), 0.38);
      } else {
        brush.set("charcoal", "#06070a", 0.45);
      }
      brush.arc(CX, CY, r, a0, a1);
    }
  }

  // Radial charcoal texture strokes into the cone funnel
  for (let i = 0; i < 180; i++) {
    let ang = (i / 180) * TWO_PI + random(-0.015, 0.015);
    let r1 = random(134, 260);
    let r2 = Math.min(425, r1 + random(80, 170));
    let alignOpp = Math.cos(ang - (LIGHT_ANGLE + Math.PI));
    let v = alignOpp > 0 ? 14 + alignOpp * 20 : 7 + Math.max(0, -alignOpp) * 8;
    brush.set("charcoal", rgbToHex(v * 0.92, v * 0.96, v * 1.08), random(0.3, 0.55));
    brush.line(
      CX + r1 * Math.cos(ang),
      CY + r1 * Math.sin(ang),
      CX + r2 * Math.cos(ang),
      CY + r2 * Math.sin(ang)
    );
  }

  // =========================================================================
  // 3. CENTRAL DOMED DUST CAP (0 <= r <= 130) & POLYMER GLUE SEAM
  // =========================================================================
  // Convex spherical dome: brightest on top-left (around r=55, angle = LIGHT_ANGLE), dark crescent on bottom-right
  const capRings = 18;
  const capSegs = 20;
  for (let i = 1; i <= capRings; i++) {
    let r = (i / capRings) * 128;
    let nr = r / 205.0; // Spherical dome normal radial component
    let nz = Math.sqrt(Math.max(0, 1.0 - nr * nr));

    for (let s = 0; s < capSegs; s++) {
      let a0 = (s / capSegs) * TWO_PI;
      let a1 = ((s + 1.08) / capSegs) * TWO_PI;
      let aMid = 0.5 * (a0 + a1);

      let nx = nr * Math.cos(aMid);
      let ny = nr * Math.sin(aMid);
      let dotL = Math.max(0, nx * LX + ny * LY + nz * LZ);
      // Specular halfway vector H = normalize(L + (0,0,1))
      let hx = -0.34,
        hy = -0.34,
        hz = 0.88;
      let spec = Math.pow(Math.max(0, nx * hx + ny * hy + nz * hz), 9.0);

      let v = 7 + dotL * 24 + spec * 34;
      let col = rgbToHex(v * 0.92, v * 0.96, v * 1.1);
      brush.set("rubbery_charcoal", col, 0.95);
      brush.arc(CX, CY, r, a0, a1);
    }
  }

  // Fine woven/molded micro-texture on the central dust cap dome
  for (let i = 0; i < 160; i++) {
    let rr = Math.sqrt(random()) * 124;
    let th = random(TWO_PI);
    let x = CX + rr * Math.cos(th);
    let y = CY + rr * Math.sin(th);
    let distHighlight = Math.hypot(x - (CX - 46), y - (CY - 46));
    let v = Math.max(8, 46 - distHighlight * 0.28);
    brush.set("2H", rgbToHex(v * 0.9, v * 0.96, v * 1.1), 0.28);
    let tang = th + HALF_PI + random(-0.2, 0.2);
    brush.line(
      x - 4 * Math.cos(tang),
      y - 4 * Math.sin(tang),
      x + 4 * Math.cos(tang),
      y + 4 * Math.sin(tang)
    );
  }

  // Glossy black polymer glue fillet at r = 130
  brush.set("2B", "#030406", 0.9);
  brush.circle(CX, CY, 130.5, 0.01);
  // Specular glint on the glue bead (top-left inner & bottom-right outer)
  brush.set("2H", "#4d5666", 0.35);
  brush.arc(CX, CY, 129.2, LIGHT_ANGLE - 0.7, LIGHT_ANGLE + 0.7);
  brush.arc(CX, CY, 131.2, LIGHT_ANGLE + Math.PI - 0.6, LIGHT_ANGLE + Math.PI + 0.6);

  // =========================================================================
  // 4. EXACT PENCIL DETAIL ON THE FOAM SURROUND & RIM (428 <= r <= 568)
  // =========================================================================
  // 4A. 3D Torus Roll Shading on the Half-Roll Foam Surround (431 <= r <= 497)
  // Center of half-roll torus at r = 464, half-width = 33
  const rollSteps = 22;
  const rollSegs = 36;
  for (let i = 0; i <= rollSteps; i++) {
    let u = -1.0 + (2.0 * i) / rollSteps; // -1 at inner edge (431), +1 at outer edge (497)
    let r = 464.0 + u * 33.0;
    let nr = Math.sin(u * HALF_PI);
    let nz = Math.cos(u * HALF_PI);

    for (let s = 0; s < rollSegs; s++) {
      let a0 = (s / rollSegs) * TWO_PI;
      let a1 = ((s + 1.04) / rollSegs) * TWO_PI;
      let aMid = 0.5 * (a0 + a1);

      let nx = nr * Math.cos(aMid);
      let ny = nr * Math.sin(aMid);
      let dotL = Math.max(0, nx * LX + ny * LY + nz * LZ);
      let spec = Math.pow(Math.max(0, nx * -0.34 + ny * -0.34 + nz * 0.88), 7.0);

      let v = 8 + dotL * 48 + spec * 46;
      let col = rgbToHex(v * 0.93, v * 0.97, v * 1.08);
      brush.set("HB", col, 0.65);
      brush.arc(CX, CY, r, a0, a1);
    }
  }

  // 4B. Exact Technical Pencil Cross-Contours sculpting the 3D curvature of the foam surround
  const numContours = 540;
  for (let i = 0; i < numContours; i++) {
    let baseAng = (i / numContours) * TWO_PI + random(-0.003, 0.003);
    // Split each cross-contour into outer-roll and inner-roll segments so pencil value tracks 3D normal
    for (let half = 0; half < 2; half++) {
      let uStart = half === 0 ? -0.96 : 0.0;
      let uEnd = half === 0 ? 0.0 : 0.96;
      let uMid = 0.5 * (uStart + uEnd);

      let nr = Math.sin(uMid * HALF_PI);
      let nz = Math.cos(uMid * HALF_PI);
      let nx = nr * Math.cos(baseAng);
      let ny = nr * Math.sin(baseAng);
      let dotL = Math.max(0, nx * LX + ny * LY + nz * LZ);
      let spec = Math.pow(Math.max(0, nx * -0.34 + ny * -0.34 + nz * 0.88), 6.0);

      let v = 10 + dotL * 54 + spec * 52 + random(-5, 5);
      let r1 = 464.0 + uStart * 33.0;
      let r2 = 464.0 + uEnd * 33.0;
      let rMid = 0.5 * (r1 + r2);
      // Slight azimuthal arch to convey the raised 3D convex roll cross-section
      let archOffset = 0.008 * Math.cos(uMid * HALF_PI);

      let p1 = [CX + r1 * Math.cos(baseAng), CY + r1 * Math.sin(baseAng)];
      let p2 = [
        CX + rMid * Math.cos(baseAng + archOffset),
        CY + rMid * Math.sin(baseAng + archOffset)
      ];
      let p3 = [CX + r2 * Math.cos(baseAng), CY + r2 * Math.sin(baseAng)];

      let bName = v > 55 ? "2H" : v > 28 ? "HB" : "2B";
      brush.set(bName, rgbToHex(v * 0.93, v * 0.97, v * 1.08), 0.26);
      brush.spline([p1, p2, p3], 0.4);
    }
  }

  // 4C. Fine cellular foam pores & crisp graphite ridge highlights on the surround
  for (let i = 0; i < 900; i++) {
    let u = random(-0.92, 0.92);
    let r = 464.0 + u * 33.0;
    let ang = random(TWO_PI);
    let nr = Math.sin(u * HALF_PI);
    let nz = Math.cos(u * HALF_PI);
    let dotL = Math.max(0, nr * Math.cos(ang) * LX + nr * Math.sin(ang) * LY + nz * LZ);
    if (dotL > 0.35) {
      let v = 22 + dotL * 68;
      let x = CX + r * Math.cos(ang);
      let y = CY + r * Math.sin(ang);
      brush.set("2H", rgbToHex(v * 0.92, v * 0.96, v * 1.08), 0.22);
      brush.line(x, y, x + 1.4 * Math.sin(ang), y - 1.4 * Math.cos(ang));
    }
  }

  // Inner surround glue lip & crease (428 <= r <= 433)
  brush.set("2B", "#050608", 0.75);
  brush.circle(CX, CY, 430.5, 0.008);
  brush.set("2H", "#4a5362", 0.3);
  brush.arc(CX, CY, 432.0, LIGHT_ANGLE + Math.PI - 0.85, LIGHT_ANGLE + Math.PI + 0.85);

  // 4D. Outer Mounting Gasket & Machined Cast-Aluminum Basket Flange (497 <= r <= 568)
  // Deep shadow step at outer edge of foam roll (r = 497)
  brush.set("2B", "#040507", 0.85);
  brush.circle(CX, CY, 497.5, 0.008);

  // Gasket flat ring (498 <= r <= 522) and outer metal flange (522 <= r <= 566) rendered in fine pencil
  for (let r = 499; r <= 566; r += 2.5) {
    let isGasket = r < 522;
    let isBevel = Math.abs(r - 522) < 2.5 || r > 558;
    for (let s = 0; s < 24; s++) {
      let a0 = (s / 24) * TWO_PI;
      let a1 = ((s + 1.02) / 24) * TWO_PI;
      let aMid = 0.5 * (a0 + a1);
      let lightAlign = Math.cos(aMid - LIGHT_ANGLE);

      let v = isGasket ? 20 + lightAlign * 14 : 26 + lightAlign * 18;
      if (isBevel) v += lightAlign * 22;
      v = Math.max(7, Math.min(95, v));

      brush.set(v > 42 ? "2H" : "HB", rgbToHex(v * 0.94, v * 0.97, v * 1.06), 0.32);
      brush.arc(CX, CY, r, a0, a1);
    }
  }

  // Precision radial graphite hatching on the gasket and outer metal rim
  for (let i = 0; i < 360; i++) {
    let ang = (i / 360) * TWO_PI;
    let lightAlign = Math.cos(ang - LIGHT_ANGLE);
    let v = Math.max(9, 24 + lightAlign * 22);
    brush.set("2H", rgbToHex(v * 0.94, v * 0.97, v * 1.06), 0.22);
    brush.line(
      CX + 498 * Math.cos(ang),
      CY + 498 * Math.sin(ang),
      CX + 521 * Math.cos(ang),
      CY + 521 * Math.sin(ang)
    );
    if (i % 2 === 0) {
      brush.line(
        CX + 523 * Math.cos(ang),
        CY + 523 * Math.sin(ang),
        CX + 565 * Math.cos(ang),
        CY + 565 * Math.sin(ang)
      );
    }
  }

  // 8 Gasket Segment Joint Seams & 8 Recessed Mounting Screw Holes on the Basket Rim
  for (let k = 0; k < 8; k++) {
    let seamAng = (k * Math.PI) / 4.0;
    brush.set("2B", "#050608", 0.55);
    brush.line(
      CX + 497 * Math.cos(seamAng),
      CY + 497 * Math.sin(seamAng),
      CX + 522 * Math.cos(seamAng),
      CY + 522 * Math.sin(seamAng)
    );
    brush.set("2H", "#566070", 0.25);
    brush.line(
      CX + 498 * Math.cos(seamAng + 0.005),
      CY + 498 * Math.sin(seamAng + 0.005),
      CX + 521 * Math.cos(seamAng + 0.005),
      CY + 521 * Math.sin(seamAng + 0.005)
    );

    // Mounting screw hole at r = 544
    let holeAng = seamAng + Math.PI / 8.0;
    let hx = CX + 544 * Math.cos(holeAng);
    let hy = CY + 544 * Math.sin(holeAng);

    brush.noStroke();
    brush.wash("#040507", 245);
    brush.circle(hx, hy, 11, 0.05);
    brush.noWash();

    // Recessed hole rim shadow (top-left) and highlight (bottom-right)
    brush.set("2B", "#020304", 0.65);
    brush.arc(hx, hy, 11.2, LIGHT_ANGLE - 1.2, LIGHT_ANGLE + 1.2);
    brush.set("2H", "#6c7688", 0.35);
    brush.arc(hx, hy, 11.5, LIGHT_ANGLE + Math.PI - 1.1, LIGHT_ANGLE + Math.PI + 1.1);

    // Socket head bolt inside mounting hole
    brush.set("HB", "#2b303a", 0.35);
    brush.circle(hx, hy, 6.5, 0.04);
    brush.set("2H", "#788294", 0.28);
    brush.arc(hx, hy, 6.5, LIGHT_ANGLE - 0.9, LIGHT_ANGLE + 0.9);
  }

  // Crisp inner and outer gasket/flange pencil contour lines
  brush.set("2H", "#586272", 0.32);
  brush.arc(CX, CY, 498.5, LIGHT_ANGLE - 1.1, LIGHT_ANGLE + 1.1);
  brush.arc(CX, CY, 522.0, LIGHT_ANGLE + Math.PI - 1.1, LIGHT_ANGLE + Math.PI + 1.1);
  brush.set("2B", "#040507", 0.8);
  brush.circle(CX, CY, 566.5, 0.008);

  // =========================================================================
  // 5. COARSE SEA SALT NODAL PATTERNS (HIGH-CONTRAST CRYSTALLINE STIPPLE)
  // =========================================================================
  const polylines = buildNodalPolylines();

  // 5A. Subtle Salt Dust Halo clinging to the rubbery cone along the nodal paths
  brush.set("salt_dust", "#3e4654", 0.85);
  for (let pl of polylines) {
    let pts = pl.pts.map((p) => [CX + p[0], CY + p[1]]);
    if (pts.length >= 2) brush.spline(pts, 0.25);
  }

  // 5B. Base Crystalline Stipple Passes along all nodal curves
  // Pass 1: Tiny Cast Shadows offset (+1.9, +1.9) to bottom-right
  brush.set("salt_stipple", "#020305", 1.05);
  for (let pl of polylines) {
    let pts = pl.pts.map((p) => [CX + p[0] + 1.9, CY + p[1] + 1.9]);
    if (pts.length >= 2) brush.spline(pts, 0.25);
  }

  // Pass 2: Ice-Grey Shaded Salt Base offset (+0.6, +0.6) on leeward flank of ridges
  brush.set("salt_stipple", "#8e9ba8", 0.95);
  for (let pl of polylines) {
    let pts = pl.pts.map((p) => [CX + p[0] + 0.6, CY + p[1] + 0.6]);
    if (pts.length >= 2) brush.spline(pts, 0.25);
  }

  // Pass 3: Bright Ice-White Crystalline Ridge Core
  brush.set("salt_stipple", "#d8e2ec", 0.9);
  for (let pl of polylines) {
    let pts = pl.pts.map((p) => [CX + p[0], CY + p[1]]);
    if (pts.length >= 2) brush.spline(pts, 0.25);
  }

  // Pass 4: Stark White Specular Crest offset (-0.5, -0.5) toward top-left light
  brush.set("salt_stipple", "#ffffff", 0.78);
  for (let pl of polylines) {
    let pts = pl.pts.map((p) => [CX + p[0] - 0.5, CY + p[1] - 0.5]);
    if (pts.length >= 2) brush.spline(pts, 0.25);
  }

  // =========================================================================
  // 5C. INDIVIDUAL COARSE SEA SALT GRAINS (WITH TINY CAST SHADOWS & FACETS)
  // =========================================================================
  // Generate discrete coarse grains: crowded thick on nodal lines & crossings, scattered thin elsewhere
  let grains = [];

  // Part 1: Curve-guided coarse grains (crowded thick along rings, petals, and crossing lines)
  for (let pl of polylines) {
    let pts = pl.pts;
    for (let i = 0; i < pts.length - 1; i++) {
      let x0 = pts[i][0],
        y0 = pts[i][1];
      let x1 = pts[i + 1][0],
        y1 = pts[i + 1][1];
      let segLen = Math.hypot(x1 - x0, y1 - y0);
      let nx = -(y1 - y0) / (segLen || 1);
      let ny = (x1 - x0) / (segLen || 1);

      let densityMod = 0.55 + 0.9 * noise(x0 * 0.012 + 500, y0 * 0.012 + 500);
      let count = Math.max(1, Math.round((segLen / 3.8) * pl.weight * densityMod));

      for (let c = 0; c < count; c++) {
        let t = random();
        let spread = (random() - 0.5 + (random() - 0.5)) * 2.8 * pl.weight;
        let gx = x0 + (x1 - x0) * t + nx * spread;
        let gy = y0 + (y1 - y0) * t + ny * spread;

        // Signed offset relative to top-left light determines whether grain is on lit or shaded side of ridge
        let signedLightSide = -(nx * spread * 0.707 + ny * spread * 0.707);
        let sz = random(0.8, 1.85) * (Math.abs(spread) < 1.2 ? 1.15 : 0.9);
        grains.push({
          x: gx,
          y: gy,
          sz: sz,
          ang: random(TWO_PI),
          lit: signedLightSide + random(-0.4, 0.5),
          isNode: true
        });
      }
    }
  }

  // Part 2: 2D Field Sampling for Chladni Intersection Webs, Bouncing Fringe, & Thin Antinode Scatter
  const fieldSamples = 16000;
  for (let i = 0; i < fieldSamples; i++) {
    // Stratified polar sampling across cone and inner slope of foam surround (r <= 442)
    let r = Math.sqrt(random()) * 442.0;
    let th = random(TWO_PI);
    let gx = r * Math.cos(th);
    let gy = r * Math.sin(th);

    let d = getNodalDist(gx, gy);
    let localNoise = noise(gx * 0.01 + 700, gy * 0.01 + 700);

    let prob = 0;
    if (d < 3.2) {
      // Nodal ridges and saddle/crossing webs
      prob = 0.42 * (0.6 + 0.8 * localNoise);
    } else if (d < 13.0) {
      // Bouncing salt fringe bordering nodal lines
      prob = 0.14 * Math.exp(-(d - 3.2) * 0.34) * (0.5 + localNoise);
    } else if (r <= 428.0) {
      // Thin scatter of jumping salt grains across dark antinode regions
      prob = 0.048 * (0.4 + 0.9 * localNoise);
    } else {
      // Very sparse stray grains kicked onto the inner lip of the foam surround
      prob = 0.012;
    }

    if (random() < prob) {
      // Compute finite-difference gradient of nodal distance to shade the 3D ridge slope
      let dx = getNodalDist(gx + 1.2, gy) - getNodalDist(gx - 1.2, gy);
      let dy = getNodalDist(gx, gy + 1.2) - getNodalDist(gx, gy - 1.2);
      let ridgeLit = -(dx * 0.707 + dy * 0.707) * 0.45 + random(-0.3, 0.4);
      let sz = d < 3.5 ? random(0.9, 2.0) : random(0.75, 1.65);

      grains.push({
        x: gx,
        y: gy,
        sz: sz,
        ang: random(TWO_PI),
        lit: ridgeLit,
        isNode: d < 4.0
      });
    }
  }

  // Batch 1: Crisp Tiny Cast Shadows for every single salt grain
  brush.set("crystal_shadow", "#020305", 0.95);
  for (let g of grains) {
    let sx = CX + g.x + 1.85 * g.sz;
    let sy = CY + g.y + 1.85 * g.sz;
    let len = 1.3 * g.sz;
    brush.line(
      sx,
      sy,
      sx + len * Math.cos(g.ang),
      sy + len * Math.sin(g.ang)
    );
  }

  // Batch 2: Darker Ice-Grey Salt Grains (leeward ridge slopes & subtle midtone crystals)
  brush.set("crystal_grain", "#8492a2", 0.88);
  for (let g of grains) {
    if (g.lit < -0.15) {
      let x = CX + g.x;
      let y = CY + g.y;
      let len = 1.35 * g.sz;
      brush.line(x, y, x + len * Math.cos(g.ang), y + len * Math.sin(g.ang));
    }
  }

  // Batch 3: Cool Ice-Grey / Silver-White Salt Grains (mid-ridge & antinode scatter)
  brush.set("crystal_grain", "#b8c5d4", 0.92);
  for (let g of grains) {
    if (g.lit >= -0.15 && g.lit < 0.22) {
      let x = CX + g.x;
      let y = CY + g.y;
      let len = 1.4 * g.sz;
      brush.line(x, y, x + len * Math.cos(g.ang), y + len * Math.sin(g.ang));
    }
  }

  // Batch 4: Luminous Ice-White Salt Grains (upper nodal slopes & larger scattered crystals)
  brush.set("crystal_grain", "#e4edf6", 0.96);
  for (let g of grains) {
    if (g.lit >= 0.22) {
      let x = CX + g.x;
      let y = CY + g.y;
      let len = 1.45 * g.sz;
      brush.line(x, y, x + len * Math.cos(g.ang), y + len * Math.sin(g.ang));
    }
  }

  // Batch 5: Stark Pure-White Specular Crystalline Facets on the top-left lit edge of coarse grains
  brush.set("crystal_grain", "#ffffff", 0.82);
  for (let g of grains) {
    if (g.lit > 0.05 || g.sz > 1.35) {
      let x = CX + g.x - 0.45 * g.sz;
      let y = CY + g.y - 0.45 * g.sz;
      let len = 1.1 * g.sz;
      brush.line(
        x,
        y,
        x + len * Math.cos(g.ang + 0.5),
        y + len * Math.sin(g.ang + 0.5)
      );
    }
  }

  noLoop();
}
